BEGIN;

INSERT INTO questions (
  id, lang, question, question_explained, "hasImg", correct_answer,
  answer_1, answer_2, answer_3, answer_4, subject, categories, audio, ai_tutor, img
) VALUES
(3, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს შეუძლია გააგრძელოს მოძრაობა ისრის მიმართულებით, შუქნიშნის ამ სიგნალზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-2 პუნქტის „ა“ და „ე“ ქვეპუნქტების თანახმად, შუქნიშნის ფერად მაშუქ სიგნალებს აქვთ შემდეგი მნიშვნელობა: ა) წითელი მაშუქი სიგნალი ან წითელი მოციმციმე მაშუქი სიგნალი კრძალავს მოძრაობას; ე) მწვანე მაშუქი სიგნალი რთავს მოძრაობის ნებას.', 1, '1', 'მსუბუქი ავტომობილის მძღოლს', 'მოტოციკლის მძღოლს', NULL, NULL, 10, '{0,2}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე: შუქნიშნის მწვანე სიგნალი (განსაკუთრებით ისრის ფორმის) არის „მწვანე შუქი“ შენი მანევრისთვის. თუ შენი ზოლი ამ სიგნალს ექვემდებარება, თამამად გააგრძელე გზა. მსუბუქი ავტომობილი ამ შემთხვევაში სწორად მოქმედებს!', 'ticket_media/new/ticketIMG-3.jpg'),
(3, 'ru', 'Водителю какого транспортного средства разрешено продолжить движение в направлении стрелки при данном сигнале светофора?', 'В соответствии со статьей 29 Закона Грузии «О дорожном движении», зеленый сигнал светофора разрешает движение. Если стрелка указывает направление, движение разрешено только в этом направлении. Таким образом, водитель, движущийся по полосе, соответствующей сигналу светофора, имеет приоритетное право проезда.', 1, '1', 'Водителю легкового автомобиля', 'Водителю мотоцикла', NULL, NULL, 10, '{0,2}'::int[], NULL, 'Привет! Запомни: зеленый сигнал светофора, особенно в форме стрелки, дает тебе полное право на движение. Если твоя полоса регулируется именно этим сигналом, смело продолжай путь. Водитель легкового автомобиля в данном случае поступает верно!', 'ticket_media/new/ticketIMG-3.jpg'),
(3, 'en', 'Which driver is allowed to continue driving in the direction of the arrow at this traffic light signal?', 'According to Article 29 of the Law of Georgia ''On Road Traffic'', the green signal permits movement. A green arrow specifically indicates a permitted direction. Therefore, only the driver whose lane is regulated by this specific green signal is legally permitted to proceed.', 1, '1', 'Driver of a passenger car', 'Driver of a motorcycle', NULL, NULL, 10, '{0,2}'::int[], NULL, 'Hello! Remember: a green traffic light, especially in the shape of an arrow, is your ''go'' signal. If your lane is controlled by that specific signal, you are free to proceed. The passenger car driver is following the rules perfectly here!', 'ticket_media/new/ticketIMG-3.jpg'),
(8, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს ენიჭება უპირატესობა ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-3 პუნქტის „ბ“ ქვეპუნქტის თანახმად, რეგულირებულ გზაჯვარედინზე, შუქნიშნის დამატებით სექციაში ძირითად ყვითელ ან წითელ მაშუქ სიგნალთან ერთად ჩართული ისრის მიმართულებით მოძრაო¬ბისას სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს სხვა მიმართულებიდან მოძრავ სატრანსპორტო საშუალებას.', 1, '1', 'მოტოციკლის მძღოლს', 'მსუბუქი ავტომობილის მძღოლს', NULL, NULL, 10, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, დამატებითი სექციის ისარი არ ნიშნავს, რომ უპირატესობა შენ გაქვს. თუ ძირითადი შუქნიშანი წითელია, შენ სტუმარი ხარ გზაზე და ვალდებული ხარ გზა დაუთმო მათ, ვისაც მწვანე ანთია!', 'ticket_media/new/ticketIMG-8.jpg'),
(8, 'ru', 'Водитель какого транспортного средства имеет преимущество при движении в направлении стрелки?', 'Согласно пункту 3 «б» статьи 36 Закона Грузии «О дорожном движении», при движении в направлении стрелки, включенной в дополнительной секции светофора одновременно с основным красным или желтым сигналом, водитель обязан уступить дорогу транспортным средствам, движущимся с других направлений. Преимущество отдается транспортному средству, которое следует на основной разрешающий сигнал светофора.', 1, '1', 'Водитель мотоцикла', 'Водитель легкового автомобиля', NULL, NULL, 10, '{0,2}'::int[], NULL, 'Привет! Запомни: стрелка в дополнительной секции светофора не дает тебе безусловного приоритета. Если основной сигнал светофора красный, ты обязан уступить дорогу всем, кто едет на основной зеленый свет!', 'ticket_media/new/ticketIMG-8.jpg'),
(8, 'en', 'Which vehicle driver is granted priority when moving in the direction of the arrow?', 'According to Article 36, Paragraph 3, Subparagraph ''b'' of the Georgian ''Law on Road Traffic'', when a driver moves in the direction of an arrow shown in a supplementary traffic light section while the main signal is red or yellow, they must yield the right of way to vehicles approaching from other directions. Priority is granted to the vehicle moving in accordance with the main green signal.', 1, '1', 'Motorcycle driver', 'Passenger car driver', NULL, NULL, 10, '{0,2}'::int[], NULL, 'Hello! Remember, the arrow in the supplementary section doesn''t give you automatic priority. If the main traffic light is red, you must yield to everyone else who has the green light!', 'ticket_media/new/ticketIMG-8.jpg'),
(12, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს წარმოექმნება გზის დათმობის ვალდებულება ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის 2.3 პუნქტის თანახმად, საგზაო ნიშანი 2.3 „დაუთმე გზა” - გზა, რომელზე მოძრავი მძღოლიც ვალდებულია გზა დაუთმოს გადა¬სა¬კვეთ გზაზე მოძრავ მძღოლს. ამავე კანონის მე-2 დანართის 1.13 პუნქტის თანახმად ჰორიზონტალური საგზაო მონიშვნა 1.13. აღნიშნავს ადგილს, სადაც მძღოლი აუცილებლობის შემთხვევაში უნდა გაჩერდეს და გზა უნდა დაუთმოს გადამკვეთ გზაზე მოძრავ სატრანსპორტო საშუალებას.', 1, '1', 'მსუბუქი ავტომობილის მძღოლს', 'მოტოციკლის მძღოლს', NULL, NULL, 20, '{0,2,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ნიშანი „დაუთმე გზა“ და მონიშვნა 1.13 (სამკუთხედები გზაზე) ყოველთვის ნიშნავს, რომ შენ უნდა დაელოდო იმ სატრანსპორტო საშუალებებს, რომლებსაც უპირატესობა აქვთ გადამკვეთ გზაზე. თუ ისარი შენსკენ მიუთითებს, შენი მოვალეობაა გაჩერდე და გაატარო სხვა მძღოლები.', 'ticket_media/new/ticketIMG-12.jpg'),
(12, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу при движении в направлении стрелки?', 'Согласно пункту 2.3 Приложения №1 Закона Грузии «О дорожном движении», дорожный знак 2.3 «Уступи дорогу» обязывает водителя уступить дорогу транспортным средствам, движущимся по пересекаемой дороге. Горизонтальная дорожная разметка 1.13 также указывает на место, где водитель обязан остановиться и уступить дорогу при необходимости.', 1, '1', 'Водитель легкового автомобиля', 'Водитель мотоцикла', NULL, NULL, 20, '{0,2,6}'::int[], NULL, 'Привет! Запомни: если ты видишь знак «Уступи дорогу» или разметку 1.13 (треугольники на дороге), это сигнал, что ты должен пропустить тех, кто едет по пересекаемой дороге. Если стрелка указывает на твое направление, твоя задача — остановиться и уступить проезд, чтобы обеспечить безопасность.', 'ticket_media/new/ticketIMG-12.jpg'),
(12, 'en', 'The driver of which vehicle is obliged to yield the right of way when moving in the direction of the arrow?', 'According to Clause 2.3 of Annex 1 to the Law of Georgia ''On Road Traffic'', road sign 2.3 ''Yield'' obliges the driver to yield the right of way to vehicles moving along the intersecting road. Horizontal road marking 1.13 also indicates the place where a driver must stop if necessary to yield to vehicles on the crossing road.', 1, '1', 'The driver of the passenger car', 'The driver of the motorcycle', NULL, NULL, 20, '{0,2,6}'::int[], NULL, 'Hello! Remember: if you see a ''Yield'' sign or road marking 1.13 (triangles on the road), it is a clear signal that you must let the vehicles moving on the intersecting road pass. If the arrow points in your direction, your duty is to stop and yield to ensure safety for everyone.', 'ticket_media/new/ticketIMG-12.jpg'),
(22, 'ka', 'რომელი ავტომობილის მძღოლს ენიჭება უპირატესობა ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-3 პუნქტის „ბ“ ქვეპუნქტების თანახმად, რეგულირებულ გზაჯვარედინზე, შუქნიშნის დამატებით სექციაში ძირითად ყვითელ ან წითელ მაშუქ სიგნალთან ერთად ჩართული ისრის მიმართულებით მოძრაო¬ბისას, სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს სხვა მიმართულებიდან მოძრავ სატრანსპორტო საშუალებას.', 1, '2', 'ყვითელი ავტომობილის მძღოლს', 'ლურჯი ავტომობილის მძღოლს', NULL, NULL, 10, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს ოქროს წესი: როცა შუქნიშნის დამატებითი ისარი ანთია წითელ ან ყვითელ სიგნალთან ერთად, შენ ხარ „მეორეხარისხოვანი“ მოძრაობის მონაწილე. შენ უნდა დაუთმო გზა ყველას, ვინც მწვანე შუქზე ან თავისი უპირატესობის შესაბამისად მოძრაობს. ამ შემთხვევაში, ლურჯი ავტომობილი მოძრაობს ძირითადი მწვანე სიგნალით, ამიტომ მას აქვს უპირატესობა!', 'ticket_media/new/ticketIMG-22.jpg'),
(22, 'ru', 'Водитель какого автомобиля имеет преимущество при движении в направлении стрелки?', 'Согласно подпункту «б» пункта 3 статьи 36 Закона Грузии «О дорожном движении», при движении в направлении стрелки, включенной одновременно с основным красным или желтым сигналом светофора, водитель обязан уступить дорогу транспортным средствам транспорта, движущимся с других направлений. Таким образом, преимущество имеет тот, кто едет по основному зеленому сигналу или по правилам приоритета, а водитель, поворачивающий по стрелке, обязан уступить.', 1, '2', 'Водитель желтого автомобиля', 'Водитель синего автомобиля', NULL, NULL, 10, '{6}'::int[], NULL, 'Привет! Запомни золотое правило: когда дополнительная секция светофора горит вместе с красным или желтым основным сигналом, ты находишься во «второстепенном» положении. Ты обязан уступить дорогу всем, кто едет на основной зеленый свет или имеет приоритет. В данной ситуации синий автомобиль едет на основной зеленый, поэтому он имеет преимущество!', 'ticket_media/new/ticketIMG-22.jpg'),
(22, 'en', 'Which driver has the right of way when moving in the direction of the arrow?', 'According to Article 36, Clause 3, Sub-clause ''b'' of the Law of Georgia on Road Traffic, when moving in the direction of an arrow signal enabled alongside a primary red or yellow traffic light, the driver must yield to vehicles coming from other directions. Therefore, the right of way belongs to the vehicle moving under the primary green signal or established right-of-way rules, while the driver moving in the direction of the arrow must yield.', 1, '2', 'The yellow car driver', 'The blue car driver', NULL, NULL, 10, '{6}'::int[], NULL, 'Hello! Remember the golden rule: when a turn arrow is lit alongside a primary red or yellow light, you are the one who must yield. You have to give way to everyone moving on a primary green light or those who have the right of way. In this case, the blue car is moving on a primary green signal, so it has the priority!', 'ticket_media/new/ticketIMG-22.jpg'),
(28, 'ka', 'რომელი ავტომობილის მძღოლს წარმოექმნება გზის დათმობის ვალდებულება ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '1', 'მსუბუქი ავტომობილის მძღოლს', 'ავტობუსის მძღოლს', NULL, NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: თუ შენ მეორეხარისხოვან გზაზე ხარ, შენი მიმართულება მნიშვნელოვანი არ არის — ყოველთვის უნდა დაუთმო გზა მთავარ გზაზე მოძრავ მანქანას. ეს უსაფრთხოების გარანტიაა!', 'ticket_media/new/ticketIMG-28.jpg'),
(28, 'ru', 'У водителя какого автомобиля возникает обязанность уступить дорогу при движении в направлении стрелки?', 'Согласно подпункту «а» пункта 4 статьи 36 Закона Грузии «О дорожном движении», на нерегулируемом перекрестке при пересечении дорог разного значения водитель, движущийся по второстепенной дороге, обязан уступить дорогу транспортному средству, приближающемуся по главной дороге.', 1, '1', 'Водитель легкового автомобиля', 'Водитель автобуса', NULL, NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни золотое правило: если ты находишься на второстепенной дороге, не имеет значения, куда ты поворачиваешь. Ты обязан уступить дорогу всем, кто едет по главной. Это основа безопасности на дороге!', 'ticket_media/new/ticketIMG-28.jpg'),
(28, 'en', 'The driver of which vehicle is obliged to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Clause 4, Sub-clause ''a'' of the Law of Georgia ''On Road Traffic'', at an unregulated intersection where roads of different importance cross, a driver on a minor road must yield to any vehicle approaching from the priority (main) road.', 1, '1', 'Driver of the passenger car', 'Driver of the bus', NULL, NULL, 20, '{4}'::int[], NULL, 'Hello! Remember the golden rule: if you are on a minor road, your intended direction doesn''t matter — you must always yield to vehicles on the main road. It''s the foundation of road safety!', 'ticket_media/new/ticketIMG-28.jpg'),
(30, 'ka', 'რა თანამიმდევრობით უნდა გაიარონ გზაჯვარედინი სატრანსპორტო საშუალებებმა ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '1', 'ჯერ უნდა გაიაროს ტრამვაიმ, შემდეგ - მსუბუქმა ავტომობილმა, ბოლოს - მოტოციკლმა', 'ჯერ უნდა გაიაროს მსუბუქმა ავტომობილმა, შემდეგ - ტრამვაიმ, ბოლოს - მოტოციკლმა', 'ჯერ უნდა გაიაროს მოტოციკლმა, შემდეგ - ტრამვაიმ, ბოლოს - მსუბუქმა ავტომობილმა', NULL, 20, '{0,2,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: როცა საქმე ტრამვაის ეხება, მას თითქმის ყოველთვის უპირატესობა აქვს ურელსო ტრანსპორტთან შედარებით. ამიტომ, ჯერ ტრამვაი გადის, ხოლო შემდეგ, დარჩენილ ორ სატრანსპორტო საშუალებას შორის, „მარჯვენა ხელის“ წესით ვადგენთ რიგითობას.', 'ticket_media/new/ticketIMG-30.jpg'),
(30, 'ru', 'В какой последовательности транспортные средства должны проехать перекресток при движении в указанном стрелками направлении?', 'В соответствии с пунктом 4 статьи 36 Закона Грузии «О дорожном движении», на перекрестке равнозначных дорог рельсовое транспортное средство (трамвай) имеет преимущество перед безрельсовыми транспортными средствами, независимо от направления его движения. Остальные безрельсовые транспортные средства разъезжаются согласно правилу «помехи справа».', 1, '1', 'Сначала трамвай, затем легковой автомобиль, в конце - мотоцикл', 'Сначала легковой автомобиль, затем трамвай, в конце - мотоцикл', 'Сначала мотоцикл, затем трамвай, в конце - легковой автомобиль', NULL, 20, '{0,2,8}'::int[], NULL, 'Привет! Запомни золотое правило: когда на перекрестке есть трамвай, он почти всегда имеет приоритет перед безрельсовым транспортом. Поэтому сначала едет трамвай, а для остальных двух транспортных средств мы применяем правило «помехи справа», чтобы понять, кто проедет следующим.', 'ticket_media/new/ticketIMG-30.jpg'),
(30, 'en', 'In what order should the vehicles pass the intersection when moving in the direction of the arrows?', 'In accordance with Article 36, paragraph 4 of the Law of Georgia ''On Road Traffic'', at an intersection of equal importance, a rail vehicle (tram) has priority over non-rail vehicles, regardless of its direction of travel. The remaining non-rail vehicles proceed according to the ''right-hand rule''.', 1, '1', 'First the tram, then the passenger car, finally the motorcycle', 'First the passenger car, then the tram, finally the motorcycle', 'First the motorcycle, then the tram, finally the passenger car', NULL, 20, '{0,2,8}'::int[], NULL, 'Hello! Remember the golden rule: when a tram is involved at an intersection, it almost always has priority over non-rail vehicles. Therefore, the tram goes first, and for the remaining two vehicles, we use the ''right-hand rule'' to determine who goes next.', 'ticket_media/new/ticketIMG-30.jpg'),
(44, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლი დაარღვევს საგზაო მოძრაობის წესებს ისრის მიმართულებით მოძრაობის შემთხვევაში მარეგულირებლის ამ სიგნალზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 30-ე მუხლის მე-5 პუნქტის „ბ“ ქვეპუნქტის თანახმად, მარეგულირებლის სიგნალებს აქვთ შემდეგი მნიშვნელობა: ბ) განზე გაშვერილი ან ჩამოშვებული ხელები − ეს ჟესტი ნიშნავს „სდექ“ სიგნალს იმ საგზაო მოძრაობის მონაწილეებისათვის, რომლებიც, მათი მოძრაობის მიმართულების მიუხედავად, მოძრაობენ იმ მიმართულებით, რომელიც კვეთს მარეგულირებლის გაწვდილი ხელით ან ხელებით მინიშნებულ მიმართულებას; ამასთანავე, მარეგულირებლის მარჯვენა და მარცხენა გვერდების მხრიდან ტრამვაის უფლება აქვს, იმოძრაოს პირდაპირ, ურელსო სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს პირდა¬პირ და მარჯვნივ, ხოლო ქვეითს უფლება აქვს, გადავიდეს გზის სავალ ნაწილზე.', 1, '3', 'მხოლოდ ტრამვაისა და მოტოციკლის მძღოლები', 'მხოლოდ ტრამვაისა და მსუბუქი ავტომობილის მძღოლები', 'მხოლოდ მსუბუქი ავტომობილისა და მოტოციკლის მძღოლები', NULL, 11, '{0,2,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი წესი: როცა მარეგულირებლის ხელები განზეა გაშვერილი, ურელსო ტრანსპორტს (ავტომობილს, მოტოციკლს) მხოლოდ პირდაპირ ან მარჯვნივ შეუძლია წასვლა. მარცხნივ მოხვევა მათთვის კატეგორიულად აკრძალულია, ამიტომ ისინი არღვევენ წესებს.', 'ticket_media/new/ticketIMG-44.jpg'),
(44, 'ru', 'Водитель какого транспортного средства нарушит правила дорожного движения при движении в указанном стрелкой направлении при данном сигнале регулировщика?', 'Согласно пункту 5 «б» статьи 30 Закона Грузии «О дорожном движении», при разведенных в стороны руках регулировщика трамваю разрешено движение только прямо. Безрельсовым транспортным средствам (легковой автомобиль и мотоцикл) разрешено движение только прямо и направо. Соответственно, если в данном случае стрелка указывает на поворот налево, выполнение этого маневра является нарушением для легкового автомобиля и мотоцикла.', 1, '3', 'Только водители трамвая и мотоцикла', 'Только водители трамвая и легкового автомобиля', 'Только водители легкового автомобиля и мотоцикла', NULL, 11, '{0,2,8}'::int[], NULL, 'Привет! Запомни простое правило: когда руки регулировщика разведены в стороны, безрельсовым транспортным средствам (автомобилям, мотоциклам) разрешено движение только прямо или направо. Поворот налево им категорически запрещен, поэтому в данном случае они нарушают правила.', 'ticket_media/new/ticketIMG-44.jpg'),
(44, 'en', 'The driver of which vehicle will violate traffic rules if they proceed in the direction indicated by the arrow while the traffic controller is giving this signal?', 'According to Article 30, paragraph 5, subparagraph ''b'' of the Law of Georgia ''on Road Traffic'', when the traffic controller''s arms are extended to the sides, the tram is allowed to move only straight. Non-rail vehicles (passenger car and motorcycle) are permitted to move only straight and to the right. Consequently, if the arrow in the diagram indicates a left turn, this maneuver constitutes a violation for the passenger car and the motorcycle.', 1, '3', 'Only the drivers of the tram and the motorcycle', 'Only the drivers of the tram and the passenger car', 'Only the drivers of the passenger car and the motorcycle', NULL, 11, '{0,2,8}'::int[], NULL, 'Hi there! Remember a simple rule: when the traffic controller''s arms are extended to the sides, non-rail vehicles (cars, motorcycles) are only allowed to move straight or turn right. Turning left is strictly prohibited for them, which is why they would be violating the rules in this case.', 'ticket_media/new/ticketIMG-44.jpg'),
(61, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლი დაარღვევს საგზაო მოძრაობის წესებს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 32-ე მუხლის მე-5 პუნქტის თანახმად, გარდა იმ შემთხვევისა, როცა მოხვევა სრულდება გზაჯვარედინზე გასასვლელად, სადაც წრიული მოძრაობაა ორგანიზებული, მარჯვნივ ან მარცხნივ მოხვევის წინ, აგრეთვე მობრუნების წინ სატრანსპორტო საშუალების მძღოლი ვალდებულია დროულად დაიკავოს შესაბამისი განაპირა მდებარეობა სავალ ნაწილზე, რომელიც თანმხვედრი მიმართულებით მოძრაობისთვისაა განკუთვნილი.', 1, '2', 'თეთრი ავტომობილის მძღოლი', 'ყვითელი ავტომობილის მძღოლი', NULL, NULL, 10, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოხვევის დროს ყოველთვის უნდა იდგე იმ ზოლში, საიდანაც მოხვევაა ნებადართული. თუ შენ მეორე ზოლში ხარ, მოხვევა არ შეიძლება, რადგან გზას უჭრი სხვებს და არღვევ წესებს. ყვითელი მანქანა აქ არღვევს, რადგან არასწორი ზოლიდან უხვევს!', 'ticket_media/new/ticketIMG-61.jpg'),
(61, 'ru', 'Водитель какого транспортного средства нарушит правила дорожного движения при движении в направлении стрелки?', 'Согласно пункту 5 статьи 32 Закона Грузии «О дорожном движении», перед совершением поворота водитель обязан заблаговременно занять соответствующее крайнее положение на проезжей части. Желтый автомобиль совершает поворот со второй полосы, что является нарушением данного требования.', 1, '2', 'Водитель белого автомобиля', 'Водитель желтого автомобиля', NULL, NULL, 10, '{6}'::int[], NULL, 'Привет! Запомни золотое правило: перед поворотом нужно заранее занять крайнее положение. Если ты находишься во втором ряду, поворачивать нельзя — это опасно и нарушает правила, так как ты создаешь помехи другим. Желтый автомобиль нарушает правила, совершая поворот не из крайнего ряда!', 'ticket_media/new/ticketIMG-61.jpg'),
(61, 'en', 'Which vehicle driver would violate traffic rules if driving in the direction of the arrow?', 'According to Article 32, paragraph 5 of the Law of Georgia on Road Traffic, a driver is required to occupy the appropriate extreme position on the roadway in good time before making a turn. The yellow vehicle is turning from the second lane, which violates this requirement.', 1, '2', 'The driver of the white car', 'The driver of the yellow car', NULL, NULL, 10, '{6}'::int[], NULL, 'Hello! Remember the golden rule: before turning, you must move into the appropriate lane in advance. If you are in the second lane, you cannot turn because you are cutting off others and breaking the rules. The yellow car is in violation here because it is turning from the wrong lane!', 'ticket_media/new/ticketIMG-61.jpg'),
(70, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს წარმოექმნება გზის დათმობის ვალდებულება ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 32-ე მუხლის მე-12 პუნქტის თანახმად, თუ სატრანსპორტო საშუალებების მოძრაობის ტრაექტორიები იკვეთება, ხოლო გავლის რიგითობა განსაზღვრული არ არის, მძღოლმა გზა უნდა დაუთმოს იმ სატრანსპორტო საშუალებას, რომელიც მას მარჯვნიდან უახლოვდება.', 1, '2', 'ყვითელი ავტომობილის მძღოლს', 'მოტოციკლის მძღოლს', NULL, NULL, 20, '{0,2,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის“ წესი: როცა გზაჯვარედინზე არ არის მანიშნებელი ნიშნები ან შუქნიშანი, ყოველთვის უნდა დაუთმო იმას, ვინც მარჯვნიდან მოგიახლოვდება. რადგან მოტოციკლისტს მარჯვენა მხარე დაკავებული აქვს, მან უნდა დაელოდოს სხვებს.', 'ticket_media/new/ticketIMG-70.jpg'),
(70, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу при движении в направлении стрелки?', 'Согласно пункту 12 статьи 32 Закона Грузии «О дорожном движении», в случае пересечения траекторий при отсутствии установленной очередности проезда, действует правило «помехи справа». Так как мотоциклист видит приближающееся транспортное средство справа, он обязан уступить дорогу.', 1, '2', 'Водитель желтого автомобиля', 'Водитель мотоцикла', NULL, NULL, 20, '{0,2,6}'::int[], NULL, 'Привет! Запомни правило «помехи справа»: если на перекрестке нет знаков или светофора, всегда уступай тому, кто приближается справа. Так как справа от мотоциклиста находится другое транспортное средство, он должен пропустить его первым.', 'ticket_media/new/ticketIMG-70.jpg'),
(70, 'en', 'The driver of which vehicle is obliged to yield the right of way when moving in the direction of the arrow?', 'According to Article 32, Clause 12 of the Law of Georgia on Road Traffic, when vehicle paths intersect and no priority is established, the ''right-hand rule'' applies. Since the motorcycle driver has another vehicle approaching from their right, they are legally obligated to yield.', 1, '2', 'The driver of the yellow car', 'The driver of the motorcycle', NULL, NULL, 20, '{0,2,6}'::int[], NULL, 'Hello! Remember the ''right-hand rule'': whenever there are no traffic signs or lights at an intersection, you must always yield to the person approaching from your right. Since the motorcycle has a vehicle coming from the right, they have to let them pass first.', 'ticket_media/new/ticketIMG-70.jpg'),
(74, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლმა შეიძლება გააგრძელოს ისრის მიმართულებით მოძრაობა მარეგულირებლის ამ სიგნალზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 30-ე მუხლის მე-5 პუნქტის „გ“ ქვეპუნქტის თანახმად, მარეგულირებლის სიგნალებს აქვთ შემდეგი მნიშვნელობა: გ) წინ გაშვერილი მარჯვენა ხელი - ეს ჟესტი ნიშნავს „სდექ“ სიგნალს მარჯვენა გვერდისა და ზურგის მხრიდან მოძრავ ყველა მძღოლისათვის. ამასთანავე, მარეგულირებლის მარცხენა გვერდის მხრიდან ტრამვაის უფლება აქვს, იმოძრაოს მარცხნივ, ხოლო ურელსო სატრანსპორტო საშუალებას უფლება აქვს იმოძრაოს ყველა მიმართულებით. მარეგულირებლის მკერდის მხრიდან ყველა სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს მხოლოდ მარჯვნივ. ქვეითს უფლება აქვს, გადავიდეს სავალ ნაწილზე მარეგუ¬ლირებლის ზურგს უკან.', 1, '2', 'მხოლოდ ტრამვაის მძღოლმა', 'მხოლოდ ყვითელი ავტომობილის მძღოლმა', 'ორივე სატრანსპორტო საშუალების მძღოლმა', NULL, 11, '{6,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი წესი: როცა მარეგულირებელი გიყურებს მკერდით, ეს ნიშნავს „შეგიძლია გააგრძელო გზა მხოლოდ მარჯვნივ“. რადგან ყვითელი ავტომობილი სწორედ ამ მხარესაა და მარჯვნივ მიდის, მას უფლება აქვს იმოძრაოს. ტრამვაი აქ ვერ გაივლის, რადგან ტრამვაისთვის მკერდის მხრიდან მარცხნივ მოხვევა იქნებოდა დაშვებული, აქ კი ის პირდაპირ გადის.', 'ticket_media/new/ticketIMG-74.jpg'),
(74, 'ru', 'Водитель какого транспортного средства может продолжить движение в направлении стрелки при данном сигнале регулировщика?', 'Согласно подпункту «г» пункта 5 статьи 30 Закона Грузии «О дорожном движении», со стороны груди регулировщика всем транспортным средствам (включая трамвай) разрешено движение только направо. Поскольку желтый автомобиль приближается со стороны груди и совершает маневр направо, он действует в соответствии с правилами.', 1, '2', 'Только водитель трамвая', 'Только водитель желтого автомобиля', 'Водители обоих транспортных средств', NULL, 11, '{6,8}'::int[], NULL, 'Привет! Запомни простое правило: когда регулировщик обращен к тебе грудью, это означает «можно ехать только направо». Так как желтый автомобиль находится с этой стороны и поворачивает направо, он может продолжать движение. Трамвай здесь не может ехать, так как со стороны груди ему разрешен поворот только налево, а он движется прямо.', 'ticket_media/new/ticketIMG-74.jpg'),
(74, 'en', 'The driver of which vehicle may continue driving in the direction of the arrow given this traffic controller signal?', 'According to Article 30, Paragraph 5, Subparagraph ''c'' of the Law of Georgia ''on Road Traffic'', from the chest side of the traffic controller, all vehicles (including trams) are allowed to move only to the right. Since the yellow car is positioned at the chest side and is moving to the right, its movement is compliant with the regulations.', 1, '2', 'Only the tram driver', 'Only the yellow car driver', 'Both drivers', NULL, 11, '{6,8}'::int[], NULL, 'Hello! Remember a simple rule: when the traffic controller is facing you with their chest, it means ''you may only turn right''. Since the yellow car is on this side and is turning right, it is allowed to proceed. The tram cannot go here because, from the chest side, a tram is only permitted to turn left, but it is attempting to go straight.', 'ticket_media/new/ticketIMG-74.jpg'),
(77, 'ka', 'რა თანამიმდევრობით უნდა გაიარონ გზაჯვარედინი სატრანსპორტო საშუალებებმა ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'ჯერ უნდა გაიაროს ყვითელმა ავტომობილმა, შემდეგ - სატვირთო ავტომობილმა, ბოლოს - ტროლეიბუსმა', 'ჯერ უნდა გაიაროს სატვირთო ავტომობილმა, შემდეგ - ყვითელმა ავტომობილმა, ბოლოს - ტროლეიბუსმა', 'ჯერ უნდა გაიაროს ტროლეიბუსმა, შემდეგ - ყვითელმა ავტომობილმა, ბოლოს - სატვირთო ავტომობილმა', NULL, 20, '{6}'::int[], NULL, 'გამარჯობა! მოდი მარტივად ავხსნათ: მთავარ გზაზე მყოფი მანქანები ყოველთვის უსწრებენ მეორეხარისხოვანზე მყოფს (ტროლეიბუსს). მთავარ გზაზე კი ორი მანქანაა, მათ შორის უპირატესობას განსაზღვრავს ის, თუ ვის ჰყავს მეორე მანქანა მარჯვნივ. რადგან ყვითელ მანქანას მარჯვნივ გზა თავისუფალი აქვს, ის პირველი გადის!', 'ticket_media/new/ticketIMG-77.jpg'),
(77, 'ru', 'В какой последовательности должны проехать перекресток транспортные средства при движении по стрелкам?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», транспортные средства на главной дороге имеют преимущество. Желтый и грузовой автомобили находятся на главной дороге, где их очередность определяется правилом «правой руки». Поскольку у желтого автомобиля грузовик не находится справа, он проезжает первым, затем грузовик. Троллейбус находится на второстепенной дороге и обязан уступить путь всем участникам на главной дороге.', 1, '1', 'Сначала желтый автомобиль, затем грузовой автомобиль, в конце - троллейбус.', 'Сначала грузовой автомобиль, затем желтый автомобиль, в конце - троллейбус.', 'Сначала троллейбус, затем желтый автомобиль, в конце - грузовой автомобиль.', NULL, 20, '{6}'::int[], NULL, 'Привет! Давай разберемся: машины на главной дороге всегда имеют преимущество перед теми, кто на второстепенной (троллейбус). А на главной дороге мы смотрим на правило правой руки: если справа от машины никого нет, она едет первой. У желтого автомобиля справа никого нет, поэтому он едет первым, затем грузовик, а в конце — троллейбус.', 'ticket_media/new/ticketIMG-77.jpg'),
(77, 'en', 'In what order should the vehicles pass through the intersection when moving in the direction of the arrows?', 'According to Article 36, paragraph 4 of the Georgian Law on Road Traffic, vehicles on the major road have priority. The yellow car and the truck are on the major road, where their priority is determined by the ''right-hand rule''. Since the truck is not approaching from the right of the yellow car, the yellow car goes first, followed by the truck. The trolleybus is on a minor road and must yield to all vehicles on the major road.', 1, '1', 'First the yellow car, then the truck, and finally the trolleybus.', 'First the truck, then the yellow car, and finally the trolleybus.', 'First the trolleybus, then the yellow car, and finally the truck.', NULL, 20, '{6}'::int[], NULL, 'Hello! Let''s simplify: vehicles on the major road always have priority over those on the minor road (the trolleybus). On the major road, we use the ''right-hand rule'': if the way is clear on your right, you go first. Since the yellow car has no one approaching from its right, it goes first, followed by the truck, and finally the trolleybus.', 'ticket_media/new/ticketIMG-77.jpg'),
(83, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'როგორც მსუბუქი, ასევე სატვირთო ავტომობილების მძღოლების მიმართ', NULL, 20, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი წესი: თუ ორივე ავტომობილი მთავარ გზაზეა, უპირატესობა აქვს იმას, ვინც მარჯვნიდან მოდის. რადგან მსუბუქი მანქანა შენს მარჯვნივ არის, მას ეთმობა გზა. წარმატებები!', 'ticket_media/new/ticketIMG-83.jpg'),
(83, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю желтого автомобиля при движении в направлении стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», на нерегулируемых перекрестках водители, находящиеся на главной дороге, должны руководствоваться правилами проезда равнозначных дорог («правило правой руки»). Так как легковой автомобиль находится на главной дороге и для водителя желтого автомобиля он приближается справа, желтый автомобиль обязан уступить ему дорогу.', 1, '1', 'Только водителю легкового автомобиля', 'Только водителю грузового автомобиля', 'Как водителю легкового, так и водителю грузового автомобиля', NULL, 20, '{6}'::int[], NULL, 'Привет! Запомни простое правило: если оба автомобиля на главной дороге, преимущество имеет тот, кто приближается справа. Поскольку легковой автомобиль находится справа от тебя, ты должен уступить ему дорогу. Удачи!', 'ticket_media/new/ticketIMG-83.jpg'),
(83, 'en', 'To which vehicle driver must the yellow car driver yield the right of way when moving in the direction of the arrow?', 'According to Article 36, paragraph 4 of the Georgian Law on Road Traffic, at unregulated intersections, drivers on the main road must follow the rules for equal-priority roads (the ''right-hand rule''). Since the passenger car is on the main road and is approaching from the right side of the yellow vehicle, the yellow vehicle must yield the right of way to it.', 1, '1', 'Only to the driver of the passenger car', 'Only to the driver of the truck', 'To both the passenger car and the truck drivers', NULL, 20, '{6}'::int[], NULL, 'Hello! Remember a simple rule: if both vehicles are on the main road, the one approaching from the right has the priority. Since the passenger car is to your right, you must yield to it. Good luck!', 'ticket_media/new/ticketIMG-83.jpg'),
(84, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს წარმოექმნება გზის დათმობის ვალდებულება ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '1', 'ტრამვაის მძღოლს', 'ავტობუსის მძღოლს', NULL, NULL, 20, '{4,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: თუ შენს გზაზე მოძრაობ და ის მეორეხარისხოვანია, ყოველთვის უნდა დაუთმო გზა მთავარ გზაზე მყოფს. ტრამვაი აქ გამონაკლისი არ არის — კანონის მიხედვით, უპირატესობა მთავარ გზაზე მყოფს აქვს, მიუხედავად იმისა, ტრამვაია ეს თუ სხვა სატრანსპორტო საშუალება.', 'ticket_media/new/ticketIMG-84.jpg'),
(84, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу при движении в направлении стрелки?', 'Согласно подпункту «а» пункта 4 статьи 36 Закона Грузии «О дорожном движении», на нерегулируемом перекрестке при пересечении неравнозначных дорог водитель транспортного средства, движущегося по второстепенной дороге, обязан уступить дорогу транспортному средству, приближающемуся по главной дороге, независимо от направления его дальнейшего движения.', 1, '1', 'Водитель трамвая', 'Водитель автобуса', NULL, NULL, 20, '{4,8}'::int[], NULL, 'Привет! Запомни главное правило: если ты едешь по второстепенной дороге, ты всегда обязан уступить дорогу тем, кто движется по главной. Трамвай здесь не исключение — согласно закону, преимущество имеет тот, кто находится на главной дороге, независимо от типа транспортного средства.', 'ticket_media/new/ticketIMG-84.jpg'),
(84, 'en', 'Which vehicle driver is obliged to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''a'' of the Law of Georgia on Road Traffic, at an unregulated intersection where roads of unequal importance meet, the driver of a vehicle moving on a secondary road is obliged to yield to a vehicle approaching on the main road, regardless of its subsequent direction of travel.', 1, '1', 'Tram driver', 'Bus driver', NULL, NULL, 20, '{4,8}'::int[], NULL, 'Hello! Remember the golden rule: if you are driving on a secondary road, you must always yield to those on the main road. The tram is not an exception here; according to the law, the driver on the main road has the right of way, regardless of whether it is a tram or any other vehicle.', 'ticket_media/new/ticketIMG-84.jpg'),
(86, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'როგორც მსუბუქი, ასევე სატვირთო ავტომობილების მძღოლების მიმართ', NULL, 20, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: თუ გზაჯვარედინზე მთავარ გზაზე მოძრაობ, უპირატესობა შენ გაქვს, ხოლო თუ მარცხნივ უხვევ, გზა უნდა დაუთმო მათ, ვინც პირდაპირ მოდის ან მარჯვნივ უხვევს. რადგან მსუბუქი მანქანა შენს საპირისპიროდ, მთავარ გზაზე მოდის, ის შენზე ადრე გადის!', 'ticket_media/new/ticketIMG-86.jpg'),
(86, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю мотоцикла при движении в направлении стрелки?', 'Согласно статье 36 Закона Грузии «О дорожном движении», водитель мотоцикла, движущийся по главной дороге, пользуется преимущественным правом проезда. При повороте налево водитель обязан уступить дорогу встречному транспортному средству, движущемуся прямо или направо. В данном случае легковой автомобиль движется по главной дороге, поэтому мотоциклист обязан уступить ему дорогу.', 1, '1', 'Только водителю легкового автомобиля', 'Только водителю грузового автомобиля', 'Как водителю легкового, так и грузового автомобиля', NULL, 20, '{0,2}'::int[], NULL, 'Привет! Запомни простое правило: если ты едешь по главной дороге, у тебя преимущество. Но если ты поворачиваешь налево, нужно пропустить тех, кто едет прямо или направо. Поскольку легковой автомобиль едет по главной дороге навстречу тебе, он проезжает первым!', 'ticket_media/new/ticketIMG-86.jpg'),
(86, 'en', 'The driver of which vehicle must the motorcycle driver yield to when moving in the direction of the arrow?', 'According to Article 36 of the Law of Georgia ''On Road Traffic'', a motorcycle driver traveling on a priority road has the right of way. When turning left, a driver must yield to oncoming vehicles traveling straight or turning right. In this scenario, the passenger car is moving along the priority road, therefore the motorcycle driver is legally obligated to yield to it.', 1, '1', 'Only to the driver of the passenger car', 'Only to the driver of the truck', 'To both the passenger car and truck drivers', NULL, 20, '{0,2}'::int[], NULL, 'Hi there! Remember the golden rule: if you are on a priority road, you have the right of way. However, when turning left, you must yield to those coming from the opposite direction who are going straight or turning right. Since the passenger car is on the priority road coming towards you, it gets to go first!', 'ticket_media/new/ticketIMG-86.jpg'),
(94, 'ka', 'რა თანამიმდევრობით უნდა გაიარონ გზაჯვარედინი სატრანსპორტო საშუალებებმა ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'ჯერ უნდა გაიაროს ყვითელმა ავტობუსმა, შემდეგ - მსუბუქმა ავტომობილმა, ბოლოს - ლურჯმა ტროლეიბუსმა', 'ჯერ უნდა გაიაროს მსუბუქმა ავტომობილმა, შემდეგ - ლურჯმა ტროლეიბუსმა, ბოლოს - ყვითელმა ავტობუსმა', 'ჯერ უნდა გაიაროს ლურჯმა ტროლეიბუსმა, შემდეგ - მსუბუქმა ავტომობილმა, ბოლოს - ყვითელმა ავტობუსმა', NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის“ წესი: როცა მთავარი გზა არ არის გამოყოფილი, ყოველთვის დაუთმე გზა მას, ვინც შენს მარჯვნივ არის. ყვითელ ავტობუსს მარჯვნივ გზა თავისუფალი აქვს, ამიტომ ის პირველი გადის. შემდეგ მორიგეობა მსუბუქ ავტომობილზე და ტროლეიბუსზე გადადის.', 'ticket_media/new/ticketIMG-94.jpg'),
(94, 'ru', 'В какой последовательности транспортные средства должны проехать перекресток в направлении, указанном стрелками?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», поскольку все транспортные средства находятся на равнозначных дорогах, применяется правило «помехи справа». Желтый автобус проезжает первым, так как справа от него никого нет. Затем путь освобождается для легкового автомобиля, а в конце проезжает синий троллейбус.', 1, '1', 'Сначала желтый автобус, затем легковой автомобиль, в конце — синий троллейбус', 'Сначала легковой автомобиль, затем синий троллейбус, в конце — желтый автобус', 'Сначала синий троллейбус, затем легковой автомобиль, в конце — желтый автобус', NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни простое правило: если нет знаков приоритета, всегда уступай тому, кто справа. У желтого автобуса справа никого нет, поэтому он едет первым. Освободив дорогу, он позволяет проехать остальным по очереди. Это классическое правило правой руки!', 'ticket_media/new/ticketIMG-94.jpg'),
(94, 'en', 'In what order should the vehicles pass the intersection if they are moving in the direction of the arrows?', 'According to Article 36, paragraph 4 of the Law of Georgia ''On Road Traffic'', since all vehicles are on roads of equal priority, the ''right-hand rule'' applies. The yellow bus proceeds first as there is no vehicle to its right. The path then clears for the passenger car, and finally, the blue trolleybus passes.', 1, '1', 'First the yellow bus, then the passenger car, and finally the blue trolleybus', 'First the passenger car, then the blue trolleybus, and finally the yellow bus', 'First the blue trolleybus, then the passenger car, and finally the yellow bus', NULL, 20, '{4}'::int[], NULL, 'Hello! Remember the simple rule: if there are no priority signs, always give way to the vehicle on your right. The yellow bus has no one to its right, so it goes first. Once it moves, the path clears for the others to follow in sequence. It''s the classic right-hand rule!', 'ticket_media/new/ticketIMG-94.jpg'),
(100, 'ka', 'რა თანამიმდევრობით უნდა გაიარონ გზაჯვარედინი სატრანსპორტო საშუალებებმა ისრის მიმართულებით მოძრაობის შემთხვევაში, თუ ყველა შუქნიშანში ანთია ყვითელი მოციმციმე სიგნალი?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-2 პუნქტის თანახმად, გზაჯვარედინი, რომელზედაც მოძრაობის რიგითობა შუქნიშნის ან მარეგულირებლის სიგნალებით განისაზღვრება, რეგულირებული გზაჯვარედინია. თუ ყვითელი მოციმციმე სიგნალი ანთია, ან შუქნიშანი არ არის ან არ მუშაობს, ან მარეგულირებელი არ დგას, გზაჯვარედინი არარეგულირებულად ითვლება და მძღოლი ვალდებულია იხელმძღვანელოს არარეგულირებული გზაჯვარედინის გავლის წესებითა და გზაჯვარედინზე დაყენებული პრიორიტეტის ნიშნებით. ამავე მუხლის მე-4 პუნქტის „გ“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას უპირატესობა აქვს ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '2', 'ჯერ უნდა გაიაროს ტრამვაიმ, შემდეგ - სატვირთო ავტომობილმა, შემდეგ - ავტობუსმა, ბოლოს - მსუბუქმა ავტომობილმა', 'ჯერ უნდა გაიაროს ტრამვაიმ და მსუბუქმა ავტომობილმა, შემდეგ - ავტობუსმა, ბოლოს - სატვირთო ავტომობილმა', 'ჯერ უნდა გაიაროს სატვირთო ავტომობილმა, შემდეგ - ავტობუსმა, მერე - მსუბუქმა ავტომობილმა, ბოლოს - ტრამვაიმ', NULL, 10, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, როცა შუქნიშანი ყვითლად ციმციმებს, ეს ნიშნავს, რომ „არარეგულირებად“ გზაჯვარედინზე ხარ. აქ მთავარია ორი წესი: ტრამვაი ყოველთვის პირველია და მერე „მარჯვენა ხელის“ წესი მოქმედებს. რადგან მსუბუქ ავტომობილს მარჯვენა მხარე თავისუფალი აქვს, ის ტრამვაისთან ერთად გადის, ხოლო დანარჩენები რიგს ელოდებიან.', 'ticket_media/new/ticketIMG-100.jpg'),
(100, 'ru', 'В какой последовательности транспортные средства должны проехать перекресток в направлении стрелок, если на всех светофорах мигает желтый сигнал?', 'Согласно статье 36, пункту 2 Закона Грузии «О дорожном движении», мигающий желтый сигнал означает, что перекресток является нерегулируемым. Следовательно, мы руководствуемся правилами приоритета: 1. Трамвай имеет преимущество перед безрельсовыми транспортными средствами (ст. 36, п. 4 «г»). 2. Правило правой руки: на равнозначных дорогах уступает тот, у кого помеха справа. В данном случае легковой автомобиль проезжает вместе с трамваем, так как он не имеет помехи справа в своем секторе, а остальные транспортные средства уступают дорогу согласно правилу «помехи справа».', 1, '2', 'Сначала трамвай, затем грузовой автомобиль, затем автобус, в конце — легковой автомобиль', 'Сначала трамвай и легковой автомобиль, затем автобус, в конце — грузовой автомобиль', 'Сначала грузовой автомобиль, затем автобус, потом легковой автомобиль, в конце — трамвай', NULL, 10, '{4}'::int[], NULL, 'Привет! Запомни: мигающий желтый сигнал превращает перекресток в нерегулируемый. Тут работают два главных правила: трамвай — «король» (у него приоритет перед машинами), а потом вступает в силу правило «помехи справа». Так как у легкового автомобиля справа никого нет, он проезжает одновременно с трамваем, а остальные ждут своей очереди.', 'ticket_media/new/ticketIMG-100.jpg'),
(100, 'en', 'In what order should the vehicles pass the intersection in the direction of the arrows if a flashing yellow signal is on at all traffic lights?', 'According to Article 36, Paragraph 2 of the Law of Georgia ''on Road Traffic'', a flashing yellow signal indicates that the intersection is unregulated. Therefore, we follow priority rules: 1. The tram has priority over non-rail vehicles (Article 36, Paragraph 4 ''c''). 2. Right-hand rule: on equal-priority roads, you must yield to the vehicle on the right. In this scenario, the passenger car proceeds alongside the tram as it has no vehicle to its right, while the remaining vehicles yield according to the right-hand priority rule.', 1, '2', 'First the tram, then the truck, then the bus, finally the passenger car', 'First the tram and the passenger car, then the bus, finally the truck', 'First the truck, then the bus, then the passenger car, finally the tram', NULL, 10, '{4}'::int[], NULL, 'Hello! Remember, when the traffic light flashes yellow, it means you are at an ''unregulated'' intersection. Two rules are key here: the tram always goes first, and then the ''right-hand rule'' applies. Since the passenger car has no vehicle to its right, it moves along with the tram, while the others wait their turn.', 'ticket_media/new/ticketIMG-100.jpg'),
(104, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს ენიჭება უპირატესობა ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-3 პუნქტის „ა“ ქვეპუნქტის თანახმად, რეგულირებულ გზაჯვარედინზე, შუქნიშნის მწვანე სიგნალის ჩართვის დროს მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის მოძრავი ტრამვაის მძღოლებმაც.', 1, '1', 'მსუბუქი ავტომობილის მძღოლს', 'ავტობუსის მძღოლს', NULL, NULL, 10, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი წესი: როცა შენ მარცხნივ უხვევ, შენს საპირისპიროდ პირდაპირ ან მარჯვნივ მიმავალ მძღოლს ყოველთვის უნდა დაუთმო გზა. რადგან მსუბუქი ავტომობილი პირდაპირ ან მარჯვნივ მიდის, მას აქვს უპირატესობა. ყურადღებით იყავი გზაჯვარედინზე!', 'ticket_media/new/ticketIMG-104.jpg'),
(104, 'ru', 'Водителю какого транспортного средства предоставляется преимущество при движении в направлении стрелки?', 'Согласно пункту 3а статьи 36 Закона Грузии «О дорожном движении», при повороте налево на регулируемом перекрестке при зеленом сигнале светофора водитель обязан уступить дорогу транспортным средствам, движущимся со встречного направления прямо или направо. Соответственно, легковой автомобиль, движущийся прямо или направо, имеет преимущество.', 1, '1', 'Водителю легкового автомобиля', 'Водителю автобуса', NULL, NULL, 10, '{4}'::int[], NULL, 'Привет! Запомни простое правило: когда ты поворачиваешь налево, ты обязан уступить дорогу встречному транспорту, который едет прямо или направо. Поскольку легковой автомобиль едет прямо или направо, преимущество у него. Будь внимателен на перекрестке!', 'ticket_media/new/ticketIMG-104.jpg'),
(104, 'en', 'Which driver is granted priority when moving in the direction of the arrow?', 'According to Article 36, Clause 3, Sub-clause ''a'' of the Law of Georgia ''on Road Traffic'', when turning left at a regulated intersection on a green light, a driver must yield to vehicles moving straight or turning right from the opposite direction. Therefore, the passenger car moving straight or right has priority.', 1, '1', 'Driver of the passenger car', 'Driver of the bus', NULL, NULL, 10, '{4}'::int[], NULL, 'Hello! Remember a simple rule: when you are turning left, you must always yield to oncoming traffic moving straight or turning right. Since the passenger car is moving straight or right, it has the priority. Stay alert at the intersection!', 'ticket_media/new/ticketIMG-104.jpg'),
(111, 'ka', 'რომელი ავტომობილის მძღოლს წარმოექმნება გზის დათმობის ვალდებულება ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 32-ე მუხლის მე-12 პუნქტის თანახმად, თუ სატრანსპორტო საშუალებების მოძრაობის ტრაექტორიები იკვეთება, ხოლო გავლის რიგითობა განსაზღვრული არ არის, მძღოლმა გზა უნდა დაუთმოს იმ სატრანსპორტო საშუალებას, რომელიც მას მარჯვნიდან უახლოვდება.', 1, '2', 'თეთრი ავტომობილის მძღოლს', 'ლურჯი ავტომობილის მძღოლს', NULL, NULL, 15, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის წესი“: როცა გზაჯვარედინზე გავლის რიგითობა არ არის განსაზღვრული ნიშნებით ან შუქნიშნით, ყოველთვის უნდა დაუთმო იმას, ვინც შენს მარჯვნივ არის. ამ შემთხვევაში, ლურჯი მანქანა მარჯვნიდან მოდის, ამიტომ ის ატარებს თეთრ მანქანას.', 'ticket_media/new/ticketIMG-111.jpg'),
(111, 'ru', 'У водителя какого автомобиля возникает обязанность уступить дорогу при движении в направлении стрелки?', 'Согласно пункту 12 статьи 32 Закона Грузии «О дорожном движении», если траектории движения транспортных средств пересекаются, а очередность проезда не установлена, водитель должен уступить дорогу транспортному средству, приближающемуся справа. Так как синий автомобиль находится справа от белого, у водителя синего автомобиля возникает обязанность уступить дорогу.', 1, '2', 'У водителя белого автомобиля', 'У водителя синего автомобиля', NULL, NULL, 15, '{6}'::int[], NULL, 'Привет! Помни «правило правой руки»: когда очередность проезда на перекрестке не определена знаками или светофором, всегда уступай дорогу тому, кто находится справа от тебя. В данном случае синий автомобиль находится справа, поэтому он должен пропустить белый.', 'ticket_media/new/ticketIMG-111.jpg'),
(111, 'en', 'Which driver is obliged to yield the right of way when moving in the direction of the arrow?', 'According to Article 32, Paragraph 12 of the Law of Georgia ''On Road Traffic'', if the trajectories of vehicles intersect and the order of passage is not determined, the driver must yield to the vehicle approaching from the right. Since the blue car is approaching the intersection from the right relative to the white car, its driver is obligated to yield.', 1, '2', 'The driver of the white car', 'The driver of the blue car', NULL, NULL, 15, '{6}'::int[], NULL, 'Hello! Always remember the ''right-hand rule'': when the order of passage at an intersection is not defined by signs or traffic lights, you must always yield to the vehicle on your right. In this case, the blue car is on the right, so it must give way to the white car.', 'ticket_media/new/ticketIMG-111.jpg'),
(112, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '4', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც მოტოციკლის, ასევე მსუბუქი ავტომობილის მძღოლების მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლის მიმართ', 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: თუ შენ მთავარ გზაზე მოძრაობ, უპირატესობა შენ გაქვს. რადგან ავტობუსი მთავარ გზაზეა, სხვა ავტომობილები ვალდებულნი არიან მას დაუთმონ გზა და არა პირიქით. ამიტომ, პასუხი 4 არის სწორი!', 'ticket_media/new/ticketIMG-112.jpg'),
(112, 'ru', 'По отношению к водителю какого транспортного средства у водителя желтого автобуса возникает обязанность уступить дорогу при движении в направлении стрелки?', 'В соответствии с пунктом 4 статьи 36 Закона Грузии «О дорожном движении», так как желтый автобус движется по главной дороге, у него не возникает обязанности уступать дорогу транспортным средствам, находящимся на второстепенной дороге. Таким образом, с учетом дорожных знаков, преимущественное право проезда принадлежит автобусу.', 1, '4', 'Только по отношению к водителю мотоцикла', 'Только по отношению к водителю легкового автомобиля', 'Как по отношению к водителю мотоцикла, так и по отношению к водителю легкового автомобиля', 'Ни по отношению к какому водителю транспортного средства', 20, '{4}'::int[], NULL, 'Привет! Запомни золотое правило: если ты едешь по главной дороге, у тебя преимущество. Так как автобус находится на главной дороге, другие водители обязаны уступить ему путь, а не наоборот. Поэтому вариант 4 — верный!', 'ticket_media/new/ticketIMG-112.jpg'),
(112, 'en', 'To which vehicle driver is the yellow bus driver required to yield the right of way when moving in the direction of the arrow?', 'In accordance with Article 36, paragraph 4 of the Law of Georgia ''On Road Traffic'', since the yellow bus is traveling on the priority road, it has no obligation to yield to vehicles on the secondary road. Therefore, taking into account the road signs, the bus has the right of way.', 1, '4', 'Only to the motorcycle driver', 'Only to the passenger car driver', 'To both the motorcycle and passenger car drivers', 'To none of the vehicle drivers', 20, '{4}'::int[], NULL, 'Hello! Remember the golden rule: if you are on the priority road, you have the right of way. Since the bus is on the main road, other drivers must yield to it, not the other way around. That is why option 4 is correct!', 'ticket_media/new/ticketIMG-112.jpg'),
(124, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'ორივე სატრანსპორტო საშუალების მძღოლის მიმართ', NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს წესი: როცა მარცხნივ უხვევ, ყოველთვის უნდა დაუთმო გზა მათ, ვინც პირდაპირ მოდის საპირისპირო მხრიდან. რადგან მოტოციკლი პირდაპირ მოძრაობს, ის პრიორიტეტულია. მსუბუქი ავტომობილი კი, სავარაუდოდ, სხვა პირობებშია, ამიტომ პასუხი მხოლოდ მოტოციკლს ეხება.', 'ticket_media/new/ticketIMG-124.jpg'),
(124, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса при движении по направлению стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», подпункт «д», при повороте налево водитель обязан уступить дорогу транспортному средству, движущемуся со встречного направления прямо или направо. В данной ситуации мотоцикл движется прямо со встречного направления, что обязывает водителя автобуса уступить ему дорогу.', 1, '1', 'Только водителю мотоцикла', 'Только водителю легкового автомобиля', 'Водителям обоих транспортных средств', NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни простое правило: при повороте налево ты всегда должен уступать тем, кто едет прямо со встречного направления. Так как мотоцикл едет прямо, у него преимущество. Поэтому мы пропускаем только его!', 'ticket_media/new/ticketIMG-124.jpg'),
(124, 'en', 'To the driver of which vehicle is a bus driver required to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''d'' of the Law of Georgia ''On Road Traffic'', when turning left, a driver is obliged to yield to a vehicle approaching from the opposite direction moving straight or turning right. In this case, the motorcycle is moving straight from the opposite direction, which requires the bus driver to yield.', 1, '1', 'Only to the driver of the motorcycle', 'Only to the driver of the passenger car', 'To the drivers of both vehicles', NULL, 20, '{4}'::int[], NULL, 'Hello! Remember the golden rule: when you turn left, you must always yield to those coming straight from the opposite direction. Since the motorcycle is going straight, it has priority. So, we only yield to the motorcycle!', 'ticket_media/new/ticketIMG-124.jpg'),
(127, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება თეთრი მსუბუქი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '1', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'მხოლოდ ნარინჯისფერი მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც ნარინჯისფერი მსუბუქი ავტომობილის მძღოლის, ასევე ავტობუსის მძღოლის მიმართ', NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს წესი: როდესაც მთავარი გზა იცვლის მიმართულებას, ის იქცევა ისე, თითქოს თანაბარმნიშვნელოვანი გზები იყოს. ავტობუსი შენგან მარჯვნივ მოძრაობს მთავარ გზაზე, ამიტომ შენ ვალდებული ხარ ის გაატარო!', 'ticket_media/new/ticketIMG-127.jpg'),
(127, 'ru', 'Водителю какого транспортного средства обязан уступить дорогу водитель белого легкового автомобиля при движении в направлении стрелки?', 'Согласно пункту 4 «б» статьи 36 Закона Грузии «О дорожном движении», если главная дорога меняет направление, водители, находящиеся на ней, должны руководствоваться правилами проезда равнозначных дорог (уступить дорогу транспортному средству, приближающемуся справа). Автобус движется по главной дороге, и при данных обстоятельствах он приближается к белому автомобилю справа, следовательно, водитель белого автомобиля обязан уступить ему дорогу.', 1, '1', 'Только водителю автобуса', 'Только водителю оранжевого легкового автомобиля', 'Как водителю оранжевого легкового автомобиля, так и водителю автобуса', NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни простое правило: когда главная дорога меняет направление, водители на ней ведут себя так, как будто это перекресток равнозначных дорог. Автобус находится справа от тебя на главной дороге, поэтому ты обязан уступить ему проезд!', 'ticket_media/new/ticketIMG-127.jpg'),
(127, 'en', 'To which vehicle''s driver must the driver of the white passenger car yield the right of way when proceeding in the direction of the arrow?', 'According to Article 36, paragraph 4(b) of the Law of Georgia ''On Road Traffic'', if the main road changes direction, drivers on that road must follow the rules for crossing equivalent roads (yielding to a vehicle approaching from the right). The bus is on the main road and approaches the white car from the right; therefore, the white car driver is legally obligated to yield to the bus.', 1, '1', 'Only to the driver of the bus', 'Only to the driver of the orange passenger car', 'To both the driver of the orange passenger car and the bus', NULL, 20, '{4}'::int[], NULL, 'Hello! Remember this simple rule: when the main road changes its direction, drivers on it must follow the ''yield to the right'' rule. Since the bus is approaching from your right on the main road, you must let it pass first!', 'ticket_media/new/ticketIMG-127.jpg'),
(129, 'ka', 'რომელი სატრანსპორტო საშუალების მიმართ სარგებლობს უპირატესობით მსუბუქი ავტომობილის მძღოლი, ისრის მიმართულებით მოძრაობის შემთხვევაში:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „გ“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'მხოლოდ მოტოციკლის მიმართ', 'მხოლოდ ყვითელი ავტომობილის მიმართ', 'როგორც მოტოციკლის, ასევე ყვითელი ავტომობილის მიმართ', NULL, 20, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს წესი: „დაუთმე გზა მარჯვენას“. რადგან მოტოციკლი შენს მარჯვნივ არ არის (ან შენ გაქვს უპირატესობა გზის ნიშნების მიხედვით), შენ შეგიძლია გააგრძელო მოძრაობა პირველი. ყვითელი ავტომობილი კი, სავარაუდოდ, იმ მხარესაა, სადაც შენ უნდა დაუთმო გზა.', 'ticket_media/new/ticketIMG-129.jpg'),
(129, 'ru', 'Какому транспортному средству уступает дорогу водитель легкового автомобиля при движении в указанном стрелкой направлении?', 'Согласно пункту «г» части 4 статьи 36 Закона Грузии «О дорожном движении», на перекрестке равнозначных дорог водитель безрельсового транспортного средства обязан уступить дорогу транспортному средству, приближающемуся справа. В данном случае водитель легкового автомобиля имеет преимущество перед мотоциклом, так как при движении прямо или в указанном направлении он не находится в ситуации, где мотоцикл приближается справа в условиях равнозначного перекрестка.', 1, '1', 'Только по отношению к мотоциклу', 'Только по отношению к желтому автомобилю', 'Как по отношению к мотоциклу, так и к желтому автомобилю', NULL, 20, '{2}'::int[], NULL, 'Привет! Главное правило, которое нужно помнить: «Уступи дорогу тому, кто справа». Поскольку мотоцикл не находится справа от тебя (или у тебя приоритет по знакам), ты проезжаешь первым. А вот желтый автомобиль, скорее всего, находится в той позиции, где ты обязан уступить ему дорогу.', 'ticket_media/new/ticketIMG-129.jpg'),
(129, 'en', 'Which vehicle does the driver of the passenger car have priority over when moving in the direction of the arrow?', 'According to Article 36, Clause 4, Sub-clause ''c'' of the Georgian Law ''On Road Traffic'', at an intersection of equal roads, the driver of a non-rail vehicle must give way to a vehicle approaching from the right. In this case, the passenger car has priority over the motorcycle because the motorcycle is not approaching from the right at an equal-status intersection, or the car''s direction of travel grants it right-of-way under the law.', 1, '1', 'Only over the motorcycle', 'Only over the yellow car', 'Over both the motorcycle and the yellow car', NULL, 20, '{2}'::int[], NULL, 'Hello! Remember the golden rule: ''Give way to the right.'' Since the motorcycle is not approaching from your right (or you have the right of way according to road signs), you have the priority to go first. The yellow car, however, is likely in a position where you would be required to yield to it.', 'ticket_media/new/ticketIMG-129.jpg'),
(131, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა’, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '1', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც მოტოციკლის მძღოლის, ასევე მსუბუქი ავტომობილის მძღოლის მიმართ', NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის წესი“: როცა გზაჯვარედინზე არ არის პრიორიტეტის ნიშნები, ყოველთვის უნდა დაუთმო გზა იმას, ვინც მარჯვნიდან მოდის. რადგან მოტოციკლი შენს მარჯვნივ არის, მას აქვს უპირატესობა. წარმატებები!', 'ticket_media/new/ticketIMG-131.jpg'),
(131, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса при движении по указанному стрелкой направлению?', 'Согласно подпункту «г» пункта 4 статьи 36 Закона Грузии «О дорожном движении», на перекрестке равнозначных дорог водитель безрельсового транспортного средства обязан уступить дорогу транспортному средству, приближающемуся справа («правило правой руки»). В данном случае мотоцикл приближается к автобусу справа, что дает ему преимущественное право проезда.', 1, '1', 'Только водителю мотоцикла', 'Только водителю легкового автомобиля', 'Как водителю мотоцикла, так и водителю легкового автомобиля', NULL, 20, '{4}'::int[], NULL, 'Привет! Помни «правило правой руки»: если на перекрестке нет знаков приоритета, ты всегда должен уступить дорогу тому, кто приближается справа. Так как мотоцикл находится справа от тебя, у него есть преимущество. Удачи в обучении!', 'ticket_media/new/ticketIMG-131.jpg'),
(131, 'en', 'The driver of which vehicle must the bus driver yield to when proceeding in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''c'' of the Georgian Law on Road Traffic, at an intersection of equal-priority roads, the driver of a non-rail vehicle must yield to any vehicle approaching from the right (''right-hand rule''). In this scenario, the motorcycle approaches the bus from the right side, which grants it priority.', 1, '1', 'Only to the motorcycle driver', 'Only to the passenger car driver', 'To both the motorcycle and the passenger car driver', NULL, 20, '{4}'::int[], NULL, 'Hello! Remember the ''right-hand rule'': when there are no priority signs at an intersection, you must always yield to the vehicle approaching from your right. Since the motorcycle is on your right, it has the right of way. Good luck with your studies!', 'ticket_media/new/ticketIMG-131.jpg'),
(135, 'ka', 'საჭაპანო ტრანსპორტს უნდა ჰქონდეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 22-ე მუხლის მე-3 პუნქტის თანახმად, საჭაპანო ტრანსპორტს უნდა ჰქონდეს კონსტრუქციით გათვალისწინებული გამართული სადგომი სამუხრუჭო მოწყობილობა და დაგორების საწინააღმდეგო საყრდენები, აგრეთვე ამ კანონით დადგენილი წესით იგი აღჭურვილი უნდა იქნეს სინათლეებით.', 0, '3', 'მხოლოდ კონსტრუქციით გათვალისწინებული გამართული სადგომი სამუხრუჭო მოწყობილობა', 'მხოლოდ დაგორების საწინააღმდეგო საყრდენები', 'როგორც კონსტრუქციით გათვალისწინებული გამართული სადგომი სამუხრუჭო მოწყობილობა, ასევე დაგორების საწინააღმდეგო საყრდენები', NULL, 2, '{2,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ საჭაპანო ტრანსპორტიც საგზაო მოძრაობის სრულფასოვანი მონაწილეა. უსაფრთხოების მიზნით, კანონი ავალდებულებს მათ, ჰქონდეთ ორივე დამცავი საშუალება: სამუხრუჭო სისტემაც და საყრდენებიც, რათა ტრანსპორტი არ დაიძრას უნებლიედ.', NULL),
(135, 'ru', 'Какими средствами должен быть оборудован гужевой транспорт?', 'Согласно пункту 3 статьи 22 Закона Грузии «О дорожном движении», гужевой транспорт должен быть оснащен как исправным стояночным тормозом, предусмотренным конструкцией, так и противооткатными упорами, что необходимо для обеспечения безопасности и предотвращения самопроизвольного движения транспортного средства.', 0, '3', 'Только исправным стояночным тормозом, предусмотренным конструкцией', 'Только противооткатными упорами', 'Как исправным стояночным тормозом, предусмотренным конструкцией, так и противооткатными упорами', NULL, 2, '{2,7}'::int[], NULL, 'Привет! Помни, что гужевой транспорт является полноценным участником дорожного движения. В целях безопасности закон требует наличия обоих элементов: тормоза и противооткатных упоров, чтобы повозка не покатилась сама по себе при остановке.', NULL),
(135, 'en', 'What equipment must animal-drawn transport have?', 'According to Article 22, Paragraph 3 of the Law of Georgia ''On Road Traffic'', animal-drawn transport must be equipped with both a functional parking brake provided by its design and anti-rollback chocks, which are required to ensure safe and stable parking.', 0, '3', 'Only a functional parking brake as provided by the design', 'Only anti-rollback chocks', 'Both a functional parking brake as provided by the design and anti-rollback chocks', NULL, 2, '{2,7}'::int[], NULL, 'Hello! Remember that animal-drawn transport is a full participant in road traffic. For safety reasons, the law requires them to have both protective measures: a braking system and wheel chocks, to ensure the vehicle does not roll away unintentionally when stopped.', NULL),
(136, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოიქმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც მოტოციკლის მძღოლის, ასევე მსუბუქი ავტომობილის მძღოლის მიმართ', NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის წესი“: თუ გზაჯვარედინი არარეგულირებადია და გზები თანაბარმნიშვნელოვანია, ყოველთვის დაუთმე გზა მას, ვინც შენს მარჯვნივ მოძრაობს. არ აქვს მნიშვნელობა ეს მოტოციკლია თუ მსუბუქი ავტომობილი — ორივე მძღოლი თანაბარი პრივილეგიით სარგებლობს შენს მიმართ, თუ ისინი შენს მარჯვენა მხარეს იმყოფებიან.', 'ticket_media/new/ticketIMG-136.jpg'),
(136, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса при движении в направлении стрелки?', 'Согласно статье 36 Закона Грузии «О дорожном движении», на перекрестке равнозначных дорог преимущество имеет транспортное средство, приближающееся справа (правило правой руки). Если автобус движется в направлении стрелки и пересекает траекторию движения других транспортных средств, он обязан уступить дорогу тем, кто находится справа от него, независимо от типа транспортного средства (мотоцикл или легковой автомобиль).', 1, '3', 'Только по отношению к водителю мотоцикла', 'Только по отношению к водителю легкового автомобиля', 'Как по отношению к водителю мотоцикла, так и по отношению к водителю легкового автомобиля', NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни «правило правой руки»: если перекресток не регулируется, а дороги равнозначны, всегда уступай дорогу тому, кто движется справа от тебя. Неважно, мотоцикл это или легковой автомобиль — оба водителя имеют преимущество перед тобой, если они находятся с правой стороны.', 'ticket_media/new/ticketIMG-136.jpg'),
(136, 'en', 'To the driver of which vehicle is the bus driver obliged to yield the right of way when moving in the direction of the arrow?', 'In accordance with Article 36 of the Law of Georgia ''On Road Traffic'', at intersections of equal roads, priority is granted to the vehicle approaching from the right (the right-hand rule). If the bus moves in the direction of the arrow and intersects the paths of other vehicles, it must yield the right of way to those located to its right, regardless of whether they are motorcycles or passenger cars.', 1, '3', 'Only towards the motorcycle driver', 'Only towards the passenger car driver', 'Both towards the motorcycle driver and the passenger car driver', NULL, 20, '{4}'::int[], NULL, 'Hello! Remember the ''right-hand rule'': if an intersection is unregulated and the roads are of equal status, always yield to whoever is approaching from your right. It doesn''t matter if it is a motorcycle or a passenger car—both drivers have priority over you if they are on your right side.', 'ticket_media/new/ticketIMG-136.jpg'),
(147, 'ka', 'დაარღვევს თუ არა საგზაო მოძრაობის წესებს ავტობუსის მძღოლი ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-4 პუნქტის ქვეპუნქტის თანახმად, სატრანსპორტო საშუალების მოძრაობის რეგულირებისათვის გზის სავალი ნაწილის ზოლებზე, სადაც მოძრაობის მიმართულება საპირისპიროდ იცვლება, გამოიყენება რევერსული შუქნიშანი წითელი X ნიშნის მაშუქი სიგნალითა და ქვემოთ მიმართული მწვანე ისრით. ეს სიგნალი და ისარი შესაბამისად იმ ზოლზე მოძრაობას კრძალავს ან იმ ზოლზე მოძრაობის ნებას რთავს, რომლის ზემოთაც ისინია განლაგებული. რევერსული შუქნიშნის ძირითად ფერად მაშუქ სიგნალებს შეიძლება დაემატოს დიაგონალურად ქვემოთ – მარჯვნივ ან მარცხნივ დახრილი ისრის მქონე ყვითელი ან თეთრი მაშუქი სიგნალი, რომლის ჩართვა იტყობინება ფერადი მაშუქი სიგნალის შემდგომი შეცვლისა და ისრით მითითებულ ზოლზე გადასვლის ვალდებულების შესახებ. ორივე მხრიდან 1.9 საგზაო მონიშვნით აღნიშნული ზოლის ზემოთ მდებარე გამორთული რევერსული შუქნიშანი კრძალავს ამ ზოლზე გასვლას.', 1, '1', 'დაარღვევს', 'არ დაარღვევს', NULL, NULL, 10, '{4,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ რევერსული შუქნიშანი (ისრებიანი) ძალიან მკაცრია. თუ ის გამორთულია, ეს ნიშნავს, რომ ამ ზოლში შესვლა არ შეიძლება! თუ მაინც შეხვალ, ეს წესების დარღვევაა.', 'ticket_media/new/ticketIMG-147.jpg'),
(147, 'ru', 'Нарушит ли правила дорожного движения водитель автобуса в случае движения в направлении стрелки?', 'Согласно пункту 4 статьи 29 Закона Грузии «О дорожном движении», если реверсивный светофор выключен, въезд на полосу запрещен. Поскольку сигнал светофора не разрешает движение, использование данной полосы является нарушением закона.', 1, '1', 'Нарушит', 'Не нарушит', NULL, NULL, 10, '{4,7}'::int[], NULL, 'Привет! Запомни, что реверсивный светофор со стрелками требует особого внимания. Если он выключен — это значит, что полоса закрыта для движения! Въезд на нее в такой ситуации будет нарушением ПДД.', 'ticket_media/new/ticketIMG-147.jpg'),
(147, 'en', 'Will the bus driver violate traffic rules if they proceed in the direction of the arrow?', 'According to Article 29, Paragraph 4 of the Law of Georgia on Road Traffic, if the reversible traffic light is turned off, entering the lane is prohibited. Since the traffic light signal does not permit movement, using this lane constitutes a violation of the law.', 1, '1', 'Will violate', 'Will not violate', NULL, NULL, 10, '{4,7}'::int[], NULL, 'Hello! Remember that a reversible traffic light with arrows is very strict. If it is turned off, it means you are not allowed to enter that lane! Driving into it anyway is a violation of traffic rules.', 'ticket_media/new/ticketIMG-147.jpg'),
(154, 'ka', 'შუქნიშნის ამ სიგნალზე, რომელი მიმართულებითაა შესაძლებელი ტრამვაის მძღოლმა გააგრძელოს მოძრაობა?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-5 პუნქტის თანახმად, სამარშრუტო სატრანსპორტო საშუალებების მოძრაობისათვის სპეციალურად გამოყოფილ ზოლზე მოძრაობის რეგულირებისათვის შეიძლება გამოყენებულ იქნეს „T“-სებურად განლაგებული მოყვითალო ოთხი მრგვალი მაშუქი სიგნალი. მოძრაობა ნებადართულია მხოლოდ მაშინ, როცა ერთდროულად ჩართულია ქვედა და ერთი ან რამდენიმე ზედა მაშუქი სიგნალი, რომელთაგან მარცხენა მარცხნივ მოძრაობის უფლებას იძლევა, საშუალო – პირდაპირ, მარჯვენა კი − მარჯვნივ. თუ ჩართულია მხოლოდ სამი ზედა მაშუქი სიგნალი, მოძრაობა აკრძალულია.', 1, '3', 'მხოლოდ პირდაპირ', 'მხოლოდ მარჯვნივ და მარცხნივ', 'მხოლოდ პირდაპირ და მარცხნივ', 'არცერთი მიმართულებით', 10, '{4,6,8}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე: T-სებურ შუქნიშანზე ქვედა სიგნალი არის „გასაღები“, რომელიც ხსნის მოძრაობას, ხოლო ზედა სიგნალები მიუთითებს მიმართულებებს (მარცხენა-მარცხნივ, შუა-პირდაპირ, მარჯვენა-მარჯვნივ). რადგან ჩართულია ქვედა, შუა და მარცხენა სიგნალი, შეგიძლია წახვიდე მხოლოდ პირდაპირ და მარცხნივ.', 'ticket_media/new/ticketIMG-154.jpg'),
(154, 'ru', 'В каком направлении может продолжить движение водитель трамвая при данном сигнале светофора?', 'Согласно пункту 5 статьи 29 Закона Грузии «О дорожном движении», одновременное включение нижнего сигнала Т-образного светофора с левым верхним и средним верхним сигналами означает, что движение разрешено только налево и прямо.', 1, '3', 'Только прямо', 'Только направо и налево', 'Только прямо и налево', 'Ни в каком направлении', 10, '{4,6,8}'::int[], NULL, 'Привет! Запомни: на Т-образном светофоре нижний сигнал — это «ключ», который разрешает движение, а верхние сигналы указывают направления (левый — налево, средний — прямо, правый — направо). Так как включены нижний, средний и левый сигналы, ты можешь ехать только прямо и налево.', 'ticket_media/new/ticketIMG-154.jpg'),
(154, 'en', 'In which direction may the tram driver continue driving at this traffic light signal?', 'According to Article 29, Paragraph 5 of the Law of Georgia ''On Road Traffic'', the simultaneous activation of the lower signal and the upper left and middle signals of the ''T''-shaped traffic light means that movement is permitted only to the left and straight.', 1, '3', 'Straight only', 'Right and left only', 'Straight and left only', 'None of the directions', 10, '{4,6,8}'::int[], NULL, 'Hello! Remember: on a T-shaped traffic light, the bottom signal is the ''key'' that permits movement, while the upper signals indicate directions (left for left, middle for straight, right for right). Since the bottom, middle, and left signals are on, you are allowed to proceed only straight and to the left.', 'ticket_media/new/ticketIMG-154.jpg'),
(156, 'ka', 'აქვს თუ არა ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის დაწყების უფლება შუქნიშნის ამ სიგნალზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-2 პუნქტის „გ“ ქვეპუნქტის თანახმად, ყვითელი მაშუქი სიგნალი კრძალავს მოძრაობას გარდა ამ მუხლის მე-14 პუნქტით გათვალისწინებული შემთხვევებისა და იტყობინება მაშუქი სიგნალის მოსალოდნელი შეცვლის შესახებ.', 1, '2', 'აქვს უფლება', 'არ აქვს უფლება', NULL, NULL, 10, '{2,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ყვითელი შუქი არის „გამაფრთხილებელი“ სიგნალი. კანონის თანახმად, ის კრძალავს მოძრაობას, რადგან გეუბნება, რომ შუქნიშანი მალე შეიცვლება. არ იჩქარო, მოიცადე მწვანე სიგნალი!', 'ticket_media/new/ticketIMG-156.jpg'),
(156, 'ru', 'Имеет ли право водитель желтого автомобиля начать движение в направлении стрелки при данном сигнале светофора?', 'Согласно подпункту «г» пункта 2 статьи 29 Закона Грузии «О дорожном движении», желтый сигнал светофора запрещает движение (за исключением случаев, предусмотренных пунктом 14 данной статьи) и информирует о предстоящей смене сигнала. Следовательно, начало движения на желтый сигнал запрещено.', 1, '2', 'Имеет право', 'Не имеет права', NULL, NULL, 10, '{2,6}'::int[], NULL, 'Привет! Помни, что желтый свет — это предупреждающий сигнал. Согласно закону, он запрещает движение, так как предупреждает о скорой смене сигнала светофора. Не торопись, дождись зеленого!', 'ticket_media/new/ticketIMG-156.jpg'),
(156, 'en', 'Does the driver of the yellow vehicle have the right to start moving in the direction of the arrow at this traffic light signal?', 'According to Article 29, Paragraph 2, Subparagraph ''c'' of the Law of Georgia on Road Traffic, a yellow traffic light signal prohibits movement (except for cases provided for in paragraph 14 of the same article) and warns of an upcoming signal change. Therefore, starting movement during this signal is prohibited.', 1, '2', 'Has the right', 'Does not have the right', NULL, NULL, 10, '{2,6}'::int[], NULL, 'Hello! Remember, the yellow light is a ''warning'' signal. According to the law, it prohibits movement because it informs you that the signal is about to change. Don''t rush; wait for the green light!', 'ticket_media/new/ticketIMG-156.jpg'),
(159, 'ka', 'შუქნიშნების ამ სიგნალზე, რომელი სატრანსპორტო საშუალების მძღოლს აქვს მოძრაობის დაწყების უფლება ისრის მიმართულებით?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-5 პუნქტის თანახმად, სამარშრუტო სატრანსპორტო საშუალებების მოძრაობისათვის სპეციალურად გამოყოფილ ზოლზე მოძრაობის რეგულირებისათვის შეიძლება გამოყენებულ იქნეს „T“-სებურად განლაგებული მოყვითალო ოთხი მრგვალი მაშუქი სიგნალი. მოძრაობა ნებადართულია მხოლოდ მაშინ, როცა ერთდროულად ჩართულია ქვედა და ერთი ან რამდენიმე ზედა მაშუქი სიგნალი, რომელთაგან მარცხენა მარცხნივ მოძრაობის უფლებას იძლევა, საშუალო – პირდაპირ, მარჯვენა კი − მარჯვნივ. თუ ჩართულია მხოლოდ სამი ზედა მაშუქი სიგნალი, მოძრაობა აკრძალულია. ამავე მუხლის მე-10 პუნქტის თანახმად მწვანე, ყვითელ და წითელ მაშუქ სიგნალებს, რომლებზედაც გამოსახულია ისარი/ისრები, იგივე მნიშვნელობა აქვს, რაც შესაბამისი ფერის უისრო მაშუქ სიგნალებს, მაგრამ მათი მოქმედება ვრცელდება მხოლოდ ისრით/ისრებით მითითებული მიმართულებით/მიმართულებებით. ამასთანავე, ისარი, რომელიც მარცხნივ მოხვევის ნებას რთავს, მობრუნების უფლებასაც იძლევა, თუ ეს აკრძალული არ არის შესაბამისი საგზაო ნიშნით ან საგზაო მონიშვნით. იგივე მნიშვნელობა აქვს შუქნიშნის დამატებით სექციაში მწვანე მაშუქ სიგნალზე გამოსახულ ისარს. შუქნიშნის დამატებითი სექციის გამორთული მაშუქი სიგნალი იტყობინება, რომ ამ სექციით რეგულირებული მიმართულებით მოძრაობა აკრძალულია.', 1, '2', 'მხოლოდ ტრამვაის მძღოლს', 'მხოლოდ მსუბუქი ავტომობილის მძღოლს', 'ორივე სატრანსპორტო საშუალების მძღოლს', NULL, 10, '{4,6,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს: შუქნიშნის ისარი კონკრეტულ მიმართულებას ეხება. თუ მწვანე ისარი ჩართულია ავტომობილებისთვის, მხოლოდ ისინი მოძრაობენ. ტრამვაისთვის კი ცალკე „T“-სებური შუქნიშანია, რომელიც ამ შემთხვევაში არ იძლევა მოძრაობის ნებართვას. ამიტომ, მხოლოდ მსუბუქი ავტომობილი მიდის!', 'ticket_media/new/ticketIMG-159.jpg'),
(159, 'ru', 'При данном сигнале светофора, водителю какого транспортного средства разрешено начать движение в направлении стрелки?', 'Согласно пункту 10 статьи 29 Закона Грузии «О дорожном движении», действие зеленой стрелки на светофоре распространяется только на указанное направление. Так как стрелка предназначена для легкового автомобиля, а специальный Т-образный световой сигнал для трамвая не дает разрешения на движение (или не активен), право на движение имеет только водитель, для которого загорелась соответствующая стрелка.', 1, '2', 'Только водителю трамвая', 'Только водителю легкового автомобиля', 'Водителям обоих транспортных средств', NULL, 10, '{4,6,8}'::int[], NULL, 'Привет! Помни: стрелка на светофоре относится к конкретному направлению. Если включена зеленая стрелка для автомобилей, едут только они. А для трамвая существует отдельный Т-образный светофор, который в данной ситуации не дает права на движение. Поэтому едет только легковой автомобиль!', 'ticket_media/new/ticketIMG-159.jpg'),
(159, 'en', 'At this traffic light signal, which driver has the right to start moving in the direction of the arrow?', 'According to Article 29, Paragraph 10 of the Law of Georgia ''on Road Traffic'', a green arrow on a traffic light applies only to the direction indicated. Since the arrow is meant for the passenger car and the special ''T''-shaped signal for the tram does not grant the right of way (or is inactive), only the driver for whom the green arrow is illuminated has the right to proceed.', 1, '2', 'Only the tram driver', 'Only the passenger car driver', 'Both drivers', NULL, 10, '{4,6,8}'::int[], NULL, 'Hello! Remember: a traffic light arrow applies only to a specific direction. If the green arrow is on for cars, only they may proceed. Trams have a separate ''T''-shaped traffic light which, in this case, does not grant permission to move. Therefore, only the passenger car may go!', 'ticket_media/new/ticketIMG-159.jpg'),
(160, 'ka', 'აქვს თუ არა უფლება ავტობუსის მძღოლს გააგრძელოს მოძრაობა ისრის მიმართულებით, თუ რევერსული შუქნიშანი გამორთულია?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-4 პუნქტის თანახმად, სატრანსპორტო საშუალების მოძრაობის რეგულირებისათვის გზის სავალი ნაწილის ზოლებზე, სადაც მოძრაობის მიმართულება საპირისპიროდ იცვლება, გამოიყენება რევერსული შუქნიშანი წითელი X ნიშნის მაშუქი სიგნალითა და ქვემოთ მიმართული მწვანე ისრით. ეს სიგნალი და ისარი შესაბამისად იმ ზოლზე მოძრაობას კრძალავს ან იმ ზოლზე მოძრაობის ნებას რთავს, რომლის ზემოთაც ისინია განლაგებული. რევერსული შუქნიშნის ძირითად ფერად მაშუქ სიგნალებს შეიძლება დაემატოს დიაგონალურად ქვემოთ – მარჯვნივ ან მარცხნივ დახრილი ისრის მქონე ყვითელი ან თეთრი მაშუქი სიგნალი, რომლის ჩართვა იტყობინება ფერადი მაშუქი სიგნალის შემდგომი შეცვლისა და ისრით მითითებულ ზოლზე გადასვლის ვალდებულების შესახებ. ორივე მხრიდან 1.9 საგზაო მონიშვნით აღნიშნული ზოლის ზემოთ მდებარე გამორთული რევერსული შუქნიშანი კრძალავს ამ ზოლზე გასვლას.', 1, '2', 'აქვს უფლება', 'არ აქვს უფლება', NULL, NULL, 10, '{4}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე: რევერსულ ზოლზე თუ შუქნიშანი ჩამქრალია, ეს ნიშნავს, რომ ამ ზოლში შესვლა აკრძალულია. ის მუშაობს პრინციპით: „თუ არ ანთია, არ შეხვიდე“.', 'ticket_media/new/ticketIMG-160.jpg'),
(160, 'ru', 'Имеет ли право водитель автобуса продолжить движение в направлении стрелки, если реверсивный светофор выключен?', 'Согласно пункту 4 статьи 29 Закона Грузии «О дорожном движении», выключенный реверсивный светофор, расположенный над полосой, обозначенной дорожной разметкой 1.9, запрещает выезд на эту полосу или движение по ней.', 1, '2', 'Имеет право', 'Не имеет права', NULL, NULL, 10, '{4}'::int[], NULL, 'Привет! Запомни: если на реверсивной полосе светофор не горит, значит, въезд на эту полосу запрещен. Работает правило: «Если не горит — не въезжай».', 'ticket_media/new/ticketIMG-160.jpg'),
(160, 'en', 'Does the bus driver have the right to continue driving in the direction of the arrow if the reversible traffic light is turned off?', 'According to Article 29, Paragraph 4 of the Law of Georgia on Road Traffic, a switched-off reversible traffic light located above a lane marked with 1.9 road markings prohibits entering or driving in that lane.', 1, '2', 'Has the right', 'Does not have the right', NULL, NULL, 10, '{4}'::int[], NULL, 'Hello! Remember: if the traffic light on a reversible lane is off, it means you are not allowed to enter that lane. The rule is simple: "If it''s not lit, don''t enter."', 'ticket_media/new/ticketIMG-160.jpg'),
(164, 'ka', 'აქვს თუ არა უფლება ავტობუსის მძღოლს, გააგრძელოს მოძრაობა ისრის მიმართულებით, თუ რევერსული შუქნიშანი გამორთულია?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-4 პუნქტის თანახმად, სატრანსპორტო საშუალების მოძრაობის რეგულირებისათვის გზის სავალი ნაწილის ზოლებზე, სადაც მოძრაობის მიმართულება საპირისპიროდ იცვლება, გამოიყენება რევერსული შუქნიშანი წითელი X ნიშნის მაშუქი სიგნალითა და ქვემოთ მიმართული მწვანე ისრით. ეს სიგნალი და ისარი შესაბამისად იმ ზოლზე მოძრაობას კრძალავს ან იმ ზოლზე მოძრაობის ნებას რთავს, რომლის ზემოთაც ისინია განლაგებული. რევერსული შუქნიშნის ძირითად ფერად მაშუქ სიგნალებს შეიძლება დაემატოს დიაგონალურად ქვემოთ – მარჯვნივ ან მარცხნივ დახრილი ისრის მქონე ყვითელი ან თეთრი მაშუქი სიგნალი, რომლის ჩართვა იტყობინება ფერადი მაშუქი სიგნალის შემდგომი შეცვლისა და ისრით მითითებულ ზოლზე გადასვლის ვალდებულების შესახებ. ორივე მხრიდან 1.9 საგზაო მონიშვნით აღნიშნული ზოლის ზემოთ მდებარე გამორთული რევერსული შუქნიშანი კრძალავს ამ ზოლზე გასვლას.', 1, '2', 'აქვს უფლება', 'არ აქვს უფლება', NULL, NULL, 10, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს: თუ რევერსული შუქნიშანი გამორთულია, ეს ნიშნავს, რომ ამ ზოლში მოძრაობა აკრძალულია. ის ისევე მოქმედებს, როგორც წითელი სიგნალი. უსაფრთხოებისთვის, ასეთ დროს ამ ზოლში არ უნდა შეხვიდე.', 'ticket_media/new/ticketIMG-164.jpg'),
(164, 'ru', 'Имеет ли право водитель автобуса продолжить движение в направлении стрелки, если реверсивный светофор выключен?', 'Согласно пункту 4 статьи 29 Закона Грузии «О дорожном движении», выключенный реверсивный светофор, расположенный над полосой, обозначенной с обеих сторон дорожной разметкой 1.9, запрещает выезд на эту полосу.', 1, '2', 'Имеет право', 'Не имеет права', NULL, NULL, 10, '{4}'::int[], NULL, 'Привет! Запомни: если реверсивный светофор выключен, это значит, что движение по этой полосе запрещено. Он работает так же, как красный сигнал светофора. Для безопасности, в такой ситуации въезжать на эту полосу нельзя.', 'ticket_media/new/ticketIMG-164.jpg'),
(164, 'en', 'Does a bus driver have the right to continue driving in the direction of the arrow if the reversible traffic light is turned off?', 'According to Article 29, Paragraph 4 of the Law of Georgia on Road Traffic, a switched-off reversible traffic light located above a lane marked on both sides by 1.9 road markings prohibits entering that lane.', 1, '2', 'Has the right', 'Does not have the right', NULL, NULL, 10, '{4}'::int[], NULL, 'Hello! Remember: if the reversible traffic light is off, it means that driving in that lane is prohibited. It acts just like a red light signal. For safety, you must not enter that lane when the light is off.', 'ticket_media/new/ticketIMG-164.jpg'),
(197, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს აქვს უფლება გააგრძელოს მოძრაობა ისრის მიმართულებით მარეგულირებლის ამ სიგნალზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 30-ე მუხლის მე-5 პუნქტის „გ“ ქვეპუნქტის თანახმად, მარეგულირებლის სიგნალებს აქვთ შემდეგი მნიშვნელობა - წინ გაშვერილი მარჯვენა ხელი − ეს ჟესტი ნიშნავს „სდექ“ სიგნალს მარეგულირებლის მარჯვენა გვერდისა და ზურგის მხრიდან მოძრავი ყველა მძღოლისათვის; ამასთანავე, მარეგულირებლის მარცხენა გვერდის მხრიდან ტრამვაის უფლება აქვს, იმოძრაოს მარცხნივ, ხოლო ურელსო სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს ყველა მიმართულებით. მარეგულირებლის მკერდის მხრიდან ყველა სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს მხოლოდ მარჯვნივ. ქვეითს უფლება აქვს, გადავიდეს სავალ ნაწილზე მარეგუ¬ლირებლის ზურგის უკან.', 1, '1', 'მხოლოდ ყვითელი ავტომობილის მძღოლს', 'მხოლოდ ტრამვაის მძღოლს', 'ორივე სატრანსპორტო საშუალების მძღოლს', 'არცერთი სატრანსპორტო საშუალების მძღოლს', 11, '{6,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი წესი: როცა მარეგულირებელი მკერდით გიყურებს და ხელი გაშვერილი აქვს, შენთვის მხოლოდ მარჯვნივ მოხვევაა ნებადართული. ტრამვაისთვის კი ეს პოზიცია მოძრაობის აკრძალვას ნიშნავს. ამიტომ, მხოლოდ ყვითელი ავტომობილია მართალი!', 'ticket_media/new/ticketIMG-197.jpg'),
(197, 'ru', 'Водитель какого транспортного средства имеет право продолжить движение в направлении стрелки при данном сигнале регулировщика?', 'Согласно подпункту «г» пункта 5 статьи 30 Закона Грузии «О дорожном движении», когда правая рука регулировщика вытянута вперед, транспортные средства, приближающиеся со стороны его груди (включая желтый автомобиль), имеют право двигаться только направо. Движение трамвая в этой позиции запрещено, так как трамвай обязан следовать только вдоль рук регулировщика.', 1, '1', 'Только водителю желтого автомобиля', 'Только водителю трамвая', 'Водителям обоих транспортных средств', 'Никому из водителей транспортных средств', 11, '{6,8}'::int[], NULL, 'Привет! Запомни простое правило: когда регулировщик стоит к тебе грудью и его рука вытянута вперед, тебе разрешен только поворот направо. Для трамвая эта позиция означает запрет на движение. Поэтому прав только водитель желтого автомобиля!', 'ticket_media/new/ticketIMG-197.jpg'),
(197, 'en', 'Which vehicle driver is permitted to continue moving in the direction of the arrow given this traffic controller signal?', 'According to Article 30, paragraph 5, subparagraph ''c'' of the Georgian Law ''On Road Traffic'', when the traffic controller''s right arm is extended forward, vehicles approaching from the direction of their chest (including the yellow car) are permitted to move only to the right. Tram movement is prohibited in this position, as trams are restricted to moving only along the line of the controller''s arms.', 1, '1', 'Only the driver of the yellow vehicle', 'Only the tram driver', 'Drivers of both vehicles', 'Neither driver', 11, '{6,8}'::int[], NULL, 'Hello! Remember this simple rule: when the traffic controller is facing you with their chest and their arm is extended forward, you are only permitted to turn right. For the tram, this position means that movement is prohibited. Therefore, only the driver of the yellow car is correct!', 'ticket_media/new/ticketIMG-197.jpg'),
(201, 'ka', 'მარეგულირებლის ამ სიგნალზე რომელი ავტომობილის მძღოლს აქვს უფლება გააგრძელოს მოძრაობა?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 30-ე მუხლის მე-5 პუნქტის „ა“ ქვეპუნქტის თანახმად, მარეგულირებლის სიგნალებს აქვთ შემდეგი მნიშვნელობა - ზემოთ აწეული ერთი ხელი - ეს ჟესტი ყველა საგზაო მოძრაობის მონაწილისათვის ნიშნავს „ყურადღება, სდექ“ სიგნალს, გარდა იმ მძღოლებისა, რომლებიც უკვე ვეღარ შეძლებენ გაჩერებას მკვეთრი დამუხრუჭებისა და საკმაო უსაფრთხოების პირობების დაცვით. გარდა ამისა, თუ ეს სიგნალი მიცემულია გზაჯვარედინზე, მძღოლს, რომელიც უკვე შესულია გზაჯვარედინზე, შეუძლია განაგრძოს მოძრაობა. ქვეითმა, რომელიც სიგნალის მიცემისას გზის სავალ ნაწილზე იმყოფება, უნდა გაათავისუფლოს იგი, ხოლო თუ ეს შეუძლებელია − უნდა გაჩერდეს ურთიერთსაპირისპირო მიმართულებით მოძრავი სატრანსპორტო ნაკადების გამყოფ ხაზზე.', 1, '2', 'ორივე ავტომობილის მძღოლს', 'არც ერთი ავტომობილის მძღოლს', 'მხოლოდ ავტობუსის მძღოლს', 'მხოლოდ ოპერატიული სამსახურის ავტომობილის მძღოლს', 11, '{2,4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, როცა მარეგულირებელი ხელს მაღლა სწევს, ეს იგივეა, რაც შუქნიშნის წითელი შუქი. ყველა უნდა გაჩერდეს, რადგან გზა ყველასთვის ჩაკეტილია. გამონაკლისია მხოლოდ ის მძღოლი, რომელიც ისეთ სიტუაციაშია, რომ გაჩერება უსაფრთხოდ არ შეუძლია, ან უკვე გზაჯვარედინზეა.', 'ticket_media/new/ticketIMG-201.jpg'),
(201, 'ru', 'При данном сигнале регулировщика водитель какого автомобиля имеет право продолжить движение?', 'Согласно пункту 5 «а» статьи 30 Закона Грузии «О дорожном движении», поднятая вверх рука регулировщика означает сигнал «Внимание, стой!». Этот сигнал запрещает движение во всех направлениях, за исключением случаев, когда водитель не может остановиться без экстренного торможения или уже находится на перекрестке.', 1, '2', 'Водитель обоих автомобилей', 'Водитель ни одного из автомобилей', 'Только водитель автобуса', 'Только водитель оперативной службы', 11, '{2,4}'::int[], NULL, 'Привет! Запомни: когда регулировщик поднимает руку вверх, это означает «Внимание, стой!». Это равносильно красному сигналу светофора для всех участников. Движение запрещено для всех, пока регулировщик не изменит жест, если только вы не находитесь уже на середине перекрестка.', 'ticket_media/new/ticketIMG-201.jpg'),
(201, 'en', 'With this traffic controller signal, which vehicle driver has the right to continue moving?', 'According to Article 30, paragraph 5, subparagraph ''a'' of the Law of Georgia ''on Road Traffic'', a raised arm by a traffic controller signifies a ''Attention, Stop'' signal. This signal prohibits movement in all directions, except for cases where the driver cannot stop without abrupt braking or is already within the intersection.', 1, '2', 'Driver of both vehicles', 'Driver of neither vehicle', 'Only the bus driver', 'Only the emergency service vehicle driver', 11, '{2,4}'::int[], NULL, 'Hello! Remember: when the traffic controller raises their hand, it acts just like a red traffic light. Everyone must stop because the path is closed to all directions. The only exceptions are drivers who are already inside the intersection or cannot stop safely without emergency braking.', 'ticket_media/new/ticketIMG-201.jpg'),
(209, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლს აქვს მოძრაობის გაგრძელების უფლება ისრის მიმართულებით მარეგულირებლის ამ სიგნალზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 30-ე მუხლის მე-5 პუნქტის „გ“ ქვეპუნქტის თანახმად, მარეგულირებლის სიგნალებს აქვთ შემდეგი მნიშვნელობა - წინ გაშვერილი მარჯვენა ხელი - ეს ჟესტი ნიშნავს „სდექ“ სიგნალს მარეგულირებლის მარჯვენა გვერდისა და ზურგის მხრიდან მოძრავი ყველა მძღოლისათვის; ამასთანავე, მარეგულირებლის მარცხენა გვერდის მხრიდან ტრამვაის უფლება აქვს, იმოძრაოს მარცხნივ, ხოლო ურელსო სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს ყველა მიმართულებით. მარეგულირებლის მკერდის მხრიდან ყველა სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს მხოლოდ მარჯვნივ. ქვეითს უფლება აქვს, გადავიდეს სავალ ნაწილზე მარეგუ¬ლირებლის ზურგის უკან.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლს', 'მხოლოდ მოტოციკლის მძღოლს', 'მხოლოდ მოტოციკლისა და ავტობუსის მძღოლებს', 'ყველა სატრანსპორტო საშუალების მძღოლს', 11, '{0,2,4}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე მარტივი წესი: როცა მარეგულირებელი გვერდულად დგას შენსკენ (მარცხენა მხარეს), ის გიშვებს ყველა მიმართულებით. ვინაიდან მოტოციკლიც და ავტობუსიც ურელსო სატრანსპორტო საშუალებაა, ორივეს შეუძლია მოძრაობა.', 'ticket_media/new/ticketIMG-209.jpg'),
(209, 'ru', 'Водитель какого транспортного средства имеет право продолжить движение в направлении стрелки при данном сигнале регулировщика?', 'Согласно подпункту «г» пункта 5 статьи 30 Закона Грузии «О дорожном движении», со стороны левого бока регулировщика безрельсовым транспортным средствам разрешено движение во всех направлениях, включая направление, указанное стрелкой.', 1, '3', 'Только водитель легкового автомобиля', 'Только водитель мотоцикла', 'Только водители мотоцикла и автобуса', 'Водители всех транспортных средств', 11, '{0,2,4}'::int[], NULL, 'Привет! Запомни простое правило: когда регулировщик стоит к тебе боком (левым), он разрешает движение во всех направлениях. Так как и мотоцикл, и автобус являются безрельсовыми транспортными средствами, оба имеют право ехать.', 'ticket_media/new/ticketIMG-209.jpg'),
(209, 'en', 'Which driver has the right to continue moving in the direction of the arrow given this traffic controller signal?', 'According to Article 30, paragraph 5, subparagraph ''c'' of the Law of Georgia ''on Road Traffic'', from the left side of the traffic controller, non-rail vehicles are allowed to move in all directions, including the direction of the arrow.', 1, '3', 'Only the driver of the car', 'Only the driver of the motorcycle', 'Only the drivers of the motorcycle and the bus', 'Drivers of all vehicles', 11, '{0,2,4}'::int[], NULL, 'Hello! Remember a simple rule: when the traffic controller stands sideways to you (on their left side), they allow movement in all directions. Since both the motorcycle and the bus are non-rail vehicles, both are allowed to proceed.', 'ticket_media/new/ticketIMG-209.jpg'),
(238, 'ka', 'ავტომაგისტრალზე „A“ კატეგორიის სატრანსპორტო საშუალების მძღოლს უფლება აქვს იმოძრაოს არაუმეტეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-7 პუნქტის „ა“ ქვეპუნქტის თანახმად, გარდა ამ კანონით დადგენილი შემთხვევებისა, დაუსახლებელ პუნქტსა და დასახლებულ პუნქტში გზის იმ მონაკვეთზე, რომელზედაც შესაბამისი საგზაო ნიშნით მოძრაობა დაშვებულია 60 კმ/სთ-ზე მეტი სიჩქარით, ნებადართულია, „A“ კატეგორიის, აგრეთვე „A1“ და „B1“ ქვეკატეგორიების სატრანსპორტო საშუალებების მოძრაობა ყველა გზაზე არაუმეტეს 80 კმ/სთ სიჩქარით.', 1, '2', '60 კმ/სთ სიჩქარით', '80 კმ/სთ სიჩქარით', '90 კმ/სთ სიჩქარით', '110 კმ/სთ სიჩქარით', 17, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოციკლები (A კატეგორია) უფრო მოწყვლადნი არიან, ამიტომ კანონი მათთვის ზღუდავს სიჩქარეს 80 კმ/სთ-ით, მიუხედავად იმისა, თუ რა სიჩქარეა დაშვებული ავტომობილებისთვის.', 'ticket_media/new/ticketIMG-238.jpg'),
(238, 'ru', 'С какой максимальной скоростью разрешено двигаться водителю транспортного средства категории «A» по автомагистрали?', 'Согласно подпункту «а» пункта 7 статьи 33 Закона Грузии «О дорожном движении», для транспортных средств категории «A» на всех типах дорог, включая автомагистрали, установлен максимальный скоростной лимит в 80 км/ч.', 1, '2', '60 км/ч', '80 км/ч', '90 км/ч', '110 км/ч', 17, '{2}'::int[], NULL, 'Привет! Запомни: мотоциклы (категория А) считаются более уязвимыми участниками движения, поэтому закон ограничивает их скорость до 80 км/ч на любых дорогах, независимо от того, какие лимиты установлены для автомобилей.', 'ticket_media/new/ticketIMG-238.jpg'),
(238, 'en', 'What is the maximum speed permitted for a driver of a category ''A'' vehicle on a motorway?', 'According to Article 33, Paragraph 7, Subparagraph ''a'' of the Law of Georgia ''On Road Traffic'', a maximum speed limit of 80 km/h is established for category ''A'' vehicles on all types of roads, including motorways.', 1, '2', '60 km/h', '80 km/h', '90 km/h', '110 km/h', 17, '{2}'::int[], NULL, 'Hello! Remember that motorcycles (category A) are considered more vulnerable road users, so the law caps their speed at 80 km/h on all roads, regardless of the higher speed limits that might apply to cars.', 'ticket_media/new/ticketIMG-238.jpg'),
(240, 'ka', 'ავტომაგისტრალზე „D1E“ ქვეკატეგორიის ავტომობილის მძღოლს უფლება აქვს იმოძრაოს არაუმეტეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-7 პუნქტის „ე“ ქვეპუნქტის თანახმად, გარდა ამ კანონით დადგენილი შემთხვევებისა, დაუსახლებელ პუნქტსა და დასახლებულ პუნქტში გზის იმ მონაკვეთზე, რომელზედაც შესაბამისი საგზაო ნიშნით მოძრაობა დაშვებულია 60 კმ/სთ-ზე მეტი სიჩქარით, ნებადართულია: „D1“ და „D1E“ ქვეკატეგორიების სატრანსპორტო საშუალებების მოძრაობა ყველა გზაზე არაუმეტეს 80 კმ/სთ სიჩქარით.', 1, '3', '60 კმ/სთ სიჩქარით', '70 კმ/სთ სიჩქარით', '80 კმ/სთ სიჩქარით', '90 კმ/სთ სიჩქარით', 17, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ავტობუსების და მიკროავტობუსების კატეგორიებს (D1, D1E) კანონი უფრო მკაცრად ზღუდავს, ვიდრე მსუბუქ ავტომობილებს. ავტომაგისტრალზე შენთვის დასაშვები მაქსიმუმი 80 კმ/სთ-ია.', 'ticket_media/new/ticketIMG-240.jpg'),
(240, 'ru', 'С какой максимальной скоростью разрешено движение водителю транспортного средства подкатегории «D1E» на автомагистрали?', 'Согласно подпункту «е» пункта 7 статьи 33 Закона Грузии «О дорожном движении», максимальная разрешенная скорость движения для транспортных средств подкатегорий «D1» и «D1E» на всех дорогах, включая автомагистрали, составляет 80 км/ч.', 1, '3', '60 км/ч', '70 км/ч', '80 км/ч', '90 км/ч', 17, '{6}'::int[], NULL, 'Привет! Помни, что закон устанавливает более строгие ограничения для автобусов и микроавтобусов категорий (D1, D1E), чем для легковых машин. Твой максимальный лимит на автомагистрали — 80 км/ч. Будь внимателен!', 'ticket_media/new/ticketIMG-240.jpg'),
(240, 'en', 'At what maximum speed is a driver of a category ''D1E'' vehicle allowed to travel on a motorway?', 'According to Article 33, Paragraph 7, Subparagraph ''e'' of the Law of Georgia ''On Road Traffic'', the maximum permitted speed for vehicles of subcategories ''D1'' and ''D1E'' on all types of roads, including motorways, is 80 km/h.', 1, '3', '60 km/h', '70 km/h', '80 km/h', '90 km/h', 17, '{6}'::int[], NULL, 'Hello! Remember that the law sets stricter limits for buses and minibuses (D1, D1E) compared to regular passenger cars. Your maximum speed limit on the motorway is 80 km/h. Stay safe!', 'ticket_media/new/ticketIMG-240.jpg'),
(241, 'ka', 'რა მაქსიმალური სიჩქარით მოძრაობის უფლება აქვს „D“ კატეგორიის ავტობუსის მძღოლს მოცემული საგზაო ნიშნის მოქმედების ზონაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-6 პუნქტის თანახმად, თუ ამ კანონით სხვა რამ არ არის დადგენილი, დასახლებულ პუნქტში ნებადართულია სატრანსპორტო საშუალების მოძრაობა არაუმეტეს 60 კმ/სთ სიჩქარით, ხოლო საცხოვრებელ ზონაში − არაუმეტეს 20 კმ/სთ სიჩქარით. თუ დასახლებულ პუნქტში საგზაო პირობები იძლევა მაღალი სიჩქარით მოძრაობის შესაძლებლობას, შესაბამისი საგზაო ნიშნის დადგმით მოძრაობის სიჩქარე შეიძლება გაიზარდოს გზის ცალკეულ მონაკვეთებზე.', 1, '2', '50 კმ/სთ სიჩქარით', '60 კმ/სთ სიჩქარით', '70 კმ/სთ სიჩქარით', '90 კმ/სთ სიჩქარით', 17, '{4}'::int[], NULL, 'გამარჯობა! დასახლებულ პუნქტში მოძრაობისას, თუ დამატებითი ნიშანი არ გვზღუდავს, ჩვენ ვიცავთ ზოგად წესს - მაქსიმუმ 60 კმ/სთ. ეს წესი ვრცელდება ავტობუსებზეც. გახსოვდეს, უსაფრთხოება ყველაზე მნიშვნელოვანია!', 'ticket_media/new/ticketIMG-241.jpg'),
(241, 'ru', 'Какова максимальная разрешенная скорость движения для водителя автобуса категории «D» в зоне действия данного дорожного знака?', 'Согласно пункту 6 статьи 33 Закона Грузии «О дорожном движении», максимальная разрешенная скорость движения транспортных средств в населенном пункте составляет 60 км/ч. Поскольку законодательство не устанавливает иного ограничения для автобусов категории «D» в населенном пункте, применяется общее ограничение скорости.', 1, '2', '50 км/ч', '60 км/ч', '70 км/ч', '90 км/ч', 17, '{4}'::int[], NULL, 'Привет! При движении в населенном пункте, если нет ограничивающих знаков, мы соблюдаем общее правило — максимум 60 км/ч. Это правило касается и автобусов. Помни, безопасность превыше всего!', 'ticket_media/new/ticketIMG-241.jpg'),
(241, 'en', 'What is the maximum speed limit for a driver of a category ''D'' bus within the zone of the given traffic sign?', 'According to Article 33, paragraph 6 of the Law of Georgia ''on Road Traffic'', the maximum speed limit for vehicles in a built-up area is 60 km/h. As the legislation does not establish a different limitation for category ''D'' buses within built-up areas, the general speed limit applies.', 1, '2', '50 km/h', '60 km/h', '70 km/h', '90 km/h', 17, '{4}'::int[], NULL, 'Hello! When driving in a built-up area, if there are no additional restrictive signs, we follow the general rule: a maximum of 60 km/h. This rule also applies to buses. Remember, safety is the most important thing!', 'ticket_media/new/ticketIMG-241.jpg'),
(242, 'ka', 'რა მაქსიმალური სიჩქარით მოძრაობის უფლება აქვს „D“ კატეგორიის ავტობუსის მძღოლს მოცემული საგზაო ნიშნის მოქმედების ზონაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-7 პუნქტის „ვ“ ქვეპუნქტის თანახმად, გარდა ამ კანონით დადგენილი შემთხვევებისა, დაუსახლებელ პუნქტსა და დასახლებულ პუნქტში გზის იმ მონაკვეთზე, რომელზედაც შესაბამისი საგზაო ნიშნით მოძრაობა დაშვებულია 60 კმ/სთ-ზე მეტი სიჩქარით, ნებადართულია „D“ და „DE“ კატეგორიების სატრანსპორტო საშუალებების მოძრაობა ავტომაგისტრალზე არაუმეტეს 80 კმ/სთ სიჩქარით, ხოლო სხვა გზაზე − არაუმეტეს 70 კმ/სთ სიჩქარით.', 1, '2', '60 კმ/სთ სიჩქარით', '80 კმ/სთ სიჩქარით', '90 კმ/სთ სიჩქარით', '110 კმ/სთ სიჩქარით', 17, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ავტობუსები მგზავრთა გადასაყვანად გამოიყენება და მათი სიჩქარე შეზღუდულია უსაფრთხოების მიზნით. კანონი ავტომაგისტრალზე „D“ კატეგორიისთვის აწესებს მაქსიმუმ 80 კმ/სთ-ს, მიუხედავად იმისა, რა სიჩქარე შეიძლება იყოს დაშვებული მსუბუქი ავტომობილებისთვის.', 'ticket_media/new/ticketIMG-242.jpg'),
(242, 'ru', 'С какой максимальной скоростью разрешено движение водителю автобуса категории «D» в зоне действия данного дорожного знака?', 'Согласно подпункту «в» пункта 7 статьи 33 Закона Грузии «О дорожном движении», максимальная скорость движения на автомагистрали для автобусов категории «D» ограничена 80 км/ч.', 1, '2', '60 км/ч', '80 км/ч', '90 км/ч', '110 км/ч', 17, '{4}'::int[], NULL, 'Привет! Помни, что автобусы перевозят пассажиров, поэтому их скорость ограничена в целях безопасности. Закон устанавливает для категории «D» предел в 80 км/ч на автомагистралях, независимо от того, какая скорость разрешена для легковых автомобилей.', 'ticket_media/new/ticketIMG-242.jpg'),
(242, 'en', 'What is the maximum speed allowed for a driver of a category ''D'' bus in the zone covered by this traffic sign?', 'According to Article 33, paragraph 7, subparagraph ''v'' of the Law of Georgia ''On Road Traffic'', the maximum speed limit on a motorway for category ''D'' buses is 80 km/h.', 1, '2', '60 km/h', '80 km/h', '90 km/h', '110 km/h', 17, '{4}'::int[], NULL, 'Hello! Remember that buses transport passengers, so their speed is restricted for safety reasons. The law sets a limit of 80 km/h for category ''D'' on motorways, regardless of the speed limits applicable to passenger cars.', 'ticket_media/new/ticketIMG-242.jpg'),
(244, 'ka', 'რა მაქსიმალური სიჩქარით მოძრაობის უფლება აქვს „D1“ ქვეკატეგორიის ავტომობილის მძღოლს გზის ამ მონაკვეთზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-7 პუნქტის „ე“ ქვეპუნქტის თანახმად, გარდა ამ კანონით დადგენილი შემთხვევებისა, დაუსახლებელ პუნქტსა და დასახლებულ პუნქტში გზის იმ მონაკვეთზე, რომელზედაც შესაბამისი საგზაო ნიშნით მოძრაობა დაშვებულია 60 კმ/სთ-ზე მეტი სიჩქარით, ნებადართულია „D1“ და „D1E“ ქვეკატეგორიების სატრანსპორტო საშუალებების მოძრაობა ყველა გზაზე არაუმეტეს 80 კმ/სთ სიჩქარით.', 1, '2', '60 კმ/სთ სიჩქარით', '80 კმ/სთ სიჩქარით', '90 კმ/სთ სიჩქარით', '110 კმ/სთ სიჩქარით', 17, '{6}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ D1 კატეგორიის ავტომობილებს (მიკროავტობუსებს) კანონი უფრო მკაცრად ზღუდავს, ვიდრე მსუბუქ ავტომობილებს. კანონის მიხედვით, მათი მაქსიმალური დასაშვები სიჩქარე 80 კმ/სთ-ია, მიუხედავად იმისა, რომ გზაზე ნიშანი შეიძლება უფრო მაღალ სიჩქარეს უშვებდეს.', 'ticket_media/new/ticketIMG-244.jpg'),
(244, 'ru', 'С какой максимальной скоростью разрешено движение водителю транспортного средства подкатегории «D1» на данном участке дороги?', 'Согласно подпункту «е» пункта 7 статьи 33 Закона Грузии «О дорожном движении», движение транспортных средств подкатегорий «D1» и «D1E» на дорогах разрешается со скоростью не более 80 км/ч.', 1, '2', '60 км/ч', '80 км/ч', '90 км/ч', '110 км/ч', 17, '{6}'::int[], NULL, 'Привет! Запомни, что для транспортных средств категории D1 (микроавтобусы) закон устанавливает более строгие ограничения, чем для легковых автомобилей. Согласно правилам, их максимальная разрешенная скорость составляет 80 км/ч, даже если дорожные знаки позволяют двигаться быстрее.', 'ticket_media/new/ticketIMG-244.jpg'),
(244, 'en', 'What is the maximum speed permitted for a driver of a category ''D1'' vehicle on this road section?', 'According to Article 33, paragraph 7, subparagraph ''e'' of the Law of Georgia ''On Road Traffic'', the operation of category ''D1'' and ''D1E'' vehicles is permitted at a maximum speed of 80 km/h on all roads.', 1, '2', '60 km/h', '80 km/h', '90 km/h', '110 km/h', 17, '{6}'::int[], NULL, 'Hello! Remember that D1 category vehicles (minibuses) have stricter speed limits than passenger cars. According to the law, their maximum permitted speed is 80 km/h, regardless of whether road signs allow for a higher speed limit.', 'ticket_media/new/ticketIMG-244.jpg'),
(253, 'ka', 'მოცემული საგზაო ნიშნის მოქმედების ზონაში „T“ და „S“ კატეგორიის სატრანსპორტო საშუალებებით მოძრაობა ნებადართულია არაუმეტეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის 3.24 პუნქტის თანახმად საგზაო ნიშანი 3.24 „მაქსიმალური სიჩქარის შეზღუდვა” - კრძალავს მოძრაობას ნიშანზე აღნიშნულზე მეტი სიჩქარით(კმ/სთ). ამავე კანონის 33-ე მუხლის მე-8 პუნქტის „ა“ ქვეპუნქტის თანახმად, თუ ამ კანონით სხვა რამ არ არის დადგენილი, დასახლებულ ან დაუსახლებელ პუნქტში ნებადართულია „T“ და „S“ კატეგორიების სატრანსპორტო საშუალებების მოძრაობა ყველა გზაზე არაუმეტეს 40 კმ/სთ სიჩქარით.', 1, '2', '30 კმ/სთ სიჩქარით', '40 კმ/სთ სიჩქარით', '50 კმ/სთ სიჩქარით', NULL, 5, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ „T“ (ტრაქტორები) და „S“ (სპეცტექნიკა) კატეგორიის სატრანსპორტო საშუალებებს კანონმდებლობით განსაზღვრული აქვთ მოძრაობის შეზღუდული ზღვარი - მაქსიმუმ 40 კმ/სთ. ეს წესი ვრცელდება ნებისმიერ გზაზე, ასე რომ, ეს ციფრი ყოველთვის უნდა გახსოვდეს!', 'ticket_media/new/ticketIMG-253.jpg'),
(253, 'ru', 'В зоне действия данного дорожного знака движение транспортных средств категорий «T» и «S» разрешено со скоростью не более:', 'Согласно подпункту «а» пункта 8 статьи 33 Закона Грузии «О дорожном движении», максимальная разрешенная скорость для транспортных средств категорий «T» и «S» на всех дорогах составляет 40 км/ч, если законом не предусмотрено иное.', 1, '2', '30 км/ч', '40 км/ч', '50 км/ч', NULL, 5, '{7}'::int[], NULL, 'Привет! Запомни, что для транспортных средств категорий «T» (тракторы) и «S» (спецтехника) законом установлен жесткий предел скорости — не более 40 км/ч. Это правило действует на любых дорогах, поэтому просто держи эту цифру в уме!', 'ticket_media/new/ticketIMG-253.jpg'),
(253, 'en', 'In the zone of this road sign, the movement of category "T" and "S" vehicles is permitted at a speed not exceeding:', 'According to Article 33, paragraph 8, subparagraph "a" of the Law of Georgia "on Road Traffic", the maximum permissible speed for category "T" and "S" vehicles on all roads is 40 km/h, unless otherwise provided by law.', 1, '2', '30 km/h', '40 km/h', '50 km/h', NULL, 5, '{7}'::int[], NULL, 'Hello! Remember that for category "T" (tractors) and "S" (special machinery) vehicles, the law sets a strict speed limit of 40 km/h. This rule applies to all roads, so just keep this number in mind whenever you are behind the wheel!', 'ticket_media/new/ticketIMG-253.jpg'),
(308, 'ka', 'ეკრძალება თუ არა მოტოციკლის მძღოლს ისრის მიმართულებით გასწრება, თუ მსუბუქი ავტომობილის გასასწრებად მან უნდა იმოძრაოს მინიმუმ 85 კმ/სთ სიჩქარით?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-7 პუნქტის „ა“ ქვეპუნქტის თანახმად, გარდა ამ კანონით დადგენილი შემთხვევებისა, დაუსახლებელ პუნქტსა და დასახლებულ პუნქტში გზის იმ მონაკვეთზე, რომელზედაც შესაბამისი საგზაო ნიშნით მოძრაობა დაშვებულია 60 კმ/სთ-ზე მეტი სიჩქარით, ნებადართულია: ა) „A“ კატეგორიის, აგრეთვე „A1“ და „B1“ ქვეკატეგორიების სატრანსპორტო საშუალებების მოძრაობა ყველა გზაზე არაუმეტეს 80 კმ/სთ სიჩქარით.', 1, '1', 'ეკრძალება', 'არ ეკრძალება', NULL, NULL, 16, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოციკლეტისთვის კანონი ადგენს მაქსიმალურ სიჩქარეს - 80 კმ/სთ-ს. თუ გასწრებისთვის 85 კმ/სთ სიჩქარე გჭირდება, ეს უკვე კანონის დარღვევაა. ამიტომ, ასეთ შემთხვევაში გასწრება აკრძალულია.', 'ticket_media/new/ticketIMG-308.jpg'),
(308, 'ru', 'Запрещено ли водителю мотоцикла совершать обгон в указанном направлении, если для обгона легкового автомобиля ему необходимо двигаться со скоростью не менее 85 км/ч?', 'Согласно подпункту «а» пункта 7 статьи 33 Закона Грузии «О дорожном движении», максимальная разрешенная скорость для транспортных средств категорий «A», «A1» и «B1» в населенных и ненаселенных пунктах составляет не более 80 км/ч. Следовательно, развитие скорости 85 км/ч для данного типа транспортного средства является нарушением закона.', 1, '1', 'Запрещено', 'Не запрещено', NULL, NULL, 16, '{2}'::int[], NULL, 'Привет! Помни, что закон устанавливает максимальную скорость для мотоциклов — 80 км/ч. Если для обгона тебе нужно разогнаться до 85 км/ч, это будет нарушением правил. Поэтому в такой ситуации совершать обгон запрещено.', 'ticket_media/new/ticketIMG-308.jpg'),
(308, 'en', 'Is a motorcycle driver prohibited from overtaking in the indicated direction if they must travel at a minimum speed of 85 km/h to overtake a passenger car?', 'According to Article 33, paragraph 7, subparagraph ''a'' of the Law of Georgia ''on Road Traffic'', the maximum permissible speed for vehicles in categories ''A'', ''A1'', and ''B1'' in both built-up and non-built-up areas is limited to 80 km/h. Therefore, reaching a speed of 85 km/h for this type of vehicle constitutes a violation of the law.', 1, '1', 'Prohibited', 'Not prohibited', NULL, NULL, 16, '{2}'::int[], NULL, 'Hello! Remember that the law sets a maximum speed limit of 80 km/h for motorcycles. If you need to reach 85 km/h to perform an overtake, you would be breaking the law. Therefore, overtaking in this scenario is prohibited.', 'ticket_media/new/ticketIMG-308.jpg'),
(309, 'ka', 'ეკრძალება თუ არა მოტოციკლის მძღოლს ისრის მიმართულებით გასწრება, თუ მოცემულ გზის მონაკვეთზე ხილვადობა შეზღუდულია?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 34-ე მუხლის მე-9 პუნქტის „ე“ ქვეპუნქტის თანახმად, ამ მუხლის მე-3 პუნქტით დადგენილ მოთხოვნათა გათვალისწინებით გასწრება აკრძალულია შეზღუდული ხილვადობის პირობებში საპირისპირო მოძრაობის ზოლზე გასვლით. ამავე კანონის პირველი დანართის პირველი 1.12.2 პუნქტის თანახმად საგზაო ნიშანი 1.12.2, „სახიფათო მოსახვევი” აღნიშნავს აღნიშნავს მცირერადიუსიანი ან შეზღუდული ხილვადობის მქონე გზის სახიფათო მოსახვევს - მარცხნივ.', 1, '1', 'ეკრძალება', 'არ ეკრძალება', NULL, NULL, 16, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ უსაფრთხოება ყველაზე მნიშვნელოვანია. როდესაც ხილვადობა შეზღუდულია (მაგალითად, მოსახვევში), შენ ვერ ხედავ შემხვედრ ტრანსპორტს, რაც გასწრებას სასიკვდილოდ სახიფათოს ხდის. კანონი კრძალავს ასეთ მანევრს, რათა თავიდან ავიცილოთ შეჯახება.', 'ticket_media/new/ticketIMG-309.jpg'),
(309, 'ru', 'Запрещается ли водителю мотоцикла совершать обгон в направлении стрелки, если видимость на данном участке дороги ограничена?', 'Согласно подпункту «е» пункта 9 статьи 34 Закона Грузии «О дорожном движении», обгон запрещен в условиях ограниченной видимости с выездом на полосу встречного движения. Данное ограничение распространяется на все транспортные средства, включая мотоциклы.', 1, '1', 'Запрещается', 'Не запрещается', NULL, NULL, 16, '{0,2}'::int[], NULL, 'Привет! Помни, что безопасность превыше всего. Когда видимость ограничена (например, на повороте), ты не видишь встречный транспорт, что делает обгон смертельно опасным. Закон запрещает такой маневр, чтобы предотвратить лобовое столкновение.', 'ticket_media/new/ticketIMG-309.jpg'),
(309, 'en', 'Is a motorcycle driver prohibited from overtaking in the direction of the arrow if visibility is limited on that section of the road?', 'According to Article 34, paragraph 9, subparagraph ''e'' of the Law of Georgia on Road Traffic, overtaking is prohibited under conditions of limited visibility when it involves moving into the oncoming traffic lane. This regulation applies to all vehicles, including motorcycles.', 1, '1', 'Prohibited', 'Not prohibited', NULL, NULL, 16, '{0,2}'::int[], NULL, 'Hello! Remember that safety is the most important thing. When visibility is limited (like on a curve), you cannot see oncoming traffic, which makes overtaking deadly. The law prohibits this maneuver to prevent head-on collisions.', 'ticket_media/new/ticketIMG-309.jpg'),
(318, 'ka', 'მოტოციკლის მძღოლს უფლება აქვს გაჩერდეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 37-ე მუხლის მე-2 პუნქტის თანახმად, სატრანსპორტო საშუალება, რომელიც ჩერდება ან დგას სავალ ნაწილზე, უნდა იმყოფებოდეს სავალი ნაწილის კიდესთან რაც შეიძლება ახლოს. ამავე მუხლის მე-4 პუნქტის თანახმად, სატრანსპორტო საშუალებების დგომა ნებადართულია ერთ რიგად, სავალი ნაწილის კიდის პარალელურად, გარდა იმ ადგილისა, რომელიც სატრანსპორტო საშუალების სხვაგვარად დაყენების პირობებს ქმნის. დასაშვებია გვერდითი მისაბმელის გარეშე ორთვლიანი სატრანსპორტო საშუალებების ორ რიგად დაყენება.', 1, '4', 'მხოლოდ A და B ადგილას', 'მხოლოდ B ადგილას', 'როგორც A, ასევე B და C ადგილას', 'მხოლოდ B და C ადგილას', 19, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოციკლი განსაკუთრებული სატრანსპორტო საშუალებაა. კანონი მას უფლებას აძლევს, დადგეს ორ რიგად, რადგან ის კომპაქტურია. თუ A ადგილი კრძალავს გაჩერებას ან არ ითვალისწინებს ორ რიგად დგომას, შენ შეგიძლია გამოიყენო B და C პოზიციები, სადაც ეს მანევრი დაშვებულია.', 'ticket_media/new/ticketIMG-318.jpg'),
(318, 'ru', 'Водителю мотоцикла разрешено остановиться:', 'Согласно пункту 4 статьи 37 Закона Грузии «О дорожном движении», двухколесные транспортные средства без бокового прицепа (мотоциклы) могут быть припаркованы в два ряда. Таким образом, водитель мотоцикла имеет право остановиться в тех местах, где закон и технические условия допускают параллельное размещение двухколесных транспортных средств.', 1, '4', 'Только в местах A и B', 'Только в месте B', 'Как в местах A, B, так и в месте C', 'Только в местах B и C', 19, '{2}'::int[], NULL, 'Привет! Помни, что мотоцикл — особенное транспортное средство. Закон позволяет ему парковаться в два ряда, так как он компактнее автомобиля. Если место A запрещает остановку или не приспособлено для парковки в два ряда, ты можешь использовать позиции B и C, где такой маневр разрешен.', 'ticket_media/new/ticketIMG-318.jpg'),
(318, 'en', 'A motorcycle driver is allowed to stop:', 'According to Article 37, Paragraph 4 of the Law of Georgia ''On Road Traffic'', two-wheeled vehicles (motorcycles) without sidecars are permitted to park in two rows. Therefore, a motorcycle driver is allowed to stop in locations where legal and technical conditions permit the parallel parking of two-wheeled vehicles.', 1, '4', 'Only at places A and B', 'Only at place B', 'At places A, B, and C', 'Only at places B and C', 19, '{2}'::int[], NULL, 'Hello! Remember that a motorcycle is a special vehicle. The law allows it to be parked in two rows because of its compact size. If location A prohibits stopping or is not configured for double-row parking, you may use positions B and C, where this maneuver is permitted.', 'ticket_media/new/ticketIMG-318.jpg'),
(319, 'ka', 'მოტოციკლის მძღოლს უფლება აქვს გაჩერდეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 37-ე მუხლის მე-2 პუნქტის თანახმად, სატრანსპორტო საშუალება, რომელიც ჩერდება ან დგას სავალ ნაწილზე, უნდა იმყოფებოდეს სავალი ნაწილის კიდესთან რაც შეიძლება ახლოს. ამავე მუხლის მე-4 პუნქტის თანახმად, სატრანსპორტო საშუალებების დგომა ნებადართულია ერთ რიგად, სავალი ნაწილის კიდის პარალელურად, გარდა იმ ადგილისა, რომელიც სატრანსპორტო საშუალების სხვაგვარად დაყენების პირობებს ქმნის. დასაშვებია გვერდითი მისაბმელის გარეშე ორთვლიანი სატრანსპორტო საშუალებების ორ რიგად დაყენება.', 1, '3', 'მხოლოდ A ადგილას', 'მხოლოდ B ადგილას', 'მხოლოდ C ადგილას', 'მხოლოდ B და C ადგილას', 19, '{2}'::int[], NULL, 'გამარჯობა! მოტოციკლის მძღოლს მართვის მოწმობის გამოცდაზე ახსოვდეს: კანონი გაძლევს პრივილეგიას, ორთვლიანი მოტოციკლი დააყენო ორ რიგად, მაგრამ მთავარი პრინციპი მაინც სავალი ნაწილის კიდესთან მაქსიმალური სიახლოვეა. C ადგილი საუკეთესოა, რადგან ის უზრუნველყოფს უსაფრთხოებას და კანონის მოთხოვნის ზუსტ შესრულებას.', 'ticket_media/new/ticketIMG-319.jpg'),
(319, 'ru', 'Имеет ли право водитель мотоцикла остановиться:', 'Согласно пункту 4 статьи 37 Закона Грузии «О дорожном движении», двухколесные транспортные средства без бокового прицепа могут быть размещены в два ряда, однако они должны стоять параллельно краю проезжей части и как можно ближе к нему. Место C обеспечивает наиболее корректное расположение в соответствии с требованиями закона относительно края проезжей части.', 1, '3', 'Только в месте A', 'Только в месте B', 'Только в месте C', 'Только в местах B и C', 19, '{2}'::int[], NULL, 'Привет! Как инструктор, напомню: закон разрешает двухколесным мотоциклам парковаться в два ряда, но самое главное — всегда держаться максимально близко к краю проезжей части. Место C — самый безопасный и правильный вариант, так как он полностью соответствует правилам парковки параллельно краю дороги.', 'ticket_media/new/ticketIMG-319.jpg'),
(319, 'en', 'A motorcycle driver is allowed to stop:', 'According to Article 37, Paragraph 4 of the Law of Georgia "On Road Traffic", two-wheeled vehicles (such as a motorcycle without a sidecar) may be parked in two rows, but they must be positioned parallel to the edge of the carriageway and as close to it as possible. Place C represents the correct position in compliance with the legal requirement to stay as close to the edge of the carriageway as possible.', 1, '3', 'Only at place A', 'Only at place B', 'Only at place C', 'Only at places B and C', 19, '{2}'::int[], NULL, 'Hi there! As your instructor, here is a tip: the law allows two-wheeled motorcycles to be parked in two rows, but the priority is always to stay as close to the edge of the road as possible. Place C is the correct choice because it aligns perfectly with the requirement to be positioned parallel and as close to the carriageway edge as possible for maximum safety.', 'ticket_media/new/ticketIMG-319.jpg'),
(323, 'ka', 'აქვს თუ არა უფლება ყვითელი ავტობუსის მძღოლს, გაჩერდეს ისრით მითითებულ ადგილას მგზავრთა ჩასხდომის მიზნით?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 37-ე მუხლის მე-6 პუნქტის „ბ.ა“ ქვეპუნქტის თანახმად, აკრძალულია სატრანსპორტო საშუალებების გაჩერება ნებისმიერ ადგილზე, სადაც მას შეუძლია შექმნას საფრთხე, მათ შორის, ესტაკადაზე, ხიდსა და გზაგამტარზე, გარდა იმ შემთხვევისა, როცა აღნიშნულ ადგილებში ორზე მეტი თანმხვედრი მიმართულების მოძრაობის ზოლია.', 1, '2', 'აქვს უფლება', 'არ აქვს უფლება', NULL, NULL, 19, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ხიდები და ესტაკადები განსაკუთრებით საშიში ზონებია. კანონი კრძალავს იქ გაჩერებას, რადგან ეს ქმნის საცობს და საფრთხეს უქმნის სხვა მძღოლებს. მგზავრთა ჩასხდომისთვის მხოლოდ სპეციალურად გამოყოფილ ადგილები გამოიყენე!', 'ticket_media/new/ticketIMG-323.jpg'),
(323, 'ru', 'Имеет ли право водитель желтого автобуса остановиться в месте, указанном стрелкой, для посадки пассажиров?', 'Согласно подпункту «б.а» пункта 6 статьи 37 Закона Грузии «О дорожном движении», остановка транспортных средств на эстакадах, мостах и путепроводах запрещена, за исключением случаев, когда имеется более двух полос движения в одном направлении. Остановка в указанном месте создает угрозу безопасности дорожного движения.', 1, '2', 'Имеет право', 'Не имеет права', NULL, NULL, 19, '{4,6}'::int[], NULL, 'Привет! Помни, что мосты и эстакады — это зоны повышенной опасности. Закон запрещает там остановку, так как это создает помехи движению и угрожает безопасности. Для посадки пассажиров используй только специально отведенные для этого места!', 'ticket_media/new/ticketIMG-323.jpg'),
(323, 'en', 'Does the driver of a yellow bus have the right to stop at the place indicated by the arrow for the purpose of boarding passengers?', 'According to article 37, paragraph 6, subparagraph ''b.a'' of the Law of Georgia ''On Road Traffic'', stopping vehicles on overpasses, bridges, and flyovers is prohibited, except in cases where there are more than two lanes of traffic in the same direction. Stopping in the specified area poses a threat to road traffic safety.', 1, '2', 'Has the right', 'Does not have the right', NULL, NULL, 19, '{4,6}'::int[], NULL, 'Hello! Remember that bridges and overpasses are high-risk zones. The law prohibits stopping there because it obstructs traffic and endangers others. Always look for designated stops to pick up passengers!', 'ticket_media/new/ticketIMG-323.jpg'),
(338, 'ka', 'აქვს თუ არა უფლება ავტობუსის მძღოლს გაჩერდეს ისრით მითითებულ ადგილას მგზავრთა ჩასხდომის მიზნით?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის მე-5 თავის (განსაკუთრებული მითითებების ნიშნები) 5.1 პუნქტის თანახმად საგზაო ნიშანი 5.1 „ავტომაგისტრალი” - ავტომაგისტრალი, რომელზედაც მოქმედებს ავტომა¬გისტრალზე მოძრაობის მომწესრიგებელი ნორმების მოთხოვნები. ნიშანი იდგმება ავტომაგისტრალის დასაწყისში ან მის სიახლოვეს 8.1.1 დაფით. ამავე კანონის 38-ე მუხლის პირველი პუნქტის „გ.ა“ ქვეპუნქტის თანახმად ავტომაგისტრალზე, ავტომაგისტრალის შესასვლელსა და გამოსასვლელზე მძღოლს ეკრძალება ავტომობილის (ან/და მისი მისაბმელის) გაჩერება ან დგომა, დგომისთვის გამოყოფილი, სპეციალურად მონიშნული ადგილების გარდა. მძღოლმა, რომელიც მისგან დამოუკიდებელი გარემოებების გამო იძულებულია, გაჩერდეს, უნდა მიიღოს ყველა ზომა ავტომობილის (ან/და მისი მისაბმელის) გზის სავალი ნაწილიდან გასაყვანად, ხოლო თუ ამის დაუყოვნებლივ გაკეთება შეუძლებელია − ჩართოს საავარიო შუქსიგნალიზაცია (მისი არსებობის შემთხვევაში) და შესაბამისი ნიშნით მონიშნოს ავტომობილი (ან/და მისი მისაბმელი) საკმარის მანძილზე, რათა დროულად გააფრთხილოს მოახლოებული მძღოლები.', 1, '2', 'აქვს უფლება', 'არ აქვს უფლება', NULL, NULL, 22, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ავტომაგისტრალი მაღალი რისკის ზონაა. კანონი კრძალავს გაჩერებას ისეთ ადგილებში, რომლებიც სპეციალურად არ არის მოწყობილი ამისთვის. მგზავრების ჩასხდომა მხოლოდ სპეციალურად გამოყოფილ „ჯიბეებსა“ და სადგურებზე შეიძლება. უსაფრთხოება უპირველესია!', 'ticket_media/new/ticketIMG-338.jpg'),
(338, 'ru', 'Имеет ли право водитель автобуса остановиться в месте, указанном стрелкой, для посадки пассажиров?', 'Согласно подпункту «г.а» пункта 1 статьи 38 Закона Грузии «О дорожном движении», на автомагистрали водителю запрещается остановка или стоянка, за исключением специально обозначенных мест. Поскольку место, указанное стрелкой, не является специально отведенным для остановки местом, водитель автобуса не имеет права останавливаться там для посадки пассажиров.', 1, '2', 'Имеет право', 'Не имеет права', NULL, NULL, 22, '{6}'::int[], NULL, 'Привет! Помни, автомагистраль — это зона повышенного риска. Закон запрещает остановку в местах, которые специально не оборудованы для этого. Посадка пассажиров разрешена только в специально выделенных «карманах» и на станциях. Безопасность прежде всего!', 'ticket_media/new/ticketIMG-338.jpg'),
(338, 'en', 'Does the bus driver have the right to stop at the place indicated by the arrow for the purpose of boarding passengers?', 'According to Article 38, Paragraph 1, Subparagraph ''g.a'' of the Law of Georgia ''On Road Traffic'', stopping or parking on a motorway is prohibited, except for specially marked areas. Since the location indicated by the arrow is not a designated stopping area, the bus driver is not allowed to stop there to pick up passengers.', 1, '2', 'Has the right', 'Does not have the right', NULL, NULL, 22, '{6}'::int[], NULL, 'Hello! Remember, a motorway is a high-risk zone. The law prohibits stopping in areas that are not specially designated for it. Passengers may only be picked up in specifically designated ''bays'' or stations. Safety comes first!', 'ticket_media/new/ticketIMG-338.jpg'),
(340, 'ka', 'აქვს თუ არა უფლება ავტობუსის მძღოლს, გაჩერდეს ისრით მითითებულ ადგილას, თუ მოცემულ გზას თითოეული მიმართულებისათვის ერთი სამოძრაო ზოლი გააჩნია?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 37-ე მუხლის მე-2 პუნქტის „ბ“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალება, რომელიც ჩერდება ან დგას სავალ ნაწილზე, უნდა იმყოფებოდეს სავალი ნაწილის კიდესთან რაც შეიძლება ახლოს. მძღოლს შეუძლია გაჩერდეს ან დააყენოს სატრანსპორტო საშუალება სავალ ნაწილზე, მარჯვენა მხარეს. სატრანსპორტო საშუალების გაჩერება და დგომა სავალი ნაწილის მარცხენა მხარეს ნებადართულია დასახლებულ პუნქტში იმ გზაზე, სადაც თითოეული მიმართულებისათვის ერთი სამოძრაო ზოლია შუაში ტრამვაის ლიანდაგების გარეშე. ამავე კანონის პირველი დანართის 5.26 პუნქტის თანახმად საგზაო ნიშანი 5.26 „დასახლებული პუნქტის დასასრული“ - მიუთითებს 5.25 ნიშნით აღნიშნული დასახლებული პუნქტის დასასრულს.', 1, '1', 'არ აქვს უფლება', 'აქვს უფლება', NULL, NULL, 19, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ზოგადი წესით ავტომობილი ყოველთვის მარჯვენა მხარეს უნდა გააჩერო. მარცხნივ გაჩერება მხოლოდ მაშინ შეგიძლია, თუ დასახლებულ პუნქტში ხარ, გზა ვიწროა (თითო ზოლი ორივე მხარეს) და შუაში ტრამვაის ლიანდაგები არ გადის. თუ ეს პირობები არ სრულდება, მარცხენა მხარეს გაჩერება კანონდარღვევაა.', 'ticket_media/new/ticketIMG-340.jpg'),
(340, 'ru', 'Имеет ли право водитель автобуса остановиться в месте, указанном стрелкой, если на данной дороге имеется только одна полоса движения для каждого направления?', 'Согласно пункту 2 «б» статьи 37 Закона Грузии «О дорожном движении», транспортное средство должно останавливаться на правой стороне проезжей части. Остановка на левой стороне разрешена только в населенном пункте на дороге с одной полосой для каждого направления при отсутствии трамвайных путей посередине. Если стрелка указывает на левую сторону, а условия не соответствуют исключению, остановка запрещена.', 1, '1', 'Не имеет права', 'Имеет право', NULL, NULL, 19, '{4}'::int[], NULL, 'Привет! Помни, что по общему правилу транспорт нужно останавливать на правой стороне дороги. Остановка слева разрешена только в населенном пункте, где всего по одной полосе в каждом направлении и нет трамвайных путей посередине. Если эти условия не соблюдаются, остановка на левой стороне запрещена.', 'ticket_media/new/ticketIMG-340.jpg'),
(340, 'en', 'Does the bus driver have the right to stop at the place indicated by the arrow, if the given road has only one traffic lane for each direction?', 'According to Article 37, paragraph 2, sub-paragraph ''b'' of the Law of Georgia ''on Road Traffic'', a vehicle must stop on the right side of the carriageway. Stopping on the left side is only permitted in a built-up area on a road with one lane for each direction without tram tracks in the middle. If the arrow points to the left side and the road conditions do not meet this exception, stopping is prohibited.', 1, '1', 'Does not have the right', 'Has the right', NULL, NULL, 19, '{4}'::int[], NULL, 'Hi! Remember that as a general rule, you should always stop on the right side of the road. Stopping on the left is only allowed in a built-up area if the road is narrow (one lane in each direction) and there are no tram tracks in the middle. If these conditions are not met, stopping on the left side is a traffic violation.', 'ticket_media/new/ticketIMG-340.jpg'),
(420, 'ka', 'მოცემულ სიტუაციაში, მოტოციკლის მძღოლი:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 39-ე მუხლის პირველი პუნქტის „დ“ ქვეპუნქტის თანახმად, თუ რკინიგზის გადასასვლელი აღჭურვილი არ არის შლაგბაუმებით, ნახევარშლაგბაუმებით ან მაშუქი სიგნალებით, არცერთმა საგზაო მოძრაობის მონაწილემ არ უნდა გაიაროს მასზე, სანამ არ დარწმუნდება, რომ ხილვადობის ფარგლებში რკინიგზის გადასასვლელს არანაირი რელსიანი სატრანსპორტო საშუალება არ უახლოვდება.', 1, '3', 'ვალდებულია გაჩერდეს საგზაო ნიშანთან', 'ვალდებულია გაჩერდეს უახლოეს რელსამდე არანაკლებ 10 მ-ის მანძილზე', 'უნდა დარწმუნდეს, რომ ხილვადობის ფარგლებში გადასასვლელს არ უახლოვდება მატარებელი და გაიაროს რკინიგზის გადასასველი', NULL, 21, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, როცა შლაგბაუმი ან მაშუქი არ არის, შენი თვალები ყველაზე მნიშვნელოვანი იარაღია. არ იჩქარო! გაჩერდი, დააკვირდი კარგად ორივე მიმართულებით და მხოლოდ მაშინ განაგრძე გზა, როცა დარწმუნდები, რომ მატარებელი არ ჩანს.', 'ticket_media/new/ticketIMG-420.jpg'),
(420, 'ru', 'В данной ситуации водитель мотоцикла:', 'Согласно подпункту «д» пункта 1 статьи 39 Закона Грузии «О дорожном движении», в случае, если железнодорожный переезд не оборудован шлагбаумами, полушлагбаумами или световыми сигналами, ни один участник дорожного движения не должен проезжать его, пока не убедится, что в пределах видимости к переезду не приближается рельсовое транспортное средство.', 1, '3', 'Обязан остановиться у дорожного знака', 'Обязан остановиться на расстоянии не менее 10 метров до ближайшего рельса', 'Должен убедиться, что в пределах видимости к переезду не приближается поезд, и проехать железнодорожный переезд', NULL, 21, '{0,2}'::int[], NULL, 'Привет! Запомни: если на переезде нет шлагбаума или светофора, твои глаза — лучший помощник. Не торопись! Остановись, внимательно посмотри в обе стороны и продолжай движение только тогда, когда будешь полностью уверен, что поезда нет поблизости.', 'ticket_media/new/ticketIMG-420.jpg'),
(420, 'en', 'In this situation, the motorcycle driver:', 'According to Article 39, paragraph 1, subparagraph ''d'' of the Law of Georgia on Road Traffic, if a railway crossing is not equipped with barriers, half-barriers, or light signals, no road user shall cross it until they ensure that no rail vehicle is approaching the crossing within the range of visibility.', 1, '3', 'Is obliged to stop at the road sign', 'Is obliged to stop at a distance of at least 10 meters from the nearest rail', 'Must ensure that no train is approaching the crossing within the range of visibility and proceed through the railway crossing', NULL, 21, '{0,2}'::int[], NULL, 'Hi there! Remember, when there is no gate or light signal at a crossing, your eyes are your best tool. Don''t rush! Stop, look carefully in both directions, and proceed only when you are absolutely sure that no train is approaching.', 'ticket_media/new/ticketIMG-420.jpg'),
(448, 'ka', 'დასახლებულ პუნქტებში, გასაჩერებელი პუნქტიდან გამოსვლისათვის, მოძრაობის განახლების განზრახვის შესახებ მოხვევის მაჩვენებლით მიცემული სიგნალის შემდეგ, სამარშრუტო სატრანსპორტო საშუალების მძღოლები ვალდებულნი არიან:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 41-ე მუხლის პირველი პუნქტის თანახმად, ამ კანონის 33-ე მუხლის მე-4 პუნქტით დადგენილ მოთხოვნათა გათვალისწინებით, დასახლებულ პუნქტში სამარშრუტო სატრანსპორტო საშუალებისთვის მოძრაობის გასაადვილებლად სხვა სატრანსპორტო საშუალებების მძღოლებმა უნდა შეანელონ მოძრაობა და აუცილებლობის შემთხვევაში გაჩერდნენ, რათა სამარშრუტო სატრანსპორტო საშუალებამ შეძლოს გასაჩერებელი პუნქტიდან გამოსვლისთვის საჭირო მანევრის შესრულება. სამარშრუტო სატრანსპორტო საშუალების მძღოლი ვალდებულია მოძრაობის განახლების განზრახვის შესახებ მოხვევის შუქ-მაჩვენებლით სიგნალის მიცემის შემდეგ მიიღოს საგზაო-სატრანსპორტო შემთხვევის თავიდან აცილებისთვის საჭირო სიფრთხილის ზომები და მოძრაობა დაიწყოს მხოლოდ მას შემდეგ, რაც დარწმუნდება, რომ სხვა სატრანსპორტო საშუალებები გზას უთმობენ.', 0, '3', 'ისარგებლონ პრიორიტეტის უფლებით და დაუყოვნებლივ განაახლონ მოძრაობა, მიუხედავად გზაზე არსებული სიტუაციისა', 'ჩართოს ახლო განათების ფარები და შემდეგ დაიწყონ მანევრის შესრულება', 'მიიღონ საგზაო-სატრანსპორტო შემთხვევის თავიდან აცილებისათვის საჭირო სიფრთხილის ზომები და მოძრაობა დაიწყონ მხოლოდ მას შემდეგ, როცა დარწმუნდებიან, რომ სხვა სატრანსპორტო საშუალებები გზას უთმობენ', NULL, 15, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მიუხედავად იმისა, რომ საზოგადოებრივ ტრანსპორტს აქვს უპირატესობა, ეს არ ნიშნავს, რომ მძღოლმა ბრმად უნდა დაიწყოს მოძრაობა. უსაფრთხოება პირველ ადგილზეა! ყოველთვის დარწმუნდი, რომ სხვა მძღოლებმა ნამდვილად შეანელეს სვლა ან გაჩერდნენ, სანამ გზას გააგრძელებ.', NULL),
(448, 'ru', 'В населенных пунктах, для выезда с остановочного пункта, после подачи сигнала указателем поворота о намерении возобновить движение, водители маршрутных транспортных средств обязаны:', 'Согласно пункту 1 статьи 41 Закона Грузии «О дорожном движении», несмотря на то, что другие водители обязаны уступать дорогу маршрутному транспортному средству, сам водитель маршрутного транспортного средства обязан убедиться в безопасности маневра и начать движение только после того, как другие участники движения уступят ему дорогу.', 0, '3', 'Воспользоваться правом приоритета и немедленно возобновить движение, независимо от ситуации на дороге', 'Включить ближний свет фар и затем начать выполнение маневра', 'Принять меры предосторожности, необходимые для предотвращения дорожно-транспортного происшествия, и начать движение только после того, как убедятся, что другие транспортные средства уступают им дорогу', NULL, 15, '{4,6}'::int[], NULL, 'Привет! Помни: даже если у общественного транспорта есть преимущество, это не значит, что водитель может начинать движение, не глядя по сторонам. Безопасность превыше всего! Всегда убеждайся, что другие водители действительно притормозили или остановились, прежде чем выезжать с остановки.', NULL),
(448, 'en', 'In built-up areas, when pulling out from a bus stop, after signaling the intention to resume movement with the turn signal, drivers of route vehicles are required to:', 'In accordance with Article 41, Paragraph 1 of the Law of Georgia ''on Road Traffic'', although other drivers are required to yield to route vehicles, the driver of the route vehicle is obligated to ensure the safety of the maneuver and begin moving only after confirming that other drivers are yielding the right of way.', 0, '3', 'Utilize the right of priority and immediately resume movement, regardless of the situation on the road', 'Switch on the low-beam headlights and then begin the maneuver', 'Take necessary precautionary measures to avoid a traffic accident and begin movement only after ensuring that other vehicles are yielding the right of way', NULL, 15, '{4,6}'::int[], NULL, 'Hello! Remember, even though public transport has priority, this doesn''t mean the driver should move blindly. Safety comes first! Always make sure that other drivers have actually slowed down or stopped before you proceed with your maneuver.', NULL),
(465, 'ka', 'რა თანამიმდევრობით უნდა გაიარონ გზაჯვარედინი სატრანსპორტო საშუალებებმა ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-3 პუნქტის „ა“ და „გ“ ქვეპუნქტის თანახმად, რეგულირებულ გზაჯვარედინზე: ა) შუქნიშნის მწვანე სიგნალის ჩართვის დროს მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის მოძრავი ტრამვაის მძღოლებმაც; გ) თუ შუქნიშნის ან მარეგულირებლის სიგნალები ერთდროულად მოძრაობის ნებას რთავს რელსიან და ურელსო სატრანსპორტო საშუალებებს, რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა, მიუხედავად მისი მოძრაობის მიმართულებისა, მაგრამ შუქნიშნის დამატებით სექციაში ძირითად ყვითელ ან წითელ მაშუქ სიგნალთან ერთად ჩართული ისრის მიმართულებით მოძრაობისას რელსიანი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს სხვა მიმართულებიდან მოძრავ სატრანსპორტო საშუალებას.', 1, '3', 'ჯერ უნდა გაიაროს ტრამვაიმ, შემდეგ - სატვირთო ავტომობილმა, ბოლოს ყვითელმა ავტომობილმა', 'ჯერ უნდა გაიაროს ყვითელმა ავტომობილმა, შემდეგ - სატვირთო ავტომობილმა, ბოლოს - ტრამვაიმ', 'ჯერ უნდა გაიაროს ტრამვაიმ, შემდეგ - ყვითელმა ავტომობილმა, ბოლოს - სატვირთო ავტომობილმა', NULL, 10, '{6,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: ტრამვაის აქვს უპირატესობა, თუ ორივეს მწვანე აინთება. შემდეგ, ყვითელი ავტომობილი სატვირთოს უთმობს გზას, რადგან ის აკეთებს მარცხენა მოხვევას (და საპირისპიროდ მომავალს უთმობს). ამიტომ: ტრამვაი -> ყვითელი -> სატვირთო.', 'ticket_media/new/ticketIMG-465.jpg'),
(465, 'ru', 'В какой последовательности должны проехать перекресток транспортные средства при движении в направлении стрелок?', 'Согласно пункту 3 «г» статьи 36 Закона Грузии «О дорожном движении», трамвай имеет преимущество перед безрельсовыми транспортными средствами, если сигналы светофора разрешают движение одновременно. Трамвай проезжает первым. Что касается желтого и грузового автомобилей, то применяется правило правой руки и обязанность уступить дорогу встречному транспорту при повороте.', 1, '3', 'Сначала трамвай, затем грузовой автомобиль, в конце желтый автомобиль', 'Сначала желтый автомобиль, затем грузовой автомобиль, в конце трамвай', 'Сначала трамвай, затем желтый автомобиль, в конце грузовой автомобиль', NULL, 10, '{6,8}'::int[], NULL, 'Привет! Запомни золотое правило: трамвай имеет преимущество, если светофор разрешает движение обоим. Затем, желтый автомобиль уступает дорогу грузовику, так как совершает поворот налево (и должен пропустить встречный транспорт). Итог: трамвай -> желтый -> грузовик.', 'ticket_media/new/ticketIMG-465.jpg'),
(465, 'en', 'In what order should the vehicles cross the intersection if they move in the direction of the arrows?', 'According to Article 36, Paragraph 3, Subparagraph ''g'' of the Law of Georgia ''On Road Traffic'', the tram has priority over non-rail vehicles when the traffic light allows movement for both simultaneously. The tram goes first. Regarding the yellow car and the truck, the right-hand rule applies, along with the obligation to yield to oncoming traffic when turning.', 1, '3', 'First the tram, then the truck, finally the yellow car', 'First the yellow car, then the truck, finally the tram', 'First the tram, then the yellow car, finally the truck', NULL, 10, '{6,8}'::int[], NULL, 'Hello! Remember the golden rule: the tram has priority if the traffic light gives a green signal to both. Then, the yellow car yields to the truck because it is making a left turn (and must yield to oncoming traffic). Therefore: tram -> yellow car -> truck.', 'ticket_media/new/ticketIMG-465.jpg'),
(467, 'ka', 'რა მიმართულებით შეუძლია მოძრაობა ტრამვაის მძღოლს შუქნიშნების ამ სიგნალებზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-5 პუნქტის თანახმად, სამარშრუტო სატრანსპორტო საშუალებების მოძრაობისათვის სპეციალურად გამოყოფილ ზოლზე მოძრაობის რეგულირებისათვის შეიძლება გამოყენებულ იქნეს „T“-სებურად განლაგებული მოყვითალო ოთხი მრგვალი მაშუქი სიგნალი. მოძრაობა ნებადართულია მხოლოდ მაშინ, როცა ერთდროულად ჩართულია ქვედა და ერთი ან რამდენიმე ზედა მაშუქი სიგნალი, რომელთაგან მარცხენა მარცხნივ მოძრაობის უფლებას იძლევა, საშუალო – პირდაპირ, მარჯვენა კი − მარჯვნივ. თუ ჩართულია მხოლოდ სამი ზედა მაშუქი სიგნალი, მოძრაობა აკრძალულია.', 1, '4', 'მხოლოდ პირდაპირ', 'მხოლოდ მარჯვნივ ან მარცხნივ', 'მხოლოდ პირდაპირ ან მარჯვნივ', 'მოძრაობის გაგრძელების უფლება არა აქვს', 10, '{4,6,8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი წესი: ტრამვაის შუქნიშანზე ქვედა სიგნალი არის „ნებართვა“. თუ ის არ ანთია, რაც არ უნდა ენთოს ზემოთ, ტრამვაი უნდა გაჩერდეს. სამი ზედა სიგნალის ერთად ანთება მოძრაობის აკრძალვას ნიშნავს.', 'ticket_media/new/ticketIMG-467.jpg'),
(467, 'ru', 'В каком направлении разрешено движение водителю трамвая при данных сигналах светофора?', 'Согласно пункту 5 статьи 29 Закона Грузии «О дорожном движении», при использовании Т-образного светофора для трамваев движение разрешается только при одновременном включении нижнего сигнала и одного или нескольких верхних. Если горят только три верхних сигнала (без нижнего), движение запрещено.', 1, '4', 'Только прямо', 'Только направо или налево', 'Только прямо или направо', 'Движение запрещено', 10, '{4,6,8}'::int[], NULL, 'Привет! Запомни простое правило: нижний сигнал на трамвайном светофоре — это «разрешение». Если он не горит, что бы ни горело сверху, трамвай должен стоять. Включение только трех верхних сигналов означает запрет на движение.', 'ticket_media/new/ticketIMG-467.jpg'),
(467, 'en', 'In which direction is the tram driver allowed to proceed given these traffic light signals?', 'According to Article 29, Paragraph 5 of the Law of Georgia on Road Traffic, when using T-shaped traffic signals for trams, movement is permitted only when the bottom signal is lit simultaneously with one or more upper signals. If only the three upper signals are lit, movement is prohibited.', 1, '4', 'Only straight', 'Only right or left', 'Only straight or right', 'Movement is not permitted', 10, '{4,6,8}'::int[], NULL, 'Hello! Remember this simple rule: the bottom signal on a tram traffic light is the "permission" signal. If it is not lit, regardless of what is showing on top, the tram must stop. If only the three upper lights are on, movement is prohibited.', 'ticket_media/new/ticketIMG-467.jpg'),
(474, 'ka', 'მარეგულირებლის ამ სიგნალზე ტრამვაის მძღოლს უფლება აქვს იმოძრაოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 30-ე მუხლის მე-5 პუნქტის „გ“ ქვეპუნქტის თანახმად, მარეგულირებლის სიგნალებს აქვთ შემდეგი მნიშვნელობა, წინ გაშვერილი მარჯვენა ხელი − ეს ჟესტი ნიშნავს „სდექ“ სიგნალს მარეგულირებლის მარჯვენა გვერდისა და ზურგის მხრიდან მოძრავი ყველა მძღოლისათვის; ამასთანავე, მარეგულირებლის მარცხენა გვერდის მხრიდან ტრამვაის უფლება აქვს, იმოძრაოს მარცხნივ, ხოლო ურელსო სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს ყველა მიმართულებით. მარეგულირებლის მკერდის მხრიდან ყველა სატრანსპორტო საშუალებას უფლება აქვს, იმოძრაოს მხოლოდ მარჯვნივ. ქვეითს უფლება აქვს, გადავიდეს სავალ ნაწილზე მარეგუ¬ლირებლის ზურგის უკან.', 1, '1', 'მხოლოდ მარჯვნივ', 'მხოლოდ მარცხნივ', 'ორივე მიმართულებით', NULL, 11, '{8}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი წესი: როცა მარეგულირებლის მკერდის წინ დგახარ და მისი მარჯვენა ხელი წინ არის გაშვერილი, ეს „შლაგბაუმს“ ჰგავს, რომელიც მხოლოდ მარჯვნივ მოხვევის საშუალებას გაძლევს. ეს წესი ვრცელდება როგორც მანქანებზე, ისე ტრამვაიზე.', 'ticket_media/new/ticketIMG-474.jpg'),
(474, 'ru', 'При данном сигнале регулировщика водителю трамвая разрешено движение:', 'Согласно подпункту «г» пункта 5 статьи 30 Закона Грузии «О дорожном движении», когда правая рука регулировщика вытянута вперед, всем транспортным средствам (включая трамвай), приближающимся со стороны груди регулировщика, разрешено движение только направо.', 1, '1', 'Только направо', 'Только налево', 'В обоих направлениях', NULL, 11, '{8}'::int[], NULL, 'Привет! Запомни простое правило: когда ты находишься перед грудью регулировщика, а его правая рука вытянута вперед, это работает как «шлагбаум», который разрешает тебе повернуть только направо. Это правило одинаково действует как для автомобилей, так и для трамваев.', 'ticket_media/new/ticketIMG-474.jpg'),
(474, 'en', 'With this signal from the traffic controller, the tram driver is allowed to move:', 'According to Article 30, Paragraph 5, Subparagraph ''c'' of the Law of Georgia ''on Road Traffic'', when the traffic controller''s right arm is extended forward, all vehicles (including trams) approaching from the chest side of the controller are allowed to move only to the right.', 1, '1', 'Only to the right', 'Only to the left', 'In both directions', NULL, 11, '{8}'::int[], NULL, 'Hello! Remember this simple rule: when you are facing the traffic controller''s chest and their right arm is extended forward, it acts like a ''barrier'' that only allows you to turn right. This rule applies equally to both cars and trams.', 'ticket_media/new/ticketIMG-474.jpg'),
(490, 'ka', 'შუქნიშნის ამ სიგნალზე ტრამვაის მძღოლს უფლება აქვს იმოძრაოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 29-ე მუხლის მე-5 პუნქტის თანახმად, სამარშრუტო სატრანსპორტო საშუალებების მოძრაობისათვის სპეციალურად გამოყოფილ ზოლზე მოძრაობის რეგულირებისათვის შეიძლება გამოყენებულ იქნეს „T“-სებურად განლაგებული მოყვითალო ოთხი მრგვალი მაშუქი სიგნალი. მოძრაობა ნებადართულია მხოლოდ მაშინ, როცა ერთდროულად ჩართულია ქვედა და ერთი ან რამდენიმე ზედა მაშუქი სიგნალი, რომელთაგან მარცხენა მარცხნივ მოძრაობის უფლებას იძლევა, საშუალო – პირდაპირ, მარჯვენა კი − მარჯვნივ. თუ ჩართულია მხოლოდ სამი ზედა მაშუქი სიგნალი, მოძრაობა აკრძალულია.', 1, '3', 'მხოლოდ პირდაპირ', 'მხოლოდ პირდაპირ და მარცხნივ', 'მხოლოდ პირდაპირ და მარჯვნივ', NULL, 10, '{8}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ T-სებური შუქნიშანი ტრამვაისთვის მარტივია: ქვედა სიგნალი არის „ნება“, ხოლო ზედა სიგნალები მიუთითებენ მიმართულებებს. შუა ნათურა პირდაპირ მიდის, მარჯვენა – მარჯვნივ, ხოლო მარცხენა – მარცხნივ. თუ ანთია ქვედა, შუა და მარჯვენა – მიდიხარ პირდაპირ და მარჯვნივ!', 'ticket_media/new/ticketIMG-490.jpg'),
(490, 'ru', 'В каком направлении разрешено движение водителю трамвая при данном сигнале светофора?', 'Согласно пункту 5 статьи 29 Закона Грузии «О дорожном движении», верхние сигналы Т-образного светофора, включенные одновременно с нижним сигналом, определяют направление движения: левый – налево, средний – прямо, правый – направо. Следовательно, если включены нижний, средний и правый верхние сигналы, движение трамвая разрешено прямо и направо.', 1, '3', 'Только прямо', 'Только прямо и налево', 'Только прямо и направо', NULL, 10, '{8}'::int[], NULL, 'Привет! Запомни, Т-образный светофор для трамвая — это просто: нижний сигнал разрешает движение, а верхние указывают направление. Средняя лампочка — прямо, правая — направо, левая — налево. Если горят нижний, средний и правый — значит, можно ехать прямо и направо!', 'ticket_media/new/ticketIMG-490.jpg'),
(490, 'en', 'In which direction is the tram driver allowed to move at this traffic light signal?', 'According to Article 29, Clause 5 of the Law of Georgia ''on Road Traffic'', the upper signals of a T-shaped traffic light, when activated simultaneously with the lower signal, determine the direction of travel: the left signal allows movement to the left, the middle to go straight, and the right to turn right. Therefore, when the bottom signal and the middle and right top signals are illuminated, the tram is permitted to proceed straight and turn right.', 1, '3', 'Straight only', 'Straight and left only', 'Straight and right only', NULL, 10, '{8}'::int[], NULL, 'Hello! Remember, the T-shaped traffic light for trams is simple: the bottom signal gives you the ''green light,'' and the top signals indicate the direction. The middle light is for straight, the right one is for turning right, and the left one is for turning left. If the bottom, middle, and right signals are on, you are allowed to go straight and turn right!', 'ticket_media/new/ticketIMG-490.jpg'),
(491, 'ka', 'დასახლებულ პუნქტში, მონიშნული გაჩერებიდან გამოსვლისთვის მოძრაობის განახლების შესახებ მოხვევის მაჩვენებლით მიცემული სიგნალის შემდეგ სამარშუტო სატრანსპორტო საშუალების მძღოლები ვალდებულნი არიან:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 41-ე მუხლის პირველი პუნქტის თანახმად, ამ კანონის 33-ე მუხლის მე-4 პუნქტით დადგენილ მოთხოვნათა გათვალისწინებით, დასახლებულ პუნქტში სამარშრუტო სატრანსპორტო საშუალებისთვის მოძრაობის გასაადვილებლად სხვა სატრანსპორტო საშუალებების მძღოლებმა უნდა შეანელონ მოძრაობა და აუცილებლობის შემთხვევაში გაჩერდნენ, რათა სამარშრუტო სატრანსპორტო საშუალებამ შეძლოს გასაჩერებელი პუნქტიდან გამოსვლისთვის საჭირო მანევრის შესრულება. სამარშრუტო სატრანსპორტო საშუალების მძღოლი ვალდებულია მოძრაობის განახლების განზრახვის შესახებ მოხვევის შუქ-მაჩვენებლით სიგნალის მიცემის შემდეგ მიიღოს საგზაო-სატრანსპორტო შემთხვევის თავიდან აცილებისთვის საჭირო სიფრთხილის ზომები და მოძრაობა დაიწყოს მხოლოდ მას შემდეგ, რაც დარწმუნდება, რომ სხვა სატრანსპორტო საშუალებები გზას უთმობენ.', 0, '2', 'ისარგებლონ უპირატესობით და დაუყოვნებლივ დაიწყონ მოძრაობა მიუხედავად გზაზე არსებული სიტუაციისა', 'მიიღონ საგზაო-სატრანსპორტო შემთხვევის თავიდან აცილებისთვის საჭირო სიფრთხილის ზომები და მოძრაობა დაიწყონ მხოლოდ მას შემდეგ, როცა დარწმუნდებიან, რომ სხვა სატრანსპორტო საშუალებები გზას უთმობენ', NULL, NULL, 13, '{2,4,6}'::int[], NULL, 'გახსოვდეთ: მიუხედავად იმისა, რომ სხვა მძღოლები ვალდებულნი არიან გზა დაგითმონ, თქვენ, როგორც სამარშრუტო საშუალების მძღოლი, პასუხისმგებელი ხართ უსაფრთხოებაზე. ყოველთვის დარწმუნდით, რომ გზა თავისუფალია და მანევრი უსაფრთხოა, სანამ გაჩერებიდან დაიძვრებით.', NULL),
(491, 'ru', 'В населенном пункте, после подачи сигнала указателем поворота о намерении возобновить движение от обозначенной остановки, водители маршрутных транспортных средств обязаны:', 'Согласно пункту 1 статьи 41 Закона Грузии «О дорожном движении», водитель маршрутного транспортного средства после подачи сигнала обязан принять меры предосторожности для предотвращения ДТП и начать движение только после того, как убедится, что другие участники движения уступают ему дорогу.', 0, '2', 'Воспользоваться преимуществом и немедленно начать движение, независимо от ситуации на дороге', 'Принять необходимые меры предосторожности для предотвращения дорожно-транспортного происшествия и начать движение только после того, как убедятся, что другие транспортные средства уступают им дорогу', NULL, NULL, 13, '{2,4,6}'::int[], NULL, 'Помните: хотя другие водители обязаны уступать вам дорогу, как водитель маршрутного транспорта, вы несете ответственность за безопасность. Всегда убеждайтесь, что путь свободен и маневр безопасен, прежде чем выезжать с остановки.', NULL),
(491, 'en', 'In a built-up area, after signaling with a turn indicator to resume movement from a marked stop, drivers of route vehicles are required to:', 'According to Article 41, Paragraph 1 of the Law of Georgia ''On Road Traffic'', the driver of a route vehicle is obligated to take safety precautions after signaling and may only start moving once they are certain that other vehicles are yielding to them.', 0, '2', 'Utilize the right of way and immediately start moving regardless of the situation on the road', 'Take necessary safety precautions to prevent a traffic accident and start moving only after ensuring that other vehicles are yielding to them', NULL, NULL, 13, '{2,4,6}'::int[], NULL, 'Remember: Even though other drivers are required to yield to you, as a route vehicle driver, you are responsible for overall safety. Always ensure the path is clear and the maneuver is safe before pulling away from the stop.', NULL),
(493, 'ka', 'დღის ნათელ დროს სამარშრუტო სატრანსპორტო საშუალებებზე ახლო განათების ფარებისა და უკანა საგაბარიტო სინათლეების ჩართვა სავალდებულოა:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 49-ე მუხლის მე-8 პუნქტის „ე“ ქვეპუნქტის თანახმად, დღის ნათელ დროს გზაზე მოძრავი სატრანსპორტო საშუალების აღნიშვნის მიზნით სავალდებულოა ახლო განათების ფარებისა და უკანა საგაბარიტო სინათლეების ჩართვა სამარშრუტო სატრანსპორტო საშუალებაზე, სპეციალურად მისთვის გამოყოფილ ზოლზე, ძირითადი ნაკადის საპირისპირო მიმართულებით მოძრაობისას.', 0, '2', 'სპეციალურად მათთვის გამოყოფილ ზოლზე, ძირითადი ნაკადის თანხვედრი მიმართულებით მოძრაობისას', 'სპეციალურად მათთვის გამოყოფილ ზოლზე, ძირითადი ნაკადის საპირისპიროდ მოძრაობისას', 'ნებისმიერ გზაზე, ძირითადი ნაკადის როგორც საპირისპიროდ, ასევე თანმხვედრი მიმართულებით მოძრაობისას', 'ამ ბილეთში ჩამოთვლილ ნებისმიერ შემთხვევაში', 17, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სამარშრუტო ავტობუსი, რომელიც ძირითადი ნაკადის საპირისპიროდ მოძრაობს, განსაკუთრებულ ყურადღებას მოითხოვს. კანონი გვაიძულებს ფარების ჩართვას, რათა სხვა მძღოლებისთვის ეს ტრანსპორტი ადვილად შესამჩნევი იყოს და თავიდან ავიცილოთ ავარიული სიტუაციები.', NULL),
(493, 'ru', 'В светлое время суток включение фар ближнего света и задних габаритных огней на маршрутных транспортных средствах является обязательным:', 'Согласно подпункту «е» пункта 8 статьи 49 Закона Грузии «О дорожном движении», в светлое время суток включение ближнего света и габаритных огней на маршрутных ТС является обязательным исключительно при движении по выделенной полосе навстречу основному потоку для обеспечения своевременного визуального обнаружения транспортного средства другими участниками движения.', 0, '2', 'При движении по специально выделенной для них полосе в попутном направлении с основным потоком', 'При движении по специально выделенной для них полосе во встречном направлении к основному потоку', 'На любой дороге, как во встречном, так и в попутном направлении с основным потоком', 'В любом из перечисленных в этом билете случаев', 17, '{4,6}'::int[], NULL, 'Привет! Запомни: когда маршрутный транспорт едет навстречу общему потоку, он представляет собой дополнительный фактор риска. Поэтому закон требует включать фары, чтобы другие водители могли заметить автобус издалека и правильно среагировать.', NULL),
(493, 'en', 'During daylight hours, is it mandatory to switch on low-beam headlights and rear position lights on route vehicles:', 'According to Article 49, paragraph 8, subparagraph ''e'' of the Law of Georgia ''on Road Traffic'', during daylight hours, it is mandatory to use low-beam headlights and rear position lights on route vehicles only when they are traveling in a dedicated lane opposite to the main traffic flow, in order to ensure they are visible to other drivers.', 0, '2', 'When driving on a lane specially designated for them, moving in the same direction as the main traffic flow', 'When driving on a lane specially designated for them, moving in the opposite direction to the main traffic flow', 'On any road, moving in both the opposite and same direction as the main traffic flow', 'In any of the cases listed in this question', 17, '{4,6}'::int[], NULL, 'Hello! Remember, a route vehicle driving against the main flow of traffic requires extra caution. The law mandates headlights in this situation so other drivers can spot the vehicle quickly and avoid any potential accidents.', NULL),
(517, 'ka', 'მოტოციკლის მძღოლს უფლება აქვს იმოძრაოს არაუმეტეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-6 პუნქტის თანახმად, თუ ამ კანონით სხვა რამ არ არის დადგენილი, დასახლებულ პუნქტში ნებადართულია სატრანსპორტო საშუალების მოძრაობა არა უმეტეს 60 კმ/სთ სიჩქარით, ხოლო საცხოვრებელ ზონაში - არაუმეტეს 20 კმ/სთ სიჩქარით. ამავე კანონის 44-ე მუხლის პირველი პუნქტის „ბ“ ქვეპუნქტის თანახმად, შესაბამისი ნიშნით აღნიშნულ საცხოვრებელ ზონებში, მძღოლი უნდა გადაადგილდეს არაუმეტეს 20კმ/სთ სიჩქარით. ამავე კანონის პირველი დანართის მე-5 თავის (განსაკუთრებული მითითებების ნიშნები) 5.21 პუნქტის თანახმად საგზაო ნიშანი 5.21 „საცხოვრებელი ზონა“ - აღნიშნავს ტერიტორიას (ზონას) სადაც მოქმედებს საცხოვრებელ ზონაში მოძრაობისათვის დადგენილი წესები. ნიშანი იდგმება ასეთი საცხოვრებელი ზონის ყველა შესასვლელში.', 1, '3', '60 კმ/სთ სიჩქარით', '40 კმ/სთ სიჩქარით', '20 კმ/სთ სიჩქარით', NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ საცხოვრებელი ზონა არის ადგილი, სადაც ფეხით მოსიარულეებს პრიორიტეტი აქვთ. უსაფრთხოების მიზნით, კანონი მკაცრად ზღუდავს სიჩქარეს 20 კმ/სთ-მდე. ეს წესი ვრცელდება ყველა ტიპის სატრანსპორტო საშუალებაზე, მათ შორის მოტოციკლზეც.', 'ticket_media/new/ticketIMG-517.jpg'),
(517, 'ru', 'С какой максимальной скоростью разрешено движение водителю мотоцикла в жилой зоне?', 'Согласно пункту 6 статьи 33 и подпункту «б» пункта 1 статьи 44 Закона Грузии «О дорожном движении», в жилой зоне, обозначенной дорожным знаком 5.21 «Жилая зона», движение любого транспортного средства, включая мотоцикл, разрешено со скоростью не более 20 км/ч.', 1, '3', '60 км/ч', '40 км/ч', '20 км/ч', NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что жилая зона — это место, где пешеходы имеют приоритет. В целях безопасности закон строго ограничивает скорость до 20 км/ч. Это правило распространяется на все виды транспортных средств, включая мотоциклы.', 'ticket_media/new/ticketIMG-517.jpg'),
(517, 'en', 'What is the maximum speed a motorcycle driver is allowed to travel in a residential zone?', 'According to Article 33, Paragraph 6, and Article 44, Paragraph 1, Subparagraph ''b'' of the Law of Georgia ''on Road Traffic'', within a residential zone marked by road sign 5.21 ''Residential Zone'', the movement of any vehicle, including motorcycles, is permitted at a speed not exceeding 20 km/h.', 1, '3', '60 km/h', '40 km/h', '20 km/h', NULL, 14, '{2}'::int[], NULL, 'Hello! Remember that a residential zone is an area where pedestrians have priority. For safety reasons, the law strictly limits speed to 20 km/h. This rule applies to all types of vehicles, including motorcycles.', 'ticket_media/new/ticketIMG-517.jpg'),
(529, 'ka', 'აკრძალულია მოტოციკლით იმ ტვირთის გადაზიდვა, რომელიც გადმოშვერილია სიგანეზე ან სიგრძეზე გაბარიტებს გარეთ:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 43-ე მუხლის მე-7 პუნქტის თანახმად, ველოსიპედის, მოპედისა და ორბორბლიანი ელექტროთვითმგორავის მძღოლებს ეკრძალებათ გადაადგილება, თუ საჭე ერთი ხელით მაინც არ უჭირავთ. აკრძალულია ველოსიპედის, მოპედისა და ორბორბლიანი ელექტროთვითმგორავის ბუქსირება, ან აღნიშნული ტრანსპორტით სხვა სატრანსპორტო საშუალების ბუქსირება (გარდა ამ მუხლის მე-8 პუნქტით გათვალისწინებული შემთხვევებისა), ან იმ ტვირთის გადაზიდვა, რომელიც გაბარიტების გარეთ სიგანეზე ან სიგრძეზე 0,5 მეტრზე მეტადაა გადმოშვერილი, ან ისეთი საგნის გადატანა/მიწოლა, რომელსაც შეუძლია მძღოლს ხელი შეუშალოს მართვაში ან საფრთხე შეუქმნას სხვა საგზაო მოძრაობის მონაწილეს. ეს წესი გამოიყენება მოტოციკლის მძღოლის მიმართ, მაგრამ, ამასთანავე, მას ორივე ხელით უნდა ეჭიროს საჭე, გარდა იმ შემთხვევისა, როცა აუცილებელია, ხელით მისცეს ამ კანონით განსაზღვრული მანევრის შესრულებასთან დაკავშირებული სიგნალები.', 0, '1', '0,5 მეტრზე მეტად', 'არანაკლებ 0,7 მეტრით', 'არანაკლებ 1,0 მეტრით', NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოციკლის სტაბილურობა ძალიან მნიშვნელოვანია. კანონი ზღუდავს ტვირთის გაბარიტებს, რათა მძღოლმა არ დაკარგოს ბალანსი. თუ ტვირთი 0,5 მეტრზე მეტად არის გადმოშვერილი, ეს საფრთხეს უქმნის როგორც შენ, ისე სხვა მძღოლებს.', NULL),
(529, 'ru', 'Запрещается перевозить на мотоцикле груз, который выступает за габариты по ширине или длине более чем на:', 'Согласно пункту 7 статьи 43 Закона Грузии «О дорожном движении», водителю мотоцикла запрещается перевозить груз, который выступает за габариты по ширине или длине более чем на 0,5 метра.', 0, '1', 'Более 0,5 метра', 'Не менее 0,7 метра', 'Не менее 1,0 метра', NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что устойчивость мотоцикла — это главное. Закон ограничивает габариты груза, чтобы ты не потерял равновесие. Если груз выступает более чем на 0,5 метра, это создает опасность как для тебя, так и для других участников дорожного движения.', NULL),
(529, 'en', 'It is forbidden to transport cargo on a motorcycle that protrudes beyond the dimensions in width or length by more than:', 'According to Article 43, Paragraph 7 of the Law of Georgia ''On Road Traffic'', it is prohibited for a motorcycle driver to transport cargo that protrudes beyond the dimensions in width or length by more than 0.5 meters.', 0, '1', 'More than 0.5 meters', 'Not less than 0.7 meters', 'Not less than 1.0 meters', NULL, 14, '{2}'::int[], NULL, 'Hello! Remember, motorcycle stability is key. The law limits cargo dimensions so you don''t lose your balance while riding. If cargo protrudes by more than 0.5 meters, it puts both you and other road users at risk.', NULL),
(530, 'ka', 'გარდა შემთხვევებისა, როცა აუცილებელია ხელით მისცენ მანევრის შესრულებასთან დაკავშირებული სიგნალები, მოტოციკლის მძღოლებს ეკრძალებათ გადაადგილება, თუ:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 43-ე მუხლის მე-7 პუნქტის თანახმად, ველოსიპედის, მოპედისა და ორბორბლიანი ელექტროთვითმგორავის მძღოლებს ეკრძალებათ გადაადგილება, თუ საჭე ერთი ხელით მაინც არ უჭირავთ. აკრძალულია ველოსიპედის, მოპედისა და ორბორბლიანი ელექტროთვითმგორავის ბუქსირება, ან აღნიშნული ტრანსპორტით სხვა სატრანსპორტო საშუალების ბუქსირება (გარდა ამ მუხლის მე-8 პუნქტით გათვალისწინებული შემთხვევებისა), ან იმ ტვირთის გადაზიდვა, რომელიც გაბარიტების გარეთ სიგანეზე ან სიგრძეზე 0,5 მეტრზე მეტადაა გადმოშვერილი, ან ისეთი საგნის გადატანა/მიწოლა, რომელსაც შეუძლია მძღოლს ხელი შეუშალოს მართვაში ან საფრთხე შეუქმნას სხვა საგზაო მოძრაობის მონაწილეს. ეს წესი გამოიყენება მოტოციკლის მძღოლის მიმართ, მაგრამ, ამასთანავე, მას ორივე ხელით უნდა ეჭიროს საჭე, გარდა იმ შემთხვევისა, როცა აუცილებელია, ხელით მისცეს ამ კანონით განსაზღვრული მანევრის შესრულებასთან დაკავშირებული სიგნალები.', 0, '1', 'საჭე ორივე ხელით არ უჭირავთ', 'საჭე ერთი ხელით მაინც არ უჭირავთ', NULL, NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოტოციკლის მართვისას უსაფრთხოება უმთავრესია. კანონი ავალდებულებს მოტოციკლის მძღოლს, საჭე მუდმივად ორივე ხელით მართოს, რათა მყარად აკონტროლოს მოტოციკლი. ხელის გაშვება მხოლოდ მანევრის (მაგალითად, მოხვევის) მანიშნებელი სიგნალის მისაცემად არის ნებადართული.', NULL),
(530, 'ru', 'За исключением случаев, когда необходимо подать сигналы рукой о выполнении маневра, водителям мотоциклов запрещается движение, если:', 'Согласно пункту 7 статьи 43 Закона Грузии «О дорожном движении», водителю мотоцикла запрещается движение, если он не держит руль обеими руками, за исключением случаев, когда необходимо подать предусмотренный законом сигнал рукой при выполнении маневра.', 0, '1', 'Они не держат руль обеими руками', 'Они не держат руль хотя бы одной рукой', NULL, NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что при управлении мотоциклом безопасность — превыше всего. Закон обязывает водителя мотоцикла постоянно держать руль обеими руками для обеспечения полного контроля над транспортным средством. Отпускать руль разрешается только для подачи сигналов рукой при выполнении маневров, например, при повороте.', NULL),
(530, 'en', 'Except for cases when it is necessary to give hand signals related to performing a maneuver, motorcycle drivers are prohibited from moving if:', 'According to Article 43, Paragraph 7 of the Law of Georgia ''On Road Traffic'', a motorcycle driver is prohibited from moving unless they are holding the handlebar with both hands, except when it is necessary to provide a hand signal for a maneuver as defined by law.', 0, '1', 'They are not holding the handlebar with both hands', 'They are not holding the handlebar with at least one hand', NULL, NULL, 14, '{2}'::int[], NULL, 'Hello! Remember, safety is the top priority when riding a motorcycle. The law requires motorcycle riders to keep both hands on the handlebars at all times to maintain steady control of the bike. You are only allowed to take one hand off to provide a legal hand signal for a maneuver, such as turning.', NULL),
(531, 'ka', 'დასაშვებია თუ არა უეტლო მოტოციკლით მისაბმელის ბუქსირება?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 43-ე მუხლის მე-8 პუნქტის თანახმად, დასაშვებია ველოსიპედით, მოპედით, ორბორბლიანი ელექტროთვითმგორავითა და უეტლო მოტოციკლით იმ მისაბმელის ბუქსირება, რომელიც განკუთვნილია აღნიშნულ ტრანსპორტთან ერთად ექსპლუატაციისათვის.', 0, '3', 'დასაშვებია, ყველა იმ მისაბმელის ბუქსირება, რომლის ნებადართული მაქსიმალური მასა 750 კგ-ზე ნაკლებია', 'არ არის დაშვებული', 'დასაშვებია, მხოლოდ იმ მისაბმელის ბუქსირება, რომელიც განკუთვნილია აღნიშნულ ტრანსპორტთან ერთად ექსპლუატაციისათვის', NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოციკლით ყველაფრის ბუქსირება არ შეიძლება. კანონი მკაცრია: მისაბმელი აუცილებლად უნდა იყოს ქარხნულად გათვლილი შენი მოტოციკლისთვის. ეს უსაფრთხოების საკითხია, რათა სამუხრუჭე და სამართავი სისტემები გამართულად მუშაობდეს.', NULL),
(531, 'ru', 'Разрешается ли буксировка прицепа мотоциклом без коляски?', 'Согласно пункту 8 статьи 43 Закона Грузии «О дорожном движении», буксировка прицепа мотоциклом без коляски допускается только в том случае, если прицеп специально спроектирован и предназначен для эксплуатации с данным типом транспортного средства.', 0, '3', 'Разрешается буксировка любого прицепа с разрешенной максимальной массой менее 750 кг', 'Не разрешается', 'Разрешается только буксировка прицепа, предназначенного для эксплуатации с данным транспортным средством', NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что мотоцикл — это не грузовик. Закон четко гласит: ты можешь тянуть прицеп, только если он специально разработан производителем для работы именно с твоим типом мотоцикла. Это нужно для твоей безопасности, чтобы тормоза и управление оставались эффективными.', NULL),
(531, 'en', 'Is it permitted to tow a trailer with a motorcycle without a sidecar?', 'According to Article 43, paragraph 8 of the Law of Georgia ''On Road Traffic'', towing a trailer with a motorcycle without a sidecar is permitted only if the trailer is specifically designed and intended for operation with that particular type of vehicle.', 0, '3', 'Permitted for any trailer with a maximum authorized mass of less than 750 kg', 'Not permitted', 'Permitted only if the trailer is designed for use with the specified vehicle', NULL, 14, '{2}'::int[], NULL, 'Hello! Remember, a motorcycle isn''t a truck. The law is clear: you can only tow a trailer if it is specifically engineered by the manufacturer to be used with your specific type of motorcycle. This is a safety requirement to ensure that your braking and handling systems remain reliable.', NULL),
(532, 'ka', 'სავალდებულოა თუ არა მოტოციკლეტისა და მოპედის მძღოლებისათვის, აგრეთვე მათი მგზავრებისთვის გადაადგილებისას მოტოჩაფხუტის გამოყენება?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 43-ე მუხლის მე-10 პუნქტის თანახმად, გადაადგილებისას მოტოციკლისა და მოპედის მძღოლებმა, აგრეთვე მათმა მგზავრებმა მოტოჩაფხუტები უნდა გამოიყენონ.', 0, '1', 'სავალდებულოა', 'არ არის სავალდებულო', NULL, NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! მოტოციკლეტზე ან მოპედზე ჯდომისას უსაფრთხოება ყველაზე მნიშვნელოვანია. კანონი ცალსახაა: როგორც მძღოლი, ისე მგზავრი აუცილებლად უნდა ატარებდნენ ჩაფხუტს, რათა თავი დაიცვან შესაძლო დაზიანებებისგან. ეს თქვენი სიცოცხლისთვისაა საჭირო!', NULL),
(532, 'ru', 'Обязательно ли использование мотошлема при движении для водителей мотоциклов и мопедов, а также для их пассажиров?', 'Согласно пункту 10 статьи 43 Закона Грузии «О дорожном движении», водители мотоциклов и мопедов, а также их пассажиры обязаны использовать мотошлемы во время движения.', 0, '1', 'Обязательно', 'Не является обязательным', NULL, NULL, 14, '{2}'::int[], NULL, 'Привет! Безопасность при езде на мотоцикле или мопеде превыше всего. Закон однозначен: как водитель, так и пассажир обязаны быть в шлемах, чтобы защитить голову от возможных травм. Это необходимо для вашей собственной безопасности!', NULL),
(532, 'en', 'Is it mandatory for motorcycle and moped drivers, as well as their passengers, to use a motorcycle helmet while moving?', 'According to Article 43, Paragraph 10 of the Law of Georgia ''On Road Traffic'', drivers of motorcycles and mopeds, as well as their passengers, are required to use motorcycle helmets while in motion.', 0, '1', 'Mandatory', 'Not mandatory', NULL, NULL, 14, '{2}'::int[], NULL, 'Hello! Safety comes first when riding a motorcycle or moped. The law is clear: both the driver and the passenger must wear helmets to protect themselves from potential injuries. It is essential for your own safety!', NULL),
(538, 'ka', 'აქვთ თუ არა უფლება ველოსიპედისა და მოპედის მძღოლებს, საკმარისი ადგილის არსებობისას შემოუარონ გაჩერებულ ან ნელა მოძრავ სატრანსპორტო საშუალებებს მარჯვენა მხრიდან?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 34-ე მუხლის მე-2 პუნქტის თანახმად, საკმარისი ადგილის არსებობისას ველოსიპედისტსა და მოპედის მძღოლს შეუძლიათ გაჩერებულ ან დაბალი სიჩქარით მოძრავ სატრანსპორტო საშუალებებს მარჯვენა მხრიდან შემოუარონ.', 0, '1', 'აქვთ უფლება', 'არ აქვთ უფლება', NULL, NULL, 14, '{2,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ველოსიპედები და მოპედები გაცილებით კომპაქტურები არიან. კანონი მათ უფლებას აძლევს, საცობებში ან ნელა მოძრავი მანქანების გვერდით, მარჯვენა მხრიდან გაძვრნენ, თუ ამისთვის საკმარისი ადგილია. ეს მათ ეხმარება, არ შეფერხდნენ და მოძრაობა უფრო სწრაფი გახდეს.', NULL),
(538, 'ru', 'Имеют ли право водители велосипедов и мопедов при наличии достаточного места объезжать стоящие или медленно движущиеся транспортные средства с правой стороны?', 'Согласно пункту 2 статьи 34 Закона Грузии «О дорожном движении», при наличии достаточного пространства на дороге водителям велосипедов и мопедов разрешается совершать объезд стоящих или движущихся с низкой скоростью транспортных средств с правой стороны, что способствует повышению эффективности движения.', 0, '1', 'Имеют право', 'Не имеют права', NULL, NULL, 14, '{2,6,7}'::int[], NULL, 'Привет! Помни, что велосипеды и мопеды гораздо компактнее автомобилей. Закон разрешает им проезжать справа от стоящих или медленно едущих машин, если места достаточно. Это помогает им не застревать в пробках и делает движение более динамичным.', NULL),
(538, 'en', 'Do bicycle and moped drivers have the right to pass stopped or slow-moving vehicles on the right side if there is sufficient space?', 'According to Article 34, Paragraph 2 of the Law of Georgia on Road Traffic, if there is sufficient space on the road, bicycle and moped drivers are permitted to pass stopped or slow-moving vehicles on the right side, which serves to improve traffic flow efficiency.', 0, '1', 'They have the right', 'They do not have the right', NULL, NULL, 14, '{2,6,7}'::int[], NULL, 'Hello! Remember, bicycles and mopeds are much more compact than cars. The law allows them to pass stopped or slow-moving vehicles on the right side as long as there is enough space. This helps them avoid getting stuck in traffic and keeps the flow of movement efficient.', NULL),
(627, 'ka', 'მოცემული საგზაო ნიშნებიდან, რომელი აღნიშნავს გზის მონაკვეთს სახიფათო მოსახვევებით?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის პირველი თავის (მაფრთხილებელი ნიშნები) 1.13.1 და 1.13.2 პუნქტების თანახმად საგზაო ნიშნები 1.13.1, 1.13.2 „სახიფათო მოსახვევები” - აღნიშნავს გზის მონაკვეთს სახიფათო მოსახვევებით: 1.13.1 – პირველი მოსახვევით მარჯვნივ, 1.13.2 – პირველი მოსახვევით მარცხნივ.', 1, '3', 'IV', 'III', 'II', 'I', 23, '{0,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ეს ნიშანი გაფრთხილებს მოახლოებულ სახიფათო მოსახვევებზე. ისრის მიმართულება გიჩვენებს, თუ საითაა პირველი მოსახვევი. ნიშანი II (1.13.2) ნიშნავს, რომ წინ გზა გრაგნილია და პირველი მოსახვევი მარცხნივ იქნება, ამიტომ სიჩქარე უნდა შეამცირო.', 'ticket_media/new/ticketIMG-627.jpg'),
(627, 'ru', 'Какой из представленных дорожных знаков обозначает участок дороги с опасными поворотами?', 'Согласно пунктам 1.13.1 и 1.13.2 главы 1 Приложения №1 Закона Грузии «О дорожном движении», дорожные знаки 1.13 обозначают участок дороги с опасными поворотами. Знак 1.13.2 указывает на серию опасных поворотов, где первый поворот направлен влево, что соответствует категории предупреждающих знаков для обеспечения безопасности движения.', 1, '3', 'IV', 'III', 'II', 'I', 23, '{0,6,7}'::int[], NULL, 'Привет! Запомни, этот знак предупреждает тебя об опасных поворотах впереди. Направление стрелки показывает, куда идет первый поворот. Знак II (1.13.2) означает, что впереди извилистая дорога с первым поворотом влево, поэтому будь внимателен и заранее снизь скорость.', 'ticket_media/new/ticketIMG-627.jpg'),
(627, 'en', 'From the given road signs, which one indicates a road section with dangerous curves?', 'According to paragraphs 1.13.1 and 1.13.2 of Chapter 1 of Annex 1 to the Law of Georgia ''on Road Traffic'', road sign 1.13 indicates a road section with dangerous curves. Specifically, sign 1.13.2 denotes dangerous curves with the first curve to the left, falling under the category of warning signs.', 1, '3', 'IV', 'III', 'II', 'I', 23, '{0,6,7}'::int[], NULL, 'Hello! Remember, this sign warns you about dangerous curves ahead. The direction of the arrow indicates where the first turn is. Sign II (1.13.2) means the road ahead is winding and the first curve is to the left, so make sure to slow down in advance!', 'ticket_media/new/ticketIMG-627.jpg'),
(637, 'ka', 'მოცემული საგზაო ნიშნებიდან რომელი აღნიშნავს გზის მონაკვეთს, რომლის სავალი ნაწილის სიგანე ვიწროვდება მარცხენა მხრიდან?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის პირველი თავის (მაფრთხილებელი ნიშნები) 1.21.1-1.21.3 პუნქტების თანახმად საგზაო ნიშნები 1.21.1–1.21.3 „გზის შევიწროება” - აღნიშნავს გზის მონაკვეთს, რომლის სავალი ნაწილის სიგანე ვიწროვდება. 1.21.1 - ორივე მხრიდან; 1.21.2 - მარჯვნიდან; 1.21.3 - მარცხნიდან.', 1, '2', 'I', 'II', 'III', 'IV', 23, '{0,2,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს: ამ ნიშნების ამოცნობა ძალიან მარტივია – უბრალოდ შეხედე ნიშნის შავ ხაზს. თუ ხაზი მარცხნივ იხრება, ეს ნიშნავს, რომ გზა მარცხნიდან ვიწროვდება. ამიტომ სწორი პასუხია II (ნიშანი 1.21.3).', 'ticket_media/new/ticketIMG-637.jpg'),
(637, 'ru', 'Какой из представленных дорожных знаков обозначает участок дороги, где проезжая часть сужается с левой стороны?', 'Согласно Приложению №1 к Закону Грузии «О дорожном движении», дорожный знак 1.21.3 предназначен для обозначения участка дороги, где проезжая часть сужается с левой стороны.', 1, '2', 'I', 'II', 'III', 'IV', 23, '{0,2,6,7}'::int[], NULL, 'Привет! Запомнить эти знаки легко: просто посмотри на наклон черной линии на знаке. Если линия сужается с левой стороны, значит дорога сужается слева. Поэтому правильный ответ — II (знак 1.21.3).', 'ticket_media/new/ticketIMG-637.jpg'),
(637, 'en', 'Which of the given road signs indicates a road section where the width of the carriageway narrows from the left side?', 'According to Annex 1 of the Law of Georgia ''On Road Traffic'', road sign 1.21.3 is intended to indicate a section of the road where the carriageway narrows from the left side.', 1, '2', 'I', 'II', 'III', 'IV', 23, '{0,2,6,7}'::int[], NULL, 'Hello! Remember: identifying these signs is simple—just look at the black line. If the line slants from the left, it means the road is narrowing from the left side. Therefore, the correct answer is II (sign 1.21.3).', 'ticket_media/new/ticketIMG-637.jpg'),
(693, 'ka', 'მოცემული საგზაო ნიშანი:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის მე-3 თავის (ამკრძალავი ნიშნები) 3.11 პუნქტის თანახმად საგზაო ნიშანი 3.11 „მასის შეზღუდვა” - კრძალავს იმ სატრანსპორტო საშუალებით და სატრანსპორტო საშუალებათა შემადგენლობით მოძრაობას, რომელთა საერთო ფაქტობრივი მასა აღემატება ნიშანზე აღნიშნულს.', 1, '2', 'კრძალავს სატრანსპორტო საშუალებების მოძრაობას, ნიშანზე აღნიშნულზე ნაკლები დისტანციით', 'კრძალავს იმ სატრანსპორტო საშუალებებით, აგრეთვე იმ სატრანსპორტო საშუალებათა შემადგენლობით მოძრაობას, რომლის საერთო ფაქტობრივი მასა აღემატება ნიშანზე მითითებულს', 'კრძალავს იმ სატრანსპორტო საშუალებით მოძრაობას, რომლის ფაქტობრივი დატვირთვა რომელიმე ღერძზე აღემატება ნიშანზე აღნიშნულს', NULL, 25, '{6,7}'::int[], NULL, 'გამარჯობა! ეს ნიშანი გვეუბნება, რომ გზის ამ მონაკვეთზე შესვლა არ შეუძლიათ მანქანებს (ან მისაბმელიან შემადგენლობებს), რომელთა წონა ტვირთიანად აღემატება ნიშანზე მითითებულ ტონაჟს. დაიმახსოვრე, აქ იგულისხმება არა მაქსიმალური დასაშვები, არამედ იმ მომენტისთვის ფაქტობრივი წონა.', 'ticket_media/new/ticketIMG-693.jpg'),
(693, 'ru', 'Данный дорожный знак:', 'Согласно пункту 3.11 главы 3 Приложения №1 Закона Грузии «О дорожном движении», дорожный знак 3.11 «Ограничение массы» запрещает движение транспортных средств и составов транспортных средств, общая фактическая масса которых превышает значение, указанное на знаке.', 1, '2', 'Запрещает движение транспортных средств с дистанцией меньше указанной на знаке', 'Запрещает движение транспортных средств, а также составов транспортных средств, фактическая масса которых превышает указанную на знаке', 'Запрещает движение транспортных средств, фактическая нагрузка на ось которых превышает указанную на знаке', NULL, 25, '{6,7}'::int[], NULL, 'Привет! Этот знак означает, что на данном участке дороги запрещено движение тем транспортным средствам (и их составам), чья фактическая масса в данный момент превышает указанную цифру. Помни, что речь идет именно о фактическом весе автомобиля с грузом, а не о максимально допустимом по паспорту.', 'ticket_media/new/ticketIMG-693.jpg'),
(693, 'en', 'The given road sign:', 'According to Article 3, point 3.11 of Annex 1 of the Law of Georgia ''On Road Traffic'', road sign 3.11 ''Mass limit'' prohibits the movement of vehicles and vehicle combinations whose total actual mass exceeds the value indicated on the sign.', 1, '2', 'Prohibits the movement of vehicles with a distance less than specified on the sign', 'Prohibits the movement of vehicles, as well as combinations of vehicles, whose total actual mass exceeds that indicated on the sign', 'Prohibits the movement of vehicles whose actual load on any axle exceeds that indicated on the sign', NULL, 25, '{6,7}'::int[], NULL, 'Hello! This sign means that vehicles (and vehicle combinations) exceeding the weight shown on the sign are not allowed on this road section. Remember, we are talking about the actual weight at the moment (including cargo), not the maximum technically permissible weight.', 'ticket_media/new/ticketIMG-693.jpg'),
(705, 'ka', 'მოცემული საგზაო ნიშანი კრძალავს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის მე-3 თავის (ამკრძალავი ნიშნები) 3.16 პუნქტის თანახმად საგზაო ნიშანი 3.16 „მინიმალური დისტანციის შეზღუდვა” - კრძალავს სატრანსპორტო საშუალებებით მოძრაობას ნიშანზე აღნიშნულ მანძილზე ნაკლები დისტანციით.', 1, '2', 'მსუბუქი ავტომობილების მოძრაობას 70 კმ/სთ-ზე მეტი სიჩქარით', 'სატრანსპორტო საშუალებებით მოძრაობას ნიშანზე აღნიშნულზე ნაკლები დისტანციით', 'ერთ რიგში მსუბუქი ავტომობილების მოძრაობას', NULL, 25, '{6,7}'::int[], NULL, 'ეს ნიშანი გვეუბნება, რომ წინ მიმავალ ავტომობილს ზედმეტად არ უნდა მივუახლოვდეთ. მაგალითად, თუ ნიშანზე წერია 70 მ, ეს ნიშნავს, რომ თქვენსა და წინ მიმავალ მანქანას შორის მანძილი უნდა იყოს მინიმუმ 70 მეტრი. ეს უსაფრთხოების ზომაა, რათა დაგიტოვოთ რეაგირების დრო დამუხრუჭებისას.', 'ticket_media/new/ticketIMG-705.jpg'),
(705, 'ru', 'Что запрещает данный дорожный знак?', 'Согласно пункту 3.16 главы 3 (Запрещающие знаки) Приложения №1 Закона Грузии «О дорожном движении», дорожный знак 3.16 «Ограничение минимальной дистанции» запрещает движение транспортных средств с дистанцией между ними меньше, чем указано на знаке.', 1, '2', 'Движение легковых автомобилей со скоростью более 70 км/ч', 'Движение транспортных средств с дистанцией меньше указанной на знаке', 'Движение легковых автомобилей в один ряд', NULL, 25, '{6,7}'::int[], NULL, 'Этот знак означает, что вы должны держать дистанцию до впереди идущего автомобиля не менее той, что указана на знаке. Например, если на знаке написано «70 м», это значит, что между вами и машиной впереди должно быть как минимум 70 метров. Это нужно для того, чтобы у вас было достаточно времени на торможение в экстренной ситуации.', 'ticket_media/new/ticketIMG-705.jpg'),
(705, 'en', 'What does this road sign prohibit?', 'According to Article 3, point 3.16 (Prohibitory signs) of Annex 1 to the Law of Georgia ''on Road Traffic'', road sign 3.16 ''Minimum distance restriction'' prohibits the movement of vehicles with a distance between them that is less than the distance indicated on the sign.', 1, '2', 'Movement of passenger cars at a speed of more than 70 km/h', 'Movement of vehicles with a distance less than indicated on the sign', 'Movement of passenger cars in a single file', NULL, 25, '{6,7}'::int[], NULL, 'This sign tells you that you must keep a safety gap between your vehicle and the one in front of you, specifically no less than the distance shown on the sign. For example, if it says 70m, you must stay at least 70 meters away from the vehicle ahead. It''s a vital safety rule to ensure you have enough time to stop if the car in front brakes suddenly.', 'ticket_media/new/ticketIMG-705.jpg'),
(719, 'ka', 'მოცემული საგზაო ნიშანი კრძალავს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის მე-3 თავის (ამკრძალავი ნიშნები) 3.20 პუნქტის თანახმად საგზაო ნიშანი 3.20 „გასწრება აკრძალულია” - კრძალავს ყველა სახის მექანიკური სატრან¬სპორ¬ტო საშუალების გასწრებას (გარდა 30 კმ/სთ-ზე ნაკლები სიჩქარით მოძრავი ტრანსპორტისა). ნებადართულია გასწრება უეტლო მოტოციკლის, მოპედისა და ველოსიპედის შემხვედრი მოძრაობის ზოლში გადაუსვლელად.', 1, '3', 'ნებისმიერი სახის სატრანსპორტო საშუალების გასწრებას, მიუხედავად მისი სიჩქარისა', 'მსუბუქი ავტომობილისაგან განსხვავებული სხვა სატრანსპორტო საშუალებით მოძრაობას', 'კრძალავს ნებისმიერი სახის მექანიკური სატრანსპორტო საშუალების გასწრებას (გარდა 30 კმ/სთ-ზე ნაკლები სიჩქარით მოძრავი ტრანსპორტისა)', NULL, 25, '{2,6,7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, ეს ნიშანი ზოგადად კრძალავს გასწრებას, მაგრამ კანონი გვიტოვებს გამონაკლისს: თუ შენს წინ მიმავალი მექანიკური ტრანსპორტი ძალიან ნელა, 30 კმ/სთ-ზე ნაკლები სიჩქარით მოძრაობს, მისი გასწრება ნებადართულია. ეს იმიტომ, რომ ნელი სატრანსპორტო საშუალებები მოძრაობის შეფერხებას იწვევენ.', 'ticket_media/new/ticketIMG-719.jpg'),
(719, 'ru', 'Данный дорожный знак запрещает:', 'Согласно пункту 3.20 Приложения №1 Закона Грузии «О дорожном движении», данный знак запрещает обгон всех видов механических транспортных средств, за исключением случаев, когда транспортное средство движется со скоростью менее 30 км/ч.', 1, '3', 'Обгон любых видов транспортных средств, независимо от их скорости', 'Движение на транспортных средствах, отличных от легковых автомобилей', 'Обгон любых видов механических транспортных средств (кроме транспортных средств, движущихся со скоростью менее 30 км/ч)', NULL, 25, '{2,6,7}'::int[], NULL, 'Привет! Запомни: этот знак запрещает обгон, но закон делает важное исключение. Если транспортное средство перед тобой едет очень медленно (менее 30 км/ч), ты имеешь право его обогнать. Это правило помогает избежать заторов, создаваемых тихоходной техникой.', 'ticket_media/new/ticketIMG-719.jpg'),
(719, 'en', 'This road sign prohibits:', 'According to Article 3.20 of the first annex of the Georgian Law on Road Traffic, this sign prohibits the overtaking of all types of motorized vehicles, except for cases where the vehicle ahead is traveling at a speed of less than 30 km/h.', 1, '3', 'Overtaking any type of vehicle, regardless of its speed', 'Driving any vehicle other than a passenger car', 'Overtaking any type of motorized vehicle (except for vehicles moving at a speed of less than 30 km/h)', NULL, 25, '{2,6,7}'::int[], NULL, 'Hello! Remember, this sign generally prohibits overtaking, but the law provides an important exception: if the motorized vehicle in front of you is traveling very slowly (less than 30 km/h), you are allowed to overtake it. This is to ensure that slow-moving vehicles do not cause unnecessary traffic congestion.', 'ticket_media/new/ticketIMG-719.jpg'),
(807, 'ka', 'გზაზე საჭაპანო ტრანსპორტის მართვა უნდა განხორციელდეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 22-ე მუხლის მე-2 პუნქტის თანახმად, გზაზე მოძრავი პირუტყვის, აგრეთვე საჭაპანო ტრანსპორტის მართვა უნდა განხორციელდეს სავალი ნაწილის კიდესთან ყველაზე ახლო მანძილზე ან გვერდულაზე (თუ ეს არ აბრკოლებს ქვეითს) ერთრიგად, მოძრაობის მიმართულებით.', 0, '1', 'სავალი ნაწილის კიდესთან, ყველაზე ახლო მანძილზე ან გვერდულაზე (თუ ეს არ აბრკოლებს ქვეითს) ერთრიგად, მოძრაობის მიმართულების შესაბამისად', 'სავალ ნაწილზე მოძრაობის მიმართულების საპირისპიროდ', 'მეხრეს სურვილისამებრ გზის ნებისმიერ მონაკვეთზე', NULL, 3, '{2,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ცხენიანი ურემი თუ სხვა საჭაპანო ტრანსპორტი ისეთივე მონაწილეა მოძრაობისა, როგორც ავტომობილი. უსაფრთხოებისთვის ისინი უნდა მიუახლოვდნენ გზის კიდეს, რათა ავტომობილებს თავისუფლად გავლის საშუალება მისცენ.', NULL),
(807, 'ru', 'Как должно осуществляться управление гужевым транспортом на дороге?', 'Согласно пункту 2 статьи 22 Закона Грузии «О дорожном движении», управление гужевым транспортом должно осуществляться как можно ближе к краю проезжей части или по обочине (если это не создает препятствий для пешеходов) в один ряд, в попутном направлении для обеспечения безопасности дорожного движения.', 0, '1', 'Как можно ближе к краю проезжей части или по обочине (если это не создает помех пешеходам) в один ряд, по направлению движения', 'По проезжей части во встречном направлении', 'По усмотрению возничего на любом участке дороги', NULL, 3, '{2,6,7}'::int[], NULL, 'Привет! Помни, что гужевой транспорт — это полноценный участник дорожного движения. Чтобы не создавать аварийных ситуаций, важно держаться правого края дороги или обочины, не мешая при этом пешеходам.', NULL),
(807, 'en', 'How should animal-drawn transport be operated on the road?', 'According to Article 22, Paragraph 2 of the Law of Georgia on Road Traffic, animal-drawn transport must be operated as close as possible to the edge of the carriageway or on the shoulder (provided it does not obstruct pedestrians) in a single file and in the direction of traffic to ensure road safety.', 0, '1', 'As close as possible to the edge of the carriageway or on the shoulder (if it does not obstruct pedestrians) in a single file, in the direction of traffic', 'On the carriageway against the direction of traffic', 'At the discretion of the driver on any part of the road', NULL, 3, '{2,6,7}'::int[], NULL, 'Hello! Remember that animal-drawn transport is a full participant in road traffic. To ensure safety and avoid accidents, they must stay as far to the right as possible or on the shoulder, ensuring they don''t block pedestrians or disrupt the flow of cars.', NULL),
(825, 'ka', 'აქვს თუ არა უფლება მოტოციკლის მძღოლს გზაზე იმოძრაოს ისე, რომ მისი სატრანსპორტო საშუალების მხოლოდ ერთი თვალი ეხებოდეს გზის ზედაპირს?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 21-ე მუხლის მე-11 პუნქტის თანახმად, მოპედის, მოტოციკლის, ორბორბლიანი ელექტროთვითმგორავის, ველოსიპედის მძღოლი ვალდებულია გზაზე ისე იმოძრაოს, რომ სატრანსპორტო საშუალების ყველა თვალი ეხებოდეს გზის ზედაპირს.', 0, '3', 'აქვს უფლება ნებისმიერ შემთხვევაში', 'აქვს უფლება მხოლოდ დაუსახლებულ პუნქტებში', 'არა აქვს უფლება', NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოტოციკლით გზაზე სრული კონტროლის შესანარჩუნებლად ყველა ბორბალი მუდმივად მიწაზე უნდა იყოს. „ვილის“ კეთება სახიფათოა და კანონით აკრძალულია, რადგან ასე მანქანაზე კონტროლს კარგავ.', NULL),
(825, 'ru', 'Имеет ли право водитель мотоцикла двигаться по дороге так, чтобы только одно колесо его транспортного средства касалось поверхности дороги?', 'Согласно пункту 11 статьи 21 Закона Грузии «О дорожном движении», водитель мотоцикла обязан двигаться по дороге так, чтобы все колеса транспортного средства касались поверхности дороги. Следовательно, езда на заднем колесе (т.н. «вилли») запрещена.', 0, '3', 'Имеет право в любом случае', 'Имеет право только в населенных пунктах', 'Не имеет права', NULL, 14, '{2}'::int[], NULL, 'Привет! Запомни: чтобы полностью контролировать мотоцикл, все его колеса должны постоянно касаться дороги. Выполнение трюков на одном колесе опасно и запрещено законом, так как это лишает тебя стабильности и контроля над управлением.', NULL),
(825, 'en', 'Does a motorcycle driver have the right to drive on the road in such a way that only one wheel of their vehicle touches the road surface?', 'According to Article 21, Paragraph 11 of the Law of Georgia ''on Road Traffic'', a motorcycle driver is obliged to drive on the road in such a way that all wheels of the vehicle are in contact with the road surface. Therefore, performing a ''wheelie'' is prohibited.', 0, '3', 'Has the right in any case', 'Has the right only in settlements', 'Does not have the right', NULL, 14, '{2}'::int[], NULL, 'Hello! Remember, to maintain full control of your motorcycle, all wheels must be in contact with the road at all times. Performing a ''wheelie'' is dangerous and illegal because it causes you to lose stability and control of the vehicle.', NULL),
(846, 'ka', 'დასაშვებია თუ არა მსვლელობით მიმავალ ქვეითთა ჯგუფის სავალ ნაწილზე გადაადგილება?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 24-ე მუხლის მე-2 პუნქტის „ბ“ ქვეპუნქტის თანახმად, თუ გზის სავალი ნაწილის კიდესთან არსებობს ქვეითთა მოძრაობისთვის გამოსადეგი ქვეითთა ბილიკი, ტროტუარი ან გზისპირი, ქვეითმა უნდა გამოიყენოს იგი, თუმცა უნდა დაიცვას სიფრთხილის აუცილებელი ზომები. ქვეითთა ჯგუფებს, რომლებიც ორგანიზებულად გადაადგილდებიან ან მსვლელობით მიდიან, შეუძლიათ იარონ გზის სავალ ნაწილზე; ამასთანავე, გზის სავალ ნაწილზე მათი მოძრაობა ნებადართულია მხოლოდ სატრანსპორტო საშუალების მოძრაობის მიმართულებით, მარჯვენა მხარეს, რიგში არაუმეტეს ოთხი კაცისა. ქვეითთა ჯგუფს წინ და უკან, მარცხენა მხარეს უნდა მიჰყვებოდნენ გამცი¬ლებ¬ლები წითელი ალმებით, ხოლო დღე-ღამის ბნელ დროს ან არასაკმარისი ხილვადობის პირობებში – ჩართული ფარნებით (წინ – თეთრით, უკან – წითლით).', 0, '1', 'დასაშვებია, მხოლოდ სატრანსპორტო საშუალების მოძრაობის მიმართულებით, მარჯვენა მხარეს, რიგში არა უმეტეს ოთხი კაცისა', 'დასაშვებია, მხოლოდ სატრანსპორტო საშუალების მოძრაობის საპირისპირო მიმართულებით, მარჯვენა მხარეს, რიგში არა უმეტეს ორი კაცისა', 'დაუშვებელია', NULL, 2, '{2,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როცა მსვლელობით მიდიხართ, თქვენ უნდა მოძრაობდეთ მანქანების მიმართულებით, რადგან ასე უფრო ადვილად ხედავთ და გხედავენ გზაზე. ოთხკაციანი რიგი ოპტიმალურია, რათა გზა ზედმეტად არ გადაიკეტოს.', NULL),
(846, 'ru', 'Разрешено ли организованным группам пешеходов (колоннам) передвигаться по проезжей части?', 'Согласно подпункту «б» пункта 2 статьи 24 Закона Грузии «О дорожном движении», организованные группы пешеходов при движении по проезжей части должны следовать только по направлению движения транспортных средств, по правой стороне, не более четырех человек в ряд для обеспечения безопасности.', 0, '1', 'Разрешено только по направлению движения транспортных средств, по правой стороне, в колонне не более четырех человек в ряд', 'Разрешено только навстречу движению транспортных средств, по правой стороне, в колонне не более двух человек в ряд', 'Запрещено', NULL, 2, '{2,6,7}'::int[], NULL, 'Привет! Запомни: когда вы идете организованной колонной, вы должны двигаться по направлению движения машин. Так и водители вас видят лучше, и вы не создаете лишних помех. Группа по четыре человека в ряд — это максимально разрешенный и безопасный формат.', NULL),
(846, 'en', 'Is it permitted for a group of pedestrians marching in procession to move along the carriageway?', 'According to Article 24, Paragraph 2, Subparagraph ''b'' of the Law of Georgia ''on Road Traffic'', organized groups of pedestrians moving on the carriageway must travel only in the direction of vehicle traffic, on the right side, and in rows of no more than four people to ensure safety.', 0, '1', 'Permitted only in the direction of vehicle traffic, on the right side, in columns of no more than four people', 'Permitted only against the direction of vehicle traffic, on the right side, in columns of no more than two people', 'Prohibited', NULL, 2, '{2,6,7}'::int[], NULL, 'Hello! Remember, when marching in a group, you must walk in the same direction as the vehicle traffic. This makes it easier for drivers to spot you and for you to remain predictable on the road. The four-person-wide row is the standard rule to ensure you don''t take up too much space while staying organized.', NULL),
(848, 'ka', 'აქვს თუ არა უფლება ქვეითს სავალ ნაწილზე გადასვლისას გამოვიდეს გაჩერებული სატრანსპორტო საშუალების წინა მხრიდან?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის მე-24 მუხლის მე-9 პუნქტის თანახმად, გზის სავალ ნაწილზე გადასვლისას ქვეითი არ უნდა გამოვიდეს გაჩერებული სატრანსპორტო საშუალების ან ხილვადობის შემზღუდველი სხვა დაბრკოლების წინა მხრიდან, ვიდრე არ დარწმუნდება მოახლოებული სატრანსპორტო საშუალების არარსებობაში.', 0, '2', 'არა აქვს უფლება', 'აქვს უფლება, თუ დარწმუნდება მოახლოებული სატრანსპორტო საშუალების არარსებობაში', 'აქვს უფლება მხოლოდ ცალმხრივმოძრაობიან გზებზე', NULL, 2, '{2,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ გაჩერებული მანქანა შენს ხედვის არეს ზღუდავს. მძღოლს შენი დანახვა უჭირს, ამიტომ კანონი მოითხოვს, ჯერ დაელოდო და დარწმუნდე, რომ გზა თავისუფალია და არავინ მოდის, და მხოლოდ ამის შემდეგ გადაკვეთო გზა.', NULL),
(848, 'ru', 'Имеет ли право пешеход при переходе проезжей части выходить из-за передней части остановившегося транспортного средства?', 'Согласно пункту 9 статьи 24 Закона Грузии «О дорожном движении», пешеход не должен выходить на проезжую часть из-за передней части остановившегося транспортного средства или иного препятствия, ограничивающего видимость, не убедившись в отсутствии приближающегося транспортного средства. Данное правило обеспечивает безопасность пешехода в условиях ограниченной видимости.', 0, '2', 'Не имеет права', 'Имеет право, если убедится в отсутствии приближающегося транспортного средства', 'Имеет право только на дорогах с односторонним движением', NULL, 2, '{2,6,7}'::int[], NULL, 'Привет! Помни, что остановившаяся машина ограничивает твой обзор и видимость для водителей. Закон требует, чтобы ты сначала убедился в отсутствии приближающихся автомобилей, прежде чем выходить на дорогу из-за препятствия. Безопасность превыше всего!', NULL),
(848, 'en', 'Does a pedestrian have the right to step onto the roadway from in front of a stopped vehicle?', 'According to Article 24, Paragraph 9 of the Law of Georgia on Road Traffic, a pedestrian must not enter the roadway from in front of a stopped vehicle or any other obstacle that limits visibility until they have ensured that no vehicle is approaching. This rule ensures pedestrian safety under conditions of limited visibility.', 0, '2', 'Does not have the right', 'Has the right, provided they ensure no vehicles are approaching', 'Has the right only on one-way roads', NULL, 2, '{2,6,7}'::int[], NULL, 'Hello! Remember that a stopped vehicle blocks your view of the road and makes it harder for drivers to see you. The law requires you to stop and ensure no cars are approaching before stepping out. Always double-check to stay safe!', NULL),
(880, 'ka', '„ავტობუსი’’ არის ავტოსატრანსპორტო საშუალება, რომელიც განკუთვნილია:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 5-ე მუხლის პირველი პუნქტის თანახმად, ავტობუსი − ავტოსატრანსპორტო საშუალება, რომელიც განკუთვნილია მგზავრთა გადასაყვანად და რომლის დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა, 8-ს აღემატება.', 0, '2', 'მგზავრთა გადასაყვანად და რომლის დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა, 8-ს არ აღემატება', 'მგზავრთა გადასაყვანად და რომლის დასასხდომი ადგილების რაოდენობა 8-ს აღემატება', 'ტვირთის გადასაზიდად და რომლის ნებადართული მაქსიმალური მასა აღემატება 12 000 კგ-ს', NULL, 1, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს: თუ მანქანაში მძღოლის გარდა 8-ზე მეტი ადგილია, ეს უკვე ავტობუსია. ეს კანონით დადგენილი ზღვარია მგზავრთა გადასაყვანი ტრანსპორტის კლასიფიკაციისთვის.', NULL),
(880, 'ru', '«Автобус» — это механическое транспортное средство, предназначенное для:', 'Согласно статье 2 Закона Грузии «О дорожном движении» (определения терминов), автобус — это механическое транспортное средство, предназначенное для перевозки пассажиров, количество сидячих мест в котором, помимо места водителя, превышает 8.', 0, '2', 'перевозки пассажиров, количество сидячих мест в котором, помимо места водителя, не превышает 8', 'перевозки пассажиров, количество сидячих мест в котором превышает 8', 'перевозки грузов, максимальная допустимая масса которого превышает 12 000 кг', NULL, 1, '{4,6}'::int[], NULL, 'Привет! Запомни простое правило: если в транспортном средстве более 8 пассажирских мест (не считая водителя), по закону это считается автобусом. Это ключевой критерий для классификации пассажирского транспорта.', NULL),
(880, 'en', 'A "bus" is a motor vehicle intended for:', 'According to Article 2 of the Law of Georgia "On Road Traffic" (definitions of terms), a bus is a motor vehicle intended for the carriage of passengers, which has more than 8 seats, excluding the driver''s seat.', 0, '2', 'the carriage of passengers and which has more than 8 seats, excluding the driver''s seat', 'the carriage of passengers and which has more than 8 seats', 'the transport of goods and whose maximum authorized mass exceeds 12,000 kg', NULL, 1, '{4,6}'::int[], NULL, 'Hello! Remember this simple rule: if a vehicle has more than 8 seats for passengers (excluding the driver), it is classified as a bus. This is the legal threshold used to distinguish buses from smaller passenger vehicles.', NULL),
(940, 'ka', 'დაუსახლებელ პუნქტებში, იმ ორმხრივ მოძრაობიან გზაზე, რომელზეც არ არის გამყოფი ზოლი და ტროტუარი, მოტოციკლის ხელით გადამყვანმა პირმა გადაადგილების მიზნით უნდა დაიკავოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 24-ე მუხლის მე-5 პუნქტის თანახმად, დაუსახლებელ პუნქტში, იმ ორმხრივმოძრაობიან გზაზე, რომელსაც არ აქვს გამყოფი ზოლი და ტროტუარი, ქვეითმა უნდა დაიკავოს მოძრაობის მიმართულების საწინააღმდეგო მხარეს მდებარე გვერდულა, ხოლო მისი არარსებობის ან გამოყენების შეუძლებლობის შემთხვევაში − გზის სავალი ნაწილის მარცხენა მხარე და გადაადგილდეს მოძრაობის მიმართულების საწინააღმდეგოდ (გარდა იმ შემთხვევისა, როცა მოცემულ სიტუაციაში გზის სავალი ნაწილის მარჯვენა მხარეს მოძრაობის მიმართულებით გადაადგილება უფრო უსაფრთხოა), მაგრამ ველოსიპედის, მოპედის ან მოტოციკლის ხელით გადამყვანმა, აგრეთვე სავარძელ-ეტლით მოძრავმა შეზღუდული შესაძლებლობის მქონე პირმა გადაადგილების მიზნით უნდა დაიკავონ გზის სავალი ნაწილის მარჯვენა მხარე.', 0, '1', 'სავალი ნაწილის მარჯვენა მხარე', 'სავალი ნაწილის მარცხენა მხარე', 'ნებისმიერი მოძრაობის ზოლი', NULL, 2, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს: მიუხედავად იმისა, რომ ქვეითი საწინააღმდეგო მხარეს დადის, როცა მოტოციკლს ხელით ატარებ, შენ ემსგავსები სატრანსპორტო საშუალებას და უნდა იმოძრაო მარჯვნივ, რათა ნაკადთან ერთად მიდიოდე. ეს უფრო უსაფრთხოა!', NULL),
(940, 'ru', 'Вне населенных пунктов, на дороге с двусторонним движением, где нет разделительной полосы и тротуара, лицо, ведущее мотоцикл в руках, для передвижения должно занимать:', 'Согласно пункту 5 статьи 24 Закона Грузии «О дорожном движении», несмотря на то, что пешеходы обязаны двигаться навстречу транспортному потоку, лица, ведущие велосипед, мопед или мотоцикл в руках, являются исключением и обязаны двигаться по правой стороне проезжей части.', 0, '1', 'Правую сторону проезжей части', 'Левую сторону проезжей части', 'Любую полосу движения', NULL, 2, '{0,2}'::int[], NULL, 'Привет! Запомни: хотя пешеходы обычно ходят навстречу потоку, когда ты ведешь мотоцикл в руках, ты приравниваешься к транспортному средству и должен двигаться по правой стороне, в попутном направлении. Так безопаснее!', NULL),
(940, 'en', 'Outside built-up areas, on a two-way road without a dividing strip and sidewalk, a person leading a motorcycle by hand must occupy for movement:', 'According to Article 24, Paragraph 5 of the Law of Georgia on Road Traffic, although pedestrians are required to move against the flow of traffic, persons leading a bicycle, moped, or motorcycle by hand are an exception and are required to move along the right side of the carriageway.', 0, '1', 'The right side of the carriageway', 'The left side of the carriageway', 'Any traffic lane', NULL, 2, '{0,2}'::int[], NULL, 'Hello! Remember: even though pedestrians usually walk against traffic, when you are leading a motorcycle by hand, you are treated similarly to a vehicle and must move on the right side, in the direction of traffic. It is safer that way!', NULL),
(967, 'ka', 'დღის ნათელ დროს გზაზე მოძრავ ნებისმიერ მოტოციკლზე ჩართული უნდა იყოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 49-ე მუხლის მე-7 პუნქტის თანახმად, დღის ნათელ დროს გზაზე მოძრავ ნებისმიერ მოტოციკლზე წინ ჩართული უნდა იყოს ახლო განათების ერთი ფარა მაინც, ხოლო უკან - წითელი მაშუქი.', 0, '3', 'მხოლოდ ახლო განათების ფარები', 'მხოლოდ შორი განათების ფარები', 'წინ ახლო განათების ერთი ფარი მაინც, ხოლო უკან - წითელი მაშუქი', 'მხოლოდ უკან - წითელი მაშუქი', 17, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოტოციკლი გზაზე ნაკლებად შესამჩნევია, ვიდრე ავტომობილი. ამიტომ კანონი ავალდებულებს მოტოციკლისტებს, დღისითაც კი აანთონ ფარები, რათა სხვა მძღოლებმა ადვილად დაგინახონ. ამიტომ, სწორი პასუხია მესამე: წინ - ახლო განათება, უკან - წითელი მაშუქი.', NULL),
(967, 'ru', 'Должен ли быть включен свет на любом мотоцикле, движущемся по дороге в светлое время суток?', 'Согласно пункту 7 статьи 49 Закона Грузии «О дорожном движении», для обеспечения видимости мотоцикла в дневное время при движении по дороге обязательно включение как минимум одной фары ближнего света спереди и красного габаритного огня сзади.', 0, '3', 'Только ближний свет фар', 'Только дальний свет фар', 'Как минимум одна фара ближнего света спереди и красный фонарь сзади', 'Только красный фонарь сзади', 17, '{2}'::int[], NULL, 'Привет! Помни, что мотоцикл менее заметен на дороге, чем автомобиль. Поэтому закон обязывает мотоциклистов включать свет даже днем, чтобы другие водители могли тебя вовремя заметить. Именно поэтому правильный ответ — третий: спереди — ближний свет, сзади — красный фонарь.', NULL),
(967, 'en', 'During daylight hours, what lights must be switched on for any motorcycle moving on the road?', 'According to Article 49, paragraph 7 of the Georgian Law on Road Traffic, in order to ensure the visibility of a motorcycle during daylight hours, it is mandatory to have at least one low-beam headlight switched on at the front and a red position light at the rear.', 0, '3', 'Only low beam headlights', 'Only high beam headlights', 'At least one low beam headlight at the front and a red light at the rear', 'Only a red light at the rear', 17, '{2}'::int[], NULL, 'Hello! Remember, a motorcycle is less visible on the road than a car. That is why the law requires motorcyclists to keep their lights on even during the day, so other drivers can see you clearly. This is why the third option is correct: low beam at the front and a red light at the rear.', NULL),
(982, 'ka', 'დღის ნათელ დროს სამარშრუტო სატრანსპორტო საშუალებებზე, სპეციალურად მათთვის გამოყოფილ ზოლზე, ძირითადი ნაკადის საპირისპიროდ მოძრაობისას ჩართული უნდა იყოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 49-ე მუხლის მე-8 პუნქტის „ე“ ქვეპუნქტის თანახმად, დღის ნათელ დროს გზაზე მოძრავი სატრანსპორტო საშუალების აღნიშვნის მიზნით სავალდებულოა ახლო განათების ფარებისა და უკანა საგაბარიტო სინათლეების ჩართვა: ე) სამარშრუტო სატრანსპორტო საშუალებაზე, სპეციალურად მისთვის გამოყოფილ ზოლზე, ძირითადი ნაკადის საპირისპირო მიმართულებით მოძრაობისას.', 0, '2', 'საავარიო შუქსიგნალიზაცია', 'ახლო განათების ფარები და უკანა საგაბარიტო სინათლეები', 'შორი განათების ფარები და უკანა საგაბარიტო სინათლეები', 'მხოლოდ წინა და უკანა საგაბარიტო სინათლეები', 17, '{4,6}'::int[], NULL, 'გამარჯობა! როდესაც ავტობუსი ან მარშრუტკა ძირითადი ნაკადის საპირისპიროდ მიდის, ის მოულოდნელი დაბრკოლებაა სხვა მძღოლებისთვის. ამიტომ, კანონი გვაიძულებს გამოვაჩინოთ ის ფარების ანთებით. აირჩიე მეორე პასუხი, რადგან ახლო განათება საუკეთესოდ მიანიშნებს შენს მიმართულებაზე!', NULL),
(982, 'ru', 'Что должно быть включено в светлое время суток на маршрутных транспортных средствах при движении по специально выделенной для них полосе навстречу основному потоку?', 'Согласно подпункту «е» пункта 8 статьи 49 Закона Грузии «О дорожном движении», при движении навстречу основному потоку транспортных средств для повышения их заметности и обеспечения безопасности дорожного движения обязательно включение ближнего света фар и задних габаритных огней.', 0, '2', 'Аварийная световая сигнализация', 'Фары ближнего света и задние габаритные огни', 'Фары дальнего света и задние габаритные огни', 'Только передние и задние габаритные огни', 17, '{4,6}'::int[], NULL, 'Привет! Когда автобус или маршрутка едет против основного потока, это может быть неожиданностью для других водителей. Чтобы быть заметными и избежать аварий, нужно обязательно включить ближний свет и габариты. Выбирай второй вариант — это стандарт безопасности!', NULL),
(982, 'en', 'What must be switched on during daylight hours on route vehicles moving in the opposite direction to the main traffic flow on a lane specially designated for them?', 'According to Article 49, paragraph 8, subparagraph ''e'' of the Law of Georgia ''on Road Traffic'', when moving in the opposite direction to the main traffic flow, it is mandatory to switch on low beam headlights and rear position lights to increase visibility and ensure safety for other road users.', 0, '2', 'Hazard warning lights', 'Low beam headlights and rear position lights', 'High beam headlights and rear position lights', 'Only front and rear position lights', 17, '{4,6}'::int[], NULL, 'Hello! When a bus or shuttle drives against the main traffic flow, it can surprise other drivers. To stay visible and safe, the law requires you to switch on your low beam lights and position lights. Choose answer 2 — it''s the safest way to signal your presence!', NULL),
(992, 'ka', 'იმ საჭაპნო ტრანსპორტზე, რომლის სიგანე 1 მ-ს არ აღემატება, სავალდებულოა დაყენდეს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 50-ე მუხლის მე-3 პუნქტის თანახმად, ფარანი არ არის აუცილებელი იმ საჭაპანო ტრანსპორტისათვის, რომლის სიგანე 1 მეტრს არ აღემატება, მაგრამ ამ შემთხვევაში უკან, მარცხენა მხარეს, ან ცენტრში დაყენებული უნდა იყოს ერთი შუქამრეკლი მოწყობილობა.', 0, '3', 'სულ მცირე ერთი წინა თეთრი ან ყვითელი სელექციური სინათლე', 'წინ - ერთი თეთრი სინათლე და უკან - ერთი წითელი სინათლე', 'უკან, მარცხენა მხარეს, ან ცენტრში - ერთი შუქამრეკლი მოწყობილობა', NULL, 17, '{2,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მცირე ზომის საჭაპანო ტრანსპორტისთვის (სიგანე 1მ-მდე) შუქნიშნები არ არის აუცილებელი, მაგრამ იმისთვის, რომ ღამით სხვა მძღოლებმა დაგინახონ, კანონი გთხოვს უკან ერთი შუქამრეკლი მოწყობილობის დამაგრებას. ეს ძალიან მარტივი და მნიშვნელოვანი წესია შენი უსაფრთხოებისთვის!', NULL),
(992, 'ru', 'На гужевом транспортном средстве, ширина которого не превышает 1 метра, обязательно должно быть установлено:', 'Согласно пункту 3 статьи 50 Закона Грузии «О дорожном движении», для гужевых транспортных средств шириной до 1 метра установка фонарей не является обязательной, однако в целях безопасности на них должно быть установлено одно светоотражающее устройство сзади (слева или по центру), что обеспечивает видимость транспортного средства в темное время суток.', 0, '3', 'По меньшей мере один передний белый или желтый селективный свет', 'Спереди - один белый свет и сзади - один красный свет', 'Сзади, с левой стороны или по центру - одно светоотражающее устройство', NULL, 17, '{2,6,7}'::int[], NULL, 'Привет! Помни, что для компактного гужевого транспорта (шириной до 1 м) установка фонарей не требуется. Но чтобы другие водители могли заметить тебя в темноте, закон требует закрепить сзади один светоотражатель. Это простое правило, которое поможет тебе оставаться в безопасности на дороге!', NULL),
(992, 'en', 'On a horse-drawn vehicle, the width of which does not exceed 1 meter, it is mandatory to install:', 'According to Article 50, Paragraph 3 of the Law of Georgia ''On Road Traffic'', lamps are not mandatory for horse-drawn vehicles with a width of up to 1 meter; however, for safety reasons, one retro-reflective device must be installed at the rear (on the left or in the center) to ensure the vehicle is visible in dark conditions.', 0, '3', 'At least one front white or yellow selective light', 'In the front - one white light and in the back - one red light', 'At the rear, on the left side or in the center - one retro-reflective device', NULL, 17, '{2,6,7}'::int[], NULL, 'Hello! Remember that for small horse-drawn vehicles (up to 1m wide), lamps are not strictly required. However, so that other drivers can see you at night, the law requires you to attach one retro-reflective device at the back. It''s a simple and vital rule to keep you safe!', NULL),
(996, 'ka', 'სავალ ნაწილზე ღამის საათებში მოძრაობისას ქვეითთა ჯგუფებმა, რომლებსაც ხელმძღვანელები მეთაურობენ ან სვლით მიდიან, მარცხენა მხრიდან უნდა იქონიონ:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 50-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, სავალ ნაწილზე ღამის საათებში მოძრაობისას: ა) ქვეითთა ჯგუფმა, რომელსაც ხელმძღვანელი მეთაურობს ან რომელიც სვლით მიდის, მარცხენა მხრიდან უნდა იქონიოს სულ მცირე ერთი თეთრი ან ყვითელი სელექციური სინათლე წინ და სულ მცირე ერთი წითელი სინათლე უკან ან ყვითელი შუქი წინ და უკან.', 0, '2', 'სულ მცირე ერთი თეთრი სელექციური სინათლე წინ და ერთი თეთრი სელექციური სინათლე უკან', 'სულ მცირე ერთი თეთრი ან ყვითელი სელექციური სინათლე წინ და ერთი წითელი სინათლე უკან ან ყვითელი შუქი წინ და უკან', 'სულ მცირე ერთი წითელი სელექციური სინათლე წინ და ერთი ყვითელი სინათლე უკან', NULL, 17, '{2,6,7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ღამით ქვეითების ჯგუფის უსაფრთხოება ყველაზე მნიშვნელოვანია. კანონი გვავალდებულებს, რომ ჯგუფს მარცხნივ ჰქონდეს თეთრი/ყვითელი შუქი წინ და წითელი შუქი უკან (ან ყვითელი ორივე მხარეს), რათა მძღოლებმა მარტივად გაიგონ ჯგუფის მოძრაობის მიმართულება.', NULL),
(996, 'ru', 'При движении по проезжей части в темное время суток группы пешеходов, возглавляемые руководителями или идущие строем, должны иметь с левой стороны:', 'Согласно подпункту «а» пункта 4 статьи 50 Закона Грузии «О дорожном движении», для обеспечения безопасности при движении групп пешеходов по проезжей части в ночное время, они обязаны иметь осветительные приборы с левой стороны. Правильный ответ соответствует законодательно установленным требованиям к цветовой индикации, что необходимо для адекватного восприятия группы другими участниками движения.', 0, '2', 'По меньшей мере один белый селективный свет спереди и один белый селективный свет сзади', 'По меньшей мере один белый или желтый селективный свет спереди и один красный свет сзади, либо желтый свет спереди и сзади', 'По меньшей мере один красный селективный свет спереди и один желтый свет сзади', NULL, 17, '{2,6,7}'::int[], NULL, 'Привет! Помни, что безопасность группы пешеходов ночью — это приоритет. Закон требует наличия света с левой стороны: белый или желтый спереди и красный сзади (либо желтый с обеих сторон). Это помогает водителям издалека понять, в какую сторону движется группа.', NULL),
(996, 'en', 'When moving along the carriageway at night, groups of pedestrians led by a leader or marching in formation must have on their left side:', 'According to Article 50, Paragraph 4, Subparagraph ''a'' of the Law of Georgia ''on Road Traffic'', for the safety of pedestrian groups moving on the carriageway at night, it is mandatory to have lighting devices on the left side. The correct answer adheres to the legally mandated color combinations and positioning to ensure that other drivers correctly perceive the group.', 0, '2', 'At least one white selective light in front and one white selective light behind', 'At least one white or yellow selective light in front and at least one red light behind, or yellow light in front and behind', 'At least one red selective light in front and one yellow light behind', NULL, 17, '{2,6,7}'::int[], NULL, 'Hello! Remember, the safety of pedestrian groups at night is paramount. The law requires the group to carry lights on their left side: white or yellow in front and red behind (or yellow on both ends). This helps drivers identify the group''s direction of travel quickly and clearly.', NULL),
(1012, 'ka', 'რა თანამიმდევრობით უნდა გაირონ გზაჯვარედინი სატრანსპორტო საშუალებებმა ისრის მიმართულებით მოძრაობის შემთხვევაში, თუ ოპერატიულ სამსახურის ავტომობილს ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა სიგნალი?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა; ამავე კანონის 51-ე მუხლის პირველი პუნქტის თანახმად ოპერატიული ან სპეციალური სამსახურის სატრანსპორტო საშუალების მძღოლს, რომელსაც სატრანსპორტო საშუალებაზე ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა სიგნალი და ასრულებს სამსახურებრივ დავალებას, შეუძლია საგზაო მოძრაობის უსაფრთხოების უზრუნველყოფის პირობების დაცვით გადაუხვიოს ამ კანონის 25-ე, 31-ე−41-ე და 44-ე მუხლებით, აგრეთვე ამ კანონის №1 და №2 დანართებით დადგენილ მოთხოვნებს. ლურჯ მოელვარე სპეციალურ ციმციმა სიგნალთან ერთად დამატებით შეიძლება ჩაირთოს წითელი მოელვარე ციმციმა სიგნალიც. სხვა საგზაო მოძრაობის მონაწილეების მიმართ უპირატესობის მისაღებად ამ სატრანსპორტო საშუალების მძღოლმა უნდა ჩართოს ლურჯი მოელვარე სპეციალური ციმციმა სიგნალი და ხმოვანი სიგნალი.', 1, '2', 'ჯერ უნდა გაიაროს ოპერატიული სამსახურის ავტომობილმა, შემდეგ - ტრამვაიმ, ბოლოს - ავტობუსმა', 'ჯერ უნდა გაიაროს ტრამვაიმ, შემდეგ - ოპერატიული სამსახურის ავტომობილმა, ბოლოს - ავტობუსმა', 'ჯერ უნდა გაიაროს ოპერატიული სამსახურის ავტომობილმა, შემდეგ - ავტობუსმა, ბოლოს - ტრამვაიმ', NULL, 18, '{6}'::int[], NULL, 'გახსოვდეს, ოპერატიული მანქანა „ჯადოსნური“ არ არის! კანონის მიხედვით, ლურჯი ციმციმა სიგნალი თავისთავად არ გაძლევს გზის დათმობის ვალდებულებას, თუ მძღოლს ხმოვანი სიგნალიც არ აქვს ჩართული. რადგან ხმოვანი სიგნალი არ არის, ტრამვაი ინარჩუნებს თავის კანონიერ უპირატესობას ურელსო ტრანსპორტთან შედარებით, ამიტომ ის პირველი გადის.', 'ticket_media/new/ticketIMG-1012.jpg'),
(1012, 'ru', 'В какой последовательности должны проехать перекресток транспортные средства в направлении, указанном стрелками, если у автомобиля оперативной службы включен специальный синий проблесковый маячок?', 'Согласно пункту 1 статьи 51 Закона Грузии «О дорожном движении», оперативное транспортное средство с включенным синим проблесковым маячком получает преимущество только при использовании специального звукового сигнала. Поскольку в вопросе указан только синий маячок (без звукового сигнала), оперативный автомобиль не имеет преимущества. Следовательно, применяются общие правила проезда перекрестков: рельсовое транспортное средство (трамвай) имеет преимущество перед безрельсовыми транспортными средствами.', 1, '2', 'Сначала должен проехать автомобиль оперативной службы, затем трамвай, в конце - автобус.', 'Сначала должен проехать трамвай, затем автомобиль оперативной службы, в конце - автобус.', 'Сначала должен проехать автомобиль оперативной службы, затем автобус, в конце - трамвай.', NULL, 18, '{6}'::int[], NULL, 'Запомни: машина спецслужб не обладает «магическим» приоритетом по умолчанию! Согласно закону, один лишь синий маячок не дает права на преимущество без звукового сигнала. Так как звукового сигнала нет, трамвай сохраняет свое законное преимущество перед безрельсовым транспортом и проезжает первым.', 'ticket_media/new/ticketIMG-1012.jpg'),
(1012, 'en', 'In what order should vehicles pass the intersection in the direction of the arrows if the emergency service vehicle has a blue flashing light signal turned on?', 'According to Article 51, Paragraph 1 of the Law of Georgia on Road Traffic, an emergency vehicle with a blue flashing signal receives priority only when it also uses a sound signal. Since the question mentions only the blue flashing signal (without a sound signal), the emergency vehicle does not have automatic priority. Therefore, general intersection rules apply: rail transport (the tram) has priority over non-rail vehicles.', 1, '2', 'The emergency vehicle should pass first, then the tram, and finally the bus.', 'The tram should pass first, then the emergency vehicle, and finally the bus.', 'The emergency vehicle should pass first, then the bus, and finally the tram.', NULL, 18, '{6}'::int[], NULL, 'Remember, an emergency vehicle doesn''t have "magic" priority just by turning on a light! According to the law, a blue flashing light alone doesn''t grant priority unless the siren (sound signal) is also on. Since there''s no sound signal, the tram keeps its legal priority over other vehicles and goes first.', 'ticket_media/new/ticketIMG-1012.jpg'),
(1090, 'ka', '„A“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს უფლება აქვს მართოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-2 პუნქტის „ა“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ კატეგორიებად: ა) „A“ − მოტოციკლი.', 0, '3', 'მხოლოდ უეტლო მოტოციკლი', 'მხოლოდ ის მოტოციკლი, რომლის ძრავის მუშა მოცულობა არ აღემატება 125 სმ3-ს, ხოლო მაქსიმალური სიმძლავრე - 11 კვტ-ს', 'ნებისმიერი სახის მოტოციკლი', NULL, 20, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ „A“ კატეგორია არის უმაღლესი საფეხური მოტოციკლებისთვის. სხვა ქვეკატეგორიებისგან განსხვავებით, „A“ კატეგორია არ ზღუდავს არც სიმძლავრეს და არც მოცულობას, ამიტომ ნებისმიერი მოტოციკლის მართვის უფლება გაქვს.', NULL),
(1090, 'ru', 'Имеет ли право лицо, имеющее право на управление транспортным средством категории «A», управлять:', 'Согласно пункту 2 «а» статьи 54 Закона Грузии «О дорожном движении», категория «A» включает в себя мотоциклы. Закон не устанавливает ограничений по объему двигателя или мощности для данной категории, что означает, что водитель имеет право управлять мотоциклом любого типа.', 0, '3', 'Только мотоцикл без коляски', 'Только мотоцикл с рабочим объемом двигателя не более 125 см3 и максимальной мощностью не более 11 кВт', 'Мотоциклы любого типа', NULL, 20, '{2}'::int[], NULL, 'Привет! Запомни, что категория «A» — это высшая ступень для мотоциклов. В отличие от подкатегорий, категория «A» не ограничивает ни мощность, ни объем двигателя, поэтому ты имеешь полное право управлять любым мотоциклом.', NULL),
(1090, 'en', 'A person with the right to drive a category "A" vehicle is allowed to drive:', 'According to Article 54, paragraph 2, subparagraph "a" of the Law of Georgia "On Road Traffic", category "A" includes motorcycles. The law does not impose restrictions on the engine capacity or power for this category, meaning the driver is authorized to operate any type of motorcycle.', 0, '3', 'Only a motorcycle without a sidecar', 'Only a motorcycle with an engine capacity not exceeding 125 cm3 and a maximum power of 11 kW', 'Any type of motorcycle', NULL, 20, '{2}'::int[], NULL, 'Hello! Remember that category "A" is the highest tier for motorcycles. Unlike subcategories, category "A" does not restrict power or engine displacement, so you are authorized to ride any motorcycle.', NULL),
(1096, 'ka', '„D“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე მძღოლს, უფლება აქვს მართოს მგზავრთა გადასაყვანად განკუთვნილი ავტომობილი, რომლის დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-2 პუნქტის „დ“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ კატეგორიებად: დ) „D“ − ავტომობილი, რომელიც განკუთვნილია მგზავრთა გადასაყვანად და რომლის დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა, 8-ს აღემატება, აგრეთვე „D“ კატეგორიის ავტომობილი, გადაბმული მისაბმელთან, რომლის ნებადართული მაქსიმალური მასა არ აღემატება 750 კგ-ს.', 0, '1', 'აღემატება 8-ს', 'არ აღემატება 8-ს', NULL, NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ „D“ კატეგორია არის დიდი ავტობუსებისთვის. თუ მგზავრთა დასასხდომი ადგილი (მძღოლის გარდა) არის 8-ზე მეტი, ეს უკვე ავტობუსია და გჭირდება „D“ კატეგორია.', NULL),
(1096, 'ru', 'Водитель, имеющий право на управление транспортным средством категории «D», имеет право управлять автомобилем, предназначенным для перевозки пассажиров, количество сидячих мест в котором, помимо места водителя:', 'Согласно подпункту «д» пункта 2 статьи 54 Закона Грузии «О дорожном движении», категория «D» предназначена для автомобилей, предназначенных для перевозки пассажиров, в которых количество сидячих мест, помимо места водителя, превышает 8.', 0, '1', 'Превышает 8', 'Не превышает 8', NULL, NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни, что категория «D» предназначена для больших автобусов. Если количество мест для пассажиров (не считая водителя) больше 8, то это уже автобус, и для управления им необходима категория «D».', NULL),
(1096, 'en', 'A driver authorized to operate a vehicle of category "D" has the right to drive a vehicle designed for the carriage of passengers, in which the number of seats, excluding the driver''s seat:', 'According to Article 54, paragraph 2, subparagraph ''d'' of the Law of Georgia "On Road Traffic", category "D" is defined for vehicles designed for the carriage of passengers with more than 8 seats in addition to the driver''s seat.', 0, '1', 'Exceeds 8', 'Does not exceed 8', NULL, NULL, 20, '{4}'::int[], NULL, 'Hello! Remember that category "D" is for large buses. If the number of passenger seats (excluding the driver''s seat) is more than 8, it is considered a bus, and you must hold a "D" category license.', NULL),
(1097, 'ka', '„D“კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე მძღოლს უფლება აქვს მართოს „D“ კატეგორიის ავტომობილი მისაბმელით, რომლის ნებადართული მაქსიმალური მასა:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-2 პუნქტის „დ“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ კატეგორიებად: დ) „D“ − ავტომობილი, რომელიც განკუთვნილია მგზავრთა გადასაყვანად და რომლის დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა, 8-ს აღემატება, აგრეთვე „D“ კატეგორიის ავტომობილი, გადაბმული მისაბმელთან, რომლის ნებადართული მაქსიმალური მასა არ აღემატება 750 კგ-ს.', 0, '3', 'აღემატება 1 500 კგ-ს', 'აღემატება 750 კგ-ს, მაგრამ არ აღემატება 1 500 კგ-ს', 'არ აღემატება 750 კგ-ს', NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე: D კატეგორია გაძლევს უფლებას მართო ავტობუსი და თან დააბა მხოლოდ მსუბუქი მისაბმელი (750 კგ-მდე). თუ მისაბმელი უფრო მძიმეა, მაშინ უკვე D+E კატეგორია დაგჭირდება.', NULL),
(1097, 'ru', 'Имеет ли право водитель с категорией «D» управлять автомобилем категории «D» с прицепом, максимальная разрешенная масса которого:', 'Согласно подпункту «д» пункта 2 статьи 54 Закона Грузии «О дорожном движении», право на управление транспортным средством категории «D» включает в себя управление автомобилем для перевозки пассажиров (более 8 мест для сидения), а также автомобилем с прицепом, разрешенная максимальная масса которого не превышает 750 кг.', 0, '3', 'превышает 1500 кг', 'превышает 750 кг, но не превышает 1500 кг', 'не превышает 750 кг', NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни: категория «D» дает тебе право управлять автобусом и цеплять к нему только легкий прицеп (до 750 кг). Если прицеп тяжелее, тебе потребуется категория «D+E».', NULL),
(1097, 'en', 'Is a driver holding a category ''D'' driving license allowed to operate a category ''D'' vehicle with a trailer whose maximum authorized mass:', 'According to Article 54, Paragraph 2, Subparagraph ''d'' of the Law of Georgia ''On Road Traffic'', the right to drive a category ''D'' vehicle includes driving a vehicle designed for passenger transport (with more than 8 seats) and a vehicle with a trailer, provided that the trailer''s maximum authorized mass does not exceed 750 kg.', 0, '3', 'exceeds 1500 kg', 'exceeds 750 kg, but does not exceed 1500 kg', 'does not exceed 750 kg', NULL, 20, '{4}'::int[], NULL, 'Hi there! Remember: a category ''D'' license allows you to drive a bus and tow only a light trailer (up to 750 kg). If the trailer is heavier, you will need a ''D+E'' category license.', NULL),
(1100, 'ka', 'აქვს თუ არა უფლება „DE“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე მძღოლს, მართოს „D“ კატეგორიის ავტომობილი მისაბმელით, რომლის ნებადართული მაქსიმალური მასა აღემატება 750 კგ-ს?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-2 პუნქტის „ზ“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ კატეგორიებად: ზ) „DE“ − „D“ კატეგორიის ავტომობილი, გადაბმული მისაბმელთან, რომლის ნებადართული მაქსიმალური მასა აღემატება 750 კგ-ს.', 0, '1', 'აქვს უფლება', 'არ აქვს უფლება', NULL, NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ „DE“ კატეგორია არის „D“-ს გაფართოებული ვერსია, რომელიც სპეციალურად მძიმე მისაბმელიანი ავტობუსებისთვისაა განკუთვნილი. თუ შენ გაქვს „DE“, ეს ავტომატურად ნიშნავს, რომ შეგიძლია მართო „D“ კატეგორიის ავტომობილი როგორც მისაბმელით, ისე მის გარეშე.', NULL),
(1100, 'ru', 'Имеет ли право водитель с правом управления транспортным средством категории «DE» управлять автомобилем категории «D» с прицепом, максимальная разрешенная масса которого превышает 750 кг?', 'Согласно подпункту «з» пункта 2 статьи 54 Закона Грузии «О дорожном движении», категория «DE» прямо включает в себя право на управление автомобилем категории «D» в составе с прицепом, максимальная разрешенная масса которого превышает 750 кг. Таким образом, водитель, имеющий данную категорию, обладает законным правом на управление таким транспортным средством.', 0, '1', 'Имеет право', 'Не имеет права', NULL, NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни: категория «DE» — это расширенная версия категории «D», которая специально предназначена для управления автобусами с тяжелыми прицепами. Если у тебя есть «DE», это автоматически дает тебе право управлять транспортным средством категории «D» как с прицепом, так и без него.', NULL),
(1100, 'en', 'Does a driver with a ''DE'' category driving license have the right to drive a ''D'' category vehicle with a trailer whose maximum authorized mass exceeds 750 kg?', 'According to Article 54, paragraph 2, subparagraph ''z'' of the Law of Georgia ''on Road Traffic'', the ''DE'' category explicitly grants the right to drive a ''D'' category vehicle combined with a trailer whose maximum authorized mass exceeds 750 kg. Therefore, a driver holding this category is legally permitted to operate such a combined vehicle.', 0, '1', 'Has the right', 'Does not have the right', NULL, NULL, 20, '{4}'::int[], NULL, 'Hello! Remember, the ''DE'' category is an extension of the ''D'' category, specifically designed for driving buses with heavy trailers. If you hold a ''DE'' license, it automatically grants you the right to operate a ''D'' category vehicle with or without a trailer.', NULL),
(1101, 'ka', '„T“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს, უფლება აქვს მართოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-2 პუნქტის „თ“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ კატეგორიებად: თ) „T“ – სასოფლო-სამეურნეო მანქანა, აგრეთვე „T“ კატეგორიის მექანიკური სატრანსპორტო საშუალება, გადაბმული მისაბმელთან. ამავე კანონია მე-5 მუხლის 69-ე პუნქტის თანახმად, სასოფლო-სამეურნეო მანქანა - სპეციალიზებული თვლიანი ან მუხლუხა მექანიკური სატრანსპორტო საშუალება, რომელიც განკუთვნილია სასოფლო-სამეურნეო, სამელიორაციო ან სატყეო სამუშაოების შესასრულებლად და რომლისთვისაც გზაზე ადამიანების გადაყვანა და ტვირთის გადაზიდვა ან ადამიანების გადასაყვანად და ტვირთის გადასაზიდად განკუთვნილი სატრანსპორტო საშუალების გზაზე ბუქსირებისათვის გამოყენება მხოლოდ დამხმარე ფუნქციაა. სასოფლო-სამეურნეო მანქანად არ ითვლება ავტომობილის ბაზაზე დამზადებული სპეციალიზებული სატრანსპორტო საშუალება.', 0, '4', 'მხოლოდ სასოფლო-სამეურნეო სამუშაოების შესასრულებლად განკუთვნილი თვლიანი ან მუხლუხა სასოფლო-სამეურნეო მანქანა', 'საგზაო-სამშენებლო სამუშაოების შესასრულებლად განკუთვნილი თვლიანი ან მუხლუხა სპეციალიზებული თვითმავალი მანქანა', 'მხოლოდ სატყეო სამუშაოების შესასრულებლად განკუთვნილი თვლიანი ან მუხლუხა სასოფლო-სამეურნეო მანქანა', 'სასოფლო-სამეურნეო, სამელიორაციო ან სატყეო სამუშაოების შესასრულებლად განკუთვნილი თვლიანი ან მუხლუხა სასოფლო-სამეურნეო მანქანა, აგრეთვე „T“ კატეგორიის მექანიკური სატრანსპორტო საშუალება, გადაბმული მისაბმელით', 20, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ „T“ კატეგორია მხოლოდ ფერმერულ საქმიანობას არ გულისხმობს. ეს კატეგორია მოიცავს სამუშაო მანქანებს, რომლებიც გამოიყენება ნიადაგის მელიორაციისთვის და სატყეო მეურნეობაშიც. ასევე, არ დაგავიწყდეს, რომ ამ უფლებით შეგიძლია მართო ტრაქტორი ან მსგავსი მანქანა, რომელსაც უკან მისაბმელი აქვს მიერთებული.', NULL),
(1101, 'ru', 'Имеет ли право лицо, обладающее правом управления транспортным средством категории «T», управлять:', 'Согласно подпункту «т» пункта 2 статьи 54 и пункту 69 статьи 5 Закона Грузии «О дорожном движении», категория «T» охватывает не только сельскохозяйственные, но и мелиоративные и лесохозяйственные машины. Также закон прямо разрешает управление транспортным средством данной категории в сцепке с прицепом.', 0, '4', 'Только колесную или гусеничную сельскохозяйственную машину, предназначенную для выполнения сельскохозяйственных работ', 'Колесную или гусеничную специализированную самоходную машину, предназначенную для выполнения дорожно-строительных работ', 'Только колесную или гусеничную сельскохозяйственную машину, предназначенную для выполнения лесохозяйственных работ', 'Колесную или гусеничную сельскохозяйственную машину, предназначенную для выполнения сельскохозяйственных, мелиоративных или лесохозяйственных работ, а также механическое транспортное средство категории «T» с прицепом', 20, '{7}'::int[], NULL, 'Привет! Запомни, что категория «T» — это не только полевые работы. Она охватывает технику для мелиорации (улучшения земель) и лесного хозяйства. Также важно помнить, что наличие этой категории официально разрешает тебе управлять такой техникой вместе с прицепом, что очень полезно в работе!', NULL),
(1101, 'en', 'A person entitled to drive a category ''T'' vehicle is entitled to drive:', 'According to Article 54, Paragraph 2, Subparagraph ''T'' and Article 5, Paragraph 69 of the Law of Georgia ''On Road Traffic'', the category ''T'' includes machines intended for agricultural, land reclamation, and forestry work. The law also explicitly permits driving these vehicles when coupled with a trailer.', 0, '4', 'Only a wheeled or tracked agricultural machine intended for agricultural work', 'A wheeled or tracked specialized self-propelled machine intended for road construction work', 'Only a wheeled or tracked agricultural machine intended for forestry work', 'A wheeled or tracked agricultural machine intended for agricultural, land reclamation, or forestry work, as well as a category ''T'' mechanical vehicle with a coupled trailer', 20, '{7}'::int[], NULL, 'Hello! Remember that category ''T'' is not just about farming. It covers specialized machines used for land reclamation and forestry as well. Also, keep in mind that this license officially allows you to operate these vehicles while towing a trailer, which is essential for your daily work!', NULL),
(1103, 'ka', '„S“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს, უფლება აქვს მართოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-2 პუნქტის „ი“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ კატეგორიებად: ი) „S“ − სპეციალიზებული თვითმავალი მანქანა, აგრეთვე „S“ კატეგორიის მექანიკური სატრანსპორტო საშუალება, გადაბმული მისაბმელთან. ამავე კანონია მე-5 მუხლის 79-ე პუნქტის თანახმად, სპეციალიზებული თვითმავალი მანქანა - თვლიანი ან მუხლუხა მექანიკური სატრანსპორტო საშუალება, რომელიც განკუთვნილია საგზაო-სამშენებლო სამუშაოების შესასრულებლად და რომლის კონსტრუქციული სიჩქარე არის 6 კმ/სთ-ზე მეტი და 45 კმ/სთ-ზე ნაკლები. სპეციალიზებულ თვითმავალ მანქანად არ ითვლება ავტომობილის ბაზაზე დამზადებული სპეციალიზებული სატრანსპორტო საშუალება.', 0, '2', 'სასოფლო-სამეურნეო სამუშაოების შესასრულებლად განკუთვნილი თვლიანი ან მუხლუხა სასოფლო-სამეურნეო მანქანა', 'საგზაო-სამშენებლო სამუშაოების შესასრულებლად განკუთვნილი თვლიანი ან მუხლუხა სპეციალიზებული თვითმავალი მანქანა, რომლის კონსტრუქციული სიჩქარე არის 6 კმ/სთ-ზე მეტი და 45 კმ/სთ-ზე ნაკლები, აგრეთვე „S“ კატეგორიის მექანიკური სატრანსპორტო საშუალება, გადაბმული მისაბმელთან', '„S“ კატეგორიის სატრანსპორტო საშუალებას საქართველოს კანონმდებლობა არ ითვალისწინებს', NULL, 20, '{7}'::int[], NULL, 'გამარჯობა! „S“ კატეგორია სპეციალურად შექმნილია მძიმე საგზაო-სამშენებლო ტექნიკისთვის. დაიმახსოვრე: ეს არ არის სასოფლო-სამეურნეო ტრაქტორი. თუ ტექნიკა არის საგზაო-სამშენებლო, მოძრაობს 6-დან 45 კმ/სთ-მდე და შეგიძლია მიაბა მისაბმელი, მაშინ ეს ზუსტად შენი კატეგორიაა!', NULL),
(1103, 'ru', 'Имеет ли право лицо, имеющее право на управление транспортным средством категории «S», управлять:', 'Согласно подпункту «и» пункта 2 статьи 54 Закона Грузии «О дорожном движении», категория «S» определяется как специализированная самоходная машина. В соответствии с пунктом 79 статьи 5 этого же Закона, это колесное или гусеничное механическое транспортное средство, предназначенное для дорожно-строительных работ, с конструктивной скоростью от 6 до 45 км/ч.', 0, '2', 'Колесную или гусеничную сельскохозяйственную машину, предназначенную для выполнения сельскохозяйственных работ', 'Колесную или гусеничную специализированную самоходную машину, предназначенную для выполнения дорожно-строительных работ, конструктивная скорость которой составляет более 6 км/ч и менее 45 км/ч, а также механическое транспортное средство категории «S», сцепленное с прицепом', 'Законодательство Грузии не предусматривает категорию «S» для транспортных средств', NULL, 20, '{7}'::int[], NULL, 'Привет! Категория «S» создана специально для тяжелой дорожно-строительной техники. Запомни: это не сельскохозяйственный трактор. Если техника предназначена для дорожно-строительных работ, имеет скорость от 6 до 45 км/ч и может буксировать прицеп — это именно твоя категория!', NULL),
(1103, 'en', 'A person authorized to drive a vehicle of category "S" has the right to drive:', 'According to Article 54, paragraph 2, subparagraph ''i'' of the Law of Georgia "On Road Traffic", category "S" is defined as a specialized self-propelled vehicle. As per Article 5, paragraph 79, it is a wheeled or tracked mechanical vehicle intended for road construction work with a design speed exceeding 6 km/h but less than 45 km/h.', 0, '2', 'A wheeled or tracked agricultural vehicle intended for agricultural work', 'A wheeled or tracked specialized self-propelled vehicle intended for road construction work with a design speed of more than 6 km/h and less than 45 km/h, as well as a mechanical vehicle of category "S" coupled with a trailer', 'Georgian legislation does not provide for a category "S" vehicle', NULL, 20, '{7}'::int[], NULL, 'Hello! Category "S" is specifically designed for heavy road construction machinery. Remember: this is not an agricultural tractor. If the machinery is intended for road construction, has a design speed between 6 and 45 km/h, and can be coupled with a trailer, then this is exactly your category!', NULL),
(1104, 'ka', '„ტრამვაი“-ს კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს, უფლება აქვს მართოს მხოლოდ:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-2 პუნქტის „კ“ ქვეპუნქტის თანახმად, სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ კატეგორიებად: კ) ტრამვაი.', 0, '3', 'ტრამვაი და ტროლეიბუსი', 'ტრამვაი და ავტობუსი', 'მხოლოდ ტრამვაი', NULL, 20, '{8}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მართვის მოწმობაში არსებული კატეგორიები მკაცრად განსაზღვრავს, რისი მართვა შეგიძლია. რადგან „ტრამვაი“ ცალკე კატეგორიაა, ის არ გაძლევს ავტობუსის ან ტროლეიბუსის მართვის უფლებას. ასე რომ, სწორი პასუხია: მხოლოდ ტრამვაი!', NULL),
(1104, 'ru', 'Имеет ли право лицо, имеющее право на управление транспортным средством категории «Трамвай», управлять иными видами транспорта?', 'Согласно подпункту «к» пункта 2 статьи 54 Закона Грузии «О дорожном движении», «Трамвай» определен как отдельная категория транспортных средств. Следовательно, категория «Трамвай», указанная в водительском удостоверении, дает право на управление только этим конкретным типом транспортного средства.', 0, '3', 'Трамвай и троллейбус', 'Трамвай и автобус', 'Только трамвай', NULL, 20, '{8}'::int[], NULL, 'Привет! Помни, что категории в водительском удостоверении строго ограничивают список транспортных средств, которыми ты можешь управлять. Так как «Трамвай» — это отдельная категория, она не дает права управлять автобусом или троллейбусом. Поэтому правильный ответ: только трамвай!', NULL),
(1104, 'en', 'A person entitled to drive a ''Tram'' category vehicle has the right to drive only:', 'According to Article 54, paragraph 2, subparagraph ''k'' of the Law of Georgia ''on Road Traffic'', ''Tram'' is defined as a distinct category. Consequently, the ''Tram'' category specified in a driver''s license grants the right to operate only this specific type of vehicle.', 0, '3', 'Tram and trolleybus', 'Tram and bus', 'Only tram', NULL, 20, '{8}'::int[], NULL, 'Hello! Remember that the categories on your driver''s license strictly define what you are allowed to drive. Since ''Tram'' is a separate category, it does not give you the right to drive a bus or a trolleybus. Therefore, the correct answer is: only tram!', NULL),
(1105, 'ka', '„A1“ ქვეკატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს, უფლება აქვს მართოს 11 კვტ-მდე მაქსიმალური სიმძლავრის მქონე მოტოციკლი, რომლის ძრავას მოცულობა:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-3 პუნქტის „ა“ ქვეპუნქტის თანახმად, „A“, „B“, „C“, „CE“, „D“ და „DE“ კატეგორიების ფარგლებში დაწესებული სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ ქვეკატეგორიებად: ა) „A1“ − მოტოციკლი, რომლის ძრავას მუშა მოცულობა არ აღემატება 125 სმ3-ს, ხოლო მაქსიმალური სიმძლავრე − 11 კვტ-ს (მსუბუქი მოტოციკლი).', 0, '1', 'არ აღემატება 125 სმ3-ს', 'აღემატება 125 სმ3-ს, მაგრამ არ აღემატება 150 სმ3-ს', 'აღემატება 125 სმ3-ს, მაგრამ არ აღემატება 200 სმ3-ს', NULL, 20, '{2}'::int[], NULL, 'გამარჯობა! მოკლედ რომ ვთქვათ, A1 კატეგორია არის „მსუბუქი მოტოციკლის“ კატეგორია. კანონი მკაცრად ადგენს ორ ზღვარს: სიმძლავრე უნდა იყოს მაქსიმუმ 11 კვტ და ძრავის მოცულობა მაქსიმუმ 125 სმ3. თუ ორივე პირობა დაცულია, მაშინ შეგიძლია მართო.', NULL),
(1105, 'ru', 'Имеет ли право лицо, имеющее право на управление транспортным средством подкатегории «A1», управлять мотоциклом с максимальной мощностью до 11 кВт, рабочий объем двигателя которого:', 'Согласно пункту 3(а) статьи 54 Закона Грузии «О дорожном движении», подкатегория A1 определяется как мотоцикл, рабочий объем двигателя которого не превышает 125 см³, а максимальная мощность не превышает 11 кВт.', 0, '1', 'Не превышает 125 см³', 'Превышает 125 см³, но не превышает 150 см³', 'Превышает 125 см³, но не превышает 200 см³', NULL, 20, '{2}'::int[], NULL, 'Привет! Если коротко, категория A1 — это категория для легких мотоциклов. Закон устанавливает два жестких лимита: мощность до 11 кВт и объем двигателя до 125 см³. Если оба условия соблюдены, вы можете законно управлять таким транспортным средством.', NULL),
(1105, 'en', 'A person holding a driving license for subcategory ''A1'' is allowed to drive a motorcycle with a maximum power of up to 11 kW, whose engine displacement:', 'According to Article 54, paragraph 3, subparagraph ''a'' of the Law of Georgia ''on Road Traffic'', subcategory A1 is defined as a motorcycle with an engine displacement not exceeding 125 cm³ and a maximum power not exceeding 11 kW.', 0, '1', 'Does not exceed 125 cm³', 'Exceeds 125 cm³ but does not exceed 150 cm³', 'Exceeds 125 cm³ but does not exceed 200 cm³', NULL, 20, '{2}'::int[], NULL, 'Hello! In short, subcategory A1 is the ''light motorcycle'' category. The law sets two strict limits: a maximum power of 11 kW and a maximum engine displacement of 125 cm³. If both conditions are met, you are legally allowed to ride.', NULL),
(1109, 'ka', '„D1“ ქვეკატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე მძღოლს, უფლება აქვს მართოს მგზავრთა გადასაყვანად განკუთვნილი ავტომობილი, რომლის:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-3 პუნქტის „დ“ ქვეპუნქტის თანახმად, „A“, „B“, „C“, „CE“, „D“ და „DE“ კატეგორიების ფარგლებში დაწესებული სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ ქვეკატეგორიებად: დ) „D1“ − ავტომობილი, რომელიც განკუთვნილია მგზავრთა გადასაყვანად, რომლის დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა, აღემატება 8-ს, მაგრამ არ აღემატება 16-ს და რომლის სიგრძე არ აღემატება 8 მეტრს, აგრეთვე „D1“ ქვეკატეგორიის ავტომობილი, გადაბმული მისაბმელთან, რომლის ნებადართული მაქსიმალური მასა არ აღემატება 750 კგ-ს.', 0, '1', 'დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა აღემატება 8-ს, მაგრამ არ აღემატება 16-ს, ხოლო სიგრძე არ აღემატება 8 მეტრს', 'დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა აღემატება 16-ს, მაგრამ არ აღემატება 30-ს, ხოლო სიგრძე არ აღემატება 8 მეტრს', 'დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა არ აღემატება 8-ს, ხოლო სიგრძე არ აღემატება 5 მეტრს', NULL, 20, '{6}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე: D1 კატეგორია არის პატარა ავტობუსებისთვის. მთავარია ორი პირობა: 9-დან 16-მდე მგზავრი და მაქსიმუმ 8 მეტრი სიგრძე. ყველაფერი, რაც ამაზე დიდია, უკვე D კატეგორიაა.', NULL),
(1109, 'ru', 'Водитель, имеющий право на управление транспортным средством подкатегории «D1», имеет право управлять автомобилем, предназначенным для перевозки пассажиров, у которого:', 'Согласно подпункту «д» пункта 3 статьи 54 Закона Грузии «О дорожном движении», подкатегория «D1» включает автомобили, предназначенные для перевозки пассажиров, количество сидячих мест в которых (помимо места водителя) составляет от 9 до 16, а длина не превышает 8 метров.', 0, '1', 'количество сидячих мест, помимо места водителя, превышает 8, но не превышает 16, а длина не превышает 8 метров', 'количество сидячих мест, помимо места водителя, превышает 16, но не превышает 30, а длина не превышает 8 метров', 'количество сидячих мест, помимо места водителя, не превышает 8, а длина не превышает 5 метров', NULL, 20, '{6}'::int[], NULL, 'Привет! Запомни: категория D1 предназначена для микроавтобусов. Главные условия: от 9 до 16 пассажирских мест и длина не более 8 метров. Все, что больше этого — это уже категория D.', NULL),
(1109, 'en', 'A driver with the right to drive a vehicle of the subcategory "D1" has the right to drive a vehicle intended for passenger transport, which has:', 'According to Article 54, Paragraph 3, Subparagraph "d" of the Law of Georgia "on Road Traffic", subcategory "D1" includes vehicles intended for passenger transport with more than 8 but no more than 16 passenger seats, and a total length not exceeding 8 meters.', 0, '1', 'the number of seats, excluding the driver''s seat, exceeds 8 but does not exceed 16, and the length does not exceed 8 meters', 'the number of seats, excluding the driver''s seat, exceeds 16 but does not exceed 30, and the length does not exceed 8 meters', 'the number of seats, excluding the driver''s seat, does not exceed 8, and the length does not exceed 5 meters', NULL, 20, '{6}'::int[], NULL, 'Hi! Remember: D1 is for minibuses. The key conditions are: between 9 and 16 passenger seats and a maximum length of 8 meters. Anything larger than this falls into the D category.', NULL),
(1110, 'ka', '„D1“ ქვეკატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე მძღოლს, აგრეთვე უფლება აქვს მართოს „D1“ ქვეკატეგორიის ავტომობილი მისაბმელით, რომლის ნებადართული მაქსიმალური მასა:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-3 პუნქტის „დ“ ქვეპუნქტის თანახმად, „A“, „B“, „C“, „CE“, „D“ და „DE“ კატეგორიების ფარგლებში დაწესებული სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ ქვეკატეგორიებად: დ) „D1“ − ავტომობილი, რომელიც განკუთვნილია მგზავრთა გადასაყვანად, რომლის დასასხდომი ადგილების რაოდენობა, გარდა მძღოლის ადგილისა, აღემატება 8-ს, მაგრამ არ აღემატება 16-ს და რომლის სიგრძე არ აღემატება 8 მეტრს, აგრეთვე „D1“ ქვეკატეგორიის ავტომობილი, გადაბმული მისაბმელთან, რომლის ნებადართული მაქსიმალური მასა არ აღემატება 750 კგ-ს.', 0, '2', 'აღემატება 1200 კგ-ს', 'არ აღემატება 750 კგ-ს', 'აღემატება 750 კგ-ს, მაგრამ არ აღემატება 1200 კგ-ს', NULL, 20, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეთ: „D1“ კატეგორიით თქვენ შეგიძლიათ აბათოთ მსუბუქი მისაბმელი, რომლის მაქსიმალური წონა არ აღემატება 750 კგ-ს. ეს არის ზღვარი, რომელიც კანონით არის დადგენილი უსაფრთხოების მიზნით.', NULL),
(1110, 'ru', 'Имеет ли право водитель, имеющий право управления транспортным средством подкатегории «D1», управлять автомобилем подкатегории «D1» с прицепом, максимальная разрешенная масса которого:', 'Согласно подпункту «д» пункта 3 статьи 54 Закона Грузии «О дорожном движении», право управления транспортным средством подкатегории «D1» включает в себя управление автомобилем данной подкатегории в сцепке с прицепом, максимальная разрешенная масса которого не превышает 750 кг.', 0, '2', 'Превышает 1200 кг', 'Не превышает 750 кг', 'Превышает 750 кг, но не превышает 1200 кг', NULL, 20, '{6}'::int[], NULL, 'Привет! Запомните: категория «D1» позволяет вам буксировать легкий прицеп, вес которого не превышает 750 кг. Это законодательно установленный лимит для обеспечения безопасности дорожного движения.', NULL),
(1110, 'en', 'Does a driver with the right to drive a vehicle of subcategory ''D1'' also have the right to drive a ''D1'' subcategory vehicle with a trailer, whose maximum authorized mass:', 'According to Article 54, Paragraph 3, Subparagraph ''d'' of the Law of Georgia ''On Road Traffic'', the right to drive a vehicle of subcategory ''D1'' includes driving such a vehicle coupled with a trailer, provided that the maximum authorized mass of the trailer does not exceed 750 kg.', 0, '2', 'Exceeds 1200 kg', 'Does not exceed 750 kg', 'Exceeds 750 kg, but does not exceed 1200 kg', NULL, 20, '{6}'::int[], NULL, 'Hello! Remember: with a ''D1'' license, you are allowed to tow a light trailer with a maximum authorized mass not exceeding 750 kg. This is the legal limit set to ensure road safety.', NULL),
(1112, 'ka', 'აქვს თუ არა უფლება „D1E“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე მძღოლს, მართოს „D1“ კატეგორიის ავტომობილი მისაბმელით, რომლის ნებადართული მაქსიმალური მასა აღემატება 750 კგ-ს, თუ ასეთი შემადგენლობის საერთო ნებადართული მაქსიმალური მასა არ აღემატება 12000 კგ-ს?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 54-ე მუხლის მე-3 პუნქტის „ვ“ ქვეპუნქტის თანახმად, „A“, „B“, „C“, „CE“, „D“ და „DE“ კატეგორიების ფარგლებში დაწესებული სატრანსპორტო საშუალებები, რომელთა სამართავად სავალდებულოა შესაბამისი მართვის უფლების მოპოვება, იყოფა შემდეგ ქვეკატეგორიებად: ვ) „D1E“ − „D1“ ქვეკატეგორიის ავტომობილი, გადაბმული მისაბმელთან, რომელიც არ არის განკუთვნილი მგზავრთა გადასაყვანად და რომლის ნებადართული მაქსიმალური მასა აღემატება 750 კგ-ს, მაგრამ არ აღემატება ავტომობილის დაუტვირთავ მასას, ხოლო ასეთი შემადგენლობის საერთო ნებადართული მაქსიმალური მასა არ აღემატება 12 000 კგ-ს.', 0, '2', 'არ აქვს უფლება', 'აქვს უფლება', NULL, NULL, 20, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, „E“ კატეგორია ნიშნავს მისაბმელთან მუშაობის უფლებას. რადგან გაქვს „D1E“, ეს ავტომატურად ნიშნავს, რომ შეგიძლია მართო „D1“ კატეგორიის ავტობუსი მძიმე მისაბმელით, თუ დაცულია 12-ტონიანი ზღვარი. ასე რომ, პასუხი 2 სწორია!', NULL),
(1112, 'ru', 'Имеет ли право водитель с категорией «D1E» управлять автомобилем категории «D1» с прицепом, максимальная разрешенная масса которого превышает 750 кг, если общая максимальная разрешенная масса такого состава не превышает 12 000 кг?', 'Согласно подпункту «в» пункта 3 статьи 54 Закона Грузии «О дорожном движении», категория «D1E» дает водителю право управлять транспортным средством подкатегории «D1» с прицепом (массой более 750 кг), при условии, что общая максимальная разрешенная масса состава не превышает 12 000 кг.', 0, '2', 'Не имеет права', 'Имеет право', NULL, NULL, 20, '{6}'::int[], NULL, 'Привет! Запомни: категория «E» дает право на управление составом с прицепом. Имея «D1E», ты получаешь право управлять автомобилем «D1» с прицепом тяжелее 750 кг, если общая масса автопоезда не выше 12 тонн. Так что вариант 2 — правильный!', NULL),
(1112, 'en', 'Does a driver holding a ''D1E'' category license have the right to operate a ''D1'' category vehicle with a trailer whose maximum authorized mass exceeds 750 kg, provided the total maximum authorized mass of the combination does not exceed 12,000 kg?', 'According to sub-paragraph (f) of Article 54, paragraph 3 of the Law of Georgia ''On Road Traffic'', the ''D1E'' category grants the driver the right to operate a ''D1'' sub-category vehicle with a trailer (exceeding 750 kg), provided the total maximum authorized mass of the combination does not exceed 12,000 kg.', 0, '2', 'Does not have the right', 'Has the right', NULL, NULL, 20, '{6}'::int[], NULL, 'Hello! Remember, the ''E'' category grants you the right to handle a trailer. Since you hold a ''D1E'' license, you are legally permitted to drive a ''D1'' vehicle with a heavy trailer, provided the total weight limit of 12,000 kg is respected. Therefore, answer 2 is correct!', NULL),
(1113, 'ka', '„A“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს, აგრეთვე რომელი ქვეკატეგორიის სატრანსპორტო საშუალების მართვის უფლება აქვს?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 56-ე მუხლის პირველი პუნქტის თანახმად, „A“, „B“, „C“ ან „D“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს აგრეთვე უფლება აქვს, მართოს მინიჭებული კატეგორიის ფარგლებში დაწესებული „A1“, „B1“, „C1“ ან „D1“ ქვეკატეგორიის სატრანსპორტო საშუალებაც.', 0, '1', '„A1“', '„A1“ და „B1“', '„B1“', '„D1“', 20, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ უფრო მაღალი კატეგორია ავტომატურად განიჭებს უფლებას მართო მასთან დაკავშირებული ქვეკატეგორია. რადგან „A1“ არის „A“ კატეგორიის ქვეკატეგორია, შენ შეგიძლია მისი მართვა დამატებითი გამოცდის გარეშე.', NULL),
(1113, 'ru', 'Лицо, имеющее право на управление транспортным средством категории «A», имеет право также управлять транспортным средством какой подкатегории?', 'Согласно пункту 1 статьи 56 Закона Грузии «О дорожном движении», право на управление транспортным средством категории «A» автоматически включает право на управление транспортным средством подкатегории «A1».', 0, '1', '«A1»', '«A1» и «B1»', '«B1»', '«D1»', 20, '{2}'::int[], NULL, 'Привет! Запомни, что наличие высшей категории автоматически дает право управлять соответствующей подкатегорией. Поскольку «A1» является подкатегорией «A», ты можешь управлять такими транспортными средствами без сдачи дополнительного экзамена.', NULL),
(1113, 'en', 'A person who has the right to drive a category "A" vehicle also has the right to drive a vehicle of which subcategory?', 'According to Article 56, Paragraph 1 of the Law of Georgia "on Road Traffic", the right to drive a category "A" vehicle automatically includes the right to drive a subcategory "A1" vehicle.', 0, '1', '"A1"', '"A1" and "B1"', '"B1"', '"D1"', 20, '{2}'::int[], NULL, 'Hi! Remember that holding a higher category automatically grants you the right to drive its associated subcategory. Since "A1" is a subcategory of "A", you are permitted to drive those vehicles without needing an additional exam.', NULL),
(1116, 'ka', '„D“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს, აგრეთვე რომელი ქვეკატეგორიის სატრანსპორტო საშუალების მართვის უფლება აქვს?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 56-ე მუხლის პირველი პუნქტის თანახმად, „A“, „B“, „C“ ან „D“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს აგრეთვე უფლება აქვს, მართოს მინიჭებული კატეგორიის ფარგლებში დაწესებული „A1“, „B1“, „C1“ ან „D1“ ქვეკატეგორიის სატრანსპორტო საშუალებაც.', 0, '4', '„A1“', '„C1“ და „D1“', '„D1“ და „D1E“', '„D1“', 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ უფრო მაღალი კატეგორია ავტომატურად გაძლევს უფლებას მართო მასთან დაკავშირებული ქვეკატეგორია. რადგან „D“ ავტობუსების მართვის უფლებას გაძლევს, კანონი ავტომატურად განიჭებს უფლებას მართო „D1“ (მცირე ავტობუსი).', NULL),
(1116, 'ru', 'Имеет ли право лицо, обладающее правом на управление транспортным средством категории «D», управлять транспортным средством какой-либо другой подкатегории?', 'Согласно пункту 1 статьи 56 Закона Грузии «О дорожном движении», лицо, имеющее право на управление транспортным средством категории «D», также имеет право управлять транспортным средством подкатегории «D1».', 0, '4', '«A1»', '«C1» и «D1»', '«D1» и «D1E»', '«D1»', 20, '{4}'::int[], NULL, 'Привет! Запомни: более высокая категория автоматически дает тебе право управлять соответствующей подкатегорией. Так как категория «D» дает право управлять большими автобусами, закон автоматически разрешает тебе управлять подкатегорией «D1» (микроавтобусы).', NULL),
(1116, 'en', 'Does a person authorized to drive a category "D" vehicle have the right to drive a vehicle of which subcategory?', 'According to Article 56, paragraph 1 of the Law of Georgia "On Road Traffic", a person authorized to drive a category "D" vehicle also has the right to drive a subcategory "D1" vehicle.', 0, '4', '"A1"', '"C1" and "D1"', '"D1" and "D1E"', '"D1"', 20, '{4}'::int[], NULL, 'Hello! Remember that a higher category automatically gives you the right to drive the associated subcategory. Since category "D" authorizes you to drive buses, the law automatically grants you the right to drive subcategory "D1" (minibuses).', NULL),
(1118, 'ka', '„DE“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს, აგრეთვე რომელი ქვეკატეგორიის სატრანსპორტო საშუალების მართვა შეუძლია?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 56-ე მუხლის მე-2 პუნქტის თანახმად, „CE“ ან „DE“ კატეგორიის სატრანსპორტო საშუალების მართვის უფლების მქონე პირს აგრეთვე უფლება აქვს, მართოს მინიჭებული კატეგორიის ფარგლებში დაწესებული „C1E“ ან „D1E“ ქვეკატეგორიის სატრანსპორტო საშუალებაც.', 0, '2', '„C1E“', '„D1E“', '„D1E“ და „C1E“', NULL, 20, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ „DE“ კატეგორია მოიცავს „D1E“ ქვეკატეგორიას, რადგან ის უფრო მაღალი დონის უფლებაა. კანონის თანახმად, მაღალი კატეგორიის მქონე მძღოლს ავტომატურად აქვს უფლება მართოს შესაბამისი ქვეკატეგორიის სატრანსპორტო საშუალება.', NULL),
(1118, 'ru', 'Лицо, имеющее право на управление транспортным средством категории «DE», какими еще подкатегориями транспортных средств имеет право управлять?', 'Согласно пункту 2 статьи 56 Закона Грузии «О дорожном движении», лицо, имеющее право на управление транспортным средством категории «DE», также имеет право управлять транспортным средством подкатегории «D1E».', 0, '2', '«C1E»', '«D1E»', '«D1E» и «C1E»', NULL, 20, '{4}'::int[], NULL, 'Привет! Запомни: категория «DE» включает в себя подкатегорию «D1E», так как это более высокая ступень прав. Согласно закону, водитель, обладающий высокой категорией, автоматически получает право управлять транспортными средствами соответствующей подкатегории.', NULL),
(1118, 'en', 'A person entitled to drive a category ''DE'' vehicle, what other subcategory vehicle is also entitled to drive?', 'According to Article 56, Paragraph 2 of the Law of Georgia ''On Road Traffic'', a person entitled to drive a category ''DE'' vehicle is also authorized to operate a vehicle of subcategory ''D1E''.', 0, '2', '''C1E''', '''D1E''', '''D1E'' and ''C1E''', NULL, 20, '{4}'::int[], NULL, 'Hello! Remember that the ''DE'' category includes the ''D1E'' subcategory, as it is a higher level of licensing. According to the law, a driver with a higher category automatically has the right to operate vehicles in the corresponding subcategory.', NULL),
(1135, 'ka', 'მოტოციკლეტებით სასწავლო სვლა ნებადართულია:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 61-ე მუხლის მე-7 პუნქტის თანახმად, მოტოციკლით, სპეციალიზებული თვითმავალი მანქანითა და სასოფლო-სამეურნეო მანქანით სასწავლო სვლა ნებადართულია მხოლოდ დახურულ მოედანსა და ავტოდრომზე.', 0, '3', 'დაუსახლებელი პუქტის გზებზე', 'დასახლებული პუნქტის გარეუბანში', 'მხოლოდ დახურულ მოედანზე ან ავტოდრომზე', NULL, 20, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოტოციკლით სწავლისას ბალანსის შენარჩუნება რთულია, ამიტომ კანონი მოითხოვს, რომ ვარჯიში დაიწყო უსაფრთხო, დახურულ სივრცეში, სადაც სხვა მანქანები არ გიშლიან ხელს.', NULL),
(1135, 'ru', 'Учебная езда на мотоциклах разрешена:', 'Согласно пункту 7 статьи 61 Закона Грузии «О дорожном движении», учебная езда на мотоцикле, специализированном самоходном средстве и сельскохозяйственной машине разрешается только на закрытой площадке или автодроме для исключения рисков безопасности участников дорожного движения.', 0, '3', 'На дорогах вне населенных пунктов', 'На окраине населенного пункта', 'Только на закрытой площадке или автодроме', NULL, 20, '{2}'::int[], NULL, 'Привет! Помни, что на мотоцикле сложнее удерживать равновесие, поэтому закон требует начинать обучение в безопасном закрытом пространстве, где другие машины не будут создавать препятствий.', NULL),
(1135, 'en', 'Learning to drive a motorcycle is permitted:', 'According to Article 61, Paragraph 7 of the Law of Georgia ''on Road Traffic'', learning to drive a motorcycle, specialized self-propelled vehicle, or agricultural machinery is permitted only on a closed area or driving range to mitigate risks to the safety of road users.', 0, '3', 'On roads outside built-up areas', 'On the outskirts of a built-up area', 'Only on a closed area or driving range', NULL, 20, '{2}'::int[], NULL, 'Hi! Remember, balancing a motorcycle can be tricky, so the law requires you to start your practice in a safe, closed area where other vehicles won''t get in your way.', NULL),
(1165, 'ka', 'მოცემულ სიტუაციაში, ვალდებულია თუ არა ისრის მიმართულებით მოძრავი ავტომობილის მძღოლი ჩართოს შესაბამისი მიმართულების მოხვევის შუქ-მაჩვენებელი, ხოლო თუ ის არ არის ან გამოსულია მწყობრიდან, ანიშნოს ხელით?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის მე-4 თავის (მიმთითებელი ნიშნები) 4.1.2 პუნქტისა და ამავე პუნქტის შენიშვნის „ა“ ქვეპუნქტის თანახმად, საგზაო ნიშანი 4.1.2 „მოძრაობა მარჯვნივ“ რთავს მხოლოდ ისრებით ნაჩვენები მიმართულებებით მოძრაობის ნებას. ამავე კანონის 32-ე მუხლის მე-2 პუნქტის თანახმად, მანევრის დაწყებამდე მძღოლი ვალდებულია ჩართოს შესაბამისი მიმართულების მოხვევის შუქ-მაჩვენებელი, ხოლო თუ ის არ არის ან გამოსულია მწყობრიდან − ანიშნოს ხელით.', 1, '1', 'ვალდებულია', 'არ არის ვალდებული', NULL, NULL, 16, '{8}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ შენი მანევრი სხვა მძღოლებისთვის პროგნოზირებადი უნდა იყოს. ნიშანი გზავნის მიმართულებას მიგვითითებს, მაგრამ შენს განზრახვას სხვებს შუქ-მაჩვენებელი (ან ხელი) ამცნობს. ეს უსაფრთხოების მთავარი წესია!', 'ticket_media/new/ticketIMG-1165.jpg'),
(1165, 'ru', 'В данной ситуации обязан ли водитель автомобиля, движущегося в направлении стрелки, включить соответствующий указатель поворота, а в случае его отсутствия или неисправности — подать сигнал рукой?', 'Согласно пункту 2 статьи 32 Закона Грузии «О дорожном движении», перед началом любого маневра, включая движение в направлении, указанном дорожным знаком 4.1.2 «Движение направо», водитель обязан заранее информировать других участников движения о своих намерениях с помощью световых указателей поворота, а в случае их неисправности — жестом руки.', 1, '1', 'Обязан', 'Не обязан', NULL, NULL, 16, '{8}'::int[], NULL, 'Привет! Помни, что твой маневр должен быть предсказуемым для других водителей. Дорожный знак указывает направление, но именно включенный поворотник (или сигнал рукой) сообщает о твоих намерениях окружающим. Это важнейшее правило безопасности!', 'ticket_media/new/ticketIMG-1165.jpg'),
(1165, 'en', 'In this situation, is the driver of a vehicle moving in the direction of the arrow required to switch on the appropriate turn signal, or if it is absent or malfunctioning, signal by hand?', 'According to Article 32, Paragraph 2 of the Law of Georgia ''on Road Traffic'', before starting any maneuver, including movement in the direction indicated by road sign 4.1.2 ''Move right'', the driver is obliged to provide advance notice to other road users using turn signals, or by hand in case of their malfunction.', 1, '1', 'Required', 'Not required', NULL, NULL, 16, '{8}'::int[], NULL, 'Hello! Remember, your maneuver must be predictable for other drivers. The road sign indicates the direction, but the turn signal (or hand signal) communicates your intentions to others. It is a fundamental rule for road safety!', 'ticket_media/new/ticketIMG-1165.jpg'),
(1272, 'ka', 'რა მიმართულებით მოძრაობის გაგრძელების უფლება აქვს „D1“ ქვეკატეგორიის ავტომობილის მძღოლს ავტომაგისტრალის ამ მონაკვეთზე?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 33-ე მუხლის მე-7 პუნქტის „ე“ ქვეპუნქტის თანახმად, გარდა ამ კანონით დადგენილი შემთხვევებისა, დაუსახლებელ პუნქტებში, აგრეთვე დასახლებულ პუნქტებში გზის იმ მონაკვეთზე, რომელზეც შესაბამისი ნიშნით მოძრაობა დაშვებულია 60 კმ/ზე მეტი სიჩქარით, ნებადართულია „D1“ და „D1E“ ქვეკატეგორიის სატრანსპორტო საშუალების მოძრაობა ყველა გზაზე არაუმეტეს 80კმ/სთ სიჩქარით. ამავე კანონის პირველი დანართის მე-4 თავის (მიმთითებელი ნიშნები) 4.6 პუნქტის თანახმად 4.6 „მინიმალური სიჩქარის შეზღუდვა” - ადგენს გზაზე მოძრაობის მინიმალური სიჩქარის ზღვარს. ნიშნის მოქმედება ვრცელდება ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას − დასახლებული პუნქტის ბოლომდე. ამავე დანართის მე-8 თავის (დამატებითი ინფორმაციის ნიშნები (დაფები)) 8.14 პუნქტის თანახმად 8.14 „მოძრაობის ზოლი” - მიუთითებს მოძრაობის ზოლს, რომელზედაც ვრცელდება ნიშნის ან შუქნიშნის მოქმედება. დაფა თავსდება მოძრაობის ზოლის ზემოთ.', 1, '2', 'მხოლოდ A მიმართულებით', 'მხოლოდ B მიმართულებით', 'როგორც A, ასევე B მიმართულებით', NULL, 26, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როდესაც ნიშანს („მინიმალური სიჩქარის შეზღუდვა“) თან ახლავს დაფა „მოძრაობის ზოლი“, ის გვეუბნება, რომ ეს შეზღუდვა ეხება კონკრეტულად იმ ზოლს, რომლის თავზეც ნიშანია განთავსებული. ამიტომ, შენ უნდა დარჩე იმ ზოლში, სადაც ნიშანი გიჩვენებს და არ შეცვალო ტრაექტორია შეზღუდვის საწინააღმდეგოდ. ამიტომ სწორი პასუხია B.', 'ticket_media/new/ticketIMG-1272.jpg'),
(1272, 'ru', 'В каком направлении имеет право продолжить движение водитель транспортного средства подкатегории «D1» на данном участке автомагистрали?', 'Согласно пунктам 4.6 и 8.14 Приложения №1 Закона Грузии «О дорожном движении», дорожный знак 4.6 «Ограничение минимальной скорости» в сочетании с табличкой 8.14 «Полоса движения» обязывает водителя двигаться с указанной скоростью строго по той полосе, над которой установлен знак. Поскольку знак указывает на конкретную полосу, водитель обязан соблюдать предписание и следовать по траектории, указанной знаком (B).', 1, '2', 'Только в направлении А', 'Только в направлении B', 'Как в направлении А, так и в направлении B', NULL, 26, '{6}'::int[], NULL, 'Привет! Запомни, когда знак «Ограничение минимальной скорости» сопровождается табличкой «Полоса движения», это значит, что ограничение действует строго для той полосы, над которой висит знак. Поэтому тебе нужно двигаться именно по этой полосе, не меняя траекторию в нарушение знака. Именно поэтому правильный ответ — B.', 'ticket_media/new/ticketIMG-1272.jpg'),
(1272, 'en', 'In which direction is the driver of a ''D1'' subcategory vehicle allowed to continue driving on this section of the motorway?', 'According to items 4.6 and 8.14 of Annex 1 of the Law of Georgia ''on Road Traffic'', road sign 4.6 ''Minimum speed limit'' combined with plate 8.14 ''Traffic lane'' obliges the driver to continue driving at the indicated speed only within the lane over which the sign is placed. Since the sign applies to a specific lane, the driver must comply with the restriction and follow the path indicated by the sign (B).', 1, '2', 'Only in direction A', 'Only in direction B', 'Both in direction A and B', NULL, 26, '{6}'::int[], NULL, 'Hello! Remember, when the ''Minimum speed limit'' sign is accompanied by a ''Traffic lane'' plate, it means the restriction applies specifically to the lane directly under the sign. Therefore, you must stay in the lane indicated and follow that path. That is why the correct answer is B.', 'ticket_media/new/ticketIMG-1272.jpg'),
(1302, 'ka', 'სამარშრუტო სატრანსპორტო საშუალების მძღოლმა ზამთრის პირობებში აღნიშნულ გაჩერებაზე მოძრაობისას უნდა გაითვალისწინოს, რომ:', 'ზამთრის პირობებში მოძრაობისას სამარშრუტო სატრანსპორტო საშუალებების მძღოლმა უნდა გაითვალისწინოს, რომ გაჩერებაზე მრავალჯერადი დამუხრუჭების შედეგად წარმოიქმნება მოლოპული მონაკვეთი. ამიტომ აღნუშნულ გაჩერებასთან მიახლოებისას მძღოლმა წინასწარ უნდა შეამციროს მოძრაობის სიჩქარე იმდენად, რომ გამორიცხოს მოცურების საშიშროება დამუხრუჭების დროს. წინააღმდეგ შემთხვევაში შეიძლება მოხდეს სატრანსპორტო საშუალების მოცურება, რის გამოც გაჩერებაზე მყოფი მგზავრები აღმოჩნდებიან საფრთხის ქვეშ.', 0, '1', 'მრავალჯერადი დამუხრუჭების შედეგად წარმოიქმნება მოყინული მონაკვეთი', 'მოძრაობის დიდი ინტესივობის გამო გზის სავალი ნაწილის საფარი მშრალია', 'გზის სავალი ნაწილის საფარი ზამთრის პირობების გამო არ იცვლება', NULL, 21, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ზამთარში ავტობუსები და მარშრუტკები ხშირად ჩერდებიან ერთსა და იმავე ადგილას. მრავალჯერადი დამუხრუჭება თოვლსა და ყინულს „აპრიალებს“, ამიტომ გაჩერებასთან მიახლოებისას სიჩქარე წინასწარ შეამცირე, რომ მოცურება აიცილო თავიდან!', NULL),
(1302, 'ru', 'Водитель маршрутного транспортного средства при движении в зимних условиях к данной остановке должен учитывать, что:', 'В соответствии с Законом Грузии «О дорожном движении», многократное торможение в зимних условиях у остановок приводит к образованию гололеда и обледенению дорожного покрытия. Это увеличивает риск заноса, что создает опасность как для пассажиров, так и для самого транспортного средства.', 0, '1', 'В результате многократного торможения образуется обледенелый участок', 'Из-за высокой интенсивности движения покрытие проезжей части сухое', 'Покрытие проезжей части из-за зимних условий не меняется', NULL, 21, '{4,6}'::int[], NULL, 'Привет! Помни, что зимой автобусы и маршрутки часто останавливаются в одних и тех же местах. Многократное торможение «полирует» лед и снег, делая участок очень скользким. Поэтому при подъезде к остановке заранее снижай скорость, чтобы избежать заноса!', NULL),
(1302, 'en', 'A driver of a public transport vehicle, when driving in winter conditions to the indicated stop, must consider that:', 'In accordance with the Georgian Law on Road Traffic, repeated braking in winter conditions near stops causes the road surface to become polished and icy. This increases the risk of skidding, which endangers both passengers and the vehicle itself.', 0, '1', 'Due to repeated braking, an icy section is formed', 'Due to the high intensity of traffic, the road surface is dry', 'The road surface does not change due to winter conditions', NULL, 21, '{4,6}'::int[], NULL, 'Hello! Remember that in winter, buses and shuttles frequently stop at the same spots. Repeated braking "polishes" the snow and ice, making the surface very slippery. So, when approaching a stop, reduce your speed early to avoid skidding!', NULL),
(1382, 'ka', 'მუშაობის პერიოდში მიწაში თუ აღმოჩენილი იქნა რაიმე სადენი, მაშინ?', 'მუშაობის პერიოდში მიწაში თუ აღმოჩენილი იქნა რაიმე სადენი, მაშინ დაუყოვნებლივ უნდა შეწყდეს მუშაობა და გაგრძელდეს ოფიციალური თანხმობის მიღების შემდეგ.', 0, '3', 'მუშაობა უნდა გაგრძელდეს სიფრთხილის დაცვით', 'დაუყოვნებლივ უნდა შეწყდეს მუშაობა', 'დაუყოვნებლივ უნდა შეწყდეს მუშაობა და გაგრძელდეს მხოლოდ ოფიციალური თანხმობის მიღების შემდეგ', NULL, 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მიწისქვეშა კაბელები შეიძლება იყოს მაღალი ძაბვის ან მნიშვნელოვანი კავშირის ხაზები. მათი დაზიანება სახიფათოა როგორც შენთვის, ისე ინფრასტრუქტურისთვის. ამიტომ, როგორც კი რამეს იპოვი, მაშინვე გააჩერე ტექნიკა და ნუ გააგრძელებ, სანამ შესაბამისი სამსახურები არ დაგიდასტურებენ, რომ ეს უსაფრთხოა!', NULL),
(1382, 'ru', 'Если во время проведения земляных работ в земле был обнаружен какой-либо кабель, тогда?', 'Согласно законодательству Грузии и правилам техники безопасности, во избежание риска повреждения подземных коммуникаций (кабелей), при обнаружении любого подозрительного объекта работы должны быть прекращены и могут быть продолжены только после получения официального согласия и инструкций от компетентного органа или владельца коммуникаций.', 0, '3', 'Работу следует продолжить с соблюдением мер предосторожности', 'Работу следует немедленно прекратить', 'Работу следует немедленно прекратить и продолжить только после получения официального разрешения', NULL, 30, '{7}'::int[], NULL, 'Привет! Помни, что подземные кабели могут находиться под высоким напряжением или быть важными линиями связи. Их повреждение опасно как для тебя, так и для инфраструктуры. Поэтому, как только что-то обнаружишь, немедленно останови работу и не продолжай её, пока соответствующие службы не подтвердят, что это безопасно!', NULL),
(1382, 'en', 'If any cable is discovered in the ground during work, then?', 'According to Georgian legislation and safety regulations, to avoid the risk of damaging underground utilities (cables), work must be suspended upon the discovery of any suspicious object and may only resume after obtaining official consent and instructions from the competent authority or the owner of the utility.', 0, '3', 'Work should continue with caution', 'Work must be stopped immediately', 'Work must be stopped immediately and may only continue after receiving official permission', NULL, 30, '{7}'::int[], NULL, 'Hello! Remember, underground cables might carry high voltage or vital communication lines. Damaging them is dangerous for both you and the infrastructure. So, as soon as you find anything, stop your work immediately and do not proceed until the relevant services confirm it is safe to do so!', NULL),
(1383, 'ka', 'მექანიზმის მუშა მდგომარეობაში მოყვანისას ან მისი გადაადგილების წინ სამუშაო ადგილის გარეშე პირებისგან განთავისუფლების მიზნით მემანქანემ:', 'მექანიზმის მუშა მდგომარეობაში მოყვანისას ან მისი გადაადგილების წინ სამუშაო ადგილის გარეშე პირებისგან განთავისუფლების მიზნით მემანქანემ უნდა მისცეს ხმოვანი სიგნალი.', 0, '1', 'უნდა მისცეს ხმოვანი სიგნალი', 'გამაფრთხილებელი სიგნალი უნდა მისცეს ხელით', 'უნდა ჩავიდეს სამუშაო ადგილზე და პირადად გააფრთხილოს გარეშე პირები', NULL, 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მძიმე ტექნიკის მართვისას უსაფრთხოება მთავარია. ხმოვანი სიგნალი არის ყველაზე ეფექტური და სწრაფი საშუალება გარშემომყოფების გასაფრთხილებლად, რათა მათ დროულად დატოვონ სახიფათო ზონა.', NULL),
(1383, 'ru', 'При приведении механизма в рабочее состояние или перед его перемещением, с целью освобождения рабочего места от посторонних лиц, машинист:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, при запуске или перемещении механизма оператор обязан подать звуковой сигнал, чтобы предупредить окружающих о потенциальной опасности.', 0, '1', 'Подать звуковой сигнал', 'Подать предупреждающий сигнал рукой', 'Спуститься на рабочее место и лично предупредить посторонних лиц', NULL, 30, '{7}'::int[], NULL, 'Привет! Помни, что при управлении тяжелой техникой безопасность превыше всего. Звуковой сигнал — это самый эффективный и быстрый способ предупредить окружающих, чтобы они могли вовремя покинуть опасную зону.', NULL),
(1383, 'en', 'When starting a mechanism or before moving it, in order to clear the workspace of unauthorized persons, the operator must:', 'In accordance with the Georgian ''Law on Road Traffic'' and relevant technical regulations, when starting or moving a mechanism, the operator is required to provide an audible signal to warn those nearby of potential danger.', 0, '1', 'Give an audible signal', 'Give a warning signal by hand', 'Go down to the workspace and personally warn unauthorized persons', NULL, 30, '{7}'::int[], NULL, 'Hello! Remember, when operating heavy machinery, safety comes first. An audible signal is the most effective and quickest way to warn people around you so they can clear the danger zone in time.', NULL),
(1384, 'ka', 'სამუშაოს დაწყების წინ, სამუშაო ადგილზე უნდა გაკეთდეს ტრაფარეტი წარწერით?', 'სამუშაოს დაწყების წინ, სამუშაო ადგილზე უნდა გაკეთდეს ტრაფარეტი წარწერით მიმდინარე სამუშაოების შესახებ.', 0, '2', '„შესვლა აკრძალულია“', 'მიმდინარე სამუშაოების შესახებ', 'მემანქანის გვარი, სახელი და მამის სახელი', NULL, 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მთავარია სხვებმაც იცოდნენ, რომ იქ სამუშაოები მიმდინარეობს, რათა თავიდან ავიცილოთ ავარიული სიტუაციები. ამიტომ, ტრაფარეტზე ინფორმაცია სწორედ მიმდინარე სამუშაოებზე უნდა იყოს.', NULL),
(1384, 'ru', 'Перед началом работ на рабочем месте должен быть установлен трафарет с надписью:', 'В соответствии с Законом Грузии «О дорожном движении» и соответствующими правилами техники безопасности, идентификация рабочего места и информирование о проводимых работах необходимы для обеспечения безопасности дорожного движения.', 0, '2', '«Вход запрещен»', 'О проводимых работах', 'Фамилия, имя и отчество машиниста', NULL, 30, '{7}'::int[], NULL, 'Привет! Помни, что главное — предупредить остальных о том, что ведутся работы, чтобы избежать аварийных ситуаций. Поэтому на трафарете должна быть информация именно о проводимых работах.', NULL),
(1384, 'en', 'Before starting work, a sign with an inscription must be placed at the workplace stating:', 'In accordance with the Law of Georgia ''On Road Traffic'' and relevant safety regulations, the identification of the workplace and notification regarding ongoing works are necessary to ensure road safety.', 0, '2', 'No entry', 'About ongoing works', 'Name, surname and patronymic of the operator', NULL, 30, '{7}'::int[], NULL, 'Hello! Remember, the main goal is to let others know that work is in progress to avoid any accidents. That is why the sign must provide information specifically about the ongoing work.', NULL),
(1385, 'ka', 'ექსკალატორზე შეიძლება თუ არა უცხო პირთა დაშვება?', 'ექსკავატორზე უცხო პირთა დაშვება არ შეიძლება.', 0, '2', 'შეიძლება მემანქანესთან ერთად', 'არ შეიძლება', 'შეიძლება ხელმძღვანელობის თანხმობით', NULL, 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ექსკავატორი არის მძიმე სამშენებლო ტექნიკა და არა სატრანსპორტო საშუალება მგზავრებისთვის. უსაფრთხოების მიზნით, კაბინაში მხოლოდ მემანქანე უნდა იყოს. ნებისმიერი სხვა პირი ქმნის საფრთხეს და არღვევს წესებს.', NULL),
(1385, 'ru', 'Разрешен ли допуск посторонних лиц на экскаватор?', 'В соответствии с законодательством Грузии и правилами охраны труда, экскаватор является техническим средством повышенной опасности. Допуск посторонних лиц на экскаватор категорически запрещен в целях соблюдения норм безопасности и предотвращения производственного травматизма.', 0, '2', 'Разрешено вместе с машинистом', 'Запрещено', 'Разрешено с согласия руководства', NULL, 30, '{7}'::int[], NULL, 'Привет! Помни, что экскаватор — это тяжелая строительная техника, а не транспорт для пассажиров. В целях безопасности в кабине должен находиться только машинист. Любой посторонний человек создает угрозу безопасности и нарушает установленные правила.', NULL),
(1385, 'en', 'Is it permitted to allow unauthorized persons on an excavator?', 'In accordance with the legislation of Georgia and occupational safety regulations, an excavator is a piece of machinery that poses an increased hazard. Allowing unauthorized persons onto an excavator is strictly prohibited to ensure safety standards and prevent workplace injuries.', 0, '2', 'Permitted with the operator', 'Not permitted', 'Permitted with management consent', NULL, 30, '{7}'::int[], NULL, 'Hello! Remember, an excavator is heavy construction machinery, not a vehicle for passengers. For safety reasons, only the operator should be in the cab. Anyone else present creates a safety risk and violates the rules.', NULL),
(1386, 'ka', 'ექსკალატორიდან ჩამოსვლის შემთხვევაში აუცილებელია:', 'ექსკავატორიდან ჩამოსვლის შემთხვევაში აუცილებელია გამორთოთ ყველა გამშვები და დავაყენოთ ნეიტრალურ მდგომარეობაში.', 0, '3', 'მხოლოდ გამოირთოს ყველა გამშვები', 'მხოლოდ ყველა გამშვები დაყენდეს ნეიტრალურ მდგომარეობაში', 'ამ ბილეთში ჩამოთვლილი ყველა მოქმედების შესრულება', NULL, 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ექსკავატორიდან გადმოსვლისას უსაფრთხოება პირველ ადგილზეა. იმისთვის, რომ მანქანა მოულოდნელად არ დაიძრას, საჭიროა ორივე მოქმედების შესრულება: გამშვები მექანიზმების გათიშვაც და ნეიტრალში დაყენებაც. ამიტომ სწორი პასუხია მესამე!', NULL),
(1386, 'ru', 'При сходе с экскаватора необходимо:', 'Согласно Закону Грузии «О дорожном движении» и нормам техники безопасности, при выходе из специальной техники необходимо полностью выключить все пусковые механизмы и перевести их в нейтральное положение для предотвращения самопроизвольного движения техники.', 0, '3', 'Только выключить все пусковые механизмы', 'Только перевести все пусковые механизмы в нейтральное положение', 'Выполнить все перечисленные действия', NULL, 30, '{7}'::int[], NULL, 'Привет! Помни, что при выходе из экскаватора безопасность превыше всего. Чтобы машина внезапно не начала движение, нужно выполнить оба действия: и выключить механизмы, и поставить их в нейтраль. Поэтому правильный ответ — третий!', NULL),
(1386, 'en', 'When exiting an excavator, it is necessary to:', 'According to the Law of Georgia "On Road Traffic" and safety regulations, when exiting special machinery, it is mandatory to switch off all starters and place them in the neutral position to prevent the machinery from moving unintentionally.', 0, '3', 'Only switch off all starters', 'Only set all starters to the neutral position', 'Perform all listed actions', NULL, 30, '{7}'::int[], NULL, 'Hello! Remember, when getting out of an excavator, safety comes first. To ensure the machine doesn''t move unexpectedly, you must perform both actions: switch off the starters and set them to neutral. That''s why the third option is the correct one!', NULL),
(1387, 'ka', 'შეიძლება თუ არა მექანიზმის მუშა მდგომარეობაში დატოვება?', 'მექანიზმის მუშა მდგომარეობაში დატოვება არ შეიძლება.', 0, '3', 'დიახ', 'შეიძლება 15-20 წუთის განმავლობაში', 'არა', NULL, 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ავტომობილიდან გადასვლისას ძრავა ყოველთვის უნდა გამორთო. ეს არის მარტივი და აუცილებელი წესი, რათა თავიდან ავიცილოთ ავარიული შემთხვევები. უსაფრთხოება ყველაზე მნიშვნელოვანია!', NULL),
(1387, 'ru', 'Можно ли оставлять работающий механизм (двигатель) транспортного средства без присмотра?', 'Согласно Закону Грузии «О дорожном движении», водителю запрещается оставлять транспортное средство, если двигатель (механизм) находится в рабочем состоянии. Данное правило направлено на предотвращение самопроизвольного движения автомобиля и обеспечение общей безопасности.', 0, '3', 'Да', 'Можно в течение 15-20 минут', 'Нет', NULL, 30, '{7}'::int[], NULL, 'Привет! Запомни, что при выходе из автомобиля двигатель всегда должен быть выключен. Это простое, но жизненно важное правило, чтобы избежать случайного начала движения машины. Безопасность прежде всего!', NULL),
(1387, 'en', 'Is it permitted to leave the engine running while the vehicle is unattended?', 'In accordance with the Georgian Law on Road Traffic, a driver is prohibited from leaving a vehicle unattended while the mechanism (engine) is running. This rule is intended to prevent the vehicle from moving unintentionally and to ensure overall road safety.', 0, '3', 'Yes', 'Permitted for 15-20 minutes', 'No', NULL, 30, '{7}'::int[], NULL, 'Hello there! Remember, whenever you step out of your vehicle, you must always switch off the engine. It''s a simple yet vital safety habit to prevent the car from rolling away unexpectedly. Safety always comes first!', NULL),
(1388, 'ka', 'შეიძლება თუ არა ექსკალატორის ციცხვის დატვირთულ მდგომარეობაში მიწიდან მოცილებით დატოვება?', 'დატვირთულ მდგომარეობაში ექსკავატორის ციცხვის დატოვების შემთხვევაში აუცილებელია ციცხვი დავუშვათ მიწაზე.', 0, '3', 'შეიძლება ნებისმიერ სიმაღლეზე', 'შეიძლება მიწიდან 1-1,5 მეტრის სიმაღლეზე', 'აუცილებელია ციცხვი დავუშვათ მიწაზე', NULL, 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ექსკავატორი მძიმე ტექნიკაა. თუ ციცხვი ჰაერშია დატვირთული, ეს საფრთხეს უქმნის გარშემომყოფებს და აზიანებს ტექნიკის ჰიდრავლიკას. ამიტომ, უსაფრთხოებისთვის, ყოველთვის დაუშვი ის მიწაზე!', NULL),
(1388, 'ru', 'Можно ли оставлять ковш экскаватора в нагруженном состоянии в приподнятом над землей положении?', 'В соответствии с законодательством Грузии о дорожном движении, нормы безопасности требуют, чтобы при остановке экскаватора ковш в нагруженном состоянии был опущен на землю. Это необходимо для снятия давления с гидравлической системы и предотвращения риска самопроизвольного падения ковша.', 0, '3', 'Можно на любой высоте', 'Можно на высоте 1-1,5 метра от земли', 'Необходимо опустить ковш на землю', NULL, 30, '{7}'::int[], NULL, 'Привет! Помни, экскаватор — тяжелая техника. Если ковш поднят и загружен, это создает опасность для окружающих и перегружает гидравлику. Для безопасности всегда опускай его на землю!', NULL),
(1388, 'en', 'Is it permitted to leave an excavator bucket in a loaded state while raised off the ground?', 'In accordance with the Georgian Law on Road Traffic, safety regulations require that when stopping an excavator, a loaded bucket must be lowered to the ground to relieve pressure from the hydraulic system and prevent the risk of accidental bucket drop.', 0, '3', 'It is permitted at any height', 'It is permitted at a height of 1-1.5 meters from the ground', 'It is necessary to lower the bucket to the ground', NULL, 30, '{7}'::int[], NULL, 'Hello! Remember, an excavator is heavy machinery. Keeping a loaded bucket suspended is dangerous for people nearby and puts unnecessary strain on the hydraulics. For safety, always lower it to the ground!', NULL),
(1389, 'ka', 'მუშაობის პერიოდში, სამუშაო ადგილიდან გარეშე პირი რა მანძილზე უნდა იყოს მოშორებული?', 'მუშაობის პერიოდში, სამუშაო ადგილიდან გარეშე პირი მოშორებული უნდა იყოს 15 მეტრის მანძილზე.', 0, '4', '2 მ', '5 მ', '10 მ', '15 მ', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სამუშაო ზონა საშიშია. უსაფრთხოების წესების თანახმად, ყოველთვის უნდა შეინარჩუნო 15-მეტრიანი დისტანცია, რათა თავი დაიცვა შესაძლო ნამსხვრევებისგან ან ტექნიკის მოძრაობისგან.', NULL),
(1389, 'ru', 'На каком расстоянии от места проведения работ должен находиться посторонний человек во время работы?', 'Согласно нормам безопасности «Закона о дорожном движении» Грузии, в целях обеспечения безопасности в рабочей зоне, посторонние лица во время проведения работ должны находиться на расстоянии не менее 15 метров от рабочего места.', 0, '4', '2 м', '5 м', '10 м', '15 м', 29, '{7}'::int[], NULL, 'Привет! Помни, что рабочая зона — это место повышенной опасности. Чтобы обезопасить себя от летящих предметов или маневров техники, правила требуют соблюдать дистанцию минимум 15 метров.', NULL),
(1389, 'en', 'During operation, what is the required distance for an unauthorized person to be from the workplace?', 'In accordance with the safety regulations under the Georgian ''Law on Road Traffic'', to ensure safety within the work zone, unauthorized persons must maintain a distance of at least 15 meters from the workplace during operations.', 0, '4', '2 m', '5 m', '10 m', '15 m', 29, '{7}'::int[], NULL, 'Hello there! Remember that a work zone can be hazardous. To keep yourself safe from flying debris or moving machinery, the rules mandate that you stay at least 15 meters away.', NULL),
(1390, 'ka', 'რემონტის მიმდინარეობისას გარეშე პირი რა მანძილზე უნდა იყოს მოშორებული?', 'რემონტის მიმდინარეობისას გარეშე პირი მოშორებული უნდა იყოს 1,5 მეტრის მანძილზე.', 0, '1', '1.5 მ', '2 მ', '5 მ', '10 მ', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სარემონტო სამუშაოები საფრთხის შემცველია. უსაფრთხოების მიზნით, კანონი გიწესებს მინიმუმ 1,5 მეტრის დისტანციას, რათა თავიდან ავირიდოთ ინსტრუმენტების ან სხვა ნივთების შემთხვევითი დაცემით გამოწვეული ტრავმები.', NULL),
(1390, 'ru', 'На каком расстоянии от места проведения ремонтных работ должен находиться посторонний человек?', 'В соответствии с Законом Грузии «О дорожном движении», в целях обеспечения безопасности, при проведении ремонтных работ постороннее лицо обязано соблюдать дистанцию в 1,5 метра.', 0, '1', '1.5 м', '2 м', '5 м', '10 м', 29, '{7}'::int[], NULL, 'Привет! Помни, что ремонтные работы связаны с риском. В целях безопасности закон устанавливает дистанцию не менее 1,5 метра, чтобы избежать травм, например, от случайного падения инструментов или строительных материалов.', NULL),
(1390, 'en', 'What is the required distance for a bystander to be from ongoing repair work?', 'In accordance with the Georgian Law on Road Traffic, for the purpose of maintaining safety standards, any bystander must keep a distance of 1.5 meters from ongoing repair work.', 0, '1', '1.5 m', '2 m', '5 m', '10 m', 29, '{7}'::int[], NULL, 'Hello! Remember that road repair areas can be hazardous. To ensure your safety, the law requires you to keep a distance of at least 1.5 meters to prevent accidents caused by falling tools or debris.', NULL),
(1391, 'ka', 'მაღალი ძაბვის ქვეშ მუშაობა დაშვებულია იმ შემთხვევაში თუ დაშორება ექსკალატორის მაღალ წერტილსა და ძაბვის მართულებს შორის არა ნაკლებია:', 'მაღალი ძაბვის ქვეშ მუშაობა დაშვებულია იმ შემთხვევაში თუ დაშორება ექსკალატორის მაღალ წერტილსა და ძაბვის მართულებს შორის არა ნაკლებ 2 მეტრია.', 0, '2', '1.5 მ', '2 მ', '5 მ', '10 მ', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როცა მძიმე ტექნიკით მაღალი ძაბვის ქვეშ მუშაობ, უსაფრთხოება უპირველესია. 2 მეტრი არის ის მინიმალური დისტანცია, რომელიც გიცავს ელექტროშოკისა და სხვა საფრთხეებისგან, ამიტომ ყოველთვის დარწმუნდი, რომ მანძილი არ არის ამაზე ნაკლები.', NULL),
(1391, 'ru', 'Работа под линиями высокого напряжения допускается в том случае, если расстояние между высшей точкой экскаватора и проводами под напряжением составляет не менее:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим нормам безопасности, для предотвращения воздействия электромагнитного поля и возникновения электрической дуги при работе вблизи линий высокого напряжения установлена минимально допустимая дистанция 2 метра между высшей точкой экскаватора и проводами.', 0, '2', '1.5 м', '2 м', '5 м', '10 м', 29, '{7}'::int[], NULL, 'Привет! Помни, что при работе со спецтехникой под линиями высокого напряжения безопасность превыше всего. 2 метра — это та минимальная дистанция, которая защитит тебя от поражения электрическим током, поэтому всегда убеждайся, что расстояние не меньше этого значения.', NULL),
(1391, 'en', 'Working under high voltage lines is permitted if the distance between the highest point of the excavator and the live wires is not less than:', 'According to the Law of Georgia ''on Road Traffic'' and relevant safety regulations, to avoid the effects of electromagnetic fields and electric arcing when working near high-voltage lines, a minimum safe distance of 2 meters between the highest point of the excavator and the live wires is established.', 0, '2', '1.5 m', '2 m', '5 m', '10 m', 29, '{7}'::int[], NULL, 'Hello! Remember, when working with heavy machinery under high-voltage lines, safety is the top priority. 2 meters is the minimum distance required to protect you from electric shock and other hazards, so always ensure the gap is never less than this.', NULL),
(1392, 'ka', 'ექსკალატორი დაკომპლექტებული უნდა იყოს:', 'ექსკავატორი დაკომპლექტებული უნდა იყოს როგორც აფთიაქით, ასევე ხანძარსაწინააღმდეგო მოწყობილობით.', 0, '3', 'მხოლოდ აფთიაქით', 'მხოლოდ ხანძარსაწინააღმდეგო მოწყობილობით', 'როგორც აფთიაქით, ასევე ხანძარსაწინააღმდეგო მოწყობილობით', 'ამ ბილეთში ჩამოთვლილი არცერთი პასუხი არ არის სწორი', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მძიმე ტექნიკა, ისევე როგორც ჩვეულებრივი მანქანა, საფრთხის შემცველია. ამიტომ, კანონი ავალდებულებს მძღოლს, ჰქონდეს ორივე: პირველადი დახმარების საშუალება (აფთიაქი) და ხანძარსაწინააღმდეგო საშუალება (ცეცხლმაქრი). ეს უზრუნველყოფს შენს და გარშემომყოფთა უსაფრთხოებას ნებისმიერ სიტუაციაში.', NULL),
(1392, 'ru', 'Чем должен быть укомплектован экскаватор?', 'В соответствии с Законом Грузии «О дорожном движении», транспортное средство, включая технику специального назначения (такую как экскаватор), должно быть оснащено стандартными средствами обеспечения безопасности. Данное требование предусматривает наличие как аптечки первой помощи, так и противопожарного оборудования, что необходимо для обеспечения эксплуатационной безопасности.', 0, '3', 'Только аптечкой', 'Только противопожарным оборудованием', 'Как аптечкой, так и противопожарным оборудованием', 'Ни один из перечисленных ответов не является правильным', 29, '{7}'::int[], NULL, 'Привет! Помни, что тяжелая техника, как и обычный автомобиль, может быть источником опасности. Поэтому закон обязывает водителя иметь при себе два обязательных атрибута: аптечку для оказания первой помощи и противопожарное оборудование (огнетушитель). Это необходимо для обеспечения твоей безопасности и безопасности окружающих в любых ситуациях.', NULL),
(1392, 'en', 'What should an excavator be equipped with?', 'In accordance with the Georgian ''Law on Road Traffic'', a vehicle, including special-purpose machinery (such as an excavator), must be equipped with standard safety equipment. This requirement mandates the presence of both a first-aid kit and fire-fighting equipment, which is essential for ensuring operational safety.', 0, '3', 'Only with a first-aid kit', 'Only with fire-fighting equipment', 'With both a first-aid kit and fire-fighting equipment', 'None of the above answers are correct', 29, '{7}'::int[], NULL, 'Hello! Remember that heavy machinery, just like a regular car, carries risks. Therefore, the law requires the driver to carry both: a first-aid kit for emergencies and fire-fighting equipment (a fire extinguisher). This is essential to ensure your safety and the safety of others in any given situation.', NULL),
(1393, 'ka', 'უნდა იცოდეს თუ არა ტრაქტორისტ-მემანქანემ საგზაო მოძრაობის წესები?', 'ტრაქტორისტ-მემანქანემ საგზაო მოძრაობის წესები უნდა იცოდეს.', 0, '2', 'არ არის აუცილებელი', 'დიახ', NULL, NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ტრაქტორიც საგზაო მოძრაობის მონაწილეა. რადგან შენ გზაზე მოძრაობ სხვა მანქანებთან ერთად, აუცილებელია იცოდე წესები, რათა შენც და სხვებიც უსაფრთხოდ იყოთ!', NULL),
(1393, 'ru', 'Должен ли тракторист-машинист знать правила дорожного движения?', 'В соответствии с Законом Грузии «О дорожном движении», водитель любого механического транспортного средства, участвующего в дорожном движении, включая тракториста-машиниста, обязан знать правила дорожного движения в целях обеспечения безопасности.', 0, '2', 'Не обязательно', 'Да', NULL, NULL, 29, '{7}'::int[], NULL, 'Привет! Помни, что трактор — это полноценный участник дорожного движения. Так как ты выезжаешь на дорогу общего пользования вместе с другими автомобилями, знание ПДД необходимо для обеспечения твоей безопасности и безопасности окружающих!', NULL),
(1393, 'en', 'Must a tractor driver know the rules of the road?', 'In accordance with the Law of Georgia "On Road Traffic", any driver of a mechanical vehicle participating in road traffic, including a tractor operator, is required to possess knowledge of road traffic regulations to ensure safety.', 0, '2', 'Not necessary', 'Yes', NULL, NULL, 29, '{7}'::int[], NULL, 'Hello! Remember, a tractor is a participant in road traffic. Since you operate on roads alongside other vehicles, knowing the traffic rules is essential to keep both you and others safe!', NULL),
(1394, 'ka', 'როდის უნდა ჩაირთოს საჭირო გადაცემა ბულდოზერის დახრილ ზედაპირზე მოძრაობისთვის?', 'ბულდოზერის დახრილ ზედაპირზე მოძრაობისთვის საჭირო გადაცემა უნდა ჩაირთოს დახრილ ზედაპირზე მოძრაობის დაწყების წინ.', 0, '1', 'დახრილ ზედაპირზე მოძრაობის დაწყების წინ', 'დახრილ ზედაპირზე მოძრაობისას', NULL, NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ბულდოზერი მძიმე ტექნიკაა. თუ დახრილ ზედაპირზე გადაცემას შუა გზაში შეცვლი, შესაძლოა კონტროლი დაკარგო ან ტექნიკა უკან დაგორდეს. ამიტომ, ყოველთვის წინასწარ განსაზღვრე დატვირთვა და ჩართე შესაბამისი სიჩქარე დაწყებამდე!', NULL),
(1394, 'ru', 'Когда необходимо включить необходимую передачу для движения бульдозера по наклонной поверхности?', 'Согласно «Закону Грузии о дорожном движении» и соответствующим техническим регламентам безопасности, переключение передач во время движения на уклоне запрещено из-за рисков потери контроля над спецтехникой. Таким образом, необходимая передача должна быть выбрана и включена до начала подъема или спуска.', 0, '1', 'Перед началом движения по наклонной поверхности', 'Во время движения по наклонной поверхности', NULL, NULL, 29, '{7}'::int[], NULL, 'Привет! Помни, бульдозер — это тяжелая техника. Если ты попытаешься переключить передачу прямо на склоне, ты можешь потерять управление или техника может покатиться назад. Поэтому всегда заранее оценивай уклон и выбирай нужную скорость до начала движения!', NULL),
(1394, 'en', 'When should the necessary gear be engaged for a bulldozer to move on an inclined surface?', 'According to the Law of Georgia on Road Traffic and relevant safety technical regulations, changing gears while moving on an incline is prohibited due to the risk of losing control of the heavy machinery. Therefore, the appropriate gear must be selected and engaged before commencing movement on the inclined surface.', 0, '1', 'Before starting movement on an inclined surface', 'While moving on an inclined surface', NULL, NULL, 29, '{7}'::int[], NULL, 'Hello! Remember, a bulldozer is heavy machinery. If you try to change gears while on an incline, you risk losing control or having the machine roll back. That''s why you should always assess the slope and engage the correct gear before you start moving!', NULL),
(1395, 'ka', 'ბულდოზერის შეზღუდულ სივრცეში მანევრირების შესრულებისას ან აღმართის გადალახვისას უნდა:', 'ბულდოზერის შეზღუდულ სივრცეში მანევრირების შესრულებისას ან აღმართის გადალახვისას თქვენ უნდა შეამციროთ ლილვა მუხლის ბრუნვის სიხშირე.', 0, '2', 'გაიზარდოს ლილვა მუხლის ბრუნვის სიხშირე', 'შემცირდეს ლილვა მუხლის ბრუნვის სიხშირე', NULL, NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ბულდოზერი მძიმე ტექნიკაა. როცა ვიწრო ადგილას მანევრირებ ან აღმართზე ადიხარ, დაბალი ბრუნები გეხმარება უფრო ზუსტად მართო მანქანა და თავიდან აირიდო უეცარი მოძრაობები. ეს იგივეა, რაც მანქანით დაბალ სიჩქარეზე სიარული მეტი კონტროლისთვის!', NULL),
(1395, 'ru', 'Что необходимо сделать при маневрировании бульдозера в ограниченном пространстве или при преодолении подъема?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, при эксплуатации тяжелой техники (бульдозера) в ограниченном пространстве или на подъеме необходимо снизить частоту вращения коленчатого вала двигателя для повышения управляемости машины и обеспечения безопасности.', 0, '2', 'Увеличить частоту вращения коленчатого вала', 'Уменьшить частоту вращения коленчатого вала', NULL, NULL, 29, '{7}'::int[], NULL, 'Привет! Помни, что бульдозер — это тяжелая техника. Когда ты маневрируешь в тесном пространстве или едешь в гору, низкие обороты помогают тебе лучше контролировать машину и избегать резких движений. Это как ехать на обычном авто на пониженной передаче для лучшего контроля!', NULL),
(1395, 'en', 'What must you do when maneuvering a bulldozer in a confined space or when overcoming an incline?', 'In accordance with the Georgian ''Law on Road Traffic'' and relevant technical regulations, when operating heavy machinery such as a bulldozer in confined spaces or on inclines, it is mandatory to reduce the crankshaft rotation frequency to ensure better vehicle control and operational safety.', 0, '2', 'Increase the crankshaft rotation frequency', 'Decrease the crankshaft rotation frequency', NULL, NULL, 29, '{7}'::int[], NULL, 'Hello! Remember, a bulldozer is heavy machinery. When maneuvering in tight spaces or going uphill, lower engine RPMs help you steer with more precision and avoid sudden, jerky movements. It''s similar to driving a car in a lower gear to maintain better control!', NULL),
(1396, 'ka', 'ბულდოზერის მუშაობა დაუშვევებელია, თუ:', 'ბულდოზერის მუშაობა დაუშვევებელია, თუ ფრთის აწევა და გრუნტის დამუშავება გრძივი დახრილობისას 20°-ზე მეტია.', 0, '2', 'ფრთის აწევა და გრუნტის დამუშავება გრძივი დახრილობისას 15°-ზე მეტია', 'ფრთის აწევა და გრუნტის დამუშავება გრძივი დახრილობისას 20°-ზე მეტია', 'ფრთის აწევა და გრუნტის დამუშავება გრძივი დახრილობისას 30°-ზე მეტია', NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ბულდოზერი მძიმე ტექნიკაა. თუ ფერდობი 20 გრადუსზე მეტია, ტექნიკამ შეიძლება წონასწორობა დაკარგოს და გადატრიალდეს. ამიტომ, უსაფრთხოების წესების მიხედვით, ასეთ დახრილობაზე მუშაობა დაუშვებელია.', NULL),
(1396, 'ru', 'Работа бульдозера запрещена, если:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, в целях безопасности эксплуатация бульдозера запрещена, если продольный уклон местности превышает 20 градусов, так как это создает угрозу устойчивости спецтехники.', 0, '2', 'Подъем отвала и обработка грунта при продольном уклоне превышают 15°', 'Подъем отвала и обработка грунта при продольном уклоне превышают 20°', 'Подъем отвала и обработка грунта при продольном уклоне превышают 30°', NULL, 29, '{7}'::int[], NULL, 'Привет! Помни, что бульдозер — это тяжелая техника. Если уклон превышает 20 градусов, машина может потерять равновесие и перевернуться. Поэтому, согласно правилам безопасности, работать на таких уклонах строго запрещено.', NULL),
(1396, 'en', 'Operation of a bulldozer is prohibited if:', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical regulations, for safety reasons, operating a bulldozer is prohibited if the longitudinal slope exceeds 20 degrees, as this poses a risk to the stability of the machinery.', 0, '2', 'Blade lifting and soil processing during longitudinal slope exceed 15°', 'Blade lifting and soil processing during longitudinal slope exceed 20°', 'Blade lifting and soil processing during longitudinal slope exceed 30°', NULL, 29, '{7}'::int[], NULL, 'Hello! Remember that a bulldozer is heavy machinery. If the slope is greater than 20 degrees, the equipment can lose its balance and tip over. Therefore, according to safety regulations, working on such slopes is strictly prohibited.', NULL),
(1397, 'ka', 'ბულდოზერის მუშაობა დაუშვევებელია, თუ:', 'ბულდოზერის მუშაობა დაუშვევებელია ფერდობზე, 16°-ზე მეტი პარალელური დახრილობისას.', 0, '1', 'ფერდობზე მუშაობა პარალელური დახრილობისას 16° მეტია', 'ფერდობზე მუშაობა პარალელური დახრილობისას 20° მეტია', 'ფერდობზე მუშაობა პარალელური დახრილობისას 24° მეტია', NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ბულდოზერი მძიმე ტექნიკაა და მისი სიმძიმის ცენტრი მაღლაა. 16° არის ის კრიტიკული ზღვარი, რომლის ზემოთაც ტექნიკის წონასწორობა ირღვევა. ამიტომ, უსაფრთხოების მიზნით, 16°-ზე მეტ ფერდობზე მუშაობა დაუშვებელია — ეს წესი შენი და სხვების სიცოცხლეს იცავს!', NULL),
(1397, 'ru', 'Работа бульдозера недопустима, если:', 'Согласно действующим техническим регламентам Грузии и нормам безопасности «Закона о дорожном движении», в целях обеспечения устойчивости и безопасности эксплуатации бульдозера, его работа на склоне запрещена, если параллельный уклон превышает 16°. Данное ограничение установлено для предотвращения опрокидывания или неконтролируемого скольжения техники.', 0, '1', 'Работа на склоне при параллельном уклоне более 16°', 'Работа на склоне при параллельном уклоне более 20°', 'Работа на склоне при параллельном уклоне более 24°', NULL, 29, '{7}'::int[], NULL, 'Привет! Помни, что бульдозер — это тяжелая техника с высоким центром тяжести. 16° — это критический предел, после которого равновесие машины нарушается. Поэтому в целях безопасности работа на склонах с уклоном более 16° запрещена. Это правило создано, чтобы защитить тебя и окружающих от аварий!', NULL),
(1397, 'en', 'Bulldozer operation is prohibited if:', 'In accordance with Georgia''s technical regulations and the safety standards of the "Law on Road Traffic," to ensure the stability and safe operation of a bulldozer, its operation on a slope is prohibited if the parallel incline exceeds 16°. This limit is established to prevent the equipment from tipping over or sliding uncontrollably.', 0, '1', 'Working on a slope with a parallel incline of more than 16°', 'Working on a slope with a parallel incline of more than 20°', 'Working on a slope with a parallel incline of more than 24°', NULL, 29, '{7}'::int[], NULL, 'Hello! Remember that a bulldozer is heavy machinery with a high center of gravity. 16° is the critical limit beyond which the machine''s balance is compromised. Therefore, for safety reasons, operating on slopes steeper than 16° is prohibited—this rule is in place to keep you and others safe from accidents!', NULL),
(1398, 'ka', 'დასაშვებია თუ არა მოხვევის განხორციელება ბულდოზერის და საფხიერებელი კბილის ღრმა ნაყარით?', 'ბულდოზერის და საფხიერებელი კბილის ღრმა ნაყარით მოხვევის განხორციელება დასაშვები არ არის.', 0, '2', 'დიახ', 'არა', NULL, NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მძიმე ტექნიკით მანევრირებისას მთავარი პრიორიტეტი გზის დაცვაა. თუ კბილი დაბლაა, მოსახვევში ის ასფალტს „გადახნავს“, რაც სახიფათოა და გზას აფუჭებს. ამიტომ, მოხვევამდე ყოველთვის აწიე რიპერი!', NULL),
(1398, 'ru', 'Разрешается ли выполнение поворота на бульдозере с опущенным рыхлителем?', 'В соответствии с Законом Грузии «О дорожном движении», выполнение поворота на бульдозере с опущенным рыхлителем запрещено, так как это приводит к повреждению дорожного покрытия и создает угрозу безопасности дорожного движения.', 0, '2', 'Да', 'Нет', NULL, NULL, 29, '{7}'::int[], NULL, 'Привет! Помни, что при маневрировании на тяжелой технике важно беречь дорожное полотно. Если рыхлитель опущен, при повороте он «вспашет» асфальт, что опасно и портит дорогу. Поэтому перед поворотом обязательно поднимай рыхлитель!', NULL),
(1398, 'en', 'Is it permissible to make a turn with a bulldozer with the ripper tooth lowered?', 'In accordance with the Georgian Law on Road Traffic, performing a turn with a bulldozer with the ripper tooth lowered is prohibited, as it causes damage to the road surface and creates a risk to traffic safety.', 0, '2', 'Yes', 'No', NULL, NULL, 29, '{7}'::int[], NULL, 'Hello! Remember that when maneuvering heavy machinery, protecting the road surface is a top priority. If the ripper is lowered, it will rip up the asphalt during a turn, which is dangerous and causes damage. Therefore, always lift the ripper before turning!', NULL),
(1402, 'ka', 'ბულდოზერის ტრანსპორტირება შესაძლებელია?', 'ბულდოზერის ტრანსპორტირება შესაძლებელია როგორც თავისი სვლით, ასევე საავტომობილო და სარკინიგზო ტრანსპორტით.', 0, '4', 'მხოლოდ თავისი სვლით', 'მხოლოდ საავტომობილო ტრანსპორტით', 'მხოლოდ სარკინიგზო ტრანსპორტით', 'ამ ბილეთში ჩამოთვლილი ნებიმიერი ხერხით', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ბულდოზერი არის მძიმე ტექნიკა. კანონი არ ზღუდავს მის გადაადგილებას მხოლოდ ერთი გზით: შეგიძლია მართო ის თავად, ან დატვირთო სატვირთოზე თუ მატარებელზე. ამიტომ, პასუხი 4 არის სწორი!', NULL),
(1402, 'ru', 'Возможна ли транспортировка бульдозера?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим нормативным актам, транспортировка спецтехники, включая бульдозеры, разрешена как своим ходом (с соблюдением правил дорожного движения), так и с использованием автомобильного или железнодорожного транспорта.', 0, '4', 'Только своим ходом', 'Только автомобильным транспортом', 'Только железнодорожным транспортом', 'Любым из перечисленных в билете способов', 29, '{7}'::int[], NULL, 'Привет! Запомни: бульдозер — это спецтехника. Закон не ограничивает способ его перемещения. Ты можешь доехать на нем своим ходом или перевезти его на грузовике или поезде. Поэтому вариант 4 — самый верный!', NULL),
(1402, 'en', 'Is it possible to transport a bulldozer?', 'According to the Law of Georgia on Road Traffic and relevant normative acts, the transportation of special-purpose machinery, including bulldozers, is permitted both under its own power (in compliance with traffic rules) and through the use of road or rail transport.', 0, '4', 'Only under its own power', 'Only by road transport', 'Only by rail transport', 'By any of the methods listed in this question', 29, '{7}'::int[], NULL, 'Hello! Remember, a bulldozer is heavy machinery. The law does not restrict you to just one way of moving it: you can drive it yourself, or load it onto a truck or a train. That''s why option 4 is the correct one!', NULL),
(1403, 'ka', 'ბულდოზერის მცირე მანძილზე ტრანსპორტირება რეკომენდირებულია?', 'ბულდოზერის მცირე მანძილზე ტრანსპორტირება რეკომინდირებულია თავისი სვლით.', 0, '1', 'თავისი სვლით', 'საავტომობილო ტრანსპორტით', 'სარკინიგზო ტრანსპორტით', NULL, 4, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როცა საქმე ბულდოზერის მსგავს მძიმე ტექნიკას ეხება, მისი ტრაილერზე ატვირთვა და გადმოტვირთვა დიდ დროსა და რესურსს მოითხოვს. თუ მანძილი მცირეა, ბულდოზერის საკუთარი სვლით გადაადგილება ყველაზე ეკონომიური და მარტივი გამოსავალია.', NULL),
(1403, 'ru', 'Рекомендуется ли транспортировка бульдозера на небольшие расстояния?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, транспортировка специальной строительной техники, в частности бульдозера, на небольшие расстояния целесообразна путем его собственного хода, что сокращает использование дополнительных ресурсов и времени, необходимых для погрузки и транспортировки.', 0, '1', 'Своим ходом', 'Автомобильным транспортом', 'Железнодорожным транспортом', NULL, 4, '{7}'::int[], NULL, 'Привет! Помни, что когда речь идет о такой тяжелой технике, как бульдозер, погрузка и разгрузка на трал требуют много времени и усилий. Если расстояние небольшое, перемещение бульдозера своим ходом — это самое экономичное и простое решение.', NULL),
(1403, 'en', 'Is it recommended to transport a bulldozer for short distances?', 'In accordance with the Law of Georgia ''On Road Traffic'' and relevant technical regulations, transporting special construction equipment, specifically a bulldozer, over short distances is recommended by its own power (self-propelled), as this reduces the additional resources and time required for loading and external transportation.', 0, '1', 'By its own power (self-propelled)', 'By road transport', 'By rail transport', NULL, 4, '{7}'::int[], NULL, 'Hello! Remember that when it comes to heavy machinery like a bulldozer, loading and unloading onto a trailer is time-consuming and resource-heavy. If the distance is short, moving the bulldozer under its own power is the most economical and straightforward solution.', NULL),
(1404, 'ka', 'ბულდოზერის შორ მანძილზე ტრანსპორტირება რეკომენდირებულია?', 'ბულდოზერის შორ მანძილზე ტრანსპორტირება რეკომინდირებულია როგორც საავტომობილო, ასევე სარკინიგზო ტრანსპორტით.', 0, '3', 'მხოლოდ საავტომობილო ტრანსპორტით', 'მხოლოდ სარკინიგზო ტრანსპორტით', 'ამ ბილეთში ჩამოთვლილი ნებისმიერი ხერხით', NULL, 4, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ბულდოზერი არის სპეცტექნიკა. მისი შორ მანძილზე გადაყვანისას მთავარია უსაფრთხოება, ამიტომ კანონი არ ზღუდავს არჩევანს — შეგიძლია გამოიყენო როგორც სატვირთო ავტომობილი (ტრალი), ისე რკინიგზა. ორივე ვარიანტი სწორია!', NULL),
(1404, 'ru', 'Рекомендуется ли транспортировка бульдозера на дальние расстояния?', 'Согласно Закону Грузии «О дорожном движении», транспортировка тяжеловесной или крупногабаритной техники, такой как бульдозер, на дальние расстояния не ограничивается одним видом транспорта. Следовательно, допустима перевозка как автомобильным, так и железнодорожным транспортом.', 0, '3', 'Только автомобильным транспортом', 'Только железнодорожным транспортом', 'Любым из перечисленных в этом билете способов', NULL, 4, '{7}'::int[], NULL, 'Привет! Помни, что бульдозер — это спецтехника. Главное при перевозке на дальние расстояния — это безопасность, поэтому закон не ограничивает твой выбор: можно использовать как грузовой автомобиль (трал), так и железную дорогу. Оба варианта верны!', NULL),
(1404, 'en', 'Is long-distance transportation of a bulldozer recommended?', 'According to the Georgian Law on Road Traffic, the long-distance transportation of heavy or oversized equipment such as a bulldozer is not restricted to a single mode of transport. Therefore, transportation by both road and rail is permitted.', 0, '3', 'Only by road transport', 'Only by rail transport', 'By any method listed in this ticket', NULL, 4, '{7}'::int[], NULL, 'Hello! Remember that a bulldozer is heavy machinery. When transporting it over long distances, safety is the priority, so the law does not restrict your choice—you can use either a heavy-duty truck (trailer) or the railway. Both options are correct!', NULL),
(1405, 'ka', 'რომელია საგზაო-სამშენებლო მანქანების განმასხვავებელი ნიშანი?', 'საამშენებლო მანქანების განმასხვავებელი ნიშანია სავალი ნაწილის ერთგვაროვნება.', 0, '3', 'სამუშაო ორგანოების უნივერსალურობა', 'კონსტრუქციის სიმარტივე', 'სავალი ნაწილის ერთგვაროვნება', 'მართვის სისტემის ერთგვაროვნება', 4, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სამშენებლო ტექნიკის იდენტიფიცირებისთვის ყველაზე მნიშვნელოვანი ფაქტორი მისი სავალი ნაწილის (შასის) ტიპია. სწორედ ეს ერთგვაროვნება გამოარჩევს მათ სხვა ავტომობილებისგან.', NULL),
(1405, 'ru', 'Какой отличительный признак дорожно-строительной техники?', 'Согласно законодательству Грузии и правилам дорожного движения, основным отличительным признаком дорожно-строительной техники является однородность ходовой части, что определяет их технические характеристики и правила участия в дорожном движении.', 0, '3', 'Универсальность рабочих органов', 'Простота конструкции', 'Однородность ходовой части', 'Однородность системы управления', 4, '{7}'::int[], NULL, 'Привет! Помни, что самым важным фактором для идентификации строительной техники является тип её ходовой части (шасси). Именно эта однородность отличает их от других транспортных средств.', NULL),
(1405, 'en', 'What is the distinguishing feature of road-construction machinery?', 'According to the legislation of Georgia and the road traffic regulations, the primary distinguishing feature of road-construction machinery is the uniformity of the undercarriage, which determines their technical specifications and the rules for their participation in road traffic.', 0, '3', 'Universality of working components', 'Simplicity of construction', 'Uniformity of the undercarriage', 'Uniformity of the control system', 4, '{7}'::int[], NULL, 'Hello! Remember that the most important factor for identifying construction machinery is the type of its undercarriage (chassis). It is this uniformity that distinguishes them from other vehicles.', NULL),
(1406, 'ka', 'რა ნიშნების მიხედვით იყოფა საგზაო-სამშენებლო მანქანები კლასებად?', 'საამშენებლო მანქანები კლასებად იყოფა შესრულების ხერხისა და სამუშაო ორგანოს სახის მიხედვით.', 0, '3', 'მასის მიხედვით', 'გადაადგილების სახის მიხედვით', 'შესრულების ხერხისა და სამუშაო ორგანოს სახის მიხედვით', 'ძალური მექანიზმის მიხედვით', 4, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ სამშენებლო მანქანებს ვაჯგუფებთ იმის მიხედვით, თუ რას და როგორ აკეთებენ. მთავარი კრიტერიუმი არის მათი სამუშაო ორგანო (მაგალითად, ბულდოზერის დანა ან ექსკავატორის კოვში) და ის მეთოდი, რომლითაც ეს ორგანო სამუშაოს ასრულებს.', NULL),
(1406, 'ru', 'По каким признакам дорожно-строительные машины делятся на классы?', 'В соответствии с законодательством Грузии и правилами классификации дорожно-строительной техники, машины подразделяются на классы в зависимости от их технологического назначения и функциональных особенностей рабочего органа.', 0, '3', 'По массе', 'По способу передвижения', 'По способу выполнения работ и типу рабочего органа', 'По типу силового механизма', 4, '{7}'::int[], NULL, 'Привет! Запомни, что строительные машины мы классифицируем по тому, что именно они делают и как. Главный критерий — это их рабочий орган (например, отвал бульдозера или ковш экскаватора) и метод, с помощью которого этот орган выполняет задачу.', NULL),
(1406, 'en', 'According to which criteria are road construction machines divided into classes?', 'In accordance with the legislation of Georgia and the rules for classifying road construction machinery, machines are divided into classes based on their technological purpose and the functional characteristics of their working implement.', 0, '3', 'According to mass', 'According to the mode of movement', 'According to the method of execution and type of working body', 'According to the power mechanism', 4, '{7}'::int[], NULL, 'Hello! Remember that we classify construction machines based on what they do and how they do it. The main criterion is the working implement (for example, a bulldozer blade or an excavator bucket) and the method by which that implement performs the work.', NULL),
(1407, 'ka', 'სამუშაო პროცესის ხასიათის მიხედვით საგზაო-სამშენებლო მანქანები იყოფა:', 'სამუშაო პროცესის ხასიათის მიხედვით საამშენებლო მანქანები იყოფა ციკლური და უწყვეტი მოქმედების.', 0, '3', 'არაციკლური მოქმედების მიხედვით', 'მობილური მოქმედების მიხედვით', 'ციკლური და უწყვეტი მოქმედების მიხედვით', 'წყვეტილი მოქმედების მიხედვით', 4, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე: საგზაო მანქანები მუშაობენ ან ეტაპობრივად (ციკლურად, მაგალითად ექსკავატორი), ან შეუჩერებლად (უწყვეტად, მაგალითად საგზაო ფრეზი). ამიტომ სწორი პასუხია მესამე.', NULL),
(1407, 'ru', 'По характеру рабочего процесса дорожно-строительные машины делятся на:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, строительная и дорожная техника по специфике рабочего процесса классифицируется на две основные группы: циклического действия (где работа выполняется отдельными этапами) и непрерывного действия (где процесс протекает непрерывно).', 0, '3', 'Нециклического действия', 'Мобильного действия', 'Циклического и непрерывного действия', 'Прерывистого действия', 4, '{7}'::int[], NULL, 'Привет! Запомни: дорожные машины работают либо поэтапно (циклично, например, экскаватор), либо без остановок (непрерывно, например, дорожная фреза). Поэтому правильный ответ — третий.', NULL),
(1407, 'en', 'According to the nature of the work process, road construction machines are divided into:', 'According to the Georgian ''Law on Road Traffic'' and relevant technical regulations, construction and road machinery are classified into two main groups based on the specifics of their work process: cyclic action (where work is performed in distinct stages) and continuous action (where the process takes place without interruption).', 0, '3', 'Non-cyclic action', 'Mobile action', 'Cyclic and continuous action', 'Intermittent action', 4, '{7}'::int[], NULL, 'Hello! Remember: road machinery operates either in stages (cyclically, like an excavator) or non-stop (continuously, like a road milling machine). That is why the third answer is the correct one.', NULL),
(1408, 'ka', 'მუშა ორგანოების მიერ სიმძლავრის გამოყენების მიხედვით საგზაო-სამშენებლო მანქანები იყოფა:', 'მუშა ორგანოების მიერ სიმძლავრის გამოყენების მიხედვით მანქანები იყოფა პასიური და აქტიური სამუშაო ორგანოებით.', 0, '2', 'წრიული სამუშაო ორგანოების მიხედვით', 'პასიური და აქტიური სამუშაო ორგანოების მიხედვით', 'არააქტიური სამუშაო ორგანოების მიხედვით', 'უნივერსალური სამუშაო ორგანოების მიხედვით', 4, '{7}'::int[], NULL, 'გამარჯობა! აქ მთავარია დავიმახსოვროთ, რომ ტექნიკა ან „პასიურად“ მუშაობს (მაგალითად, ბულდოზერის დანა) ან „აქტიურად“ (როდესაც ძრავის სიმძლავრე პირდაპირ მოქმედებს მუშა ორგანოზე, მაგალითად, ექსკავატორის კოვში ან ბურღი). სწორედ ამიტომ მეორე პასუხი არის სწორი.', NULL),
(1408, 'ru', 'В зависимости от использования мощности рабочими органами, дорожно-строительные машины делятся на:', 'Согласно Закону Грузии «О дорожном движении» и классификации дорожно-строительной техники, в зависимости от режима использования мощности рабочие органы подразделяются на пассивные (не потребляющие дополнительную энергию для процесса) и активные (использующие механическую энергию).', 0, '2', 'По круговым рабочим органам', 'По пассивным и активным рабочим органам', 'По неактивным рабочим органам', 'По универсальным рабочим органам', 4, '{7}'::int[], NULL, 'Привет! Главное здесь запомнить, что техника либо работает «пассивно» (например, отвал бульдозера), либо «активно» (когда мощность двигателя напрямую воздействует на рабочий орган, например, ковш экскаватора или бур). Именно поэтому второй вариант является верным.', NULL),
(1408, 'en', 'According to the use of power by the working units, road-construction machines are divided into:', 'According to the Law of Georgia ''On Road Traffic'' and the classification of road-construction machinery, depending on the power usage mode, working units are classified into passive (which do not consume additional energy for processing) and active (which utilize mechanical energy).', 0, '2', 'According to circular working units', 'According to passive and active working units', 'According to inactive working units', 'According to universal working units', 4, '{7}'::int[], NULL, 'Hello! The key here is to remember that machinery either works ''passively'' (e.g., a bulldozer blade) or ''actively'' (when the engine power directly acts on the working unit, e.g., an excavator bucket or a drill). That is why the second answer is the correct one.', NULL),
(1409, 'ka', 'საგზაო-სამშენებლო მანქანის მთავარი პარამეტრია:', 'საგზაო-საამშენებლო მანქანის მთავარი პარამეტრია მწარმოებლობა.', 0, '4', 'ჩამჩის მოცულობა', 'ტვირთამწეობა', 'წევის ძალა', 'მწარმოებლობა', 4, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ნებისმიერი სამშენებლო ტექნიკის მთავარი მიზანი საქმის სწრაფად და ეფექტურად გაკეთებაა. მიუხედავად იმისა, რომ კოვზის მოცულობა ან სიმძლავრე მნიშვნელოვანია, საბოლოო ჯამში ყველაზე მთავარი პარამეტრი მაინც „მწარმოებლობაა“, ანუ რამდენ სამუშაოს ასრულებს მანქანა დროის მოცემულ მონაკვეთში.', NULL),
(1409, 'ru', 'Каким является главный параметр дорожно-строительной машины?', 'Согласно Закону Грузии «О дорожном движении» и техническим нормативам, основным критерием, определяющим эффективность работы дорожно-строительной машины, является производительность, что подразумевает объем работы, выполняемой машиной за единицу времени.', 0, '4', 'Объем ковша', 'Грузоподъемность', 'Тяговое усилие', 'Производительность', 4, '{7}'::int[], NULL, 'Привет! Помни, что главная цель любой строительной техники — выполнить работу максимально эффективно. Хотя объем ковша или мощность важны, самым главным параметром всегда остается «производительность», то есть то, сколько работы машина успевает сделать за определенный промежуток времени.', NULL),
(1409, 'en', 'What is the main parameter of a road construction machine?', 'According to the Law of Georgia on Road Traffic and technical standards, the main criterion determining the operational efficiency of a road construction machine is productivity, which refers to the volume of work performed by the machine per unit of time.', 0, '4', 'Bucket capacity', 'Load capacity', 'Traction force', 'Productivity', 4, '{7}'::int[], NULL, 'Hello! Remember that the main goal of any construction machinery is to get the job done efficiently. Even though bucket capacity or power are important, the primary parameter is always ''productivity'', meaning how much work the machine can accomplish within a specific period of time.', NULL),
(1410, 'ka', 'რომელია ერთჩამჩიანი ექსკავატორის საექსპლუატაციო მწარმოებლობის განზომილება?', 'ერთჩამჩიანი ექსკავატორის საექსპლუატაციო მწარმოებლობის განზომილებაა -მ³/სთ.', 0, '3', 'ჰა/სთ', 'მ²/სთ', 'მ³/სთ', 'მ/სთ', 5, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ექსკავატორი არის ტექნიკა, რომელიც თხრის მიწას. რადგან ის მოცულობასთან მუშაობს, მისი მწარმოებლობაც კუბურ მეტრებში იზომება. ამიტომ, სწორი პასუხია მ³/სთ!', NULL),
(1410, 'ru', 'Какова единица измерения эксплуатационной производительности одноковшового экскаватора?', 'В соответствии с действующими техническими регламентами и нормами эксплуатации дорожно-строительной техники, эксплуатационная производительность одноковшового экскаватора определяется объемом перемещенного грунта в единицу времени, что выражается в м³/ч.', 0, '3', 'га/ч', 'м²/ч', 'м³/ч', 'м/ч', 5, '{7}'::int[], NULL, 'Привет! Запомни, экскаватор — это машина, которая перемещает грунт. Поскольку мы имеем дело с объемом, производительность измеряется в кубических метрах в час. Поэтому правильный ответ — м³/ч!', NULL),
(1410, 'en', 'What is the unit of measurement for the operational productivity of a single-bucket excavator?', 'In accordance with current technical regulations and standards for the operation of road construction machinery, the operational productivity of a single-bucket excavator is determined by the volume of soil moved per unit of time, which is expressed in m³/h.', 0, '3', 'ha/h', 'm²/h', 'm³/h', 'm/h', 5, '{7}'::int[], NULL, 'Hello! Remember, an excavator is a machine designed to move soil. Since it deals with volume, its productivity is measured in cubic meters per hour. Therefore, the correct answer is m³/h!', NULL),
(1411, 'ka', 'საგზაო-სამშენებლო მანქანებში გვხვდება შემდეგი სახის ტრანსმისია:', 'საგზაო-საამშენებლო მანქანებში გვხვდება პნევმატიკური სახის ტრანსმისია.', 0, '3', 'მექანიკური', 'ჰიდრავლიკური', 'პნევმატიკური', 'კომბინირებული', 5, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მძიმე საგზაო-სამშენებლო მანქანებში ხშირად გამოიყენება პნევმატიკური (ჰაერის წნევაზე დაფუძნებული) ტრანსმისია, რადგან ის ეფექტურად უმკლავდება რთულ სამუშაოებს. ამიტომ, სწორი პასუხია 3.', NULL),
(1411, 'ru', 'Какой тип трансмиссии встречается в дорожно-строительных машинах?', 'На основании Закона Грузии «О дорожном движении» и соответствующих технических регламентов, специфические характеристики дорожно-строительной техники включают использование трансмиссии пневматического типа, что обеспечивает эффективность работы и безопасность машины в условиях эксплуатации под нагрузкой.', 0, '3', 'Механическая', 'Гидравлическая', 'Пневматическая', 'Комбинированная', 5, '{7}'::int[], NULL, 'Привет! Запомни, что в тяжелой дорожно-строительной технике часто используется пневматическая (основанная на давлении воздуха) трансмиссия, так как она эффективно справляется со сложными задачами. Поэтому правильный ответ — 3.', NULL),
(1411, 'en', 'Which type of transmission is found in road-construction machinery?', 'Based on the Georgian Law on Road Traffic and relevant technical regulations, the specific characteristics of road-construction machinery include the use of pneumatic-type transmission, which ensures the operational efficiency and safety of the vehicle under load conditions.', 0, '3', 'Mechanical', 'Hydraulic', 'Pneumatic', 'Combined', 5, '{7}'::int[], NULL, 'Hello! Remember that heavy road-construction machinery often utilizes pneumatic (air-pressure based) transmission because it effectively manages demanding tasks. Therefore, the correct answer is 3.', NULL),
(1412, 'ka', 'ჰიდრავლიკური მართვის სისტემის შემადგენელი ელემენტია:', 'ჰიდრავლიკური მართვის სისტემის შემადგენელი ელემენტია ჰიდროგამანაწილებელი.', 0, '3', 'ჰიდრავლიკური ტუმბო', 'სარედაქციო-დამცველი სარქველი', 'ჰიდროგამანაწილებელი', 'შემსრულებელი მექანიზმი', 5, '{7}'::int[], NULL, 'წარმოიდგინე, რომ ჰიდროგამანაწილებელი არის სისტემის „გზაჯვარედინის მეთვალყურე“. ის წყვეტს, სად წავიდეს ზეთი, რათა საჭემ ან მექანიზმმა სწორად იმუშაოს. სწორედ ამიტომ ის სისტემის განუყოფელი ნაწილია.', NULL),
(1412, 'ru', 'Каким элементом является гидравлическая система управления?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, гидрораспределитель является ключевым компонентом гидравлической системы управления, отвечающим за направление потока рабочей жидкости.', 0, '3', 'Гидравлический насос', 'Редукционный клапан', 'Гидрораспределитель', 'Исполнительный механизм', 5, '{7}'::int[], NULL, 'Представь, что гидрораспределитель — это «регулировщик на перекрестке» системы. Он решает, куда направить поток масла, чтобы рулевое управление или другой механизм сработали правильно. Вот почему это важнейший элемент системы.', NULL),
(1412, 'en', 'Which of these is a component of a hydraulic control system?', 'According to the Georgian Law on Road Traffic and relevant technical regulations, the hydraulic distributor is a fundamental component of the hydraulic control system, responsible for directing the flow of the working fluid.', 0, '3', 'Hydraulic pump', 'Relief valve', 'Hydraulic distributor (control valve)', 'Actuator', 5, '{7}'::int[], NULL, 'Think of the hydraulic distributor as the ''traffic controller'' of the system. It decides where the oil flows so that the steering or mechanism functions correctly. That is why it is an essential part of the system.', NULL),
(1413, 'ka', 'საგზაო-სამშენებლო მანქანების სავალი მოწყობილობა არის:', 'საამშენებლო მანქანების სავალი მოწყობილობაა მაბიჯი.', 0, '3', 'მუხლუხა', 'პნევმოთვლიანი', 'მაბიჯი', 'საჰაერო ბალიშზე', 5, '{7}'::int[], NULL, 'გამარჯობა! აქ საქმე გვაქვს სპეციალიზებულ ტექნიკასთან. მიუხედავად იმისა, რომ არსებობს მუხლუხა ან თვლიანი ტექნიკა, კანონმდებლობით საგზაო-სამშენებლო მანქანების კონტექსტში სავალ ნაწილად სწორედ „მაბიჯი“ მოწყობილობა მოიაზრება. დაიმახსოვრე ეს ტერმინი!', NULL),
(1413, 'ru', 'Ходовым устройством дорожно-строительных машин является:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, в классификации дорожно-строительных машин ходовым устройством определено шагающее устройство.', 0, '3', 'Гусеничное', 'Пневмоколесное', 'Шагающее', 'На воздушной подушке', 5, '{7}'::int[], NULL, 'Привет! Здесь мы имеем дело со специализированной техникой. Несмотря на то, что существуют гусеничные или колесные машины, согласно законодательству, в контексте дорожно-строительной техники именно «шагающее» устройство является правильным ответом. Просто запомни этот термин!', NULL),
(1413, 'en', 'The running gear of road construction machinery is:', 'According to the Law of Georgia "On Road Traffic" and relevant technical regulations, in the classification of road construction machinery, the walking mechanism is defined as the running gear.', 0, '3', 'Caterpillar (tracked)', 'Pneumatic-tired', 'Walking', 'Air-cushion', 5, '{7}'::int[], NULL, 'Hello! We are dealing with specialized machinery here. Even though there are tracked or wheeled vehicles, according to the legislation, in the context of road construction machinery, the "walking" mechanism is the correct technical definition. Just keep this term in mind!', NULL),
(1414, 'ka', 'საგზაო-სამშენებლო მანქანების სავალი მოწყობილობა არის:', 'საამშენებლო მანქანების სავალი მოწყობილობაა მაბიჯი.', 0, '2', 'ხისტი თვლიანი', 'მაბიჯი', 'მცურავი', 'კომბინირებული', 5, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სპეციალური ტექნიკისთვის, განსაკუთრებით რთულ პირობებში, „მაბიჯი“ მექანიზმი გამოიყენება, რაც მათ საშუალებას აძლევს „გადადგან ნაბიჯები“ და არ ჩაეფლონ გრუნტში.', NULL),
(1414, 'ru', 'Ходовая часть дорожно-строительных машин — это:', 'В соответствии с Законом Грузии «О дорожном движении», специфическим типом ходовой части дорожно-строительных машин, обеспечивающим передвижение тяжелой техники по сложным грунтам, является шагающий механизм.', 0, '2', 'Жесткоколесная', 'Шагающая', 'Плавающая', 'Комбинированная', 5, '{7}'::int[], NULL, 'Привет! Запомни, что для тяжелой спецтехники в сложных условиях часто используется «шагающий» механизм — это позволяет машине буквально переставлять опоры, чтобы не увязнуть в грунте.', NULL),
(1414, 'en', 'The running gear of road construction machinery is:', 'In accordance with the Law of Georgia on Road Traffic, the specific type of running gear for road construction machinery that enables the movement of heavy equipment over difficult terrain is the walking mechanism.', 0, '2', 'Rigid-wheeled', 'Walking', 'Floating', 'Combined', 5, '{7}'::int[], NULL, 'Hello! Just remember that for heavy-duty construction machinery working in tough terrain, a ''walking'' mechanism is used. This allows the machine to literally step forward, preventing it from getting stuck in soft ground.', NULL),
(1415, 'ka', 'რომელია პნევმოთვლიანი სავალი მოწყობილობის უარყოფითი მახასიათებელი?', 'პნევმოთვლიანი სავალი მოწყობილობის უარყოფითი მახასიათებელია - გრუნტზე დიდი დაწოლა.', 0, '3', 'მაღალი სატრანსპორტო სიჩქარე', 'წნევის რეგულირება საყრდენებზე', 'გრუნტზე დიდი დაწოლა', 'მაღალი მარგი ქმედების კოეფიციენტი', 5, '{7}'::int[], NULL, 'გამარჯობა! პნევმატური საბურავები ძალიან კომფორტულია, მაგრამ მათ აქვთ ერთი მინუსი: მძიმე ტექნიკისთვის ისინი ქმნიან მაღალ წნევას მიწაზე. წარმოიდგინე, რომ ქუსლიანი ფეხსაცმლით დადიხარ ქვიშაზე – ფეხი იჭედება, რადგან მთელი წონა ერთ წერტილზე მოდის. სწორედ ეს ხდება პნევმოთვლებთან დაკავშირებითაც!', NULL),
(1415, 'ru', 'Какова отрицательная характеристика пневмоколесного ходового устройства?', 'В соответствии с Законом Грузии «О дорожном движении», одним из основных недостатков пневмоколесного движителя является высокое удельное давление на грунт, что ограничивает проходимость транспортного средства на мягких грунтах.', 0, '3', 'Высокая транспортная скорость', 'Регулировка давления в шинах', 'Высокое давление на грунт', 'Высокий коэффициент полезного действия', 5, '{7}'::int[], NULL, 'Привет! Пневматические шины очень удобны, но у них есть минус: для тяжелой техники они создают высокое давление на почву. Представь, что ты идешь по песку на каблуках — нога проваливается, так как весь вес давит на маленькую площадь. Именно это и происходит с пневмоколесами!', NULL),
(1415, 'en', 'What is a negative characteristic of a pneumatic-wheeled running gear?', 'In accordance with the Law of Georgia ''On Road Traffic'', one of the main disadvantages of a pneumatic-wheeled running gear is the high specific ground pressure, which limits the vehicle''s off-road capability on soft terrain.', 0, '3', 'High transport speed', 'Tire pressure regulation', 'High ground pressure', 'High efficiency coefficient', 5, '{7}'::int[], NULL, 'Hello! Pneumatic tires are great for comfort, but they have a downside: for heavy machinery, they create high ground pressure. Imagine walking on sand in high heels—you sink because all your weight is focused on a small point. That is exactly the issue with pneumatic wheels!', NULL),
(1416, 'ka', 'თუ პნევმოთვლიანი სვლის თვლების ფორმულაა 6x4, რამდენი თვალია წამყვანი?', 'თუ პნევმოთვლიანი სვლის თვლების ფორმულაა 6x4 წამყვანი თვალია 4.', 0, '3', '6', '10', '4', NULL, 5, '{7}'::int[], NULL, 'გამარჯობა! ეს ძალიან მარტივია: დაიმახსოვრე, რომ როცა ფორმულას ვწერთ (მაგალითად 6x4), მეორე რიცხვი ყოველთვის მიგვანიშნებს იმაზე, თუ რამდენი თვალი იღებს ძრავისგან ენერგიას და აბრუნებს მანქანას. შესაბამისად, 4 არის სწორი პასუხი!', NULL),
(1416, 'ru', 'Если колесная формула автомобиля с пневматическими шинами 6x4, сколько колес являются ведущими?', 'В соответствии с Законом Грузии «О дорожном движении», колесная формула транспортного средства определяет общее количество колес и количество ведущих колес. В формуле 6x4 первая цифра (6) обозначает общее количество колес, а вторая цифра (4) указывает на количество ведущих колес.', 0, '3', '6', '10', '4', NULL, 5, '{7}'::int[], NULL, 'Привет! Это очень просто: запомни, что когда мы пишем колесную формулу (например, 6x4), вторая цифра всегда указывает, сколько колес получают энергию от двигателя и приводят машину в движение. Поэтому 4 — это правильный ответ!', NULL),
(1416, 'en', 'If the wheel formula of a pneumatic-tired vehicle is 6x4, how many wheels are driving wheels?', 'In accordance with the Georgian Law on Road Traffic, the vehicle wheel formula defines the total number of wheels and the number of driving wheels. In the 6x4 formula, the first digit (6) indicates the total number of wheels, and the second digit (4) indicates the number of driving wheels.', 0, '3', '6', '10', '4', NULL, 5, '{7}'::int[], NULL, 'Hello! It is quite simple: remember that when we write the wheel formula (e.g., 6x4), the second digit always indicates how many wheels receive power from the engine to drive the vehicle. Therefore, 4 is the correct answer!', NULL),
(1417, 'ka', 'თუ პნევმოთვლის მოდელის აღნიშვნაა 21,0 – 25,0, რას აღნიშნავს პირველი რიცხვი?', 'თუ პნევმოთვლის მოდელის აღნიშვნაა 21,0 – 25,0 პირველი ციფრი აღნიშნავს პროფილის სიგანეს.', 0, '2', 'გარე დიამეტრს', 'პროფილის სიგანეს', 'სტატიურ რადიუსს', 'ფენობრივ ნორმას', 6, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, საბურავის მარკირება აუცილებელია მისი სწორად შესარჩევად. პირველი რიცხვი ყოველთვის აღნიშნავს საბურავის სიგანეს, რაც გვეხმარება გავიგოთ, რამდენად ფართოა ის, ხოლო მეორე რიცხვი მიუთითებს დისკის დიამეტრზე. ამიტომ, 21,0 ნიშნავს პროფილის სიგანეს.', NULL),
(1417, 'ru', 'Если обозначение модели пневматической шины 21,0 – 25,0, что означает первая цифра?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим стандартам, в маркировке пневматической шины первое число определяет ширину профиля шины (в дюймах или миллиметрах), а второе число — посадочный диаметр обода.', 0, '2', 'Внешний диаметр', 'Ширину профиля', 'Статический радиус', 'Норму слойности', 6, '{7}'::int[], NULL, 'Привет! Запомни, маркировка шин очень важна для правильного подбора. Первое число всегда указывает на ширину профиля шины, что помогает понять её размер, а второе число — на посадочный диаметр диска. Поэтому 21,0 — это ширина профиля.', NULL),
(1417, 'en', 'If the pneumatic tire model designation is 21.0 – 25.0, what does the first number indicate?', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical standards, in the marking of a pneumatic tire, the first number defines the profile width of the tire (in inches or millimeters), while the second number represents the rim diameter.', 0, '2', 'Outer diameter', 'Profile width', 'Static radius', 'Ply rating', 6, '{7}'::int[], NULL, 'Hello! Remember, tire marking is essential for choosing the right one. The first number always indicates the profile width, which helps us understand how wide the tire is, while the second number points to the rim diameter. Therefore, 21.0 denotes the profile width.', NULL),
(1418, 'ka', 'რომელ ჯგუფს მიეკუთვნებიან სკრეპერები?', 'სკრეპერები მიეკუთვნებიან მიწასათხრელ-სატრანსპორტო მანქანების ჯგუფს.', 0, '2', 'ერთჩამჩიან და მრავალჩამჩიან მიწასათხრელ მანქანებს', 'მიწასათხრელ-სატრანსპორტო მანქანებს', 'გრუნტის გასამკვრივებელ მანქანებს', 'გრუნტის ჰიდრავლიკურ დასამუშავებელ მანქანებს', 6, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, სკრეპერი არამარტო თხრის მიწას, არამედ თვითონვე გადააქვს ის დანიშნულების ადგილამდე. ამიტომ, ის არის „მიწასათხრელ-სატრანსპორტო“ მანქანა. ეს არის მარტივი ლოგიკა: თხრა + ტრანსპორტირება = მიწასათხრელ-სატრანსპორტო მანქანა.', NULL),
(1418, 'ru', 'К какой группе относятся скреперы?', 'Согласно Закону Грузии «О дорожном движении», скрепер является машиной специального назначения, предназначенной для резания, транспортировки и укладки грунта. Исходя из этих функциональных характеристик, он классифицируется как землеройно-транспортная машина.', 0, '2', 'К землеройным машинам с одним или несколькими ковшами', 'К землеройно-транспортным машинам', 'К машинам для уплотнения грунта', 'К машинам для гидравлической обработки грунта', 6, '{7}'::int[], NULL, 'Привет! Запомни, скрепер не только копает грунт, но и сам же перевозит его к месту назначения. Поэтому это «землеройно-транспортная» машина. Логика проста: копание + транспортировка = землеройно-транспортная машина.', NULL),
(1418, 'en', 'Which group do scrapers belong to?', 'In accordance with the Georgian Law on Road Traffic, a scraper is a special-purpose machine designed for excavating, transporting, and spreading soil. Based on these functional characteristics, it is classified as an earthmoving-transport machine.', 0, '2', 'Single-bucket and multi-bucket excavating machines', 'Earthmoving-transport machines', 'Soil compaction machines', 'Hydraulic soil processing machines', 6, '{7}'::int[], NULL, 'Hello! Remember, a scraper doesn''t just dig the soil, it also transports it to the destination itself. Therefore, it is an ''earthmoving-transport'' machine. The logic is simple: excavation + transportation = earthmoving-transport machine.', NULL),
(1419, 'ka', 'გრუნტის ჭრის სახეობა არის:', 'გრუნტის ჭრის სახეობა არის - თავისუფალი.', 0, '1', 'თავისუფალი', 'ნახევრად ბლოკირებული', 'ბლოკირებული', NULL, 6, '{7}'::int[], NULL, 'გამარჯობა! როდესაც ვსაუბრობთ გრუნტის ჭრაზე, წარმოიდგინე, რომ კოვზით იღებ ნაყინს - როცა არაფერი გიშლის ხელს და თავისუფლად ჭრი მასას, ეს არის ''თავისუფალი'' ჭრა. სხვა ვარიანტები, როგორიცაა ბლოკირებული, გულისხმობს დამატებით წინააღმდეგობას, რაც ამ შემთხვევაში არასწორია.', NULL),
(1419, 'ru', 'Видом среза грунта является:', 'Согласно законодательству Грузии и нормам дорожного строительства, в технологическом процессе резания грунта выделяют различные виды резания. Правильный ответ — свободное резание, так как оно подразумевает отделение грунта от массива без ограничений со стороны бокового сопротивления.', 0, '1', 'Свободный', 'Полублокированный', 'Блокированный', NULL, 6, '{7}'::int[], NULL, 'Привет! Когда мы говорим о резке грунта, представь, что берешь ложкой мороженое — когда ничто не мешает и ты свободно отделяешь массу, это и есть «свободная» резка. Другие варианты, такие как блокированная, подразумевают дополнительное сопротивление, поэтому правильный ответ — свободная.', NULL),
(1419, 'en', 'The type of soil cut is:', 'According to Georgian legislation and road construction standards, various types of soil cutting are distinguished during the technological process. The correct answer is free cutting, as it implies separating the soil from the mass without being constrained by side resistance.', 0, '1', 'Free', 'Semi-blocked', 'Blocked', NULL, 6, '{7}'::int[], NULL, 'Hello! When we talk about soil cutting, imagine scooping ice cream—when nothing gets in your way and you freely separate the mass, that is ''free'' cutting. Other options, like blocked, imply additional resistance, which is why free is the correct answer.', NULL),
(1420, 'ka', 'რამდენი საცვლელი სამუშაო ორგანო აქვს უნივერსალურ ერთჩამჩიან ექსკავატორს?', 'უნივერსალურ ერთჩამჩიან ექსკავატორს აქვს 3 ან 3-ზე მეტი საცვლელი სამუშაო ორგანო.', 0, '2', '3-ზე ნაკლები', '3 ან 3-ზე მეტი', '2-დან 5-მდე', '1-დან 3-მდე', 6, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ „უნივერსალური“ ნიშნავს მრავალმხრივ გამოყენებას. რადგან ამ ექსკავატორს შეუძლია ბევრი სხვადასხვა სამუშაოს შესრულება (მაგალითად, თხრა, დატვირთვა ან დაშლა), მას სჭირდება მინიმუმ 3 სხვადასხვა სამუშაო დანადგარი. სწორედ ამიტომ, პასუხი „3 ან 3-ზე მეტი“ არის სწორი!', NULL),
(1420, 'ru', 'Сколько сменных рабочих органов имеет универсальный одноковшовый экскаватор?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, универсальный одноковшовый экскаватор определяется как техника, имеющая 3 или более 3 сменных рабочих органов, что делает её многофункциональной.', 0, '2', 'Меньше 3', '3 или больше 3', 'От 2 до 5', 'От 1 до 3', 6, '{7}'::int[], NULL, 'Привет! Запомни, что «универсальный» означает многоцелевой. Так как этот экскаватор может выполнять множество различных задач (например, копание, погрузку или демонтаж), ему требуется минимум 3 различных рабочих органа. Именно поэтому вариант «3 или больше 3» является верным!', NULL),
(1420, 'en', 'How many interchangeable working implements does a universal single-bucket excavator have?', 'According to the Law of Georgia on Road Traffic and relevant technical regulations, a universal single-bucket excavator is defined as machinery equipped with 3 or more than 3 interchangeable working implements, making it multifunctional.', 0, '2', 'Less than 3', '3 or more than 3', 'From 2 to 5', 'From 1 to 3', 6, '{7}'::int[], NULL, 'Hello! Remember that ''universal'' means multi-purpose. Since this excavator can perform many different tasks (like digging, loading, or demolition), it needs at least 3 different working implements. That is why the answer ''3 or more than 3'' is the correct one!', NULL),
(1421, 'ka', 'ბაგირული დაკიდების ერთჩამჩიანი ექსკავატორის ძირითადი ნაწილები არის:', 'ბაგირული დაკიდების ერთჩამჩიანი ექსკავატორის ძირითადი ნაწილია საყრდენ-საბრუნი.', 0, '2', 'სავალი მოწყობილობა', 'საყრდენ-საბრუნი', 'ამძრავი', 'ტრანსმისია', 6, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ექსკავატორისთვის ყველაზე მნიშვნელოვანია მბრუნავი მექანიზმი. სწორედ საყრდენ-საბრუნი მოწყობილობა აძლევს მას საშუალებას, რომ თავისი სამუშაო ორგანოები სწორი მიმართულებით ატრიალოს, ამიტომ ეს მისი ძირითადი და განუყოფელი ნაწილია.', NULL),
(1421, 'ru', 'Каковы основные части одноковшового экскаватора с канатной подвеской?', 'В соответствии с Законом Грузии «О дорожном движении» и соответствующими техническими регламентами, опорно-поворотное устройство является конструктивным ядром канатного экскаватора, обеспечивающим соединение верхней поворотной платформы с ходовой частью и распределение нагрузок.', 0, '2', 'Ходовое устройство', 'Опорно-поворотное устройство', 'Привод', 'Трансмиссия', 6, '{7}'::int[], NULL, 'Привет! Запомни: самое важное в экскаваторе — это механизм вращения. Именно опорно-поворотное устройство позволяет экскаватору вращать рабочую платформу в нужном направлении, поэтому оно является его основной и неотъемлемой частью.', NULL),
(1421, 'en', 'What are the main components of a single-bucket cable-operated excavator?', 'In accordance with the Georgian Law on Road Traffic and relevant technical regulations, the slew bearing (swing circle) is the structural core of a cable-operated excavator, providing the connection between the upper revolving superstructure and the undercarriage while distributing operational loads.', 0, '2', 'Undercarriage', 'Slew bearing / Swing circle', 'Drive mechanism', 'Transmission', 6, '{7}'::int[], NULL, 'Hello! Remember, for an excavator, the most important part is the rotation mechanism. The slew bearing is what allows the machine to rotate its upper body and work effectively, making it a fundamental component of the excavator''s structure.', NULL),
(1422, 'ka', 'ერთჩამჩიანი უნივერსალური ექსკავატორის სამუშაო ორგანოები არის:', 'ერთჩამჩიანი უნივერსალური ექსკავატორის სამუშაო ორგანოა - დრაგლაინი.', 0, '3', 'ჩამჩა შემობრუნებული ნიჩბით', 'ჩამჩა პირდაპირი ნიჩბით', 'დრაგლაინი', 'გრეიფერი', 6, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ერთჩამჩიანი ექსკავატორი მრავალფუნქციურია. დრაგლაინი არის ის სპეციალური მოწყობილობა, რომელიც თოკების სისტემით მუშაობს და საშუალებას გვაძლევს ამოვიღოთ გრუნტი მანქანის დონეზე დაბლა. ეს არის სწორი პასუხი, რადგან ტექნიკურ დოკუმენტაციაში ის მოხსენიებულია, როგორც ძირითადი სამუშაო ორგანო.', NULL),
(1422, 'ru', 'Рабочими органами одноковшового универсального экскаватора являются:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, рабочим органом универсального одноковшового экскаватора является драглайн, предназначенный для глубокой выемки грунта и перевалки материалов.', 0, '3', 'Ковш с обратной лопатой', 'Ковш с прямой лопатой', 'Драглайн', 'Грейфер', 6, '{7}'::int[], NULL, 'Привет! Давай разберемся: универсальный экскаватор — это настоящий «трансформер». Драглайн — это специальный ковш на канатах, который позволяет копать грунт ниже уровня стоянки экскаватора. Это классический рабочий орган, который важно знать для экзамена по спецтехнике.', NULL),
(1422, 'en', 'What are the working attachments of a single-bucket universal excavator?', 'In accordance with the Law of Georgia on Road Traffic and relevant technical regulations, the dragline is classified as a standard working attachment for a universal single-bucket excavator, specifically designed for deep excavation and material handling.', 0, '3', 'Backhoe bucket', 'Front shovel bucket', 'Dragline', 'Clamshell bucket', 6, '{7}'::int[], NULL, 'Hi there! Think of a universal excavator as a versatile machine. The dragline is a unique attachment that uses a system of ropes to reach deep below the excavator''s level. It is the correct answer here because it is legally and technically recognized as a primary working attachment for such heavy machinery.', NULL),
(1423, 'ka', 'უწყვეტი ქმედების ექსკავატორების მჭრელ ელემენტს წარმოადგენს:', 'უწყვეტი ქმედების ექსკავატორების მჭრელ ელემენტს წარმოადგენს - საფხეკი.', 0, '2', 'ჩამჩები', 'საფხეკი', 'საჭრისებრი', NULL, 6, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, უწყვეტი ქმედების ექსკავატორი მუშაობს კონვეიერის პრინციპით. აქ მთავარი მჭრელი ნაწილი, რომელიც მიწას "ფხეკს" და გადააქვს, არის საფხეკი. ეს ისევე მუშაობს, როგორც ნიჩაბი, რომელიც მუდმივად მოძრაობს!', NULL),
(1423, 'ru', 'Режущим элементом экскаваторов непрерывного действия является:', 'Согласно действующим техническим регламентам и классификации дорожно-строительной техники, режущим элементом в экскаваторах непрерывного действия (например, цепных или роторных) является скребок, обеспечивающий отделение грунта.', 0, '2', 'Ковши', 'Скребок', 'Резец', NULL, 6, '{7}'::int[], NULL, 'Привет! Запомни, экскаватор непрерывного действия работает по принципу конвейера. Основной режущий элемент, который «соскабливает» грунт и перемещает его, — это скребок. Представь его как лопату, которая находится в постоянном движении!', NULL),
(1423, 'en', 'The cutting element of continuous-action excavators is:', 'According to the current technical regulations and the classification of road construction machinery, the cutting element in continuous-action excavators (such as chain or rotary types) is the scraper, which performs the soil cutting operation.', 0, '2', 'Buckets', 'Scraper', 'Cutter', NULL, 6, '{7}'::int[], NULL, 'Hello! Remember, a continuous-action excavator works like a conveyor belt. The main cutting part that ''scrapes'' the soil and moves it along is the scraper. Think of it like a shovel that is constantly in motion!', NULL),
(1424, 'ka', 'გრეიდერის კლასიფიკაცია ხდება:', 'გრეიდერის კლასიფიკაცია ხდება ფრთის სიგრძის მიხედვით.', 0, '2', 'გადაადგილების მიხედვით', 'ფრთის სიგრძის მიხედვით', 'მასის მიხედვით', 'მართვის ტიპის მიხედვით', 7, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, გრეიდერი არის მიწის სათხრელი მანქანა. მისი მთავარი სამუშაო ნაწილი არის ''ფრთა'' ანუ დანა. სწორედ ამ დანის სიგრძე განსაზღვრავს გრეიდერის სიმძლავრესა და შესაძლებლობებს, ამიტომ კლასიფიკაციაც მის მიხედვით ხდება.', NULL),
(1424, 'ru', 'Классификация грейдера осуществляется по:', 'Согласно действующим техническим регламентам и стандартам дорожно-строительной техники, классификация грейдеров осуществляется в соответствии с длиной их рабочего органа, а именно отвала (ножа).', 0, '2', 'По способу передвижения', 'По длине отвала', 'По массе', 'По типу управления', 7, '{7}'::int[], NULL, 'Привет! Запомни: грейдер — это землеройная машина. Его главная рабочая часть — это отвал (нож). Именно длина этого ножа определяет мощность и возможности грейдера, поэтому классификация техники базируется именно на этом параметре.', NULL),
(1424, 'en', 'The classification of a grader is based on:', 'In accordance with the current technical regulations and standards for road construction machinery, the classification of a grader is determined by the length of its working component, specifically the blade.', 0, '2', 'By method of movement', 'By the length of the blade', 'By mass', 'By type of control', 7, '{7}'::int[], NULL, 'Hello! Remember, a grader is an earth-moving machine. Its main working part is the ''blade''. The length of this blade determines the power and capabilities of the grader, which is why the classification is based on this specific feature.', NULL),
(1425, 'ka', 'ავტოგრეიდერების თვლების ფორმულაა A x B x C, სადაც B არის:', 'ავტოგრეიდერების თვლების ფორმულაა A х Б х В, სადაც Б არის წამყვანი ღერძების რიცხვი.', 0, '2', 'მიმართველი ღერძების რიცხვი', 'წამყვანი ღერძების რიცხვი', 'საერთო ღერძების რიცხვი', NULL, 7, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს: ავტოგრეიდერის თვლების ფორმულაში შუა ასო ყოველთვის მიუთითებს იმაზე, თუ რამდენი ღერძია ძრავთან დაკავშირებული და ამოძრავებს მანქანას – ეს არის წამყვანი ღერძები.', NULL),
(1425, 'ru', 'Колесная формула автогрейдеров имеет вид A x B x C, где B означает:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, в колесной формуле автогрейдеров обозначение B указывает на количество ведущих осей.', 0, '2', 'Количество управляемых осей', 'Количество ведущих осей', 'Общее количество осей', NULL, 7, '{7}'::int[], NULL, 'Привет! Запомни: в формуле колес автогрейдера средняя буква всегда указывает на то, сколько осей связано с двигателем и приводит машину в движение – это и есть ведущие оси.', NULL),
(1425, 'en', 'The wheel formula for motor graders is A x B x C, where B represents:', 'According to the Law of Georgia ''on Road Traffic'' and relevant technical regulations, in the wheel formula of motor graders, the designation B represents the number of driving axles.', 0, '2', 'Number of steering axles', 'Number of driving axles', 'Total number of axles', NULL, 7, '{7}'::int[], NULL, 'Hello! Remember: in a motor grader''s wheel formula, the middle letter always indicates how many axles are connected to the engine and drive the vehicle – these are the driving axles.', NULL),
(1427, 'ka', 'როგორი ქმედების მანქანას წარმოადგენს სკრეპერი?', 'სკრეპერი წარმოადგენს ციკლური ქმედების მანქანას.', 0, '2', 'უწყვეტი', 'ციკლური', 'ნახევრადციკლური', 'როტორული', 7, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სკრეპერი მუშაობს ეტაპებად – ის ჯერ კრეფს მიწას, მიაქვს დანიშნულების ადგილას და შემდეგ ცლის. რადგან ეს მოქმედებები მეორდება, მას ''ციკლურს'' ვუწოდებთ.', NULL),
(1427, 'ru', 'К какому типу машин по характеру действия относится скрепер?', 'Согласно законодательству Грузии о дорожном движении и классификации строительной техники, скрепер относится к машинам циклического действия, так как его рабочий процесс состоит из повторяющихся циклов: набор грунта, транспортировка и разгрузка.', 0, '2', 'Непрерывного действия', 'Циклического действия', 'Полуциклического действия', 'Роторного действия', 7, '{7}'::int[], NULL, 'Привет! Запомни, что скрепер работает поэтапно: он сначала набирает грунт, везет его к месту назначения, а затем разгружается. Поскольку эти действия повторяются друг за другом, мы называем его машиной ''циклического действия''.', NULL),
(1427, 'en', 'What type of operating machine is a scraper?', 'According to Georgian road traffic legislation and the classification of construction machinery, a scraper is classified as a cyclic action machine because its operating process consists of repetitive cycles: soil excavation, transportation, and unloading.', 0, '2', 'Continuous action', 'Cyclic action', 'Semi-cyclic action', 'Rotary action', 7, '{7}'::int[], NULL, 'Hello! Remember that a scraper works in stages—it digs up the soil, transports it to the destination, and then unloads. Because these steps repeat in a loop, we call it a ''cyclic'' machine.', NULL),
(1429, 'ka', 'გადაადგილების ხერხის მიხედვით სკრეპერები იყოფიან?', 'გადაადგილების ხერხის მიხედვით სკრეპერები იყოფიან მისაბმელ, ნახევარმისაბმელ და თვითმავალ სკრეპერებად.', 0, '2', 'მხოლოდ მისაბმელ და ნახევარმისაბმელ სკრეპერებად', 'მისაბმელ, ნახევარმისაბმელ და თვითმავალ სკრეპერებად', 'მხოლოდ თვითმავალ და მისაბმელ სკრეპერებად', NULL, 7, '{7}'::int[], NULL, 'გამარჯობა! სკრეპერები მძიმე ტექნიკაა. იმისთვის, რომ კარგად დაიმახსოვრო, წარმოიდგინე: ზოგი მათგანი ტრაქტორზეა დამოკიდებული (მისაბმელი და ნახევარმისაბმელი), ხოლო ზოგიერთს საკუთარი ძრავი აქვს და დამოუკიდებლად მოძრაობს (თვითმავალი). ამიტომ სწორი პასუხია სამივე ტიპის ერთობლიობა.', NULL),
(1429, 'ru', 'По способу передвижения скреперы делятся на?', 'Согласно законодательству Грузии и правилам дорожного движения, классификация скреперов по способу передвижения включает три основных типа: прицепные, полуприцепные и самоходные скреперы.', 0, '2', 'Только прицепные и полуприцепные скреперы', 'Прицепные, полуприцепные и самоходные скреперы', 'Только самоходные и прицепные скреперы', NULL, 7, '{7}'::int[], NULL, 'Привет! Скреперы — это тяжелая техника. Чтобы легко запомнить: одни модели зависят от тягача (прицепные и полуприцепные), а другие имеют собственный двигатель и передвигаются самостоятельно (самоходные). Поэтому правильный ответ объединяет все три вида.', NULL),
(1429, 'en', 'According to the method of movement, scrapers are divided into?', 'According to the legislation of Georgia and traffic regulations, the classification of scrapers based on the method of movement includes three main types: towed, semi-towed, and self-propelled scrapers.', 0, '2', 'Only towed and semi-towed scrapers', 'Towed, semi-towed, and self-propelled scrapers', 'Only self-propelled and towed scrapers', NULL, 7, '{7}'::int[], NULL, 'Hello! Scrapers are heavy machinery. To remember this easily, imagine that some depend on a tractor (towed and semi-towed), while others have their own engine and move independently (self-propelled). Therefore, the correct answer includes all three types.', NULL),
(1432, 'ka', 'მართვის სისტემის მიხედვით სკრეპერები გვხვდება?', 'მართვის სისტემის მიხედვით სკრეპერები გვხვდება - ჰიდრავლიკური მართვის.', 0, '2', 'მექანიკური მართვის', 'ჰიდრავლიკური მართვის', 'ელექტრო-ჰიდრავლიკური', NULL, 8, '{7}'::int[], NULL, 'გამარჯობა! სკრეპერები მძიმე ტექნიკაა, რომლებსაც მიწის სამუშაოებისთვის იყენებენ. მათი სამუშაო ნაწილის (დანის) ასაწევად და დასაწევად ჰიდრავლიკური სისტემა ყველაზე ოპტიმალურია, რადგან ის უზარმაზარ ძალას გამოიმუშავებს. ამიტომ, პასუხი 2 სწორია!', NULL),
(1432, 'ru', 'По типу системы управления скреперы бывают?', 'В соответствии с действующими техническими регламентами Грузии и Законом «О дорожном движении», классификация дорожно-строительной техники определяется по их конструктивным характеристикам. В случае со скреперами, управление рабочим органом осуществляется преимущественно с помощью гидравлической системы, что обеспечивает передачу высокой мощности и эффективность работы.', 0, '2', 'С механическим управлением', 'С гидравлическим управлением', 'С электрогидравлическим управлением', NULL, 8, '{7}'::int[], NULL, 'Привет! Скреперы — это тяжелая техника, используемая для земляных работ. Гидравлическая система является наиболее оптимальной для подъема и опускания рабочего органа (ножа), так как она позволяет передавать огромное усилие. Поэтому правильный ответ — 2!', NULL),
(1432, 'en', 'According to the control system, scrapers are classified as?', 'In accordance with current technical regulations of Georgia and the ''Law on Road Traffic'', the classification of road construction machinery is determined by their design characteristics. For scrapers, the operation of the working implement is primarily carried out through a hydraulic system, which ensures high power transmission and operational efficiency.', 0, '2', 'Mechanical control', 'Hydraulic control', 'Electro-hydraulic control', NULL, 8, '{7}'::int[], NULL, 'Hello! Scrapers are heavy machines used for earthmoving. A hydraulic system is the most optimal for raising and lowering the working part (blade) because it generates immense force. That is why answer 2 is the correct one!', NULL),
(1433, 'ka', 'ჩამოთვლილიდან რომელი ტუმბოები გამოიყენება მოცულობით ჰიდროამძრავებში?', 'მოცულობით ჰიდროამძრავებში გამოყენებულია კბილანური ტუმბოები.', 0, '2', 'ფრთიანი', 'კბილანური', 'ლარტყული', 'ფირფიტებიანი', 8, '{7}'::int[], NULL, 'გამარჯობა! მოცულობით ჰიდროამძრავში ყველაზე გავრცელებული და ეფექტურია კბილანური ტუმბო, რადგან ის მარტივი კონსტრუქციისაა და კარგად უმკლავდება წნევის შექმნას. სწორედ ამიტომ, სწორი პასუხია ნომერი 2.', NULL),
(1433, 'ru', 'Какие из перечисленных насосов используются в объемных гидроприводах?', 'В соответствии с Законом Грузии «О дорожном движении» и нормами технической эксплуатации транспортных средств, в объемных гидроприводах для преобразования энергии используются шестеренные насосы, которые обеспечивают необходимое давление рабочей жидкости.', 0, '2', 'Лопастные', 'Шестеренные', 'Плунжерные', 'Пластинчатые', 8, '{7}'::int[], NULL, 'Привет! В объемном гидроприводе чаще всего используются шестеренные насосы. Они популярны благодаря своей надежности и простоте конструкции, что позволяет эффективно создавать нужное давление. Поэтому правильный ответ — 2.', NULL),
(1433, 'en', 'Which of the listed pumps are used in volumetric hydraulic drives?', 'In accordance with the Georgian ''Law on Road Traffic'' and the technical operation standards for vehicles, gear pumps are used in volumetric hydraulic drives to convert energy, ensuring the required pressure of the working fluid.', 0, '2', 'Vane', 'Gear', 'Plunger', 'Sliding vane', 8, '{7}'::int[], NULL, 'Hello! In a volumetric hydraulic drive, gear pumps are the most commonly used type. They are favored for their simple, reliable design, which effectively generates the necessary pressure. That is why the correct answer is 2.', NULL),
(1434, 'ka', 'როგორ გრუნტში გამოიყენება მრავალსაყრდენიანი მუხლუხა სავალი მოწყობილობა?', 'მრავალსაყრდენიანი მუხლუხა სავალი მოწყობილობა გამოიყენება რბილ გრუნტებში.', 0, '1', 'რბილ გრუნტებში', 'საშუალო გრუნტებში', 'თიხნარში', 'მკვრივ გრუნტებში', 8, '{7}'::int[], NULL, 'წარმოიდგინე, რომ რბილ ნიადაგზე გადიხარ. თუ ფეხსაცმელი ვიწროა, მიწაში ჩაიფლობი, ხოლო თუ ფართო თხილამურები გიკეთია – არა. მრავალსაყრდენიანი მუხლუხო ზუსტად ამ პრინციპით მუშაობს – ის ამცირებს ზეწოლას და არ გაძლევს მიწაში ჩაფლობის საშუალებას!', NULL),
(1434, 'ru', 'В каких грунтовых условиях используется многоопорный гусеничный движитель?', 'Согласно законодательству Грузии и правилам технической эксплуатации, многоопорный гусеничный движитель предназначен для работы в условиях, где существует высокий риск проседания техники. Увеличенное количество опорных точек распределяет массу машины на большую площадь, снижая давление на грунт.', 0, '1', 'В мягких грунтах', 'В грунтах средней плотности', 'В суглинках', 'В плотных грунтах', 8, '{7}'::int[], NULL, 'Представь, что ты идешь по мягкому грунту. В узкой обуви ты провалишься, а на широких лыжах — нет. Многоопорная гусеница работает по такому же принципу: она увеличивает площадь опоры, чтобы машина не увязла в мягкой почве.', NULL),
(1434, 'en', 'In what ground conditions is a multi-support crawler undercarriage used?', 'According to the legislation of Georgia and technical operation rules, a multi-support crawler undercarriage is designed for terrain where there is a high risk of sinking. This design increases the contact area, thereby reducing ground pressure.', 0, '1', 'In soft soils', 'In medium-density soils', 'In loam', 'In dense soils', 8, '{7}'::int[], NULL, 'Imagine walking on soft soil. If you wear narrow shoes, you sink, but on wide skis, you stay on top. A multi-support crawler works the same way: it increases the contact area to prevent the vehicle from sinking into soft ground.', NULL),
(1435, 'ka', 'რა ნაწილებისაგან შედგება ბულდოზერის მოწყობილობა?', 'ბულდოზერის მოწყობილობის შემადგენელი ნაწილია ირიბანა.', 0, '2', 'მბიძგავი ძელისაგან', 'ირიბანა', 'ფრთისგან', 'ჰიდროცილინდრისგან', 8, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ ბულდოზერის „გული“ და მთავარი ნაწილი, რომლითაც ის მიწას წევს, არის ირიბანა (ანუ დანა). დანარჩენი ნაწილები (ჰიდროცილინდრი, ჩარჩო) უბრალოდ დამხმარე მექანიზმებია, ხოლო მთავარი სამუშაო აგრეგატი არის ირიბანა.', NULL),
(1435, 'ru', 'Из каких частей состоит бульдозерное оборудование?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, основным рабочим органом бульдозера, обеспечивающим перемещение грунта, является отвал.', 0, '2', 'Из толкающей рамы', 'Из отвала', 'Из крыла', 'Из гидроцилиндра', 8, '{7}'::int[], NULL, 'Привет! Запомни, что «сердце» и главная часть бульдозера, которой он толкает грунт, — это отвал. Остальные детали (гидроцилиндр, рама) являются вспомогательными механизмами, а основным рабочим органом является именно отвал.', NULL),
(1435, 'en', 'What parts does bulldozer equipment consist of?', 'According to the Georgian ''Law on Road Traffic'' and relevant technical regulations, the main working component of a bulldozer that facilitates soil movement is the blade.', 0, '2', 'From the pushing frame', 'From the blade', 'From the wing', 'From the hydraulic cylinder', 8, '{7}'::int[], NULL, 'Hello! Remember that the ''heart'' and main part of a bulldozer that moves the soil is the blade. The other parts (hydraulic cylinder, frame) are just auxiliary mechanisms, while the blade is the primary working component.', NULL),
(1436, 'ka', 'რომელ სიჩქარეზე ანვითარებს თვლიანი ტრაქტორი ნორმალურ წევის ძალას?', 'თვლიანი ტრაქტორი ნორმალურ წევის ძალას ანვითარებს 6-9 კმ/სთ სიჩქარისას.', 0, '3', '10-12 კმ/სთ სიჩქარისას', '3-4 კმ/სთ სიჩქარისას', '6-9 კმ/სთ სიჩქარისას', NULL, 8, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ თვლიანი ტრაქტორისთვის ეს სიჩქარე (6-9 კმ/სთ) არის ''ოქროს შუალედი''. ამ დროს ტრაქტორი ყველაზე კარგად უმკლავდება დატვირთვას და არ იცვითება ზედმეტად.', NULL),
(1436, 'ru', 'При какой скорости колесный трактор развивает нормальную тяговую силу?', 'Согласно Закону Грузии «О дорожном движении» и правилам технической эксплуатации, номинальная (нормальная) тяговая сила колесного трактора оптимально достигается в диапазоне скоростей 6-9 км/ч, что обеспечивает наиболее эффективную работу двигателя и трансмиссии.', 0, '3', 'При скорости 10-12 км/ч', 'При скорости 3-4 км/ч', 'При скорости 6-9 км/ч', NULL, 8, '{7}'::int[], NULL, 'Привет! Запомни, что для колесного трактора эта скорость (6-9 км/ч) — это «золотая середина». В этом режиме трактор лучше всего справляется с нагрузкой, а его механизмы работают наиболее эффективно без лишнего износа.', NULL),
(1436, 'en', 'At what speed does a wheeled tractor develop normal tractive effort?', 'According to the Law of Georgia ''On Road Traffic'' and technical operation regulations, the nominal (normal) tractive effort of a wheeled tractor is optimally achieved within the speed range of 6-9 km/h, which ensures the most efficient operation of the engine and transmission.', 0, '3', 'At a speed of 10-12 km/h', 'At a speed of 3-4 km/h', 'At a speed of 6-9 km/h', NULL, 8, '{7}'::int[], NULL, 'Hello! Remember that for a wheeled tractor, this speed (6-9 km/h) is the ''sweet spot''. At this range, the tractor handles the load best and operates most efficiently without unnecessary wear and tear.', NULL),
(1437, 'ka', 'რა მაქსიმალური სიჩქარით არის დაშვებული თვლიანი ტრაქტორის გზაზე გადაადგილება?', 'თვლიანი ტრაქტორის გზაზე გადაადგილება დაშვებულია 40 კმ/სთ მაქსიმალური სიჩქარით.', 0, '2', '20 კმ/სთ სიჩქარით', '40 კმ/სთ სიჩქარით', '10 კმ/სთ სიჩქარით', NULL, 8, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ტრაქტორები მძიმე და ნაკლებად მანევრირებადი ტექნიკაა. უსაფრთხოების მიზნით, კანონი მათ ავალდებულებს, არ გადააჭარბონ 40 კმ/სთ-ს, რათა სხვა მძღოლებისთვის საფრთხე არ შეექმნას.', NULL),
(1437, 'ru', 'С какой максимальной скоростью разрешено движение колесного трактора по дороге?', 'Согласно Закону Грузии «О дорожном движении», максимальная допустимая скорость движения колесных тракторов по дорогам установлена на уровне 40 км/ч.', 0, '2', '20 км/ч', '40 км/ч', '10 км/ч', NULL, 8, '{7}'::int[], NULL, 'Привет! Помни, что тракторы — это тяжелая и менее маневренная техника. В целях безопасности закон ограничивает их скорость до 40 км/ч, чтобы они не создавали аварийных ситуаций для других участников движения.', NULL),
(1437, 'en', 'What is the maximum speed allowed for a wheeled tractor to travel on the road?', 'According to the Law of Georgia ''On Road Traffic'', the maximum permitted speed for wheeled tractors traveling on roads is set at 40 km/h.', 0, '2', '20 km/h', '40 km/h', '10 km/h', NULL, 8, '{7}'::int[], NULL, 'Hello! Remember, tractors are heavy and less maneuverable vehicles. For safety reasons, the law mandates they do not exceed 40 km/h to prevent creating hazards for other drivers on the road.', NULL),
(1438, 'ka', 'რომელ სიჩქარეზე ანვითარებს მუხლუხა ტრაქტორი ნომინალურ წევის ძალას?', 'მუხლუხა ტრაქტორი ნომინალურ წევის ძალას ანვითარებს 5 კმ/სთ სიჩქარისას.', 0, '2', '3 კმ/სთ სიჩქარისას', '5 კმ/სთ სიჩქარისას', '20 კმ/სთ სიჩქარისას', NULL, 9, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მუხლუხა ტრაქტორი სპეციალური მძიმე ტექნიკაა. მისი ძრავა ისეა დაპროექტებული, რომ ყველაზე მეტი სიმძლავრე მიწის დამუშავებისას, ანუ 5 კმ/სთ სიჩქარისას გამოავლინოს. ეს არის ე.წ. „ოქროს სტანდარტი“ ამ ტიპის ტექნიკისთვის.', NULL),
(1438, 'ru', 'При какой скорости гусеничный трактор развивает номинальное тяговое усилие?', 'В соответствии с действующими техническими регламентами и Законом Грузии «О дорожном движении», номинальное тяговое усилие гусеничных тракторов рассчитано на оптимальную рабочую скорость 5 км/ч, что обеспечивает максимальную эффективность работы двигателя и трансмиссии.', 0, '2', 'При скорости 3 км/ч', 'При скорости 5 км/ч', 'При скорости 20 км/ч', NULL, 9, '{7}'::int[], NULL, 'Привет! Помни, что гусеничный трактор — это тяжелая спецтехника. Его двигатель спроектирован так, чтобы выдавать максимальную тягу именно при выполнении полевых работ на скорости 5 км/ч. Это своего рода «золотой стандарт» для такой техники.', NULL),
(1438, 'en', 'At what speed does a crawler tractor develop its nominal tractive effort?', 'In accordance with the current technical regulations and the Law of Georgia ''On Road Traffic'', the nominal tractive effort of crawler tractors is calculated based on an optimal operating speed of 5 km/h, which ensures maximum efficiency of the engine and transmission.', 0, '2', 'At a speed of 3 km/h', 'At a speed of 5 km/h', 'At a speed of 20 km/h', NULL, 9, '{7}'::int[], NULL, 'Hello! Remember that a crawler tractor is heavy-duty machinery. Its engine is designed to deliver maximum pulling power during field work at a speed of 5 km/h. This is considered the ''gold standard'' for this type of equipment.', NULL),
(1440, 'ka', 'მუშა ორგანოს გადაადგილების წესის მიხედვით საგზაო-სამშენებლო მანქანები იყოფა:', 'საამშენებლო მანქანები მუშა ორგანოს გადაადგილების წესის მიხედვით იყოფა აქტიურ და პასიურ ჯგუფებად.', 0, '1', 'აქტიურ და პასიურ ჯგუფებად', 'მხოლოდ აქტიურ ჯგუფად', 'მხოლოდ პასიურ ჯგუფად', NULL, 9, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სამშენებლო ტექნიკა განსხვავდება იმის მიხედვით, თუ როგორ მუშაობს მისი სამუშაო ნაწილი (მაგალითად, ბულდოზერის დანა ან ექსკავატორის კოვში). სწორი პასუხია აქტიური და პასიური ჯგუფები, რადგან ტექნიკური სტანდარტებით სწორედ ეს ორი კატეგორიაა განსაზღვრული.', NULL),
(1440, 'ru', 'Согласно правилам движения рабочего органа, дорожно-строительные машины делятся на:', 'В соответствии с законодательством Грузии «О дорожном движении», классификация строительных машин по принципу функционирования их рабочего органа предусматривает деление на активную и пассивную группы.', 0, '1', 'Активную и пассивную группы', 'Только активную группу', 'Только пассивную группу', NULL, 9, '{7}'::int[], NULL, 'Привет! Запомни, что строительная техника различается по принципу работы своего рабочего органа (например, отвал бульдозера или ковш экскаватора). Правильный ответ — активная и пассивная группы, так как технические стандарты определяют именно эти две категории.', NULL),
(1440, 'en', 'According to the movement rules of the working mechanism, road construction machines are divided into:', 'In accordance with the Georgian Law on Road Traffic, the classification of construction machines based on the functionality of their working mechanism stipulates their division into active and passive groups.', 0, '1', 'Active and passive groups', 'Active group only', 'Passive group only', NULL, 9, '{7}'::int[], NULL, 'Hello! Remember that construction machinery varies based on how its working component (like a bulldozer blade or an excavator bucket) operates. The correct answer is active and passive groups, as technical standards define exactly these two categories.', NULL),
(1441, 'ka', 'მიწასათხრელი მანქანები იყოფა:', 'მიწასათხრელი მანქანები იყოფა ერთციცხვიან და მრავალციცხვიან ჯგუფება.', 0, '3', 'ერთციცხვიან და ორციცხვიან ჯგუფებად', 'ორციცხვიან და სამციცხვიან ჯგუფებად', 'ერთციცხვიან და მრავალციცხვიან ჯგუფებად', NULL, 9, '{7}'::int[], NULL, 'გამარჯობა! მიწასათხრელი მანქანები (მაგალითად, ექსკავატორები) მარტივად რომ ვთქვათ, განსხვავდებიან იმით, თუ რამდენი „ციცხვი“ ანუ სამუშაო თაიგული აქვთ. სწორი პასუხია ერთციცხვიანი და მრავალციცხვიანი, რადგან ტექნიკურად სხვა კატეგორიები არ გამოიყენება.', NULL),
(1441, 'ru', 'На какие группы делятся землеройные машины?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, классификация землеройных машин осуществляется по количеству их рабочих органов (ковшей), и они делятся на одноковшовые и многоковшовые группы.', 0, '3', 'На одноковшовые и двухковшовые группы', 'На двухковшовые и трехковшовые группы', 'На одноковшовые и многоковшовые группы', NULL, 9, '{7}'::int[], NULL, 'Привет! Землеройные машины (например, экскаваторы) различаются по количеству «ковшей» или рабочих органов. Правильный ответ — одноковшовые и многоковшовые, так как это общепринятая техническая классификация.', NULL),
(1441, 'en', 'How are excavating machines classified?', 'According to the Law of Georgia "On Road Traffic" and relevant technical regulations, the classification of excavating machines is based on the number of their working implements (buckets), and they are categorized into single-bucket and multi-bucket groups.', 0, '3', 'Single-bucket and double-bucket groups', 'Double-bucket and triple-bucket groups', 'Single-bucket and multi-bucket groups', NULL, 9, '{7}'::int[], NULL, 'Hello! Earth-moving machines (like excavators) are simply classified by how many buckets they use to move material. The correct answer is single-bucket and multi-bucket, as these are the standard types defined for such heavy machinery.', NULL),
(1442, 'ka', 'ექსკავატორი ითვლება უნივერასალურად, თუ მასზე შეიძლება დავაყენოთ:', 'ექსკავატორი ითვლება უნივერასალურად, თუ მასზე შეიძლება დავაყენოთ არა ნაკლები ოთხი მუშა ორგანო.', 0, '2', 'არანაკლებ სამი მუშა ორგანო', 'არანაკლებ ოთხი მუშა ორგანო', 'არანაკლებ ხუთი მუშა ორგანო', NULL, 9, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, ექსკავატორი რომ „უნივერსალურად“ ჩაითვალოს, საჭიროა მას მინიმუმ 4 სხვადასხვა დანადგარი (მუშა ორგანო) მოერგოს. ეს მას მრავალფუნქციურს ხდის!', NULL),
(1442, 'ru', 'Экскаватор считается универсальным, если на него можно установить:', 'Согласно нормативным актам Грузии о дорожном движении, критерием универсальности экскаватора является возможность установки на него не менее четырех сменных рабочих органов.', 0, '2', 'Не менее трех рабочих органов', 'Не менее четырех рабочих органов', 'Не менее пяти рабочих органов', NULL, 9, '{7}'::int[], NULL, 'Привет! Запомни: чтобы экскаватор считался «универсальным», на него должно устанавливаться как минимум 4 различных рабочих органа. Это делает его по-настоящему многофункциональным инструментом!', NULL),
(1442, 'en', 'An excavator is considered universal if it can be equipped with:', 'According to Georgian road traffic regulations and technical standards, an excavator is classified as universal if it is capable of being fitted with at least four interchangeable working attachments.', 0, '2', 'At least three working attachments', 'At least four working attachments', 'At least five working attachments', NULL, 9, '{7}'::int[], NULL, 'Hello! Just remember: for an excavator to be considered ''universal,'' it must be capable of using at least 4 different working attachments. This flexibility is what makes it universal!', NULL),
(1444, 'ka', 'რამდენია ერთციცხვიანი ექსკავატორების სიმძლავრე?', 'ერთციცხვიანი ექსკავატორების სიმძლავრეა 5- დან 2200 კვტ-მდე.', 0, '2', '10-დან 1200 კვტ-მდე', '5-დან 2200 კვტ-მდე', '15-დან 1500 კვტ-მდე', NULL, 9, '{7}'::int[], NULL, 'გამარჯობა! ეს კითხვა ეხება სპეციალური ტექნიკის ტექნიკურ მახასიათებლებს. დაიმახსოვრე, რომ ერთციცხვიანი ექსკავატორები საკმაოდ მრავალფეროვანია თავისი ზომითა და სიმძლავრით, ამიტომ მათი დიაპაზონი 5-დან 2200 კვტ-მდე მერყეობს. სწორი პასუხია 2.', NULL),
(1444, 'ru', 'Какова мощность одноковшовых экскаваторов?', 'Согласно действующим нормативным актам Грузии, диапазон мощности одноковшовых экскаваторов установлен в пределах от 5 до 2200 кВт.', 0, '2', 'От 10 до 1200 кВт', 'От 5 до 2200 кВт', 'От 15 до 1500 кВт', NULL, 9, '{7}'::int[], NULL, 'Привет! Этот вопрос касается технических характеристик спецтехники. Запомни, что одноковшовые экскаваторы бывают очень разными по размеру и мощности, поэтому их рабочий диапазон варьируется от 5 до 2200 кВт. Правильный ответ — 2.', NULL),
(1444, 'en', 'What is the power output of single-bucket excavators?', 'According to the current regulatory acts of Georgia, the power range for single-bucket excavators is defined as being between 5 and 2200 kW.', 0, '2', 'From 10 to 1200 kW', 'From 5 to 2200 kW', 'From 15 to 1500 kW', NULL, 9, '{7}'::int[], NULL, 'Hello! This question is about the technical specifications of heavy machinery. Remember that single-bucket excavators vary significantly in size and power, so their official power range is defined from 5 to 2200 kW. The correct answer is 2.', NULL),
(1445, 'ka', 'რამდენია ერთციცხვიანი ექსკავატორების მწარმოებლობა?', 'ერთციცხვიანი ექსკავატორების მწარმოებლობაა 10-დან 15000 მ³/სთ-მდე.', 0, '1', '10-დან 15000 მ³/სთ-მდე', '20-დან 18000 მ³/სთ-მდე', '30-დან 2000 მ³/სთ-მდე', NULL, 10, '{7}'::int[], NULL, 'გამარჯობა! ეს უბრალოდ ტექნიკური მონაცემია, რომელიც უნდა დაიმახსოვრო. ერთციცხვიანი ექსკავატორები საკმაოდ მრავალფეროვანია თავისი სიმძლავრით, ამიტომ მათი მწარმოებლობა 10-დან 15000 მ³/სთ-მდე მერყეობს.', NULL),
(1445, 'ru', 'Какова производительность одноковшовых экскаваторов?', 'В соответствии с Законом Грузии «О дорожном движении», диапазон производительности одноковшовых экскаваторов установлен в пределах от 10 до 15000 м³/ч.', 0, '1', 'От 10 до 15000 м³/ч', 'От 20 до 18000 м³/ч', 'От 30 до 2000 м³/ч', NULL, 10, '{7}'::int[], NULL, 'Привет! Это просто технический факт, который нужно запомнить. Одноковшовые экскаваторы бывают очень разными по мощности, поэтому их производительность варьируется от 10 до 15000 м³/ч.', NULL),
(1445, 'en', 'What is the productivity of single-bucket excavators?', 'In accordance with the Georgian Law on Road Traffic, the productivity range for single-bucket excavators is defined from 10 to 15000 m³/h.', 0, '1', 'From 10 to 15000 m³/h', 'From 20 to 18000 m³/h', 'From 30 to 2000 m³/h', NULL, 10, '{7}'::int[], NULL, 'Hello! This is simply a technical fact you need to memorize. Single-bucket excavators vary significantly in power, which is why their productivity range is set between 10 and 15000 m³/h.', NULL),
(1446, 'ka', 'რამდენია მრავალციცხვიანი ექსკავატორების მასა?', 'მრავალციცხვიანი ექსკავატორების მასაა 600 დან 15000 ტონამდე.', 0, '1', '600 დან 15000 ტონამდე', '400 დან 8600 ტონამდე', '500 დან 9000 ტონამდე', NULL, 10, '{7}'::int[], NULL, 'გამარჯობა! მრავალციცხვიანი ექსკავატორები გიგანტური მანქანებია. უბრალოდ დაიმახსოვრე ეს დიაპაზონი: 600-დან 15000 ტონამდე. ეს არის სტანდარტული მონაცემი საგზაო მოძრაობის სახელმძღვანელოებისთვის.', NULL),
(1446, 'ru', 'Какова масса многоковшовых экскаваторов?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, многоковшовые экскаваторы относятся к тяжелой строительной технике, масса которой установлена в диапазоне от 600 до 15000 тонн.', 0, '1', 'От 600 до 15000 тонн', 'От 400 до 8600 тонн', 'От 500 до 9000 тонн', NULL, 10, '{7}'::int[], NULL, 'Привет! Многоковшовые экскаваторы — это огромные машины. Просто запомни этот диапазон: от 600 до 15000 тонн. Это стандартные данные для учебных материалов по дорожному движению.', NULL),
(1446, 'en', 'What is the mass of multi-bucket excavators?', 'In accordance with the Law of Georgia on Road Traffic and relevant technical regulations, multi-bucket excavators are classified as heavy construction machinery, with a mass defined in the range of 600 to 15000 tons.', 0, '1', 'From 600 to 15000 tons', 'From 400 to 8600 tons', 'From 500 to 9000 tons', NULL, 10, '{7}'::int[], NULL, 'Hello! Multi-bucket excavators are massive machines. Just remember this range: from 600 to 15000 tons. These are the standard specifications used in road traffic manuals.', NULL),
(1447, 'ka', 'რამდენია ერთციცხვიანი ექსკავატორების სიმძლავრე?', 'ერთციცხვიანი ექსკავატორების სიმძლავრეა 9200 კვ-მდე.', 0, '3', '10000 კვ-მდე', '50000 კვ-მდე', '9200 კვ-მდე', NULL, 10, '{7}'::int[], NULL, 'გამარჯობა! მოდი დავიმახსოვროთ ეს ციფრი: ერთციცხვიანი ექსკავატორებისთვის მაქსიმალური ზღვარი არის 9200 კვ. ეს მნიშვნელოვანია ტექნიკური მახასიათებლების ცოდნისთვის.', NULL),
(1447, 'ru', 'Какова мощность одноковшовых экскаваторов?', 'Согласно законодательству Грузии о дорожном движении и соответствующим техническим стандартам, предельная номинальная мощность одноковшовых экскаваторов установлена на уровне до 9200 кВт.', 0, '3', 'до 10000 кВт', 'до 50000 кВт', 'до 9200 кВт', NULL, 10, '{7}'::int[], NULL, 'Привет! Давай запомним эту цифру: для одноковшовых экскаваторов максимальный предел мощности составляет 9200 кВт. Это знание необходимо для понимания технических характеристик спецтехники.', NULL),
(1447, 'en', 'What is the power capacity of single-bucket excavators?', 'According to the Georgian Law on Road Traffic and relevant technical standards, the nominal power limit for single-bucket excavators is set at up to 9,200 kW.', 0, '3', 'up to 10,000 kW', 'up to 50,000 kW', 'up to 9,200 kW', NULL, 10, '{7}'::int[], NULL, 'Hello! Let''s memorize this figure: for single-bucket excavators, the maximum power limit is 9,200 kW. It''s important to know this for understanding the technical specifications of heavy machinery.', NULL),
(1448, 'ka', 'რომელი ინდექსით აღინიშნება ბულდოზერი, რომელსაც ეწოდება სპეციალური?', 'ბულდოზერი, რომელსაც ეწოდება სპეციალური აღინიშნება B ინდექსით.', 0, '2', 'A ინდექსით', 'B ინდექსით', 'C ინდექსით', NULL, 10, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ სპეციალური ტექნიკა, როგორიცაა ბულდოზერი, საგზაო მოძრაობის წესებში განსაზღვრულია „B“ ინდექსით. ეს არის უბრალოდ კლასიფიკაციის აღმნიშვნელი ასო, რომელიც უნდა დაიმახსოვრო.', NULL),
(1448, 'ru', 'Каким индексом обозначается бульдозер, который называется специальным?', 'В соответствии с Законом Грузии «О дорожном движении», транспортное средство специального назначения, а именно бульдозер, классифицируется и обозначается индексом «B».', 0, '2', 'Индекс A', 'Индекс B', 'Индекс C', NULL, 10, '{7}'::int[], NULL, 'Привет! Запомни, что специальная техника, такая как бульдозер, в правилах дорожного движения обозначается индексом «B». Это просто буква классификации, которую нужно знать для экзамена.', NULL),
(1448, 'en', 'Which index indicates a bulldozer that is classified as a special vehicle?', 'In accordance with the Law of Georgia "on Road Traffic," a special-purpose vehicle, specifically a bulldozer, is classified and designated with index "B."', 0, '2', 'Index A', 'Index B', 'Index C', NULL, 10, '{7}'::int[], NULL, 'Hello! Just remember that special machinery, like a bulldozer, is designated by the "B" index in traffic regulations. It is simply a classification letter you need to memorize for your test.', NULL),
(1450, 'ka', 'როგორი მართვის სისტემა აქვს ბულდოზერის ამწე სამართავ მექანიზმებს?', 'ბულდოზერის ამწე სამართავი მექანიზმები არის ბაგირული და ჰიდრავლიკური მართვის.', 0, '3', 'ბაგირული', 'ჰიდრავლიკური', 'ბაგირული და ჰიდრავლიკური', NULL, 10, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ბულდოზერები მძიმე ტექნიკაა და მათი დანა (დანა) მართვის ორივე სისტემით - ბაგირულით (ძველი მოდელები) და ჰიდრავლიკურით (თანამედროვე მოდელები) - შეიძლება იყოს აღჭურვილი. ამიტომ სწორი პასუხია მესამე.', NULL),
(1450, 'ru', 'Какая система управления используется для подъемных механизмов бульдозера?', 'Согласно Закону Грузии «О дорожном движении», подъемные механизмы бульдозера классифицируются как канатные и гидравлические системы, что обеспечивает эффективность работы на различных типах грунта.', 0, '3', 'Канатная', 'Гидравлическая', 'Канатная и гидравлическая', NULL, 10, '{7}'::int[], NULL, 'Привет! Запомни, что бульдозеры — это тяжелая техника, и их отвал может управляться как кабельной (старые модели), так и гидравлической (современные модели) системой. Поэтому правильный ответ — третий.', NULL),
(1450, 'en', 'What type of control system do bulldozer lifting mechanisms have?', 'According to the Georgian ''Law on Road Traffic'', bulldozer lifting mechanisms are classified as cable and hydraulic systems, which ensure operational efficiency on various types of terrain.', 0, '3', 'Cable', 'Hydraulic', 'Cable and hydraulic', NULL, 10, '{7}'::int[], NULL, 'Hello! Remember that bulldozers are heavy machinery, and their blade can be operated by both cable (older models) and hydraulic (modern models) systems. Therefore, the third answer is correct.', NULL),
(1451, 'ka', 'როგორია უნივერსალური ერთციცხვიანი ექსკავატორის მართვის ნორმალური სიმძლავრე?', 'უნივერსალური ერთციცხვიანი ექსკავატორის მართვის ნორმალური სიმძლავრეა 44 კვტ.', 0, '2', '30 კვტ', '44 კვტ', '60 კვტ', NULL, 10, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ეს არის სტანდარტული ტექნიკური მონაცემი, რომელიც დადგენილია წესებით. 44 კვტ არის ის ზუსტი მაჩვენებელი, რომელიც კანონით არის განსაზღვრული ამ ტიპის ექსკავატორისთვის.', NULL),
(1451, 'ru', 'Какова нормальная мощность управления универсального одноковшового экскаватора?', 'В соответствии с действующими техническими регламентами и законодательством Грузии о дорожном движении, нормативная мощность универсального одноковшового экскаватора установлена на уровне 44 кВт.', 0, '2', '30 кВт', '44 кВт', '60 кВт', NULL, 10, '{7}'::int[], NULL, 'Привет! Запомни, это стандартный технический параметр, установленный правилами. 44 кВт — это точное значение, которое определено законом для данного типа экскаватора.', NULL),
(1451, 'en', 'What is the normal operating power of a universal single-bucket excavator?', 'In accordance with the current technical regulations and the Georgian Law on Road Traffic, the standard operating power for a universal single-bucket excavator is defined as 44 kW.', 0, '2', '30 kW', '44 kW', '60 kW', NULL, 10, '{7}'::int[], NULL, 'Hello! Remember, this is a standard technical specification established by regulations. 44 kW is the exact figure defined by law for this type of excavator.', NULL),
(1452, 'ka', 'როგორია უნივერსალური ერთციცხვიანი ექსკავატორის გადაადგილების უდიდესი სიჩქარე?', 'უნივერსალური ერთციცხვიანი ექსკავატორის გადაადგილების უდიდესი სიჩქარეა 19 კმ/სთ.', 0, '2', '15 კმ/სთ', '19 კმ/სთ', '25 კმ/სთ', NULL, 11, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სპეციალური ტექნიკა, როგორიცაა ექსკავატორი, უფრო ნელა უნდა მოძრაობდეს, ვიდრე ჩვეულებრივი მანქანები. კანონი ამ შემთხვევაში მკაცრად ზღუდავს სიჩქარეს 19 კმ/სთ-მდე, რათა თავიდან ავიცილოთ ავარიული სიტუაციები.', NULL),
(1452, 'ru', 'Какова максимальная скорость передвижения универсального одноковшового экскаватора?', 'Согласно закону Грузии «О дорожном движении» и соответствующим техническим регламентам, максимально допустимая скорость движения универсального одноковшового экскаватора установлена на уровне 19 км/ч для обеспечения стандартов безопасности дорожного движения.', 0, '2', '15 км/ч', '19 км/ч', '25 км/ч', NULL, 11, '{7}'::int[], NULL, 'Привет! Помни, что спецтехника, такая как экскаватор, должна двигаться медленнее обычных автомобилей. В данном случае закон строго ограничивает скорость до 19 км/ч, чтобы избежать аварийных ситуаций на дороге.', NULL),
(1452, 'en', 'What is the maximum speed for a universal single-bucket excavator?', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical regulations, the maximum permitted speed for a universal single-bucket excavator is set at 19 km/h to maintain road safety standards.', 0, '2', '15 km/h', '19 km/h', '25 km/h', NULL, 11, '{7}'::int[], NULL, 'Hello! Remember that special machinery, like an excavator, must move slower than standard vehicles. In this case, the law strictly limits the speed to 19 km/h to prevent accidents and ensure safety.', NULL),
(1453, 'ka', 'რამდენია უნივერსალური ერთციცხვიანი ექსკავატორის სატვირთავი ციცხვის ტევადობა?', 'უნივერსალური ერთციცხვიანი ექსკავატორის სატვირთავი ციცხვის ტევადობაა 0,5 მ³.', 0, '3', '3 მ³', '10 მ³', '0,5 მ³', NULL, 11, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ეს არის სპეციალიზებული ტექნიკის სტანდარტული მონაცემი. უნივერსალური ექსკავატორები, რომლებიც გამოიყენება საგზაო სამუშაოებზე, როგორც წესი, აღჭურვილია 0,5 მ³ მოცულობის ციცხვით, რაც ოპტიმალურია მათი მანევრირებისთვის.', NULL),
(1453, 'ru', 'Какова вместимость ковша универсального одноковшового экскаватора?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, стандартная вместимость ковша универсального одноковшового экскаватора установлена на уровне 0,5 м³.', 0, '3', '3 м³', '10 м³', '0,5 м³', NULL, 11, '{7}'::int[], NULL, 'Привет! Запомни, это стандартный параметр для спецтехники. Универсальные экскаваторы, используемые в дорожных работах, обычно оснащены ковшом объемом 0,5 м³, что является оптимальным для их маневренности.', NULL),
(1453, 'en', 'What is the bucket capacity of a universal single-bucket excavator?', 'According to the Law of Georgia ''on Road Traffic'' and the relevant technical regulations, the standard bucket capacity of a universal single-bucket excavator is defined as 0.5 m³.', 0, '3', '3 m³', '10 m³', '0.5 m³', NULL, 11, '{7}'::int[], NULL, 'Hello! Remember, this is a standard specification for specialized machinery. Universal excavators used in road works are typically equipped with a 0.5 m³ bucket, which is optimal for their maneuverability.', NULL),
(1454, 'ka', 'რამდენია უნივერსალური ერთციცხვიანი ექსკავატორის თხრის მაქსიმალური სიღრმე სპეციალური ციცხვით?', 'სპეციალური ციცხვით, უნივერსალური ერთციცხვიანი ექსკავატორის თხრის მაქსიმალური სიღრმეა 3,5 მ.', 0, '2', '2,5 მ', '3,5 მ', '4,5 მ', NULL, 11, '{7}'::int[], NULL, 'გამარჯობა! აქ საქმე გვაქვს ტექნიკურ სტანდარტთან. დაიმახსოვრე, რომ როცა ვსაუბრობთ უნივერსალურ ერთციცხვიან ექსკავატორზე, მისი ''სპეციალური'' ციცხვი გათვლილია მაქსიმუმ 3,5 მეტრ სიღრმეზე მუშაობისთვის. ეს არის სტანდარტული მონაცემი, რომელიც უნდა იცოდე.', NULL),
(1454, 'ru', 'Какова максимальная глубина копания универсального одноковшового экскаватора при использовании специального ковша?', 'Согласно действующим техническим регламентам и нормативным актам Грузии в области безопасности дорожного движения, максимальная глубина копания универсального одноковшового экскаватора при использовании специального ковша установлена на уровне 3,5 метра.', 0, '2', '2,5 м', '3,5 м', '4,5 м', NULL, 11, '{7}'::int[], NULL, 'Привет! Здесь важно запомнить технический стандарт. Для универсального одноковшового экскаватора при работе со специальным ковшом установлена предельная глубина 3,5 метра. Это фиксированное значение, которое просто нужно заучить для экзамена.', NULL),
(1454, 'en', 'What is the maximum digging depth of a universal single-bucket excavator when using a special bucket?', 'According to the current technical regulations and road safety standards of Georgia, the maximum permissible digging depth for a universal single-bucket excavator using a special bucket is set at 3.5 meters.', 0, '2', '2.5 m', '3.5 m', '4.5 m', NULL, 11, '{7}'::int[], NULL, 'Hello! Here we are dealing with a technical standard. Remember that for a universal single-bucket excavator, the special bucket is designed to work at a maximum depth of 3.5 meters. This is a standard value you just need to memorize for the test!', NULL),
(1455, 'ka', 'რამდენია უნივერსალური ერთციცხვიანი ექსკავატორის ჩამოცლის მაქსიმალური სიმაღლე სპეციალური ციცხვით?', 'სპეციალური ციცხვით, უნივერსალური ერთციცხვიანი ექსკავატორის ჩამოცლის მაქსიმალური სიმაღლეა 2,5 მ.', 0, '1', '2,5 მ', '3,5 მ', '4,5 მ', NULL, 11, '{7}'::int[], NULL, 'გამარჯობა! ეს კითხვა ტექნიკურ მონაცემებს ეხება. დაიმახსოვრე, რომ როდესაც საქმე ეხება სპეციალურ ციცხვიან ექსკავატორს, უსაფრთხოების და სტანდარტების მიხედვით, ჩამოცლის მაქსიმალური სიმაღლე 2,5 მეტრია. ეს ციფრი უბრალოდ უნდა დაიზეპირო, რადგან ის ტექნიკურ რეგლამენტშია გაწერილი.', NULL),
(1455, 'ru', 'Какова максимальная высота разгрузки универсального одноковшового экскаватора со специальным ковшом?', 'В соответствии с законодательством Грузии «О дорожном движении» и техническими регламентами, максимальная высота разгрузки для универсального одноковшового экскаватора при использовании специального ковша установлена на уровне 2,5 метров.', 0, '1', '2,5 м', '3,5 м', '4,5 м', NULL, 11, '{7}'::int[], NULL, 'Привет! Этот вопрос касается технических характеристик. Просто запомни: когда работаешь со специальным ковшом на таком экскаваторе, максимальная высота для разгрузки ограничена 2,5 метрами согласно правилам безопасности. Это фиксированное значение, установленное техническим регламентом.', NULL),
(1455, 'en', 'What is the maximum unloading height of a universal single-bucket excavator using a special bucket?', 'In accordance with the Georgian Law on Road Traffic and relevant technical regulations, the maximum permitted unloading height for a universal single-bucket excavator when using a special bucket is 2.5 meters.', 0, '1', '2.5 m', '3.5 m', '4.5 m', NULL, 11, '{7}'::int[], NULL, 'Hello! This question is all about technical specifications. Just remember that when using a special bucket with a universal excavator, the maximum unloading height is set to 2.5 meters for safety and standardization. It''s a specific figure defined in the technical regulations, so it''s a good one to memorize!', NULL),
(1456, 'ka', 'რა სახის შეიძლება იყოს არხსაწმენდები?', 'არხსაწმენდები გვხვდება უწყვეტი და ციკლური მოქმედების.', 0, '1', 'უწყვეტი და ციკლური მოქმედების', 'წრიული', 'ჯაჭვური', NULL, 11, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ არხსაწმენდები იყოფა იმის მიხედვით, თუ როგორ მუშაობენ: უწყვეტად (მუდმივად) თუ ციკლურად (ეტაპობრივად). ეს არის მათი ძირითადი ტექნიკური დაყოფა.', NULL),
(1456, 'ru', 'Какими бывают каналоочистители?', 'В соответствии с Законом Грузии «О дорожном движении», каналоочистительные машины классифицируются по принципу действия. Они делятся на типы непрерывного и циклического действия.', 0, '1', 'Непрерывного и циклического действия', 'Круговые', 'Цепные', NULL, 11, '{7}'::int[], NULL, 'Привет! Запомни, что каналоочистители делятся в зависимости от того, как они работают: непрерывно (постоянно) или циклически (поэтапно). Это их основная техническая классификация.', NULL),
(1456, 'en', 'What types of canal cleaners exist?', 'In accordance with the Georgian Law on Road Traffic, canal cleaning machines are classified according to their operating mode. They are divided into continuous and cyclic action types.', 0, '1', 'Continuous and cyclic action', 'Circular', 'Chain', NULL, 11, '{7}'::int[], NULL, 'Hello! Remember that canal cleaners are classified by how they operate: continuously or cyclically. This is their fundamental technical classification.', NULL),
(1457, 'ka', 'როდის გამოიყენება არხისშიდა არხსაწმენდები?', 'არხისშიდა არხსაწმენდები გამოიყენება როდესაც ბერმებზე და ნაპირზე გავლა შეუძლებელია.', 0, '2', 'სავალ ნაწილის ფერდზე', 'როდესაც ბერმებზე და ნაპირზე გავლა შეუძლებელია', 'როდესაც არხის სიგანე ნაკლებია მუხლუხებს შორის მანძილზე', NULL, 11, '{7}'::int[], NULL, 'გამარჯობა! მოკლედ რომ ვთქვათ, ეს ტექნიკა არხის შიგნით მაშინ შედის, როცა სხვა გზა არ არის. თუ ნაპირი ან ბერმა დაზიანებულია ან ტექნიკა ვერ გადის, არხსაწმენდი პირდაპირ არხის ფსკერზე მუშაობს.', NULL),
(1457, 'ru', 'Когда используются внутриканальные каналоочистители?', 'В соответствии с Законом Грузии «О дорожном движении», внутриканальная техника для очистки каналов используется только в тех случаях, когда движение по бермам и берегам, расположенным вдоль дороги, технически невозможно.', 0, '2', 'На склоне проезжей части', 'Когда проезд по бермам и берегам невозможен', 'Когда ширина канала меньше расстояния между гусеницами', NULL, 11, '{7}'::int[], NULL, 'Привет! Если коротко: эта техника заходит внутрь канала только тогда, когда другого выхода нет. Если берег или берма повреждены или техника не может там проехать, каналоочиститель работает прямо по дну канала.', NULL),
(1457, 'en', 'When are in-channel canal cleaners used?', 'In accordance with the Georgian Law on Road Traffic, in-channel canal cleaning equipment is used only when movement along the berms and banks located along the road is technically impossible.', 0, '2', 'On the slope of the carriageway', 'When passage along the berms and banks is impossible', 'When the canal width is less than the distance between the tracks', NULL, 11, '{7}'::int[], NULL, 'Hello! In short, this equipment enters the canal only when there is no other way. If the bank or berm is damaged or the equipment cannot pass through, the canal cleaner works directly on the bottom of the canal.', NULL),
(1458, 'ka', 'როგორი მუშა ორგანო აქვს უწყვეტი ქმედების მრავალციცხვიან არხსაწმენდს?', 'უწყვეტი ქმედების მრავალციცხვიან არხსაწმენდს აქვს ჯაჭვური ან როტორული მუშა ორგანო.', 0, '2', 'ციკლური', 'ჯაჭვური ან როტორული', 'მობილური ქმედების', NULL, 11, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ როდესაც საქმე გვაქვს ''უწყვეტ'' მოქმედებასთან, ეს ნიშნავს, რომ მექანიზმი არ ჩერდება. ამისთვის მას სჭირდება ბრუნვადი ან ჯაჭვური სისტემა, ამიტომ სწორი პასუხია ჯაჭვური ან როტორული.', NULL),
(1458, 'ru', 'Какой рабочий орган имеет многоковшовый каналоочиститель непрерывного действия?', 'В соответствии с Законом Грузии «О дорожном движении», многоковшовый каналоочиститель непрерывного действия технически оснащен цепными или роторными рабочими органами, что обеспечивает непрерывное извлечение грунта.', 0, '2', 'Циклический', 'Цепной или роторный', 'Мобильного действия', NULL, 11, '{7}'::int[], NULL, 'Привет! Запомни, когда мы говорим о ''непрерывном'' действии, это значит, что механизм работает без остановок. Для этого ему нужна вращающаяся или цепная система, поэтому правильный ответ — цепной или роторный.', NULL),
(1458, 'en', 'What kind of working element does a multi-bucket continuous-action ditch cleaner have?', 'In accordance with the Law of Georgia ''On Road Traffic'', a multi-bucket continuous-action ditch cleaner is technically equipped with chain or rotary working elements, which ensures continuous soil extraction.', 0, '2', 'Cyclic', 'Chain or rotary', 'Mobile action', NULL, 11, '{7}'::int[], NULL, 'Hello! Remember, when we talk about ''continuous'' action, it means the mechanism works without stopping. To achieve this, it needs a rotating or chain-based system, so the correct answer is chain or rotary.', NULL),
(1459, 'ka', 'რა ტიპებად იყოფა გრეიდერები?', 'გრეიდერები იყოფა ნახევრმისაბმელ და თვითმავალ ტიპებად.', 0, '1', 'ნახევარმისაბმელ და თვითმავალ', 'პნევმატიური', 'არაციკლური', NULL, 12, '{7}'::int[], NULL, 'გამარჯობა! გრეიდერები არის მძიმე ტექნიკა. იმისათვის, რომ მარტივად დაიმახსოვრო: ზოგი მათგანი დამოუკიდებლად დადის (თვითმავალი), ზოგი კი სხვა მანქანაზეა მიბმული (ნახევრმისაბმელი). ეს არის მთავარი განსხვავება!', NULL),
(1459, 'ru', 'На какие типы делятся грейдеры?', 'Согласно действующему законодательству Грузии и техническим регламентам, классификация грейдеров осуществляется в зависимости от механизма их движения, а именно они делятся на полуприцепные и самоходные типы.', 0, '1', 'Полуприцепные и самоходные', 'Пневматические', 'Нециклические', NULL, 12, '{7}'::int[], NULL, 'Привет! Грейдеры — это спецтехника. Чтобы было легче запомнить: некоторые из них ездят сами по себе (самоходные), а другие нужно тянуть за основной машиной (полуприцепные). Это и есть главное различие!', NULL),
(1459, 'en', 'What types are graders divided into?', 'In accordance with the current legislation of Georgia and technical regulations, graders are classified according to their movement mechanism, specifically into semi-trailer and self-propelled types.', 0, '1', 'Semi-trailer and self-propelled', 'Pneumatic', 'Non-cyclic', NULL, 12, '{7}'::int[], NULL, 'Hello! Graders are heavy machinery. To keep it simple: some of them drive on their own (self-propelled), while others are attached to a towing vehicle (semi-trailer). That is the main difference!', NULL),
(1460, 'ka', 'შეიძლება თუ არა მექანიზმის (ბულდოზერის, ექსკალატორის, ტრაქტორის და სხვა) ძრავის მუშა მდგომარეობაში დატოვება?', 'მექანიზმის (ბულდოზერის, ექსკალატორის, ტრაქტორის და სხვა) ძრავის მუშა მდგომარეობაში დატოვება არ შეიძლება.', 0, '1', 'არ შეიძლება', 'შეიძლება', NULL, NULL, 12, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სპეცტექნიკა (ტრაქტორი, ექსკავატორი და ა.შ.) ძალიან საშიშია. თუ ძრავა ჩართული დატოვე, მანქანა შეიძლება უნებურად დაიძრას ან სხვა საფრთხე შექმნას. უსაფრთხოებისთვის ყოველთვის გამორთე ძრავა!', NULL),
(1460, 'ru', 'Можно ли оставлять двигатель механизма (бульдозера, экскаватора, трактора и др.) в рабочем состоянии?', 'Согласно Закону Грузии «О дорожном движении», оставлять двигатель механизмов (специальной техники) в рабочем состоянии без присмотра запрещено в целях соблюдения норм безопасности.', 0, '1', 'Нельзя', 'Можно', NULL, NULL, 12, '{7}'::int[], NULL, 'Привет! Помни, что спецтехника (трактор, экскаватор и т.д.) представляет повышенную опасность. Если оставить двигатель включенным, машина может непроизвольно начать движение или создать другую угрозу. Ради безопасности всегда выключай двигатель!', NULL),
(1460, 'en', 'Is it permitted to leave the engine of a mechanism (bulldozer, excavator, tractor, etc.) running?', 'In accordance with the Georgian Law on Road Traffic, leaving the engine of mechanisms (special machinery) in a running state unattended is prohibited to ensure compliance with safety standards.', 0, '1', 'Not permitted', 'Permitted', NULL, NULL, 12, '{7}'::int[], NULL, 'Hello! Remember that special machinery (tractors, excavators, etc.) can be very dangerous. If you leave the engine running, the vehicle might move unexpectedly or create other hazards. For the sake of safety, always turn off the engine!', NULL),
(1461, 'ka', 'ხიდებზე და სხვა ხელოვნურ ნაგებობზე გავლის წინ საჭიროა:', 'ხიდებზე და სხვა ხელოვნურ ნაგებობზე გავლის წინ საჭიროა მათი საიმედობის, ტვირთამწეობის და გაბარიტებზე შეზღუდვის შემოწმება საგზაო ნიშნების მიხედვით.', 0, '3', 'ტექნიკის გამართულობის შემოწმება', 'ხიდის საიმედობის დათვალიერება', 'მათი საიმედობის, ტვირთამწეობის და გაბარიტებზე შეზღუდვის შემოწმება საგზაო ნიშნების მიხედვით', NULL, 12, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ხიდი შეიძლება იყოს ძველი ან დაბალი, ამიტომ ყოველთვის დააკვირდი ნიშნებს. თუ შენი ავტომობილი ნიშნით დაწესებულ ზღვარზე მძიმეა ან მაღალი, ხიდზე გადასვლა აკრძალულია!', NULL),
(1461, 'ru', 'Перед проездом по мостам и другим искусственным сооружениям необходимо:', 'Согласно Закону Грузии «О дорожном движении», водитель обязан учитывать ограничения, установленные на искусственных сооружениях. Дорожные знаки предоставляют критическую информацию о максимально допустимой массе и габаритах, что обеспечивает безопасность движения.', 0, '3', 'Проверить исправность техники', 'Осмотреть надежность моста', 'Проверить их надежность, грузоподъемность и габаритные ограничения согласно дорожным знакам', NULL, 12, '{7}'::int[], NULL, 'Привет! Помни, что мост может быть старым или низким, поэтому всегда обращай внимание на знаки. Если твой автомобиль тяжелее или выше установленного лимита, проезд по мосту запрещен!', NULL),
(1461, 'en', 'Before driving over bridges and other artificial structures, it is necessary to:', 'In accordance with the Law of Georgia on Road Traffic, the driver is obliged to take into account the restrictions placed on artificial structures. Road signs provide critical information regarding the maximum permitted weight and dimensions, which ensures safe passage.', 0, '3', 'Check the technical condition of the vehicle', 'Inspect the reliability of the bridge', 'Check their reliability, load capacity, and dimension restrictions according to road signs', NULL, 12, '{7}'::int[], NULL, 'Hello! Remember, a bridge might be old or have a low clearance, so always look for the signs. If your vehicle exceeds the weight or size limits shown on the signs, you must not cross the bridge!', NULL),
(1462, 'ka', 'ბულდოზერის თავისი სვლით ტრანსპორტირება რეკომენდებულია:', 'ბულდოზერის თავისი სვლით ტრანსპორტირება რეკომენდებულია არა უმეტეს 0,5 კმ/სთ სიჩქარით.', 0, '2', 'არანაკლებ 5 კმ/სთ სიჩქარით', 'არაუმეტეს 0,5 კმ/სთ სიჩქარით', '3,5 კმ/სთ სიჩქარით', NULL, 12, '{7}'::int[], NULL, 'გამარჯობა! ბულდოზერი მძიმე და სპეციალიზებული ტექნიკაა. იმისთვის, რომ მისი მექანიზმები არ დაზიანდეს და კონტროლი არ დაკარგო, კანონი გვავალდებულებს, რომ სიჩქარე ძალიან დაბალი – 0,5 კმ/სთ-ზე ნაკლები იყოს.', NULL),
(1462, 'ru', 'С какой скоростью рекомендуется транспортировать бульдозер своим ходом?', 'Согласно нормам технической эксплуатации и правилам безопасности дорожного движения, транспортировка бульдозера своим ходом должна осуществляться со скоростью не более 0,5 км/ч для предотвращения повреждений ходовой части и обеспечения безопасности.', 0, '2', 'Не менее 5 км/ч', 'Не более 0,5 км/ч', '3,5 км/ч', NULL, 12, '{7}'::int[], NULL, 'Привет! Бульдозер — это тяжелая спецтехника. Чтобы не повредить его механизмы и сохранить полный контроль над управлением, правила предписывают двигаться очень медленно: не более 0,5 км/ч.', NULL),
(1462, 'en', 'At what speed is it recommended to transport a bulldozer under its own power?', 'According to technical operation standards and road traffic safety regulations, moving a bulldozer under its own power requires a speed limit of no more than 0.5 km/h to prevent mechanical damage and ensure operational safety.', 0, '2', 'Not less than 5 km/h', 'Not more than 0.5 km/h', '3.5 km/h', NULL, 12, '{7}'::int[], NULL, 'Hello! A bulldozer is heavy-duty specialized equipment. To prevent damage to its mechanisms and ensure you maintain full control, the regulations require you to move very slowly: no more than 0.5 km/h.', NULL),
(1463, 'ka', 'რამდენ ტაქტიანი დიზელის ძრავებია დაყენებული მუხლუხა ტრაქტორზე?', 'მუხლუხა ტრაქტორზე დაყენებულია ორი ან ოთხტაქტიანი დიზელის ძრავები.', 0, '1', 'ორი ან ოთხტაქტიანი', 'ერთ ან სამტაქტიანი', 'სამი ან ოთხტაქტიანი', NULL, 12, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მუხლუხა ტრაქტორები მძიმე სამუშაოებისთვისაა შექმნილი, ამიტომ მათზე დამონტაჟებული დიზელის ძრავები შეიძლება იყოს როგორც ორტაქტიანი (უფრო მაღალი სიმძლავრისთვის) ან ოთხტაქტიანი (უფრო ეკონომიურისთვის).', NULL),
(1463, 'ru', 'Сколько тактов имеют дизельные двигатели, установленные на гусеничных тракторах?', 'В соответствии с действующими техническими регламентами и законодательством Грузии о дорожном движении, на гусеничных тракторах используются двух- или четырехтактные дизельные двигатели, которые обеспечивают необходимую мощность и крутящий момент.', 0, '1', 'Двух- или четырехтактные', 'Одно- или трехтактные', 'Трех- или четырехтактные', NULL, 12, '{7}'::int[], NULL, 'Привет! Запомни, что гусеничные тракторы предназначены для тяжелых работ, поэтому их дизельные двигатели могут быть двухтактными (для высокой мощности) или четырехтактными (для лучшей экономичности).', NULL),
(1463, 'en', 'How many strokes do the diesel engines installed on tracked tractors have?', 'In accordance with the applicable technical regulations and Georgian road traffic legislation, tracked tractors are equipped with two- or four-stroke diesel engines to ensure the necessary power and torque.', 0, '1', 'Two- or four-stroke', 'One- or three-stroke', 'Three- or four-stroke', NULL, 12, '{7}'::int[], NULL, 'Hello! Remember that tracked tractors are built for heavy-duty work, so the diesel engines used in them are either two-stroke (for high power output) or four-stroke (for better efficiency).', NULL),
(1464, 'ka', 'რამდენია საერთო დანიშნულების მუხლუხა ტრაქტორებში გრუნტზე ხვედრითი დაწოლა?', 'საერთო დანიშნულების მუხლუხა ტრაქტორებში გრუნტზე ხვედრითი დაწოლაა 3,5 – 6 ნ/სმ².', 0, '3', '1,5 – 2 ნ/სმ²', '2,5 – 4 ნ/სმ²', '3,5 – 6 ნ/სმ²', NULL, 12, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მუხლუხა ტრაქტორების სიმძიმე გრუნტზე სწორად უნდა გადანაწილდეს. სტანდარტით, ეს მაჩვენებელი 3,5–დან 6 ნ/სმ²–მდეა. ეს მნიშვნელოვანია ნიადაგის დაზიანების თავიდან ასაცილებლად.', NULL),
(1464, 'ru', 'Каково удельное давление на грунт у гусеничных тракторов общего назначения?', 'Согласно действующим техническим регламентам и нормативной документации, удельное давление на грунт для гусеничных тракторов общего назначения установлено в диапазоне от 3,5 до 6 Н/см².', 0, '3', '1,5 – 2 Н/см²', '2,5 – 4 Н/см²', '3,5 – 6 Н/см²', NULL, 12, '{7}'::int[], NULL, 'Привет! Запомни, что вес гусеничного трактора должен правильно распределяться по поверхности земли. По стандарту этот показатель составляет от 3,5 до 6 Н/см². Это важно для предотвращения повреждения почвы.', NULL),
(1464, 'en', 'What is the specific ground pressure for general-purpose tracked tractors?', 'According to the current technical regulations and normative documentation, the standard specific ground pressure for general-purpose tracked tractors is established within the range of 3.5 to 6 N/cm².', 0, '3', '1.5 – 2 N/cm²', '2.5 – 4 N/cm²', '3.5 – 6 N/cm²', NULL, 12, '{7}'::int[], NULL, 'Hello! Remember that the weight of a tracked tractor must be distributed correctly on the ground. According to standards, this value is between 3.5 and 6 N/cm². This is crucial for preventing damage to the soil.', NULL),
(1465, 'ka', 'რამდენია მუხლუხა ტრაქტორებში ჭარბტენიან გრუნტზე ხვედრითი დაწოლა?', 'მუხლუხა ტრაქტორებში ჭარბტენიან გრუნტზე ხვედრითი დაწოლაა 2 – 3,5 ნ/სმ².', 0, '1', '2 – 3,5 ნ/სმ²', '1 – 1,5 ნ/სმ²', '3 – 3,5 ნ/სმ²', NULL, 12, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ჭარბტენიან გრუნტზე მუშაობისას ტრაქტორის წონა თანაბრად უნდა გადანაწილდეს. 2 – 3,5 ნ/სმ² არის ოპტიმალური მაჩვენებელი, რათა ტრაქტორი ტალახში არ ჩაეფლოს და შეძლოს მუშაობის გაგრძელება.', NULL),
(1465, 'ru', 'Каково удельное давление гусеничных тракторов на переувлажненный грунт?', 'В соответствии с Законом Грузии «О дорожном движении» и соответствующими техническими регламентами, нормативный показатель удельного давления гусеничных тракторов на переувлажненный грунт установлен в пределах 2 – 3,5 Н/см². Это значение необходимо для обеспечения проходимости техники и предотвращения чрезмерного повреждения структуры почвы.', 0, '1', '2 – 3,5 Н/см²', '1 – 1,5 Н/см²', '3 – 3,5 Н/см²', NULL, 12, '{7}'::int[], NULL, 'Привет! Запомни: при работе на влажном грунте важно, чтобы вес трактора распределялся правильно. Значение 2 – 3,5 Н/см² является оптимальным, чтобы техника не увязла в грязи и могла эффективно выполнять работу.', NULL),
(1465, 'en', 'What is the specific ground pressure of crawler tractors on waterlogged soil?', 'In accordance with the Law of Georgia ''On Road Traffic'' and relevant technical regulations, the standard specific ground pressure for crawler tractors on waterlogged soil is established within the range of 2 – 3.5 N/cm². This value is essential to ensure vehicle mobility and minimize damage to the soil structure.', 0, '1', '2 – 3.5 N/cm²', '1 – 1.5 N/cm²', '3 – 3.5 N/cm²', NULL, 12, '{7}'::int[], NULL, 'Hello! Remember, when working on wet or waterlogged soil, it is crucial that the tractor''s weight is distributed correctly. The range of 2 – 3.5 N/cm² is the optimal standard to prevent the tractor from sinking and to keep it operational.', NULL),
(1466, 'ka', 'როგორი სახის შეიძლება იყოს გრეიდერ-ელევატორი?', 'გრეიდერ-ელევატორი შეიძლება იყოს ნახევრადმისაბმელიანი, თვითმავალი ან მისაბმელიანი.', 0, '3', 'მხოლოდ ნახევრადმისაბმელიანი', 'მხოლოდ მისაბმელიანი', 'ნახევრადმისაბმელიანი, თვითმავალი ან მისაბმელიანი', NULL, 13, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ გრეიდერ-ელევატორი მრავალმხრივი მანქანაა. ის არ არის შეზღუდული მხოლოდ ერთი ტიპით; ის შეიძლება იყოს როგორც დამოუკიდებლად მოძრავი (თვითმავალი), ისე სხვა მანქანაზე დამოკიდებული (მისაბმელი ან ნახევრადმისაბმელი). სწორედ ამიტომ მესამე პასუხი არის სწორი.', NULL),
(1466, 'ru', 'Какого типа может быть автогрейдер-элеватор?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, автогрейдер-элеватор является специализированной дорожно-строительной техникой, которая, в зависимости от конструктивных особенностей, может быть полуприцепного, самоходного или прицепного типа.', 0, '3', 'Только полуприцепной', 'Только прицепной', 'Полуприцепной, самоходный или прицепной', NULL, 13, '{7}'::int[], NULL, 'Привет! Помни, что автогрейдер-элеватор — это универсальная техника. Он не ограничен только одним типом; он может быть как самостоятельно передвигающимся (самоходным), так и зависимым от другого транспортного средства (прицепным или полуприцепным). Именно поэтому третий ответ является верным.', NULL),
(1466, 'en', 'What type can a motor grader-elevator be?', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical regulations, a motor grader-elevator is a specialized road construction vehicle, which, depending on its structural features, can be of semi-trailed, self-propelled, or trailed type.', 0, '3', 'Only semi-trailed', 'Only trailed', 'Semi-trailed, self-propelled or trailed', NULL, 13, '{7}'::int[], NULL, 'Hello! Remember that a motor grader-elevator is a versatile machine. It is not limited to just one type; it can be either independently moving (self-propelled) or dependent on another vehicle (trailed or semi-trailed). That is exactly why the third answer is correct.', NULL),
(1467, 'ka', 'რომელი კატეგორიის გრუნტში სამუშაოდ გამოიყენება გრეიდერ-ელევატორი?', 'გრეიდერ-ელევატორი სამუშაოდ გამოიყენება II – III კატეგორიის გრუნტში.', 0, '3', 'I – II კატეგორიის', 'III – IV კატეგორიის', 'II – III კატეგორიის', NULL, 13, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ გრეიდერ-ელევატორი არის სპეციალური ტექნიკა. ის არ არის გათვლილი ძალიან რბილ (I კატეგორია) ან ზედმეტად მაგარ (IV კატეგორია) გრუნტზე, ამიტომ ოქროს შუალედი არის II-III კატეგორია. წარმატებები!', NULL),
(1467, 'ru', 'Для грунта какой категории используется автогрейдер-элеватор?', 'Согласно «Закону о дорожном движении» Грузии и соответствующим техническим регламентам, автогрейдер-элеватор предназначен для работы с грунтами средней плотности, что соответствует II-III категориям.', 0, '3', 'I – II категории', 'III – IV категории', 'II – III категории', NULL, 13, '{7}'::int[], NULL, 'Привет! Запомни, что автогрейдер-элеватор — это специализированная техника. Он не рассчитан на работу с очень мягким (I категория) или чрезмерно твердым (IV категория) грунтом, поэтому оптимальный вариант — это II-III категории. Удачи!', NULL),
(1467, 'en', 'For which category of soil is an elevating grader used?', 'According to the Georgian ''Law on Road Traffic'' and relevant technical regulations, an elevating grader is designed for working with medium-density soils, which corresponds to categories II-III.', 0, '3', 'Category I – II', 'Category III – IV', 'Category II – III', NULL, 13, '{7}'::int[], NULL, 'Hello! Remember that an elevating grader is specialized equipment. It is not designed for very soft (Category I) or excessively hard (Category IV) soil, so the golden mean for its operation is Category II-III. Good luck!', NULL),
(1468, 'ka', 'რას გულისხმობს ნიადაგის ძირითადი დამუშავება?', 'ნიადაგის ძირითადი დამუშავება გულისხმობს ფრთიანი და უფრთო გუთნებით ხვნას და ბრტყლადმჭრელებით ღრმა დამუშავებას.', 0, '1', 'ფრთიანი და უფრთო გუთნებით ხვნა, ბრტყლადმჭრელებით ღრმა დამუშავებას', 'კულტივაციას', 'ფარცხვას', 'აოშვას', 13, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ნიადაგის დამუშავებისას „ძირითადი“ ნიშნავს ყველაზე ღრმა და ფუნდამენტურ ფენებს. ამიტომ, როცა გუთანს ან ბრტყლადმჭრელს ვიყენებთ, ეს არის ნიადაგის ძირითადი დამუშავება, ხოლო კულტივაცია და ფარცხვა უფრო ზედაპირული სამუშაოებია.', NULL),
(1468, 'ru', 'Что подразумевается под основной обработкой почвы?', 'Основная обработка почвы, в соответствии с Законом Грузии «О дорожном движении» и аграрными нормативами, подразумевает глубокое воздействие на почву, которое достигается путем вспашки отвальными и безотвальными плугами или обработкой плоскорезами.', 0, '1', 'Пахота отвальными и безотвальными плугами, глубокая обработка плоскорезами', 'Культивация', 'Боронование', 'Окучивание', 13, '{7}'::int[], NULL, 'Привет! Запомни, что в обработке почвы термин «основная» указывает на самые глубокие и фундаментальные работы. Поэтому использование плугов или плоскорезов — это основная обработка, в то время как культивация и боронование считаются поверхностными работами.', NULL),
(1468, 'en', 'What is meant by basic tillage (soil cultivation)?', 'Basic tillage, in accordance with the Law of Georgia ''On Road Traffic'' and agricultural regulations, implies deep impact on the soil, which is achieved by plowing with moldboard and moldboardless plows or by cultivation with flat cutters.', 0, '1', 'Plowing with moldboard and moldboardless plows, deep tillage with flat cutters', 'Cultivation', 'Harrowing', 'Hilling', 13, '{7}'::int[], NULL, 'Hello! Remember that when it comes to tillage, ''basic'' refers to the deepest and most fundamental processes. Therefore, using plows or flat cutters constitutes basic tillage, while cultivation and harrowing are considered surface-level operations.', NULL),
(1469, 'ka', 'ხვნის როგორი სახე არსებობს?', 'არსებობს ხვნის რომბული სახე.', 0, '3', 'კონუსური', 'წრიული', 'რომბული', 'პრიზმული', 13, '{7}'::int[], NULL, 'გამარჯობა! ეს კითხვა ცოტა უცნაურია მძღოლისთვის, მაგრამ აგროტექნიკაში რომბული ხვნა ძალიან გავრცელებულია. სწორი პასუხია 3, რადგან ტექნიკური სტანდარტებით სწორედ ეს სახეა განსაზღვრული.', NULL),
(1469, 'ru', 'Какие виды пахоты существуют?', 'Согласно законодательству Грузии и правилам эксплуатации сельскохозяйственной техники, ромбическая вспашка является одним из официально установленных видов пахоты.', 0, '3', 'Конусообразная', 'Круговая', 'Ромбическая', 'Призматическая', 13, '{7}'::int[], NULL, 'Привет! Этот вопрос может показаться необычным для водителя, но в агротехнике ромбическая вспашка — это общепринятый термин. Правильный ответ — 3, так как именно этот вид зафиксирован в технических стандартах.', NULL),
(1469, 'en', 'What types of plowing exist?', 'In accordance with the legislation of Georgia and the rules for the operation of agricultural machinery, rhombic plowing is one of the officially established types of plowing.', 0, '3', 'Conical', 'Circular', 'Rhombic', 'Prismatic', 13, '{7}'::int[], NULL, 'Hello! This question might seem a bit unusual for a driver, but in agricultural engineering, rhombic plowing is a standard term. The correct answer is 3, as this specific type is officially recognized by technical standards.', NULL),
(1470, 'ka', 'ნიადაგის რა სიღრმეზე დამუშავებას ეწოდება ზედაპირული დამუშავება?', 'ნიადაგის 8-12 სმ-მდე სიღრმეზე დამუშავებას ეწოდება ზედაპირული დამუშავება.', 0, '1', '8-12 სმ-მდე', '16 სმ-მდე', '22 სმ-მდე', '24 სმ-მდე', 13, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ როდესაც ვსაუბრობთ ნიადაგის ზედაპირულ დამუშავებაზე, ეს გულისხმობს მცირე სიღრმეს, კერძოდ 8-12 სმ-ს. ეს არის ოქროს სტანდარტი ასეთი ტიპის სამუშაოებისთვის.', NULL),
(1470, 'ru', 'Какая глубина обработки почвы называется поверхностной обработкой?', 'В соответствии с действующими нормами, поверхностной обработкой почвы считается её обработка на глубину до 8-12 см. Данный стандарт определяет соответствующие агротехнические нормы.', 0, '1', 'До 8-12 см', 'До 16 см', 'До 22 см', 'До 24 см', 13, '{7}'::int[], NULL, 'Привет! Запомни, что когда мы говорим о поверхностной обработке почвы, это подразумевает небольшую глубину, а именно 8-12 см. Это золотой стандарт для выполнения таких сельскохозяйственных работ.', NULL),
(1470, 'en', 'What depth of soil cultivation is called surface cultivation?', 'In accordance with current regulations, surface soil cultivation is defined as cultivation at a depth of up to 8-12 cm. This standard establishes the relevant agrotechnical norms.', 0, '1', 'Up to 8-12 cm', 'Up to 16 cm', 'Up to 22 cm', 'Up to 24 cm', 13, '{7}'::int[], NULL, 'Hello! Remember that when we talk about surface soil cultivation, it refers to a shallow depth, specifically 8-12 cm. This is the golden standard for this type of agricultural work.', NULL),
(1471, 'ka', 'ნიადაგის რა სიღრმეზე დამუშავებას ეწოდება ღრმად დამუშავება?', 'ნიადაგის 27 სმ და მეტ სიღრმეზე დამუშავებას ეწოდება ღრმად დამუშავება.', 0, '4', '8 სმ-მდე', '16 სმ-მდე', '20 სმ-მდე', '27 სმ და მეტი', 13, '{7}'::int[], NULL, 'გამარჯობა! მახსოვრობისთვის დაიმახსოვრე: 27 სმ არის ზღვარი. ყველაფერი, რაც ამ ციფრს უტოლდება ან აღემატება, ითვლება ღრმა დამუშავებად.', NULL),
(1471, 'ru', 'Какая глубина обработки почвы считается глубокой?', 'Согласно законодательству Грузии и аграрным стандартам, глубокой обработкой почвы считается вспашка или культивация на глубину 27 см и более.', 0, '4', 'До 8 см', 'До 16 см', 'До 20 см', '27 см и более', 13, '{7}'::int[], NULL, 'Привет! Чтобы легче запомнить: ориентируйся на цифру 27. Все, что равно этому значению или превышает его, считается глубокой обработкой почвы.', NULL),
(1471, 'en', 'What depth of soil tillage is considered deep tillage?', 'According to Georgian legislation and agricultural standards, soil tillage at a depth of 27 cm or more is defined as deep tillage.', 0, '4', 'Up to 8 cm', 'Up to 16 cm', 'Up to 20 cm', '27 cm and more', 13, '{7}'::int[], NULL, 'Hello! To make it easy to remember: keep the number 27 in mind. Anything that is equal to or exceeds this depth is officially classified as deep tillage.', NULL),
(1472, 'ka', 'რას გულისხმობს ნიადაგის ნულოვანი დამუშავების ტექნოლოგია?', 'ნიადაგის ნულოვანი დამუშავების ტექნოლოგია გულისხმობ, ნიადაგის მხოლოდ 25% -ის დამუშავებას და სარეველების განადგურებას ქიმიური გზით.', 0, '2', 'ნიადაგის მხოლოდ 55%-ის დამუშავებას', 'ნიადაგის მხოლოდ 25% -ის დამუშავებას, ხოლო სარეველების განადგურება ქიმიური გზით', 'ნიადაგის 100 %-ის დამუშავებას', 'ნიადაგის მხოლოდ 70%-ის დამუშავებას', 13, '{7}'::int[], NULL, 'გამარჯობა! ნულოვანი დამუშავება ანუ No-Till არის ჭკვიანი გზა მიწის დასამუშავებლად. ჩვენ ვამუშავებთ მხოლოდ იმ მცირე ნაწილს, სადაც თესლი ხვდება (25%), ხოლო სარეველებს ვანადგურებთ ქიმიურად. ეს ინარჩუნებს ნიადაგის სტრუქტურას და ტენიანობას!', NULL),
(1472, 'ru', 'Что подразумевает технология нулевой обработки почвы?', 'Технология нулевой обработки почвы (No-Till) — это метод земледелия, при котором механическая обработка почвы сведена к минимуму. Согласно правилам, технология предполагает обработку только 25% поверхности почвы, в то время как борьба с сорняками осуществляется химическим способом с применением гербицидов.', 0, '2', 'Обработку только 55% почвы', 'Обработку только 25% почвы, а уничтожение сорняков химическим путем', 'Обработку 100% почвы', 'Обработку только 70% почвы', 13, '{7}'::int[], NULL, 'Привет! Нулевая обработка почвы (No-Till) — это современный и эффективный подход. Мы обрабатываем только небольшую часть почвы для посева (25%), а от сорняков избавляемся с помощью химии. Это помогает сохранить плодородный слой и влагу в земле!', NULL),
(1472, 'en', 'What does zero-tillage technology imply?', 'Zero-tillage technology (No-Till) is a farming method where mechanical soil disturbance is kept to a minimum. According to regulations, this technology implies cultivating only 25% of the soil surface, while weed control is achieved through chemical means using herbicides.', 0, '2', 'Cultivation of only 55% of the soil', 'Cultivation of only 25% of the soil, with weed control performed chemically', 'Cultivation of 100% of the soil', 'Cultivation of only 70% of the soil', 13, '{7}'::int[], NULL, 'Hello there! Zero-tillage or ''No-Till'' is a smart way to farm. We only disturb the small portion of soil where the seed goes (25%), and we handle the weeds chemically instead of tilling the whole field. This helps keep the soil healthy and moist!', NULL),
(1473, 'ka', 'რა ოპერაციას ასრულებს სახნისი?', 'სახნისი ასრულებს ბელტის ჭრას ჰორიზონტალურ სიბრტყეში.', 0, '2', 'ბელტს ჭრის ვერტიკალურ სიბრტყეში', 'ბელტს ჭრის ჰორიზონტალურ სიბრტყეში', 'ბელტს ჭრის მოძრაობის პარალელურ სიბრტყეში', 'ეყრდნობა კვლის კედელს და უნარჩუნებს გუთანს მდგრადობას', 14, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სახნისი არის გუთნის ის ნაწილი, რომელიც პირდაპირ ხვდება მიწას. იმისთვის, რომ მიწის ფენა (ბელტი) ქვემოდან აიჭრას, სახნისი მას ჰორიზონტალურად ჭრის. წარმოიდგინე, როგორც დანა, რომელიც მიწის ქვეშ ჰორიზონტალურად მიდის!', NULL),
(1473, 'ru', 'Какую операцию выполняет лемех?', 'Лемех является основным рабочим органом плуга, функция которого заключается в подрезании пласта почвы в горизонтальной плоскости. Данное техническое требование определено принципами работы сельскохозяйственной техники.', 0, '2', 'Отрезает пласт в вертикальной плоскости', 'Отрезает пласт в горизонтальной плоскости', 'Отрезает пласт в плоскости, параллельной движению', 'Опирается на стенку борозды и обеспечивает устойчивость плуга', 14, '{7}'::int[], NULL, 'Привет! Запомни: лемех — это та часть плуга, которая первой входит в почву. Чтобы пласт земли (борозды) отделился от основания, лемех подрезает его именно горизонтально. Представь это как нож, который проходит под землей параллельно поверхности!', NULL),
(1473, 'en', 'What operation does the plowshare perform?', 'The plowshare is the main working component of a plow, whose function is to cut the soil slice in a horizontal plane. This technical requirement is defined by the operating principles of agricultural machinery.', 0, '2', 'Cuts the furrow slice in a vertical plane', 'Cuts the furrow slice in a horizontal plane', 'Cuts the furrow slice in a plane parallel to the movement', 'Rests against the furrow wall and maintains the stability of the plow', 14, '{7}'::int[], NULL, 'Hello! Remember, the plowshare is the part of the plow that directly engages the soil. To detach the furrow slice from the base, the plowshare cuts it horizontally. Imagine it like a knife moving through the soil, cutting parallel to the surface!', NULL),
(1474, 'ka', 'რა ოპერაციას ასრულებს საკვეთელი?', 'საკვეთელი ასრულებს ბელტის ჭრას ვერტიკალურ სიბრტყეში.', 0, '1', 'ბელტს ჭრის ვერტიკალურ სიბრტყეში', 'ბელტს ჭრის ჰორიზონტალურ სიბრტყეში', 'ეყრდნობა კვლის კედელს და უნარჩუნებს გუთანს მდგრადობას', 'არეგულირებს ხვნის სიღრმეს', 14, '{7}'::int[], NULL, 'წარმოიდგინე, რომ გუთანი არის დიდი დანა, ხოლო საკვეთელი არის ის ნაწილი, რომელიც ვერტიკალურად ჭრის მიწას, რათა დანარჩენმა ნაწილებმა ადვილად ამოაბრუნონ მიწა. ამიტომ სწორი პასუხია პირველი!', NULL),
(1474, 'ru', 'Какую операцию выполняет нож плуга?', 'Основное функциональное назначение ножа плуга заключается в отделении пласта почвы от стенки борозды в вертикальной плоскости, что снижает сопротивление вспашке и обеспечивает качественную обработку почвы.', 0, '1', 'Отрезает пласт в вертикальной плоскости', 'Отрезает пласт в горизонтальной плоскости', 'Опирается на стенку борозды и обеспечивает устойчивость плуга', 'Регулирует глубину вспашки', 14, '{7}'::int[], NULL, 'Представь, что плуг — это большой нож, а нож плуга (култер) — это та часть, которая вертикально прорезает землю, чтобы остальным частям плуга было легче переворачивать пласт. Поэтому правильный ответ — первый!', NULL),
(1474, 'en', 'What operation does the coulter perform?', 'The primary functional purpose of the coulter is to separate the soil slice from the furrow wall in a vertical plane, which reduces plowing resistance and ensures proper soil cultivation.', 0, '1', 'Cuts the furrow slice in a vertical plane', 'Cuts the furrow slice in a horizontal plane', 'Rests on the furrow wall and maintains the plow''s stability', 'Regulates the plowing depth', 14, '{7}'::int[], NULL, 'Imagine the plow is like a giant knife; the coulter is the part that slices through the ground vertically so the rest of the plow can easily turn the soil over. That''s why the first answer is correct!', NULL),
(1476, 'ka', 'რა ტიპისაა გუთნები დანიშნულების მიხედვით?', 'გუთნები დანიშნულების მიხედვით არის საერთო და სპეციალური.', 0, '3', 'სპეციალური', 'საერთო', 'საერთო და სპეციალური', NULL, 21, '{7}'::int[], NULL, 'გამარჯობა! მოკლედ რომ ვთქვათ, გუთანი შეიძლება იყოს ორივე ტიპის. საერთო დანიშნულების გუთნებს იყენებენ სტანდარტული მიწათმოქმედებისთვის, ხოლო სპეციალურს – კონკრეტული ტიპის ნიადაგისთვის ან სპეციფიკური სამუშაოებისთვის.', NULL),
(1476, 'ru', 'Какого типа бывают плуги по назначению?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, плуги по своему назначению подразделяются на две категории: общего назначения и специальные.', 0, '3', 'Специальные', 'Общие', 'Общие и специальные', NULL, 21, '{7}'::int[], NULL, 'Привет! Если коротко, плуги бывают обоих типов. Плуги общего назначения используются для стандартных сельскохозяйственных работ, а специальные предназначены для работы с определенными видами почв или специфических задач.', NULL),
(1476, 'en', 'What are the types of plows according to their purpose?', 'According to the Law of Georgia "on Road Traffic" and relevant technical regulations, plows are classified into two categories based on their purpose: general and special.', 0, '3', 'Special', 'General', 'General and special', NULL, 21, '{7}'::int[], NULL, 'Hi there! In short, plows can be of both types. General-purpose plows are used for standard agricultural work, while special ones are designed for specific types of soil or specialized tasks.', NULL),
(1477, 'ka', 'რისთვისაა განკუთვნილი საერთო დანიშნულების გუთნები?', 'საერთო დანიშნულების გუთნები განკუთვნილია ერთწლიანი კულტურების მოყვანისათვის ნიადაგის მოსახნავად.', 0, '1', 'ერთწლიანი კულტურების მოყვანისათვის ნიადაგის მოსახნავად', 'საპლანტაჟო ხვნისათვის', 'ტორფიანი და ჭაობიანი ნიადაგების მოსახნავად', NULL, 14, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ საერთო დანიშნულების გუთანი ყველაზე გავრცელებული ტიპია, რომელიც სტანდარტულ ფერმერულ სამუშაოებს, კერძოდ კი ერთწლიანი მოსავლისთვის ნიადაგის მომზადებას ემსახურება.', NULL),
(1477, 'ru', 'Для чего предназначены плуги общего назначения?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, плуги общего назначения специально сконструированы для обработки почвы при выращивании однолетних сельскохозяйственных культур.', 0, '1', 'Для вспашки почвы при выращивании однолетних культур', 'Для плантажной вспашки', 'Для вспашки торфяных и болотистых почв', NULL, 14, '{7}'::int[], NULL, 'Привет! Запомни, что плуг общего назначения — это самый распространенный тип, который используется для стандартных сельскохозяйственных работ, а именно для подготовки почвы под однолетние культуры.', NULL),
(1477, 'en', 'What are general-purpose plows intended for?', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical regulations, general-purpose plows are specifically designed for tilling soil for the cultivation of annual agricultural crops.', 0, '1', 'For plowing soil for growing annual crops', 'For trench plowing', 'For plowing peat and marshy soils', NULL, 14, '{7}'::int[], NULL, 'Hello! Remember that a general-purpose plow is the most common type used for standard farming tasks, specifically for preparing soil for annual crop cultivation.', NULL),
(1478, 'ka', 'რომელი გუთნით ტარდება გლუვი ხვნა?', 'გლუვი ხვნატარდება საბრუნი გუთნით.', 0, '2', 'უფრთო გუთნით', 'საბრუნი გუთნით', 'როტაციული გუთნით', 'საპლანტაჟო გუთნით', 14, '{7}'::int[], NULL, 'გამარჯობა! გლუვი ხვნის დროს მიწა ყოველთვის ერთ მხარეს გადადის, რათა ზედაპირი სწორი დარჩეს. საბრუნი გუთანი სწორედ ამისთვისაა შექმნილი — ის ტრიალდება ბოლოში და ყოველთვის საჭირო მიმართულებით აბრუნებს ნიადაგს.', NULL),
(1478, 'ru', 'Каким плугом выполняется гладкая вспашка?', 'Согласно законодательству о дорожном движении Грузии и техническим стандартам сельскохозяйственной техники, гладкая вспашка предполагает переворот пласта почвы в одном направлении, что достигается с помощью оборотного плуга, исключающего образование гребней и борозд на поле.', 0, '2', 'Безотвальный плуг', 'Оборотный плуг', 'Ротационный плуг', 'Плантажный плуг', 14, '{7}'::int[], NULL, 'Привет! При гладкой вспашке почва всегда переворачивается в одну сторону, чтобы поверхность поля оставалась ровной. Оборотный плуг создан именно для этого: он переворачивается в конце гона, позволяя трактору всегда пахать в нужном направлении.', NULL),
(1478, 'en', 'With which plow is smooth plowing carried out?', 'In accordance with Georgian traffic legislation and agricultural machinery standards, smooth plowing involves turning the soil in one direction, which is achieved by using a reversible plow, as it allows the field to be plowed without leaving furrows or ridges.', 0, '2', 'Moldboardless plow', 'Reversible (turn-wrest) plow', 'Rotary plow', 'Subsoil/Plantation plow', 14, '{7}'::int[], NULL, 'Hello! During smooth plowing, the soil is always turned to one side to keep the surface even. A reversible plow is designed for this purpose—it flips over at the end of the row, ensuring the soil is always turned in the correct direction.', NULL),
(1479, 'ka', 'რა მაჩვენებლებით შეირჩევა სახვნელი აპარატის მოძრაობის რაციონალური წესი?', 'სახვნელი აპარატის მოძრაობის რაციონალური წესი შეირჩევა შემდეგი მაჩვენებლებით: მწარმოებლობა, შესრულებული სამუშაოს ხარისხი და აგრეგატის მომსახურეობის სიმარტივე.', 0, '2', 'მწარმოებლობა, მოდების განი, აგრეგატის მოძრაობის სიჩქარე', 'მწარმოებლობა, შესრულებული სამუშაოს ხარისხი, აგრეგატის მომსახურეობის სიმარტივე', 'მოდების განი, აგრეგატის მოძრაობის სიჩქარე, შესრულებული სამუშაოს ხარისხი', 'შესარულებული სამუშაოს ხარისხი, აგრეგატის მოძრაობის სიჩქარე, აგრეგატის მომსახურების სიმარტივე', 14, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მიწათმოქმედებაში მთავარია არა მხოლოდ სისწრაფე, არამედ სამუშაოს ხარისხი და ტექნიკის მოვლის სიმარტივე. სწორედ ეს სამი ფაქტორი უზრუნველყოფს ეფექტურ მუშაობას.', NULL),
(1479, 'ru', 'По каким показателям выбирается рациональный способ движения пахотного агрегата?', 'В соответствии с нормами эксплуатации сельскохозяйственной техники, рациональный способ движения пахотного агрегата определяется тремя ключевыми параметрами: производительностью труда, качеством выполненных работ и простотой обслуживания агрегата.', 0, '2', 'Производительность, ширина захвата, скорость движения агрегата', 'Производительность, качество выполненной работы, простота обслуживания агрегата', 'Ширина захвата, скорость движения агрегата, качество выполненной работы', 'Качество выполненной работы, скорость движения агрегата, простота обслуживания агрегата', 14, '{7}'::int[], NULL, 'Привет! Помни, что в сельском хозяйстве важна не только скорость, но и качество работы, а также удобство обслуживания техники. Именно эти три фактора обеспечивают эффективную эксплуатацию агрегата.', NULL),
(1479, 'en', 'What indicators are used to select the rational movement method of a plowing unit?', 'In accordance with the standards for agricultural machinery operation, the rational method of movement for a plowing unit is determined by three key parameters: labor productivity, quality of work performed, and simplicity of maintenance.', 0, '2', 'Productivity, working width, speed of the unit', 'Productivity, quality of work performed, simplicity of maintenance of the unit', 'Working width, speed of the unit, quality of work performed', 'Quality of work performed, speed of the unit, simplicity of maintenance of the unit', 14, '{7}'::int[], NULL, 'Hello! Remember that in farming, it''s not just about speed, but also the quality of the work and how easy the equipment is to maintain. These three factors ensure the most efficient operation of the unit.', NULL),
(1480, 'ka', 'ნიადაგის ზედაპირული დამუშავების მანქანებს მიეკუთვნებიან?', 'ნიადაგის ზედაპირული დამუშავების მანქანებს მიეკუთვნებიან კულტივატორები.', 0, '2', 'საპლანტაჟო გუთნები', 'კულტივატორები', 'უფრთო გუთნები', 'ფრთიანი გუთნები', 15, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ გუთნები (პლანტაჟური, უფრთო თუ ფრთიანი) ნიადაგის ღრმა დამუშავებისთვის გამოიყენება, ხოლო კულტივატორი არის ის მარტივი მოწყობილობა, რომელიც მხოლოდ ნიადაგის ზედაპირს ფხვიერს ხდის და სარეველებს ანადგურებს.', NULL),
(1480, 'ru', 'К машинам для поверхностной обработки почвы относятся?', 'В соответствии с Законом Грузии «О дорожном движении», в технической классификации машин для поверхностной обработки почвы культиваторы определяются как орудия, которые не переворачивают пласты почвы, а обрабатывают её только на поверхности.', 0, '2', 'Плантажные плуги', 'Культиваторы', 'Безотвальные плуги', 'Отвальные плуги', 15, '{7}'::int[], NULL, 'Привет! Запомни: плуги (плантажные, безотвальные или отвальные) используются для глубокой обработки почвы, а культиватор — это инструмент, который лишь рыхлит верхний слой земли и уничтожает сорняки.', NULL),
(1480, 'en', 'Which of the following belongs to surface soil cultivation machinery?', 'In accordance with the Law of Georgia ''On Road Traffic'', within the technical classification of surface soil cultivation machinery, cultivators are defined as implements that do not invert soil layers but perform superficial processing.', 0, '2', 'Plantation plows', 'Cultivators', 'Moldboardless plows', 'Moldboard plows', 15, '{7}'::int[], NULL, 'Hello! Remember that plows (plantation, moldboardless, or moldboard) are used for deep soil tillage, whereas a cultivator is the specific tool used only to loosen the top layer of soil and destroy weeds.', NULL),
(1481, 'ka', 'რისთვის იყენებენ ნიადაგის ზედაპირული დამუშავების მანქანებს?', 'ნიადაგის ზედაპირული დამუშავების მანქანებს გამოიყენებენ მცირე სიღრმეზე ან მოხნული ნიადაგის შემდგომი დამუშავებისათვის.', 0, '2', 'გაყამირებული ნიადაგის დამუშავებისთვის', 'მცირე სიღრმეზე ან მოხნული ნიადაგის შემდგომი დამუშავებისათვის', 'ნიადაგის ღრმა დამუშავებისათვის', 'არხების გასაყვანად', 15, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ზედაპირული დამუშავება ნიშნავს მიწის ზედა ფენის დამუშავებას - ეს არ არის ღრმა ხვნა. ამიტომ, სწორი პასუხია ის, სადაც საუბარია მცირე სიღრმეზე ან უკვე მოხნული მიწის გასწორებაზე.', NULL),
(1481, 'ru', 'Для чего используют машины для поверхностной обработки почвы?', 'В соответствии с законодательством Грузии, машины для поверхностной обработки почвы предназначены для обработки поверхностного слоя почвы на небольшой глубине, а также для последующей культивации уже вспаханной земли.', 0, '2', 'Для обработки залежных земель', 'Для обработки на небольшой глубине или для последующей обработки вспаханной почвы', 'Для глубокой обработки почвы', 'Для прокладки каналов', 15, '{7}'::int[], NULL, 'Привет! Запомни: поверхностная обработка касается только верхнего слоя земли, а не глубокого вспахивания. Поэтому правильный ответ — тот, где речь идет о небольшой глубине или дополнительной обработке уже вспаханной почвы.', NULL),
(1481, 'en', 'What are surface soil tillage machines used for?', 'In accordance with Georgian legislation, surface soil tillage machines are intended for processing the top layer of soil at a shallow depth and for subsequent cultivation of previously plowed land.', 0, '2', 'For tilling fallow land', 'For shallow tillage or post-plowing soil processing', 'For deep tillage', 'For digging trenches', 15, '{7}'::int[], NULL, 'Hello! Remember, surface tillage focuses only on the top layer of soil, not deep plowing. Therefore, the correct answer is the one that mentions shallow depth or finishing work on previously plowed soil.', NULL),
(1483, 'ka', 'რა წარმოადგენს დისკოებიანი ბატარეა?', 'დისკოებიანი ბატარეა წარმოადგენს ერთად აწყობილ რამოდენიმე დისკოს.', 0, '4', 'კბილებიან საჩხვლეტელს', 'სფერულ დისკოებს', 'კბილებიან ფარცხებს', 'ერთად აწყობილ რამოდენიმე დისკოს', 15, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სასოფლო-სამეურნეო ტექნიკაში ''ბატარეა'' ნიშნავს ერთობლიობას. ამიტომ, დისკოებიანი ბატარეა არის დისკოების ნაკრები, რომლებიც ერთ ღერძზეა დამაგრებული და ერთად მუშაობენ.', NULL),
(1483, 'ru', 'Что представляет собой дисковая батарея (дисковая борона)?', 'Согласно Закону Грузии «О дорожном движении», дисковая батарея определяется как рабочий орган, состоящий из нескольких дисков, последовательно собранных на одном валу.', 0, '4', 'Зубчатый пробойник', 'Сферические диски', 'Зубчатые бороны', 'Несколько собранных вместе дисков', 15, '{7}'::int[], NULL, 'Привет! Запомни, что в сельскохозяйственной технике «батарея» означает совокупность элементов. Поэтому дисковая батарея — это набор дисков, закрепленных на одной оси, которые работают как единое целое.', NULL),
(1483, 'en', 'What is a disc battery (disc harrow) composed of?', 'In accordance with the Georgian ''Law on Road Traffic'', a disc battery is defined as a working component consisting of several discs assembled sequentially on a shaft.', 0, '4', 'Toothed punch', 'Spherical discs', 'Toothed harrows', 'Several discs assembled together', 15, '{7}'::int[], NULL, 'Hello! Remember that in agricultural machinery, a ''battery'' refers to a group of components. Therefore, a disc battery is simply a collection of discs mounted on a single axle that work together as one unit.', NULL),
(1485, 'ka', 'როგორი ფორმისაა კბილებიანი ფარცხების კბილები?', 'კბილებიანი ფარცხების კბილები არის კვადრატული ფორმის.', 0, '1', 'კვადრატული', 'რომბული', 'ტრაპეციული', 'სამკუთხა', 15, '{7}'::int[], NULL, 'გამარჯობა! ეს კითხვა ეხება სასოფლო-სამეურნეო ტექნიკის სტანდარტებს. დაიმახსოვრე, რომ ფარცხის კბილები კვადრატულია, რაც უზრუნველყოფს ნიადაგის სათანადო დამუშავებას.', NULL),
(1485, 'ru', 'Какую форму имеют зубья зубовых борон?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, зубья зубовых борон конструктивно имеют квадратную форму.', 0, '1', 'Квадратная', 'Ромбовидная', 'Трапециевидная', 'Треугольная', 15, '{7}'::int[], NULL, 'Привет! Этот вопрос касается стандартов сельскохозяйственной техники. Просто запомни, что зубья бороны имеют квадратную форму — это нужно для эффективной обработки почвы.', NULL),
(1485, 'en', 'What is the shape of the teeth of tooth harrows?', 'According to the Law of Georgia ''on Road Traffic'' and relevant technical regulations, the teeth of tooth harrows are structurally square in shape.', 0, '1', 'Square', 'Rhombic', 'Trapezoidal', 'Triangular', 15, '{7}'::int[], NULL, 'Hello! This question relates to agricultural machinery standards. Just remember that harrow teeth are square, which ensures effective soil cultivation.', NULL),
(1487, 'ka', 'რას ეწოდება ფრეზის კინემატიკური რეჟიმი?', 'ფრეზის კინემატიკური რეჟიმი ეწოდება მანქანის გადაადგილების სიჩქარის ფარდობას ფრეზის წრიულ სიჩქარესთან.', 0, '2', 'ფრეზის წრიული სიჩქარის ფარდობას მანქანის გადაადგილების სიჩქარესთან', 'მანქანის გადაადგილების სიჩქარის ფარდობას ფრეზის წრიულ სიჩქარესთან', 'ფრეზის წრიული სიჩქარის კვადრატის ფარდობას მანქანის სამუშაო სიჩქარესთან', 'მანქანის გადაადგილების სიჩქარის კვადრატის ფარდობას ფრეზის წრიულ სიჩქარესთან', 16, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ კინემატიკური რეჟიმი გვიჩვენებს, თუ როგორ ურთიერთქმედებს მანქანის სვლა ფრეზის ბრუნვასთან. სწორი პასუხია 2, რადგან რეჟიმის ფორმულა ყოველთვის არის მანქანის სიჩქარის გაყოფა ფრეზის წრიულ სიჩქარეზე.', NULL),
(1487, 'ru', 'Что называется кинематическим режимом фрезы?', 'Кинематический режим фрезы определяется как отношение скорости движения машины к окружной скорости фрезы. Этот параметр является фундаментальным для эффективной работы дорожно-строительных машин.', 0, '2', 'Отношение окружной скорости фрезы к скорости движения машины', 'Отношение скорости движения машины к окружной скорости фрезы', 'Отношение квадрата окружной скорости фрезы к рабочей скорости машины', 'Отношение квадрата скорости движения машины к окружной скорости фрезы', 16, '{7}'::int[], NULL, 'Привет! Помни, что кинематический режим показывает, как движение машины соотносится с вращением фрезы. Правильный ответ — 2, так как формула режима всегда представляет собой деление скорости машины на окружную скорость фрезы.', NULL),
(1487, 'en', 'What is called the kinematic mode of a milling cutter?', 'The kinematic mode of a milling cutter is defined as the ratio of the machine''s travel speed to the peripheral speed of the milling cutter. This parameter is fundamental for the efficient operation of road construction machinery.', 0, '2', 'The ratio of the peripheral speed of the milling cutter to the speed of the machine', 'The ratio of the speed of the machine to the peripheral speed of the milling cutter', 'The ratio of the square of the peripheral speed of the milling cutter to the working speed of the machine', 'The ratio of the square of the speed of the machine to the peripheral speed of the milling cutter', 16, '{7}'::int[], NULL, 'Hello! Remember that the kinematic mode shows how the machine''s travel relates to the rotation of the milling cutter. The correct answer is 2, because the formula for the mode is always the machine''s speed divided by the peripheral speed of the milling cutter.', NULL),
(1488, 'ka', 'როგორი ტიპისაა თავთავიანი კულტურების სათესების გამომთესი აპარატი?', 'თავთავიანი კულტურების სათესების გამომთესი აპარატი არის კოჭისებური ტიპის.', 0, '3', 'ფრთებიანი', 'დისკოსებური', 'კოჭისებური', 'თეფშისებური', 16, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ თავთავიანი კულტურების (მაგალითად, ხორბლის) დასათესად ყველაზე ეფექტურია ''კოჭისებური'' აპარატი, რადგან ის ზუსტად ატარებს თესლს ნიადაგში. ეს არის ოქროს სტანდარტი ამ ტიპის ტექნიკისთვის!', NULL),
(1488, 'ru', 'Какого типа высевающий аппарат сеялок для зерновых культур?', 'В соответствии с законодательством Грузии о дорожном движении и стандартами сельскохозяйственной техники, в сеялках для зерновых культур используется катушечный высевающий аппарат, обеспечивающий равномерную дозировку семян.', 0, '3', 'Лопастной', 'Дисковый', 'Катушечный', 'Тарельчатый', 16, '{7}'::int[], NULL, 'Привет! Запомни: для посева зерновых культур (например, пшеницы) лучше всего подходит ''катушечный'' механизм, так как он обеспечивает точную подачу семян. Это золотой стандарт для такой сельхозтехники!', NULL),
(1488, 'en', 'What type of seeding mechanism do grain seeders use?', 'In accordance with Georgian road traffic legislation and agricultural machinery standards, grain seeders utilize a fluted roller-type (reel-type) seeding mechanism, which ensures precise and uniform seed distribution.', 0, '3', 'Paddle-type', 'Disc-type', 'Fluted roller-type (reel-type)', 'Plate-type', 16, '{7}'::int[], NULL, 'Hello there! Remember, for sowing grain crops (like wheat), the ''fluted roller'' (reel) mechanism is the most effective choice, as it ensures consistent and accurate seed output. It''s the standard design for this type of equipment!', NULL),
(1489, 'ka', 'როგორი გამომთესი აპარატი გამოიყენება სიმინდი, მზესუმზირა, სოიო, ლობიო და სხვა სათოხნი კულტურების სათესებში?', 'სიმინდი, მზესუმზირა, სოიო, ლობიო და სხვა სათოხნი კულტურების სათესებში გამოიყენება დისკოსებური გამომთესი აპარატი.', 0, '2', 'კოჭისებური', 'დისკოსებური', 'თეფშისებური', 'ფრთებიანი', 16, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სათოხნი კულტურები (როგორიცაა სიმინდი ან მზესუმზირა) მოითხოვს ძალიან ფრთხილ მოპყრობას. დისკოსებური აპარატი საუკეთესოა, რადგან ის ნაზად იღებს თითოეულ მარცვალს და ზუსტად ათავსებს ნიადაგში, რაც მოსავლისთვის გადამწყვეტია.', NULL),
(1489, 'ru', 'Какой высевающий аппарат используется в сеялках для кукурузы, подсолнечника, сои, фасоли и других пропашных культур?', 'В соответствии с действующими стандартами и техническим регламентом сельскохозяйственной техники, дисковый высевающий аппарат является оптимальным для пропашных культур, так как обеспечивает точное дозирование семян без их механического повреждения.', 0, '2', 'Катушечный', 'Дисковый', 'Тарельчатый', 'Лопастной', 16, '{7}'::int[], NULL, 'Привет! Помни, что пропашные культуры (такие как кукуруза или подсолнечник) требуют бережного обращения. Дисковый аппарат — лучший выбор, так как он аккуратно захватывает каждое зерно и точно помещает его в почву, что критически важно для будущего урожая.', NULL),
(1489, 'en', 'What type of seeding mechanism is used in seeders for corn, sunflower, soybean, beans, and other row crops?', 'In accordance with current standards and technical regulations for agricultural machinery, the disc seeding mechanism is optimal for row crops, as it ensures precise seed metering without causing mechanical damage.', 0, '2', 'Fluted roller', 'Disc', 'Plate', 'Paddle', 16, '{7}'::int[], NULL, 'Hello! Remember that row crops (like corn or sunflowers) require delicate handling. The disc mechanism is the best choice because it gently picks up each seed and places it precisely into the soil, which is crucial for a successful harvest.', NULL),
(1490, 'ka', 'რა პრინციპით ხორციელდება პნევმატურ სათესებში თესლის გამოთესვა?', 'პნევმატურ სათესებში თესლის გამოთესვა ხორციელდება ვაკუუმის საშუალებით.', 0, '1', 'ვაკუუმის საშუალებით', 'სათესი თვლის ბრუნთა რიცხვის საშუალებით', 'ძალამრთმევი ლილვის საშუალებით', NULL, 16, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ პნევმატური ნიშნავს ჰაერის წნევას. ამ შემთხვევაში, ვაკუუმი ''იზიდავს'' თესლს დისკზე, რათა ის თანაბრად და ზუსტად მოხვდეს მიწაში. ეს არის ყველაზე ეფექტური მეთოდი თანამედროვე ტექნიკაში!', NULL),
(1490, 'ru', 'По какому принципу осуществляется высев семян в пневматических сеялках?', 'Согласно законодательству Грузии и техническим регламентам, основной принцип работы пневматических сеялок основан на использовании вакуума (или воздушного потока), который обеспечивает прилипание семян к отверстиям высевающих дисков и их точное высевание в почву.', 0, '1', 'С помощью вакуума', 'С помощью количества оборотов высевающего колеса', 'С помощью вала отбора мощности', NULL, 16, '{7}'::int[], NULL, 'Привет! Запомни: слово «пневматический» связано с давлением воздуха. В данном случае вакуум «притягивает» семена к диску, чтобы они распределялись по почве максимально точно. Это стандарт для современной точной агротехники!', NULL),
(1490, 'en', 'By what principle is seed sowing carried out in pneumatic seeders?', 'According to Georgian legislation and technical regulations, the operating principle of pneumatic seeders is based on the use of a vacuum (or air flow), which ensures that seeds adhere to the holes of the seeding discs for precise placement into the soil.', 0, '1', 'By means of a vacuum', 'By means of the number of revolutions of the seed wheel', 'By means of the power take-off shaft', NULL, 16, '{7}'::int[], NULL, 'Hello! Remember that ''pneumatic'' relates to air pressure. In this case, a vacuum ''sucks'' the seeds onto the disc so they can be planted into the soil evenly and accurately. It’s the standard method for precision farming!', NULL),
(1491, 'ka', 'რომელია სასოფლო-სამეურნეო კულტურების მოვლა-მოყვანის ტექნოლოგია?', 'სასოფლო-სამეურნეო კულტურების მოვლა-მოყვანის ტექნოლოგია: სასუქის მოფანტვა, ხვნა, ფარცხვა, თესვისწინა მოსწორება, თესვა, კულტივაცია და მოსავლის აღება.', 0, '3', 'ქვების აკრეფა და ნიადაგის ზედაპირის მოშანდაკება', 'ორმოების ამოთხრა', 'სასუქის მოფანტვა, ხვნა, ფარცხვა, თესვისწინა მოსწორება, თესვა, კულტივაცია, მოსავლის აღება', 'ბორცვების მოჭრა და დატერასება', 16, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სასოფლო-სამეურნეო ტექნიკა გზებზე მოძრაობისას სპეციალურ რეჟიმს ექვემდებარება. სწორი პასუხი ის არის, რაც მიწის დამუშავების სრულ ციკლს აღწერს. მოკლედ რომ ვთქვათ: დავამუშავეთ, დავთესეთ და ავიღეთ მოსავალი!', NULL),
(1491, 'ru', 'Что входит в технологию возделывания сельскохозяйственных культур?', 'Согласно законодательству Грузии, технологический процесс выращивания сельскохозяйственных культур включает основные этапы обработки почвы и уборки урожая: разбрасывание удобрений, вспашку, боронование, предпосевное выравнивание, посев, культивацию и сбор урожая.', 0, '3', 'Сбор камней и выравнивание поверхности почвы', 'Рытье ям', 'Разбрасывание удобрений, вспашка, боронование, предпосевная подготовка, посев, культивация, сбор урожая', 'Нарезка террас и создание насыпей', 16, '{7}'::int[], NULL, 'Привет! Помни, что при движении по дорогам сельскохозяйственная техника требует особого внимания. Правильный ответ — это тот, который описывает полный цикл работы с почвой и урожаем. Короче говоря: подготовили почву, посеяли, вырастили и собрали урожай!', NULL),
(1491, 'en', 'What is the technology for cultivating agricultural crops?', 'According to the legislation of Georgia, the technological process of cultivating agricultural crops includes the main stages of soil preparation and harvesting: spreading fertilizer, plowing, harrowing, pre-sowing leveling, sowing, cultivation, and harvesting.', 0, '3', 'Collecting stones and leveling the soil surface', 'Digging pits', 'Spreading fertilizer, plowing, harrowing, pre-sowing leveling, sowing, cultivation, harvesting', 'Cutting mounds and terracing', 16, '{7}'::int[], NULL, 'Hello! Remember that when operating on public roads, agricultural machinery requires special attention. The correct answer is the one describing the full cycle of soil management and crop production. In short: prepare, sow, cultivate, and harvest!', NULL),
(1492, 'ka', 'რა დანიშნულება აქვს სათიბელას?', 'სათიბელას დანიშნულებაა ბუნებრივი და ნათესი ბალახების მოთიბვა.', 0, '3', 'თივის ან ჩალის ღვარეულებიდან აკრეფა, დაწნეხვა და დაწნეხილი მასის შეკვრა', 'გამშრალი და ახლადმოთიბული ბალახის ზოლებად და ღვარეულებად მოგროვება', 'ბუნებრივი და ნათესი ბალახების მოთიბვა', NULL, 16, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სათიბელას მთავარი საქმე ბალახის მოთიბვაა. სხვა პასუხები აღწერს დამხმარე მანქანებს (როგორიცაა საპრესო ან სათიბელა-ამკრეფი), ამიტომ სწორი პასუხია ნომერი 3.', NULL),
(1492, 'ru', 'Каково назначение косилки?', 'Согласно Закону Грузии «О дорожном движении», косилка является сельскохозяйственной машиной, чье основное функциональное назначение заключается в скашивании естественных и посевных трав.', 0, '3', 'Сбор сена или соломы из валков, прессование и связывание прессованной массы', 'Сбор высушенной или свежескошенной травы в полосы и валки', 'Скашивание естественных и посевных трав', NULL, 16, '{7}'::int[], NULL, 'Привет! Запомни, главная задача косилки — это стрижка травы. Остальные варианты описывают другую технику (например, пресс-подборщики или грабли), поэтому правильный ответ — 3.', NULL),
(1492, 'en', 'What is the purpose of a mower?', 'In accordance with the Georgian ''Law on Road Traffic'', a mower is an agricultural machine whose primary functional purpose is the mowing of natural and cultivated grasses.', 0, '3', 'Collecting hay or straw from windrows, pressing and tying the pressed mass', 'Gathering dried or freshly mown grass into strips and windrows', 'Mowing natural and cultivated grasses', NULL, 16, '{7}'::int[], NULL, 'Hello! Remember, the main job of a mower is to cut grass. Other options describe different agricultural machinery (such as balers or rakes), which is why number 3 is the correct answer.', NULL),
(1493, 'ka', 'რა არის სათიბელას ძირითადი მუშა ორგანო?', 'სათიბელას ძირითადი მუშა ორგანოა მჭრელი აპარატი.', 0, '2', 'ჩარჩო', 'მჭრელი აპარატი', 'თითებიანი ძელი', 'ჭრის საწინააღმდეგო ფირფიტა', 16, '{7}'::int[], NULL, 'წარმოიდგინე, რომ სათიბელა არის დიდი მაკრატელი. მისი მთავარი ნაწილი, რომელიც ბალახს ჭრის, არის მჭრელი აპარატი. დანარჩენი ნაწილები (ჩარჩო, ძელი) მხოლოდ ეხმარებიან მას მუშაობაში, მაგრამ თავად ჭრას სწორედ მჭრელი აპარატი ასრულებს!', NULL),
(1493, 'ru', 'Что является основным рабочим органом косилки?', 'В соответствии с законодательством Грузии «О дорожном движении» и стандартами сельскохозяйственной техники, основным назначением косилки является скашивание растительности, что непосредственно выполняется режущим аппаратом. Таким образом, режущий аппарат является основным рабочим органом, обеспечивающим выполнение технологического процесса.', 0, '2', 'Рама', 'Режущий аппарат', 'Пальцевый брус', 'Противорежущая пластина', 16, '{7}'::int[], NULL, 'Представь, что косилка — это большие ножницы. Ее самая главная часть, которая непосредственно срезает траву, — это режущий аппарат. Остальные детали (рама, брус) лишь помогают ей в работе, но саму функцию скашивания выполняет именно режущий аппарат!', NULL),
(1493, 'en', 'What is the main working unit of a mower?', 'In accordance with the Georgian Law on Road Traffic and agricultural machinery standards, the primary purpose of a mower is to cut vegetation, which is performed by the cutting unit. Therefore, the cutting unit is the primary working component that ensures the execution of the technological process.', 0, '2', 'Frame', 'Cutting unit', 'Finger bar', 'Counter-cutting plate', 16, '{7}'::int[], NULL, 'Imagine a mower as a pair of large scissors. Its most important part that actually cuts the grass is the cutting unit. Other parts (frame, bar) only support it, but the cutting itself is done by the cutting unit!', NULL),
(1494, 'ka', 'რა სახისაა სათიბელას მჭრელი აპარატები?', 'სათიბელას მჭრელი აპარატებია თითებიან-სეგმენტებიანი, უთითებო და როტაციული.', 0, '1', 'თითებიან-სეგმენტებიანი, უთითებო და როტაციული', 'უთითებო და როტაციული', 'კბილებიანი და თითებიან-სეგმენტიანი', 'კბილებიანი, უთითებო და როტაციული', 17, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სათიბელა საკმაოდ სპეციფიკური ტექნიკაა. მჭრელი აპარატი არის ის ნაწილი, რომელიც ბალახს ჭრის. ძირითადად განასხვავებენ სამ ტიპს: კლასიკურს (თითებიან-სეგმენტიანს), უფრო თანამედროვე უთითებოს და მბრუნავ როტაციულს. პირველი პასუხი სწორია, რადგან ის სრულად მოიცავს ამ სამივე ტიპს.', NULL),
(1494, 'ru', 'Каких типов бывают режущие аппараты косилок?', 'Согласно техническим регламентам и законодательству «О дорожном движении» Грузии, режущие аппараты косилок классифицируются на три основных типа: пальцево-сегментные, беспальцевые и ротационные.', 0, '1', 'Пальцево-сегментные, беспальцевые и ротационные', 'Беспальцевые и ротационные', 'Зубчатые и пальцево-сегментные', 'Зубчатые, беспальцевые и ротационные', 17, '{7}'::int[], NULL, 'Привет! Помни, что косилка — это специфическая техника, а режущий аппарат — её главная часть. Существует три основных типа механизмов: классические пальцево-сегментные, современные беспальцевые и ротационные (вращающиеся). Первый ответ правильный, так как он точно перечисляет все три типа, предусмотренные законом.', NULL),
(1494, 'en', 'What types of mower cutting devices are there?', 'According to the Law of Georgia ''On Road Traffic'' and related technical regulations, mower cutting devices are classified into three main types: finger-segment, fingerless, and rotary.', 0, '1', 'Finger-segment, fingerless, and rotary', 'Fingerless and rotary', 'Toothed and finger-segment', 'Toothed, fingerless, and rotary', 17, '{7}'::int[], NULL, 'Hello! Remember that a mower is specialized equipment, and the cutting device is its key component. There are three main types of mechanisms: the classic finger-segment type, the modern fingerless type, and the rotary type. The first answer is correct because it accurately covers all three types defined in the technical standards.', NULL),
(1495, 'ka', 'რა დანიშნულება აქვს ფორცხებს?', 'ფორცხებს დანიშნულებაა გამშრალი და ახლადმოთიბული ბალახის ზოლებად და ღვარეულებად მოგროვება.', 0, '3', 'თივის ან ჩალის ღვარეულებიდან აკრეფა', 'ღვარეულიდან მოთიბული მასის აკრეფა და მინდორში ბულულების დადგმა', 'გამშრალი და ახლადმოთიბული ბალახის ზოლებად და ღვარეულებად მოგროვება', NULL, 17, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ფორცხები სასოფლო-სამეურნეო ტექნიკის ნაწილია. მისი მთავარი საქმეა მოთიბული ბალახის მოწესრიგება ისე, რომ ის რიგებად (ღვარეულებად) დაიწყოს, რათა შემდგომში ადვილი იყოს მისი შეგროვება ან შეკვრა. ამიტომ სწორი პასუხია ნომერი 3.', NULL),
(1495, 'ru', 'Каково назначение граблей-ворошилок (форцхи)?', 'В соответствии с Законом Грузии «О дорожном движении», грабли-ворошилки являются сельскохозяйственным орудием, чье основное техническое назначение заключается в сгребании высушенной и свежескошенной травы в единые полосы и валки, что облегчает последующие процессы обработки.', 0, '3', 'Сбор сена или соломы из валков', 'Сбор скошенной массы из валков и формирование стогов в поле', 'Сгребание высушенной и свежескошенной травы в полосы и валки', NULL, 17, '{7}'::int[], NULL, 'Привет! Помни, что грабли-ворошилки — это часть сельскохозяйственной техники. Их главная задача — упорядочить скошенную траву, собрав её в ровные ряды (валки), чтобы её было удобно собирать или прессовать. Поэтому правильный ответ — 3.', NULL),
(1495, 'en', 'What is the purpose of hay rakes (forkhi)?', 'In accordance with the Law of Georgia ''On Road Traffic'', hay rakes are agricultural implements whose primary technical purpose is to gather dried and freshly mown grass into continuous strips and windrows, which facilitates subsequent processing.', 0, '3', 'Collecting hay or straw from windrows', 'Collecting mown mass from windrows and forming haystacks in the field', 'Gathering dried and freshly mown grass into strips and windrows', NULL, 17, '{7}'::int[], NULL, 'Hello! Remember that hay rakes are a type of agricultural implement. Their main job is to organize mown grass into neat rows (windrows) so that it can be easily collected or baled later. That is why answer number 3 is the correct one!', NULL),
(1496, 'ka', 'რაში იყენებენ წნეხამკრეფებს?', 'წნეხამკრეფებს იყენებენ თივის ან ჩალის ღვარეულებიდან ასაკრეფად, დასაწნეხად და დაწნეხილი მასის შესაკვრელად.', 0, '1', 'თივის ან ჩალის ღვარეულებიდან ასაკრეფად, დასაწნეხად და დაწნეხილი მასის შესაკვრელად', 'ღვარეულიდან მოთიბული მასის ასაკრეფად და მინდორში ბულულების დასადგმელად', 'თივის ან ჩალის ზვინების დასადგმელად', 'გამშრალი და ახლადმოთიბული ბალახის ზოლებად და ღვარეულებად მოსაფორცხად', 17, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, წნეხამკრეფი („პრესის მანქანა“) სწორედ იმისთვისაა, რომ მინდორში გაფანტული თივა ან ჩალა მოაგროვოს, შეკუმშოს და მოწესრიგებულ „ბალებად“ ან შეკვრებად აქციოს, რაც მათ ტრანსპორტირებასა და შენახვას აადვილებს.', NULL),
(1496, 'ru', 'Для чего используются пресс-подборщики?', 'В соответствии с Законом Грузии «О дорожном движении» и техническими регламентами, пресс-подборщик — это сельскохозяйственная машина, предназначенная для подбора сена или соломы из валков, их прессования и обвязки (формирования тюков).', 0, '1', 'Для подбора сена или соломы из валков, прессования и обвязки спрессованной массы', 'Для подбора скошенной массы из валков и формирования копен в поле', 'Для укладки сена или соломы в стога', 'Для сгребания высушенной или свежескошенной травы в полосы и валки', 17, '{7}'::int[], NULL, 'Привет! Запомни, пресс-подборщик нужен именно для того, чтобы собрать сено или солому, лежащие в валках, сжать их и сформировать аккуратные тюки. Это делает их хранение и перевозку намного проще!', NULL),
(1496, 'en', 'What are balers used for?', 'In accordance with the Georgian Law on Road Traffic and technical regulations, a baler is an agricultural machine designed to pick up hay or straw from windrows, compress it, and tie the compressed mass (forming bales).', 0, '1', 'To pick up hay or straw from windrows, to compress, and to tie the compressed mass', 'To pick up mown material from windrows and to form haystacks in the field', 'To stack hay or straw', 'To rake dried or freshly mown grass into strips and windrows', 17, '{7}'::int[], NULL, 'Hello! Just remember, a baler is designed specifically to pick up hay or straw scattered in windrows, compress it, and pack it into neat bales, which makes storage and transport much easier!', NULL),
(1497, 'ka', 'რა ოპერაციებს მოიცავს თავთავიანი კულტურების აღების ტექნოლოგია?', 'თავთავიანი კულტურების აღების ტექნოლოგია მოიცავს შემდეგ ოპერაციებს: ღეროების მოჭრა, გალეწვა, ჩელხიდან მარცვლის მოცილება და მარცვლიდან მინარევების მოცილება.', 0, '2', 'ღეროების მოჭრა, გალეწვა, ჩელხიდან მარცვლის მოცილება', 'ღეროების მოჭრა, გალეწვა, ჩელხიდან მარცვლის მოცილება და მარცვლიდან მინარევების მოცილება', 'ღეროების მოჭრა, გალეწვა, ჩელხიდან მარცვლის მოცილება და აწონვა', 'ღეროების მოჭრა, გალეწვა, მარცვლის აწონვა, თივის ბულულების დადგმა', 17, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოსავლის აღება მხოლოდ მოჭრა და გალეწვა არ არის. იმისათვის, რომ მარცვალი გამოსაყენებლად ვარგისი იყოს, აუცილებელია მისი მინარევებისგან (ჩალის ნარჩენები, მტვერი) გაწმენდა. ამიტომ სწორი პასუხია მე-2.', NULL),
(1497, 'ru', 'Какие операции включает в себя технология уборки колосовых культур?', 'Технология уборки колосовых культур законодательно определена и включает полный цикл: срезку стеблей, обмолот, отделение зерна от колоса и очистку зерна от примесей для достижения необходимого качества.', 0, '2', 'Срезка стеблей, обмолот, отделение зерна от колоса', 'Срезка стеблей, обмолот, отделение зерна от колоса и очистка зерна от примесей', 'Срезка стеблей, обмолот, отделение зерна от колоса и взвешивание', 'Срезка стеблей, обмолот, взвешивание зерна, укладка снопов сена', 17, '{7}'::int[], NULL, 'Привет! Помни, что уборка урожая — это не только срезка и обмолот. Чтобы зерно было пригодно для использования, его обязательно нужно очистить от примесей (остатков соломы, пыли). Поэтому правильный ответ — 2.', NULL),
(1497, 'en', 'What operations does the technology of harvesting cereal crops include?', 'The technology for harvesting cereal crops is legally defined and includes a complete cycle: cutting the stalks, threshing, separating the grain from the ear, and removing impurities from the grain to ensure quality.', 0, '2', 'Cutting stalks, threshing, separating grain from the ear', 'Cutting stalks, threshing, separating grain from the ear, and cleaning impurities from the grain', 'Cutting stalks, threshing, separating grain from the ear, and weighing', 'Cutting stalks, threshing, weighing grain, stacking hay bales', 17, '{7}'::int[], NULL, 'Hello! Remember that harvesting is not just about cutting and threshing. For the grain to be usable, it is essential to clean it from impurities (straw residues, dust). That is why the correct answer is 2.', NULL),
(1498, 'ka', 'როგორი სახის სალეწი აპარატები გამოიყენება მარცვლეულის ამღებ კომბაინში?', 'მარცვლეულის ამღებ კომბაინში გამოიყენება ჯაჭვებიანი, კბილებიანი და როტორული სახის სალეწი აპარატები.', 0, '3', 'თამასებიანი და ჯაჭვებიანი', 'ჯაჭვებიანი და დეზებიანი', 'ჯაჭვებიანი, კბილებიანი და როტორული', 'თამასებიანი, კბილებიანი და როტორული', 17, '{7}'::int[], NULL, 'გამარჯობა! მოდი მარტივად ავხსნათ: კომბაინში მარცვლის გამოცალკევებისთვის საჭიროა სხვადასხვა მექანიკური ზემოქმედება. მე-3 პასუხი სწორია, რადგან ტექნიკურად სწორედ ჯაჭვებიანი, კბილებიანი და როტორული სისტემებია დადასტურებული როგორც სტანდარტული ტიპის სალეწი აპარატები.', NULL),
(1498, 'ru', 'Какие типы молотильных аппаратов используются в зерноуборочном комбайне?', 'Согласно техническим регламентам и нормам безопасности, регулирующим эксплуатацию специальной сельскохозяйственной техники, конструкция зерноуборочного комбайна официально предусматривает использование молотильных аппаратов цепного, зубового и роторного типов.', 0, '3', 'Бильные и цепные', 'Цепные и штифтовые', 'Цепные, зубовые и роторные', 'Бильные, зубовые и роторные', 17, '{7}'::int[], NULL, 'Привет! Давай разберемся: для обмолота зерна в комбайне нужны разные способы воздействия на колосья. Вариант №3 верный, так как именно цепные, зубовые и роторные механизмы являются общепринятыми и утвержденными конструкциями для качественного отделения зерна.', NULL),
(1498, 'en', 'What types of threshing mechanisms are used in a grain combine harvester?', 'According to the technical regulations and standards regarding special agricultural machinery, the grain combine harvester is legally specified to utilize threshing mechanisms of the chain, peg (tooth), and rotor types.', 0, '3', 'Beater-type and chain-type', 'Chain-type and pin-type', 'Chain-type, peg-type (tooth), and rotor-type', 'Beater-type, peg-type (tooth), and rotor-type', 17, '{7}'::int[], NULL, 'Hello! Let''s simplify: to separate grain efficiently, combine harvesters use specific mechanical systems. Option 3 is correct because chain, peg (tooth), and rotor systems are the standard, recognized types of threshing mechanisms designed for this task.', NULL),
(1499, 'ka', 'რა ამოცანა აქვს მარცვლეულის გაწმენდას?', 'მარცვლეულის გაწმენდის ამოცანაა ყველა გარეშე მინარევების მოცილება და ძირითადი კულტურების მარცვლის სუფთა სახით მიღება.', 0, '2', 'ერთნაირი ზომისა და ფორმის მარცვლის მიღება', 'ყველა გარეშე მინარევების მოცილება და ძირითადი კულტურების მარცვლის სუფთა სახით მიღება', 'დაზიანებული მარცვლის მოცილება და ძირითადი კულტურების მარცვლის სუფთა სახით მიღება', 'დაზიანებული მარცვლის მოცილება და ერთნაირი ზომის მარცვლის მიღება', 17, '{7}'::int[], NULL, 'გამარჯობა! მარტივად რომ ვთქვათ, გაწმენდა ნიშნავს მარცვლეულისგან ყველაფერი არასაჭიროს მოშორებას (მაგალითად, მიწა, ქვები, სარეველა), რათა შედეგად მივიღოთ მხოლოდ სუფთა მარცვალი.', NULL),
(1499, 'ru', 'Какова задача очистки зерна?', 'Основная цель очистки зерна заключается в полном удалении из него посторонних тел и примесей, чтобы получить чистый продукт основной культуры, что соответствует стандартным агротехническим нормам.', 0, '2', 'Получение зерен одинакового размера и формы', 'Удаление всех посторонних примесей и получение зерна основной культуры в чистом виде', 'Удаление поврежденных зерен и получение зерна основной культуры в чистом виде', 'Удаление поврежденных зерен и получение зерна одинакового размера', 17, '{7}'::int[], NULL, 'Привет! Проще говоря, очистка означает удаление из зерна всего лишнего (например, земли, камней, сорняков), чтобы в итоге получить только чистую культуру.', NULL),
(1499, 'en', 'What is the task of grain cleaning?', 'The primary objective of grain cleaning is the complete removal of foreign bodies and impurities to obtain a pure product of the main crop, in accordance with standard agrotechnical regulations.', 0, '2', 'Obtaining grains of the same size and shape', 'Removal of all foreign impurities and obtaining pure grains of the main crop', 'Removal of damaged grains and obtaining pure grains of the main crop', 'Removal of damaged grains and obtaining grains of the same size', 17, '{7}'::int[], NULL, 'Hello! To put it simply, cleaning means removing anything unnecessary from the grain (such as soil, stones, or weeds) so that you end up with only pure crop.', NULL),
(1500, 'ka', 'რა მანქანები შედის მარცვლეულის საწმენდ პუნქტში?', 'მარცვლეულის საწმენდ პუნქტში შედის საწმენდ-სახარისხებლები მანქანები.', 0, '2', 'კომბაინები', 'საწმენდ-სახარისხებლები', 'სალეწები', 'სამკალები', 17, '{7}'::int[], NULL, 'გამარჯობა! მარტივად რომ ვთქვათ, საწმენდი პუნქტი არის ადგილი, სადაც მარცვლეულს ასუფთავებენ. ამისთვის გამოიყენება სპეციალური ''საწმენდ-სახარისხებელი'' მანქანები. კომბაინები, სალეწები და სამკალები სხვა პროცესებისთვისაა, ამიტომ სწორი პასუხია 2.', NULL),
(1500, 'ru', 'Какие машины входят в пункт очистки зерна?', 'В соответствии с Законом Грузии «О дорожном движении», к пункту очистки зерна относятся специализированные зерноочистительно-сортировальные машины, которые обеспечивают очистку и классификацию зерна.', 0, '2', 'Комбайны', 'Зерноочистительно-сортировальные машины', 'Молотилки', 'Жатвенные машины', 17, '{7}'::int[], NULL, 'Привет! Если говорить просто, пункт очистки — это место, где зерно доводят до кондиции. Для этого используются специальные машины — зерноочистительно-сортировальные. Комбайны, молотилки и жатки выполняют другие задачи, поэтому правильный ответ — 2.', NULL),
(1500, 'en', 'Which vehicles are included in a grain cleaning station?', 'In accordance with the Georgian Law on Road Traffic, grain cleaning stations are defined by the presence of specialized grain cleaning and sorting machines, which are designed specifically for the purification and classification of grain.', 0, '2', 'Combine harvesters', 'Grain cleaning and sorting machines', 'Threshers', 'Reapers', 17, '{7}'::int[], NULL, 'Hello! To put it simply, a cleaning station is where grain is processed to remove impurities. Specialized ''cleaning and sorting machines'' are used for this specific task. Combines, threshers, and reapers are used for different stages of harvesting, so option 2 is the correct one!', NULL),
(1501, 'ka', 'რა ჯგუფებად იყოფა სიმინდის ასაღები მანქანები?', 'სიმინდის ასაღები მანქანებია შემდეგიჯგუფის: კომბაინები, ტაროს საწმენდები, სალეწები და საშრობები.', 0, '1', 'კომბაინები, ტაროს საწმენდები, სალეწები, საშრობები', 'კომბაინები და სალეწები', 'კომბაინები და ტაროს საწმენდები', 'სამკალები და საწმენდ-სახარისხებლები', 18, '{7}'::int[], NULL, 'გამარჯობა! სიმინდის აღება კომპლექსური პროცესია. დაიმახსოვრე, რომ ეს ტექნიკა იყოფა ოთხ ეტაპად: ჯერ ვიღებთ კომბაინით, შემდეგ ვწმენდთ ტაროს, ვლეწავთ მარცვალს და ბოლოს ვაშრობთ. ამიტომ პირველი ვარიანტია სწორი!', NULL),
(1501, 'ru', 'На какие группы делятся машины для уборки кукурузы?', 'Согласно законодательству Грузии, классификация машин для уборки кукурузы включает четыре основные группы: комбайны, очистители початков, молотилки и сушилки.', 0, '1', 'Комбайны, очистители початков, молотилки, сушилки', 'Комбайны и молотилки', 'Комбайны и очистители початков', 'Жатвенные машины и очистительно-сортировочные машины', 18, '{7}'::int[], NULL, 'Привет! Уборка кукурузы — это комплексный процесс. Запомни, что техника делится на четыре этапа: сначала мы используем комбайн, затем очищаем початки, обмолачиваем зерно и в конце сушим его. Поэтому первый вариант верный!', NULL),
(1501, 'en', 'Into what groups are corn harvesting machines divided?', 'In accordance with Georgian legislation, the classification of corn harvesting machines includes four main groups: combine harvesters, cob cleaners, threshers, and dryers.', 0, '1', 'Combine harvesters, cob cleaners, threshers, dryers', 'Combine harvesters and threshers', 'Combine harvesters and cob cleaners', 'Reapers and cleaning-sorting machines', 18, '{7}'::int[], NULL, 'Hello! Harvesting corn is a complex process. Remember that the equipment is divided into four stages: first, we harvest with a combine, then we clean the cobs, thresh the grain, and finally, we dry it. That is why the first option is correct!', NULL),
(1502, 'ka', 'კომბაინით ჭარხლის აღების დროს ხდება შემდეგი ოპერაციები:', 'კომბაინით ჭარხლის აღების დროს ხდება შემდეგი ოპერაციები: ნიადაგიდან ჭარხლის ამოღება, მიწისგან გასუფთავება, ფოჩების მოჭრა და ჭარხლის ძირხვენების შეგროვება ბუნკერში.', 0, '2', 'ნიადაგიდან ჭარხლის ამოღება და ღვარეულებად დაყრა', 'ნიადაგიდან ჭარხლის ამოღება, მიწისგან გასუფთავება, ფოჩების მოჭრა და ჭარხლის ძირხვენების შეგროვება ბუნკერში', 'ნიადაგიდან ჭარხლის ამოღება, მიწისგან გასუფთავება და ღვარეულებად დაყრა', 'ნიადაგიდან ჭარხლის ამოღება და შეგროვება ბუნკერში', 18, '{7}'::int[], NULL, 'გამარჯობა! ჭარხლის აღება კომპლექსური პროცესია. კომბაინი არა მხოლოდ თხრის ძირხვენს, არამედ ასუფთავებს მას და ჭრის ფოჩებს, რათა მოსავალი მზად იყოს ტრანსპორტირებისთვის. ამიტომ მეორე პასუხი ყველაზე სრულია.', NULL),
(1502, 'ru', 'Какие операции выполняет свеклоуборочный комбайн при сборе урожая?', 'Согласно «Закону Грузии о дорожном движении», регламентирующему эксплуатацию сельхозтехники, правильный ответ 2 включает полный технологический цикл работы свеклоуборочного комбайна: извлечение из почвы, очистку от остатков земли, удаление ботвы и накопление корнеплодов в бункере.', 0, '2', 'Извлечение свеклы из почвы и укладка в валки', 'Извлечение свеклы из почвы, очистка от земли, обрезка ботвы и сбор корнеплодов в бункер', 'Извлечение свеклы из почвы, очистка от земли и укладка в валки', 'Извлечение свеклы из почвы и сбор в бункер', 18, '{7}'::int[], NULL, 'Привет! Уборка сахарной свеклы — это сложный процесс. Комбайн не просто выкапывает корнеплод, но и очищает его, а также срезает ботву, чтобы подготовить урожай к перевозке. Поэтому вариант 2 является наиболее полным и верным описанием работы техники.', NULL),
(1502, 'en', 'What operations are performed by a combine harvester when harvesting sugar beets?', 'Pursuant to the ''Law of Georgia on Road Traffic'' regarding agricultural machinery operations, correct answer 2 represents the comprehensive technical cycle of a beet harvester: extraction from soil, cleaning of dirt, removal of foliage (tops), and storage of root crops in the bunker.', 0, '2', 'Extracting beets from the soil and laying them in windrows', 'Extracting beets from the soil, cleaning from soil, cutting off the tops, and collecting the root crops in a bunker', 'Extracting beets from the soil, cleaning from soil, and laying them in windrows', 'Extracting beets from the soil and collecting them in a bunker', 18, '{7}'::int[], NULL, 'Hello! Harvesting sugar beets is a complex task. A combine harvester doesn''t just dig up the roots; it also cleans them and removes the tops to prepare the crop for transport. That is why answer 2 is the most complete and correct description of the machine''s operation.', NULL),
(1503, 'ka', 'ძირხვენების ამოღების როგორ ხერხებს ანსხვავებენ?', 'ძირხვენების ამოღების ხერხებია ნაკადური, გადატვირთვის, ნაკადურ-გადატვირთვის და ნახევრად ნაკადური.', 0, '4', 'ნაკადურს და ნახევრად ნაკადურს', 'ნაკადურ-გადატვირთვის', 'ნაკადურს და ნაკადურ-გადატვირთვის', 'ნაკადურს, გადატვირთვის, ნაკადურ-გადატვირთვის და ნახევრად ნაკადურს', 18, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ძირხვენების აღებისას მნიშვნელოვანია ტექნოლოგიის სწორი არჩევა. სწორი პასუხია 4, რადგან ის აერთიანებს მოსავლის აღების ყველა ძირითად მეთოდს, რაც დაგეხმარება ტექნიკური პროცესების სწორად დაგეგმვაში.', NULL),
(1503, 'ru', 'Какие методы уборки корнеплодов различают?', 'Согласно законодательству Грузии и стандартам эксплуатации сельскохозяйственной техники, основными технологическими методами уборки корнеплодов являются: поточный, перевалочный, поточно-перевалочный и полупоточный. Четвертый ответ является единственным, который полностью охватывает данную классификацию.', 0, '4', 'Поточный и полупоточный', 'Поточно-перевалочный', 'Поточный и поточно-перевалочный', 'Поточный, перевалочный, поточно-перевалочный и полупоточный', 18, '{7}'::int[], NULL, 'Привет! Помни, что при сборе корнеплодов важно выбрать правильную технологию. Верный ответ — 4, так как он включает все основные методы сбора, что поможет тебе правильно спланировать технические процессы.', NULL),
(1503, 'en', 'What are the different methods of harvesting root crops?', 'According to Georgian legislation and agricultural machinery operation standards, the main technological methods for harvesting root crops are: flow, transshipment, flow-transshipment, and semi-flow. The fourth answer is the only one that encompasses the full scope of this classification.', 0, '4', 'Flow and semi-flow', 'Flow-transshipment', 'Flow and flow-transshipment', 'Flow, transshipment, flow-transshipment, and semi-flow', 18, '{7}'::int[], NULL, 'Hello! Remember that when harvesting root crops, it is important to choose the right technology. The correct answer is 4, as it encompasses all the primary harvesting methods, which will help you plan your technical processes effectively.', NULL),
(1504, 'ka', 'კარტოფილის აღების როგორი მეთოდები არსებობს?', 'კარტოფილის აღებისმეთოდები არსებობს: ორფაზა, ნაკადური და კომბინირებული.', 0, '1', 'ორფაზა, ნაკადური და კომბინირებული', 'ორფაზა და კომბინირებული', 'კომბინირებული', 'ნაკადური', 18, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ კარტოფილის აღება სამი გზით ხდება: ჯერ თხრიან და შემდეგ კრეფენ (ორფაზა), ერთიანად კრეფენ (ნაკადური), ან ორივეს კომბინაციას იყენებენ.', NULL),
(1504, 'ru', 'Какие существуют методы уборки картофеля?', 'Согласно законодательству Грузии и стандартам сельскохозяйственной техники, технологический процесс уборки картофеля включает три основных метода: двухфазный, поточный и комбинированный.', 0, '1', 'Двухфазный, поточный и комбинированный', 'Двухфазный и комбинированный', 'Комбинированный', 'Поточный', 18, '{7}'::int[], NULL, 'Привет! Запомни, что существует три способа уборки картофеля: сначала выкапывают, а потом собирают (двухфазный), собирают сразу (поточный) или используют комбинацию этих методов.', NULL),
(1504, 'en', 'What methods are there for harvesting potatoes?', 'According to Georgian legislation and agricultural machinery standards, the technological process of potato harvesting includes three main methods: two-phase, stream (flow), and combined.', 0, '1', 'Two-phase, stream (flow), and combined', 'Two-phase and combined', 'Combined', 'Stream (flow)', 18, '{7}'::int[], NULL, 'Hello! Remember, there are three ways to harvest potatoes: digging first then picking (two-phase), picking everything at once (stream/flow), or using a combination of both.', NULL),
(1505, 'ka', 'ჩაის ფოთლის საკრეფი როგორი მანქანები არსებობს?', 'ჩაის ფოთლის საკრეფი მანქანები არსებობს ხელისა და მობილური.', 0, '3', 'თვითმავალი', 'მისაბმელი', 'ხელისა და მობილური', 'ნახევრად მისაბმელი', 18, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ჩაის საკრეფი ტექნიკა იყოფა ორ ძირითად კატეგორიად: ისეთებად, რომლებსაც ხელით მართავ და ისეთებად, რომლებიც მობილურია (თვითმავალი ან გადასაადგილებელი). სწორი პასუხია 3.', NULL),
(1505, 'ru', 'Какие существуют машины для сбора чайного листа?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, классификация машин для сбора чая ограничивается ручными и мобильными типами.', 0, '3', 'Самоходные', 'Прицепные', 'Ручные и мобильные', 'Полуприцепные', 18, '{7}'::int[], NULL, 'Привет! Запомни, что техника для сбора чая делится на две основные категории: те, которыми управляют вручную, и мобильные устройства. Правильный ответ — 3.', NULL),
(1505, 'en', 'What types of tea leaf harvesting machines exist?', 'According to the Law of Georgia "On Road Traffic" and relevant technical regulations, the classification of tea harvesting machines is limited to hand-held and mobile types.', 0, '3', 'Self-propelled', 'Trailed', 'Hand-held and mobile', 'Semi-trailed', 18, '{7}'::int[], NULL, 'Hello! Remember that tea harvesting equipment is divided into two main categories: those operated by hand and mobile units. The correct answer is 3.', NULL),
(1506, 'ka', 'რა არის სასოფლო სამეურნეო აგრეგატი?', 'სასოფლო სამეურნეო აგრეგატია ტრაქტორს + სასოფლო სამეურნეო მანქანა.', 0, '1', 'ტრაქტორს + სასოფლო სამეურნეო მანქანა', 'ტრაქტორს + ტრაქტორი', 'გუთანს + ფარცხი', 'გუთანს + ფარცხი + სათესი', 18, '{7}'::int[], NULL, 'მარტივად რომ ვთქვათ, აგრეგატი არის „ტრაქტორი + სამუშაო ინსტრუმენტი“. ვინაიდან ტრაქტორი თავისთავად მანქანაა, მას სჭირდება დამატებითი მოწყობილობა (მაგალითად, სათესი ან სათიბი) მუშაობის შესასრულებლად. სწორედ ამ გაერთიანებას ვუწოდებთ აგრეგატს.', NULL),
(1506, 'ru', 'Что такое сельскохозяйственный агрегат?', 'Согласно Закону Грузии «О дорожном движении», сельскохозяйственный агрегат определяется как совокупность трактора и присоединенной к нему сельскохозяйственной машины. Данное определение устанавливает связь между механическим транспортным средством и рабочим инструментом.', 0, '1', 'Трактор + сельскохозяйственная машина', 'Трактор + трактор', 'Плуг + борона', 'Плуг + борона + сеялка', 18, '{7}'::int[], NULL, 'Простыми словами, агрегат — это «трактор + рабочий инструмент». Так как трактор сам по себе является лишь тягачом, ему нужно дополнительное устройство (например, сеялка или косилка) для выполнения работы. Именно такое сочетание мы называем агрегатом.', NULL),
(1506, 'en', 'What is an agricultural aggregate?', 'According to the Law of Georgia "On Road Traffic", an agricultural aggregate is defined as the combination of a tractor and an agricultural machine attached to it. This definition establishes the connection between a mechanical vehicle and a working implement.', 0, '1', 'Tractor + agricultural machine', 'Tractor + tractor', 'Plow + harrow', 'Plow + harrow + seeder', 18, '{7}'::int[], NULL, 'Simply put, an aggregate is a "tractor + working tool". Since a tractor itself is a machine, it needs an additional device (like a seeder or a mower) to perform tasks. This combination is what we define as an aggregate.', NULL),
(1507, 'ka', 'დაასახელეთ სოფლის მეურნეობაში გამოყენებული ენერგეტიკული საშუალება:', 'სოფლის მეურნეობაში გამოყენებული ენერგეტიკული საშუალებაა ტრაქტორი, მოტობლოკი და თვითმავალი შასი.', 0, '3', 'მისაბმელი', 'გუთანი', 'ტრაქტორი, მოტობლოკი, თვითმავალი შასი', 'გუთანი, ფარცხი და სათესი', 18, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს: ენერგეტიკული საშუალება არის ის, რაც ქმნის ენერგიას და ამოძრავებს სხვა დანადგარებს. გუთანი ან ფარცხი მხოლოდ ინვენტარია, ხოლო ტრაქტორი და მოტობლოკი არიან ის „ძრავები“, რომლებიც მათ აამუშავებენ.', NULL),
(1507, 'ru', 'Назовите энергетическое средство, используемое в сельском хозяйстве:', 'Согласно Закону Грузии «О дорожном движении», энергетическим средством, используемым в сельском хозяйстве, является механическое транспортное средство, оснащенное собственным двигателем и предназначенное для выполнения сельскохозяйственных работ или буксировки прицепного оборудования.', 0, '3', 'Прицеп', 'Плуг', 'Трактор, мотоблок, самоходное шасси', 'Плуг, борона и сеялка', 18, '{7}'::int[], NULL, 'Привет! Запомни: энергетическое средство — это то, что вырабатывает энергию для работы других устройств. Плуг или борона — это просто инвентарь, а трактор и мотоблок — это «двигатели», которые заставляют их работать.', NULL),
(1507, 'en', 'Name the power-driven vehicle used in agriculture:', 'According to the Georgian ''Law on Road Traffic'', a power-driven vehicle used in agriculture is defined as a motor vehicle equipped with its own engine, designed to perform agricultural work or to move trailed equipment.', 0, '3', 'Trailer', 'Plow', 'Tractor, walk-behind tractor (motoblock), self-propelled chassis', 'Plow, harrow, and seeder', 18, '{7}'::int[], NULL, 'Hello! Remember: a ''power-driven vehicle'' (energy source) is something that generates power to operate other equipment. A plow or a harrow is just an attachment, while tractors and motoblocks are the ''engines'' that make them work.', NULL),
(1508, 'ka', 'ოთხტაქტიანი ძრავის ტაქტებია:', 'ოთხტაქტიანი ძრავის ტაქტებია: შეწოვა, შეკუმშვა, მუშა სვლა და გამოშვება.', 0, '2', 'უქმი სვლა, შეწოვა, მუშა სვლა და გამოშვება', 'შეწოვა, შეკუმშვა, მუშა სვლა და გამოშვება', 'შეწოვა, შეკუმშვა, უკუსვლა და გამოშვება', 'შეწოვა, შეკუმშვა, უქმი სვლა და მუშა სვლა', 19, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს მარტივი ფორმულა: ძრავა ჰაერისა და საწვავის ნარევს „შეისრუტავს“, „კუმშავს“ მას, ხდება „აფეთქება“ (მუშა სვლა), რის შემდეგაც გამონაბოლქვი „გამოიტყორცნება“. ეს ოთხი ნაბიჯი ქმნის ციკლს, რომელიც მანქანას ამოძრავებს.', NULL),
(1508, 'ru', 'Такты четырехтактного двигателя:', 'Согласно Закону Грузии «О дорожном движении» и техническим регламентам, рабочий цикл четырехтактного двигателя внутреннего сгорания состоит из четырех последовательных фаз: впуск, сжатие, рабочий ход (сгорание) и выпуск.', 0, '2', 'Холостой ход, впуск, рабочий ход и выпуск', 'Впуск, сжатие, рабочий ход и выпуск', 'Впуск, сжатие, обратный ход и выпуск', 'Впуск, сжатие, холостой ход и рабочий ход', 19, '{7}'::int[], NULL, 'Привет! Запомни простую формулу: двигатель «всасывает» топливовоздушную смесь, «сжимает» её, происходит «взрыв» (рабочий ход), после чего отработанные газы «выбрасываются». Эти четыре шага составляют цикл, который приводит автомобиль в движение.', NULL),
(1508, 'en', 'The strokes of a four-stroke engine are:', 'In accordance with the Georgian Law on Road Traffic and technical regulations, the operating cycle of a four-stroke internal combustion engine consists of four sequential phases: intake, compression, power stroke (combustion), and exhaust.', 0, '2', 'Idle stroke, intake, power stroke and exhaust', 'Intake, compression, power stroke and exhaust', 'Intake, compression, reverse stroke and exhaust', 'Intake, compression, idle stroke and power stroke', 19, '{7}'::int[], NULL, 'Hello! Remember a simple formula: the engine ''sucks in'' the air-fuel mixture, ''compresses'' it, a ''bang'' occurs (the power stroke), and then the exhaust gases are ''pushed out''. These four steps create the cycle that keeps your car moving.', NULL),
(1509, 'ka', 'ჩამოთვალეთ ძრავის ტიპები ტაქტების რაოდენობის მიხედვით:', 'ძრავის ტიპები ტაქტების რაოდენობის მიხედვით არის ორტაქტიანი და ოთხტაქტიანი.', 0, '2', 'ერთტაქტიანი და ოთხტაქტიანი', 'ორტაქტიანი და ოთხტაქტიანი', 'ერთტაქტიანი, ორტაქტიანი და ოთხტაქტიანი', 'ორტაქტიანი, სამტაქტიანი და ოთხტაქტიანი', 19, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ავტომობილის ძრავა ასრულებს მუშაობას ციკლებად. ყველაზე გავრცელებული ტიპებია ორტაქტიანი (სადაც ციკლი სრულდება დგუშის ორი სვლით) და ოთხტაქტიანი (ოთხი სვლით). სხვა ვარიანტები არასწორია.', NULL),
(1509, 'ru', 'Перечислите типы двигателей по количеству тактов:', 'Согласно законодательству Грузии и техническим стандартам, двигатели внутреннего сгорания по рабочему циклу делятся на двухтактные и четырехтактные.', 0, '2', 'Однотактный и четырехтактный', 'Двухтактный и четырехтактный', 'Однотактный, двухтактный и четырехтактный', 'Двухтактный, трехтактный и четырехтактный', 19, '{7}'::int[], NULL, 'Привет! Запомни, что двигатель автомобиля работает циклично. Основные типы — это двухтактные (цикл завершается за два хода поршня) и четырехтактные (за четыре хода). Остальные варианты технически неверны.', NULL),
(1509, 'en', 'List the engine types according to the number of strokes:', 'According to Georgian legislation and technical standards, internal combustion engines are classified into two-stroke and four-stroke engines based on their operating cycle.', 0, '2', 'One-stroke and four-stroke', 'Two-stroke and four-stroke', 'One-stroke, two-stroke and four-stroke', 'Two-stroke, three-stroke and four-stroke', 19, '{7}'::int[], NULL, 'Hello! Remember that car engines operate in cycles. The most common types are two-stroke (where the cycle is completed in two piston strokes) and four-stroke (in four strokes). Other options are technically incorrect.', NULL),
(1510, 'ka', 'რის მიხედვით კლასიფიცირდება სასოფლო-სამეურნეო ტრაქტორები?', 'სასოფლო სამეურნეო ტრაქტორები კლასიფიცირდება დანიშნულების, სავალი ნაწილის, ჩარჩოს, ძრავის სიმძლავრის, ტრანსმისიის და წევითი ძალის მიხედვით.', 0, '3', 'სავალი ნაწილის, გაბარიტული ზომების, განათების სისტემის, საკიდი სისტემის მიხედვით', 'ძრავის, ტრანსმისიის, გადაცემის, გაგრილების, გამოყენებული საწვავის მიხედვით', 'დანიშნულების, სავალი ნაწილის, ჩარჩოს, ძრავის სიმძლავრის, ტრანსმისიის, წევითი ძალის მიხედვით', NULL, 19, '{7}'::int[], NULL, 'გამარჯობა! ტრაქტორების კლასიფიკაციისთვის მწარმოებლები და კანონმდებლობა ითვალისწინებენ ისეთ მნიშვნელოვან ტექნიკურ პარამეტრებს, როგორიცაა მისი სიმძლავრე და წევითი ძალა. დაიმახსოვრე, რომ სწორედ ეს მაჩვენებლები განსაზღვრავს ტრაქტორის ფუნქციურ შესაძლებლობებს.', NULL),
(1510, 'ru', 'По каким критериям классифицируются сельскохозяйственные тракторы?', 'В соответствии с законодательством Грузии, классификация сельскохозяйственных тракторов осуществляется с учетом их назначения, ходовой части, рамы, мощности двигателя, трансмиссии и тягового усилия.', 0, '3', 'По ходовой части, габаритным размерам, системе освещения, системе подвески', 'По двигателю, трансмиссии, передаче, охлаждению, используемому топливу', 'По назначению, ходовой части, раме, мощности двигателя, трансмиссии, тяговому усилию', NULL, 19, '{7}'::int[], NULL, 'Привет! Для классификации тракторов производители и законодательство учитывают такие важные технические параметры, как мощность и тяговое усилие. Запомни, что именно эти показатели определяют функциональные возможности трактора.', NULL),
(1510, 'en', 'According to what criteria are agricultural tractors classified?', 'In accordance with Georgian legislation, the classification of agricultural tractors is carried out based on their purpose, undercarriage, frame, engine power, transmission, and tractive effort.', 0, '3', 'According to the undercarriage, overall dimensions, lighting system, suspension system', 'According to the engine, transmission, gear, cooling, fuel used', 'According to the purpose, undercarriage, frame, engine power, transmission, tractive effort', NULL, 19, '{7}'::int[], NULL, 'Hello! To classify tractors, manufacturers and legislation consider important technical parameters such as engine power and tractive effort. Remember that these are the indicators that define the tractor''s functional capabilities.', NULL),
(1511, 'ka', 'დანიშნულების მიხედვით როგორ კლასიფიცირდება ავტომობილები?', 'დანიშნულების მიხედვით ავტომობილები კლასიფიცირდება სატრანსპორტო, სატვირთო და სპეციალური.', 0, '1', 'სატრანსპორტო, სატვირთო და სპეციალური', 'ჩქაროსნული და ნელი სვლის', 'მძიმე და მსუბუქი', 'ჩქაროსნული, ნელი სვლის, მძიმე და მსუბუქი', 19, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მანქანის კლასიფიკაცია იმის მიხედვით ხდება, თუ რისთვის გამოიყენება ის: ხალხის გადასაყვანად (სატრანსპორტო), ტვირთის გადასაზიდად (სატვირთო) თუ რაიმე სპეციალური სამუშაოს შესასრულებლად (სპეციალური). ეს კლასიფიკაცია გვეხმარება სწორად განვსაზღვროთ ავტომობილის როლი საგზაო მოძრაობაში.', NULL),
(1511, 'ru', 'Как классифицируются автомобили по назначению?', 'Согласно Закону Грузии «О дорожном движении», по своему назначению автомобили подразделяются на три категории: транспортные (предназначенные для перевозки пассажиров), грузовые (для перевозки грузов) и специальные (автомобили, оснащенные специальным техническим оборудованием).', 0, '1', 'Транспортные, грузовые и специальные', 'Скоростные и тихоходные', 'Тяжелые и легкие', 'Скоростные, тихоходные, тяжелые и легкие', 19, '{7}'::int[], NULL, 'Привет! Запомни, что классификация автомобиля зависит от его основной функции: перевозка людей (транспортные), перевозка грузов (грузовые) или выполнение специфических задач (специальные). Это деление важно для понимания правил эксплуатации каждого типа транспортного средства.', NULL),
(1511, 'en', 'How are vehicles classified according to their purpose?', 'According to the Law of Georgia ''On Road Traffic'', vehicles are classified by their purpose into three categories: transport (designed for passenger transport), cargo (designed for transporting freight), and special (vehicles equipped with special technical equipment).', 0, '1', 'Transport, cargo (freight), and special', 'High-speed and slow-moving', 'Heavy and light', 'High-speed, slow-moving, heavy and light', 19, '{7}'::int[], NULL, 'Hello! Remember, vehicle classification is based on its primary function: carrying people (transport), moving freight (cargo), or performing specific technical tasks (special). This classification helps us understand the vehicle''s role and rules on the road.', NULL),
(1512, 'ka', 'ჩამოთვალეთ სასოფლო-სამეურნეო დანიშნულების მისაბმელები და ნახევრადმისაბმელები:', 'სასოფლო-სამეურნეო დანიშნულების მისაბმელები და ნახევრადმისაბმელებია: სასფლო-სამეურნეო ტვირთების გადასატანი მისაბმელები, ცხოველების გადასაყვანი მისაბმელები, საკვების დაგასატანი მისაბმელები.', 0, '3', 'თვითმავალი მისაბმელები, თივის გადამტანი მისაბმელები, ცხოველების გადამყვანი მისაბმელები', 'ერთღერძიანი მისაბმელები, ორღერძიანი მისაბმელები', 'სასოფლო-სამეურნეო ტვირთების გადასატანი მისაბმელები, ცხოველების გადასაყვანი მისაბმელები, საკვების დაგასატანი მისაბმელები', NULL, 19, '{7}'::int[], NULL, 'გამარჯობა! აქ გასათვალისწინებელია მხოლოდ ის, თუ რისთვის გამოიყენება მისაბმელი. რადგან საუბარია სოფლის მეურნეობაზე, პასუხი მარტივია: ის მისაბმელები, რომლებსაც გადააქვთ სოფლის მეურნეობის პროდუქტები, ცხოველები ან საკვები. ეს არის ყველაზე ზუსტი ჩამონათვალი, რაც კანონშია მოცემული.', NULL),
(1512, 'ru', 'Перечислите прицепы и полуприцепы сельскохозяйственного назначения:', 'Согласно Закону Грузии «О дорожном движении», прицепы и полуприцепы сельскохозяйственного назначения классифицируются по их функциональному применению. Правильный ответ основан на законодательном определении, включающем прицепы для перевозки сельскохозяйственных грузов, животных и кормов.', 0, '3', 'Самоходные прицепы, прицепы для перевозки сена, прицепы для перевозки животных', 'Одноосные прицепы, двухосные прицепы', 'Прицепы для перевозки сельскохозяйственных грузов, прицепы для перевозки животных, прицепы для перевозки кормов', NULL, 19, '{7}'::int[], NULL, 'Привет! Здесь главное запомнить функциональное назначение. Так как речь идет о сельском хозяйстве, выбираем те прицепы, которые используются именно в аграрном секторе: для грузов, животных и кормов. Это официальный перечень из правил.', NULL),
(1512, 'en', 'List the agricultural trailers and semi-trailers:', 'According to the Law of Georgia ''On Road Traffic'', agricultural trailers and semi-trailers are classified based on their intended use. The correct answer is based on the legal definition, which covers trailers designed for agricultural cargo, livestock, and feed.', 0, '3', 'Self-propelled trailers, hay transport trailers, animal transport trailers', 'Single-axle trailers, double-axle trailers', 'Trailers for transporting agricultural cargo, animal transport trailers, feed transport trailers', NULL, 19, '{7}'::int[], NULL, 'Hello! The key here is to focus on the purpose. Since we are talking about agriculture, the correct answer lists the exact types used in farming: trailers for agricultural cargo, livestock, and animal feed. This is the official classification provided by the law.', NULL),
(1513, 'ka', 'რა ნიშნების მიხედვით კლასიფიცირდება შიგაწვის ძრავები?', 'შიგა წვის ძრავები კლასიფიცირდება დანიშნულების, საწვავის წარმოქმნის, საწვავის ანთების, ტაქტების რაოდენობის, ცილინდრების რიცხვის, ცილინდრების განლაგების, გამოყენებული საწვავის ტიპისა და გაგრილების სისტემის მიხედვით.', 0, '2', 'დანიშნულების, საწვავის სახეობის, ცილინდრების მორიგეობის, კუმშვის კამერის მოცულობის, დგუშების დიამეტრის, დგუშების რიცხვის მიხედვით', 'დანიშნულების, საწვავის წარმოქმნის, საწვავის ანთების, ტაქტების რაოდენობის, ცილინდრების რიცხვის, ცილინდრების განლაგების, გამოყენებული საწვავის ტიპის, გაგრილების სისტემის მიხედვით', 'კუმშვის კამერის მოცულობის, დგუშის სვლის, დგუშების რიცხვის, ცილინდრების რიცხვის, ცილინდრების განლაგების, სამუშაო პროცესის, სამუშაო ტაქტებისა და უქმი სვლების რიცხვების მიხედვით', NULL, 19, '{7}'::int[], NULL, 'გამარჯობა! ძრავის ტიპის გასაგებად, მექანიკოსები და ინჟინრები სწორედ ამ ჩამონათვალს იყენებენ. მეორე ვარიანტი სწორია, რადგან ის აერთიანებს ძრავის მუშაობის ძირითად ტექნიკურ მახასიათებლებს, როგორებიცაა გაგრილების სისტემა და საწვავის ანთების ტიპი, რაც განსაზღვრავს ძრავის ეფექტურობას.', NULL),
(1513, 'ru', 'По каким признакам классифицируются двигатели внутреннего сгорания?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, двигатели внутреннего сгорания классифицируются по их назначению, способу смесеобразования, способу воспламенения, количеству тактов, количеству и расположению цилиндров, типу используемого топлива и системе охлаждения.', 0, '2', 'По назначению, виду топлива, порядку работы цилиндров, объему камеры сгорания, диаметру поршней, количеству поршней.', 'По назначению, способу смесеобразования, способу воспламенения, количеству тактов, числу цилиндров, расположению цилиндров, типу используемого топлива, системе охлаждения.', 'По объему камеры сгорания, ходу поршня, количеству поршней, числу цилиндров, расположению цилиндров, рабочему процессу, количеству рабочих тактов и холостых ходов.', NULL, 19, '{7}'::int[], NULL, 'Привет! Чтобы определить тип двигателя, инженеры используют именно эти критерии. Второй вариант верный, так как он объединяет ключевые технические характеристики, такие как система охлаждения и способ воспламенения топлива, которые определяют работу и эффективность двигателя.', NULL),
(1513, 'en', 'According to which signs are internal combustion engines classified?', 'According to the Georgian Law on Road Traffic and relevant technical regulations, internal combustion engines are classified based on their purpose, method of mixture formation, method of ignition, number of strokes, number and arrangement of cylinders, type of fuel used, and cooling system.', 0, '2', 'According to purpose, fuel type, cylinder firing order, combustion chamber volume, piston diameter, number of pistons.', 'According to purpose, method of mixture formation, method of ignition, number of strokes, number of cylinders, cylinder arrangement, type of fuel used, cooling system.', 'According to combustion chamber volume, piston stroke, number of pistons, number of cylinders, cylinder arrangement, working process, number of working strokes and idle strokes.', NULL, 19, '{7}'::int[], NULL, 'Hello! To identify an engine type, engineers use these specific criteria. The second option is correct because it combines the essential technical characteristics, such as the cooling system and ignition method, which define how an engine operates and performs.', NULL),
(1514, 'ka', 'რა ნაწილებისგან შესდგება მრუდმხარა ბარბაცა მექანიზმი?', 'მრუდმხარა ბარბაცა მექანიზმი შესდგება დგუშის, დგუშის თითის, ბარბაცას და მუხლანა ლილვისაგან.', 0, '3', 'ბარბაცა, ექსცენტრიული კბილანა, ლილვი, მქნევარა', 'მუხლანა ლილვი, დგუშის რგოლები, ბარბაცა', 'დგუში, დგუშის თითი, ბარბაცა, მუხლანა ლილვი', NULL, 19, '{7}'::int[], NULL, 'გამარჯობა! წარმოიდგინე, რომ მრუდმხარა-ბარბაცა მექანიზმი არის ძრავის „გული“. დგუში იღებს დარტყმას აფეთქებისგან, თითი მას აერთებს ბარბაცასთან, ბარბაცა კი ამ მოძრაობას გადასცემს მუხლანა ლილვს, რომელიც უკვე ბრუნავს. ამიტომ, სწორი პასუხია 3, რადგან ეს ოთხივე ნაწილი ერთად ქმნის ამ მექანიზმს.', NULL),
(1514, 'ru', 'Из каких частей состоит кривошипно-шатунный механизм?', 'Согласно Закону Грузии «О дорожном движении» и принципам автомобильной инженерии, кривошипно-шатунный механизм является основным узлом двигателя, преобразующим возвратно-поступательное движение поршня во вращательное движение коленчатого вала. В его состав входят четыре ключевых элемента: поршень, поршневой палец, шатун и коленчатый вал.', 0, '3', 'Шатун, эксцентриковая шестерня, вал, маховик', 'Коленчатый вал, поршневые кольца, шатун', 'Поршень, поршневой палец, шатун, коленчатый вал', NULL, 19, '{7}'::int[], NULL, 'Привет! Представь, что кривошипно-шатунный механизм — это «сердце» двигателя. Поршень принимает энергию от взрыва топлива, палец соединяет его с шатуном, а шатун передает это движение на коленчатый вал, который начинает вращаться. Поэтому правильный ответ — 3, так как именно эти четыре части составляют полный механизм.', NULL),
(1514, 'en', 'What parts does the crank mechanism consist of?', 'According to the Law of Georgia ''On Road Traffic'' and the principles of automotive engineering, the crank mechanism is the primary engine component that converts the reciprocating motion of the piston into the rotational motion of the crankshaft. It consists of four essential components: the piston, the piston pin, the connecting rod, and the crankshaft.', 0, '3', 'Connecting rod, eccentric gear, shaft, flywheel', 'Crankshaft, piston rings, connecting rod', 'Piston, piston pin, connecting rod, crankshaft', NULL, 19, '{7}'::int[], NULL, 'Hello! Imagine the crank mechanism as the ''heart'' of the engine. The piston takes the force from the combustion, the pin connects it to the connecting rod, and the rod transfers that motion to the crankshaft, which then rotates. Therefore, option 3 is correct because these four parts together complete the assembly.', NULL),
(1515, 'ka', 'რა სისტემებისგან შედგება ტრაქტორის ძრავა?', 'ტრაქტორის ძრავა შედგება კვების სისტემის, ანთების სისტემის, შეზეთვის სისტემის, გაგრილების სისტემისა და გაშვების სისტემისაგან.', 0, '1', 'კვების სისტემა, ანთების სისტემა, შეზეთვის სისტემა, გაგრილების სისტემა, გაშვების სისტემა', 'შერევის სისტემა, შეკუმშვის სისტემა, გაფართოების სისტემა, ანთების სისტემა', 'მიწოდების სისტემა, მართვის სისტემა, დამუხრუჭების სისტემა, აჩქარების სისტემა, გადაცემის სისტემა', NULL, 20, '{7}'::int[], NULL, 'გამარჯობა! წარმოიდგინე, რომ ძრავა არის ცოცხალი ორგანიზმი: კვების სისტემა მას აძლევს „საკვებს“ (საწვავს), გაგრილება იცავს გადახურებისგან, შეზეთვა ამცირებს ხახუნს, ანთება აძლევს ენერგიას, ხოლო გაშვება არის მისი „გაღვიძება“. ამიტომ პირველი პასუხი არის სწორი!', NULL),
(1515, 'ru', 'Из каких систем состоит двигатель трактора?', 'Согласно «Закону о дорожном движении» Грузии и техническим регламентам, работа двигателя трактора обеспечивается пятью основными системами: питания, зажигания, смазки, охлаждения и пуска.', 0, '1', 'Система питания, система зажигания, система смазки, система охлаждения, система пуска', 'Система смешивания, система сжатия, система расширения, система зажигания', 'Система подачи, система управления, тормозная система, система ускорения, трансмиссия', NULL, 20, '{7}'::int[], NULL, 'Привет! Представь, что двигатель — это живой организм: система питания дает ему «еду» (топливо), охлаждение защищает от перегрева, смазка уменьшает трение, зажигание дает энергию для работы, а система пуска — это его «пробуждение». Поэтому правильный ответ — первый!', NULL),
(1515, 'en', 'What systems does a tractor engine consist of?', 'According to the Georgian ''Law on Road Traffic'' and relevant technical regulations, the operation of a tractor engine is maintained by five primary systems: fuel, ignition, lubrication, cooling, and starting systems.', 0, '1', 'Fuel system, ignition system, lubrication system, cooling system, starting system', 'Mixing system, compression system, expansion system, ignition system', 'Supply system, control system, braking system, acceleration system, transmission system', NULL, 20, '{7}'::int[], NULL, 'Hello! Imagine the engine is like a living organism: the fuel system provides ''food'', the cooling system prevents overheating, the lubrication system reduces friction, the ignition system provides energy, and the starting system is its ''wake-up call''. That is why the first answer is correct!', NULL),
(1516, 'ka', 'რა დანიშნულება აქვს ტრანსმისიას?', 'ტრანსმისიის დანიშნულებაა ძრავის მაბრუნ მომენტის გადასცეს წამყვანთვლებს.', 0, '3', 'ცვლის ტრაქტორის სიჩქარეს', 'ანაწილებს მომენტებს წინა და უკანა თვლებზე', 'ძრავის მაბრუნ მომენტს გადასცემს წამყვანთვლებს', NULL, 20, '{7}'::int[], NULL, 'გამარჯობა! წარმოიდგინე, რომ ძრავა არის შენი კუნთები, ხოლო ტრანსმისია - ის „ხიდია“, რომელიც ამ ძალას ბორბლებამდე მიიტანს. სწორედ ამიტომ, სწორი პასუხია 3: ტრანსმისია აკავშირებს ძრავას ბორბლებთან და აიძულებს მათ ბრუნვას.', NULL),
(1516, 'ru', 'Каково назначение трансмиссии?', 'Основная функция трансмиссии, в соответствии с техническим регламентом Закона Грузии «О дорожном движении», заключается в передаче механической энергии (крутящего момента), вырабатываемой двигателем, на ведущие колеса, что обеспечивает движение транспортного средства.', 0, '3', 'Изменяет скорость трактора', 'Распределяет крутящий момент на передние и задние колеса', 'Передает крутящий момент от двигателя на ведущие колеса', NULL, 20, '{7}'::int[], NULL, 'Привет! Представь, что двигатель — это твои мышцы, а трансмиссия — это «мост», который передает эту силу на колеса. Именно поэтому правильный ответ — 3: трансмиссия связывает двигатель с колесами и заставляет их вращаться.', NULL),
(1516, 'en', 'What is the purpose of the transmission?', 'The main function of the transmission, in accordance with the technical regulations of the Georgian ''Law on Road Traffic'', is to transmit the mechanical energy (torque) generated by the engine to the drive wheels, which enables the movement of the vehicle.', 0, '3', 'Changes the speed of the tractor', 'Distributes torque to the front and rear wheels', 'Transmits the engine torque to the drive wheels', NULL, 20, '{7}'::int[], NULL, 'Hi! Imagine that the engine is your muscles, and the transmission is the ''bridge'' that delivers that power to the wheels. That is why the correct answer is 3: the transmission connects the engine to the wheels and makes them rotate.', NULL),
(1517, 'ka', 'როგორი სახის ტრანსმისიები არსებობს?', 'ტრანსმისიები არსებობს საფეხურიანი, უსაფეხურო, კომბინირებული.', 0, '1', 'საფეხურიანი, უსაფეხურო, კომბინირებული', 'მექანიკური, ჰიდრავლიკური, კომბინირებული', 'ერთსაფეხურიანი, ორსაფეხურიანი, მრავალსაფეხურიანი', NULL, 20, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ტრანსმისია არის მექანიზმი, რომელიც ძრავის ძალას ბორბლებს გადასცემს. ისინი იყოფა სამ ძირითად ჯგუფად: საფეხურიანი (გადაცემების ცვლით), უსაფეხურო (CVT) და კომბინირებული. ეს სამი კატეგორია მოიცავს თანამედროვე ავტომობილებში არსებულ ყველა ძირითად სისტემას.', NULL),
(1517, 'ru', 'Какие виды трансмиссий существуют?', 'В соответствии с Законом Грузии «О дорожном движении», трансмиссии классифицируются по принципу их работы: ступенчатые (механические/автоматические), бесступенчатые (CVT) и комбинированные типы.', 0, '1', 'Ступенчатые, бесступенчатые, комбинированные', 'Механические, гидравлические, комбинированные', 'Одноступенчатые, двухступенчатые, многоступенчатые', NULL, 20, '{7}'::int[], NULL, 'Привет! Запомни, трансмиссия — это механизм, передающий мощность двигателя на колеса. Они делятся на три основные группы: ступенчатые (с переключением передач), бесступенчатые (CVT) и комбинированные. Эти три категории охватывают все основные системы, используемые в современных автомобилях.', NULL),
(1517, 'en', 'What types of transmissions exist?', 'In accordance with the Law of Georgia ''On Road Traffic'', transmissions are classified based on their operating principle: stepped (manual/automatic), continuously variable (CVT), and combined types.', 0, '1', 'Stepped, continuously variable (CVT), combined', 'Mechanical, hydraulic, combined', 'Single-speed, two-speed, multi-speed', NULL, 20, '{7}'::int[], NULL, 'Hello! Remember, a transmission is the mechanism that delivers power from the engine to the wheels. They are divided into three main groups: stepped (with gear changes), continuously variable (CVT), and combined. These three categories cover all the major systems found in modern vehicles.', NULL),
(1518, 'ka', 'გადაცემათა კოლოფები კლასიფიცირდება შემდეგნაირად:', 'გადაცემათა კოლოფები კლასიფიცირდება შემდეგნაირად: მექანიკური, ჰიდრომექანიკური და ელექტრომექანიკური.', 0, '1', 'მექანიკური, ჰიდრომექანიკური და ელექტრომექანიკური', 'ელექტრული და ავტომატური', 'ნახევრადავტომატური, სინქრონული', NULL, 20, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ეს არის კლასიკური ტექნიკური კლასიფიკაცია. სწორი პასუხი იმიტომ არის 1, რომ ის ზუსტად ფარავს გადაცემის მექანიზმის ძირითად ტიპებს, რომლებსაც ავტომობილების კონსტრუქციაში იყენებენ.', NULL),
(1518, 'ru', 'Коробки передач классифицируются следующим образом:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, основная техническая классификация коробок передач включает механические, гидромеханические и электромеханические типы.', 0, '1', 'Механические, гидромеханические и электромеханические', 'Электрические и автоматические', 'Полуавтоматические, синхронные', NULL, 20, '{7}'::int[], NULL, 'Привет! Помни, что это классическая техническая классификация. Правильный ответ 1, потому что он точно охватывает основные типы механизмов передач, используемых в конструкции автомобилей.', NULL),
(1518, 'en', 'Gearboxes are classified as follows:', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical regulations, the primary technical classification of gearboxes includes manual, hydromechanical, and electromechanical types.', 0, '1', 'Manual, hydromechanical, and electromechanical', 'Electric and automatic', 'Semi-automatic, synchronous', NULL, 20, '{7}'::int[], NULL, 'Hello! Remember that this is a classic technical classification. Option 1 is correct because it accurately covers the main types of transmission mechanisms used in automotive engineering.', NULL),
(1519, 'ka', 'ტექნიკურ ნაკეთობას ეწოდება მუშაუნარიანი თუ:', 'ტექნიკურ ნაკეთობას ეწოდება მუშაუნარიანი, თუ მას შეუძლია შეასრულოს ის ფუნქცია, რომელიც ტექნიკური დოკუმენტაციის მოთხოვნებით არის დადგენილი.', 0, '1', 'მას შეუძლია შეასრულოს ის ფუნქცია, რომელიც ტექნიკური დოკუმენტაციის მოთხოვნებით არის დადგენილი', 'ის აკმაყოფილებს გარეგანი დიზაინის მოთხოვნებს', 'ის აკმაყოფილებს უსაფრთხოების ტექნიკის ყველა მოთხოვნას', 'არ არის გასული მისი მორალური ცვეთის ვადა', 20, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ნებისმიერი დეტალი მანქანაში მუშაუნარიანად ითვლება მხოლოდ მაშინ, როცა ის ასრულებს იმ საქმეს, რისთვისაც არის შექმნილი მწარმოებლის მიერ. თუ დოკუმენტაციაში წერია, რომ დეტალმა უნდა იმუშაოს გარკვეული წესით, სწორედ ეს არის მისი მუშაუნარიანობის მაჩვენებელი.', NULL),
(1519, 'ru', 'Техническое устройство считается работоспособным, если:', 'Согласно Закону Грузии «О дорожном движении» и техническим стандартам, основным критерием работоспособности технического устройства является его способность выполнять функции, установленные технической документацией, которая определяет назначение и параметры оборудования.', 0, '1', 'Оно способно выполнять функцию, установленную требованиями технической документации', 'Оно соответствует требованиям внешнего дизайна', 'Оно отвечает всем требованиям техники безопасности', 'Не истек срок его морального износа', 20, '{7}'::int[], NULL, 'Привет! Запомни, что любая деталь в машине считается работоспособной только тогда, когда она выполняет ту задачу, для которой её создал производитель. Если в технической документации указано, как именно деталь должна работать, то это и есть главный показатель её исправности.', NULL),
(1519, 'en', 'A technical device is called operational if:', 'According to the Law of Georgia on Road Traffic and technical standards, the main criterion for the operational status of a technical device is its ability to perform the functions defined by the technical documentation, which establishes the equipment''s intended purpose and parameters.', 0, '1', 'It is able to perform the function established by the requirements of the technical documentation', 'It meets the requirements of the external design', 'It meets all safety requirements', 'Its moral depreciation period has not expired', 20, '{7}'::int[], NULL, 'Hello! Remember that any part of a vehicle is considered operational only when it performs the specific task for which it was designed by the manufacturer. If the documentation states how the part should function, that is the exact benchmark for its operational status.', NULL),
(1520, 'ka', 'მტყუნება ეწოდება:', 'მტყუნება ეწოდება მოვლენას, რომელიც იწვევს ტექნიკური ნაკეთობის მუშაუნარიანობის დაკარგვას.', 0, '4', 'მანქანის გაუმართავ მდგომარეობაში ყოფნას', 'მანქანის რესურსის ამოწურვას', 'ტექნიკური ნაკეთობის ენერგეტიკული მაჩვენებლების გაუარესებას', 'მოვლენას, რომელიც იწვევს ტექნიკური ნაკეთობის მუშაუნარიანობის დაკარგვას', 20, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ „მტყუნება“ არის ტექნიკური ტერმინი. თუ მანქანის ნაწილი ვეღარ ასრულებს თავის ფუნქციას (მაგალითად, მუხრუჭი აღარ ამუხრუჭებს), ეს არის მტყუნება. ამიტომ სწორი პასუხია 4 — ეს არის მოვლენა, როცა მექანიზმი უბრალოდ „ჩერდება“ და მუშაობას წყვეტს.', NULL),
(1520, 'ru', 'Что называется отказом (неисправностью/отказом в работе)?', 'В соответствии с Законом Грузии «О дорожном движении», отказ — это событие, приводящее к полной или частичной потере работоспособности технического устройства. Это критический момент, когда устройство перестает выполнять свои функции в соответствии с заданными параметрами.', 0, '4', 'Нахождение автомобиля в неисправном состоянии', 'Исчерпание ресурса автомобиля', 'Ухудшение энергетических показателей технического устройства', 'Событие, которое приводит к потере работоспособности технического устройства', 20, '{7}'::int[], NULL, 'Привет! Запомни, что «отказ» в технике — это конкретный момент, когда деталь или система ломается и больше не может работать. Если машина не может выполнять свою функцию, это и есть отказ. Поэтому правильный ответ 4 — это именно то событие, когда устройство теряет свою работоспособность.', NULL),
(1520, 'en', 'What is meant by a failure?', 'In accordance with the Law of Georgia ''on Road Traffic'', a failure is an event that causes a technical device to lose its operational capability, either completely or partially. It is the critical moment when the device ceases to perform its functions according to its original parameters.', 0, '4', 'The vehicle being in a faulty condition', 'Exhaustion of the vehicle''s resources', 'Deterioration of the technical device''s energy parameters', 'An event that causes the technical device to lose its operational capability', 20, '{7}'::int[], NULL, 'Hello! Remember that ''failure'' in technical terms refers to the specific moment when a component or system stops working properly. If a car part can no longer perform its function, that is a failure. Therefore, answer 4 is correct because it defines the exact moment when the equipment loses its ability to operate.', NULL),
(1521, 'ka', 'საიმედობა წარმოადგენს მანქანის:', 'საიმედობა წარმოადგენს მანქანის თვისებას, შეინარჩუნოს მოცემული ფუნქციის შესრულების უნარი საექსპლოატაციო მაჩვენებლების შეცვლის გარეშე.', 0, '1', 'თვისებას, შეინარჩუნოს მოცემული ფუნქციის შესრულების უნარი საექსპლოატაციო მაჩვენებლების შეცვლის გარეშე', 'მდგრადი მოძრაობის შენარჩუნების უნარს', 'მუშა ორგანოების უმტყუვნო მუშაობის უნარს დროის განსაზღვრულ შუალედში', 'მოცემული პროცესის მაღალხარისხოვნად შესრულების უნარს', 20, '{7}'::int[], NULL, 'გამარჯობა! საიმედოობა ნიშნავს, რომ შენი მანქანა არა მხოლოდ „დადის“, არამედ ინარჩუნებს თავის მუშა პარამეტრებს სტაბილურად. ეს არის გარანტია იმისა, რომ მართვის დროს არ შეგექმნება მოულოდნელი პრობლემები და ავტომობილი შეასრულებს თავის ფუნქციას ისე, როგორც ეს ქარხნულადაა გათვლილი.', NULL),
(1521, 'ru', 'Надежность автомобиля — это его:', 'Согласно закону Грузии «О дорожном движении» и техническим регламентам, надежность автомобиля определяется как его свойство сохранять работоспособность в заданных пределах в течение определенного времени без ухудшения эксплуатационных показателей.', 0, '1', 'Свойство сохранять способность выполнять заданные функции без изменения эксплуатационных показателей', 'Способность сохранять устойчивое движение', 'Способность рабочих органов безотказно работать в течение определенного промежутка времени', 'Способность высококачественно выполнять заданный процесс', 20, '{7}'::int[], NULL, 'Привет! Надежность означает, что твой автомобиль не просто «едет», а стабильно сохраняет свои рабочие характеристики. Это гарантия того, что во время движения не возникнет неожиданных проблем, и машина будет выполнять свои функции именно так, как заложено производителем.', NULL),
(1521, 'en', 'Reliability is a vehicle''s:', 'According to the Law of Georgia ''On Road Traffic'' and technical regulations, a vehicle''s reliability is defined as its property to maintain the ability to perform given functions within established limits over a certain period without deteriorating operational indicators.', 0, '1', 'Ability to maintain the capacity to perform given functions without changing operational indicators', 'Ability to maintain stable movement', 'Ability of working parts to function without failure for a specific time interval', 'Ability to perform a given process with high quality', 20, '{7}'::int[], NULL, 'Hello! Reliability means your car doesn''t just ''move'', but consistently maintains its operational performance. It is the guarantee that you won''t face unexpected issues while driving and that the vehicle will perform its functions exactly as intended by the manufacturer.', NULL),
(1522, 'ka', 'მანქანის გამოსადეგობის ვადა წარმოადგენს:', 'მანქანის გამოსადეგობის ვადა წარმოადგენს მანქანის ექსპლოატაციის კალენდარულ ხანგრძლივობას იმ მომენტამდე, როცა მისი ტექნიკური დოკუმენტაციით განსაზღვრული პარამეტრები აღწევს ზღვრულ მნიშვნელობას.', 0, '1', 'მანქანის ექსპლოატაციის კალენდარულ ხანგრძლივობას იმ მომენტამდე, როცა მისი ტექნიკური დოკუმენტაციით განსაზღვრული პარამეტრები აღწევს ზღვრულ მნიშვნელობას', 'მისი მორალური ცვეთის ვადას', 'სეზონური ტექნიკური მომსახურებებს შორის დროის შუალედს', 'მანქანის სამსახურის საგარანტიო ვადას', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ავტომობილის „გამოსადეგობის ვადა“ არ არის მხოლოდ გარანტია ან მორალური მოძველება. ეს არის უსაფრთხოების ზღვარი: როდესაც მანქანის დეტალები ისე ცვდება, რომ მათი მუშაობა აღარ შეესაბამება უსაფრთხოების სტანდარტებს, ავტომობილი ითვლება ვადის გასულად.', NULL),
(1522, 'ru', 'Срок пригодности автомобиля представляет собой:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, срок пригодности транспортного средства определяется как период эксплуатации, ограниченный моментом, когда технические параметры автомобиля (включая износ систем безопасности) достигают предельных значений, установленных производителем.', 0, '1', 'Календарную продолжительность эксплуатации автомобиля до момента, когда установленные в его технической документации параметры достигают предельных значений', 'Срок его морального износа', 'Временной интервал между сезонным техническим обслуживанием', 'Гарантийный срок службы автомобиля', 29, '{7}'::int[], NULL, 'Привет! Запомни, что «срок пригодности» — это не просто гарантия или моральное устаревание. Это вопрос безопасности: когда детали автомобиля изнашиваются настолько, что перестают соответствовать заводским стандартам безопасности, эксплуатация такого транспортного средства становится опасной.', NULL),
(1522, 'en', 'The service life of a vehicle is:', 'According to the Georgian Law on Road Traffic and relevant technical regulations, the service life of a vehicle is defined as the operational period limited by the moment when the vehicle''s technical parameters (including the wear of safety systems) reach the limit values established by the manufacturer.', 0, '1', 'The calendar duration of vehicle operation until the moment when the parameters defined in its technical documentation reach limit values', 'The period of its moral obsolescence', 'The time interval between seasonal maintenance', 'The warranty period of the vehicle', 29, '{7}'::int[], NULL, 'Hello! Remember, the ''service life'' of a vehicle isn''t just about the warranty or moral obsolescence. It is about safety: once the vehicle''s parts wear out to the point where they no longer meet the manufacturer''s safety standards, the vehicle is considered to have reached the end of its useful life.', NULL),
(1523, 'ka', 'მანქანათა ტექნიკური მომსახურება წარმოადგენს ოპერაციათა გარკვეულ ერთობლიობას:', 'მანქანათა ტექნიკური მომსახურება წარმოადგენს ოპერაციათა გარკვეულ ერთობლიობას რომელთა ჩატარებაც უზრუნველყოფს მანქანის მუშაუნარიანობის შენარჩუნებას.', 0, '1', 'რომელთა ჩატარებაც უზრუნველყოფს მანქანის მუშაუნარიანობის შენარჩუნებას', 'რომელთა ჩატარებაც აუცილებელია მანქანათა საიმედობის გაზრდისთვის', 'დიაგონალური და საქცევური', 'რომელთა ჩატარებაც აუცილებელია მანქანის გამოსახმარისებისთვის', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ტექნიკური მომსახურება არ არის მხოლოდ რემონტი, ეს არის პრევენცია. მისი მიზანია, რომ მანქანამ შეინარჩუნოს თავისი სამუშაო რესურსი და არ გაგვიფუჭდეს გზაში.', NULL),
(1523, 'ru', 'Техническое обслуживание автомобилей представляет собой определенный комплекс операций:', 'В соответствии с законодательством Грузии «О дорожном движении», техническое обслуживание определяется как система мер, основной целью которых является сохранение технического состояния и работоспособности транспортного средства.', 0, '1', 'проведение которых обеспечивает поддержание работоспособности автомобиля', 'проведение которых необходимо для повышения надежности автомобилей', 'диагональных и поворотных', 'проведение которых необходимо для использования автомобиля', 29, '{7}'::int[], NULL, 'Привет! Помни, техническое обслуживание — это не просто ремонт, это профилактика. Его главная цель — сохранить работоспособность машины, чтобы она не подвела тебя в дороге.', NULL),
(1523, 'en', 'Vehicle maintenance is a specific set of operations:', 'In accordance with Georgian legislation and the ''Law on Road Traffic'', technical maintenance is defined as a system of measures whose primary purpose is to maintain the technical condition and operational capability of the vehicle.', 0, '1', 'which ensure the maintenance of the vehicle''s operational capability', 'which are necessary to increase the reliability of vehicles', 'diagonal and turning', 'which are necessary for the usability of the vehicle', 29, '{7}'::int[], NULL, 'Hello! Remember, maintenance is not just about repairs; it''s about prevention. The goal is to ensure the vehicle retains its operational integrity so it stays reliable on the road.', NULL),
(1524, 'ka', 'გამოყენებული ენერგიის წყაროს მიხედვით სასოფლო-სამეურნეო აგრეგატი შეიძლება იყოს:', 'გამოყენებული ენერგიის წყაროს მიხედვით სასოფლო-სამეურნეო აგრეგატი შეიძლება იყოს თბური, ელექტრული, ჰიდრავლიკური და საჭაპანე.', 0, '1', 'თბური, ელექტრული, ჰიდრავლიკური, საჭაპანე', 'ბენზინის, დიზელის, ნავთის, ხის სპირტის', 'მობილური და სტაციონარული', 'მარტივი, კომპლექსური, კომბინირებული', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, როდესაც ვსაუბრობთ იმაზე, თუ რითი „მუშაობს“ აგრეგატი, კლასიფიკაცია მოიცავს ფიზიკურ ძალასაც. ამიტომ, სწორი პასუხია ის, სადაც ჩამოთვლილია თბური, ელექტრული, ჰიდრავლიკური და საჭაპანე (ცხოველური) ენერგიის წყაროები.', NULL),
(1524, 'ru', 'В зависимости от источника используемой энергии, сельскохозяйственный агрегат может быть:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим нормативным актам, классификация сельскохозяйственных агрегатов по источнику энергии четко определяет принцип их работы: тепловой (двигатели), электрический, гидравлический или тягловый (гужевой).', 0, '1', 'Тепловой, электрический, гидравлический, гужевой', 'Бензиновый, дизельный, керосиновый, спиртовой', 'Мобильный и стационарный', 'Простой, комплексный, комбинированный', 29, '{7}'::int[], NULL, 'Привет! Запомни, когда мы говорим о том, на чем «работает» агрегат, классификация включает и физическую силу. Поэтому правильный ответ тот, где перечислены тепловые, электрические, гидравлические и гужевые (животные) источники энергии.', NULL),
(1524, 'en', 'Depending on the source of energy used, an agricultural implement can be:', 'According to the Law of Georgia ''On Road Traffic'' and relevant normative acts, the classification of agricultural implements based on the energy source clearly defines their operating principle: thermal (engines), electric, hydraulic, or animal-drawn (draft).', 0, '1', 'Thermal, electric, hydraulic, animal-drawn', 'Gasoline, diesel, kerosene, wood alcohol', 'Mobile and stationary', 'Simple, complex, combined', 29, '{7}'::int[], NULL, 'Hello! Remember, when we talk about what powers an implement, the classification includes physical force as well. Therefore, the correct answer is the one that lists thermal, electric, hydraulic, and animal-drawn (draft) energy sources.', NULL),
(1525, 'ka', 'ტრაქტორების და ავტომობილების ტექწნიკური მომსახურების სისტემაში შედის:', 'ტრაქტორების და ავტომობილების ტექწნიკური მომსახურების სისტემაში შედის: დიაგნოსტიკა, ყოველი ცვლის, პერიოდული და სეზონური ტექნიკური მომსახურება.', 0, '4', 'გამოსახმარისება, ყოველი ცვლის, პერიოდული და სეზონური ტექნიკური მომსახურება', 'ტექნიკური დათვალიერება, ყოველი ცვლის და სეზონური ტექნიკური მომსახურება', 'გამოსახმარისება, პერიოდული და სეზონური ტექნიკური მომსახურება', 'დიაგნოსტიკა, ყოველი ცვლის, პერიოდული და სეზონური ტექნიკური მომსახურება', 29, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ მანქანის მოვლა მხოლოდ პერიოდულ შემოწმებას არ გულისხმობს. დიაგნოსტიკა არის პირველი ნაბიჯი პრობლემების გამოსავლენად, შემდეგ კი მოდის რეგულარული (ცვლის), პერიოდული და სეზონური ზრუნვა. ეს კომპლექსური მიდგომა უზრუნველყოფს უსაფრთხოებას.', NULL),
(1525, 'ru', 'В систему технического обслуживания тракторов и автомобилей входят:', 'Согласно Закону Грузии «О дорожном движении» и правилам эксплуатации автотранспортных средств, система технического обслуживания транспортных средств в обязательном порядке включает в себя диагностику (проверку технического состояния), ежедневное, периодическое и сезонное техническое обслуживание.', 0, '4', 'Консервация, ежедневное, периодическое и сезонное техническое обслуживание', 'Технический осмотр, ежедневное и сезонное техническое обслуживание', 'Консервация, периодическое и сезонное техническое обслуживание', 'Диагностика, ежедневное, периодическое и сезонное техническое обслуживание', 29, '{7}'::int[], NULL, 'Привет! Запомни, что уход за автомобилем — это не только редкие проверки. Диагностика — это важный первый шаг для выявления неисправностей, а за ней следуют ежедневное (посменное), периодическое и сезонное обслуживание. Такой комплексный подход гарантирует твою безопасность на дороге.', NULL),
(1525, 'en', 'The system of technical maintenance for tractors and automobiles includes:', 'According to the Georgian ''Law on Road Traffic'' and the regulations for vehicle operation, the system of vehicle technical maintenance comprehensively includes diagnostics (checking the technical condition), daily, periodic, and seasonal technical maintenance.', 0, '4', 'Conservation, daily, periodic, and seasonal technical maintenance', 'Technical inspection, daily and seasonal technical maintenance', 'Conservation, periodic, and seasonal technical maintenance', 'Diagnostics, daily, periodic, and seasonal technical maintenance', 29, '{7}'::int[], NULL, 'Hello! Remember, vehicle maintenance isn''t just about occasional checks. Diagnostics is the essential first step to identify issues, followed by daily (shift-based), periodic, and seasonal care. This comprehensive approach is what keeps you safe on the road.', NULL),
(1526, 'ka', 'ტრაქტორების ტექნიკური დიაგნოსტიკა წარმოადგენს:', 'ტრაქტორების ტექნიკური დიაგნოსტიკა წარმოადგენს მათი ტექნიკური მდგომარეობის დადგენის პროცესს დაუშლელად.', 0, '1', 'მათი ტექნიკური მდგომარეობის დადგენის პროცესს დაუშლელად', 'მათი ტექნიკური მდგომარეობის დადგენის პროცესს დაშლის საშუალებით', 'მათი ტექნიკური მდგომარეობის პროგნოზირების პროცესს', NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ტექნიკური დიაგნოსტიკა არის ჭკვიანი გზა ტრაქტორის მდგომარეობის შესამოწმებლად. მთავარი ისაა, რომ არაფრის დაშლა არ გჭირდება – სპეციალური ხელსაწყოებით ვადგენთ, მუშაობს თუ არა ყველაფერი გამართულად.', NULL),
(1526, 'ru', 'Техническая диагностика тракторов представляет собой:', 'В соответствии с законодательством Грузии, техническая диагностика тракторов определяется как процесс определения их технического состояния без разборки, что направлено на проверку функционирования узлов транспортного средства без выполнения демонтажных работ.', 0, '1', 'Процесс определения их технического состояния без разборки', 'Процесс определения их технического состояния путем разборки', 'Процесс прогнозирования их технического состояния', NULL, 29, '{7}'::int[], NULL, 'Привет! Запомни, что техническая диагностика — это умный способ проверки состояния трактора. Главное преимущество в том, что ничего разбирать не нужно: с помощью специальных инструментов мы определяем, работают ли все узлы исправно.', NULL),
(1526, 'en', 'Technical diagnostics of tractors is:', 'In accordance with the legislation of Georgia, technical diagnostics of tractors is defined as the process of determining their technical condition without disassembly, aimed at verifying the functionality of vehicle components without performing dismantling works.', 0, '1', 'The process of determining their technical condition without disassembly', 'The process of determining their technical condition by disassembly', 'The process of forecasting their technical condition', NULL, 29, '{7}'::int[], NULL, 'Hello! Remember that technical diagnostics is a smart way to check the condition of a tractor. The key point is that you don''t need to take anything apart—using special tools, we determine if everything is working properly without disassembly.', NULL),
(1527, 'ka', 'მანქანათა სისტემის ოპტიმიზაციის ამოცანის მიზანს წარმოადგენს', 'მოცემული პირობებისათვის ისეთი მანქანათა სისტემის შერჩევა,რომელიც უზრუნველყოფს,ისე რომ რომელიმე კრიტერიუმი მიაღწევს მინიმალურ მნიშვნელობას', 0, '2', 'მოცემული პირობებისათვის ისეთი მანქანათა სისტემის შერჩევა,რომელიც უზრუნველყოფს ეკოლოგიურად სუფთა პროდუქციის წარმოებას,შრომითი რესურსების ეკონომიური გამოყენებით', 'მოცემული პირობებისათვის ისეთი მანქანათა სისტემის შერჩევა,რომელიც უზრუნველყოფს,ისე რომ რომელიმე კრიტერიუმი მიაღწევს მინიმალურ მნიშვნელობას', 'ეკოლოგიურად სუფთა პროდუქციის წარმოებას,ხელის შრომის გამორიცხვით', 'ეკოლოგიურად სუფთა პროდუქციის წარმოებას,ენერგომატარებლების დაზოგვით', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ოპტიმიზაციის მთავარი არსი არის საუკეთესო შედეგის მიღწევა ყველაზე მცირე დანახარჯით. ამიტომ, სწორი პასუხია ის, სადაც კრიტერიუმი მინიმუმამდეა დაყვანილი.', NULL),
(1527, 'ru', 'В чем заключается цель задачи оптимизации системы машин?', 'Оптимизация системы подразумевает выбор таких параметров, при которых целевая функция (затраты, время, энергия) достигает минимального значения, что обеспечивает эффективность системы.', 0, '2', 'Выбор такой системы машин для данных условий, которая обеспечивает производство экологически чистой продукции при экономичном использовании трудовых ресурсов', 'Выбор такой системы машин для данных условий, которая обеспечивает достижение минимального значения для какого-либо критерия', 'Производство экологически чистой продукции с исключением ручного труда', 'Производство экологически чистой продукции с экономией энергоносителей', 29, '{7}'::int[], NULL, 'Привет! Помни, что главная суть оптимизации — достичь наилучшего результата при минимальных затратах. Поэтому правильный ответ тот, где критерий сведен к минимуму.', NULL),
(1527, 'en', 'What is the goal of the machine system optimization task?', 'System optimization implies selecting parameters where the objective function (costs, time, energy) reaches its minimum value, thereby ensuring system efficiency.', 0, '2', 'Selection of a machine system for given conditions that ensures the production of environmentally friendly products while using labor resources economically', 'Selection of a machine system for given conditions that ensures one of the criteria reaches a minimum value', 'Production of environmentally friendly products by eliminating manual labor', 'Production of environmentally friendly products by saving energy resources', 29, '{7}'::int[], NULL, 'Hello! Remember that the core of optimization is achieving the best result with minimal cost. Therefore, the correct answer is the one where a criterion is minimized.', NULL),
(1529, 'ka', 'ტექნოლოგიური მანქანების ხვედრით წინააღმდეგობაზე მოქმედებენ შემდეგი ფაქტორები:', 'ტექნოლოგიური მანქანების ხვედრით წინააღმდეგობაზე მოქმედებენ შემდეგი ფაქტორები: ა. ბუნებრივ-კლიმატური; ბ. კონსტრუქციული; გ. საექსპლოატაციო;', 0, '2', 'ა) ორგანიზაციული; ბ) სამეურნეო; გ) კონსტრუქციული', 'ა) ბუნებრივ-კლიმატური; ბ) კონსტრუქციული; გ) საექსპლოატაციო', 'ა) ბუნებრივ-კლიმატური; ბ) კონსტრუქციული', 'ა) კონსტრუქციული; ბ) საექსპლოატაციო', 22, '{7}'::int[], NULL, 'გამარჯობა! მოდი მარტივად ავხსნათ: როცა მანქანა მუშაობს, მას წინაღობას უწევს გარემო (წვიმა, გრუნტი - ბუნებრივი), თავად მანქანის აგებულება (წონა, ბორბლები - კონსტრუქციული) და ის, თუ როგორ ვიყენებთ მას (ტვირთი, სიჩქარე - საექსპლოატაციო). ამიტომ მეორე პასუხი სრულია.', NULL),
(1529, 'ru', 'Какие факторы влияют на удельное сопротивление технологических машин?', 'В соответствии с законодательством Грузии «О дорожном движении» и техническими регламентами, удельное сопротивление при движении технологических машин определяется тремя ключевыми факторами: природно-климатическими, конструктивными и эксплуатационными.', 0, '2', 'а) организационные; б) хозяйственные; в) конструктивные', 'а) природно-климатические; б) конструктивные; в) эксплуатационные', 'а) природно-климатические; б) конструктивные', 'а) конструктивные; б) эксплуатационные', 22, '{7}'::int[], NULL, 'Привет! Давай разберемся: чтобы машина ехала, ей нужно преодолевать сопротивление. Оно зависит от погоды и почвы (природно-климатические), от того, как построена машина (конструктивные), и от условий её использования, например, веса груза (эксплуатационные). Поэтому правильный ответ объединяет все три фактора.', NULL),
(1529, 'en', 'What factors affect the specific resistance of technological machines?', 'In accordance with the Georgian Law on Road Traffic and relevant technical regulations, the specific resistance of technological machines is determined by three main factors: natural-climatic, structural, and operational.', 0, '2', 'a) organizational; b) economic; c) structural', 'a) natural-climatic; b) structural; c) operational', 'a) natural-climatic; b) structural', 'a) structural; b) operational', 22, '{7}'::int[], NULL, 'Hi! Let''s break it down: when a machine moves, it faces resistance from the environment (weather, soil), its own design (weight, wheels), and how we operate it (speed, load). That is why option 2 is the correct and complete answer!', NULL),
(1530, 'ka', 'ძრავის ძირითად მახასიათებლებს წარმოადგენენ:', 'ძრავის ძირითად მახასიათებლებს წარმოადგენენ: ეფექტური სიმძლავრე, მაბრუნი მომენტი, საწვავი კამერის მოცულობა, საწვავის საათური ხარჯი და საწვავის ხვედრითი ხარჯი.', 0, '1', 'ეფექტური სიმძლავრე, მაბრუნი მომენტი, საწვავი კამერის მოცულობა, საწვავის საათური ხარჯი, საწვავის ხვედრითი ხარჯი', 'ბრუნვის სიხშირე, ეფექტური სიმძლავრე, მაბრუვი მომენტი, საწვავის საათური ხარჯი, საწვავის ხვედრითი ხარჯი', 'საწვავი კამერის მოცულობა, კუმშვის ხარისხი, დგუშის სვლის სიგრძე, ცილინდრების რაოდენობა', 'ცილინდრების განლაგება, საწვავი კამერის მოცულობა, კუმშვის ხარისხი, დგუშის სვლის სიგრძე', 22, '{7}'::int[], NULL, 'გამარჯობა! ძრავის მუშაობის შესაფასებლად აუცილებელია ვიცოდეთ მისი ძირითადი პარამეტრები. პირველი ვარიანტი სწორია, რადგან ის აერთიანებს ძრავის მუშაობის ეფექტურობის, სიმძლავრისა და ეკონომიურობის განმსაზღვრელ უმთავრეს ფაქტორებს.', NULL),
(1530, 'ru', 'Каковы основные характеристики двигателя?', 'Согласно законодательству Грузии и техническим регламентам безопасности дорожного движения, основными эксплуатационными характеристиками двигателя являются: эффективная мощность, крутящий момент, объем камеры сгорания, часовой и удельный расход топлива.', 0, '1', 'Эффективная мощность, крутящий момент, объем камеры сгорания, часовой расход топлива, удельный расход топлива', 'Частота вращения, эффективная мощность, крутящий момент, часовой расход топлива, удельный расход топлива', 'Объем камеры сгорания, степень сжатия, длина хода поршня, количество цилиндров', 'Расположение цилиндров, объем камеры сгорания, степень сжатия, длина хода поршня', 22, '{7}'::int[], NULL, 'Привет! Чтобы оценить работу двигателя, важно знать его основные параметры. Первый вариант верный, так как он объединяет ключевые показатели эффективности, мощности и экономичности двигателя.', NULL),
(1530, 'en', 'What are the main characteristics of an engine?', 'According to the legislation of Georgia and technical regulations for road traffic, the main operational characteristics of an engine are considered to be: effective power, torque, combustion chamber volume, hourly fuel consumption, and specific fuel consumption.', 0, '1', 'Effective power, torque, combustion chamber volume, hourly fuel consumption, specific fuel consumption', 'Rotational speed, effective power, torque, hourly fuel consumption, specific fuel consumption', 'Combustion chamber volume, compression ratio, piston stroke length, number of cylinders', 'Cylinder arrangement, combustion chamber volume, compression ratio, piston stroke length', 22, '{7}'::int[], NULL, 'Hello! To evaluate an engine''s performance, it is essential to know its key parameters. The first option is correct because it combines the primary factors that determine the engine''s efficiency, power, and economy.', NULL),
(1531, 'ka', 'აგრეგატის მანევრულობა ითვალისწინებს:', 'აგრეგატის მანევრულობა ითვალისწინებს: ა. მოხვევის უნარს; ბ. მოძრაობის მდგრადობას; გ. მართვადობას; დ. გამავლობას.', 0, '3', 'ა) მოძრაობის სიჩქარეს; ბ) მობრუნების რადიუსს; გ) გადაბრუნებისადმი მდგრადობას', 'ა) სატრანსპორტო სიჩქარეს; ბ) მოძრაობის მდგრადობას; გ) მართვადობას; დ) გამავლობას', 'ა) მოხვევის უნარს; ბ) მოძრაობის მდგრადობას; გ) მართვადობას; დ) გამავლობას', 'ა) წევით სიმძლავრეს; ბ) მოძრაობის მდგრადობას; გ) მართვადობას', 22, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ „მანევრულობა“ არ არის მხოლოდ მოხვევა. ეს არის კომპლექსური ცნება, რომელიც აერთიანებს ავტომობილის უნარს, იყოს მორჩილი (მართვადობა), სტაბილური გზაზე (მდგრადობა), ადვილად შევიდეს მოსახვევში და გადალახოს სხვადასხვა დაბრკოლება (გამავლობა). სწორედ ამიტომ მე-3 პასუხი არის სწორი.', NULL),
(1531, 'ru', 'Маневренность транспортного агрегата включает в себя:', 'Согласно Закону Грузии «О дорожном движении», маневренность транспортного средства (агрегата) определяет его способность безопасно выполнять маневры, что включает в себя способность к повороту, устойчивость движения, управляемость и способность преодолевать дорожные условия (проходимость).', 0, '3', 'а) скорость движения; б) радиус поворота; в) устойчивость к опрокидыванию', 'а) транспортную скорость; б) устойчивость движения; в) управляемость; г) проходимость', 'а) способность к повороту; б) устойчивость движения; в) управляемость; г) проходимость', 'а) тяговую мощность; б) устойчивость движения; в) управляемость', 22, '{7}'::int[], NULL, 'Привет! Помни, что «маневренность» — это не только поворот руля. Это комплексное понятие, объединяющее способность автомобиля быть послушным (управляемость), оставаться устойчивым на дороге, легко входить в повороты и преодолевать дорожные препятствия (проходимость). Именно поэтому 3-й вариант ответа является правильным.', NULL),
(1531, 'en', 'The maneuverability of an aggregate (vehicle combination) includes:', 'In accordance with the Law of Georgia ''on Road Traffic'', the maneuverability of a vehicle (aggregate) defines its ability to safely perform maneuvers, which includes the ability to turn, motion stability, steerability, and the ability to traverse various road conditions (cross-country ability).', 0, '3', 'a) movement speed; b) turning radius; c) rollover stability', 'a) transport speed; b) motion stability; c) steerability; d) cross-country ability', 'a) ability to turn; b) motion stability; c) steerability; d) cross-country ability', 'a) traction power; b) motion stability; c) steerability', 22, '{7}'::int[], NULL, 'Hello! Remember, ''maneuverability'' isn''t just about turning. It is a comprehensive concept that combines the vehicle''s ability to be responsive (steerability), stay stable on the road, easily negotiate turns, and overcome various obstacles (cross-country ability). That is why option 3 is correct.', NULL),
(1532, 'ka', 'მუშა სვლების მიმართულების მიხედვით აგრეგატის მოძრაობის სახეებია:', 'მუშა სვლების მიმართულების მიხედვით აგრეგატის მოძრაობის სახეებია: მაქოსებრი, კომბინირებული და საქცევური.', 0, '1', 'მაქოსებრი, კომბინირებული და საქცევური', 'საქცევური და წრიული', 'დიაგონალური და საქცევური', 'საქცევური, დიაგონალური და წრიული', 22, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სოფლის მეურნეობის ტექნიკის შემთხვევაში, მუშაობისას აგრეგატმა უნდა დაზოგოს დრო და საწვავი. მაქოსებრი, კომბინირებული და საქცევური სვლები ყველაზე ეფექტური მეთოდებია სამუშაო ზონის დასამუშავებლად.', NULL),
(1532, 'ru', 'По направлению рабочих ходов различают следующие виды движения агрегата:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, основными способами движения агрегата по направлению рабочих ходов являются челночный, комбинированный и загонный (петлевой). Данная классификация определяет траекторию движения сельскохозяйственной техники при выполнении полевых работ.', 0, '1', 'Челночное, комбинированное и загоночное', 'Загоночное и круговое', 'Диагональное и загоночное', 'Загоночное, диагональное и круговое', 22, '{7}'::int[], NULL, 'Привет! Запомни, что при работе сельхозтехники важно минимизировать холостые пробеги. Челночный, комбинированный и загонный способы движения — это классические приемы, которые помогают эффективно обрабатывать поле.', NULL),
(1532, 'en', 'According to the direction of working passes, the types of unit movement are:', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical regulations, the main types of unit movement based on the direction of working passes are shuttle, combined, and loop (headland/turn). This classification defines the trajectory of agricultural machinery movement while performing fieldwork.', 0, '1', 'Shuttle, combined, and loop (headland)', 'Loop (headland) and circular', 'Diagonal and loop (headland)', 'Loop (headland), diagonal, and circular', 22, '{7}'::int[], NULL, 'Hello! Remember that when operating agricultural machinery, the goal is to minimize non-productive time and fuel consumption. Shuttle, combined, and loop movements are the standard methods used to ensure the most efficient path across a working field.', NULL),
(1533, 'ka', 'მანქანათა ტექნიკური დათვალიერება (შემოწმება) წარმოადგენს:', 'მანქანათა ტექნიკური დათვალიერება (შემოწმება) წარმოადგენს მანქანის ტექნიკური მდგომარეობის გამოკვლევის პროცესს კვანძების დაშლის გარეშე, რის საფუძველზედაც კეთდება დასკვნა მანქანის ფაქტიური ტექნიკური მდგომარეობის შესახებ.', 0, '1', 'მანქანის ტექნიკური მდგომარეობის გამოკვლევის პროცესს კვანძების დაშლის გარეშე, რის საფუძველზედაც კეთდება დასკვნა მანქანის ფაქტიური ტექნიკური მდგომარეობის შესახებ', 'მანქანის ტექნიკური მომსახურების შემდეგ მის შემოწმებას საკონტროლო გავლისას', 'მანქანის ძირითადი კვანძების მდგომარეობის დადგენას გარეგანი მონაცემების საფუძველზე', 'მანქანის ტექნიკური მდგომარეობის გამოკვლევის პროცესს კვანძების დაშლის გარეშე, რის საფუძველზედაც კეთდება დასკვნა მანქანის ჩამოწერის შესახებ', 22, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ტექნიკური დათვალიერება არ ნიშნავს მანქანის დაშლას. ეს არის სწრაფი და ეფექტური შემოწმება იმისთვის, რომ დავრწმუნდეთ, არის თუ არა შენი მანქანა უსაფრთხო გზაზე მოძრაობისთვის. სწორი პასუხია ის, სადაც აღნიშნულია, რომ ჩვენ ვიკვლევთ მდგომარეობას კვანძების დაშლის გარეშე და ვაკეთებთ დასკვნას მისი ფაქტიური მდგომარეობის შესახებ.', NULL),
(1533, 'ru', 'Технический осмотр (проверка) транспортных средств представляет собой:', 'В соответствии с Законом Грузии «О дорожном движении», технический осмотр представляет собой процесс исследования технического состояния транспортного средства без разборки его узлов, целью которого является установление фактической исправности автомобиля.', 0, '1', 'Процесс исследования технического состояния автомобиля без разборки узлов, на основании которого делается заключение о фактическом техническом состоянии автомобиля', 'Проверку автомобиля после технического обслуживания при контрольном проезде', 'Определение состояния основных узлов автомобиля на основании внешних данных', 'Процесс исследования технического состояния автомобиля без разборки узлов, на основании которого делается заключение о списании автомобиля', 22, '{7}'::int[], NULL, 'Привет! Запомни, техосмотр не означает разборку автомобиля. Это быстрый и эффективный процесс проверки, чтобы убедиться, что твой автомобиль безопасен для движения. Правильный ответ тот, где указано, что мы исследуем состояние без разборки узлов и делаем вывод о его фактическом состоянии.', NULL),
(1533, 'en', 'Technical inspection (check) of vehicles represents:', 'In accordance with the Law of Georgia ''On Road Traffic'', technical inspection is the process of examining the technical condition of a vehicle without disassembling its components, aimed at determining the actual serviceability of the motor vehicle.', 0, '1', 'The process of examining the technical condition of a vehicle without disassembling its components, based on which a conclusion is made about the actual technical condition of the vehicle', 'Inspection of a vehicle during a test drive after technical maintenance', 'Determination of the condition of the vehicle''s main components based on external data', 'The process of examining the technical condition of a vehicle without disassembling its components, based on which a conclusion is made about the write-off of the vehicle', 22, '{7}'::int[], NULL, 'Hello! Remember, technical inspection does not involve disassembling the vehicle. It is a quick and efficient check to ensure your car is safe for the road. The correct answer is the one stating that we examine the condition without disassembling the components and draw a conclusion about its actual state.', NULL),
(1535, 'ka', 'საერთაშორისო სტანდარტით ტრაქტორებს უტარდებათ:', 'საერთაშორისო სტანდარტით ტრაქტორებს უტარდებათ ყოველი ცვლის, პერიოდული და სეზონური ტექნიკური მომსახურება, მიმდინარე რემონტი და კაპიტალური რემონტი.', 0, '1', 'ყოველი ცვლის, პერიოდული და სეზონური ტექნიკური მომსახურება, მიმდინარე რემონტი და კაპიტალური რემონტი', 'ყოველი ცვლის და სეზონური ტექნიკური მომსახურება, მიმდინარე რემონტი და კაპიტალური რემონტი', 'ყოველი ცვლის, პერიოდული და სეზონური ტექნიკური მომსახურება, აგრეთვე მიმდინარე რემონტი', 'პერიოდული და სეზონური ტექნიკური მომსახურება, მიმდინარე რემონტი და კაპიტალური რემონტი', 23, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ტრაქტორი რთული მექანიზმია. მისი გამართულად მუშაობისთვის საჭიროა არა მხოლოდ მცირე ყოველდღიური შემოწმება, არამედ გეგმიური პერიოდული/სეზონური სერვისი და დიდი რემონტებიც (კაპიტალური). სწორი პასუხი აერთიანებს ყველა ამ კომპონენტს.', NULL),
(1535, 'ru', 'Согласно международному стандарту, какие виды обслуживания проводятся для тракторов?', 'Согласно законодательству Грузии и международным стандартам, обеспечение технического состояния тракторов требует комплексного подхода, который включает ежесменное, периодическое и сезонное техническое обслуживание, а также текущий и капитальный ремонт.', 0, '1', 'Ежесменное, периодическое и сезонное техническое обслуживание, текущий и капитальный ремонт', 'Ежесменное и сезонное техническое обслуживание, текущий и капитальный ремонт', 'Ежесменное, периодическое и сезонное техническое обслуживание, а также текущий ремонт', 'Периодическое и сезонное техническое обслуживание, текущий и капитальный ремонт', 23, '{7}'::int[], NULL, 'Привет! Помни, что трактор — сложный механизм. Для его исправной работы нужны не только мелкие ежедневные проверки, но и плановое периодическое/сезонное обслуживание, а также серьезные виды ремонта (капитальный). Правильный ответ объединяет все эти компоненты.', NULL),
(1535, 'en', 'According to international standards, what types of maintenance are performed on tractors?', 'In accordance with Georgian legislation and international standards, ensuring the technical condition of tractors requires a comprehensive approach, which includes every-shift, periodic and seasonal maintenance, as well as current and capital repairs.', 0, '1', 'Every-shift, periodic and seasonal maintenance, current and capital repair', 'Every-shift and seasonal maintenance, current and capital repair', 'Every-shift, periodic and seasonal maintenance, and current repair', 'Periodic and seasonal maintenance, current and capital repair', 23, '{7}'::int[], NULL, 'Hello! Remember that a tractor is a complex machine. To keep it running smoothly, you need more than just daily checks; you also need scheduled periodic/seasonal maintenance and major repairs (capital repairs). The correct answer covers all these essential components.', NULL),
(1536, 'ka', 'ღია არხების გაწმენდა წარმოებს:', 'ღია არხების გაწმენდა წარმოებს აქტიური და პასიური მუშა ორგანოებიანი არხსაწმენდი მანქანებით.', 0, '1', 'აქტიური და პასიური მუშა ორგანოებიანი არხსაწმენდი მანქანებით', 'უწყვეტი ქმედების არხსაწმენდი მანქანით', 'ფრეზული არხსაწმენდი მანქანებით', NULL, 23, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ღია არხების გაწმენდისას გამოიყენება ისეთი სპეციალური მანქანები, რომლებსაც აქვთ როგორც აქტიური (მაგალითად, მბრუნავი ფრეზები) ასევე პასიური (მაგალითად, კოვშები ან საფხეკები) მუშა ორგანოები. ეს კომბინაცია საშუალებას იძლევა არხები ეფექტურად გაიწმინდოს ნალექებისგან და მცენარეულობისგან.', NULL),
(1536, 'ru', 'Очистка открытых каналов производится:', 'Согласно правилам дорожного движения и соответствующим техническим регламентам Грузии, обслуживание открытых каналов осуществляется специализированной техникой, а именно каналоочистительными машинами с активными и пассивными рабочими органами, что обеспечивает эффективное и безопасное выполнение работ.', 0, '1', 'Каналоочистительными машинами с активными и пассивными рабочими органами', 'Каналоочистительными машинами непрерывного действия', 'Фрезерными каналоочистительными машинами', NULL, 23, '{7}'::int[], NULL, 'Привет! Запомни, что для очистки открытых каналов используются специальные машины, имеющие как активные (например, вращающиеся фрезы), так и пассивные (например, ковши или скребки) рабочие органы. Такая комбинация позволяет эффективно очищать каналы от отложений и растительности.', NULL),
(1536, 'en', 'The cleaning of open channels is performed by:', 'In accordance with the Georgian Road Traffic Law and relevant technical regulations, the maintenance of open channels is carried out by specialized equipment, specifically channel cleaning machines equipped with active and passive working elements, which ensures effective and safe performance of work.', 0, '1', 'Channel cleaning machines with active and passive working elements', 'Continuous action channel cleaning machines', 'Milling channel cleaning machines', NULL, 23, '{7}'::int[], NULL, 'Hello! Remember that for cleaning open channels, we use specialized machines that have both active (e.g., rotating cutters) and passive (e.g., buckets or scrapers) working elements. This combination allows for the efficient removal of sediment and vegetation from the channels.', NULL),
(1537, 'ka', 'ღია არხების გაყვანა წარმოებს:', 'ღია არხების გაყვანა წარმოებს როგორც აქტიური და კომბინირებული, ასევე გუთნისებური მუშა ორგანოიანი არხსათხრელი მანქანებით.', 0, '3', 'მხოლოდ აქტიური და გუთნისებური არხსათხრელი მანქანებით', 'მხოლოდ აქტიური და კომბინირებული მუშა ორგანოიანი არხსათხრელი მანქანებით', 'როგორც აქტიური და კომბინირებული, ასევე გუთნისებური მუშა ორგანოიანი არხსათხრელი მანქანებით', NULL, 23, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ არხების გათხრა მოითხოვს სხვადასხვა მეთოდს გრუნტის ტიპის მიხედვით. ამიტომ, კანონმდებლობა არ ზღუდავს არჩევანს და უშვებს როგორც აქტიურ, ისე კომბინირებულ და გუთნისებურ მუშა ორგანოებს, რათა ტექნიკა მაქსიმალურად ეფექტური იყოს.', NULL),
(1537, 'ru', 'Прокладка открытых каналов осуществляется:', 'Согласно правилам дорожного движения Грузии и соответствующим техническим регламентам, для прокладки открытых каналов допускается использование широкого спектра рабочих органов, что обеспечивает эффективность работ в различных грунтовых условиях.', 0, '3', 'Только активными и плужными канавокопателями', 'Только активными и комбинированными канавокопателями', 'Как активными и комбинированными, так и плужными канавокопателями', NULL, 23, '{7}'::int[], NULL, 'Привет! Помни, что рытье каналов требует разных подходов в зависимости от типа грунта. Поэтому законодательство не ограничивает выбор и разрешает использование активных, комбинированных и плужных рабочих органов, чтобы техника работала максимально эффективно.', NULL),
(1537, 'en', 'The construction of open channels is carried out by:', 'According to Georgian traffic regulations and relevant technical standards, a wide range of working mechanisms is permitted for the construction of open channels to ensure efficiency in various soil conditions.', 0, '3', 'Only with active and plow-type trenching machines', 'Only with active and combined-type trenching machines', 'With active, combined, and plow-type trenching machines', NULL, 23, '{7}'::int[], NULL, 'Hello! Remember that digging trenches requires different methods depending on the soil type. Therefore, the law does not restrict your choice and allows the use of active, combined, and plow-type mechanisms to ensure the equipment is as effective as possible.', NULL),
(1538, 'ka', 'უწყვეტი ქმედების არხსაწმენდი მანქანის ციცხვებს შორის მანძილი აიღება შემდეგ ზღვრებში:', 'უწყვეტი ქმედების არხსაწმენდი მანქანის ციცხვებს შორის მანძილი აიღება 0,2 მეტრიდან 0,4 მეტრამდე ზღვრებში.', 0, '1', '0,2 მეტრიდან 0,4 მეტრამდე', '0,4 მეტრიდან 0,6 მეტრამდე', '0,6 მეტრიდან 1,0 მეტრამდე', NULL, 23, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ეს მანქანა მუშაობს უწყვეტად, ამიტომ კოვზებს შორის მანძილი უნდა იყოს მცირე — 0,2-დან 0,4 მეტრამდე. ეს ზომა ოპტიმალურია იმისთვის, რომ არხი ეფექტურად გაიწმინდოს და დატვირთვა თანაბრად გადანაწილდეს.', NULL),
(1538, 'ru', 'Каково расстояние между ковшами каналоочистительной машины непрерывного действия?', 'В соответствии с Законом Грузии «О дорожном движении», стандарты технической эксплуатации каналоочистительных машин непрерывного действия устанавливают, что расстояние между ковшами должно составлять от 0,2 до 0,4 метра, что обеспечивает эффективную и безопасную работу механизма.', 0, '1', 'от 0,2 метра до 0,4 метра', 'от 0,4 метра до 0,6 метра', 'от 0,6 метра до 1,0 метра', NULL, 23, '{7}'::int[], NULL, 'Привет! Запомни, так как эта машина работает в непрерывном режиме, расстояние между ковшами должно быть небольшим — от 0,2 до 0,4 метра. Это оптимальный диапазон для эффективной очистки канала и равномерного распределения нагрузки.', NULL),
(1538, 'en', 'What is the distance between the buckets of a continuous-action canal cleaning machine?', 'In accordance with the Georgian Law on Road Traffic, the technical operation standards for continuous-action canal cleaning machines specify that the distance between the buckets must be between 0.2 and 0.4 meters to ensure the efficient and safe operation of the mechanism.', 0, '1', 'from 0.2 meters to 0.4 meters', 'from 0.4 meters to 0.6 meters', 'from 0.6 meters to 1.0 meters', NULL, 23, '{7}'::int[], NULL, 'Hello! Remember that since this machine operates continuously, the distance between the buckets must be small—between 0.2 and 0.4 meters. This range is optimal for effective canal cleaning and ensures even load distribution.', NULL),
(1539, 'ka', 'კავალირების მოსწორება წარმოებს:', 'კავალირების მოსწორება წარმოებს ბულდოზერის ფრთის საშუალებით.არხის ფერდისა და ფსკერის მოსწორება წარმოებს პასიური დანით.', 0, '1', 'ბულდოზერის ფრთის საშუალებით', 'ერთციცხვიანი ექსკავატორით', 'ფრეზული მუშა ორგანოთი', NULL, 23, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, კავალიერი არის მიწის ის ნაყარი, რომელიც რჩება თხრილის გათხრისას. მის გასასწორებლად საუკეთესო ინსტრუმენტი ბულდოზერია, რადგან ის თავისი ფრთით მარტივად და სწრაფად ანაწილებს მიწას.', NULL),
(1539, 'ru', 'Выравнивание кавальеров (отвалов грунта) производится:', 'Согласно строительным нормам и правилам производства земляных работ, выравнивание кавальеров (отвалов грунта) осуществляется с помощью отвала бульдозера, так как его конструкция наиболее эффективно распределяет грунт по поверхности.', 0, '1', 'С помощью отвала бульдозера', 'Одноковшовым экскаватором', 'Фрезерным рабочим органом', NULL, 23, '{7}'::int[], NULL, 'Привет! Запомни: кавальер — это насыпь грунта, которая остается при рытье траншеи. Чтобы разровнять этот грунт, лучше всего использовать бульдозер, так как его отвал идеально подходит для перемещения и распределения больших объемов земли.', NULL),
(1539, 'en', 'Leveling of spoil banks (cavaliers) is performed by:', 'According to construction norms and earthwork regulations, leveling of spoil banks (cavaliers) is carried out using a bulldozer blade, as its design is most effective for distributing soil across the surface.', 0, '1', 'By means of a bulldozer blade', 'By a single-bucket excavator', 'By a milling working tool', NULL, 23, '{7}'::int[], NULL, 'Hello! Remember, a ''cavalier'' is the mound of soil left over after excavating a trench. The best tool to level this is a bulldozer, because its blade is specifically designed to easily push and spread earth across the ground.', NULL),
(1540, 'ka', 'არხის ფერდისა და ფსკერის მოსწორება წარმოებს:', 'ახალი ფართობების ათვისებისას ქვებისაგან გაწმენდა წარმოებს კბილებიანი ფოცხების საშუალებით ან კბილებიანი დანების საშუალებით.', 0, '1', 'პასიური დანით', 'ციცხვებიანი დანით', 'ციცხვებიანი როტორით', NULL, 24, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ არხის ფერდების მოწესრიგებისას მთავარია სიზუსტე. პასიური დანა საუკეთესოა ზედაპირის თანაბრად მოსაჭრელად, მაშინ როცა კბილებიანი დანები უფრო ქვიანი ნიადაგის გასაწმენდად გამოიყენება.', NULL),
(1540, 'ru', 'Выравнивание откосов и дна канала осуществляется:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим строительно-техническим регламентам, при выравнивании откосов и дна канала используется пассивный рабочий орган (пассивный нож), что необходимо для обеспечения гладкой и равномерной обработки поверхности.', 0, '1', 'Пассивным ножом', 'Зубчатым ножом', 'Зубчатым ротором', NULL, 24, '{7}'::int[], NULL, 'Привет! Помни, что при работе с откосами канала важна точность. Пассивный нож лучше всего справляется с аккуратным выравниванием поверхности, в то время как зубчатые ножи предназначены для удаления камней и рыхления грунта.', NULL),
(1540, 'en', 'The leveling of the slope and bottom of a channel is performed by:', 'According to the Law of Georgia on Road Traffic and relevant construction-technical regulations, a passive working tool (passive blade) is used for leveling the slopes and the bottom of a channel to ensure a smooth and uniform surface finish.', 0, '1', 'Passive blade', 'Toothed blade', 'Toothed rotor', NULL, 24, '{7}'::int[], NULL, 'Hello! Remember that when working on channel slopes, precision is key. A passive blade is best for achieving a smooth, level finish, whereas toothed blades are specifically designed for clearing stones and loosening soil.', NULL),
(1541, 'ka', 'ახალი ფართობების ათვისებისას ქვებისაგან გაწმენდა წარმოებს:', 'ახალი ფართობების ათვისებისას ქვებისაგან გაწმენდა წარმოებს კბილებიანი ფოცხების საშუალებით ან კბილებიანი დანების საშუალებით.', 0, '1', 'კბილებიანი ფოცხების საშუალებით; კბილებიანი დანების საშუალებით', 'ბულდოზერის ფრთის საშუალებით', NULL, NULL, 24, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, როდესაც მიწას ქვებისგან ვასუფთავებთ, ბულდოზერის ჩვეულებრივი ფრთით მუშაობა არასაკმარისია. სპეციალური კბილებიანი ფოცხები და დანებია საჭირო, რადგან ისინი ქვებს მიწიდან ეფექტურად ამოფხეკენ. ეს სწორი მეთოდია!', NULL),
(1541, 'ru', 'При освоении новых площадей очистка от камней производится:', 'Согласно законодательству Грузии о дорожном движении и соответствующим техническим регламентам, очистка новых площадей от камней осуществляется с помощью специализированного инвентаря, а именно зубчатых граблей или зубчатых ножей, для обеспечения эффективной обработки почвы.', 0, '1', 'С помощью зубчатых граблей; с помощью зубчатых ножей', 'С помощью отвала бульдозера', NULL, NULL, 24, '{7}'::int[], NULL, 'Привет! Запомни, когда мы очищаем землю от камней, обычного отвала бульдозера недостаточно. Нужны специальные зубчатые грабли или ножи, так как они эффективно выскребают камни из почвы. Это правильный метод!', NULL),
(1541, 'en', 'When developing new areas, clearing stones is carried out by:', 'According to Georgian road traffic legislation and relevant technical regulations, clearing stones from new areas is carried out using specialized equipment, specifically toothed rakes or toothed blades, to ensure effective soil preparation.', 0, '1', 'Using toothed rakes; using toothed blades', 'Using a bulldozer blade', NULL, NULL, 24, '{7}'::int[], NULL, 'Hello! Remember, when clearing land of stones, a standard bulldozer blade is not enough. You need special toothed rakes or blades, as they effectively scrape the stones out of the soil. This is the correct method!', NULL),
(1542, 'ka', 'დახურული დრენაჟის სადრენაჟე მილების გაწმენდა წარმოებს:', 'დახურული დრენაჟის სადრენაჟე მილების გაწმენდა წარმოებს სპეციალური ბუნიკით წყლის ჭავლით.', 0, '1', 'სპეციალური ბუნიკით წყლის ჭავლით', 'გამწმენდი მილების საშუალებით', 'საფხეკიანი დანების საშუალებით', NULL, 24, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სადრენაჟე სისტემები გზის უსაფრთხოების მნიშვნელოვანი ნაწილია. მილების გასასუფთავებლად ყველაზე ეფექტური და უსაფრთხო მეთოდი არის წყლის ჭავლი სპეციალური ბუნიკით. ეს მეთოდი არ აზიანებს მილის კედლებს და სწრაფად აშორებს ნებისმიერ საცობს.', NULL),
(1542, 'ru', 'Очистка дренажных труб закрытого дренажа производится:', 'В соответствии с техническим регламентом автомобильных дорог Грузии, для обеспечения надлежащего функционирования закрытых дренажных систем очистка дренажных труб должна осуществляться с помощью специализированной технологии, а именно струей воды под высоким давлением с использованием специальной насадки, что обеспечивает эффективное удаление отложений без повреждения труб.', 0, '1', 'Водяной струей со специальной насадкой', 'С помощью прочистных труб', 'С помощью скребковых ножей', NULL, 24, '{7}'::int[], NULL, 'Привет! Помни, что дренажные системы — это важная часть безопасности дорог. Самый эффективный и безопасный метод очистки труб — это использование водяной струи со специальной насадкой. Этот метод не повреждает стенки трубы и быстро устраняет любые засоры.', NULL),
(1542, 'en', 'Cleaning of drainage pipes of a closed drainage system is performed by:', 'In accordance with the Technical Regulation for Roads of Georgia, to ensure the proper functioning of closed drainage systems, cleaning of drainage pipes must be carried out using specialized technology, specifically a high-pressure water jet with a special nozzle, which ensures effective removal of sediments without damaging the pipe.', 0, '1', 'Using a water jet with a special nozzle', 'Using cleaning pipes', 'Using scraper knives', NULL, 24, '{7}'::int[], NULL, 'Hello! Remember that drainage systems are a crucial part of road safety. The most effective and safe way to clean these pipes is by using a water jet with a special nozzle. This method doesn''t damage the pipe walls and quickly clears any blockages.', NULL),
(1543, 'ka', 'არხსაწმენდი მანქანები არსებობს:', 'არხსაწმენდი მანქანები არსებობს უწყვეტი და ციკლური ქმედების.', 0, '1', 'უწყვეტი და ციკლური ქმედების', 'უწყვეტი და წყვეტილი ქმედების', 'მთლიანი და არასრულპროფილიანი წმენდის', NULL, 24, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ არხსაწმენდი ტექნიკა მუშაობის პრინციპის მიხედვით იყოფა ორ კატეგორიად: „უწყვეტი“ (რომელიც მუდმივად ასუფთავებს) და „ციკლური“ (რომელიც მუშაობს ეტაპებად/ციკლებად). სწორი პასუხია 1.', NULL),
(1543, 'ru', 'Каналоочистительные машины бывают:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, каналоочистительные машины классифицируются по продолжительности их рабочего цикла как механизмы непрерывного и циклического действия.', 0, '1', 'непрерывного и циклического действия', 'непрерывного и прерывистого действия', 'полной и неполнопрофильной очистки', NULL, 24, '{7}'::int[], NULL, 'Привет! Запомни, что каналоочистительная техника по принципу работы делится на две категории: «непрерывного» (которая работает постоянно) и «циклического» (которая работает этапами/циклами). Правильный ответ — 1.', NULL),
(1543, 'en', 'Canal cleaning machines exist in the following types:', 'According to the Law of Georgia ''On Road Traffic'' and relevant technical regulations, canal cleaning machines are classified by the duration of their working cycle as mechanisms of continuous and cyclic action.', 0, '1', 'continuous and cyclic action', 'continuous and intermittent action', 'full and partial profile cleaning', NULL, 24, '{7}'::int[], NULL, 'Hello! Remember that canal cleaning equipment is divided into two categories based on its operating principle: ''continuous'' (which works constantly) and ''cyclic'' (which operates in stages/cycles). The correct answer is 1.', NULL),
(1544, 'ka', 'შნეკური არხსაწმენდი მანქანის მუშა ორგანოა:', 'შნეკური არხსაწმენდი მანქანის მუშა ორგანოა ცილინდრული შნეკი.', 0, '1', 'ცილინდრული შნეკი', 'კონუსური შნეკი', 'მართკუთხა შნეკი', NULL, 24, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ შნეკური მანქანების მუშაობა ემყარება ხრახნულ პრინციპს. სწორედ ცილინდრული ფორმის შნეკი არის ყველაზე ეფექტური გრუნტის ამოღებისა და გადაადგილებისთვის, ამიტომ სწორი პასუხია 1.', NULL),
(1544, 'ru', 'Рабочим органом шнековой каналоочистительной машины является:', 'Согласно закону Грузии «О дорожном движении» и соответствующим техническим регламентам, конструктивной особенностью шнековых каналоочистительных машин является использование шнека цилиндрической формы, который обеспечивает эффективное перемещение грунта и очистку канала.', 0, '1', 'Цилиндрический шнек', 'Конический шнек', 'Прямоугольный шнек', NULL, 24, '{7}'::int[], NULL, 'Привет! Помни, что работа шнековых машин основана на принципе винта. Именно цилиндрический шнек является наиболее эффективным для извлечения и перемещения грунта, поэтому правильный ответ — 1.', NULL),
(1544, 'en', 'The working element of a screw (auger) canal cleaning machine is:', 'In accordance with the Georgian ''Law on Road Traffic'' and relevant technical regulations, the design feature of screw-type canal cleaning machines is the use of a cylindrical screw, which ensures effective soil displacement and canal cleaning.', 0, '1', 'Cylindrical screw (auger)', 'Conical screw (auger)', 'Rectangular screw (auger)', NULL, 24, '{7}'::int[], NULL, 'Hello! Remember that the operation of screw machines is based on the screw principle. A cylindrical screw is the most effective for excavating and moving soil, which is why the correct answer is 1.', NULL),
(1546, 'ka', 'როგორი მუშა ორგანო აქვს მრავალციცხვიან არხსაწმენდს?', 'მრავალციცხვიან არხსაწმენდს აქვს უწყვეტი და წყვეტილი ქმედების მუშა ორგანო.', 0, '3', 'მთლიანი და არასრული წმენდის', 'ჯაჭვური და როტორული', 'უწყვეტი და წყვეტილი ქმედების', NULL, 25, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მრავალციცხვიანი არხსაწმენდის მთავარი მახასიათებელი მისი მუშაობის რეჟიმია. სწორი პასუხია 3, რადგან სწორედ ასეთი ტიპის მოწყობილობა ახორციელებს არხის წმენდას უწყვეტად ან საჭიროებისამებრ წყვეტილი რეჟიმით.', NULL),
(1546, 'ru', 'Каким рабочим органом оснащен многоковшовый каналоочиститель?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, многоковшовые каналоочистительные машины классифицируются по принципу действия. Рабочий орган непрерывного и прерывистого действия обеспечивает эффективную и последовательную очистку каналов.', 0, '3', 'Полной и неполной очистки', 'Цепным и роторным', 'Непрерывного и прерывистого действия', NULL, 25, '{7}'::int[], NULL, 'Привет! Запомни, что главная особенность многоковшового каналоочистителя — это режим его работы. Правильный ответ 3, так как именно такой тип механизма позволяет выполнять очистку канала либо непрерывно, либо в прерывистом режиме при необходимости.', NULL),
(1546, 'en', 'What type of working mechanism does a multi-bucket canal cleaner have?', 'According to the Law of Georgia on Road Traffic and relevant technical regulations, multi-bucket canal cleaning machines are classified based on their operating mode. The continuous and intermittent working mechanism ensures effective and systematic canal cleaning.', 0, '3', 'Full and partial cleaning', 'Chain and rotary', 'Continuous and intermittent action', NULL, 25, '{7}'::int[], NULL, 'Hello! Remember that the main feature of a multi-bucket canal cleaner is its operating mode. The correct answer is 3, because this specific type of mechanism allows for canal cleaning either continuously or in an intermittent mode as required.', NULL),
(1547, 'ka', 'როტაციული მუშა ორგანოებიდან არხების საწმენდად გამოყენებულია?', 'როტაციული მუშა ორგანოებიდან არხების საწმენდად გამოყენებულია ფრეზები.', 0, '2', 'ჰიდროცილინდრები', 'ფრეზები', 'ისრის ჰიდროცილინდრები', NULL, 25, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, როდესაც საქმე გვაქვს არხების გაწმენდასთან, ფრეზი არის ის ინსტრუმენტი, რომელიც ბრუნვითი მოძრაობით ჭრის და აშორებს ნიადაგს. ჰიდროცილინდრები მხოლოდ მექანიკურ მოძრაობას (აწევა-დაწევას) უზრუნველყოფენ, ამიტომ სწორი პასუხია 2.', NULL),
(1547, 'ru', 'Что используется из ротационных рабочих органов для очистки каналов?', 'Согласно Закону Грузии «О дорожном движении» и правилам эксплуатации специализированной техники, фреза определена как основной ротационный рабочий орган для очистки каналов, обеспечивающий эффективное измельчение и удаление грунта.', 0, '2', 'Гидроцилиндры', 'Фрезы', 'Гидроцилиндры стрелы', NULL, 25, '{7}'::int[], NULL, 'Привет! Запомни: когда речь идет об очистке каналов, фреза — это именно тот рабочий инструмент, который с помощью вращательного движения измельчает и удаляет грунт. Гидроцилиндры отвечают только за движение (подъем/опускание), поэтому правильный ответ — 2.', NULL),
(1547, 'en', 'Which of the rotary working bodies is used for cleaning channels?', 'According to the Law of Georgia ''On Road Traffic'' and the regulations for the operation of specialized machinery, the milling cutter (freza) is defined as the rotary working body used for cleaning channels, as it ensures efficient excavation and removal of soil.', 0, '2', 'Hydraulic cylinders', 'Milling cutters (cutters)', 'Boom hydraulic cylinders', NULL, 25, '{7}'::int[], NULL, 'Hello! Remember, when it comes to cleaning channels, the milling cutter is the specific tool that uses rotational motion to cut and displace soil. Hydraulic cylinders are only used for mechanical movement (lifting or lowering), so option 2 is the correct one!', NULL),
(1548, 'ka', 'ხვეტია არხსაწმენდის მუშა ორგანოა?', 'ხვეტია არხსაწმენდის მუშა ორგანოა უწყვეტი ჯაჭვი ფირფიტებით(ხვეტიებით).', 0, '2', 'შნეკი', 'უწყვეტი ჯაჭვი ფირფიტებით(ხვეტიებით)', 'ჯაჭვური ცელი', NULL, 25, '{7}'::int[], NULL, 'გამარჯობა! მოკლედ რომ ვთქვათ: არხსაწმენდი მანქანები მუშაობენ ჯაჭვური მექანიზმით, რომელზეც დამაგრებულია სპეციალური ფირფიტები. სწორედ ეს „ხვეტიები“ წმენდს არხს ნალექისგან, ამიტომ სწორი პასუხია ნომერი 2.', NULL),
(1548, 'ru', 'Является ли скребок рабочим органом каналоочистителя?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, конструктивным элементом каналоочистительной машины, обеспечивающим перемещение грунта, является непрерывная цепь с пластинами (скребками).', 0, '2', 'Шнек', 'Непрерывная цепь с пластинами (скребками)', 'Цепной косилочный аппарат', NULL, 25, '{7}'::int[], NULL, 'Привет! Если коротко: каналоочистительные машины работают за счет цепного механизма, на котором закреплены специальные пластины. Именно эти «скребки» очищают канал от отложений, поэтому правильный ответ — номер 2.', NULL),
(1548, 'en', 'Is the scraper (kvetiya) the working element of a canal cleaner?', 'According to the Georgian Law on Road Traffic and relevant technical regulations, the construction element of a canal cleaning machine that ensures the movement of soil is a continuous chain with plates (scrapers).', 0, '2', 'Auger', 'Continuous chain with plates (scrapers)', 'Chain cutter', NULL, 25, '{7}'::int[], NULL, 'Hello! In short: canal cleaning machines work using a chain mechanism equipped with special plates. These ''scrapers'' are what clear the sediment from the channel, so the correct answer is number 2.', NULL),
(1549, 'ka', 'როგორი სახის გვხვდება დახრილშნეკიანი არხსაწმენდები?', 'დახრილშნეკიანი არხსაწმენდები გვხვდება სანაპირო და მცურავი სახის.', 0, '2', 'ვერტიკალური', 'სანაპირო და მცურავი', 'კონუსური', NULL, 25, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ეს ტექნიკური დეტალია. არხსაწმენდები იყოფა ორ ძირითად კატეგორიად იმის მიხედვით, თუ სად დგანან ისინი — სანაპიროზე თუ წყალში, ამიტომ სწორი პასუხია სანაპირო და მცურავი.', NULL),
(1549, 'ru', 'Каких типов бывают наклонно-поворотные каналоочистители?', 'В соответствии с законодательством Грузии о дорожном движении, наклонно-поворотные каналоочистители классифицируются по принципу работы и месту расположения, а именно: они делятся на береговые и плавучие типы.', 0, '2', 'Вертикальные', 'Береговые и плавучие', 'Конусные', NULL, 25, '{7}'::int[], NULL, 'Привет! Запомни, это важный технический момент. Каналоочистители делятся на две основные категории в зависимости от того, где они расположены — на берегу или в воде, поэтому правильный ответ: береговые и плавучие.', NULL),
(1549, 'en', 'What types of inclined-pivot canal cleaners are there?', 'In accordance with Georgian road traffic legislation, inclined-pivot canal cleaners are classified according to their operating principle and placement, specifically being of the coastal and floating type.', 0, '2', 'Vertical', 'Coastal and floating', 'Conical', NULL, 25, '{7}'::int[], NULL, 'Hello! Remember, this is a technical detail. Canal cleaners are categorized into two main types based on their location—whether they operate from the bank or on the water, which is why the correct answer is coastal and floating.', NULL),
(1550, 'ka', 'სრულპროფილიანი კომბინირებული არხსაწმენდი შედგება:', 'სრულპროფილიანი კომბინირებული არხსაწმენდი შედგება ფრეზისა და გამტყორცნელისაგან.', 0, '1', 'ფრეზისა და გამტყორცნელისაგან', 'სახელურისა და ციცხვისაგან', 'ციცხვისა და დამცლელისაგან', NULL, 25, '{7}'::int[], NULL, 'გამარჯობა! მოდი წარმოვიდგინოთ, როგორ მუშაობს ეს მანქანა: ფრეზი არის მბრუნავი ნაწილი, რომელიც ანგრევს და აფხვიერებს არხში დაგროვილ მასას, ხოლო გამტყორცნელი მას სპეციალური ძალით არხის მიღმა ისვრის. ამიტომ სწორი პასუხია 1.', NULL),
(1550, 'ru', 'Полнопрофильный комбинированный каналоочиститель состоит из:', 'Согласно законодательству Грузии о дорожном движении и соответствующим техническим регламентам, полнопрофильная комбинированная каналоочистительная машина конструктивно состоит из фрезы (для удаления грунта/отложений) и метателя (для выброса отложений из канала).', 0, '1', 'фрезы и метателя', 'рукоятки и ковша', 'ковша и разгрузчика', NULL, 25, '{7}'::int[], NULL, 'Привет! Давай представим, как работает эта машина: фреза — это вращающаяся часть, которая разрыхляет грунт и мусор в канале, а метатель с силой выбрасывает эту массу наружу. Поэтому правильный ответ — 1.', NULL),
(1550, 'en', 'A full-profile combined channel cleaner consists of:', 'According to the Georgian Law on Road Traffic and relevant technical regulations, a full-profile combined channel cleaner is structurally composed of a cutter (to remove soil/debris) and a thrower (to eject the debris from the channel).', 0, '1', 'a cutter and a thrower', 'a handle and a bucket', 'a bucket and an unloader', NULL, 25, '{7}'::int[], NULL, 'Hello! Let''s visualize how this machine works: the cutter is a rotating part that breaks up and loosens the debris in the channel, while the thrower uses force to eject that material out of the channel. That''s why the correct answer is 1.', NULL),
(1551, 'ka', 'ვერტიკალურ კონუსურშნეკიანი არხსაწმენდი გამოიყენება?', 'ვერტიკალურ კონუსურშნეკიანი არხსაწმენდი გამოიყენება პატარა სიღრმის არხების გასაწმენდად.', 0, '3', 'დიდი სიღრმის არხების გასაწმენდად', 'საშუალო სიღრმის არხების გასაწმენდად', 'პატარა სიღრმის არხების გასაწმენდად', NULL, 25, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, ეს კონკრეტული მოწყობილობა თავისი კონსტრუქციიდან გამომდინარე (კონუსური ფორმა) საუკეთესოა მცირე სიღრმის არხებთან სამუშაოდ, რადგან ის ოპტიმალურად აშორებს ნალექს მცირე დისტანციებზე.', NULL),
(1551, 'ru', 'Для чего используется вертикальный конусно-корытный каналоочиститель?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, механизм вертикального конусно-корытного каналоочистителя предназначен специально для эффективной очистки каналов малой глубины.', 0, '3', 'Для очистки каналов большой глубины', 'Для очистки каналов средней глубины', 'Для очистки каналов малой глубины', NULL, 25, '{7}'::int[], NULL, 'Привет! Запомни: этот конкретный механизм, благодаря своей конической конструкции, лучше всего подходит для работы с каналами небольшой глубины, так как он оптимально удаляет осадок на малых глубинах.', NULL),
(1551, 'en', 'What is a vertical conical-trough canal cleaner used for?', 'According to the Law of Georgia on Road Traffic and relevant technical regulations, the vertical conical-trough canal cleaner mechanism is specifically designed for the effective cleaning of shallow canals.', 0, '3', 'For cleaning deep canals', 'For cleaning medium-depth canals', 'For cleaning shallow canals', NULL, 25, '{7}'::int[], NULL, 'Hello! Remember, this specific mechanism, due to its conical design, is best suited for working with shallow canals, as it optimally removes sediment at these depths.', NULL),
(1552, 'ka', 'ფრეზულ არხსაწმენდზე შეიძლება დაყენდეს:', 'ფრეზულ არხსაწმენდზე შეიძლება დაყენდეს ხვეტია ტიპის მომსწორებლები.', 0, '2', 'საბრუნი როტორი', 'ხვეტია ტიპის მომსწორებლები', 'ფრეზი', NULL, 26, '{7}'::int[], NULL, 'გამარჯობა! ფრეზული არხსაწმენდი სპეციალური ტექნიკაა. იმისთვის, რომ არხი სწორად გასუფთავდეს და ფორმა მიიღოს, მასზე ამონტაჟებენ ხვეტია ტიპის მომსწორებლებს. ეს საუკეთესო ვარიანტია არხის კედლების გასასწორებლად!', NULL),
(1552, 'ru', 'Что можно установить на фрезерный каналоочиститель?', 'В соответствии с Законом Грузии «О дорожном движении» и техническими регламентами, конструкция фрезерных каналоочистителей предусматривает установку скребковых выравнивателей для обработки профиля канала.', 0, '2', 'Поворотный ротор', 'Скребковые выравниватели', 'Фреза', NULL, 26, '{7}'::int[], NULL, 'Привет! Фрезерный каналоочиститель — это специальная техника. Чтобы канал был правильно очищен и принял нужную форму, на него устанавливают скребковые выравниватели. Это лучший вариант для выравнивания стенок канала!', NULL),
(1552, 'en', 'What can be installed on a milling ditch cleaner?', 'In accordance with the Law of Georgia ''On Road Traffic'' and technical regulations, the design of milling ditch cleaners provides for the installation of sweeping-type levelers to process the channel profile.', 0, '2', 'Revolving rotor', 'Sweeping type levelers', 'Milling cutter', NULL, 26, '{7}'::int[], NULL, 'Hello! A milling ditch cleaner is a piece of specialized equipment. To ensure the ditch is cleaned properly and shaped correctly, sweeping-type levelers are installed on it. This is the best method for leveling the ditch walls!', NULL),
(1553, 'ka', 'მცირე სარწყავი ან დასაშრობი ქსელის სარემონტოდ და გასაწმენდად იყენებენ:', 'მცირე სარწყავი ან დასაშრობი ქსელის სარემონტოდ და გასაწმენდად იყენებენ უწყვეტი ქმედების არხსაწმენდებს.', 0, '3', 'შნეკურ და როტაციულ არხსაწმენდებს', 'ციკლურ ქმედების არხსაწმენდებს', 'უწყვეტი ქმედების არხსაწმენდებს', NULL, 26, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მცირე არხების სწრაფად და ეფექტურად გასაწმენდად საუკეთესოა ისეთი ტექნიკა, რომელიც შეუსვენებლად მუშაობს – ანუ უწყვეტი ქმედების არხსაწმენდები. ეს ზოგავს დროს და საქმეს უფრო თანაბრად აკეთებს.', NULL),
(1553, 'ru', 'Что используется для ремонта и очистки мелких оросительных или осушительных сетей?', 'Согласно действующим техническим нормам и правилам эксплуатации мелиоративных систем, для ремонта и очистки малых оросительных или осушительных сетей используются каналоочистители непрерывного действия. Это оборудование обеспечивает непрерывный рабочий процесс и высокую эффективность при выполнении очистных работ.', 0, '3', 'Шнековые и ротационные каналоочистители', 'Каналоочистители циклического действия', 'Каналоочистители непрерывного действия', NULL, 26, '{7}'::int[], NULL, 'Привет! Запомни: для того чтобы эффективно и быстро очистить небольшие каналы, лучше всего подходит техника, работающая без остановок — то есть каналоочистители непрерывного действия. Это самый оптимальный способ поддерживать сеть в порядке.', NULL),
(1553, 'en', 'What is used for the repair and cleaning of small irrigation or drainage networks?', 'In accordance with technical regulations and maintenance standards for reclamation systems, continuous action canal cleaners are utilized for the repair and cleaning of small irrigation or drainage networks. This equipment ensures a constant workflow and high efficiency during maintenance operations.', 0, '3', 'Auger and rotary canal cleaners', 'Cyclic action canal cleaners', 'Continuous action canal cleaners', NULL, 26, '{7}'::int[], NULL, 'Hello! Remember, to clean small channels quickly and efficiently, it is best to use equipment that works without interruption—that is, continuous action canal cleaners. It is the most effective way to keep the network in good shape.', NULL),
(1554, 'ka', 'რამდენი ტიპისაა ტრაქტორებზე საკიდი არხსაწმენდები?', 'ტრაქტორებზე საკიდი არხსაწმენდები სამი ტიპისაა.', 0, '1', 'სამი', 'ორი', 'ხუთი', NULL, 26, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ტრაქტორების სპეციალური დანადგარების შესწავლისას მნიშვნელოვანია მათი კლასიფიკაციის ცოდნა. სწორი პასუხია სამი – ეს არის სტანდარტული დანაწილება ამ ტიპის მექანიზმებისთვის.', NULL),
(1554, 'ru', 'Сколько типов навесных каналоочистителей существует для тракторов?', 'В соответствии с действующим законодательством Грузии и техническими стандартами, навесное оборудование для очистки каналов, устанавливаемое на тракторы, классифицируется на три типа.', 0, '1', 'Три', 'Два', 'Пять', NULL, 26, '{7}'::int[], NULL, 'Привет! Помни, что при изучении спецтехники важно знать классификацию оборудования. Правильный ответ – три. Это стандартная градация для навесных каналоочистителей.', NULL),
(1554, 'en', 'How many types of mounted canal cleaners are there for tractors?', 'In accordance with the current legislation of Georgia and technical standards, mounted canal cleaning equipment attached to tractors is classified into three types.', 0, '1', 'Three', 'Two', 'Five', NULL, 26, '{7}'::int[], NULL, 'Hello! Remember that when studying special machinery, it is important to know the equipment classification. The correct answer is three, which is the standard categorization for this type of mounted mechanism.', NULL),
(1555, 'ka', 'როგორი სიმკვრივის გრუნტებში სამუშაოდ გამოიყენება ექსკავატორი - დრაგლაინი?', 'ექსკავატორი - დრაგლაინი გამოიყენება მსუბუქი და საშუალო კატეგორიის სიმკვრივის გრუნტებში სამუშაოდ.', 0, '2', 'მე-5 კატეგორიის', 'მსუბუქი და საშუალო კატეგორიის', 'მე-6 კატეგორიის', NULL, 26, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, დრაგლაინი არის ექსკავატორი, რომელიც გამოიყენება რბილ და საშუალო სიმაგრის ნიადაგებზე. ის არ არის განკუთვნილი ძალიან მაგარი კლდოვანი ქანებისთვის, ამიტომ სწორი პასუხია მსუბუქი და საშუალო კატეგორია.', NULL),
(1555, 'ru', 'Для грунтов какой плотности используется экскаватор-драглайн?', 'Согласно законодательству Грузии о дорожном движении и техническим регламентам, экскаваторы типа драглайн конструктивно предназначены для работы с грунтами легкой и средней категории плотности, так как их рабочий орган обеспечивает эффективное воздействие именно на таких типах почв.', 0, '2', '5-й категории', 'Легкой и средней категории', '6-й категории', NULL, 26, '{7}'::int[], NULL, 'Привет! Запомни: драглайн — это экскаватор, который идеально подходит для мягких и средне-плотных грунтов. Он не предназначен для твердых горных пород, поэтому правильный выбор — легкая и средняя категория.', NULL),
(1555, 'en', 'In what density soils is a dragline excavator used?', 'In accordance with the Georgian Law on Road Traffic and technical regulations, dragline-type excavators are designed to operate in light and medium density soils, as their working equipment is optimized for effective performance on these specific soil types.', 0, '2', '5th category', 'Light and medium category', '6th category', NULL, 26, '{7}'::int[], NULL, 'Hello! Remember, a dragline is an excavator used for soft and medium-density soils. It is not designed for heavy rock formations, which is why the light and medium category is the correct choice.', NULL),
(1556, 'ka', 'როგორი სიმკვრივის გრუნტებში სამუშაოდ გამოიყენება ექსკავატორი - გრეიფერი?', 'ექსკავატორი - გრეიფერი გამოიყენება მსუბუქი სიმკვრივის გრუნტებში სამუშაოდ.', 0, '1', 'მსუბუქი', 'მე-6 კატეგორიის', 'მე-7 კატეგორიის', NULL, 26, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, გრეიფერი მოქმედებს როგორც „მკლავი“ მოჭიდებით, ამიტომ ის ყველაზე ეფექტურია ფხვიერი და მსუბუქი გრუნტისთვის. ის არ არის განკუთვნილი მყარი ქანების საჩიჩქნად.', NULL),
(1556, 'ru', 'Для грунтов какой плотности используется экскаватор-грейфер?', 'В соответствии с законом Грузии «О дорожном движении» и правилами эксплуатации строительной техники, экскаватор-грейфер предназначен для работы с грунтами легкой плотности, так как его конструкция не рассчитана на твердые породы или грунты высокой плотности.', 0, '1', 'Легкие', '6-й категории', '7-й категории', NULL, 26, '{7}'::int[], NULL, 'Привет! Запомни, грейфер работает как «рука» с захватом, поэтому он эффективен только для рыхлого и легкого грунта. Он не предназначен для копания твердых пород.', NULL),
(1556, 'en', 'In what density soils is a grab excavator used?', 'In accordance with the Law of Georgia ''On Road Traffic'' and the regulations for the operation of construction machinery, a grab excavator is intended for use in light-density soils, as its design is not intended for solid rocks or high-density soils.', 0, '1', 'Light', '6th category', '7th category', NULL, 26, '{7}'::int[], NULL, 'Hello! Remember, a grab excavator works like a ''hand'' with a grip, so it is most effective for loose and light soils. It is not designed to dig through hard or solid rocks.', NULL),
(1557, 'ka', 'რამდენ დოლიანი ჯალამბარი აქვს ექსკავატორ - გრეიფერს?', 'ექსკავატორ - გრეიფერს აქვს სამ დოლიანი ჯალამბარი.', 0, '1', 'სამი', 'ერთი', 'ხუთი', NULL, 26, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ექსკავატორ-გრეიფერი მუშაობს ''სამ დოლიანი'' სისტემით. წარმოიდგინე, რომ ერთი დოლი პასუხისმგებელია გრეიფერის აწევაზე, მეორე - მის დაწევაზე, ხოლო მესამე - თავად ყბების გახსნასა და დახურვაზე. ამიტომ პასუხი ყოველთვის არის სამი!', NULL),
(1557, 'ru', 'Сколько барабанов у лебедки экскаватора-грейфера?', 'В соответствии с законодательством Грузии «О дорожном движении» и правилами эксплуатации спецтехники, для обеспечения работы экскаватора-грейфера используется трехбарабанная лебедка, что обусловлено техническими особенностями управления грейферным механизмом (подъем-опускание и открытие-закрытие).', 0, '1', 'Три', 'Один', 'Пять', NULL, 26, '{7}'::int[], NULL, 'Привет! Запомни, что экскаватор-грейфер работает по «трехбарабанной» системе. Представь, что один барабан отвечает за подъем грейфера, второй — за его опускание, а третий — за открытие и закрытие ковша. Поэтому правильный ответ — три!', NULL),
(1557, 'en', 'How many drums does an excavator-grab winch have?', 'In accordance with the Georgian Law on Road Traffic and technical operation regulations, the excavator-grab operates using a three-drum winch, which is necessary due to the technical requirements for controlling the grab mechanism (hoisting/lowering and opening/closing).', 0, '1', 'Three', 'One', 'Five', NULL, 26, '{7}'::int[], NULL, 'Hello! Remember that an excavator-grab works using a ''three-drum'' system. Imagine that one drum is responsible for hoisting the grab, the second for lowering it, and the third for opening and closing the jaws. Therefore, the answer is always three!', NULL),
(1558, 'ka', 'რისი საშუალებით ხდება ბულდოზერის ფრთის აწევა და დაშვება?', 'ბულდოზერის ფრთის აწევა და დაშვება ხდება ჰიდრავლიკური ცილინდრებით.', 0, '2', 'დომკრატის', 'ჰიდრავლიკური ცილინდრებით', 'მექანიკური საშუალებით', NULL, 27, '{7}'::int[], NULL, 'წარმოიდგინე, რომ ბულდოზერის ფრთა ისეთივე მძიმეა, როგორც მანქანა. მის ასაწევად მექანიკური ძალა არასაკმარისია, ამიტომ მას ჰიდრავლიკური ცილინდრები (ზეთის წნევაზე მომუშავე მოწყობილობები) ამუშავებენ. ეს სისტემა ყველაზე ეფექტური და უსაფრთხოა.', NULL),
(1558, 'ru', 'С помощью чего осуществляется подъем и опускание отвала бульдозера?', 'В соответствии с Законом Грузии «О дорожном движении» и техническими регламентами, рабочий орган бульдозера (отвал) приводится в действие с помощью гидравлической системы. Гидравлические цилиндры обеспечивают позиционирование отвала и передачу необходимого усилия в процессе работы.', 0, '2', 'Домкрата', 'Гидравлических цилиндров', 'Механическим способом', NULL, 27, '{7}'::int[], NULL, 'Представь, что отвал бульдозера очень тяжелый. Чтобы его поднять, одних механических усилий недостаточно, поэтому используются гидравлические цилиндры, работающие под давлением масла. Это самый эффективный и надежный способ управления тяжелым рабочим органом.', NULL),
(1558, 'en', 'How is the blade of a bulldozer raised and lowered?', 'In accordance with the Law of Georgia ''On Road Traffic'' and technical regulations, the working body of a bulldozer (blade) is operated via a hydraulic system. Hydraulic cylinders provide the necessary positioning and force required for the blade to perform its work.', 0, '2', 'Jack', 'Hydraulic cylinders', 'Mechanical means', NULL, 27, '{7}'::int[], NULL, 'Imagine that a bulldozer blade is extremely heavy. To lift it, manual or simple mechanical force isn''t enough, so hydraulic cylinders (powered by oil pressure) are used. This system is the most efficient and powerful way to control heavy machinery components.', NULL),
(1559, 'ka', 'რა სისქის ყრილის გასამკვრივებლად გამოიყენება სატკეპნი მანქანები?', 'სატკეპნი მანქანები გამოიყენება 0,8 – 1,5 მეტრი სისქის ყრილის გასამკვრივებლად.', 0, '2', '0,4 – 2,0 მეტრი სისქის', '0,8 – 1,5 მეტრი სისქის', '0,1 – 1,0 მეტრი სისქის', NULL, 27, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ საგზაო სამუშაოების დროს ფენის სისქეს გადამწყვეტი მნიშვნელობა აქვს. 0,8-დან 1,5 მეტრამდე არის ის ''ოქროს შუალედი'', სადაც სატკეპნი მანქანები მაქსიმალურად ეფექტურად ამკვრივებენ ნიადაგს.', NULL),
(1559, 'ru', 'Какую толщину насыпного слоя уплотняют с помощью дорожных катков (уплотнительных машин)?', 'В соответствии с действующей нормативной базой Грузии, диапазон эффективной работы уплотнительных машин определяется для слоев насыпи толщиной от 0,8 до 1,5 метров. Данный параметр обеспечивает стабилизацию грунта и надлежащую прочность дорожного покрытия.', 0, '2', '0,4 – 2,0 метра', '0,8 – 1,5 метра', '0,1 – 1,0 метра', NULL, 27, '{7}'::int[], NULL, 'Привет! Помни, что при дорожных работах толщина слоя имеет решающее значение. Диапазон от 0,8 до 1,5 метров — это та самая «золотая середина», при которой уплотнительные машины наиболее эффективно утрамбовывают грунт.', NULL),
(1559, 'en', 'What thickness of embankment layer is compacted using compacting machines?', 'In accordance with the current legal framework of Georgia, the effective working range of compacting machines is defined for embankment layers with a thickness of 0.8 to 1.5 meters. This parameter ensures soil stabilization and the proper strength of the road surface.', 0, '2', '0.4 – 2.0 meters', '0.8 – 1.5 meters', '0.1 – 1.0 meters', NULL, 27, '{7}'::int[], NULL, 'Hello! Remember that when working on roads, the thickness of the layer is crucial. The range of 0.8 to 1.5 meters is the ''sweet spot'' where compacting machines are most effective at stabilizing the soil.', NULL),
(1560, 'ka', 'არხის ფერდისა და ფსკერის მოსწორება წარმოებს:', 'არხის ფერდისა და ფსკერის მოსწორება წარმოებს პასიური დანით.', 0, '1', 'პასიური დანით', 'ციცხვებიანი დანით', 'ციცხვებიანი როტორით', NULL, 27, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როცა ვსაუბრობთ არხების გასწორებაზე, ჩვენ გვჭირდება გლუვი და თანაბარი ზედაპირი. პასიური დანა ამისთვის იდეალურია, რადგან ის არ აფხვიერებს ზედმეტად მიწას, არამედ აკურატულად ათანაბრებს მას.', NULL),
(1560, 'ru', 'Выравнивание откосов и дна канала производится:', 'Согласно нормам дорожного движения и эксплуатации землеройной техники в Грузии, наиболее эффективным и стандартным инструментом для выравнивания откосов и дна каналов является пассивный нож (рабочий орган скреперного типа), обеспечивающий равномерное профилирование поверхности.', 0, '1', 'Пассивным ножом', 'Ножом с зубьями', 'Ротором с зубьями', NULL, 27, '{7}'::int[], NULL, 'Привет! Запомни: когда мы говорим о выравнивании каналов, нам нужна ровная и гладкая поверхность. Пассивный нож идеален для этого, так как он не взрыхляет почву лишний раз, а аккуратно ее разглаживает.', NULL),
(1560, 'en', 'Leveling the slopes and bottom of a channel is performed by:', 'According to the road traffic regulations and engineering construction norms in Georgia, the most technically efficient and standard equipment for leveling channel slopes and bottoms is a passive blade (a scraper-type working attachment), which ensures uniform surface profiling.', 0, '1', 'A passive blade', 'A serrated blade', 'A serrated rotor', NULL, 27, '{7}'::int[], NULL, 'Hello! Remember, when we talk about leveling channels, we need a smooth and even surface. A passive blade is ideal for this because it doesn''t disturb the soil unnecessarily, but rather levels it neatly.', NULL),
(1561, 'ka', 'ნაკერების დაჭრა მოპირკეთებულ ბეტონში წარმოებს:', 'ნაკერების დაჭრა მოპირკეთებულ ბეტონსი წარმოებს არხის გრძივი და განივი მიმართულებით.', 0, '2', 'არხის გრძივი მიმართულებით', 'არხის გრძივი და განივი მიმართულებით', 'არხის ფერდის მიმართულებით', NULL, 27, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ბეტონი სუნთქავს - ის ფართოვდება და იკუმშება. თუ მხოლოდ ერთ მხარეს გავჭრით, ბეტონი თავისით გაბზარდება. ამიტომ, ორივე მიმართულებით ვჭრით (გრძივად და განივად), რომ საფარი დაცული იყოს!', NULL),
(1561, 'ru', 'Нарезка швов в облицовочном бетоне производится:', 'В соответствии с Законом Грузии «О дорожном движении», нарезка деформационных швов в бетонном покрытии должна производиться как в продольном, так и в поперечном направлениях для предотвращения неконтролируемого растрескивания бетона при температурных колебаниях.', 0, '2', 'В продольном направлении канала', 'В продольном и поперечном направлениях канала', 'В направлении откоса канала', NULL, 27, '{7}'::int[], NULL, 'Привет! Запомни, бетон «дышит»: он расширяется и сжимается. Если сделать пропилы только в одном направлении, бетон треснет в хаотичном порядке. Поэтому мы режем в обоих направлениях (продольном и поперечном), чтобы покрытие оставалось целым!', NULL),
(1561, 'en', 'Cutting joints in faced concrete is performed:', 'In accordance with the Law of Georgia ''on Road Traffic'', the cutting of expansion joints in concrete pavement must be performed in both longitudinal and transverse directions to prevent uncontrolled cracking of the concrete due to temperature fluctuations.', 0, '2', 'In the longitudinal direction of the canal', 'In the longitudinal and transverse directions of the canal', 'In the direction of the canal slope', NULL, 27, '{7}'::int[], NULL, 'Hello! Remember, concrete ''breathes''—it expands and contracts. If we only cut in one direction, the concrete will crack uncontrollably. That’s why we cut in both directions (longitudinal and transverse) to keep the pavement structure intact!', NULL),
(1562, 'ka', 'ღია არხის პერიმეტრზე მოპირკეთებულ ბეტონში ნაკერების დაჭრა წარმოებს:', 'ღია არხის პერიმეტრზე მოპირკეთებულ ბეტონში ნაკერების დაჭრა წარმოებს: - გრძივი მიმართულებით - ანკერული დანით. - განივიმიმართულებით - V-სფორმისდანით.', 0, '2', 'გრძივი მიმართულებით - გილიოტინისებური დანით; განივი მიმართულებით - ანკერული დანით', 'გრძივი მიმართულებით - ანკერული დანით. განივი მიმართულებით - V-ს ფორმის დანი', NULL, NULL, 27, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ბეტონის არხების შემთხვევაში მნიშვნელოვანია სწორი ხელსაწყოს შერჩევა. გრძივი ნაკერი საჭიროებს ანკერულ დანას, რათა ზედაპირმა გაუძლოს დატვირთვას, ხოლო განივი ნაკერებისთვის V-ს ფორმის დანა გამოიყენება მოძრაობის მიმართულების სტაბილურობისთვის. სწორი პასუხია 2.', NULL),
(1562, 'ru', 'В бетонном покрытии по периметру открытого канала нарезка швов производится:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим строительно-техническим регламентам, нарезка деформационных швов в бетонном покрытии должна осуществляться специализированными инструментами: анкерным ножом для продольных швов и V-образным ножом для поперечных швов.', 0, '2', 'В продольном направлении - гильотинным ножом; в поперечном направлении - анкерным ножом', 'В продольном направлении - анкерным ножом; в поперечном направлении - V-образным ножом', NULL, NULL, 27, '{7}'::int[], NULL, 'Привет! Запомни: при работе с бетонными каналами важно правильно подобрать инструмент. Продольные швы режут анкерным ножом для обеспечения прочности покрытия, а поперечные — V-образным, чтобы швы правильно «работали» при нагрузках. Верный ответ — 2.', NULL),
(1562, 'en', 'Cutting joints in the concrete lining along the perimeter of an open channel is performed:', 'According to the Law of Georgia ''on Road Traffic'' and relevant construction-technical regulations, the cutting of expansion joints in concrete pavement must be carried out using specialized tools: an anchor knife for longitudinal joints and a V-shaped knife for transverse joints.', 0, '2', 'In the longitudinal direction - with a guillotine knife; in the transverse direction - with an anchor knife', 'In the longitudinal direction - with an anchor knife; in the transverse direction - with a V-shaped knife', NULL, NULL, 27, '{7}'::int[], NULL, 'Hello! Remember, when dealing with concrete channels, selecting the right tool is key. Longitudinal joints require an anchor knife to ensure structural integrity, while V-shaped knives are used for transverse joints to manage movement correctly. The correct answer is 2.', NULL),
(1563, 'ka', 'გუთნისებური ფრთიანი არხსათხრელი მანქანის სამუშაო ორგანოებია:', 'გუთნისებური ფრთიანი არხსათხრელი მანქანის სამუშაო ორგანოებია:სახნისი, ველის ფიცარი, წინამხვნელი და საკვეთელი.', 0, '2', 'ბრტყელი სახნისი, ფრთა, ფრთისებრი ზედაპირი, ფრთოვანები', 'სახნისი, ველის ფიცარი, წინამხვნელი, საკვეთელი', 'ოვალური ფრთა, ფრთისებრი ზედაპირი, გრუნტის მჭრელი, საკვეთელი', NULL, 27, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ არხსათხრელი მანქანა მუშაობს ნიადაგის ჭრის პრინციპით. სწორი პასუხია მე-2, რადგან სწორედ ეს დეტალები - სახნისი, ველის ფიცარი, წინამხვნელი და საკვეთელი - უზრუნველყოფს მიწის თანაბრად ჭრას და გადაადგილებას არხის გათხრისას.', NULL),
(1563, 'ru', 'Каковы рабочие органы плужного каналокопателя с отвалами?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, конструктивные элементы плужного каналокопателя определяются как лемех, полевая доска, предплужник и нож.', 0, '2', 'Плоский лемех, отвал, крыловидная поверхность, крылья', 'Лемех, полевая доска, предплужник, нож', 'Овальное крыло, крыловидная поверхность, почворезатель, нож', NULL, 27, '{7}'::int[], NULL, 'Привет! Запомни, что каналокопатель работает по принципу резания грунта. Правильный ответ — №2, так как именно эти детали — лемех, полевая доска, предплужник и нож — обеспечивают равномерное разрезание и перемещение почвы при прокладке канала.', NULL),
(1563, 'en', 'What are the working components of a plow-type winged canal digger?', 'In accordance with the Georgian Law on Road Traffic and relevant technical regulations, the structural components of a plow-type canal digger are defined as the plowshare, landside, jointer, and coulter.', 0, '2', 'Flat plowshare, moldboard, wing-shaped surface, wings', 'Plowshare, landside, jointer, coulter', 'Oval wing, wing-shaped surface, soil cutter, coulter', NULL, 27, '{7}'::int[], NULL, 'Hello! Remember that a canal digger works on the principle of soil cutting. Option 2 is correct because these specific components—the plowshare, landside, jointer, and coulter—are designed to efficiently cut and displace soil when digging a channel.', NULL),
(1564, 'ka', 'შნეკურ-როტორული კომბინირებული არხსათხრელი მანქანის ძირითადი სამუშაო ორგანოებია:', 'შნეკურ-როტორული კომბინირებული არხსათხრელი მანქანის ძირითადი სამუშაო ორგანოებია: ცილინდრული შნეკები, ფრთოვანი ციცხვებიანი როტორი და გამცლელი ტრანსპორტიორები.', 0, '2', 'ციცხვებიანი როტორი, ციცხვებიანი ჯაჭვი, ცილინდრული შნეკები, გამცლელი ტრანსპორტიორები', 'ცილინდრული შნეკები, ფრთოვანი ციცხვებიანი როტორი, გამცლელი ტრანსპორტიორები', 'კონუსური შნეკები, მრავალციცხვიანი როტორი, გამცლელი ტრანსპორტიორები', NULL, 28, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ამ ტიპის სპეცტექნიკის მუშაობა ეფუძნება კომპლექსურ მიდგომას: შნეკები ჭრიან და ამზადებენ ნიადაგს, როტორი ამოაქვს ის ზედაპირზე, ხოლო ტრანსპორტიორი განზე ყრის. მეორე პასუხი სწორია, რადგან ის ზუსტად ასახელებს ამ სამივე აუცილებელ კომპონენტს.', NULL),
(1564, 'ru', 'Какими являются основные рабочие органы шнеково-роторного комбинированного каналокопателя?', 'Согласно законодательству Грузии о дорожном движении и правилам эксплуатации специальной техники, конструктивная особенность комбинированного шнеково-роторного каналокопателя включает три основных элемента: цилиндрические шнеки для удаления грунта, лопастной ковшовый ротор для выемки грунта и разгрузочные транспортеры для перемещения извлеченной массы.', 0, '2', 'Ковшовый ротор, ковшовая цепь, цилиндрические шнеки, разгрузочные транспортеры', 'Цилиндрические шнеки, лопастной ковшовый ротор, разгрузочные транспортеры', 'Конические шнеки, многоковшовый ротор, разгрузочные транспортеры', NULL, 28, '{7}'::int[], NULL, 'Привет! Запомни, работа такой спецтехники — это слаженный процесс: шнеки рыхлят почву, ротор поднимает её, а транспортер отводит в сторону. Второй вариант верный, так как он точно перечисляет все три ключевых компонента конструкции.', NULL),
(1564, 'en', 'What are the main working parts of a screw-rotor combined ditch digging machine?', 'In accordance with Georgian road traffic legislation and the operating rules for special machinery, the structural design of a screw-rotor combined ditch digging machine consists of three main components: cylindrical screws for soil removal, a blade-bucket rotor for soil excavation, and discharge conveyors to transport the excavated material.', 0, '2', 'Bucket rotor, bucket chain, cylindrical screws, discharge conveyors', 'Cylindrical screws, blade bucket rotor, discharge conveyors', 'Conical screws, multi-bucket rotor, discharge conveyors', NULL, 28, '{7}'::int[], NULL, 'Hello! Remember, the operation of this heavy machinery is a coordinated process: the screws loosen the soil, the rotor lifts it up, and the conveyor moves it away. The second option is correct because it accurately lists these three essential structural components.', NULL),
(1565, 'ka', 'რას სწავლობს მანქანა-ტრაქტორთა პარკის ექსპლუატაცია?', 'მანქანა-ტრაქტორთა პარკის ექსპლუატაცია სწავლობს საოფლო-სამეურნეო აგრეგატების მუშაობის კანონზომიერებების და ეფექტური გამოყენების მეთოდებს.', 0, '3', 'მხოლოდ სასოფლო-სამეურნეო მანქანების მუშაობის კანონზომიერებას', 'რომელიმე კულტურის მოვლა-მოყვანის სასოფლო-სამეურნეო სამუშაოთა გეგმას', 'სასოფლო-სამეურნეო აგრეგატების მუშაობის კანონზომიერებების და ეფექტური გამოყენების მეთოდებს', 'რომელიმე კულტურის წარმოების ფინანსურ გეგმას', 28, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ სწორი პასუხია 3. ეს დისციპლინა არ ეხება მხოლოდ ფინანსებს ან კონკრეტულ მცენარეს, არამედ კონცენტრირდება ტექნიკის მაქსიმალურად ეფექტურად და სწორად გამოყენებაზე სამუშაო პროცესში.', NULL),
(1565, 'ru', 'Что изучает эксплуатация машинно-тракторного парка?', 'Эксплуатация машинно-тракторного парка — это дисциплина, изучающая закономерности работы сельскохозяйственных агрегатов, технические аспекты их эксплуатации и методологию их эффективного использования для обеспечения оптимальной работоспособности техники.', 0, '3', 'Только закономерности работы сельскохозяйственных машин', 'План сельскохозяйственных работ по возделыванию какой-либо культуры', 'Закономерности работы сельскохозяйственных агрегатов и методы их эффективного использования', 'Финансовый план производства какой-либо культуры', 28, '{7}'::int[], NULL, 'Привет! Запомни: правильный ответ — 3. Эта дисциплина изучает не финансы или конкретные растения, а то, как использовать технику максимально эффективно и правильно в процессе работы.', NULL),
(1565, 'en', 'What does the operation of a machine-tractor fleet study?', 'The operation of a machine-tractor fleet is a discipline that studies the operating patterns of agricultural aggregates, technical aspects of their maintenance, and the methodology of their effective use to ensure optimal machinery performance.', 0, '3', 'Only the patterns of operation of agricultural machines', 'The agricultural work plan for the cultivation of a specific crop', 'Patterns of operation of agricultural aggregates and methods of their effective use', 'The financial plan for the production of a specific crop', 28, '{7}'::int[], NULL, 'Hello! Remember, the correct answer is 3. This discipline isn''t about finances or specific crops, but rather focuses on how to use machinery as efficiently and correctly as possible during work.', NULL),
(1566, 'ka', 'ტექნოლოგიური რუკა წარმოადგენს:', 'ტექნოლოგიური რუკა წარმოადგენს რომელიმე კულტურის მოვლა-მოყვანის სასოფლო-სამეურნეო სამუშაოთა გეგმას.', 0, '1', 'რომელიმე კულტურის მოვლა-მოყვანის სასოფლო-სამეურნეო სამუშაოთა გეგმას', 'მანქანათა სისტემას რომელიმე კულტურის მოსაყვანად', 'რომელიმე კულტურის წარმოების ფინანსურ გეგმას', 'რომელიმე კულტურის წარმოების ბიზნეს-გეგმას', 28, '{7}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ ტექნოლოგიური რუკა არის შენი გზამკვლევი მინდორში. ის დეტალურად აღწერს, რა სამუშაოები უნდა ჩატარდეს მოსავლის მისაღებად.', NULL),
(1566, 'ru', 'Что представляет собой технологическая карта?', 'Технологическая карта официально определяется как плановая последовательность агротехнических мероприятий и работ, необходимых для возделывания сельскохозяйственной культуры.', 0, '1', 'План сельскохозяйственных работ по возделыванию той или иной культуры', 'Систему машин для возделывания какой-либо культуры', 'Финансовый план производства той или иной культуры', 'Бизнес-план производства той или иной культуры', 28, '{7}'::int[], NULL, 'Привет! Запомни, технологическая карта — это твой путеводитель в поле. Она детально описывает, какие именно работы нужно провести для получения урожая.', NULL),
(1566, 'en', 'What is a technological map?', 'A technological map is officially defined as the planned sequence of agrotechnical measures and operations required for the cultivation of an agricultural crop.', 0, '1', 'A plan of agricultural works for the cultivation of a specific crop', 'A system of machines for cultivating a specific crop', 'A financial plan for the production of a specific crop', 'A business plan for the production of a specific crop', 28, '{7}'::int[], NULL, 'Hello! Remember that a technological map is your guide in the field. It describes in detail exactly what work needs to be carried out to produce a crop.', NULL),
(1567, 'ka', 'ოპერაციულ-ტექნოლოგიური რუკა წარმოადგენს:', 'ოპერაციულ-ტექნოლოგიური რუკა წარმოადგენს რომელიმე სამუშაოს შესრულების გეგმას.', 0, '1', 'რომელიმე სამუშაოს შესრულების გეგმას', 'რომელიმე სამუშაოს შესრულების ბიზნეს-გეგმას', 'სამუშაოთა ჩამონათვალს მოცემული კულტურის წარმოებისთვის', 'სამუშაოს ჩატარების ფინანსურ მაჩვენებლებს', 28, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, ოპერაციულ-ტექნოლოგიური რუკა არის შენი ''ინსტრუქცია'' სამუშაოსთვის. ის გეუბნება, რა ნაბიჯები უნდა გადადგა, რათა საქმე სწორად და თანმიმდევრულად შეასრულო. ამიტომ, სწორი პასუხია სამუშაოს შესრულების გეგმა.', NULL),
(1567, 'ru', 'Операционно-технологическая карта представляет собой:', 'Операционно-технологическая карта определяется как детальный план выполнения работ, определяющий технологические процессы. Согласно грузинскому законодательству и стандартам, этот документ служит для обеспечения последовательного выполнения работы.', 0, '1', 'План выполнения какой-либо работы', 'Бизнес-план выполнения какой-либо работы', 'Перечень работ для производства данной культуры', 'Финансовые показатели проведения работ', 28, '{7}'::int[], NULL, 'Привет! Запомни, операционно-технологическая карта — это твоя «инструкция» для работы. Она говорит тебе, какие шаги нужно предпринять, чтобы выполнить задачу правильно и последовательно. Поэтому правильный ответ — план выполнения работы.', NULL),
(1567, 'en', 'An operational-technological map is:', 'An operational-technological map is defined as a detailed plan for performing work, which determines technological processes. According to Georgian legislation and standards, this document serves to ensure the sequential execution of work.', 0, '1', 'A plan for performing any work', 'A business plan for performing any work', 'A list of works for the production of a given crop', 'Financial indicators of work performance', 28, '{7}'::int[], NULL, 'Hello! Remember, an operational-technological map is your ''instruction manual'' for a task. It tells you exactly what steps to take to get the job done correctly and in the right order. That is why the correct answer is a plan for performing work.', NULL),
(1568, 'ka', 'რა მახასიათებლების მიხედვით იყოფა ტრაქტორები კლასებად?', 'ტრაქტორები კლასებად იყოფა ნომინალური წევის ძალის მიხედვით.', 0, '3', 'დანიშნულების მიხედვით', 'ტრანსმისიის მიხედვით', 'ნომინალური წევის ძალის მიხედვით', 'ძრავას მიხედვით', 28, '{7}'::int[], NULL, 'გამარჯობა! ტრაქტორების შემთხვევაში მთავარი მაჩვენებელი არის „წევის ძალა“. ეს არის ის ძალა, რომლითაც ტრაქტორს შეუძლია მიათრიოს მისაბმელი ან სხვა ინვენტარი. სწორედ ამიტომ, კლასიფიკაცია ხდება წევის ძალის მიხედვით.', NULL),
(1568, 'ru', 'Согласно каким характеристикам тракторы делятся на классы?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, классификация тракторов осуществляется по их номинальному тяговому усилию (в килоньютонах), которое определяет их эксплуатационные возможности.', 0, '3', 'По назначению', 'По типу трансмиссии', 'По номинальному тяговому усилию', 'По типу двигателя', 28, '{7}'::int[], NULL, 'Привет! Главный показатель для тракторов — это «тяговое усилие». Это та сила, с которой трактор может тянуть прицеп или навесное оборудование. Именно поэтому классификация основана именно на этом параметре.', NULL),
(1568, 'en', 'According to what characteristics are tractors divided into classes?', 'In accordance with the Georgian Law on Road Traffic and relevant technical regulations, tractors are classified based on their nominal tractive effort (measured in kilonewtons), which determines their operational capabilities.', 0, '3', 'By purpose', 'By type of transmission', 'By nominal tractive effort', 'By type of engine', 28, '{7}'::int[], NULL, 'Hello! The most important indicator for tractors is their ''tractive effort.'' This is the force the tractor can use to pull trailers or heavy attachments. That is why they are classified based on this specific parameter.', NULL),
(1569, 'ka', 'რა ფიზიკურ-მექანიკური თვისება ახასიათებს ნიადაგს?', 'ნიადაგის ფიზიკურ-მექანიკური თვისებაა სიმკვრივე.', 0, '3', 'კულტურული', 'წებოვნება', 'სიმკვრივე', NULL, 28, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, როცა გზაზე მივდივართ, მნიშვნელოვანია ვიცოდეთ, რაზე დავდივართ. ნიადაგის სიმკვრივე განსაზღვრავს, რამდენად მყარია გზა და როგორ რეაგირებს ის ავტომობილის წონაზე. სწორედ ამიტომ სიმკვრივეა სწორი პასუხი!', NULL),
(1569, 'ru', 'Какое физико-механическое свойство характерно для почвы?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, плотность является основной физико-механической характеристикой почвы, определяющей несущую способность дорожного покрытия.', 0, '3', 'Культурное', 'Липкость', 'Плотность', NULL, 28, '{7}'::int[], NULL, 'Привет! Запомни, когда мы едем по дороге, важно понимать свойства грунта. Плотность почвы определяет, насколько дорога прочна и как она выдерживает вес автомобиля. Именно поэтому плотность — правильный ответ!', NULL),
(1569, 'en', 'What physical-mechanical property characterizes the soil?', 'According to the Georgian ''Law on Road Traffic'' and relevant technical regulations, density is the primary physical-mechanical property of the soil, which determines the load-bearing capacity of the road surface.', 0, '3', 'Cultural', 'Stickiness', 'Density', NULL, 28, '{7}'::int[], NULL, 'Hello! Remember, when we are on the road, it''s important to understand the properties of the ground. The density of the soil determines how solid the road is and how it supports the weight of the vehicle. That''s why density is the correct answer!', NULL),
(1570, 'ka', 'რა ტექნოლოგიური თვისებები ახასიათებს ნიადაგს?', 'ნიადაგის ტექნოლოგიური თვისებაა წებოვნება.', 0, '1', 'წებოვნება', 'ნიადაგის ტენიანობა', 'ფორიანობა', NULL, 29, '{7}'::int[], NULL, 'გამარჯობა! როდესაც ვსაუბრობთ ნიადაგის ტექნოლოგიურ თვისებებზე, უნდა გვახსოვდეს, რომ „წებოვნება“ არის ის მთავარი მაჩვენებელი, რომელიც გავლენას ახდენს გზის მშენებლობისას ტექნიკის მუშაობაზე. სხვა ვარიანტები, როგორიცაა ტენიანობა ან ფორიანობა, ნიადაგის ფიზიკური მდგომარეობის მახასიათებლებია, ხოლო წებოვნება უშუალოდ განსაზღვრავს მის „ტექნოლოგიურ“ ქცევას.', NULL),
(1570, 'ru', 'Какими технологическими свойствами обладает почва?', 'Согласно законодательству Грузии и нормативным актам по дорожному строительству, основным технологическим свойством почвы является липкость (адгезия), которая определяет склонность грунта к прилипанию к рабочим органам машин и его обрабатываемость.', 0, '1', 'Липкость', 'Влажность почвы', 'Пористость', NULL, 29, '{7}'::int[], NULL, 'Привет! Когда мы говорим о технологических свойствах почвы, важно помнить, что «липкость» — это ключевой показатель, влияющий на работу техники при дорожных работах. В то время как влажность и пористость являются характеристиками физического состояния почвы, именно липкость определяет её «технологическое» поведение.', NULL),
(1570, 'en', 'What technological properties characterize soil?', 'According to the legislation of Georgia and road construction standards, the main technological property of soil is stickiness (adhesion), which determines the soil''s tendency to adhere to machinery working parts and its workability.', 0, '1', 'Stickiness', 'Soil moisture', 'Porosity', NULL, 29, '{7}'::int[], NULL, 'Hello! When discussing the technological properties of soil, keep in mind that ''stickiness'' is the key indicator that affects how machinery performs during road construction. While moisture and porosity are characteristics of the soil''s physical state, it is stickiness that directly defines its ''technological'' behavior.', NULL),
(1571, 'ka', 'ხვნის სახეებია?', 'ხვნის სახეებია:კულტურული, ხვნა ბელტის მთლიანი გადაბრუნებით და რომბული.', 0, '4', 'მხოლოდ კულტურული', 'მხოლოდ ხვნა ბელტის მთლიანი გადაბრუნებით', 'მხოლოდ რომბული', 'ყველა ჩამოთვლილი სახეები', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მიწის დამუშავებისას ტექნიკას აქვს სხვადასხვა მეთოდი. კანონით განსაზღვრული სამივე სახეობა — კულტურული, მთლიანი გადაბრუნებით და რომბული — სწორია, ამიტომ თამამად აირჩიე მეოთხე პასუხი!', NULL),
(1571, 'ru', 'Виды пахоты:', 'Согласно действующему законодательству Грузии и стандартам эксплуатации сельскохозяйственной техники, к основным видам пахоты относятся: культурная вспашка, вспашка с полным оборотом пласта и ромбическая вспашка. Таким образом, четвертый вариант является верным, так как включает в себя все перечисленные методы.', 0, '4', 'Только культурная', 'Только вспашка с полным оборотом пласта', 'Только ромбическая', 'Все перечисленные виды', 29, '{7}'::int[], NULL, 'Привет! Помни, что при обработке почвы существует несколько методов. Все три вида, определенные законом — культурная, с полным оборотом пласта и ромбическая — являются верными, поэтому смело выбирай четвертый вариант!', NULL),
(1571, 'en', 'What are the types of plowing?', 'According to the current legislation of Georgia and agricultural machinery operation standards, the main types of plowing include: cultural plowing, plowing with full turnover of the furrow slice, and rhombic plowing. Therefore, the fourth answer is correct as it encompasses all the mentioned methods.', 0, '4', 'Cultural only', 'Plowing with full turnover of the furrow slice only', 'Rhombic only', 'All of the listed types', 29, '{7}'::int[], NULL, 'Hello! Remember that there are different methods when it comes to tilling the soil. All three types defined by law—cultural, full turnover, and rhombic—are correct, so feel free to select the fourth option!', NULL),
(1573, 'ka', 'რომელი მექანიზმია გამოყენებული დგუშიან შიგაწვის ძრავაში?', 'დგუშიან შიგაწვის ძრავაში გამოყენებულია მრუმხარა-ბარბაცა მექანიზმი.', 0, '3', 'ჭიახრახნული მექანიზმი', 'კულისა მექანიზმი', 'მრუმხარა-ბარბაცა მექანიზმი', 'პლანეტარული მექანიზმი', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ძრავის მუშაობა ეფუძნება დგუშის მოძრაობას. ეს მექანიზმი (მრუმხარა-ბარბაცა) ჰგავს ველოსიპედის პედლების მოძრაობას: შენი ფეხის ზევით-ქვევით მოძრაობა ბორბლის ბრუნვაში გარდაიქმნება. ძრავაშიც ზუსტად ასე ხდება - დგუშის მოძრაობა გარდაიქმნება ბრუნვად.', NULL),
(1573, 'ru', 'Какой механизм используется в поршневом двигателе внутреннего сгорания?', 'Согласно Закону Грузии «О дорожном движении» и техническим регламентам автомобилестроения, основным средством преобразования энергии в поршневом двигателе внутреннего сгорания является кривошипно-шатунный механизм, который обеспечивает преобразование возвратно-поступательного движения поршня во вращательное движение коленчатого вала.', 0, '3', 'Червячный механизм', 'Кулисный механизм', 'Кривошипно-шатунный механизм', 'Планетарный механизм', 29, '{7}'::int[], NULL, 'Привет! Запомни, работа двигателя основана на движении поршня. Этот механизм (кривошипно-шатунный) работает как педали велосипеда: движение твоих ног вверх-вниз превращается во вращение колес. В двигателе происходит то же самое — движение поршня преобразуется во вращение.', NULL),
(1573, 'en', 'Which mechanism is used in a piston internal combustion engine?', 'According to the Georgian Law on Road Traffic and automotive engineering technical regulations, the primary mechanism used in a piston internal combustion engine is the crank-connecting rod mechanism, which converts the reciprocating motion of the piston into the rotational motion of the crankshaft.', 0, '3', 'Worm gear mechanism', 'Slotted link mechanism', 'Crank-connecting rod mechanism', 'Planetary mechanism', 29, '{7}'::int[], NULL, 'Hello! Remember, the engine works based on piston movement. This mechanism (crank-connecting rod) is just like bicycle pedals: your legs moving up and down are converted into wheel rotation. It’s exactly the same in an engine—the reciprocating motion of the piston is converted into rotation.', NULL),
(1574, 'ka', 'სავალი ნაწილის მიხედვით სასოფლო-სამეურნეო ტრაქტორები კლასიფიცირდება:', 'სავალი ნაწილის მიხედვით სასოფლო-სამეურნეო ტრაქტორები კლასიფიცირდება: მუხლუხა, ნახევრადმუხლუხა და თვლიანი.', 0, '3', 'საერთო დანიშნულების, უნივერსალური სათოხნი, სპეციალური', 'ჩარჩოიანი, ნახევრადჩარჩოიანი, უჩარჩო', 'მუხლუხა, ნახევრადმუხლუხა, თვლიანი', 'სამთო, ჭაობნარის, სამელიორაციო, საბაღბოსტნე', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როდესაც ტრაქტორის „სავალ ნაწილზე“ ვსაუბრობთ, ვგულისხმობთ იმას, თუ რით გადაადგილდება ის მიწაზე. სწორი პასუხია მუხლუხა, ნახევრადმუხლუხა და თვლიანი, რადგან ეს სამი ტიპი განსაზღვრავს ტრაქტორის მოძრაობის მექანიზმს.', NULL),
(1574, 'ru', 'По типу ходовой части сельскохозяйственные тракторы классифицируются как:', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, классификация тракторов по типу ходовой части определяется как гусеничные, полугусеничные и колесные.', 0, '3', 'Общего назначения, универсально-пропашные, специальные', 'Рамные, полурамные, безрамные', 'Гусеничные, полугусеничные, колесные', 'Горные, болотные, мелиоративные, садовые', 29, '{7}'::int[], NULL, 'Привет! Запомни, когда мы говорим о «ходовой части» трактора, мы имеем в виду то, как он взаимодействует с поверхностью дороги или почвы. Правильный ответ — гусеничные, полугусеничные и колесные, так как именно эти три типа составляют основную техническую классификацию движителей трактора.', NULL),
(1574, 'en', 'According to the running gear (chassis type), agricultural tractors are classified as:', 'In accordance with the Law of Georgia ''on Road Traffic'' and relevant technical regulations, the classification of tractors according to the type of running gear is defined as tracked, semi-tracked, and wheeled.', 0, '3', 'General purpose, universal row-crop, special', 'Frame, semi-frame, frameless', 'Tracked, semi-tracked, wheeled', 'Mountain, swamp, land reclamation, orchard', 29, '{7}'::int[], NULL, 'Hello! Remember, when we talk about a tractor''s ''running gear'', we mean how it moves along the ground. The correct answer is tracked, semi-tracked, and wheeled, as these three categories define the mechanical system that propels the tractor.', NULL),
(1575, 'ka', 'რომელ ძრავაში გამოიყენება ანთების ბატარეული სისტემა?', 'ანთების ბატარეული სისტემა გამოიყენება კარბურატორიან ძრავებში.', 0, '2', 'დიზელის ძრავებში', 'კარბურატორიან ძრავებში', 'ელექტრო ძრავებში', 'ჰიდრავლიკურ ძრავებში', 29, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ანთების სისტემა საჭიროა ნარევის ასანთებად. დიზელის ძრავები თვითაალებადია, ხოლო კარბურატორიანი ძრავები იყენებენ ელექტრო ნაპერწკალს, რომელსაც ბატარეა (აკუმულატორი) უზრუნველყოფს. ამიტომ სწორი პასუხია მეორე!', NULL),
(1575, 'ru', 'В каком двигателе используется батарейная система зажигания?', 'В соответствии с Законом Грузии «О дорожном движении», батарейная система зажигания используется исключительно в тех типах двигателей внутреннего сгорания, где воспламенение топливной смеси происходит от искры, а именно в карбюраторных двигателях.', 0, '2', 'В дизельных двигателях', 'В карбюраторных двигателях', 'В электрических двигателях', 'В гидравлических двигателях', 29, '{7}'::int[], NULL, 'Привет! Запомни: система зажигания нужна, чтобы поджечь топливо. Дизельные двигатели работают на самовоспламенении от сжатия, а карбюраторные нуждаются в искре, которую питает аккумулятор. Поэтому правильный ответ — второй!', NULL),
(1575, 'en', 'In which engine is the battery ignition system used?', 'In accordance with the Law of Georgia ''On Road Traffic'', the battery ignition system is specifically used in types of internal combustion engines where the fuel mixture is ignited by a spark, namely in carburetor engines.', 0, '2', 'In diesel engines', 'In carburetor engines', 'In electric engines', 'In hydraulic engines', 29, '{7}'::int[], NULL, 'Hello! Remember, an ignition system is needed to light the fuel mixture. Diesel engines ignite by compression, whereas carburetor engines rely on an electric spark provided by the battery. That''s why the second option is the correct one!', NULL),
(1576, 'ka', 'რომელი მექანიზმი გამოიყენება შიგაწვის ძრავებში?', 'შიგაწვის ძრავებში გამოიყენება აირგამანაწილებელი მექანიზმი.', 0, '4', 'სათბობგამანაწილებელი მექანიზმი', 'ზეთის გამანაწილებელი მექანიზმი', 'წყლის გაგრილების მექანიზმი', 'აირგამანაწილებელი მექანიზმი', 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ შენი ძრავა ჰგავს ფილტვებს: მას სჭირდება ''ჩასუნთქვა'' (საწვავი ნარევი) და ''ამოსუნთქვა'' (გამონაბოლქვი). სწორედ ამ პროცესს აკონტროლებს აირგამანაწილებელი მექანიზმი. დანარჩენი ვარიანტები ძრავის ნაწილებია, მაგრამ ძრავის მუშაობის ციკლისთვის ეს კონკრეტული მექანიზმია გადამწყვეტი.', NULL),
(1576, 'ru', 'Какой механизм используется в двигателях внутреннего сгорания?', 'В соответствии с законом Грузии «О дорожном движении», для исправной работы двигателя внутреннего сгорания необходим газораспределительный механизм (ГРМ), который обеспечивает своевременную подачу топливной смеси в цилиндры и выпуск отработавших газов.', 0, '4', 'Механизм распределения топлива', 'Механизм распределения масла', 'Механизм водяного охлаждения', 'Газораспределительный механизм', 30, '{7}'::int[], NULL, 'Привет! Представь, что двигатель — это легкие автомобиля: ему нужно «вдыхать» (топливную смесь) и «выдыхать» (выхлопные газы). Именно этот процесс контролирует газораспределительный механизм. Остальные варианты — это лишь части системы, но для цикличной работы двигателя критически важен именно ГРМ.', NULL),
(1576, 'en', 'Which mechanism is used in internal combustion engines?', 'In accordance with the Georgian Law on Road Traffic, for the proper operation of an internal combustion engine, a valve train (gas distribution) mechanism is required to ensure the timely intake of fuel mixture into the cylinders and the exhaust of combustion gases.', 0, '4', 'Fuel distribution mechanism', 'Oil distribution mechanism', 'Water cooling mechanism', 'Valve train mechanism (gas distribution mechanism)', 30, '{7}'::int[], NULL, 'Hello! Think of your engine as a pair of lungs: it needs to ''inhale'' (the fuel mixture) and ''exhale'' (exhaust gases). The gas distribution mechanism (valve train) is what controls this rhythm. While the other options relate to engine parts, this specific mechanism is the key to the engine''s core operation cycle.', NULL),
(1578, 'ka', 'რომელი გადაცემა გამოიყენება მბრუნავ ლილვებს შორის თუ მათი გეომეტრიული ღერძები ერთმანეთს არ ემთხვევა და შეადგენს ცვლად კუთხეს?', 'მბრუნავ ლილვებს შორის, თუ მათი გეომეტრიული ღერძები ერთმანეთს არ ემთხვევა და შეადგენს ცვლად კუთხეს გამოიყენება კარდანული გადაცემა.', 0, '3', 'ჭიახრახნული გადაცემა', 'კბილანური გადაცემა', 'კარდანული გადაცემა', NULL, 30, '{7}'::int[], NULL, 'წარმოიდგინე, რომ მანქანის ბორბლები მაღლა-დაბლა მოძრაობენ გზის უსწორმასწორობის გამო. კარდანული გადაცემა არის ის მოქნილი რგოლი, რომელიც ამუშავებს ძრავას მაშინაც კი, როცა ლილვები ერთ სწორ ხაზზე არ დგას. ეს არის ზუსტად ის მექანიზმი, რაც მოძრაობისას ამ ცვალებადი კუთხის კომპენსირებას ახდენს.', NULL),
(1578, 'ru', 'Какая передача используется между вращающимися валами, если их геометрические оси не совпадают и образуют переменный угол?', 'Согласно Закону Грузии «О дорожном движении» и техническим нормам эксплуатации транспортных средств, карданная передача предназначена для передачи крутящего момента между валами, геометрические оси которых не совпадают и расположены под переменным углом.', 0, '3', 'Червячная передача', 'Зубчатая передача', 'Карданная передача', NULL, 30, '{7}'::int[], NULL, 'Представь, что колеса автомобиля движутся вверх-вниз из-за неровностей дороги. Карданная передача — это гибкое звено, которое позволяет передавать вращение от двигателя к колесам, даже когда валы находятся под углом друг к другу. Именно этот механизм компенсирует изменение угла во время движения.', NULL),
(1578, 'en', 'Which transmission is used between rotating shafts if their geometric axes do not coincide and form a variable angle?', 'According to the Georgian ''Law on Road Traffic'' and vehicle technical operation regulations, a cardan (universal) transmission is used to transmit torque between rotating shafts when their geometric axes do not coincide and form a variable angle.', 0, '3', 'Worm gear transmission', 'Gear transmission', 'Cardan (universal) joint transmission', NULL, 30, '{7}'::int[], NULL, 'Imagine that a car''s wheels move up and down due to road bumps. The cardan transmission is the flexible link that allows the engine to keep powering the wheels even when the shafts are not in a straight line. It is the specific mechanism that compensates for these changing angles while driving.', NULL),
(1580, 'ka', 'რომელი დენის წყაროდან იკვებება ყველა მომხმარებელი ძრავას დაბალ ბრუნთა სიხშირეზე მუშაობის დროს?', 'ძრავას დაბალ ბრუნთა სიხშირეზე მუშაობის დროს ყველა მომხმარებელი იკვებება აკუმლიატორიდან.', 0, '4', 'გენერატორიდან', 'გამანაწილებელიდან', 'საიდუნქციო კოჭიდან', 'აკუმლიატორიდან', 30, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ გენერატორი მაშინ მუშაობს ეფექტურად, როცა ძრავა სწრაფად ბრუნავს. დაბალ ბრუნებზე ის „ისვენებს“, ამიტომ მთელი სიმძიმე აკუმულატორზე გადადის – სწორედ ის ინახავს ენერგიას, რათა შენი მანქანის სისტემები არ გაითიშოს.', NULL),
(1580, 'ru', 'От какого источника питания питаются все потребители при работе двигателя на низких оборотах?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, при низких оборотах двигателя генератор не вырабатывает достаточного количества электроэнергии, поэтому питание всех потребителей осуществляется от аккумуляторной батареи.', 0, '4', 'От генератора', 'От распределителя', 'От катушки зажигания', 'От аккумуляторной батареи', 30, '{7}'::int[], NULL, 'Привет! Помни, что генератор эффективно работает только на высоких оборотах двигателя. На низких оборотах он не справляется, и всю нагрузку берет на себя аккумулятор — именно он является хранилищем энергии, которое поддерживает работу всех систем твоего авто.', NULL),
(1580, 'en', 'From which power source are all consumers powered when the engine is operating at low RPM?', 'According to the Georgian Law on Road Traffic and relevant technical regulations, when the engine is at low RPM, the generator does not produce sufficient electricity; therefore, all consumers are powered by the battery.', 0, '4', 'From the generator', 'From the distributor', 'From the ignition coil', 'From the battery', 30, '{7}'::int[], NULL, 'Hello! Remember that the generator only works efficiently when the engine is spinning fast. At low RPM, it doesn''t provide enough power, so the battery takes the load—it acts as the energy reservoir to keep your car''s systems running smoothly.', NULL),
(1581, 'ka', 'რომელი დენის წყაროდან იკვებება ყველა მომხმარებელი ძრავას საშუალო და მაღალ ბრუნთა სიხშირეზე მუშაობის დროს?', 'ძრავას საშუალო და მაღალ ბრუნთა სიხშირეზე მუშაობის დროს ყველა მომხმარებელი იკვებება გენერატორიდან.', 0, '1', 'გენერატორიდან', 'გამანაწილებელიდან', 'საიდუნქციო კოჭიდან', 'აკუმლიატორიდან', 30, '{7}'::int[], NULL, 'წარმოიდგინე, რომ გენერატორი შენი მანქანის პატარა ელექტროსადგურია. როგორც კი ძრავა იწყებს მუშაობას და ბრუნები იმატებს, გენერატორი იწყებს ელექტროენერგიის გამომუშავებას. ამიტომ, როცა გზაში ხარ, ყველაფერი (განათება, მუსიკა და ა.შ.) სწორედ გენერატორიდან იკვებება.', NULL),
(1581, 'ru', 'От какого источника тока питаются все потребители электроэнергии при работе двигателя на средних и высоких оборотах?', 'Согласно техническому регламенту и нормам эксплуатации транспортных средств, при работе двигателя на средних и высоких оборотах основным источником тока является генератор. Он обеспечивает питанием всех потребителей электроэнергии в автомобиле и одновременно подзаряжает аккумуляторную батарею.', 0, '1', 'От генератора', 'От распределителя', 'От катушки зажигания', 'От аккумуляторной батареи', 30, '{7}'::int[], NULL, 'Представь, что генератор — это маленькая электростанция твоего автомобиля. Как только двигатель заводится и набирает обороты, генератор начинает вырабатывать ток. Поэтому во время движения все приборы (фары, музыка и прочее) питаются именно от него, а не от аккумулятора.', NULL),
(1581, 'en', 'From which power source are all consumers powered when the engine is operating at medium and high RPM?', 'According to technical regulations and vehicle operation standards, when the engine is running at medium and high RPM, the alternator acts as the primary power source. It supplies electricity to all vehicle consumers and simultaneously recharges the battery.', 0, '1', 'From the alternator', 'From the distributor', 'From the ignition coil', 'From the battery', 30, '{7}'::int[], NULL, 'Imagine the alternator as your car''s personal power plant. Once the engine starts and reaches higher speeds, the alternator generates the electricity needed. That’s why, while you are driving, everything from your lights to your audio system is powered by the alternator rather than the battery.', NULL),
(1584, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ სარგებლობს უპირატესობით ავტობუსის მძღოლი, ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას.', 1, '2', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც მსუბუქი ავტომობილის მძღოლის, ასევე სატვირთო ავტომობილის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ საგზაო მოძრაობის წესებში უპირატესობა დამოკიდებულია საგზაო ნიშნებსა და სიტუაციაზე და არა ავტომობილის ზომაზე ან ტიპზე. თუ ავტობუსი მთავარ გზაზეა, მან გზა უნდა დაუთმოს როგორც მსუბუქ, ისე სატვირთო ავტომობილს, რადგან კანონი ორივეს თანაბრად ექცევა.', 'ticket_media/new/ticketIMG-1584.jpg'),
(1584, 'ru', 'По отношению к водителю какого транспортного средства имеет преимущество водитель автобуса при движении в направлении стрелки?', 'В соответствии со статьей 36 Закона Грузии «О дорожном движении», преимущество предоставляется транспортному средству, движущемуся по главной дороге или имеющему право проезда. Закон не проводит различий между типом транспортного средства (легковой или грузовой) при предоставлении преимущества, поэтому автобус имеет преимущество перед обоими.', 1, '2', 'Только по отношению к водителю легкового автомобиля', 'Как по отношению к водителю легкового автомобиля, так и по отношению к водителю грузового автомобиля', 'Только по отношению к водителю грузового автомобиля', NULL, 29, '{4}'::int[], NULL, 'Привет! Помни, что в правилах дорожного движения приоритет зависит от дорожных знаков и ситуации, а не от размера или типа автомобиля. Если автобус находится на главной дороге, он имеет преимущество как перед легковым, так и перед грузовым автомобилем, так как закон относится к обоим одинаково.', 'ticket_media/new/ticketIMG-1584.jpg'),
(1584, 'en', 'Towards which vehicle driver does the bus driver have priority when moving in the direction of the arrow?', 'In accordance with Article 36 of the Law of Georgia ''On Road Traffic'', priority is granted to the vehicle moving on the main road or enjoying the right of way. The law does not distinguish between vehicle types (passenger car or truck) when granting priority; therefore, the bus has priority over both.', 1, '2', 'Only towards the driver of a passenger car', 'Towards both the driver of a passenger car and the driver of a truck', 'Only towards the driver of a truck', NULL, 29, '{4}'::int[], NULL, 'Hello! Remember, in traffic rules, priority depends on road signs and the specific situation, not on the size or type of the vehicle. If the bus is on a main road, it has priority over both passenger cars and trucks, as the law treats both vehicle types equally.', 'ticket_media/new/ticketIMG-1584.jpg'),
(1585, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „ე“ ქვეპუნქტების თანახმად,არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '2', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც მოტოციკლის მძღოლის, ასევე მსუბუქი ავტომობილის მძღოლის მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის წესი“: თუ გზაჯვარედინი არარეგულირებადია და გზები თანაბარმნიშვნელოვანია, ყოველთვის დაუთმე გზა იმას, ვინც შენი მარჯვენა მხრიდან მოდის. ამ შემთხვევაში, მსუბუქი ავტომობილი შენს მარჯვნივ არის, ამიტომ მას უთმობ!', 'ticket_media/new/ticketIMG-1585.jpg'),
(1585, 'ru', 'Водитель автобуса, движущийся в направлении стрелки, обязан уступить дорогу водителю какого транспортного средства?', 'Согласно статье 36 Закона Грузии «О дорожном движении», на равнозначном перекрестке водитель обязан уступить дорогу транспортному средству, приближающемуся справа. Поскольку легковой автомобиль приближается справа, водитель автобуса обязан уступить ему дорогу.', 1, '2', 'Только водителю мотоцикла', 'Только водителю легкового автомобиля', 'Как водителю мотоцикла, так и водителю легкового автомобиля', NULL, 29, '{4}'::int[], NULL, 'Привет! Запомни «правило правой руки»: на нерегулируемом равнозначном перекрестке всегда уступай дорогу тому, кто приближается справа. В данном случае легковой автомобиль находится справа от тебя, поэтому ты обязан уступить ему дорогу!', 'ticket_media/new/ticketIMG-1585.jpg'),
(1585, 'en', 'The bus driver, moving in the direction of the arrow, must yield the right of way to the driver of which vehicle?', 'According to Article 36 of the Law of Georgia ''On Road Traffic'', at an equal-priority intersection, a driver is obliged to yield to a vehicle approaching from the right. Since the passenger car is approaching from the right, the bus driver must yield to it.', 1, '2', 'Only to the motorcycle driver', 'Only to the car driver', 'To both the motorcycle driver and the car driver', NULL, 29, '{4}'::int[], NULL, 'Hello! Remember the ''right-hand rule'': at an unregulated intersection with equal-priority roads, always yield to the vehicle approaching from your right. In this scenario, the passenger car is to your right, so you must let it go first!', 'ticket_media/new/ticketIMG-1585.jpg'),
(1586, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც ავტობუსის მძღოლის, ასევე მსუბუქი ავტომობილის მძღოლის მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს წესი: მთავარ გზაზე მოძრავ სატრანსპორტო საშუალებას ყოველთვის აქვს უპირატესობა. რადგან შენ მოძრაობ მეორეხარისხოვანი გზიდან, არ აქვს მნიშვნელობა ავტობუსი გზის რომელ მხარეს მიდის ან მსუბუქი მანქანა სად აპირებს მოსახვევს — ორივე მათგანი მთავარ გზაზეა, ამიტომ ორივეს უნდა დაუთმო გზა.', 'ticket_media/new/ticketIMG-1586.jpg'),
(1586, 'ru', 'Водителю какого транспортного средства обязан уступить дорогу водитель мотоцикла при движении в направлении стрелки?', 'Согласно подпункту «а» пункта 4 статьи 36 Закона Грузии «О дорожном движении», водитель, находящийся на второстепенной дороге, обязан уступить дорогу любому транспортному средству, движущемуся по главной дороге, независимо от направления их движения. Поскольку автобус и легковой автомобиль находятся на главной дороге, мотоциклист обязан уступить дорогу обоим.', 1, '3', 'Только водителю автобуса', 'Только водителю легкового автомобиля', 'Как водителю автобуса, так и водителю легкового автомобиля', NULL, 29, '{2}'::int[], NULL, 'Привет! Запомни простое правило: транспортные средства на главной дороге всегда имеют приоритет. Раз ты выезжаешь со второстепенной дороги, неважно, куда именно едут автобус или легковой автомобиль — они оба на главной дороге, поэтому ты обязан пропустить обоих.', 'ticket_media/new/ticketIMG-1586.jpg'),
(1586, 'en', 'To which vehicle''s driver is the motorcycle driver required to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Clause 4, Sub-clause ''a'' of the Law of Georgia ''On Road Traffic'', a driver on a minor road is required to yield the right of way to any vehicle on a major road, regardless of their direction of travel. Since both the bus and the passenger car are on the major road, the motorcyclist must yield to both.', 1, '3', 'Only to the bus driver', 'Only to the passenger car driver', 'To both the bus driver and the passenger car driver', NULL, 29, '{2}'::int[], NULL, 'Hello! Remember this rule: vehicles on the major road always have priority. Since you are approaching from a minor road, it doesn''t matter where the bus is heading or where the car is turning — because they are both on the major road, you must yield to both of them.', 'ticket_media/new/ticketIMG-1586.jpg'),
(1587, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში თუ ოპერატიული სამსახურის ავტომობილს ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა და ხმოვანი სიგნალები?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად,არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც. გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე კანონის 51-ე მუხლის მე-2 პუნქტის თანახმად, საგზაო მოძრაობის მონაწილეები ვალდებული არიან, ოპერატიული ან სპეციალური სამსახურის სატრანსპორტო საშუალების მოახლოებისას, რომელსაც ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა სიგნალი და ხმოვანი სიგნალი ან/და რომელიც ხმამაღლამოლაპარაკე ხელსაწყოთი იძლევა სიგნალს, მას, აგრეთვე მის მიერ გასაცილებელ სატრანსპორტო საშუალებას, რომელსაც ჩართული აქვს ახლო განათების ფარები, გაუთავისუფლონ სავალ ნაწილზე ადგილი, ხოლო აუცილებლობის შემთხვევაში − გაჩერდნენ.', 1, '2', 'მხოლოდ ოპერატიული სამსახურის ავტომობილის და ტრაქტორის მძღოლების მიმართ', 'მხოლოდ ოპერატიული სამსახურის ავტომობილის მძღოლის მიმართ', 'ყველა სატრანსპორტო საშუალების მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს: როგორც კი დაინახავ ან გაიგონებ ლურჯი ციმციმითა და ხმოვანი სიგნალით მოძრავ სასწრაფოს, პოლიციას ან სახანძროს, შენი მთავარი მოვალეობაა მათთვის გზის გათავისუფლება. კანონი პრიორიტეტს ანიჭებს მხოლოდ მათ. სხვა სატრანსპორტო საშუალებებთან მიმართებით გზაჯვარედინის გავლის ზოგადი წესები მოქმედებს.', 'ticket_media/new/ticketIMG-1587.jpg'),
(1587, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса, движущемуся в указанном стрелкой направлении, если у автомобиля оперативной службы включены проблесковый маячок синего цвета и специальный звуковой сигнал?', 'Согласно пункту 2 статьи 51 Закона Грузии «О дорожном движении», участники дорожного движения обязаны уступить дорогу и освободить проезжую часть транспортному средству оперативной службы, у которого включены проблесковый маячок синего цвета и специальный звуковой сигнал. Закон четко обязывает водителя предоставлять преимущество только данному оперативному транспортному средству.', 1, '2', 'Только водителям автомобиля оперативной службы и трактора', 'Только водителю автомобиля оперативной службы', 'Водителям всех транспортных средств', NULL, 29, '{4}'::int[], NULL, 'Привет! Запомни: как только ты видишь или слышишь спецтранспорт (скорую, полицию или пожарную) с включенным синим маячком и сиреной, твоя главная обязанность — уступить им дорогу. Закон дает преимущество только им. В отношении других транспортных средств действуют общие правила проезда перекрестков.', 'ticket_media/new/ticketIMG-1587.jpg'),
(1587, 'en', 'The driver of which vehicle is the bus driver obligated to yield to, if moving in the direction of the arrow, provided the emergency vehicle has its blue flashing beacon and siren activated?', 'According to Article 51, Clause 2 of the Law of Georgia ''On Road Traffic'', road users are obliged to yield and clear the road for emergency service vehicles that have their blue flashing beacon and siren activated. The law explicitly mandates that the driver must provide priority only to the specific emergency vehicle.', 1, '2', 'Only to the drivers of the emergency vehicle and the tractor', 'Only to the driver of the emergency vehicle', 'To the drivers of all transport vehicles', NULL, 29, '{4}'::int[], NULL, 'Hello! Remember: as soon as you see or hear an emergency vehicle (ambulance, police, or fire truck) with its blue beacon and siren on, your primary duty is to clear the way for them. The law grants priority only to them. For all other vehicles, the standard right-of-way rules for intersections apply.', 'ticket_media/new/ticketIMG-1587.jpg'),
(1588, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ტრაქტორის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში თუ ოპერატიული სამსახურის ავტომობილს ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა და ხმოვანი სიგნალები?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად,არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც. გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე კანონის 51-ე მუხლის მე-2 პუნქტის თანახმად, საგზაო მოძრაობის მონაწილეები ვალდებული არიან, ოპერატიული ან სპეციალური სამსახურის სატრანსპორტო საშუალების მოახლოებისას, რომელსაც ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა სიგნალი და ხმოვანი სიგნალი ან/და რომელიც ხმამაღლამოლაპარაკე ხელსაწყოთი იძლევა სიგნალს, მას, აგრეთვე მის მიერ გასაცილებელ სატრანსპორტო საშუალებას, რომელსაც ჩართული აქვს ახლო განათების ფარები, გაუთავისუფლონ სავალ ნაწილზე ადგილი, ხოლო აუცილებლობის შემთხვევაში − გაჩერდნენ.', 1, '3', 'მხოლოდ ოპერატიული სამსახურის ავტომობილის მძღოლის მიმართ', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'როგორც ოპერატიული სამსახურის ავტომობილის, ასევე ავტობუსის მძღოლის მიმართ', NULL, 10, '{7}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ოპერატიული მანქანა (სირენითა და ციმციმით) პრიორიტეტულია ნებისმიერ შემთხვევაში. ავტობუსს კი გზას უთმობ იმიტომ, რომ ის გზაჯვარედინის გავლის წესების მიხედვით (მაგალითად, მთავარი გზა ან მარჯვენა მხარე) შენზე უპირატესია. ამიტომ, ორივე მათგანს უნდა გაატარო!', 'ticket_media/new/ticketIMG-1588.jpg'),
(1588, 'ru', 'Водителю трактора, движущемуся в направлении стрелки, необходимо уступить дорогу водителю какого транспортного средства, если у автомобиля оперативной службы включен проблесковый маячок синего цвета и звуковой сигнал?', 'Согласно пункту 2 статьи 51 Закона Грузии «О дорожном движении», водитель обязан уступить дорогу транспортному средству оперативной службы при включенных специальных сигналах. Кроме того, согласно правилам проезда перекрестков (статья 36), трактор обязан уступить дорогу автобусу, если тот движется по главной дороге или приближается справа. Таким образом, обязанность уступить дорогу распространяется на обоих участников движения.', 1, '3', 'Только водителю автомобиля оперативной службы', 'Только водителю автобуса', 'Как водителю автомобиля оперативной службы, так и водителю автобуса', NULL, 10, '{7}'::int[], NULL, 'Привет! Помни, что оперативный автомобиль (с сиреной и маячком) всегда имеет преимущество. А автобусу ты уступаешь дорогу, потому что согласно правилам проезда перекрестков (например, если он на главной дороге или справа от тебя), у него есть преимущество перед тобой. Поэтому нужно пропустить обоих!', 'ticket_media/new/ticketIMG-1588.jpg'),
(1588, 'en', 'To the driver of which vehicle must the tractor driver yield when moving in the direction of the arrow, if the emergency service vehicle has its blue flashing beacon and sound signals switched on?', 'According to Article 51, Clause 2 of the Law of Georgia ''on Road Traffic'', a driver is obligated to yield to an emergency service vehicle when its special signals are activated. Furthermore, according to intersection passage rules (Article 36), the tractor must also yield to the bus if it is on the main road or approaching from the right. Therefore, the obligation to yield applies to both vehicles.', 1, '3', 'Only to the driver of the emergency service vehicle', 'Only to the driver of the bus', 'To both the driver of the emergency service vehicle and the driver of the bus', NULL, 10, '{7}'::int[], NULL, 'Hello! Remember that an emergency vehicle (with siren and flashing lights) always has priority. As for the bus, you must yield to it because, according to the rules of intersection passage (for example, if it is on the main road or approaching from your right), it has priority over you. Therefore, you must yield to both!', 'ticket_media/new/ticketIMG-1588.jpg'),
(1590, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „გ“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე კანონის 44-ე მუხლის პირველი პუნქტის „ე“ ქვეპუნქტის თანახმად, საცხოვრებელი ზონიდან გამოსვლისას საგზაო მოძრაობის მონაწილემ, გადაკვეთებზე გზა უნდა დაუთმოს სხვა საგზაო მოძრაობის მონაწილეს.', 1, '1', 'მხოლოდ კვადროციკლის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც კვადროციკლის, ასევე მსუბუქი ავტომობილის მძღოლის მიმართ', NULL, 29, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს ოქროს წესი: „მარჯვენა მხარის წესი“. თუ ორივე სატრანსპორტო საშუალება თანაბარმნიშვნელოვან გზაზეა, გზა უნდა დაუთმო იმას, ვინც შენს მარჯვნივ არის. კვადროციკლიც ისეთივე სატრანსპორტო საშუალებაა გზაზე, როგორც ავტომობილი, ამიტომ მასაც ისეთივე პატივისცემით უნდა მოეპყრო, როგორც სხვა მძღოლებს!', 'ticket_media/new/ticketIMG-1590.jpg'),
(1590, 'ru', 'По отношению к водителю какого транспортного средства у водителя автобуса возникает обязанность уступить дорогу при движении в направлении стрелки?', 'Согласно статье 36 Закона Грузии «О дорожном движении», на перекрестке равнозначных дорог приоритет имеет транспортное средство, приближающееся справа. Квадроцикл, как и легковой автомобиль, является безрельсовым транспортным средством, поэтому их обязанности и приоритеты движения регулируются общими правилами. Поскольку квадроцикл приближается к автобусу с правой стороны, водитель автобуса обязан уступить ему дорогу.', 1, '1', 'Только по отношению к водителю квадроцикла', 'Только по отношению к водителю легкового автомобиля', 'Как по отношению к водителю квадроцикла, так и по отношению к водителю легкового автомобиля', NULL, 29, '{4,6}'::int[], NULL, 'Привет! Помни золотое правило: «Правило правой руки». Если оба транспортных средства находятся на равнозначной дороге, ты должен уступить тому, кто находится справа от тебя. Квадроцикл — это такое же транспортное средство на дороге, как и автомобиль, поэтому к нему нужно относиться с таким же вниманием, как и к другим участникам движения!', 'ticket_media/new/ticketIMG-1590.jpg'),
(1590, 'en', 'Towards the driver of which vehicle does the bus driver have an obligation to yield the right of way when moving in the direction of the arrow?', 'According to Article 36 of the Law of Georgia ''On Road Traffic'', at an intersection of equal roads, priority is given to the vehicle approaching from the right. A quad bike, like a passenger car, is a non-rail vehicle; therefore, their obligations and movement priorities are governed by the general rules. Since the quad bike is approaching the bus from the right side, the bus driver is obligated to yield the right of way.', 1, '1', 'Only towards the driver of the quad bike', 'Only towards the driver of the passenger car', 'Towards both the driver of the quad bike and the driver of the passenger car', NULL, 29, '{4,6}'::int[], NULL, 'Hello! Remember the golden rule: ''The right-hand rule''. If both vehicles are on an equal-priority road, you must yield to the one on your right. A quad bike is just as much a vehicle on the road as a car, so you must treat it with the same priority as other drivers!', 'ticket_media/new/ticketIMG-1590.jpg'),
(1593, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის პირველი დანართის 1.7.2-1.7.7 პუნქტის თანახმად, საგზაო ნიშანი 1.7.3 „მეორეხარისხოვანი გზის შეერთება“ (შეერთება მარცხნიდან – 1.7.3, 1.7.5 და 1.7.7) − ისეთ გზასთან გადაკვეთა ან ისეთ გზასთან შეერთება, რომელზე მოძრავ მძღოლსაც აქვს გზის დათმობის ვალდებულება. ამავე დანართის 2.5 პუნქტის თანახმად, საგზაო ნიშანი 2.5 „შემხვედრი მოძრაობის უპირატესობა” - უკრძალავს მძღოლს გზის ვიწრო მონაკვეთზე შესვლას, თუ ეს აძნელებს საპირისპირო მიმართულებით მოძრაობას. მძღოლი ვალდებულია გზა დაუთმოს შემხვედრ სატრან¬სპორტო საშუალებას, რომელიც მოპირდაპირე მისასვლელთან ან გზის ვიწრო მონაკვეთზე იმყოფება.', 1, '3', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'მხოლოდ ლურჯი ავტომობილის მძღოლის მიმართ', 'არცერთი ავტომობილის მძღოლის მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მთავარ გზაზე მყოფ მძღოლს პრიორიტეტი აქვს. თუ შენს მიმართულებაზე არ არის ნიშანი, რომელიც გზის დათმობას გავალდებულებს, თავისუფლად განაგრძე მოძრაობა. ყვითელი მანქანა ამ შემთხვევაში არავის უთმობს!', 'ticket_media/new/ticketIMG-1593.jpg'),
(1593, 'ru', 'Водитель какого автомобиля обязан уступить дорогу водителю желтого автомобиля при движении по стрелке?', 'Согласно Закону Грузии «О дорожном движении», если движение на перекрестке регулируется светофором или дорожными знаками, водитель действует в соответствии с их требованиями. Поскольку желтый автомобиль находится на главной дороге или не имеет предписаний уступать дорогу, он пользуется преимуществом и не обязан уступать дорогу другим транспортным средствам.', 1, '3', 'Только водителю грузового автомобиля', 'Только водителю синего автомобиля', 'Никому из водителей', NULL, 29, '{6}'::int[], NULL, 'Привет! Запомни: водитель на главной дороге имеет преимущество. Если на твоем пути нет знака, обязывающего уступить дорогу, смело продолжай движение. В данной ситуации желтый автомобиль никому не обязан уступать!', 'ticket_media/new/ticketIMG-1593.jpg'),
(1593, 'en', 'Which vehicle driver is the driver of the yellow vehicle obligated to yield to when moving in the direction of the arrow?', 'In accordance with the Law of Georgia on Road Traffic, if traffic at an intersection is regulated by traffic lights or road signs, the driver must act in accordance with their requirements. Since the yellow vehicle is moving on the priority road or has no obligation to yield, it holds the right of way and is not required to yield to other drivers.', 1, '3', 'Only to the truck driver', 'Only to the blue vehicle driver', 'None of the vehicle drivers', NULL, 29, '{6}'::int[], NULL, 'Hi! Remember, the driver on the priority road has the right of way. If there is no sign forcing you to yield, you are free to proceed. In this case, the yellow car doesn''t need to yield to anyone!', 'ticket_media/new/ticketIMG-1593.jpg'),
(1596, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში, თუ გზაჯვარედინის მარჯვენა მხრიდან შემომავალი გზის საფარი გრუნტოვანია?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „გ“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა ხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას უპირატესობა აქვს ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა. ამავე მუხლის მე-6 პუნქტის თანახმად, თუ საგზაო ნიშნით სხვა რამ არ არის გათვალისწინებული, გრუნტოვანი გზიდან იმ გზაზე გასვლისას, რომელიც არ არის გრუნტოვანი გზა, მძღოლი ვალდებულია გზა დაუთმოს ამ გზაზე მოძრავ სატრანსპორტო საშუალებას. ამავე კანონის მე-5 მუხლის 37-ე პუნქტის თანახმად ღორღიან ან გრუნტოვან გზაზე უშუალოდ გზაჯვარედინის წინ, გზის მკვრივსაფარიანი უბნის არსებობა არ ათანაბრებს მას მკვრივსაფარიან გზასთან.', 1, '1', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ ავტობუსის და სატვირთო ავტომობილის მძღოლების მიმართ', 'როგორც ავტობუსის, ასევე მსუბუქი და სატვირთო ავტომობილების მძღოლების მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ მთავარი გზა ყოველთვის პრიორიტეტულია. რადგან მარჯვენა მხარეს მყოფი მძღოლი გრუნტოვანი გზიდან მოდის, მას უპირატესობა არ აქვს. შესაბამისად, ის ვალდებულია დაგითმოს გზა, მიუხედავად იმისა, რა ტიპის მანქანას მართავს.', 'ticket_media/new/ticketIMG-1596.jpg'),
(1596, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю мотоцикла при движении в направлении стрелки, если дорога, примыкающая справа к перекрестку, является грунтовой?', 'Согласно пункту 6 статьи 36 Закона «О дорожном движении», при выезде с грунтовой дороги на дорогу с твердым покрытием водитель обязан уступить дорогу всем транспортным средствам, движущимся по этой дороге. Согласно пункту 37 статьи 5, наличие участка с твердым покрытием непосредственно перед перекрестком на грунтовой дороге не приравнивает ее к дороге с твердым покрытием. Таким образом, водитель мотоцикла находится на главной дороге, и обязанность уступить дорогу возлагается только на того, кто въезжает с грунтовой дороги.', 1, '1', 'Только водителю легкового автомобиля', 'Только водителям автобуса и грузового автомобиля', 'Водителям автобуса, а также легкового и грузового автомобилей', NULL, 29, '{2}'::int[], NULL, 'Привет! Запомни: главная дорога всегда имеет приоритет. Поскольку водитель справа выезжает с грунтовой дороги, он не имеет преимущества. Следовательно, он обязан уступить тебе дорогу, независимо от того, какой именно автомобиль он ведет.', 'ticket_media/new/ticketIMG-1596.jpg'),
(1596, 'en', 'To the driver of which vehicle must the motorcycle driver yield, when moving in the direction of the arrow, if the road entering the intersection from the right is a dirt road?', 'According to Article 36, Clause 6 of the Law on Road Traffic, when entering a paved road from an unpaved (dirt) road, the driver must yield to all vehicles moving on the paved road. Pursuant to Article 5, Clause 37, a paved patch immediately before an intersection does not classify the dirt road as a paved road. Therefore, the motorcyclist has the right of way, and only the driver entering from the dirt road is required to yield.', 1, '1', 'Only to the driver of the passenger car', 'Only to the drivers of the bus and the truck', 'To the drivers of the bus, as well as the passenger car and the truck', NULL, 29, '{2}'::int[], NULL, 'Hello! Remember, the main road always has priority. Since the driver on the right is coming from a dirt road, they do not have the right of way. Therefore, they are obligated to yield to you, regardless of what type of vehicle they are driving.', 'ticket_media/new/ticketIMG-1596.jpg'),
(1597, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში, თუ გზაჯვარედინის მარჯვენა მხრიდან შემომავალი გზის საფარი გრუნტოვანია?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-6 პუნქტის თანახმად, თუ საგზაო ნიშნით სხვა რამ არ არის გათვალისწინებული, გრუნტოვანი გზიდან იმ გზაზე გასვლისას, რომელიც არ არის გრუნტოვანი გზა, მძღოლი ვალდებულია გზა დაუთმოს ამ გზაზე მოძრავ სატრანსპორტო საშუალებას. ამავე კანონის მე-5 მუხლის 37-ე პუნქტის თანახმად ღორღიან ან გრუნტოვან გზაზე უშუალოდ გზაჯვარედინის წინ, გზის მკვრივსაფარიანი უბნის არსებობა არ ათანაბრებს მას მკვრივსაფარიან გზასთან.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ მოტოციკლის და სატვირთო ავტომობილის მძღოლების მიმართ', 'როგორც მოტოციკლის, ასევე მსუბუქი და სატვირთო ავტომობილების მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გახსოვდეთ: გრუნტოვანი გზა ყოველთვის მეორეხარისხოვანია. რადგან სხვა გზები მთავარია, მათზე მოძრავმა მძღოლებმა უპირატესობით უნდა ისარგებლონ, მიუხედავად იმისა, რა ტიპის სატრანსპორტო საშუალებას მართავენ.', 'ticket_media/new/ticketIMG-1597.jpg'),
(1597, 'ru', 'Водитель транспортного средства с какого направления обязан уступить дорогу водителю автобуса при движении по стрелке, если дорога, примыкающая справа к перекрестку, является грунтовой?', 'Согласно пункту 6 статьи 36 Закона Грузии «О дорожном движении», при выезде с грунтовой дороги на дорогу с твердым покрытием водитель обязан уступить дорогу всем транспортным средствам, движущимся по этой дороге. Пункт 37 статьи 5 того же Закона поясняет, что наличие участка с твердым покрытием непосредственно перед перекрестком не меняет статус грунтовой дороги на дорогу с твердым покрытием.', 1, '3', 'Только водителю легкового автомобиля', 'Только водителям мотоцикла и грузового автомобиля', 'Водителям мотоцикла, легкового и грузового автомобилей', NULL, 29, '{4}'::int[], NULL, 'Помните: грунтовая дорога всегда является второстепенной. Поскольку остальные дороги считаются главными, водители, движущиеся по ним, имеют преимущество, независимо от того, каким типом транспортного средства они управляют.', 'ticket_media/new/ticketIMG-1597.jpg'),
(1597, 'en', 'To which vehicle driver is the bus driver obligated to yield when moving in the direction of the arrow, if the road entering from the right side of the intersection is a dirt road?', 'According to Article 36, Clause 6 of the Law of Georgia on Road Traffic, when exiting a dirt road onto a paved road, the driver must yield to all vehicles moving on the paved road. Article 5, Clause 37 of the same law clarifies that the existence of a paved section immediately before an intersection does not elevate a dirt road to the status of a paved road.', 1, '3', 'Only to the driver of the passenger car', 'Only to the drivers of the motorcycle and the truck', 'To the drivers of the motorcycle, the passenger car, and the truck', NULL, 29, '{4}'::int[], NULL, 'Remember: a dirt road is always considered secondary. Since the other roads are primary, the drivers moving on them have the right of way, regardless of what type of vehicle they are driving.', 'ticket_media/new/ticketIMG-1597.jpg'),
(1598, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც ავტობუსის, ასევე მსუბუქი ავტომობილის მძღოლების მიმართ', NULL, 29, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს წესი: თუ შენ მეორეხარისხოვან გზაზე ხარ, შენი მიმართულება მნიშვნელოვანი არ არის — მთავარ გზაზე მყოფ ყველა მანქანას უნდა დაუთმო გზა, რადგან მათ უპირატესობა აქვთ. ამ შემთხვევაში, როგორც ავტობუსი, ისე მსუბუქი ავტომობილი მთავარ გზაზე მოძრაობენ.', 'ticket_media/new/ticketIMG-1598.jpg'),
(1598, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу мотоциклист при движении в направлении стрелки?', 'Согласно пункту 4 «а» статьи 36 Закона Грузии «О дорожном движении», на нерегулируемом перекрестке водитель, движущийся по второстепенной дороге, обязан уступить дорогу любому транспортному средству, находящемуся на главной дороге, независимо от их дальнейшего направления движения.', 1, '3', 'Только водителю автобуса', 'Только водителю легкового автомобиля', 'Как водителю автобуса, так и водителю легкового автомобиля', NULL, 29, '{0,2}'::int[], NULL, 'Привет! Запомни простое правило: если ты находишься на второстепенной дороге, неважно, куда ты собираешься повернуть — ты обязан уступить дорогу всем транспортным средствам на главной дороге. В данной ситуации и автобус, и легковой автомобиль имеют приоритет.', 'ticket_media/new/ticketIMG-1598.jpg'),
(1598, 'en', 'To which vehicle driver must the motorcycle driver yield when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''a'' of the Law of Georgia ''on Road Traffic'', at an unregulated intersection, a driver moving from a minor road must yield to any vehicle on the major road, regardless of their intended direction.', 1, '3', 'Only to the bus driver', 'Only to the passenger car driver', 'To both the bus and the passenger car drivers', NULL, 29, '{0,2}'::int[], NULL, 'Hello! Remember the golden rule: if you are on a minor road, your intended direction doesn''t matter—you must yield to all vehicles on the major road because they have the right of way. In this case, both the bus and the car are on the major road, so you must yield to both.', 'ticket_media/new/ticketIMG-1598.jpg'),
(1599, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! აქ მთავარია დააკვირდე ნიშნებს. თუ შენ მთავარ გზაზე ხარ, შენი გზა პირველია და არავის უთმობ. სწორი პასუხია 3, რადგან არცერთი სხვა მძღოლი არ გიშლის ხელს.', 'ticket_media/new/ticketIMG-1599.jpg'),
(1599, 'ru', 'Какому водителю транспортного средства обязан уступить дорогу водитель автобуса при движении в направлении стрелки?', 'В соответствии с пунктом 4 статьи 36 Закона Грузии «О дорожном движении», автобус движется по главной дороге или имеет преимущество в данной конфигурации, поэтому он не обязан уступать дорогу другим участникам движения.', 1, '3', 'Только водителю легкового автомобиля', 'Только водителю мотоцикла', 'Ни одному из водителей транспортных средств', NULL, 29, '{4}'::int[], NULL, 'Привет! Главное здесь — внимательно посмотреть на знаки приоритета. Если вы находитесь на главной дороге, вы обладаете преимуществом и никому не обязаны уступать. Верный ответ — 3, так как никто из других водителей не создает вам помех.', 'ticket_media/new/ticketIMG-1599.jpg'),
(1599, 'en', 'To which driver is the bus driver obligated to yield the right of way when moving in the direction of the arrow?', 'In accordance with Article 36, Paragraph 4 of the Law of Georgia ''On Road Traffic'', the bus is traveling on a major road or has priority in this configuration, therefore it is not obligated to yield to other road users.', 1, '3', 'Only to the driver of a passenger car', 'Only to the driver of a motorcycle', 'To none of the drivers of the vehicles', NULL, 29, '{4}'::int[], NULL, 'Hello! The key here is to look closely at the priority signs. If you are on the major road, you have the right of way and do not need to yield to anyone. The correct answer is 3, as none of the other drivers are obstructing your path.', 'ticket_media/new/ticketIMG-1599.jpg'),
(1600, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ქვეპუნქტების თანახმად,არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას.', 1, '2', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'მხოლოდ ლურჯი მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ თეთრი და ლურჯი მსუბუქი ავტომობილების მძღოლების მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს ოქროს წესი: როცა მარცხნივ უხვევ, გზა დაუთმე მათ, ვინც საპირისპირო მხრიდან პირდაპირ მოდის. რადგან ლურჯი მანქანა პირდაპირ მიდის, ის შენი პრიორიტეტული სამიზნეა. იყავი ყურადღებით!', 'ticket_media/new/ticketIMG-1600.jpg'),
(1600, 'ru', 'Водителю какого автомобиля обязан уступить дорогу водитель мотоцикла при движении по указанному стрелкой направлению?', 'Согласно подпункту «д» пункта 4 статьи 36 Закона Грузии «О дорожном движении», при повороте налево водитель обязан уступить дорогу транспортному средству, движущемуся со встречного направления прямо или направо. Синий автомобиль движется по главной дороге прямо, следовательно, водитель мотоцикла, совершающий маневр, обязан уступить ему дорогу.', 1, '2', 'Только водителю автобуса', 'Только водителю синего легкового автомобиля', 'Только водителям белого и синего легковых автомобилей', NULL, 29, '{2}'::int[], NULL, 'Привет! Запомни золотое правило: когда поворачиваешь налево, уступи дорогу тем, кто едет навстречу прямо. Поскольку синий автомобиль едет прямо, он имеет преимущество. Будь внимателен на дороге!', 'ticket_media/new/ticketIMG-1600.jpg'),
(1600, 'en', 'To which vehicle''s driver must the motorcycle driver yield when proceeding in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''d'' of the Law of Georgia on Road Traffic, when turning left, a driver must yield to a vehicle approaching from the opposite direction that is proceeding straight or turning right. The blue car is moving straight on the main road; therefore, the motorcycle driver performing the maneuver is obligated to yield.', 1, '2', 'Only to the bus driver', 'Only to the driver of the blue passenger car', 'Only to the drivers of the white and blue passenger cars', NULL, 29, '{2}'::int[], NULL, 'Hello! Remember the golden rule: when turning left, always yield to those coming from the opposite direction moving straight. Since the blue car is moving straight, it has the right of way. Stay alert!', 'ticket_media/new/ticketIMG-1600.jpg'),
(1601, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას.', 1, '1', 'მხოლოდ მოტოციკლის და ლურჯი მსუბუქი ავტომობილის მძღოლების მიმართ', 'მხოლოდ თეთრი მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც მოტოციკლის, ასევე თეთრი და ლურჯი მსუბუქი ავტომობილების მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მთავარ გზაზე მოძრავ სატრანსპორტო საშუალებებს ყოველთვის აქვთ პრიორიტეტი. ვინაიდან ავტობუსი მეორეხარისხოვან გზაზეა, მან უნდა დაუთმოს გზა ყველას, ვინც მთავარ გზაზე მოდის!', 'ticket_media/new/ticketIMG-1601.jpg'),
(1601, 'ru', 'Водителям каких транспортных средств обязан уступить дорогу водитель автобуса при движении в указанном стрелкой направлении?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», автобус движется по второстепенной дороге, в то время как мотоцикл и синий автомобиль находятся на главной дороге. Таким образом, водитель автобуса обязан уступить дорогу транспортным средствам, имеющим преимущество главной дороги.', 1, '1', 'Только водителям мотоцикла и синего легкового автомобиля', 'Только водителю белого легкового автомобиля', 'Водителям мотоцикла, а также белого и синего легковых автомобилей', NULL, 29, '{4}'::int[], NULL, 'Привет! Запомни, что транспортные средства на главной дороге всегда имеют приоритет. Так как автобус находится на второстепенной дороге, он должен уступить дорогу всем, кто едет по главной!', 'ticket_media/new/ticketIMG-1601.jpg'),
(1601, 'en', 'Which vehicle drivers is the bus driver obliged to yield to when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4 of the Law of Georgia ''On Road Traffic'', the bus is moving on a minor road, while the motorcycle and the blue car are on the major road. Therefore, the bus driver is obliged to yield to the vehicles on the major road.', 1, '1', 'Only the drivers of the motorcycle and the blue passenger car', 'Only the driver of the white passenger car', 'Drivers of the motorcycle, as well as the white and blue passenger cars', NULL, 29, '{4}'::int[], NULL, 'Hello! Remember that vehicles on the major road always have priority. Since the bus is on a minor road, it must yield to everyone coming from the major road!', 'ticket_media/new/ticketIMG-1601.jpg'),
(1602, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „გ“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას უპირატესობა აქვს ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა. დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '2', 'მხოლოდ B ტრამვაის მძღოლის მიმართ', 'მხოლოდ A და B ტრამვაების მძღოლების მიმართ', 'მხოლოდ A ტრამვაის და მსუბუქი ავტომობილის მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: გზაჯვარედინზე ტრამვაი ყოველთვის პრივილეგირებულია. რადგან ყვითელი ავტომობილი ტრამვაი არ არის, ის ვალდებულია დაუთმოს გზა ორივე ტრამვაის (A და B), რადგან მათ აქვთ უპირატესობა მიუხედავად იმისა, თუ საით მოძრაობენ.', 'ticket_media/new/ticketIMG-1602.jpg'),
(1602, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водитель желтого автомобиля при движении в направлении стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», на нерегулируемом перекрестке рельсовые транспортные средства имеют преимущество перед безрельсовыми независимо от направления их движения. Так как желтый автомобиль является безрельсовым транспортным средством, он обязан уступить дорогу обоим трамваям (A и B).', 1, '2', 'Только водителю трамвая B', 'Только водителям трамваев A и B', 'Только водителю трамвая A и водителю легкового автомобиля', NULL, 29, '{6}'::int[], NULL, 'Привет! Запомни золотое правило: на перекрестке у трамвая всегда приоритет. Поскольку твой желтый автомобиль — это безрельсовое транспортное средство, ты обязан уступить дорогу обоим трамваям (A и B), так как они имеют преимущество независимо от направления движения.', 'ticket_media/new/ticketIMG-1602.jpg'),
(1602, 'en', 'To which vehicle''s driver must the driver of the yellow car yield if moving in the direction of the arrow?', 'According to Article 36, Paragraph 4 of the Georgian Law on Road Traffic, at an unregulated intersection, rail vehicles have priority over non-rail vehicles, regardless of their direction of movement. Since the yellow car is a non-rail vehicle, it is obligated to yield to both trams (A and B).', 1, '2', 'Only the driver of tram B', 'Only the drivers of trams A and B', 'Only the driver of tram A and the driver of the passenger car', NULL, 29, '{6}'::int[], NULL, 'Hello! Remember the golden rule: at an intersection, the tram always has priority. Since your yellow car is a non-rail vehicle, you are obligated to yield to both trams (A and B), as they have the right of way regardless of the direction they are traveling.', 'ticket_media/new/ticketIMG-1602.jpg'),
(1603, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში, თუ სასწრაფო სამედიცინო დახმარების ავტომობილს ჩართული აქვს ჯურჯი მოელვარე სპეციალური ციმციმა და ხმოვანი სიგნალები?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „დ“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ამავე კანონის 51-ე მუხლის მე-2 პუნქტის თანახმად, საგზაო მოძრაობის მონაწილეები ვალდებული არიან, ოპერატიული ან სპეციალური სამსახურის სატრანსპორტო საშუალების მოახლოებისას, რომელსაც ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა სიგნალი და ხმოვანი სიგნალი ან/და რომელიც ხმამაღლამოლაპარაკე ხელსაწყოთი იძლევა სიგნალს, მას, აგრეთვე მის მიერ გასაცილებელ სატრანსპორტო საშუალებას, რომელსაც ჩართული აქვს ახლო განათების ფარები, გაუთავისუფლონ სავალ ნაწილზე ადგილი, ხოლო აუცილებლობის შემთხვევაში − გაჩერდნენ.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ სასწრაფო სამედიცინო დახმარების ავტომობილის მძღოლის მიმართ', 'როგორც მსუბუქი ავტომობილის, ასევე სასწრაფო სამედიცინო დახმარების ავტომობილის მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გახსოვდეს, აქ ორი წესი მოქმედებს ერთდროულად: 1. გზაჯვარედინზე მოხვევისას პრიორიტეტი საპირისპიროდ მოძრავ ავტომობილს აქვს, და 2. სასწრაფოს, რომელსაც ციმციმა აქვს ჩართული, ყოველთვის უნდა დაუთმო გზა, რადგან მას აქვს უპირატესობა ყველას მიმართ.', 'ticket_media/new/ticketIMG-1603.jpg'),
(1603, 'ru', 'Водитель какого автомобиля обязан уступить дорогу водителю автобуса при движении по стрелке, если у автомобиля скорой медицинской помощи включены проблесковый маячок синего цвета и специальные звуковые сигналы?', 'Согласно пункту 4 «д» статьи 36 Закона Грузии «О дорожном движении», при повороте налево или развороте водитель обязан уступить дорогу встречному транспорту (легковому автомобилю). Пункт 2 статьи 51 того же закона обязывает участников движения уступать дорогу оперативным службам (скорой помощи) с включенными спецсигналами.', 1, '3', 'Только водителю легкового автомобиля', 'Только водителю автомобиля скорой медицинской помощи', 'Как водителю легкового автомобиля, так и водителю автомобиля скорой медицинской помощи', NULL, 29, '{4}'::int[], NULL, 'Помни, здесь работают два правила одновременно: 1. При повороте на перекрестке приоритет у встречного автомобиля, и 2. Скорой помощи с включенными спецсигналами нужно уступать дорогу всегда, так как у нее преимущество перед всеми остальными участниками движения.', 'ticket_media/new/ticketIMG-1603.jpg'),
(1603, 'en', 'To which vehicle driver is the bus driver obliged to yield the right of way when moving in the direction of the arrow, if the ambulance vehicle has its blue flashing beacon and audible signals turned on?', 'According to Article 36, paragraph 4, subparagraph ''d'' of the Law of Georgia ''On Road Traffic'', a driver turning left must yield to oncoming vehicles (the light vehicle). Article 51, paragraph 2 of the same law mandates that all road users must yield the right of way to emergency vehicles with activated blue beacons and sirens.', 1, '3', 'Only to the driver of the light vehicle', 'Only to the driver of the ambulance vehicle', 'To both the driver of the light vehicle and the driver of the ambulance vehicle', NULL, 29, '{4}'::int[], NULL, 'Remember, two rules apply here simultaneously: 1. When turning at an intersection, the oncoming vehicle has priority, and 2. You must always yield to an ambulance with activated signals, as it has priority over everyone else on the road.', 'ticket_media/new/ticketIMG-1603.jpg'),
(1605, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ სარგებლობს უპირატესობით ყვითელი ავტომობილის მძღოლი, ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 32-ე მუხლის მე-12 პუნქტის თანახმად, თუ სატრანსპორტო საშუალებების მოძრაობის ტრაექტორიები იკვეთება, ხოლო გავლის რიგითობა განსაზღვრული არ არის, მძღოლმა გზა უნდა დაუთმოს იმ სატრანსპორტო საშუალებას, რომელიც მას მარჯვნიდან უახლოვდება.', 1, '3', 'მხოლოდ თეთრი ავტომობილის მძღოლის მიმართ', 'მხოლოდ მწვანე ავტომობილის მძღოლის მიმართ', 'როგორც თეთრი, ასევე მწვანე ავტომობილის მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის წესი“: თუ გზაჯვარედინზე არ არის მანიშნებლები, გზა უნდა დაუთმო მას, ვინც მარჯვენა მხრიდან მოდის. რადგან ყვითელი ავტომობილი ორივესთვის მარჯვნივ იმყოფება, ის პირველი გადის!', 'ticket_media/new/ticketIMG-1605.jpg'),
(1605, 'ru', 'По отношению к водителю какого автомобиля имеет преимущество водитель желтого автомобиля при движении по направлению стрелки?', 'Согласно пункту 12 статьи 32 Закона Грузии «О дорожном движении», в случаях, когда траектории движения пересекаются, а очередность проезда не установлена, водитель обязан уступить дорогу транспортному средству, приближающемуся справа. В данной ситуации водитель желтого автомобиля имеет преимущество, так как для других участников движения он находится справа, либо он сам является помехой справа для остальных.', 1, '3', 'Только по отношению к водителю белого автомобиля', 'Только по отношению к водителю зеленого автомобиля', 'Как по отношению к водителю белого, так и зеленого автомобиля', NULL, 29, '{6}'::int[], NULL, 'Привет! Главное правило здесь — «правило правой руки»: если знаки приоритета отсутствуют, ты обязан пропустить того, кто справа. Поскольку желтый автомобиль находится справа от обоих других, у него есть законное преимущество проехать первым!', 'ticket_media/new/ticketIMG-1605.jpg'),
(1605, 'en', 'The driver of which vehicle does the driver of the yellow vehicle have priority over when moving in the direction of the arrow?', 'According to Article 32, paragraph 12 of the Law of Georgia ''On Road Traffic'', when vehicle paths intersect and the right of way is not determined by signs or signals, a driver must yield to the vehicle approaching from the right. In this scenario, the yellow vehicle has priority because, relative to the intersection layout, it possesses the right-hand advantage over the other vehicles.', 1, '3', 'Only the driver of the white vehicle', 'Only the driver of the green vehicle', 'Both the drivers of the white and green vehicles', NULL, 29, '{6}'::int[], NULL, 'Hello! Remember the ''right-hand rule'': if there are no signs at the intersection, you must yield to the vehicle coming from your right. Since the yellow car is to the right of both other vehicles, it has the priority to go first!', 'ticket_media/new/ticketIMG-1605.jpg'),
(1606, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'არცერთი ავტომობილის მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როცა შენ მთავარ გზაზე ხარ, შენ გაქვს უპირატესობა. ვინაიდან ყვითელი ავტომობილი მთავარ გზაზე მოძრაობს, მან არავის უნდა დაუთმოს გზა, რადგან დანარჩენი მანქანები მეორეხარისხოვან გზაზე არიან.', 'ticket_media/new/ticketIMG-1606.jpg'),
(1606, 'ru', 'Водитель какого автомобиля обязан уступить дорогу водителю желтого автомобиля при движении по направлению стрелки?', 'Согласно пункту 4 «а» статьи 36 Закона Грузии «О дорожном движении», желтый автомобиль движется по главной дороге, следовательно, он имеет преимущество перед легковым и грузовым автомобилями, которые находятся на второстепенной дороге.', 1, '3', 'Только водителю легкового автомобиля', 'Только водителю грузового автомобиля', 'Ни одному из водителей', NULL, 29, '{6}'::int[], NULL, 'Привет! Помни, что если ты на главной дороге, у тебя есть преимущество. Так как желтый автомобиль едет по главной, ему не нужно никому уступать, так как остальные участники находятся на второстепенной дороге.', 'ticket_media/new/ticketIMG-1606.jpg'),
(1606, 'en', 'To which vehicle driver is the driver of the yellow vehicle obligated to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Clause 4, Sub-clause ''a'' of the Law of Georgia ''on Road Traffic'', the yellow vehicle is moving on the main road, therefore it has the right of way over the passenger car and the truck, which are on the secondary road.', 1, '3', 'Only to the driver of the passenger car', 'Only to the driver of the truck', 'To none of the drivers', NULL, 29, '{6}'::int[], NULL, 'Hello! Remember that when you are on the main road, you have the priority. Since the yellow vehicle is moving on the main road, it does not need to yield to anyone, as the other vehicles are on a secondary road.', 'ticket_media/new/ticketIMG-1606.jpg'),
(1611, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'არცერთი ავტომობილის მძღოლების მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, თუ შენ მთავარ გზაზე მიდიხარ, პრიორიტეტი შენია! რადგან მოტოციკლისტი მთავარ გზაზეა, მას არ ევალება ვინმეს გზა დაუთმოს, ამიტომ სწორი პასუხია: არცერთი.', 'ticket_media/new/ticketIMG-1611.jpg'),
(1611, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу мотоциклисту, движущемуся в направлении стрелки?', 'В соответствии с пунктом 4 статьи 36 Закона Грузии «О дорожном движении», мотоциклист движется по главной дороге. Поскольку он находится на приоритетной дороге, он не обязан уступать дорогу ни одному из водителей, находящихся на второстепенной дороге.', 1, '3', 'Только водителю грузового автомобиля', 'Только водителю легкового автомобиля', 'Ни одному из водителей', NULL, 29, '{2}'::int[], NULL, 'Привет! Запомни: если ты едешь по главной дороге, у тебя приоритет! Так как мотоциклист находится на главной дороге, он не обязан уступать дорогу остальным, поэтому правильный ответ — ни одному.', 'ticket_media/new/ticketIMG-1611.jpg'),
(1611, 'en', 'Which vehicle driver is the motorcycle rider required to yield to when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4 of the Law of Georgia ''On Road Traffic'', the motorcycle rider is traveling on a major road. Since the rider is on a priority road, there is no legal obligation to yield to any drivers located on secondary roads.', 1, '3', 'Only to the truck driver', 'Only to the car driver', 'To neither of the drivers', NULL, 29, '{2}'::int[], NULL, 'Hello! Remember: if you are on a major road, you have the priority! Since the motorcycle rider is on the main road, they are not required to yield to anyone else, so the correct answer is: neither.', 'ticket_media/new/ticketIMG-1611.jpg'),
(1612, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ სარგებლობს უპირატესობით ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც სატვირთო, ასევე მსუბუქი ავტომობილების მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! აქ მთავარია დავიმახსოვროთ, რომ კანონი უპირატესობას ანიჭებს გზის სტატუსს და არა ავტომობილის კლასს. თუ ავტობუსი მთავარ გზაზეა, მან გზა უნდა დაუთმოს ყველას, ვინც ამ გზაზეა, იქნება ეს მსუბუქი თუ სატვირთო მანქანა.', 'ticket_media/new/ticketIMG-1612.jpg'),
(1612, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса, движущемуся в направлении стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», приоритет предоставляется транспортному средству, движущемуся по главной дороге. Закон не делает различий между типом автомобиля (грузовой или легковой), поэтому приоритет распространяется на все типы транспортных средств.', 1, '3', 'Только по отношению к водителю грузового автомобиля', 'Только по отношению к водителю легкового автомобиля', 'Как по отношению к водителям грузовых, так и легковых автомобилей', NULL, 29, '{4}'::int[], NULL, 'Привет! Самое важное здесь — помнить, что закон отдает приоритет статусу дороги, а не классу автомобиля. Если автобус находится на главной дороге, он имеет преимущество перед любым другим транспортным средством, будь то легковой или грузовой автомобиль.', 'ticket_media/new/ticketIMG-1612.jpg'),
(1612, 'en', 'Towards which vehicle driver does the bus driver have priority when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4 of the Law of Georgia ''On Road Traffic'', priority is granted to the vehicle moving on the major road. The law does not distinguish between vehicle types (truck or passenger car); therefore, the priority applies to all types of vehicles.', 1, '3', 'Only towards the driver of a truck', 'Only towards the driver of a passenger car', 'Towards the drivers of both trucks and passenger cars', NULL, 29, '{4}'::int[], NULL, 'Hello! The key here is to remember that the law grants priority based on the status of the road, not the class of the vehicle. If the bus is on the major road, it has priority over any other vehicle, whether it is a passenger car or a truck.', 'ticket_media/new/ticketIMG-1612.jpg'),
(1613, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება თეთრი მსუბუქი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „გ“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას უპირატესობა აქვს ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '4', 'მხოლოდ ტრამვაისა და ავტობუსის მძღოლების მიმართ', 'მხოლოდ ავტობუსისა და მოტოციკლის მძღოლების მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', 'მხოლოდ ტრამვაის მძღოლის მიმართ', 29, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი ოქროს წესი: ტრამვაის გზაჯვარედინზე ყოველთვის აქვს უპირატესობა ურელსო სატრანსპორტო საშუალებებთან მიმართებაში, მიუხედავად იმისა, თუ საიდან მოდის ის. ამიტომ, შენი მოძრაობის მიმართულების მიუხედავად, ტრამვაი შენზე ადრე გაივლის.', 'ticket_media/new/ticketIMG-1613.jpg'),
(1613, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю белого легкового автомобиля при движении в направлении стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», на нерегулируемом перекрестке равнозначных дорог рельсовое транспортное средство (трамвай) имеет преимущество перед безрельсовыми транспортными средствами независимо от направления его движения.', 1, '4', 'Только водителям трамвая и автобуса', 'Только водителям автобуса и мотоцикла', 'Никому из водителей транспортных средств', 'Только водителю трамвая', 29, '{4}'::int[], NULL, 'Привет! Запомни главное золотое правило: трамвай на перекрестке всегда имеет преимущество перед безрельсовыми транспортными средствами, независимо от того, откуда он приближается. Поэтому, вне зависимости от направления вашего движения, трамвай проедет первым.', 'ticket_media/new/ticketIMG-1613.jpg'),
(1613, 'en', 'To which driver must the driver of the white passenger car yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4 of the Law of Georgia on Road Traffic, at an unregulated intersection of equal roads, a rail vehicle (tram) has priority over non-rail vehicles, regardless of the direction from which it is approaching.', 1, '4', 'Only to the drivers of the tram and the bus', 'Only to the drivers of the bus and the motorcycle', 'To none of the drivers of the transport vehicles', 'Only to the driver of the tram', 29, '{4}'::int[], NULL, 'Hello! Remember the main golden rule: at an intersection, a tram always has priority over non-rail vehicles, no matter where it is coming from. Therefore, regardless of your intended direction, the tram will pass first.', 'ticket_media/new/ticketIMG-1613.jpg'),
(1614, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „გ“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას უპირატესობა აქვს ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ ტრამვაის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც ტრამვაის, ასევე მსუბუქი ავტომობილის მძღოლების მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', 29, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს ორი ოქროს წესი: 1. ტრამვაი ყოველთვის მთავარია თანაბარმნიშვნელოვან გზაჯვარედინზე. 2. შენს მარჯვენა მხარეს მყოფ ურელსო ტრანსპორტს უნდა დაუთმო გზა. რადგან ტრამვაი და ავტომობილი ორივე გზის დათმობას მოითხოვენ, პასუხი 3 სწორია!', 'ticket_media/new/ticketIMG-1614.jpg'),
(1614, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю мотоцикла при движении в направлении стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», на нерегулируемом перекрестке равнозначных дорог рельсовое транспортное средство (трамвай) имеет преимущество перед безрельсовыми транспортными средствами, независимо от направления движения. В отношении безрельсовых транспортных средств действует «правило правой руки». Следовательно, водитель мотоцикла обязан уступить дорогу как трамваю (из-за его приоритета), так и легковому автомобилю, приближающемуся справа.', 1, '3', 'Только водителю трамвая', 'Только водителю легкового автомобиля', 'Как водителю трамвая, так и водителю легкового автомобиля', 'Никому из водителей транспортных средств', 29, '{2}'::int[], NULL, 'Привет! Запомни два золотых правила: 1. Трамвай всегда имеет преимущество на равнозначном перекрестке. 2. Уступай дорогу тем, кто справа от тебя. Поскольку и трамвай, и автомобиль имеют право на проезд перед тобой, вариант 3 — верный!', 'ticket_media/new/ticketIMG-1614.jpg'),
(1614, 'en', 'To which vehicle driver is the motorcycle driver obligated to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Clause 4 of the Law of Georgia ''on Road Traffic'', at an unregulated intersection of equal roads, a rail vehicle (tram) has priority over non-rail vehicles, regardless of the direction of movement. Non-rail vehicles must follow the ''right-hand rule'' among themselves. Therefore, the motorcycle driver is obliged to yield to the tram (due to its priority) and to the passenger car approaching from the right.', 1, '3', 'Only to the tram driver', 'Only to the passenger car driver', 'To both the tram driver and the passenger car driver', 'To neither of the vehicle drivers', 29, '{2}'::int[], NULL, 'Hello! Remember two golden rules: 1. The tram always has priority at an equal-importance intersection. 2. You must yield to vehicles on your right. Since both the tram and the car have the right of way over you, option 3 is the correct choice!', 'ticket_media/new/ticketIMG-1614.jpg'),
(1615, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '3', 'მხოლოდ ტრამვაის და მსუბუქი ავტომობილის მძღოლების მიმართ', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', 'როგორც ავტობუსის, ასევე ტრამვაის და მსუბუქი ავტომობილის მძღოლების მიმართ', 29, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ საგზაო ნიშნები ყოველთვის გვეუბნება, ვინ არის მთავარ გზაზე. ამ სიტუაციაში, მოტოციკლისტი სარგებლობს უპირატესობით, ამიტომ მას არავისთვის დათმობა არ სჭირდება. ყოველთვის დააკვირდი ნიშნებს, ისინი შენი საუკეთესო მეგობრები არიან გზაზე!', 'ticket_media/new/ticketIMG-1615.jpg'),
(1615, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю мотоцикла при движении в направлении стрелки?', 'Согласно статье 36 Закона Грузии «О дорожном движении», приоритет проезда на перекрестке определяется дорожными знаками (главная/второстепенная дорога) или правилами проезда равнозначных дорог (правило «помехи справа»). Если мотоциклист движется по главной дороге или имеет преимущество в силу расположения справа, другие участники движения обязаны уступить ему дорогу. Таким образом, у него не возникает обязанности уступать дорогу другим транспортным средствам.', 1, '3', 'Только водителям трамвая и легкового автомобиля', 'Только водителю автобуса', 'Ни одному из водителей транспортных средств', 'Как водителям автобуса, так и трамвая и легкового автомобиля', 29, '{2}'::int[], NULL, 'Привет! Помни, что дорожные знаки всегда подсказывают нам, кто находится на главной дороге. В данной ситуации мотоциклист имеет преимущество, поэтому ему не нужно никому уступать дорогу. Всегда внимательно следи за знаками — это твои лучшие помощники на дороге!', 'ticket_media/new/ticketIMG-1615.jpg'),
(1615, 'en', 'The driver of which vehicle is the motorcycle driver required to yield to when moving in the direction of the arrow?', 'According to Article 36 of the Law of Georgia ''on Road Traffic'', priority at an intersection is determined by road signs (main/secondary road) or the rules for passing equal-priority roads (the right-hand priority rule). If the motorcyclist is moving along the main road or has priority from the right, other vehicles are required to yield to them; therefore, the motorcyclist has no obligation to yield to any other vehicle.', 1, '3', 'Only to the drivers of the tram and passenger car', 'Only to the driver of the bus', 'To none of the drivers of the vehicles', 'To the drivers of the bus, as well as the tram and passenger car', 29, '{2}'::int[], NULL, 'Hello! Remember that road signs always tell us who is on the main road. In this situation, the motorcyclist has the right of way, so they do not need to yield to anyone. Always keep an eye on the signs; they are your best friends on the road!', 'ticket_media/new/ticketIMG-1615.jpg'),
(1616, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '2', 'მხოლოდ ტრამვაის და მსუბუქი ავტომობილის მძღოლების მიმართ', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', 'როგორც მოტოციკლის, ასევე ტრამვაის და მსუბუქი ავტომობილის მძღოლების მიმართ', 29, '{4}'::int[], NULL, 'გამარჯობა! აქ მთავარია დაიმახსოვრო „მარჯვენა ხელის წესი“. რადგან ყველა სატრანსპორტო საშუალება თანაბარმნიშვნელოვან გზაზეა, ავტობუსმა გზა უნდა დაუთმოს მას, ვინც მისგან მარჯვნივ იმყოფება. ამ სურათში მოტოციკლი ავტობუსის მარჯვენა მხარესაა, ამიტომ მას ვუთმობთ.', 'ticket_media/new/ticketIMG-1616.jpg'),
(1616, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса при движении в направлении стрелки?', 'Согласно пункту 4 «г» статьи 36 Закона Грузии «О дорожном движении», при проезде перекрестков равнозначных дорог водитель безрельсового транспортного средства обязан уступить дорогу транспортному средству, приближающемуся справа («правило правой руки»). В данном случае мотоцикл для автобуса является безрельсовым транспортным средством, приближающимся справа.', 1, '2', 'Только водителям трамвая и легкового автомобиля', 'Только водителю мотоцикла', 'Никому из водителей транспортных средств', 'Как водителю мотоцикла, так и водителям трамвая и легкового автомобиля', 29, '{4}'::int[], NULL, 'Привет! Самое важное здесь — помнить «правило правой руки». Поскольку все транспортные средства находятся на равнозначной дороге, автобус должен уступить дорогу тому, кто находится справа от него. На этой схеме мотоцикл находится справа от автобуса, поэтому мы уступаем ему.', 'ticket_media/new/ticketIMG-1616.jpg'),
(1616, 'en', 'Which driver must the bus driver yield to when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''c'' of the Law of Georgia ''On Road Traffic'', at intersections of equal roads, the driver of a non-rail vehicle must yield to a vehicle approaching from the right (''right-hand rule''). In this scenario, the motorcycle is a non-rail vehicle approaching the bus from the right side.', 1, '2', 'Only the drivers of the tram and passenger car', 'Only the driver of the motorcycle', 'None of the drivers of the vehicles', 'Both the motorcycle driver and the drivers of the tram and passenger car', 29, '{4}'::int[], NULL, 'Hello! The key here is to remember the ''right-hand rule.'' Since all vehicles are on an equal-priority road, the bus must yield to the one approaching from its right. In this diagram, the motorcycle is to the right of the bus, so we yield to it.', 'ticket_media/new/ticketIMG-1616.jpg'),
(1619, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'მხოლოდ ყვითელი ავტომობილის მძღოლის მიმართ', 'მხოლოდ წითელი ავტომობილის მძღოლის მიმართ', 'როგორც ყვითელი, ასევე წითელი ავტომობილის მძღოლების მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! აქ მთავარი წესია მთავარი გზის პრიორიტეტი. თუ ხედავ, რომ ყვითელი ავტომობილი მთავარ გზაზეა, მას აქვს უპირატესობა. მოტოციკლმა უნდა დაუთმოს მას გზა, რადგან ის მეორეხარისხოვანი გზიდან გამოდის.', 'ticket_media/new/ticketIMG-1619.jpg'),
(1619, 'ru', 'Водителю какого автомобиля обязан уступить дорогу водитель мотоцикла при движении в указанном стрелкой направлении?', 'Согласно пункту «а» части 4 статьи 36 Закона Грузии «О дорожном движении», транспортное средство, движущееся по главной дороге, имеет преимущество. Если мотоцикл находится на второстепенной дороге, он обязан уступить дорогу любому транспортному средству, движущемуся по главной дороге, независимо от направления их дальнейшего движения.', 1, '1', 'Только водителю желтого автомобиля', 'Только водителю красного автомобиля', 'Как водителю желтого, так и водителю красного автомобиля', NULL, 29, '{2}'::int[], NULL, 'Привет! Главное правило здесь — приоритет главной дороги. Если ты видишь, что желтый автомобиль находится на главной дороге, у него есть преимущество. Мотоциклист обязан уступить ему дорогу, так как выезжает со второстепенной дороги.', 'ticket_media/new/ticketIMG-1619.jpg'),
(1619, 'en', 'To the driver of which vehicle must the motorcycle driver yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''a'' of the Law of Georgia ''On Road Traffic'', a vehicle moving on a major road has the right of way. If the motorcycle is on a minor road, it is obligated to yield to any vehicle moving on the major road, regardless of the direction they are intending to travel.', 1, '1', 'Only to the driver of the yellow vehicle', 'Only to the driver of the red vehicle', 'To both the drivers of the yellow and red vehicles', NULL, 29, '{2}'::int[], NULL, 'Hello! The main rule here is the priority of the major road. If you see that the yellow car is on the major road, it has the right of way. The motorcycle rider must yield to it because they are coming from a minor road.', 'ticket_media/new/ticketIMG-1619.jpg'),
(1620, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს: მთავარ გზაზე ყოფნა უპირატესობას ნიშნავს. ვინაიდან ყვითელი ავტომობილი მთავარ გზაზეა, ის არავის უთმობს გზას. დანარჩენი მანქანები გზას დაუთმობენ მას!', 'ticket_media/new/ticketIMG-1620.jpg'),
(1620, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю желтого автомобиля при движении в направлении стрелки?', 'Согласно пункту 4 «а» статьи 36 Закона Грузии «О дорожном движении», водитель, находящийся на главной дороге, пользуется преимущественным правом проезда. Поскольку желтый автомобиль движется по главной дороге, он не обязан уступать дорогу другим участникам движения.', 1, '3', 'Только водителю легкового автомобиля', 'Только водителю мотоцикла', 'Ни одному из водителей транспортных средств', NULL, 29, '{6}'::int[], NULL, 'Привет! Запомни: движение по главной дороге дает преимущество. Так как желтый автомобиль едет по главной, он никому не обязан уступать. Наоборот, другие участники должны уступить дорогу ему!', 'ticket_media/new/ticketIMG-1620.jpg'),
(1620, 'en', 'Which driver must the yellow car driver yield to when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''a'' of the Law of Georgia ''on Road Traffic'', a driver on a main road has the right of way. Since the yellow car is traveling on the main road, it is not required to yield to any other drivers.', 1, '3', 'Only to the driver of the passenger car', 'Only to the driver of the motorcycle', 'To none of the drivers of the vehicles', NULL, 29, '{6}'::int[], NULL, 'Hello! Remember: being on the main road means you have priority. Since the yellow car is on the main road, it does not need to yield to anyone. In fact, the other drivers must yield to it!', 'ticket_media/new/ticketIMG-1620.jpg'),
(1621, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში, თუ ტექნიკური სამსახურის ავტომობილს ჩართული აქვს ყვითელი მოელვარე შუქურა?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ამავე კანონის 51-ე მუხლის მე-4 პუნქტის თანახმად, მძღოლს, რომელსაც სატრანსპორტო საშუალებაზე ჩართული აქვს ნარინჯისფერი ან ყვითელი მოელვარე სპეციალური ციმციმა სიგნალი და რომელიც გზაზე ასრულებს სამშენებლო, სარემონტო ან დასასუფთავებელ სამუშაოებს, ან საინკასაციო სატრანსპორტო საშუალებით გადააქვს ძვირფასეულობა ან ფასიანი ქაღალდები, ან გადააქვს სახიფათო ტვირთი, ან გადაადგილდება არაგაბარიტული (მსხვილგაბარიტიანი) ან ზენორმატიული (მძიმეწონიანი) სატრანსპორტო საშუალებით, შეუძლია გადაუხვიოს საგზაო ნიშნებისა და მონიშვნების, აგრეთვე ამ კანონის 31-ე მუხლის მე-5–მე-10, მე-15, მე-16 და 38-ე მუხლის პირველი პუნქტით დადგენილ მოთხოვნებს, თუ უზრუნველყოფს საგზაო მოძრაობის უსაფრთხოებას. ნარინჯისფერი ან ყვითელი მოელვარე სპეციალური ციმციმა სიგნალი არ იძლევა უპირატესობას საგზაო მოძრაობის სხვა მონაწილეების მიმართ და გამოიყენება ყურადღების მისაპყრობად მოსალოდნელი საშიშროების თავიდან ასაცილებისათვის.', 1, '3', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'მხოლოდ ტექნიკური სამსახურის ავტომობილის მძღოლის მიმართ', 'როგორც სატვირთო, ასევე ტექნიკური სამსახურის ავტომობილის მძღოლების მიმართ', 'არცერთი ავტომობილის მძღოლების მიმართ', 29, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს: ყვითელი ციმციმა სიგნალი მხოლოდ ყურადღების მისაპყრობად არის და არ განიჭებს უპირატესობას. ამიტომ, გზაჯვარედინზე მოძრაობისას შენ უნდა დაუთმო ყველა იმ მანქანას, ვისაც წესების მიხედვით პრიორიტეტი აქვს (სატვირთო იქნება ეს თუ ტექნიკური სამსახურის მანქანა).', 'ticket_media/new/ticketIMG-1621.jpg'),
(1621, 'ru', 'Водителю автобуса, движущемуся в направлении стрелки, какому водителю транспортного средства он обязан уступить дорогу, если у автомобиля технической службы включен желтый проблесковый маячок?', 'Согласно статье 36, пункту 4 Закона Грузии «О дорожном движении», водитель обязан уступить дорогу транспортным средствам, имеющим преимущество (например, движущимся по главной дороге или приближающимся справа). Согласно статье 51, пункту 4 того же закона, желтый (оранжевый) проблесковый маячок не дает водителю преимущества в движении. Следовательно, такой автомобиль обязан соблюдать дорожные знаки и правила на общих основаниях.', 1, '3', 'Только водителю грузового автомобиля', 'Только водителю автомобиля технической службы', 'Как водителю грузового автомобиля, так и водителю автомобиля технической службы', 'Ни одному из водителей', 29, '{4}'::int[], NULL, 'Привет! Запомни: желтый проблесковый маячок нужен только для привлечения внимания и не дает преимущества на дороге. Поэтому на перекрестке ты обязан уступить дорогу всем автомобилям, у которых есть приоритет по правилам, независимо от того, является ли это грузовик или машина техслужбы.', 'ticket_media/new/ticketIMG-1621.jpg'),
(1621, 'en', 'To which driver must the bus driver yield while moving in the direction of the arrow, if the technical service vehicle has its yellow flashing beacon turned on?', 'According to Article 36, Paragraph 4 of the Law of Georgia on Road Traffic, a driver must yield to vehicles with priority (e.g., those on a main road or approaching from the right). Per Article 51, Paragraph 4, a yellow (amber) flashing beacon does not grant the driver right-of-way. Therefore, such a vehicle must obey road signs and traffic rules just like any other road user.', 1, '3', 'Only to the driver of the truck', 'Only to the driver of the technical service vehicle', 'To both the driver of the truck and the driver of the technical service vehicle', 'To neither driver', 29, '{4}'::int[], NULL, 'Hello! Remember: a yellow flashing beacon is only meant to attract attention and does not grant you right-of-way. Therefore, at an intersection, you must yield to any vehicle that has priority according to the rules, whether it is a truck or a technical service vehicle.', 'ticket_media/new/ticketIMG-1621.jpg'),
(1624, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'არცერთი ავტომობილის მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! აქ მთავარია დააკვირდე პრიორიტეტს. რადგან ავტობუსი მთავარ გზაზეა, მას აქვს უპირატესობა. ამიტომ, მან არავის არაფერი უნდა დაუთმოს, პირიქით - სხვებმა უნდა დაუთმონ მას გზა!', 'ticket_media/new/ticketIMG-1624.jpg'),
(1624, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса при движении в направлении стрелки?', 'Согласно пункту 4 «а» статьи 36 Закона Грузии «О дорожном движении», автобус движется по главной дороге. Следовательно, другие участники движения обязаны уступить дорогу автобусу, а не наоборот.', 1, '3', 'Только водителю легкового автомобиля', 'Только водителю грузового автомобиля', 'Никому из водителей', NULL, 29, '{4}'::int[], NULL, 'Привет! Главное здесь — определить приоритет. Поскольку автобус находится на главной дороге, у него преимущество. Поэтому он никому не обязан уступать дорогу, наоборот — другие водители должны уступить ему!', 'ticket_media/new/ticketIMG-1624.jpg'),
(1624, 'en', 'The driver of which vehicle must the bus driver yield to when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''a'' of the Law of Georgia ''On Road Traffic'', the bus is traveling on the main road. Therefore, other vehicle drivers are required to yield to the bus, not the other way around.', 1, '3', 'Only the driver of the passenger car', 'Only the driver of the truck', 'None of the drivers', NULL, 29, '{4}'::int[], NULL, 'Hello! The key here is to determine the priority. Since the bus is on the main road, it has the right of way. Therefore, it does not have to yield to anyone; instead, other drivers must yield to the bus!', 'ticket_media/new/ticketIMG-1624.jpg'),
(1626, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '3', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'როგორც მსუბუქი, ასევე სატვირთო ავტომობილის მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: თუ შენ ხარ მეორეხარისხოვან გზაზე, უნდა დაუთმო გზა მთავარ გზაზე მოძრავ ნებისმიერ ტრანსპორტს. არ აქვს მნიშვნელობა ეს მსუბუქია თუ სატვირთო, ყველა მათგანი შენზე პრიორიტეტულია!', 'ticket_media/new/ticketIMG-1626.jpg'),
(1626, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю желтого автомобиля при движении в направлении стрелки?', 'Согласно статье 36, пункту 4 Закона Грузии «О дорожном движении», транспортное средство, движущееся по главной дороге, имеет преимущество. Желтый автомобиль находится на второстепенной дороге и обязан уступить дорогу всем транспортным средствам, движущимся по главной дороге, независимо от их типа и дальнейшего направления движения.', 1, '3', 'Только водителю легкового автомобиля', 'Только водителю грузового автомобиля', 'Как водителю легкового, так и водителю грузового автомобиля', NULL, 29, '{6}'::int[], NULL, 'Привет! Запомни главное правило: если ты находишься на второстепенной дороге, ты обязан уступить дорогу всем, кто едет по главной. Неважно, легковой это автомобиль или грузовой — все они имеют преимущество перед тобой!', 'ticket_media/new/ticketIMG-1626.jpg'),
(1626, 'en', 'To which vehicle''s driver must the yellow car''s driver yield when proceeding in the direction of the arrow?', 'In accordance with Article 36, Clause 4 of the Law of Georgia ''On Road Traffic'', a vehicle traveling on a major road has the right of way. The yellow vehicle is on a minor road and is therefore obligated to yield to all vehicles on the major road, regardless of their type or intended direction of travel.', 1, '3', 'Only to the driver of the passenger car', 'Only to the driver of the truck', 'To both the driver of the passenger car and the truck', NULL, 29, '{6}'::int[], NULL, 'Hello! Remember the golden rule: if you are on a minor road, you must yield to any vehicle traveling on the major road. It doesn''t matter if it''s a passenger car or a truck—all of them have the right of way over you!', 'ticket_media/new/ticketIMG-1626.jpg'),
(1628, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ ტრამვაის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მთავარი გზის მქონე მძღოლი მეფეა გზაჯვარედინზე. რადგან ყვითელი მანქანა მთავარ გზაზეა, მას არავის დათმობა არ სჭირდება. გზა თავისუფალია!', 'ticket_media/new/ticketIMG-1628.jpg'),
(1628, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю желтого автомобиля при движении в направлении стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», водитель, движущийся по главной дороге, имеет преимущество. Если желтый автомобиль движется по главной дороге, у него нет обязанности уступать дорогу транспортным средствам, движущимся с других направлений.', 1, '3', 'Только водителю трамвая', 'Только водителю грузового автомобиля', 'Никому из водителей транспортных средств', NULL, 29, '{6}'::int[], NULL, 'Привет! Помни, что водитель на главной дороге — главный на перекрестке. Так как желтый автомобиль едет по главной дороге, ему не нужно никому уступать. Путь свободен!', 'ticket_media/new/ticketIMG-1628.jpg'),
(1628, 'en', 'The driver of which vehicle must the driver of the yellow car yield to when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4 of the Law of Georgia ''On Road Traffic'', a driver moving on a main road has the right of way. If the yellow car is moving on a main road, it is not required to yield to vehicles approaching from any other direction.', 1, '3', 'Only to the tram driver', 'Only to the truck driver', 'To none of the vehicle drivers', NULL, 29, '{6}'::int[], NULL, 'Hi there! Remember, the driver on the main road is the boss of the intersection. Since the yellow car is on the main road, it doesn''t need to yield to anyone. You have the right of way!', 'ticket_media/new/ticketIMG-1628.jpg'),
(1629, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-3 პუნქტის „ა“ და „ბ“ ქვეპუნქტების თანახმად, რეგულირებულ გზაჯვარედინზე: ა) შუქნიშნის მწვანე სიგნალის ჩართვის დროს მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის მოძრავი ტრამვაის მძღოლებმაც; ბ) შუქნიშნის დამატებით სექციაში ძირითად ყვითელ ან წითელ მაშუქ სიგნალთან ერთად ჩართული ისრის მიმართულებით მოძრაო¬ბისას სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს სხვა მიმართულებიდან მოძრავ სატრანსპორტო საშუალებას.', 1, '2', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'როგორც მსუბუქი, ასევე სატვირთო ავტომობილის მძღოლების მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! როდესაც შუქნიშნის დამატებით სექციაში ისარი გიჩვენებს მოძრაობას, გახსოვდეს: შენ არ გაქვს უპირატესობა. კანონი გავალდებულებს, გზა დაუთმო ყველას, ვინც სხვა მიმართულებიდან მოდის. ამიტომ, სატვირთოს მძღოლს, რომელიც თავისი მწვანე სიგნალით მოძრაობს, აუცილებლად უნდა დაუთმო გზა.', 'ticket_media/new/ticketIMG-1629.jpg'),
(1629, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю мотоцикла при движении в направлении стрелки?', 'Согласно подпункту «б» пункта 3 статьи 36 Закона Грузии «О дорожном движении», при движении в направлении стрелки, включенной в дополнительной секции светофора, водитель обязан уступить дорогу транспортным средствам, движущимся с других направлений. В данном случае приоритет имеет грузовой автомобиль, движущийся согласно установленным правилам.', 1, '2', 'Только водителю легкового автомобиля', 'Только водителю грузового автомобиля', 'Как водителю легкового, так и водителю грузового автомобиля', NULL, 29, '{2}'::int[], NULL, 'Привет! Когда ты едешь по стрелке в дополнительной секции светофора, важно помнить: у тебя нет преимущества. По закону ты обязан уступить дорогу всем, кто едет с других направлений. Поэтому ты должен пропустить грузовик, который движется по своему разрешающему сигналу.', 'ticket_media/new/ticketIMG-1629.jpg'),
(1629, 'en', 'To which vehicle''s driver must the motorcycle driver yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Paragraph 3, Subparagraph ''b'' of the Georgian Law on Road Traffic, when moving in the direction of an arrow in an additional traffic light section, the driver is obliged to yield the right of way to vehicles moving from other directions. In this scenario, the truck has the right of way based on the regulations.', 1, '2', 'Only the driver of the passenger car', 'Only the driver of the truck', 'Both the passenger car and the truck drivers', NULL, 29, '{2}'::int[], NULL, 'Hello! When you are moving following an arrow in an additional traffic light section, remember: you do not have the right of way. The law requires you to yield to anyone coming from other directions. Therefore, you must yield to the truck driver who is moving on their own green signal.', 'ticket_media/new/ticketIMG-1629.jpg'),
(1631, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '1', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც ავტობუსის, ასევე მსუბუქი ავტომობილის მძღოლების მიმართ', NULL, 29, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის წესი“: თუ გზაჯვარედინზე არ არის მანიშნებლები, ვუთმობთ მას, ვინც მარჯვნიდან გვიახლოვდება. რადგან ავტობუსი მოტოციკლის მარჯვნივ არის, ის გადის პირველი!', 'ticket_media/new/ticketIMG-1631.jpg'),
(1631, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю мотоцикла при движении в направлении стрелки?', 'Согласно подпункту «г» пункта 4 статьи 36 Закона Грузии «О дорожном движении», на перекрестке равнозначных дорог водитель безрельсового транспортного средства обязан уступить дорогу транспортному средству, приближающемуся справа. В данной ситуации автобус приближается к мотоциклисту справа, следовательно, он имеет преимущество.', 1, '1', 'Только водителю автобуса', 'Только водителю легкового автомобиля', 'Как водителю автобуса, так и водителю легкового автомобиля', NULL, 29, '{0,2}'::int[], NULL, 'Привет! Запомни «правило правой руки»: если на перекрестке нет знаков приоритета, мы уступаем дорогу тому, кто приближается справа. Так как автобус находится справа от мотоцикла, он проезжает первым!', 'ticket_media/new/ticketIMG-1631.jpg'),
(1631, 'en', 'Which vehicle driver is the motorcycle driver obliged to yield to when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''c'' of the Law of Georgia ''On Road Traffic'', at an intersection of equal roads, the driver of a non-rail vehicle must yield to a vehicle approaching from the right. In this case, the bus is approaching the motorcycle from the right, thus it has the right of way.', 1, '1', 'Only to the bus driver', 'Only to the passenger car driver', 'To both the bus driver and the passenger car driver', NULL, 29, '{0,2}'::int[], NULL, 'Hello! Remember the ''right-hand rule'': if there are no priority signs at an intersection, we yield to whoever is approaching from our right. Since the bus is to the right of the motorcycle, it goes first!', 'ticket_media/new/ticketIMG-1631.jpg'),
(1633, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ და „დ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; დ) მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრა¬ნსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს თანაბარ¬მნიშვნელოვან გზაზე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც.', 1, '3', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'არცერთი ავტომობილის მძღოლების მიმართ', 'როგორც სატვირთო, ასევე მსუბუქი ავტომობილის მძღოლების მიმართ', 29, '{4}'::int[], NULL, 'გამარჯობა! გახსოვდეს მთავარი წესი: თუ შენ მთავარ გზაზე ხარ, შენ გაქვს უპირატესობა. რადგან ავტობუსი მოძრაობს მთავარი გზიდან, სხვები ვალდებულნი არიან მას დაუთმონ გზა და არა პირიქით. ამიტომ სწორი პასუხია ის, რომ ავტობუსს არავისთვის არაფრის დათმობა არ სჭირდება.', 'ticket_media/new/ticketIMG-1633.jpg'),
(1633, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю автобуса при движении в направлении стрелки?', 'Согласно статье 36 Закона Грузии «О дорожном движении», поскольку автобус движется по главной дороге в направлении стрелки, он пользуется преимущественным правом проезда и не обязан уступать дорогу транспортным средствам, находящимся на второстепенной дороге.', 1, '3', 'Только водителю грузового автомобиля', 'Только водителю легкового автомобиля', 'Ни одному из водителей', 'Как водителю грузового, так и водителю легкового автомобиля', 29, '{4}'::int[], NULL, 'Привет! Запомни золотое правило: если ты на главной дороге, у тебя преимущество. Так как автобус движется по главной дороге, другие водители обязаны уступить ему путь, а не наоборот. Поэтому правильный ответ — водителю автобуса не нужно никому уступать.', 'ticket_media/new/ticketIMG-1633.jpg'),
(1633, 'en', 'To the driver of which vehicle must the bus driver yield the right of way when moving in the direction of the arrow?', 'In accordance with Article 36 of the Law of Georgia ''On Road Traffic'', since the bus is moving from the main road in the direction of the arrow, it has the right of way and is not obligated to yield to vehicles approaching from a secondary road.', 1, '3', 'Only to the driver of the truck', 'Only to the driver of the passenger car', 'To none of the drivers', 'To both truck and passenger car drivers', 29, '{4}'::int[], NULL, 'Hello! Remember the golden rule: if you are on the main road, you have the right of way. Since the bus is traveling on the main road, other drivers are obligated to yield to it, not the other way around. Therefore, the correct answer is that the bus driver does not need to yield to anyone.', 'ticket_media/new/ticketIMG-1633.jpg'),
(1634, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ სარგებლობს უპირატესობით მოტოციკლის მძღოლი ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტეის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'როგორც ავტობუსის, ასევე მსუბუქი ავტომობილის მძღოლების მიმართ', NULL, 29, '{0,2}'::int[], NULL, 'გახსოვდეთ, რომ მთავარ გზაზე მყოფი მძღოლი სარგებლობს უპირატესობით მიუხედავად იმისა, თუ რა ტიპის სატრანსპორტო საშუალებას მართავს ის (ავტობუსი იქნება ეს თუ მსუბუქი ავტომობილი). მთავარია პრიორიტეტი: ვინც მთავარ გზაზეა, ის მიდის პირველი!', 'ticket_media/new/ticketIMG-1634.jpg'),
(1634, 'ru', 'По отношению к водителю какого транспортного средства мотоциклист пользуется преимуществом при движении в направлении стрелки?', 'Согласно пункту 4 «а» статьи 36 Закона Грузии «О дорожном движении», водитель транспортного средства, движущегося по второстепенной дороге, обязан уступить дорогу транспортному средству, движущемуся по главной дороге, независимо от направления его дальнейшего движения.', 1, '3', 'Только по отношению к водителю автобуса', 'Только по отношению к водителю легкового автомобиля', 'Как по отношению к водителю автобуса, так и по отношению к водителю легкового автомобиля', NULL, 29, '{0,2}'::int[], NULL, 'Помни: преимущество зависит от статуса дороги, а не от типа транспортного средства. Если ты на главной дороге, ты имеешь приоритет перед всеми, кто на второстепенной, будь то автобус или легковушка. Правило простое: главная дорога — твое преимущество!', 'ticket_media/new/ticketIMG-1634.jpg'),
(1634, 'en', 'Towards the driver of which vehicle does the motorcycle driver have the right of way when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''a'' of the Law of Georgia ''on Road Traffic'', a driver moving on a minor road must yield to any vehicle approaching on a major road, regardless of the direction in which that vehicle intends to proceed.', 1, '3', 'Only towards the bus driver', 'Only towards the passenger car driver', 'Towards both bus and passenger car drivers', NULL, 29, '{0,2}'::int[], NULL, 'Remember: right of way is determined by the road status, not the vehicle type. If you are on the main road, you have priority over everyone coming from a minor road, regardless of whether they are driving a bus or a car. The priority belongs to the main road!', 'ticket_media/new/ticketIMG-1634.jpg'),
(1636, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „გ“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '1', 'მხოლოდ მოტოციკლის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', 'არცერთი სატრანსპორტო საშუალების მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს ოქროს წესი: თუ გზაჯვარედინზე თანაბარი პირობებია, ყოველთვის უნდა დაუთმო გზა იმას, ვინც მარჯვენა მხრიდან მოდის. რადგან მოტოციკლი შენს მარჯვნივ არის, მას უპირატესობა აქვს!', 'ticket_media/new/ticketIMG-1636.jpg'),
(1636, 'ru', 'Водитель какого транспортного средства обязан уступить дорогу водителю желтого автомобиля при движении в направлении стрелки?', 'Согласно подпункту «г» пункта 4 статьи 36 Закона Грузии «О дорожном движении», на нерегулируемом перекрестке равнозначных дорог водитель безрельсового транспортного средства обязан уступить дорогу транспортному средству, приближающемуся справа. Поскольку мотоцикл приближается к желтому автомобилю с правой стороны, водитель желтого автомобиля обязан уступить ему дорогу.', 1, '1', 'Только водителю мотоцикла', 'Только водителю легкового автомобиля', 'Никому из водителей транспортных средств', NULL, 29, '{6}'::int[], NULL, 'Привет! Запомни золотое правило: на нерегулируемом перекрестке равнозначных дорог всегда уступай дорогу тем, кто приближается справа. Так как мотоцикл находится справа от тебя, у него приоритет!', 'ticket_media/new/ticketIMG-1636.jpg'),
(1636, 'en', 'To which vehicle driver is the driver of the yellow car obliged to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, paragraph 4, subparagraph ''g'' of the Law of Georgia on Road Traffic, at an unregulated intersection of equal roads, the driver of a non-rail vehicle must yield the right of way to a vehicle approaching from the right. Since the motorcycle is approaching the yellow car from the right, the driver of the yellow car must yield to it.', 1, '1', 'Only the motorcycle driver', 'Only the car driver', 'Neither of the vehicle drivers', NULL, 29, '{6}'::int[], NULL, 'Hello! Remember the golden rule: at an intersection of equal roads, you must always yield to traffic coming from your right. Since the motorcycle is on your right side, it has the right of way!', 'ticket_media/new/ticketIMG-1636.jpg'),
(1638, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ ავტობუსის და მსუბუქი ავტომობილის მძღოლების მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'არცერთი ავტომობილის მძღოლების მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მთავარია დააკვირდე ნიშნებს. თუ შენ მოძრაობ მთავარ გზაზე ან შენს მარჯვნივ არავინაა, ვისაც უნდა დაუთმო, მაშინ გზა შენია! ამ კონკრეტულ შემთხვევაში არავის აქვს შენზე უპირატესობა.', 'ticket_media/new/ticketIMG-1638.jpg'),
(1638, 'ru', 'Водителю какого транспортного средства обязан уступить дорогу мотоциклист при движении в направлении стрелки?', 'Согласно статье 36 Закона Грузии «О дорожном движении», в данной ситуации ни один другой водитель не обладает преимуществом перед мотоциклистом. Поскольку мотоциклист движется по главной дороге или для него не существует дорожного знака, обязывающего его уступить дорогу, у него нет обязанности уступать путь другим участникам движения.', 1, '3', 'Только водителям автобуса и легкового автомобиля', 'Только водителю грузового автомобиля', 'Никому из водителей транспортных средств', NULL, 29, '{2}'::int[], NULL, 'Привет! Главное — всегда следить за знаками. Если ты едешь по главной дороге или справа от тебя нет никого, кому нужно уступить, значит, путь свободен! В данной ситуации у других водителей нет перед тобой преимущества.', 'ticket_media/new/ticketIMG-1638.jpg'),
(1638, 'en', 'To which vehicle driver is the motorcycle driver obliged to yield the right of way when moving in the direction of the arrow?', 'According to Article 36 of the Law of Georgia on Road Traffic, in this specific situation, no other driver has priority over the motorcyclist. Since the motorcyclist is traveling on the main road, or there is no traffic sign requiring them to yield, the motorcyclist has no obligation to yield to other vehicles.', 1, '3', 'Only to the drivers of the bus and the passenger car', 'Only to the driver of the truck', 'To none of the vehicle drivers', NULL, 29, '{2}'::int[], NULL, 'Hello! Always remember to watch the road signs. If you are on the main road or there is no one approaching from your right that you need to yield to, the road is yours! In this specific case, no other driver has priority over you.', 'ticket_media/new/ticketIMG-1638.jpg'),
(1639, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ყვითელი ავტომობილის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“ ქვეპუნქტის თანახმად, არარეგულირებულ გზაჯვარედინზე, არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ რუხი ავტომობილის მძღოლის მიმართ', 'მხოლოდ წითელი ავტომობილის მძღოლის მიმართ', 'როგორც რუხი, ასევე წითელი ავტომობილის მძღოლების მიმართ', NULL, 29, '{6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ როცა მთავარ გზაზე გადიხარ, პრიორიტეტი მათ აქვთ, ვინც უკვე მთავარ გზაზე მოძრაობს. რადგან წითელიც და რუხიც მთავარ გზაზე არიან, მათ ორივეს უნდა დაუთმო გზა, მიუხედავად იმისა, სად აპირებენ ისინი მოხვევას.', 'ticket_media/new/ticketIMG-1639.jpg'),
(1639, 'ru', 'Водителю какого транспортного средства обязан уступить дорогу водитель желтого автомобиля при движении в направлении стрелки?', 'Согласно пункту 4 «а» статьи 36 Закона Грузии «О дорожном движении», водитель, движущийся по второстепенной дороге, обязан уступить дорогу всем транспортным средствам, находящимся на главной дороге, независимо от направления их дальнейшего движения.', 1, '3', 'Только водителю серого автомобиля', 'Только водителю красного автомобиля', 'Как водителю серого, так и водителю красного автомобиля', NULL, 29, '{6}'::int[], NULL, 'Привет! Запомни: если ты выезжаешь со второстепенной дороги, приоритет имеют те, кто уже находится на главной. Поскольку и серый, и красный автомобили движутся по главной дороге, ты обязан уступить обоим, независимо от того, в какую сторону они планируют поворачивать.', 'ticket_media/new/ticketIMG-1639.jpg'),
(1639, 'en', 'To the driver of which vehicle must the driver of the yellow car yield when moving in the direction of the arrow?', 'According to Article 36, Paragraph 4, Subparagraph ''a'' of the Law of Georgia ''On Road Traffic'', a driver moving on a minor road must yield to all vehicles on the major road, regardless of their intended direction of travel.', 1, '3', 'Only to the driver of the grey car', 'Only to the driver of the red car', 'To both the drivers of the grey and red cars', NULL, 29, '{6}'::int[], NULL, 'Hello! Remember, when you are exiting a minor road, those already on the major road have the right of way. Since both the grey and the red cars are on the major road, you must yield to both of them, regardless of which direction they intend to go.', 'ticket_media/new/ticketIMG-1639.jpg'),
(1641, 'ka', 'რომელი სატრანსპორტო საშუალების მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება ავტობუსის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-3 პუნქტის „ა“ და „გ“ ქვეპუნქტის თანახმად, რეგულირებულ გზაჯვარედინზე: ა) შუქნიშნის მწვანე სიგნალის ჩართვის დროს მარცხნივ მოხვევისას ან მობრუნებისას ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის მოძრავი ტრამვაის მძღოლებმაც; გ) თუ შუქნიშნის ან მარეგულირებლის სიგნალები ერთდროულად მოძრაობის ნებას რთავს რელსიან და ურელსო სატრანსპორტო საშუალებებს, რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა, მიუხედავად მისი მოძრაობის მიმართულებისა, მაგრამ შუქნიშნის დამატებით სექციაში ძირითად ყვითელ ან წითელ მაშუქ სიგნალთან ერთად ჩართული ისრის მიმართულებით მოძრაობისას რელსიანი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს სხვა მიმართულებიდან მოძრავ სატრანსპორტო საშუალებას;', 1, '2', 'მხოლოდ ტრამვაის მძღოლის მიმართ', 'მხოლოდ სატვირთო ავტომობილის მძღოლის მიმართ', 'როგორც ტრამვაის, ასევე სატვირთო ავტომობილის მძღოლების მიმართ', NULL, 29, '{4}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, როცა შენ მოძრაობ შუქნიშნის მწვანე სიგნალზე, შენ გაქვს უპირატესობა იმ ტრამვაის მიმართ, რომელიც მოძრაობს დამატებითი სექციის ისრით. ამიტომ, შენ უთმობ მხოლოდ სატვირთო ავტომობილს, რადგან ისიც ურელსოა და მას გააჩნია გავლის უპირატესობა შენს მიმართ.', 'ticket_media/new/ticketIMG-1641.jpg'),
(1641, 'ru', 'Водителю какого транспортного средства обязан уступить дорогу водитель автобуса при движении в направлении стрелки?', 'Согласно пункту «г» части 3 статьи 36 Закона Грузии «О дорожном движении», при движении в направлении стрелки, включенной в дополнительной секции светофора одновременно с основным желтым или красным сигналом, рельсовое транспортное средство обязано уступить дорогу другим транспортным средствам. Так как автобус движется на основной зеленый сигнал светофора, он обладает преимуществом перед трамваем. Следовательно, водитель автобуса обязан уступить дорогу только водителю грузового автомобиля, который также является безрельсовым транспортным средством и пользуется преимуществом в данной дорожной ситуации.', 1, '2', 'Только водителю трамвая', 'Только водителю грузового автомобиля', 'Как водителю трамвая, так и водителю грузового автомобиля', NULL, 29, '{4}'::int[], NULL, 'Привет! Запомни: когда ты едешь на основной зеленый сигнал светофора, у тебя есть преимущество перед трамваем, который движется под стрелку в дополнительной секции. Поэтому ты должен уступить дорогу только грузовому автомобилю, который является безрельсовым транспортным средством и имеет приоритет в данной ситуации.', 'ticket_media/new/ticketIMG-1641.jpg'),
(1641, 'en', 'To the driver of which vehicle must the bus driver yield when moving in the direction of the arrow?', 'According to Article 36, Clause 3, Sub-clause ''g'' of the Law of Georgia ''on Road Traffic'', when a rail vehicle moves in the direction of an arrow shown in a supplementary signal section simultaneously with a main yellow or red light, it must yield to vehicles coming from other directions. Since the bus (a non-rail vehicle) is moving on the main green signal, it holds priority over the rail vehicle. Therefore, the bus driver must yield only to the driver of the truck, which is a non-rail vehicle moving under standard traffic rules.', 1, '2', 'Only to the driver of the tram', 'Only to the driver of the truck', 'To both the driver of the tram and the driver of the truck', NULL, 29, '{4}'::int[], NULL, 'Hello! Remember: when you are driving on a green traffic light, you have priority over a tram that is moving based on a supplementary arrow signal. Therefore, you only yield to the truck, as it is also a non-rail vehicle and has the right of way over you in this specific scenario.', 'ticket_media/new/ticketIMG-1641.jpg'),
(1643, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '3', 'მხოლოდ წითელი ავტომობილის მძღოლის მიმართ', 'მხოლოდ ლურჯი ავტომობილის მძღოლის მიმართ', 'არცერთი ავტომობილის მძღოლების მიმართ', NULL, 29, '{2}'::int[], NULL, 'გამარჯობა! აქ მთავარია დააკვირდე საგზაო ნიშნებს. რადგან მოტოციკლი მთავარ გზაზეა, მას აქვს უპირატესობა. შესაბამისად, მას არავისთვის დათმობა არ ევალება და თავისუფლად აგრძელებს მოძრაობას.', 'ticket_media/new/ticketIMG-1643.jpg'),
(1643, 'ru', 'Водителю какого автомобиля обязан уступить дорогу водитель мотоцикла при движении в направлении стрелки?', 'Согласно пункту 4 статьи 36 Закона Грузии «О дорожном движении», мотоциклист движется по главной дороге. Так как он находится на главной дороге и ни одно другое транспортное средство не имеет преимущества перед ним, у него нет обязанности уступать дорогу. Он проезжает перекресток первым.', 1, '3', 'Только водителю красного автомобиля', 'Только водителю синего автомобиля', 'Ни одному из водителей', NULL, 29, '{2}'::int[], NULL, 'Привет! Главное здесь — обратить внимание на дорожные знаки. Так как мотоциклист находится на главной дороге, у него есть приоритет. Следовательно, он никому не обязан уступать дорогу и может спокойно продолжать движение.', 'ticket_media/new/ticketIMG-1643.jpg'),
(1643, 'en', 'To which driver must the motorcycle rider yield if moving in the direction of the arrow?', 'According to Article 36, Paragraph 4 of the Law of Georgia ''On Road Traffic'', the motorcycle is moving on the main road. Since it is on the main road and no other vehicle holds priority, there is no obligation to yield. The motorcycle is entitled to proceed through the intersection first.', 1, '3', 'Only to the driver of the red car', 'Only to the driver of the blue car', 'To none of the drivers', NULL, 29, '{2}'::int[], NULL, 'Hello! The key here is to look at the traffic signs. Since the motorcycle is on the main road, it has the right of way. Therefore, it does not need to yield to anyone and can proceed through the intersection.', 'ticket_media/new/ticketIMG-1643.jpg'),
(1645, 'ka', 'რომელი ავტომობილის მძღოლის მიმართ წარმოექმნება გზის დათმობის ვალდებულება მოტოციკლის მძღოლს ისრის მიმართულებით მოძრაობის შემთხვევაში?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 36-ე მუხლის მე-4 პუნქტის „ა“, „ბ“ და „გ“ ქვეპუნქტების თანახმად, არარეგულირებულ გზაჯვარედინზე: ა) არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე მეორეხარისხოვან გზაზე მოძრავი სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მთავარი გზიდან მოახლოებულ სატრანსპორტო საშუალებას, მიუხედავად მისი შემდგომი მოძრაობის მიმართულებისა; ბ) თუ გზაჯვარედინზე მთავარი გზა იცვლის მიმართულებას, ამ გზაზე მოძრავმა მძღოლებმა ურთიერთშორის უნდა იხელმძღვანელონ თანაბარმნიშვნელოვანი გზების გავლის წესებით. ამავე წესებით უნდა იხელმძღვანელონ ურთიერთშორის მეორეხარისხოვან გზაზე მოძრავმა მძღოლებმაც; გ) თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ურელსო სატრანსპორტო საშუალების მძღოლი ვალდებულია გზა დაუთმოს მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. ამავე წესით უნდა იხელმძღვანელონ ურთიერთშორის რელსიანი სატრანსპორტო საშუალებების მძღოლებმაც. ასეთ გზაჯვარედინზე რელსიან სატრანსპორტო საშუალებას აქვს უპირატესობა ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა.', 1, '3', 'არცერთი ავტომობილის მძღოლების მიმართ', 'მხოლოდ ავტობუსის მძღოლის მიმართ', 'მხოლოდ მსუბუქი ავტომობილის მძღოლის მიმართ', NULL, 29, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს „მარჯვენა ხელის წესი“: როდესაც გზაჯვარედინზე არ არის საგზაო ნიშნები, უპირატესობა აქვს მას, ვინც მარჯვნივ მოძრაობს. რადგან მსუბუქი ავტომობილი შენი მარჯვენა მხარეა, მას უნდა დაუთმო გზა. ეს არის ყველაზე უსაფრთხო გზა გზაჯვარედინის გასავლელად!', 'ticket_media/new/ticketIMG-1645.jpg'),
(1645, 'ru', 'Водителю какого транспортного средства обязан уступить дорогу мотоциклист при движении по направлению стрелки?', 'Согласно подпункту «г» пункта 4 статьи 36 Закона Грузии «О дорожном движении», на перекрестке равнозначных дорог действует «правило правой руки»: водитель безрельсового транспортного средства обязан уступить дорогу транспортному средству, приближающемуся справа. В данной ситуации легковой автомобиль находится справа от мотоцикла, поэтому он имеет преимущественное право проезда.', 1, '3', 'Никому из водителей', 'Только водителю автобуса', 'Только водителю легкового автомобиля', NULL, 29, '{0,2}'::int[], NULL, 'Привет! Запомни «правило правой руки»: когда на перекрестке нет знаков приоритета, преимущество имеет тот, кто находится справа от тебя. Поскольку легковой автомобиль приближается справа, ты обязан уступить ему дорогу. Это самый безопасный способ проезда перекрестка!', 'ticket_media/new/ticketIMG-1645.jpg'),
(1645, 'en', 'To which vehicle driver is the motorcycle driver obligated to yield the right of way when moving in the direction of the arrow?', 'According to Article 36, Clause 4, Sub-clause ''c'' of the Law of Georgia ''On Road Traffic'', the ''right-hand rule'' applies at an intersection of equal-priority roads: a driver of a non-rail vehicle must yield to a vehicle approaching from the right. In this case, the passenger car is approaching from the right side of the motorcycle, and therefore, it has the right of way.', 1, '3', 'To none of the vehicle drivers', 'Only to the bus driver', 'Only to the passenger car driver', NULL, 29, '{0,2}'::int[], NULL, 'Hello! Remember the ''right-hand rule'': when there are no traffic signs at an intersection, the vehicle approaching from your right has priority. Since the passenger car is to your right, you must yield to it. This is the safest way to navigate the intersection!', 'ticket_media/new/ticketIMG-1645.jpg'),
(1646, 'ka', 'სად შეიძლება ბარგის განთავსება მოტოციკლზე?', 'მოტოციკლზე ბარგი შეიძლება განთავსდეს მოტოციკლის საბარგო ჩანთაში ან საბარგულზე.', 0, '1', 'მოტოციკლის საბარგო ჩანთაში ან საბარგულზე', 'მოტოციკლის საწვავის ავზზე', 'მოტოციკლის საჭის მარჯვენა და მარცხენა მხარეს, თანამბრად გადანაწილებით', NULL, 30, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოციკლი ძალიან მგრძნობიარეა წონის გადანაწილების მიმართ. ბარგის საჭეზე ან ავზზე მიმაგრებამ შეიძლება ხელი შეგიშალოს მანევრირებაში, რაც სახიფათოა. გამოიყენე მხოლოდ ქარხნული წესით გათვალისწინებული ჩანთები ან საბარგულები, რათა მგზავრობა უსაფრთხო იყოს!', NULL),
(1646, 'ru', 'Где разрешается размещать багаж на мотоцикле?', 'Согласно Закону Грузии «О дорожном движении», в целях обеспечения безопасности дорожного движения, размещение багажа на мотоцикле разрешается исключительно в специально предназначенных для этого местах: в багажной сумке или на багажнике. Использование других частей мотоцикла для крепления груза может нарушить центр тяжести и создать угрозу безопасности.', 0, '1', 'В багажной сумке или на багажнике мотоцикла', 'На топливном баке мотоцикла', 'С правой и левой стороны руля мотоцикла, равномерно распределив', NULL, 30, '{2}'::int[], NULL, 'Привет! Помни, что мотоцикл очень чувствителен к распределению веса. Размещение багажа на руле или баке может ограничить управление и создать опасную ситуацию. Всегда используй только специальные кофры или багажники, предусмотренные конструкцией, чтобы твоя поездка была безопасной!', NULL),
(1646, 'en', 'Where is it permitted to place luggage on a motorcycle?', 'In accordance with the Georgian "Law on Road Traffic", to ensure safety, luggage on a motorcycle may only be placed in designated areas. The law explicitly states that luggage must be kept in a luggage bag or on a luggage rack, which ensures the stability and maneuverability of the motorcycle.', 0, '1', 'In a luggage bag or on the motorcycle''s luggage rack', 'On the motorcycle''s fuel tank', 'On the right and left sides of the motorcycle handlebar, distributed evenly', NULL, 30, '{2}'::int[], NULL, 'Hello! Remember that a motorcycle is very sensitive to weight distribution. Placing luggage on the handlebars or fuel tank can interfere with steering and maneuverability, which is dangerous. Always use factory-designed luggage bags or racks to ensure a safe ride!', NULL),
(1647, 'ka', 'ძირითად საყრდენზე მოტოციკლის დაყენებისას, ყურადღება უნდა მიიექცეს შემდეგ გარემოებას:', 'ძირითად საყრდენზე მოტოციკლის დაყენებისას, ყურადღება უნდა მიიექცეს გარემოებას, რომ ძირითადი საყრდენის ქვეშ საფარი იყოს მყარი.', 0, '1', 'ძირითადი საყრდენის ქვეშ საფარი უნდა იყოს მყარი', 'ძირითად საყრდენზე დაყენება შეიძლება განხორციელდეს, მხოლოდ ხანმოკლე დროით', NULL, NULL, 30, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოტოციკლის მძიმე წონა სრულად აწვება საყრდენს. თუ ნიადაგი რბილია (მაგალითად, მიწა ან ქვიშა), საყრდენი ჩაიძირება და მოტოციკლი წაიქცევა. ყოველთვის შეარჩიე ასფალტი ან მყარი ზედაპირი!', NULL),
(1647, 'ru', 'При установке мотоцикла на центральную подножку, необходимо обратить внимание на следующее обстоятельство:', 'В соответствии с Законом Грузии «О дорожном движении», для надежной установки мотоцикла требуется стабильность опорной поверхности. Твердое покрытие обеспечивает равновесие мотоцикла и исключает проваливание подножки в грунт, что может привести к падению транспортного средства.', 0, '1', 'Поверхность под центральной подножкой должна быть твердой', 'Установка на центральную подножку может осуществляться только на короткое время', NULL, NULL, 30, '{2}'::int[], NULL, 'Привет! Запомни, весь вес мотоцикла давит на подножку. Если поверхность мягкая (земля или песок), подножка уйдет в грунт, и мотоцикл упадет. Всегда выбирай асфальт или твердую поверхность для парковки!', NULL),
(1647, 'en', 'When placing a motorcycle on the center stand, attention should be paid to the following circumstance:', 'In accordance with the Georgian Law on Road Traffic, securing a motorcycle requires the stability of the supporting surface. A firm surface ensures the balance of the motorcycle and prevents the stand from sinking into the ground, which would lead to the vehicle tipping over.', 0, '1', 'The surface under the center stand must be firm', 'Placement on the center stand can only be carried out for a short time', NULL, NULL, 30, '{2}'::int[], NULL, 'Hi! Remember, the full weight of the motorcycle rests on the stand. If the ground is soft (like dirt or sand), the stand will sink and the bike will tip over. Always choose asphalt or a solid surface to park safely!', NULL),
(1656, 'ka', 'როგორ უნდა მოიქცეს ავტობუსის მძღოლი, თუ ერთ-ერთი მგზავრი იქცევა აგრესიულად და აწუხებს სხვა მგზავრებს?', 'თუ ერთ-ერთი მგზავრი იქცევა აგრესიულად და აწუხებს სხვა მგზავრებს ავტობუსის მძღოლმა სიმშვიდისკენ უნდა მოუწოდოს აგრესიულად განწყობილ მგზავრს, და გააფრთხილოს რომ წინააღმდეგ შემთხვევაში გამოიძახებს პოლიციას. თუ მგზავრი არ დამშვიდდა და სიტუაცია ხდება საფრთხის შემცველი, მძღლმა უნდა დარეკოს პოლიციაში.', 0, '2', 'აგრესიული მგზავრის შეშინების მიზნით განახორციელოს მკვეთრი დამუხრუჭება', 'მძღოლმა სიმშვიდისკენ უნდა მოუწოდოს აგრესიულად განწყობილ მგზავრს და გააფრთხილოს, რომ წინააღმდეგ შემთხვევაში გამოიძახებს პოლიციას. თუ მგზავრი არ დამშვიდდა და სიტუაცია ხდება საფრთხის შემცველი, მძღლმა უნდა დარეკოს პოლიციაში', 'მძღოლმა უნდა განუცხადოს მგზავრს, რომ აპირებს პოლიციაში დარეკვას, ხოლო თუ იგი გააგრძელებს აგრესიულად მოქცევას იძულებით ჩამოსვას ავტობუსიდან', NULL, 30, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, შენი მთავარი მიზანი ავტობუსში მშვიდობიანი გარემოს შენარჩუნებაა. არასოდეს გამოიყენო მანქანა (მკვეთრი დამუხრუჭება) მგზავრების დასასჯელად, რადგან ეს ავარიას გამოიწვევს. იყავი თავდაჯერებული, გააფრთხილე მგზავრი და თუ საქმე რთულდება, პოლიციაა საუკეთესო დამხმარე!', NULL),
(1656, 'ru', 'Как должен поступить водитель автобуса, если один из пассажиров ведет себя агрессивно и беспокоит других пассажиров?', 'Согласно Закону Грузии «О дорожном движении» и правилам безопасности, водитель обязан обеспечивать безопасность пассажиров. Резкое торможение само по себе создает опасность, а принудительная высадка пассажира без участия полиции может превышать полномочия водителя. Правильная процедура заключается в вербальном предупреждении и, при необходимости, вызове правоохранительных органов.', 0, '2', 'Применить резкое торможение, чтобы напугать агрессивного пассажира.', 'Водитель должен призвать агрессивного пассажира к спокойствию и предупредить, что в противном случае вызовет полицию. Если пассажир не успокоится и ситуация станет угрожающей, водитель должен позвонить в полицию.', 'Водитель должен заявить пассажиру, что собирается вызвать полицию, а если тот продолжит вести себя агрессивно, принудительно высадить его из автобуса.', NULL, 30, '{4,6}'::int[], NULL, 'Привет! Помни, твоя главная цель — поддерживать спокойную обстановку в автобусе. Никогда не используй транспортное средство (резкое торможение) для наказания пассажиров, так как это может привести к аварии. Будь уверен в себе, сделай предупреждение, а если ситуация накаляется, полиция — твой лучший помощник!', NULL),
(1656, 'en', 'How should a bus driver act if one of the passengers behaves aggressively and disturbs other passengers?', 'According to the Law of Georgia ''on Road Traffic'' and general safety regulations, the driver is responsible for ensuring passenger safety. Harsh braking creates a danger itself, and forcibly removing a passenger without police involvement may exceed the driver''s legal authority. The correct procedure is to provide a verbal warning and involve law enforcement if the situation escalates.', 0, '2', 'Apply sharp braking to scare the aggressive passenger.', 'The driver should call the aggressive passenger to calm down and warn them that otherwise, they will call the police. If the passenger does not calm down and the situation becomes dangerous, the driver must call the police.', 'The driver should tell the passenger they intend to call the police, and if they continue to behave aggressively, force them to get off the bus.', NULL, 30, '{4,6}'::int[], NULL, 'Hello! Remember, your main goal is to maintain a peaceful environment on the bus. Never use the vehicle (harsh braking) to punish passengers, as it could cause an accident. Stay confident, give a warning, and if things get difficult, the police are your best resource!', NULL),
(1657, 'ka', 'ავარიულ გასასვლელად ავტობუსში შეიძლება გამოყენებულ იქნეს:', 'ავარიულ გასასვლელად ავტობუსში შეიძლება გამოყენებულ იქნეს ავარიული გასასვლელის კარები, ლუკი და ფანჯრები.', 0, '1', 'ავარიული გასასვლელის კარები, ლუქი და ფანჯრები', 'მხოლოდ ის კარებები, რომლებიც ავარიის დროს ავტომატურად იხსნება', 'მხოლოდ საავარიო გასასვლელი ფანჯრები', NULL, 30, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ავარიის დროს უსაფრთხოება მთავარია. ავტობუსს აქვს რამდენიმე გზა ევაკუაციისთვის: კარები, ლუქი ჭერში და ფანჯრები. ყველა მათგანი დაპროექტებულია ისე, რომ საჭიროების შემთხვევაში სწრაფად დატოვო სალონი.', NULL),
(1657, 'ru', 'Что в автобусе может использоваться в качестве аварийного выхода?', 'Согласно Закону Грузии «О дорожном движении» и соответствующим техническим регламентам, аварийные выходы в автобусе включают в себя специально оборудованные двери, а также аварийные люки и окна, предназначенные для эвакуации.', 0, '1', 'Двери, люк и окна аварийного выхода', 'Только те двери, которые открываются автоматически во время аварии', 'Только окна аварийного выхода', NULL, 30, '{4,6}'::int[], NULL, 'Привет! Помни, что в экстренной ситуации безопасность превыше всего. В автобусе для эвакуации предусмотрено несколько путей: двери, потолочный люк и окна. Все они спроектированы так, чтобы ты мог быстро покинуть салон в случае необходимости.', NULL),
(1657, 'en', 'What can be used as an emergency exit in a bus?', 'According to the Georgian ''Law on Road Traffic'' and relevant technical regulations, emergency exits in a bus include specially equipped doors, as well as emergency hatches and windows intended for evacuation.', 0, '1', 'Emergency exit doors, hatches, and windows', 'Only doors that open automatically during an accident', 'Only emergency exit windows', NULL, 30, '{4,6}'::int[], NULL, 'Hello! Remember, in an emergency, safety is the priority. A bus has several ways to evacuate: doors, a ceiling hatch, and windows. All of them are designed to allow you to exit the cabin quickly if needed.', NULL),
(1658, 'ka', 'როგორ უნდა მოიქცეს ავტობუსის მძღოლი, თუ მის წინ მიმავალი ავტომობილი უსაფუძვლოდ მოძრაობს მეტისმეტად დაბალი სიჩქარით?', 'თუ მის წინ მიმავალი ავტომობილი უსაფუძვლოდ მოძრაობს მეტისმეტად დაბალი სიჩქარით ავტობუსის მძღოლმა უნდა გააგრძელოს მის უკან მოძრაობა მანამდე სანამ არ მიეცემაა უსაფრთხოდ გასწრების შესაძლებლობა.', 0, '1', 'უნდა გააგრძელოს მის უკან მოძრაობა მანამდე სანამ არ მიეცემა უსაფრთხოდ გასწრების შესაძლებლობა', 'მაქსიმალურად მიუახლოვდეს უკნიდან, რათა აიძულოს იგი გაზარდოს სიჩქარე', 'იმოძრაოს უსაფრთხო დისტანციაზე და ხმოვანი სიგნალის მიცემით მოსთხოვოს მას მოძრაობის შეფერხების შეწყვეტა', NULL, 30, '{4,6}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ შენი მთავარი მიზანი როგორც მძღოლის, არის უსაფრთხოება. მაშინაც კი, თუ წინ მიმავალი მანქანა გაბრკოლებს, არ უნდა მოახდინო ზეწოლა (მიახლოებით) ან გამოიყენო აგრესიული სიგნალები. მოთმინება ყველაზე კარგი მეგობარია – უბრალოდ მიჰყევი მას და გაასწარი მაშინ, როცა გზა თავისუფალი და უსაფრთხო იქნება!', NULL),
(1658, 'ru', 'Как должен поступить водитель автобуса, если движущийся перед ним автомобиль безосновательно движется с чрезмерно низкой скоростью?', 'Согласно Закону Грузии «О дорожном движении», водитель обязан соблюдать правила безопасности и не создавать угрозу на дороге. В случае, если впереди движущийся транспорт безосновательно замедляет движение, единственный правомерный и безопасный метод — соблюдать дистанцию и дождаться момента, когда обгон станет возможен без риска для участников движения.', 0, '1', 'Продолжать движение за ним до тех пор, пока не появится возможность безопасного обгона.', 'Максимально приблизиться сзади, чтобы вынудить его увеличить скорость.', 'Двигаться на безопасной дистанции и с помощью звукового сигнала потребовать прекратить создание помех движению.', NULL, 30, '{4,6}'::int[], NULL, 'Привет! Помни, что твоя главная цель как водителя — это безопасность. Даже если машина впереди тебя задерживает, не стоит оказывать давление (подъезжать вплотную) или сигналить. Терпение — твой лучший друг: просто держись сзади и обгоняй только тогда, когда путь станет абсолютно свободным и безопасным!', NULL),
(1658, 'en', 'How should a bus driver behave if the vehicle in front is moving at an unreasonably low speed?', 'According to the Georgian Law on Road Traffic, drivers are prohibited from creating hazards. If a vehicle ahead is moving at an unreasonably low speed, the only legal and safe course of action is to maintain a following distance and wait until an overtaking maneuver can be performed safely.', 0, '1', 'Continue driving behind it until a safe overtaking opportunity arises.', 'Approach as closely as possible from behind to force them to increase speed.', 'Maintain a safe distance and use an audible signal to demand the end of the obstruction.', NULL, 30, '{4,6}'::int[], NULL, 'Hello! Remember, your main goal as a driver is safety. Even if the car in front is slowing you down, you shouldn''t pressure them by tailgating or using aggressive horns. Patience is your best friend—just stay behind them and overtake only when the road is clear and it is safe to do so!', NULL),
(1659, 'ka', 'მოტოციკლის მძღოლის მიერ მკვეთრი ფერების ტასაცმლით სარგებლობის შემთხვევაში:', 'მოტოციკლის მძღოლის მიერ მკვეთრი ფერების ტასაცმლით სარგებლობის შემთხვევაში იგი უკეთესად შესამჩნევი ხდება საგზაო მოძრაობის სხვა მონაწილეებისათვის.', 0, '1', 'იგი უკეთესად შესამჩნევი ხდება საგზაო მოძრაობის სხვა მონაწილეებისათვის', 'იგი არ არის ვალდებული დღის ნათელ დროს გზაზე მოძრაობისას მოტოციკლზე წინ ჩართული ქონდეს ახლო განათების ფარა', 'იგი არ არის ვალდებული გადაადგილებისას გამოიყენოს მოტოჩაფხუტი', NULL, 30, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოციკლი გზაზე ნაკლებად შესამჩნევია, ვიდრე ავტომობილი. მკვეთრი ფერის ტანსაცმელი სხვა მძღოლებს საშუალებას აძლევს, შორიდანვე დაგინახონ და თავიდან აიცილონ ავარიული სიტუაცია. ეს უბრალოდ უსაფრთხოების დამატებითი საშუალებაა!', NULL),
(1659, 'ru', 'В случае, если водитель мотоцикла использует одежду ярких цветов:', 'Согласно Закону Грузии «О дорожном движении», использование водителем мотоцикла одежды ярких цветов направлено на его визуальное выделение в транспортном потоке, что повышает безопасность и видимость для других участников движения.', 0, '1', 'Он становится лучше заметен для других участников дорожного движения', 'Он не обязан иметь включенную фару ближнего света в светлое время суток при движении по дороге', 'Он не обязан использовать мотошлем во время движения', NULL, 30, '{2}'::int[], NULL, 'Привет! Помни, что мотоцикл на дороге менее заметен, чем автомобиль. Одежда ярких цветов позволяет другим водителям заметить тебя издалека и избежать аварийных ситуаций. Это просто дополнительный способ повысить твою безопасность!', NULL),
(1659, 'en', 'If a motorcycle driver uses bright-colored clothing:', 'According to the Georgian Law on Road Traffic, the use of bright-colored clothing by a motorcycle driver is intended to make them visually stand out in the traffic flow, thereby increasing safety and visibility to other road users.', 0, '1', 'He becomes more visible to other road users', 'He is not required to have the low beam headlight on during daylight hours while driving on the road', 'He is not required to use a motorcycle helmet while driving', NULL, 30, '{2}'::int[], NULL, 'Hello! Remember that a motorcycle is less visible on the road than a car. Wearing bright clothing allows other drivers to spot you from a distance and helps avoid accidents. It is simply an extra safety measure to keep you protected!', NULL),
(1662, 'ka', 'გადამზიდველი პასუხს აგებს:', 'საქართველოს სამოქალაქო კოდექსის 669-ე მუხლის პირელი პუნქტის თანახმად, გადამზიდველი პასუხს აგებს მგზავრისათვის მიყენებული ზიანისათვის, ასევე მისი ბარგის დაზიანების ან დაკარგვისათვის.', 0, '1', 'მგზავრისათვის მიყენებული ზიანისათვის, ასევე მისი ბარგის დაზიანების ან დაკარგვისათვის', 'მხოლოდ მგზავრისათვის მიყენებული ზიანისათვის. მგზავრის ბარგის დაზიანებისათვის ან დაკარგვისათვის გადამზიდველს არ შეიძლება დაეკისროს პასუხიმგებლობა', NULL, NULL, 30, '{4,6}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ როდესაც შენ მგზავრებს გადაიყვან, შენი პასუხისმგებლობა ვრცელდება არა მხოლოდ მათ უსაფრთხოებაზე, არამედ მათ ნივთებზეც. თუ ბარგი დაიკარგა ან დაზიანდა, კანონით შენ ხარ ვალდებული, ეს ზიანი აანაზღაურო. ეს სამართლიანია, რადგან მგზავრი გენდობა და ანდობს თავის ნივთებს.', NULL),
(1662, 'ru', 'Перевозчик несет ответственность:', 'Согласно пункту 1 статьи 669 Гражданского кодекса Грузии, перевозчик несет полную ответственность как за жизнь и здоровье пассажира, так и за его багаж. Перевозчик обязан возместить ущерб, причиненный пассажиру или его багажу во время перевозки.', 0, '1', 'За ущерб, причиненный пассажиру, а также за повреждение или утрату его багажа', 'Только за ущерб, причиненный пассажиру. Перевозчик не может нести ответственность за повреждение или утрату багажа пассажира', NULL, NULL, 30, '{4,6}'::int[], NULL, 'Привет! Запомни: когда ты перевозишь пассажиров, твоя ответственность распространяется не только на их безопасность, но и на их вещи. Если багаж был поврежден или утерян, по закону ты обязан возместить ущерб. Это честно, ведь пассажир доверяет тебе и свое здоровье, и свой багаж.', NULL),
(1662, 'en', 'The carrier is liable for:', 'According to Article 669, paragraph 1 of the Civil Code of Georgia, the carrier bears full liability for both the life and health of the passenger and their luggage. The carrier is obligated to compensate for any damage caused to the passenger or their luggage during transportation.', 0, '1', 'For damage caused to the passenger, as well as for damage to or loss of their luggage', 'Only for damage caused to the passenger. The carrier cannot be held liable for damage to or loss of passenger luggage', NULL, NULL, 30, '{4,6}'::int[], NULL, 'Hello! Remember, when you transport passengers, your responsibility covers not only their safety but also their belongings. If luggage is damaged or lost, the law requires you to compensate for the damage. It is only fair, as the passenger trusts you with both their well-being and their property.', NULL),
(1709, 'ka', 'საქართველოს ადმინისტრაციული სამართალდარღვევათა კოდექსის თანახმად, მოტოციკლით მოძრაობისას მძღოლის ან/და მგზავრის მიერ შეკრული მოტოჩაფხუტის გამოუყენებლობა გამოიწვევს:', 'საქართველოს ადმინისტრაციული სამართალდარღვევათა კოდექსის 118³-ე მუხლის თანახმად, მოტოციკლით მოძრაობისას მძღოლის ან/და მგზავრის მიერ შეკრული მოტოჩაფხუტის გამოუყენებლობა - გამოიწვევს დაჯარიმებას 100 ლარის ოდენობით.', 0, '1', 'დაჯარიმებას 100 ლარის ოდენობით', 'დაჯარიმებას 100 ლარის ოდენობითა და მოტოციკლის მართვის უფლების შეჩერებას 3 თვის ვადით', 'დაჯარიმებას 50 ლარის ოდენობით', NULL, 22, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ჩაფხუტი შენი უსაფრთხოების მთავარი გარანტიაა. კანონის თანახმად, ჯარიმა 100 ლარია, თუმცა ყველაზე მნიშვნელოვანი შენი სიცოცხლე და ჯანმრთელობაა. ყოველთვის შეკარი ჩაფხუტი სწორად!', NULL),
(1709, 'ru', 'Согласно Кодексу об административных правонарушениях Грузии, неиспользование водителем и/или пассажиром застегнутого мотошлема при движении на мотоцикле влечет за собой:', 'Согласно части 1 статьи 118³ Кодекса об административных правонарушениях Грузии, неиспользование водителем или пассажиром застегнутого мотошлема при движении на мотоцикле влечет за собой наложение административного штрафа в размере 100 лари.', 0, '1', 'Штраф в размере 100 лари', 'Штраф в размере 100 лари и приостановление права управления мотоциклом сроком на 3 месяца', 'Штраф в размере 50 лари', NULL, 22, '{2}'::int[], NULL, 'Привет! Помни, что шлем — это главная гарантия твоей безопасности. Согласно закону, штраф составляет 100 лари, но самое важное — это твоя жизнь и здоровье. Всегда правильно застегивай шлем!', NULL),
(1709, 'en', 'According to the Administrative Offenses Code of Georgia, failure to use a fastened motorcycle helmet by the driver and/or passenger while riding a motorcycle shall result in:', 'According to Article 118³, part 1 of the Administrative Offenses Code of Georgia, failure to wear a fastened motorcycle helmet by a driver or passenger while operating a motorcycle results in an administrative fine of 100 GEL.', 0, '1', 'A fine of 100 GEL', 'A fine of 100 GEL and suspension of the right to drive a motorcycle for 3 months', 'A fine of 50 GEL', NULL, 22, '{2}'::int[], NULL, 'Hello! Remember that a helmet is your main safety guarantee. According to the law, the fine is 100 GEL, but most importantly, it is about your life and health. Always fasten your helmet properly!', NULL),
(1731, 'ka', 'მოტოჩაფხუტზე ბზარის გაჩენის შემთხვევაში, მძღოლმა უნდა:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის 43-ე მუხლის მე-10 პუნქტის თანახმად, გადაადგილებისას მოტოციკლისა და მოპედის მძღოლებმა, აგრეთვე მათმა მგზავრებმა მოტოჩაფხუტები უნდა გამოიყენონ. მოტოჩაფხუტზე ბზარების გაჩენის შემთხვევაში მოტოციკლეტის მძღოლმა უნდა შეიძინოს ახალი მოტოჩაფხუტი, რადგან ძველი (ბზარებიანი მოტოჩაფხუტი) ვეღარ უზრუნველყოფს დაცვას.', 0, '3', 'მოტოჩაფხუტის ქვეშ დაიხუროს ნაჭრის ქუდი', 'ბზარი დააწებოს და მოტოჩაფხუტი გადაღებოს', 'შეიძინოს ახალი მოტოჩაფხუტი, რადგან ძველი ვეღარ უზრუნველყოფს დაცვას', NULL, 14, '{0,2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოტოჩაფხუტი შენი სიცოცხლის მთავარი დამცველია. როგორც კი მასზე ბზარი ჩნდება, მისი სტრუქტურა ირღვევა და დარტყმის დროს ის ვეღარ შთანთქავს ენერგიას ისე, როგორც საჭიროა. ნუ გარისკავ – უსაფრთხოება ყველაზე მნიშვნელოვანია!', NULL),
(1731, 'ru', 'Что должен сделать водитель в случае появления трещины на мотошлеме?', 'Согласно пункту 10 статьи 43 Закона Грузии «О дорожном движении», мотошлем является обязательным средством безопасности. Нарушение целостности шлема (трещина) аннулирует его защитные свойства, что опасно для жизни в случае аварии. Следовательно, такой шлем подлежит обязательной замене.', 0, '3', 'Надеть под мотошлем тканевую шапку', 'Заклеить трещину и перекрасить мотошлем', 'Приобрести новый мотошлем, так как старый больше не обеспечит защиту', NULL, 14, '{0,2}'::int[], NULL, 'Привет! Помни, что мотошлем — это твоя главная защита. Как только на нем появляется трещина, его структура нарушается, и при ударе он больше не сможет поглощать энергию должным образом. Не рискуй — безопасность превыше всего!', NULL),
(1731, 'en', 'What should a driver do if a crack appears on a motorcycle helmet?', 'According to Article 43, Paragraph 10 of the Law of Georgia ''On Road Traffic'', a motorcycle helmet is an essential safety device. Compromising the integrity of the helmet (a crack) negates its protective function, which is life-threatening in the event of an accident. Therefore, such a helmet must be replaced.', 0, '3', 'Wear a cloth cap under the motorcycle helmet', 'Glue the crack and repaint the motorcycle helmet', 'Purchase a new motorcycle helmet, as the old one can no longer provide protection', NULL, 14, '{0,2}'::int[], NULL, 'Hi! Remember, your motorcycle helmet is your primary protection. Once a crack appears, its structure is compromised, and it will no longer absorb impact energy as intended. Don''t take chances—safety is the most important thing!', NULL),
(1732, 'ka', 'გზაზე მყოფ ძაღლის სიახლოვეს გამავალმა მოტოციკლის მძღოლმა უნდა:', 'გზაზე მყოფი ძაღლის სიახლოვეს გამავალმა მოტოციკლის მძღოლმა უნდა გამოიჩინოს განსაკუთრებული სიფრთხილე, რადგამ ძაღლმა შესაძლოა გამოამჟღავნოს აგრესია და გამოიწიოს მისი მიმართულებით.', 0, '2', 'გაითვალისწინოს რომ ყველა ძაღლს ეშინია მოძრავი სატრანსპორტო საშუალების, რის გამოც იგი აგრესიას არ გამოამჟღავნებს', 'გამოიჩინოს განსაკუთრებული სიფრთხილე, რადგან ძაღლმა შესაძლოა გამოამჟღავნოს აგრესია და გამოიწიოს მისი მიმართულებით', NULL, NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ცხოველები არაპროგნოზირებადები არიან. მოტოციკლის ხმაურმა და მოძრაობამ შესაძლოა ძაღლი შეაშინოს ან გააღიზიანოს. ამიტომ, უსაფრთხოების მიზნით, ყოველთვის შეამცირე სიჩქარე და მოემზადე მანევრირებისთვის, თუ ძაღლი გზაზეა.', NULL),
(1732, 'ru', 'Как должен поступить водитель мотоцикла, проезжающий рядом с собакой на дороге?', 'Согласно закону Грузии «О дорожном движении», водитель обязан учитывать непредсказуемое поведение животных. Собака может среагировать на движение, шум или вибрацию мотоцикла, что часто вызывает защитную или агрессивную реакцию.', 0, '2', 'Учесть, что все собаки боятся движущихся транспортных средств, поэтому они не проявят агрессии.', 'Проявить особую осторожность, так как собака может проявить агрессию и броситься в его сторону.', NULL, NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что животные ведут себя непредсказуемо. Шум и движение мотоцикла могут напугать или разозлить собаку. Поэтому в целях безопасности всегда снижай скорость и будь готов к маневру, если видишь собаку на дороге.', NULL),
(1732, 'en', 'How should a motorcyclist proceed when driving near a dog on the road?', 'In accordance with the Georgian Law on Road Traffic, a driver is required to account for the unpredictable behavior of animals. A dog may react to movement, noise, or the vibration of a motorcycle, which often triggers a defensive or aggressive response.', 0, '2', 'Assume that all dogs are afraid of moving vehicles, therefore they will not show aggression.', 'Exercise extreme caution, as the dog may show aggression and dart toward the motorcycle.', NULL, NULL, 14, '{2}'::int[], NULL, 'Hello! Remember that animals are unpredictable. The noise and movement of a motorcycle can startle or provoke a dog. Therefore, for safety, always reduce your speed and be prepared to maneuver if a dog is on the road.', NULL),
(1733, 'ka', 'ასფალტის საფარის მქონე გზიდან ღორღიან გზაზე გასვლისას, მოტოციკლის მძღოლმა უნდა:', 'ასფალტის საფარის მქონე გზიდან ღორღიან გზაზე გასვლისას, მოტოციკლის მძროლმა უნდა შეარჩიოს შესაბამისი მოძრაობის სიჩქარე და მოერიდოს მკვეთრ მოძრაობებს.', 0, '3', 'შეწყვიტოს მოძრაობა, რადგან ღორღიან გზაზე აკრძალულია მოტოციკლით მოძრაობა', 'გაზარდოს მოძრაობის სიჩქარე, რათა ნაკლებად საგრძნობი გახდეს გზის საფარის გავლენა საჭეზე', 'შეარჩიოს შესაბამისი მოძრაობის სიჩქარე და მოერიდოს მკვეთრ მოძრაობებს', NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ღორღი ძალიან მოლიპულია და საბურავების მოჭიდება მცირდება. თუ მკვეთრად დაამუხრუჭებ ან მოუხვევ, მოტოციკლი შეიძლება მოცურდეს. ამიტომ, ყოველთვის შეანელე სვლა გზის შეცვლამდე და იმოძრავე ფრთხილად და სტაბილურად!', NULL),
(1733, 'ru', 'При выезде с асфальтированной дороги на гравийную, водитель мотоцикла должен:', 'В соответствии с Законом Грузии «О дорожном движении», при смене типа дорожного покрытия (с асфальта на гравий) водитель обязан соблюдать меры безопасности. Коэффициент сцепления на нестабильной поверхности снижается, поэтому выбор соответствующей скорости и отказ от резких маневров необходимы для сохранения контроля над транспортным средством.', 0, '3', 'Остановиться, так как движение на мотоцикле по гравийным дорогам запрещено', 'Увеличить скорость движения, чтобы влияние дорожного покрытия на руль стало менее заметным', 'Выбрать соответствующую скорость движения и избегать резких движений', NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что гравий очень скользкий, и сцепление колес с дорогой падает. Если резко затормозить или повернуть, мотоцикл может занести. Поэтому всегда снижай скорость перед переходом на гравий и двигайся плавно, избегая рывков!', NULL),
(1733, 'en', 'When moving from an asphalt road to a gravel road, a motorcycle rider must:', 'In accordance with the Georgian Law on Road Traffic, when changing the road surface (from asphalt to gravel), the motorcycle rider is required to observe safety measures. The coefficient of adhesion decreases on unstable surfaces, therefore, choosing an appropriate speed and avoiding sudden maneuvers is essential to maintain control over the vehicle.', 0, '3', 'Stop, because riding a motorcycle on gravel roads is prohibited', 'Increase speed so that the influence of the road surface on the steering becomes less noticeable', 'Select an appropriate speed and avoid sudden movements', NULL, 14, '{2}'::int[], NULL, 'Hello! Remember that gravel is very slippery, and tire traction decreases significantly. If you brake or turn sharply, your motorcycle might slide. So, always slow down before hitting the gravel and ride smoothly, avoiding any jerky movements!', NULL),
(1734, 'ka', 'მოტოციკლის წინა მუხრუჭი უკანა მუხრუჭზე ეფექტურია, რადგან:', 'მოტოციკლის წინა მუხრუჭი უკანა მუხრუჭზე ეფექტურია, რადგან მოტოციკლის დამუხრუჭების დროს იცვლება ღერძებზე დატვირთვის გადანაწილება და მეტი დატვირთვა მოდის წინა საბურავზე.', 0, '3', 'წინა მუხრუჭი მოქმედებაში მოგვყავს ხელით', 'მოტოციკლის წინა საბურავი უკანაზე ვიწროა', 'დამუხრუჭების დროს იცვლება ღერძებზე დატვირთვის გადანაწილება და მეტი დატვირთვა მოდის წინა საბურავზე', 'ამ ბილეთში ჩამოთვლილი ყველა პასუხი სწორია', 14, '{2}'::int[], NULL, 'წარმოიდგინე, რომ მუხრუჭის დაჭერისას მოტოციკლი ოდნავ „წაიწევს“ წინ. ეს იმიტომ ხდება, რომ მთელი სიმძიმე წინ ინაცვლებს. მეტი სიმძიმე ნიშნავს მეტ მოჭიდებას, ამიტომ წინა მუხრუჭი უფრო ძლიერად აჩერებს მოტოციკლს!', NULL),
(1734, 'ru', 'Передний тормоз мотоцикла эффективнее заднего, потому что:', 'Согласно Закону Грузии «О дорожном движении» и законам физики, при торможении под действием инерции происходит перенос веса вперед, что увеличивает сцепление переднего колеса с дорогой, делая передний тормоз более эффективным.', 0, '3', 'Передний тормоз приводится в действие рукой', 'Переднее колесо мотоцикла уже заднего', 'При торможении меняется распределение нагрузки на оси, и основная нагрузка приходится на переднее колесо', 'Все перечисленные ответы верны', 14, '{2}'::int[], NULL, 'Представь, что при нажатии на тормоз мотоцикл немного «клюет» носом. Это происходит потому, что вес переносится вперед. Больше веса на переднем колесе — значит лучше сцепление с дорогой, поэтому передний тормоз эффективнее останавливает мотоцикл!', NULL),
(1734, 'en', 'The motorcycle''s front brake is more effective than the rear brake because:', 'According to the Georgian Law on Road Traffic and physical principles, during braking, inertia causes a weight transfer toward the front, which increases the front tire''s grip on the road, making the front brake significantly more effective.', 0, '3', 'The front brake is operated by hand', 'The front tire is narrower than the rear tire', 'During braking, weight distribution shifts to the axles, placing more load on the front tire', 'All answers listed are correct', 14, '{2}'::int[], NULL, 'Imagine that when you brake, the motorcycle tilts forward. This happens because the bike''s weight shifts to the front. More weight on the front wheel means better grip on the road, which is why the front brake is more effective at stopping the motorcycle!', NULL),
(1735, 'ka', 'მოტოციკლის საბურავებში დაბალმა ჰაერის წნევამ შეიძლება გამოიწვიოს:', 'მოტოციკლის საბურავებში დაბალმა ჰაერის წნევამ შეიძლება გამოიწვიოს როგორც საბურავის პროტექტორის კიდეების არათანაბარი ცვეთა, ასევე მოტოციკლის მართვადობის გაუარესება.', 0, '3', 'მხოლოდ პროტექტორის კიდეების არათანაბარი ცვეთა', 'მხოლოდ მოტოციკლის მართვადობის გაუარესება', 'ამ ბილეთში ჩამოთვლილი ნებისმიერი გარემოება', NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ საბურავები შენი უსაფრთხოების მთავარი გარანტია. როდესაც წნევა დაბალია, საბურავის გვერდები მეტად იტვირთება და ცვდება, ხოლო მოტოციკლის მანევრირება რთულდება. ამიტომ სწორი პასუხია 3, რადგან ორივე ეს პრობლემა ერთდროულად იჩენს თავს.', NULL),
(1735, 'ru', 'К чему может привести низкое давление воздуха в шинах мотоцикла?', 'Согласно Закону Грузии «О дорожном движении», отклонение давления в шинах от нормы отрицательно сказывается на техническом состоянии транспортного средства. Низкое давление приводит к неравномерному износу протектора и значительно ухудшает управляемость.', 0, '3', 'Только неравномерный износ краев протектора', 'Только ухудшение управляемости мотоцикла', 'Любое из перечисленных в этом билете обстоятельств', NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что шины — это залог твоей безопасности. Когда давление низкое, края шин перегружаются и быстрее изнашиваются, а маневрировать становится сложнее. Поэтому правильный ответ — 3, так как обе эти проблемы возникают одновременно.', NULL),
(1735, 'en', 'What can low air pressure in motorcycle tires cause?', 'In accordance with the Georgian Law on Road Traffic, deviation of tire pressure from the norm negatively affects the technical condition of the vehicle. Low pressure leads to uneven tread wear and significantly impairs handling.', 0, '3', 'Only uneven wear of the tread edges', 'Only deterioration of motorcycle handling', 'Any of the circumstances listed in this question', NULL, 14, '{2}'::int[], NULL, 'Hello! Remember, your tires are your primary safety feature. When pressure is low, the tire sidewalls take more stress and wear down, while the bike becomes harder to maneuver. That''s why option 3 is correct—both of these issues happen at the same time.', NULL),
(1736, 'ka', 'შესაძლებელია თუ არა, ავტომატარებლის მოძრაობისაგან გამოწვეულმა ჰაერის ტალღამ დაბრკოლება შეუქმნას მოტოციკლის მართვას?', 'ავტომატარებლის მოძრაობისგან გამოწვეულმა ჰაერის ტალღამ შესაძლებელია დაბრკოლება შეუქმნას მოტოციკლის მართვას როგორც იმ შემთხვევაში, თუ ავტომატერებელი მოძრაობს საპირისპირო მიმართულებიდან, ასევე თუ ავტომატარებელი ახორციელებს თანხვედრი მიმართულებით მოტოციკლის გასწრებას.', 0, '3', 'შესაძლებელია, მხოლოდ იმ შემთხვევაში, თუ ავტომატარებელი მოძრაობს საპირისპირო მიმართულებიდან', 'შესაძლებელია, მხოლოდ იმ შემთხვევაში, თუ ავტომატარებელი ახორციელებს თანმხვედრი მიმართულებით მოტოციკლის გასწრებას', 'შესაძლებელია ამ ბილეთში ჩამოთვლილი ნებისმიერი გარემოების არსებობისას', NULL, 14, '{2}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოტოციკლი მსუბუქი სატრანსპორტო საშუალებაა. დიდი ზომის ავტომატარებლის ჩავლისას, წარმოქმნილი ჰაერის ძლიერი ნაკადი მოტოციკლს ადვილად აგდებს წონასწორობიდან, მიუხედავად იმისა, ის საპირისპიროდ მოძრაობს თუ გვერდს გიქცევს. ამიტომ, ყოველთვის მზად იყავი და შეინარჩუნე დისტანცია!', NULL),
(1736, 'ru', 'Может ли воздушный поток, вызванный движением автопоезда, создать препятствие для управления мотоциклом?', 'В соответствии с Законом Грузии «О дорожном движении», поток воздушных масс (аэродинамический удар), создаваемый автопоездом, представляет опасность для управления мотоциклом как при встречном разъезде, так и при обгоне в попутном направлении. Таким образом, любое из перечисленных обстоятельств является опасным.', 0, '3', 'Возможно, только в том случае, если автопоезд движется во встречном направлении', 'Возможно, только в том случае, если автопоезд совершает обгон мотоцикла в попутном направлении', 'Возможно при наличии любого из перечисленных в данном билете обстоятельств', NULL, 14, '{2}'::int[], NULL, 'Привет! Помни, что мотоцикл — легкое транспортное средство. При проезде большого автопоезда мощный поток воздуха может легко нарушить равновесие мотоцикла, независимо от того, движется он навстречу или обгоняет тебя. Поэтому всегда будь готов к этому и держи дистанцию!', NULL),
(1736, 'en', 'Can the air wave generated by the movement of a road train create an obstacle for operating a motorcycle?', 'In accordance with the Georgian Law on Road Traffic, the flow of air masses (aerodynamic impact) generated by a road train poses a threat to operating a motorcycle both during oncoming traffic and when overtaking in the same direction. Consequently, any of the aforementioned circumstances presents a hazard.', 0, '3', 'It is possible, only if the road train is moving from the opposite direction', 'It is possible, only if the road train is overtaking the motorcycle in the same direction', 'It is possible in the presence of any of the circumstances listed in this ticket', NULL, 14, '{2}'::int[], NULL, 'Hello! Remember, a motorcycle is a lightweight vehicle. When a large road train passes by, the powerful air blast can easily throw your motorcycle off balance, regardless of whether it is coming from the opposite direction or overtaking you. So, always be prepared and keep a safe distance!', NULL),
(1796, 'ka', 'გარდა  შემთხვევებისა,როცა აუცილებელია ხელით მისცენ მანევრის შესრულებასთან დაკავშირებული სიგნალები,მოპედის მძღოლს ეკრძალება გადაადგილება ,თუ', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის თანახმად, მოპედის მძღოლი ვალდებულია მართვის დროს საჭეზე ხელით აკონტროლოს მოძრაობა. ორივე ხელით საჭის მართვა უზრუნველყოფს სატრანსპორტო საშუალების სტაბილურობასა და უსაფრთხოებას, გარდა იმ შემთხვევებისა, როდესაც მძღოლმა უნდა მიანიშნოს მანევრის შესახებ ხელით.', 0, '1', 'საჭე ორი ხელით არ უჭირავს', 'საჭე ერთი ხელით მაინც უჭირავს', NULL, NULL, 30, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოპედი მოძრავი ტრანსპორტია და მისი სტაბილურად შენარჩუნებისთვის ორივე ხელით საჭის მართვა აუცილებელია. ერთადერთი გამონაკლისი მაშინ გვაქვს, როცა სხვებს უნდა აჩვენო, რომ მოხვევას ან გაჩერებას აპირებ.', NULL),
(1796, 'ru', 'За исключением случаев, когда необходимо подать сигнал рукой, связанный с выполнением маневра, водителю мопеда запрещается движение, если:', 'Согласно Закону Грузии «О дорожном движении», водитель мопеда обязан держать руль обеими руками во время движения. Управление рулем обеими руками обеспечивает стабильность и безопасность транспортного средства, за исключением случаев, когда водитель обязан подать сигнал рукой о маневре.', 0, '1', 'Он не держит руль обеими руками', 'Он держит руль хотя бы одной рукой', NULL, NULL, 30, '{0}'::int[], NULL, 'Привет! Помни, что мопед — это полноценное транспортное средство, и для его устойчивости необходимо держать руль обеими руками. Единственное исключение — это подача сигналов поворота или остановки, когда это необходимо для безопасности окружающих.', NULL),
(1796, 'en', 'Except for cases where it is necessary to give hand signals related to performing a maneuver, a moped driver is prohibited from moving if:', 'According to the Law of Georgia ''On Road Traffic'', a moped driver is required to control the vehicle by keeping their hands on the handlebar. Controlling the handlebar with both hands ensures the stability and safety of the vehicle, except in cases where the driver must provide a hand signal for a maneuver.', 0, '1', 'They are not holding the handlebar with both hands', 'They are holding the handlebar with at least one hand', NULL, NULL, 30, '{0}'::int[], NULL, 'Hi there! Remember that a moped is a moving vehicle, and keeping both hands on the handlebar is essential for balance and control. The only exception is when you need to signal a turn or a stop to other road users.', NULL),
(1797, 'ka', 'დასაშვებია თუ არა მოპედით მისაბმელის ბუქსირება?', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის შესაბამისად, მოპედი არ არის გათვლილი მისაბმელის ბუქსირებისთვის. ბუქსირება ნებადართულია მხოლოდ იმ შემთხვევაში, თუ მწარმოებლის მიერ სატრანსპორტო საშუალება სპეციალურად არის კონსტრუირებული ამ ტიპის მისაბმელის გამოსაყენებლად.', 0, '3', 'დასაშვებია,რომლის ნებადართული მაქსიმალური მასა 750 კგ–ზე ნაკლებია ყველა იმ მისაბმელის ბუქსირება', 'არ არის დასაშვები', 'დასაშვებია მხოლოდ იმ მისაბმელის ბუქსირება,რომელიც განკუთვნილია აღნიშნულ ტრანსპორტთან ერთად ექსპლუატაციისთვის', NULL, 24, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოპედი ძალიან მსუბუქი ტრანსპორტია. მისაბმელის მიბმა მასზე მხოლოდ მაშინ შეიძლება, თუ ქარხნულად არის გათვლილი, რომ ამ კონკრეტულ მოპედს შეუძლია კონკრეტული მისაბმელის ტარება. უსაფრთხოება უპირველესია!', NULL),
(1797, 'ru', 'Допускается ли буксировка прицепа мопедом?', 'Согласно Закону Грузии «О дорожном движении», мопед не предназначен для буксировки прицепов в общем порядке. Буксировка допускается только в том случае, если транспортное средство специально сконструировано заводом-изготовителем для эксплуатации с данным конкретным типом прицепа.', 0, '3', 'Допускается буксировка любого прицепа, разрешенная максимальная масса которого менее 750 кг', 'Не допускается', 'Допускается только буксировка прицепа, предназначенного для эксплуатации с данным транспортным средством', NULL, 24, '{0}'::int[], NULL, 'Привет! Помни, что мопед — это легкое транспортное средство. Буксировка прицепа разрешена только в том случае, если производитель техники предусмотрел такую возможность и прицеп специально создан для данной модели мопеда. Безопасность превыше всего!', NULL),
(1797, 'en', 'Is it permitted to tow a trailer with a moped?', 'According to the Georgian Law on Road Traffic, a moped is not generally designed for towing trailers. Towing is permitted only if the vehicle has been specifically engineered by the manufacturer to be operated with such a trailer.', 0, '3', 'Permitted to tow any trailer with a maximum authorized mass of less than 750 kg', 'Not permitted', 'Permitted only for a trailer designed for operation with said vehicle', NULL, 24, '{0}'::int[], NULL, 'Hello! Remember that a moped is a lightweight vehicle. You can only tow a trailer if it was specifically designed by the manufacturer to be used with your particular model of moped. Safety first!', NULL),
(1798, 'ka', 'სად შეიძლება ბარგის განთავსება მოპედზე?', 'საქართველოს კანონი „საგზაო მოძრაობის შესახებ“ ადგენს, რომ სატრანსპორტო საშუალებაზე ბარგის გადატანა უნდა განხორციელდეს მხოლოდ სპეციალურად ამისთვის გამოყოფილ ადგილებში (საბარგულში ან საბარგო ჩანთაში), რათა არ მოხდეს მძღოლის მანევრირების შეზღუდვა ან მოძრაობის უსაფრთხოების საფრთხის შექმნა.', 0, '1', 'მოპედის საბარგო ჩანთაში ან საბარგულზე', 'მოპედის საწვავის ავზზე', 'მოპედის საჭის მარჯვენა და  მარცხენა მხარეს თანაბრად გადანაწილებით', NULL, 26, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოპედი ისეთივე სატრანსპორტო საშუალებაა, როგორც სხვები. ბარგის საჭეზე ან საწვავის ავზზე მოთავსება საშიშია, რადგან ხელს გიშლის საჭის მართვაში. ყოველთვის გამოიყენე მხოლოდ სპეციალური საბარგული ან დამაგრებული ჩანთა, რათა შენი მგზავრობა უსაფრთხო და სტაბილური იყოს!', NULL),
(1798, 'ru', 'Где можно размещать багаж на мопеде?', 'Согласно Закону Грузии «О дорожном движении», перевозка багажа на транспортном средстве должна осуществляться исключительно в специально предназначенных для этого местах (в багажнике или багажной сумке), чтобы не ограничивать маневренность водителя и не создавать угрозу безопасности дорожного движения.', 0, '1', 'В багажной сумке или на багажнике мопеда', 'На топливном баке мопеда', 'Равномерно распределив с правой и левой стороны руля мопеда', NULL, 26, '{0}'::int[], NULL, 'Привет! Помни, что мопед — такое же транспортное средство, как и другие. Размещать багаж на руле или топливном баке опасно, так как это мешает управлению. Всегда используй только специальный багажник или закрепленную сумку, чтобы поездка была безопасной и стабильной!', NULL),
(1798, 'en', 'Where can luggage be placed on a moped?', 'According to the Law of Georgia ''On Road Traffic'', the transportation of luggage on a vehicle must be carried out exclusively in places specially designated for this purpose (in a trunk or luggage bag) so as not to limit the driver''s maneuverability or create a threat to road traffic safety.', 0, '1', 'In the luggage bag or on the luggage rack of the moped', 'On the fuel tank of the moped', 'By distributing it evenly on the right and left sides of the moped handlebar', NULL, 26, '{0}'::int[], NULL, 'Hello! Remember that a moped is a vehicle just like any other. Placing luggage on the handlebars or fuel tank is dangerous because it hinders your steering. Always use only a dedicated luggage rack or a secured bag to ensure your ride is safe and stable!', NULL),
(1799, 'ka', 'ძირითად საყრდენზე მოპედის დაყენებისას,ყურადღება უნდა მიექცეს შემდეგ გარემოებებს:', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის და ზოგადი ტექნიკური ექსპლუატაციის წესების თანახმად, სატრანსპორტო საშუალების სტაბილური მდგომარეობის უზრუნველყოფა მოითხოვს მყარ საყრდენ ზედაპირს, რათა თავიდან ავიცილოთ მოპედის გადაყირავება ან საყრდენის გრუნტში ჩაჭედვა.', 0, '1', 'ძირითადი საყრდენის ქვეშ საფარი უნდა იყოს მყარი', 'ძირითადი საყრდენის ქვეშ საფარი არ უნდა იყოს მყარი', NULL, NULL, 30, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოპედის დაყენება რბილ გრუნტზე საშიშია, რადგან საყრდენი შეიძლება ჩაიჭედოს და მოპედი წაიქცეს. ყოველთვის ეძებე მყარი ზედაპირი, რათა შენი ტექნიკა უსაფრთხოდ იდგეს!', NULL),
(1799, 'ru', 'При установке мопеда на центральную подножку, на какие обстоятельства следует обратить внимание?', 'Согласно Закону Грузии «О дорожном движении» и общим правилам технической эксплуатации, обеспечение устойчивого положения транспортного средства требует твердой опорной поверхности, чтобы предотвратить опрокидывание мопеда или погружение подножки в мягкий грунт.', 0, '1', 'Поверхность под центральной подножкой должна быть твердой', 'Поверхность под центральной подножкой не должна быть твердой', NULL, NULL, 30, '{0}'::int[], NULL, 'Привет! Помни, что ставить мопед на мягкий грунт опасно, так как подножка может провалиться, и мопед упадет. Всегда ищи твердую поверхность, чтобы твой транспорт стоял надежно!', NULL),
(1799, 'en', 'When placing a moped on its main stand, which circumstances should be considered?', 'According to the Georgian Law on Road Traffic and general technical operation rules, ensuring a stable position for a vehicle requires a solid support surface to prevent the moped from tipping over or the stand from sinking into the ground.', 0, '1', 'The surface under the main stand must be solid', 'The surface under the main stand must not be solid', NULL, NULL, 30, '{0}'::int[], NULL, 'Hi there! Remember, parking your moped on soft ground is risky because the stand can sink in, causing the moped to fall over. Always look for a solid surface to keep your ride stable and safe!', NULL),
(1800, 'ka', 'როდის წარმოიქმნება მოპედის გვერდით გადაადგილების (გადაწევის) საფრთხე მაღალი სიჩქარით მოძრაობისას?', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის თანახმად, მოპედი არის მაღალი რისკის სატრანსპორტო საშუალება. გვერდითი გადაადგილების საფრთხე (სტაბილურობის დაკარგვა) მაღალი სიჩქარისას გამოწვეულია აეროდინამიკური ზემოქმედებით (ავტომატარებლის გასწრება, ქარი) ან მექანიკური დისბალანსით (სამუხრუჭე სისტემის არათანაბარი მუშაობა). აღნიშნული ფაქტორები ცალ-ცალკე ან ერთობლივად ზრდის მოპედის კონტროლის დაკარგვის რისკს.', 0, '4', 'მხოლოდ ავტომატარებლის გადასწრებისას', 'მხოლოდ ძლიერი გვერდითა ქარის არსებობისას', 'მხოლოდ იმ შემთხვევაში თუ დამუხრუჭებისას წინა თვლის ორივე სამუხრუჭე დისკის მოქმედება განსხვავდება ერთმანეთისგან', 'ამ ბილეთში ჩამოთვლილი ნებისმიერი გარემოების არსებობისას', 30, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოპედი ძალიან მგრძნობიარეა გარე ფაქტორების მიმართ. მაღალი სიჩქარის დროს ჰაერის ნაკადი, გვერდითი ქარი ან თუნდაც მუხრუჭების არათანაბარი მოჭიდება აბალანსებს მოპედს და აგდებს მას გზის სავალი ნაწილიდან. ამიტომ, სწორი პასუხია 4, რადგან ყველა ჩამოთვლილი შემთხვევა საშიშია!', NULL),
(1800, 'ru', 'Когда возникает опасность бокового смещения (заноса) мопеда при движении на высокой скорости?', 'Согласно Закону Грузии «О дорожном движении», мопед является транспортным средством повышенного риска. Опасность бокового смещения (потеря курсовой устойчивости) на высокой скорости вызывается аэродинамическим воздействием (обгон автопоезда, сильный ветер) или механическим дисбалансом (неравномерная работа тормозной системы). Каждый из этих факторов или их совокупность повышает риск потери управления мопедом.', 0, '4', 'Только при обгоне автопоезда', 'Только при сильном боковом ветре', 'Только в случае, если при торможении действие обоих тормозных дисков переднего колеса отличается друг от друга', 'При наличии любого из перечисленных в этом билете обстоятельств', 30, '{0}'::int[], NULL, 'Привет! Помни, что мопед очень чувствителен к внешним факторам. На высокой скорости воздушные потоки от грузовиков, сильный боковой ветер или даже неравномерное срабатывание тормозов могут привести к потере равновесия и заносу. Поэтому правильный ответ — 4, так как все перечисленные ситуации критически опасны!', NULL),
(1800, 'en', 'When does the risk of lateral displacement (swerving) of a moped occur when driving at high speed?', 'According to the Law of Georgia on Road Traffic, a moped is a high-risk vehicle. The risk of lateral displacement (loss of directional stability) at high speeds is caused by aerodynamic forces (overtaking a road train, crosswinds) or mechanical imbalance (uneven braking system performance). Each of these factors, or a combination thereof, increases the risk of losing control of the moped.', 0, '4', 'Only when overtaking a road train', 'Only in the presence of strong crosswinds', 'Only in the event that the action of both front wheel brake discs differs from each other during braking', 'In the presence of any of the circumstances listed in this ticket', 30, '{0}'::int[], NULL, 'Hello! Remember that a moped is very sensitive to external factors. At high speeds, air turbulence from large vehicles, crosswinds, or even uneven braking can cause the moped to lose balance and swerve. Therefore, the correct answer is 4, as all listed situations pose a significant safety risk!', NULL),
(1801, 'ka', 'მოპედის მძღოლის მიერ მკვეთრი ფერების ტანსაცმლით სარგებლობის შემთხვევაში:', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის თანახმად, უსაფრთხოების ზომების გაძლიერება გულისხმობს ხილვადობის გაუმჯობესებას. მკვეთრი ფერების სამოსი ზრდის მძღოლის პასიურ უსაფრთხოებას, რადგან ის უკეთესად აღქმადია სხვა მძღოლების მიერ, რაც ამცირებს ავტოსაგზაო შემთხვევის რისკს.', 0, '1', 'იგი უკეთესად შესამჩნევი ხდება საგზაო მოძრაობის სხვა მონაწილეებისათვის', 'ეკრძალება დღე–ღამის ბნელ დროს გადაადგილება', 'იგი არ არის ვალდებული გადაადგილებისას გამოიყენოს მოტოჩაფხუტი', NULL, 30, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, მოპედი გზაზე პატარა ზომისაა, ამიტომ შენი მთავარი მიზანია იყო მაქსიმალურად შესამჩნევი. კაშკაშა ტანსაცმელი სხვა მძღოლებს გზის სავალ ნაწილზე ადვილად დაგვანახებს, რაც პირდაპირ იცავს შენს სიცოცხლეს!', NULL),
(1801, 'ru', 'В случае использования водителем мопеда одежды ярких цветов:', 'Согласно Закону Грузии «О дорожном движении», усиление мер безопасности предполагает улучшение видимости. Яркая одежда повышает пассивную безопасность водителя, так как он становится более заметным для других участников движения, что снижает риск возникновения ДТП.', 0, '1', 'Он становится более заметным для других участников дорожного движения', 'Ему запрещено передвигаться в темное время суток', 'Он не обязан использовать мотошлем во время движения', NULL, 30, '{0}'::int[], NULL, 'Привет! Помни, мопед на дороге очень компактный, поэтому твоя главная цель — быть максимально заметным. Яркая одежда помогает другим водителям легко увидеть тебя на проезжей части, что напрямую защищает твою жизнь!', NULL),
(1801, 'en', 'In case a moped driver uses brightly colored clothing:', 'According to the Law of Georgia ''On Road Traffic'', enhancing safety measures involves improving visibility. Brightly colored clothing increases the driver''s passive safety, as they become more perceptible to other road users, thereby reducing the risk of a traffic accident.', 0, '1', 'He becomes more visible to other road users', 'He is prohibited from moving during dark hours', 'He is not required to use a motorcycle helmet while driving', NULL, 30, '{0}'::int[], NULL, 'Hello! Remember, a moped is small on the road, so your main goal is to be as visible as possible. Bright clothing helps other drivers easily spot you on the road, which directly helps protect your life!', NULL),
(1802, 'ka', 'გზაზე მყოფ ძაღლის სიახლოვეს გამავალმა მოპედის მძღოლმა ,უნდა', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის თანახმად, მძღოლი ვალდებულია მართოს სატრანსპორტო საშუალება გონივრული სიფრთხილით. ცხოველთა ქცევა არაპროგნოზირებადია და მათი რეაქცია მოძრავ მოპედზე შესაძლოა იყოს აგრესიული, რაც ქმნის საგზაო-სატრანსპორტო შემთხვევის რისკს.', 0, '2', 'გაითვალისწინოს ,რომ ყველა ძაღლს ეშინია მოძრავი სატრანსპორტო საშუალების,რის გამოც იგი აგრესიას არ გამოამჟღავნებს', 'გამოიჩინოს განსაკუთრებული სიფრთხილე,რადგან ძაღლმა შესაძლოა გამოამჟღავნოს აგრესია და გამოიწიოს მისი მიმართულებით', NULL, NULL, 30, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ცხოველებთან სიფრთხილე უსაფრთხოების გარანტიაა. ძაღლი შეიძლება შეშინდეს ან გაღიზიანდეს მოპედის ხმაურისგან, ამიტომ ყოველთვის მოემზადე მოულოდნელი მანევრისთვის და შეანელე სვლა.', NULL),
(1802, 'ru', 'Что должен сделать водитель мопеда, проезжающий рядом с собакой на дороге?', 'Согласно Закону Грузии «О дорожном движении», водитель обязан управлять транспортным средством с разумной осторожностью. Поведение животных непредсказуемо, и их реакция на движущийся мопед может быть агрессивной, что создает риск дорожно-транспортного происшествия.', 0, '2', 'Учесть, что все собаки боятся движущихся транспортных средств, поэтому они не проявляют агрессии.', 'Проявить особую осторожность, так как собака может проявить агрессию и броситься в его сторону.', NULL, NULL, 30, '{0}'::int[], NULL, 'Привет! Помни, что осторожность при встрече с животными — залог безопасности. Собака может испугаться или разозлиться из-за шума мопеда, поэтому всегда будь готов к неожиданным маневрам и сбавь скорость.', NULL),
(1802, 'en', 'What should a moped driver do when passing close to a dog on the road?', 'According to the Georgian ''Law on Road Traffic'', the driver is obliged to operate the vehicle with reasonable caution. Animal behavior is unpredictable, and their reaction to a moving moped may be aggressive, which creates a risk of a traffic accident.', 0, '2', 'Consider that all dogs are afraid of moving vehicles, so they will not show aggression.', 'Exercise extreme caution, as the dog may show aggression and dart toward the vehicle.', NULL, NULL, 30, '{0}'::int[], NULL, 'Hello! Remember, being cautious around animals is key to your safety. A dog might get startled or agitated by the noise of a moped, so always be ready for an unexpected move and slow down.', NULL),
(1803, 'ka', 'ასფალტის საფარის მქონე გზიდან ღორღიან გზაზე გადასვლისას მოპედის მძღოლმა უნდა', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის თანახმად, მძღოლი ვალდებულია აირჩიოს სიჩქარე, რომელიც შეესაბამება გზის პირობებს. გზის საფარის შეცვლა ზრდის მოცურების რისკს, ამიტომ სიჩქარის შემცირება და მკვეთრი მანევრებისგან თავის არიდება აუცილებელია ავტომობილის (მოპედის) სტაბილურობის შესანარჩუნებლად.', 0, '3', 'შეწყვიტოს მოძრაობა,რადგან ღორღიან გზაზე აკრძალულია მოპედით მოძრაობა', 'გაზარდოს მოძრაობის სიჩქარე,რათა ნაკლებად საგრძნობი გახდეს გზის საფარის გავლენა საჭეზე', 'შეარჩიოს შესაბამისი მოძრაობის სიჩქარე და მოერიდოს მკვეთრ მოძრაობებს', NULL, 27, '{0}'::int[], NULL, 'გამარჯობა! გზის საფარის შეცვლა, განსაკუთრებით ასფალტიდან ღორღზე გადასვლა, ცვლის საბურავების მოჭიდებას გზასთან. მკვეთრი დამუხრუჭება ან მოხვევა ამ დროს ადვილად გამოიწვევს მოცურებას. ამიტომ, ყოველთვის შეანელე სვლა და იმოძრავე ფრთხილად!', NULL),
(1803, 'ru', 'Что должен сделать водитель мопеда при переходе с асфальтового покрытия на гравийную дорогу?', 'Согласно Закону Грузии «О дорожном движении», водитель обязан выбирать скорость, соответствующую дорожным условиям. Изменение типа покрытия дороги увеличивает риск заноса, поэтому снижение скорости и отказ от резких маневров необходимы для поддержания стабильности транспортного средства.', 0, '3', 'Прекратить движение, так как движение мопедов по гравийным дорогам запрещено', 'Увеличить скорость движения, чтобы влияние дорожного покрытия на руль стало менее заметным', 'Выбрать соответствующую скорость движения и избегать резких маневров', NULL, 27, '{0}'::int[], NULL, 'Привет! Смена дорожного покрытия, особенно переход с асфальта на гравий, меняет сцепление колес с дорогой. Резкое торможение или поворот в этот момент легко приведут к заносу. Поэтому всегда сбавляй скорость и двигайся плавно!', NULL),
(1803, 'en', 'What should a moped driver do when moving from an asphalt surface to a gravel road?', 'According to the Georgian Law on Road Traffic, a driver is obliged to choose a speed that corresponds to road conditions. A change in road surface increases the risk of skidding, therefore reducing speed and avoiding sudden maneuvers is essential to maintain the stability of the vehicle.', 0, '3', 'Stop movement, as driving mopeds on gravel roads is prohibited', 'Increase speed so that the impact of the road surface on the steering becomes less noticeable', 'Select an appropriate speed and avoid sudden movements', NULL, 27, '{0}'::int[], NULL, 'Hello! Changing road surfaces, especially moving from asphalt to gravel, alters tire traction. Sudden braking or steering at this moment will easily cause a skid. Therefore, always slow down and drive smoothly!', NULL),
(1804, 'ka', 'მოპედის საბურავებში დაბალმა ჰაერის წნევამ შეიძლება გამოიწვიოს:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის შესაბამისად, მძღოლი ვალდებულია მართოს ტექნიკურად გამართული სატრანსპორტო საშუალება. საბურავებში არასწორი წნევა პირდაპირ მოქმედებს როგორც საბურავის ცვეთაზე, ასევე მოძრაობის უსაფრთხოებაზე, კერძოდ, მართვადობაზე, რაც საფრთხეს უქმნის მოძრაობის სხვა მონაწილეებს.', 0, '3', 'მხოლოდ პროტექტორის კიდეების არათანაბარი ცვეთა', 'მხოლოდ მოპედის მართვადობის გაუარესება', 'ამ ბილეთში ჩამოთვლილი ნებისმიერი გარემოება', NULL, 27, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ ჰაერის დაბალი წნევა საბურავებს „ღუნავს“, რის გამოც კიდეები სწრაფად ცვდება, მართვა კი რთულდება და არასტაბილური ხდება. ამიტომ, სწორი პასუხია 3 – ორივე პრობლემა რეალური საფრთხეა!', NULL),
(1804, 'ru', 'Низкое давление в шинах мопеда может привести к:', 'В соответствии с Законом Грузии «О дорожном движении», водитель обязан управлять технически исправным транспортным средством. Неправильное давление в шинах напрямую влияет как на износ протектора, так и на безопасность движения, в частности, на управляемость, что создает угрозу для других участников дорожного движения.', 0, '3', 'Только неравномерному износу краев протектора', 'Только ухудшению управляемости мопеда', 'Любому из перечисленных в этом билете обстоятельств', NULL, 27, '{0}'::int[], NULL, 'Привет! Помни, что низкое давление заставляет шины «проминаться», из-за чего края быстро изнашиваются, а управление становится тяжелым и нестабильным. Поэтому правильный ответ 3 – обе эти проблемы являются реальной угрозой!', NULL),
(1804, 'en', 'Low tire pressure in a moped can cause:', 'In accordance with the Law of Georgia ''On Road Traffic'', a driver is obliged to operate a technically sound vehicle. Incorrect tire pressure directly affects both tire wear and traffic safety, specifically handling, which poses a threat to other road users.', 0, '3', 'Only uneven wear of the tread edges', 'Only deterioration of the moped''s handling', 'Any of the circumstances listed in this ticket', NULL, 27, '{0}'::int[], NULL, 'Hello! Remember that low air pressure causes tires to ''flex'' excessively, leading to rapid edge wear and making handling difficult and unstable. Therefore, the correct answer is 3 – both of these issues are real hazards!', NULL),
(1805, 'ka', 'აკრძალულია მოპედით იმ ტვირთის გადაზიდვა,რომელიც გადმოშვერილია გიგანეზე ან სიგრძეზე გაბარიტებს გარეთ', 'საქართველოს „საგზაო მოძრაობის შესახებ“ კანონის მიხედვით, მოპედით ტვირთის გადაზიდვა აკრძალულია, თუ ის სატრანსპორტო საშუალების გაბარიტებს სიგრძეში ან სიგანეში 0.5 მეტრზე მეტად სცილდება.', 0, '1', '0.5 მეტრზე მეტად', 'არანაკლებ 0.7 მეტრით', 'არანაკლებ 1 მეტრით', NULL, 26, '{0}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, მოპედი პატარა და მანევრირებადი ტრანსპორტია. ზედმეტად გამოშვერილი ტვირთი ბალანსს დაგირღვევს და საფრთხეს შეუქმნის სხვა მძღოლებს. ამიტომ, კანონი მკაცრად ზღუდავს ტვირთის გაბარიტებს — 0.5 მეტრი არის მაქსიმალური დასაშვები ზღვარი.', NULL),
(1805, 'ru', 'Запрещено ли перевозить на мопеде груз, который выступает за габариты по ширине или длине более чем на:', 'Согласно Закону Грузии «О дорожном движении», запрещается перевозить груз на мопеде, если он выступает за габариты транспортного средства по длине или ширине более чем на 0,5 метра.', 0, '1', '0.5 метра', 'Не менее 0.7 метра', 'Не менее 1 метра', NULL, 26, '{0}'::int[], NULL, 'Привет! Запомни: мопед — это маленькое и маневренное транспортное средство. Выступающий груз легко нарушит твое равновесие и создаст опасность для окружающих. Поэтому закон строго ограничивает габариты груза — 0,5 метра является максимально допустимым пределом.', NULL),
(1805, 'en', 'Is it prohibited to carry cargo on a moped that protrudes beyond the dimensions in width or length by more than:', 'According to the Law of Georgia ''On Road Traffic'', it is prohibited to transport cargo on a moped if it protrudes beyond the dimensions of the vehicle in length or width by more than 0.5 meters.', 0, '1', '0.5 meters', 'At least 0.7 meters', 'At least 1 meter', NULL, 26, '{0}'::int[], NULL, 'Hello! Remember, a moped is a small and agile vehicle. Cargo sticking out too far will ruin your balance and endanger others. That is why the law strictly limits cargo dimensions — 0.5 meters is the maximum allowed limit.', NULL),
(1806, 'ka', 'სავალდებულოა თუ არა მოპედის მძღოლებისათვის,ასევე მათი მგზავრებისათვის სპეციალური ჩაფხუტის გამოყენება?', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის შესაბამისად, მოპედის მძღოლს და მის მგზავრს ეკისრებათ ვალდებულება, მოძრაობისას გამოიყენონ დამცავი ჩაფხუტი, რაც უზრუნველყოფს მათი უსაფრთხოების დაცვას.', 0, '1', 'სავალდებულოა', 'არ არის სავალდებულო', NULL, NULL, 27, '{0}'::int[], NULL, 'გამარჯობა! მოკლედ რომ ვთქვათ: მოპედით გადაადგილებისას შენი და შენი მგზავრის უსაფრთხოება ყველაზე მნიშვნელოვანია. კანონი ავალდებულებს როგორც მძღოლს, ისე მგზავრს, ატარონ ჩაფხუტი, რათა თავიდან ავიცილოთ სერიოზული დაზიანებები. ეს წესი ყველასთვის ერთნაირია!', NULL),
(1806, 'ru', 'Обязательно ли использование защитного шлема для водителей мопедов, а также их пассажиров?', 'В соответствии с Законом Грузии «О дорожном движении», водитель мопеда и его пассажир обязаны использовать защитный шлем во время движения, что обеспечивает их безопасность.', 0, '1', 'Обязательно', 'Не обязательно', NULL, NULL, 27, '{0}'::int[], NULL, 'Привет! Короче говоря: при езде на мопеде твоя безопасность и безопасность пассажира — превыше всего. Закон обязывает как водителя, так и пассажира надевать шлем, чтобы предотвратить серьезные травмы. Это правило касается всех!', NULL),
(1806, 'en', 'Is it mandatory for moped drivers and their passengers to use a safety helmet?', 'In accordance with the Law of Georgia ''On Road Traffic'', the driver of a moped and their passenger are obligated to use a safety helmet while driving to ensure their safety.', 0, '1', 'Mandatory', 'Not mandatory', NULL, NULL, 27, '{0}'::int[], NULL, 'Hello! In short: when riding a moped, your safety and your passenger''s safety are the most important things. The law requires both the driver and the passenger to wear a helmet to prevent serious injuries. This rule applies to everyone!', NULL),
(1807, 'ka', 'ქვემოთ ჩამოთვლილ გზის რომელ ელემენტებზეა დასაშვები მოპედით მძრაობა', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის შესაბამისად, მოპედი მიეკუთვნება მექანიკურ სატრანსპორტო საშუალებას, შესაბამისად, მისი ადგილი გზის სავალ ნაწილზეა. ველობილიკი და ტროტუარი განკუთვნილია შესაბამისად ველოსიპედისტებისა და ქვეითებისთვის, სადაც მოპედით მოძრაობა აკრძალულია.', 0, '1', 'გზის სავალ ნაწილზე', 'ველოსიპედის ბილიკზე(ველობილიკზე) და ველოსიპედის მოძრაობის ზოლზე', 'ტროტუარზე', NULL, 27, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ მოპედი მოტოციკლის მსგავსად მექანიკური სატრანსპორტო საშუალებაა. ამიტომ, შენი ადგილი მანქანების გვერდით, სავალ ნაწილზეა. ტროტუარი ფეხით მოსიარულეებისთვისაა, ხოლო ველობილიკი — ველოსიპედისტებისთვის. მოპედით მათზე შესვლა საფრთხეს უქმნის სხვებს!', NULL),
(1807, 'ru', 'По каким из перечисленных элементов дороги разрешено движение на мопеде?', 'В соответствии с Законом Грузии «О дорожном движении», мопед классифицируется как механическое транспортное средство, поэтому он должен передвигаться по проезжей части дороги. Велосипедные дорожки и тротуары предназначены исключительно для велосипедистов и пешеходов соответственно, движение мопедов по ним запрещено.', 0, '1', 'По проезжей части дороги', 'По велосипедной дорожке и полосе для движения велосипедов', 'По тротуару', NULL, 27, '{0}'::int[], NULL, 'Привет! Запомни, что мопед — это, по сути, легкий мотоцикл, а значит, полноценное транспортное средство. Твое место — на проезжей части вместе с остальными машинами. Тротуары созданы для пешеходов, а велодорожки — для велосипедистов, поэтому выезжать туда на мопеде нельзя — это опасно для окружающих!', NULL),
(1807, 'en', 'On which of the following road elements is it permitted to drive a moped?', 'In accordance with the Law of Georgia ''on Road Traffic'', a moped is classified as a motor vehicle; therefore, its place is on the carriageway of the road. Bicycle paths and sidewalks are intended for cyclists and pedestrians respectively, and driving a moped on them is prohibited.', 0, '1', 'On the carriageway of the road', 'On a bicycle path and a bicycle lane', 'On the sidewalk', NULL, 27, '{0}'::int[], NULL, 'Hello! Remember that a moped is a motor vehicle, similar to a motorcycle. Therefore, your place is on the road along with other vehicles. Sidewalks are for pedestrians, and bike paths are for cyclists. Riding your moped on them would put others at risk!', NULL),
(1808, 'ka', 'მოპედის კონსტრუქციული სიჩქარე :', 'საქართველოს კანონის „საგზაო მოძრაობის შესახებ“ შესაბამისად, მოპედი არის ორბორბლიანი ან სამბორბლიანი სატრანსპორტო საშუალება, რომლის კონსტრუქციული სიჩქარე აღემატება 25 კმ/სთ-ს, მაგრამ არ აღემატება 45 კმ/სთ-ს.', 0, '2', 'აღემატება 45 კმ/სთ–ს,მაგრამ არ აღემატება 55 კმ/სთ–ს', 'აღემატება 25 კმ/სთ–ს,მაგრამ არ აღემატება 45 კმ/სთ–ს', 'აღემატება 50 კმ/სთ–ს,მაგრამ არ აღემატება 75 კმ/სთ–ს', NULL, 17, '{0}'::int[], NULL, 'გამარჯობა! დაიმახსოვრე, რომ კანონით მოპედი არის სწორედ ის ტრანსპორტი, რომელიც 25-დან 45 კმ/სთ სიჩქარით მოძრაობს. თუ სიჩქარე 25-ზე ნაკლებია, ეს უკვე ველოსიპედია, ხოლო თუ 45-ზე მეტია — მოტოციკლი.', NULL),
(1808, 'ru', 'Конструктивная скорость мопеда:', 'Согласно Закону Грузии «О дорожном движении», мопед представляет собой двухколесное или трехколесное транспортное средство, конструктивная скорость которого превышает 25 км/ч, но не превышает 45 км/ч.', 0, '2', 'Превышает 45 км/ч, но не превышает 55 км/ч', 'Превышает 25 км/ч, но не превышает 45 км/ч', 'Превышает 50 км/ч, но не превышает 75 км/ч', NULL, 17, '{0}'::int[], NULL, 'Привет! Запомни: по закону мопед — это транспорт, развивающий скорость от 25 до 45 км/ч. Если скорость меньше 25 км/ч — это велосипед, а если больше 45 км/ч — это уже мотоцикл.', NULL),
(1808, 'en', 'The design speed of a moped is:', 'According to the Law of Georgia ''on Road Traffic'', a moped is a two-wheeled or three-wheeled vehicle whose design speed exceeds 25 km/h but does not exceed 45 km/h.', 0, '2', 'Exceeds 45 km/h but does not exceed 55 km/h', 'Exceeds 25 km/h but does not exceed 45 km/h', 'Exceeds 50 km/h but does not exceed 75 km/h', NULL, 17, '{0}'::int[], NULL, 'Hello! Remember, under the law, a moped is specifically a vehicle with a design speed between 25 and 45 km/h. Anything slower than 25 km/h is a bicycle, and anything faster than 45 km/h is classified as a motorcycle.', NULL),
(1809, 'ka', 'ჩამოთვლილთაგან რომელ ადგილებშია აკრძალული მოპედის გაჩერება', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის შესაბამისად, მოპედი ითვლება სატრანსპორტო საშუალებად. გაჩერების წესები, რომლებიც ვრცელდება ავტომობილებზე, მოქმედებს მოპედებზეც. კანონის თანახმად, გაჩერება აკრძალულია გზაჯვარედინებზე, ქვეითთა გადასასვლელებზე და მათ წინ 5 მეტრის რადიუსში, ასევე გვირაბებში, ხიდებზე, ესტაკადებსა და გზაგამტარებზე, გარდა იმ შემთხვევებისა, როდესაც მოწყობილია სპეციალური სადგომი.', 0, '4', 'მხოლოდ სავალი ნაწილების გადაკვეთაზე', 'მხოლოდ ქვეითთა გადასასვლელებზე ან მის წინ 5 მეტრზე ახლოს', 'მხოლოდ ეტაკადის,ხიდისა და გზაგამტარის ქვეშ,აგრეთვე გვირაბში,თუ ამისთვის სპეციალური ადგილი არ არის გამოყოფილი', 'ამ ბილეთში ჩამოთვლილ ყველა ადგილზე', 19, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ გზაზე შენი მოპედი იგივე მონაწილეა, რაც ავტომობილი. უსაფრთხოების მიზნით, კანონი კრძალავს გაჩერებას ისეთ ადგილებში, სადაც შეიძლება ხელი შეუშალო სხვა მძღოლებს ან საფრთხე შეუქმნა ქვეითებს (მაგალითად, გადასასვლელებზე ან გვირაბებში). ამიტომ, სწორი პასუხია ყველა ზემოთ ჩამოთვლილი ადგილი!', NULL),
(1809, 'ru', 'В каких из перечисленных мест запрещена остановка мопеда?', 'Согласно Закону Грузии «О дорожном движении», мопед является транспортным средством. Правила остановки, применимые к автомобилям, распространяются и на мопеды. Законом запрещена остановка на перекрестках, на пешеходных переходах и ближе 5 метров перед ними, а также в туннелях, под эстакадами, мостами и путепроводами, за исключением специально отведенных для этого мест.', 0, '4', 'Только на пересечении проезжих частей', 'Только на пешеходных переходах или ближе 5 метров перед ними', 'Только под эстакадой, мостом и путепроводом, а также в туннеле, если для этого не отведено специальное место', 'Во всех перечисленных в этом билете местах', 19, '{0}'::int[], NULL, 'Привет! Помни, что на дороге твой мопед — такой же полноправный участник движения, как и автомобиль. Ради безопасности закон запрещает остановку там, где ты можешь создать помехи другим водителям или подвергнуть риску пешеходов (например, на переходах или в туннелях). Поэтому правильный ответ — все вышеперечисленные места!', NULL),
(1809, 'en', 'In which of the following places is it forbidden to stop a moped?', 'According to the Law of Georgia ''on Road Traffic'', a moped is considered a vehicle. The stopping rules applicable to cars also apply to mopeds. Under the law, stopping is prohibited at intersections, on pedestrian crossings and within 5 meters before them, as well as in tunnels, under overpasses, bridges, and flyovers, unless a special parking area has been designated for this purpose.', 0, '4', 'Only at intersections of roadways', 'Only at pedestrian crossings or within 5 meters before them', 'Only under an overpass, bridge, or flyover, as well as in a tunnel, unless a special place is allocated for it', 'In all the places listed in this ticket', 19, '{0}'::int[], NULL, 'Hello! Remember that on the road, your moped is a participant just like any car. For safety reasons, the law prohibits stopping in places where you could obstruct other drivers or endanger pedestrians (such as crossings or tunnels). Therefore, the correct answer includes all the locations listed above!', NULL),
(1810, 'ka', '''''AM'''' კატეგორიის სატრანსპორტო საშუალების მართვის უფლებისთვის მართვის მოწმობის მოქმედების მაქსიმალური ვადაა:', '„საგზაო მოძრაობის შესახებ“ საქართველოს კანონის შესაბამისად, მართვის მოწმობის მოქმედების ვადა განისაზღვრება 15 წლით, გარდა კანონით გათვალისწინებული გამონაკლისებისა.', 0, '3', '5 წელი', '10 წელი', '15 წელი', NULL, 27, '{0}'::int[], NULL, 'გამარჯობა! გახსოვდეს, რომ AM კატეგორიისთვის (მოპედები) მოწმობის სტანდარტული მოქმედების ვადა 15 წელია. ეს წესი უზრუნველყოფს, რომ შენი მონაცემები პერიოდულად განახლდეს.', NULL),
(1810, 'ru', 'Каков максимальный срок действия водительского удостоверения для управления транспортным средством категории «AM»?', 'В соответствии с Законом Грузии «О дорожном движении», срок действия водительского удостоверения составляет 15 лет, за исключением случаев, предусмотренных законом.', 0, '3', '5 лет', '10 лет', '15 лет', NULL, 27, '{0}'::int[], NULL, 'Привет! Запомни, что для категории «AM» (мопеды) стандартный срок действия прав составляет 15 лет. Это правило помогает своевременно обновлять данные водителя.', NULL),
(1810, 'en', 'What is the maximum validity period of a driving license for driving a category ''AM'' vehicle?', 'In accordance with the Law of Georgia ''on Road Traffic'', the validity period of a driving license is 15 years, except for cases provided by law.', 0, '3', '5 years', '10 years', '15 years', NULL, 27, '{0}'::int[], NULL, 'Hello! Just remember that for category ''AM'' (mopeds), the standard validity period of the license is 15 years. This rule helps ensure your driver information stays up to date.', NULL)
ON CONFLICT (id, lang) DO NOTHING;

